#include "pir/lower.h"

#include <algorithm>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <limits>
#include <set>
#include <typeinfo>
#include <unordered_map>
#include <unordered_set>

// For `isIntName` -- the one place that already answers "is this the name of an integer type", so
// this pass asks it rather than keeping a second list that can disagree with it.
#include "semantic/semutil.h"

// For `collectRefs` -- the free-variable walk a lambda's automatic capture needs. It touches no
// LLVM and belongs to neither backend; writing a second walk over every expression kind is how the
// two ends of a closure come to disagree about what it carries.
#include "codegen/cgutil.h"

// For `readArrangement` -- what a `layout` asks of the type implementing it, including the byte
// ceiling. The reading of an `onArrange` block belongs where the layout is declared and validated;
// this pass is only the one that knows the SIZE to hold it against.
#include "semantic/layouts.h"

// For the compile-time evaluator. What counts as a constant is a property of the LANGUAGE, decided
// in one place that both the analyzer and the trusted backend already drive; a second copy written
// here would answer differently the first time either was changed.
#include "semantic/comptime.h"
#include "semantic/sys_intrinsics.h"

namespace polaron::pir {

namespace {

// §34: a `Decimal` is a 128-bit mantissa holding the value times 10^18. The width and the scale are
// stated once, here and in `cgutil::DECIMAL_SCALE`, because every part of the type reads both: the
// literal scales by it, `*` and `/` rescale through it, a cast multiplies or divides by it, and the
// formatter splits on it.
constexpr unsigned kDecimalBits = 128;

// The intermediate `*` and `/` go through. A product of two mantissas is up to 2^254, so the scale
// has to come back out at a width the multiply cannot have overflowed.
constexpr unsigned kDecimalWideBits = 256;

// The lowering. One class, walking declarations then bodies, because a call can name a method
// declared later in the file and the function has to exist before its key is used.
class Lower {
public:
    Lower(const ast::Program& program, std::function<std::string(std::string_view, int)> sourceLine,
          std::string triple, BundleContext bundles)
        : ast_(program),
          sourceLine_(std::move(sourceLine)),
          triple_(std::move(triple)),
          bundles_(std::move(bundles)) {
        // THE IMPORTED BUNDLES' NUMBERING IS ADOPTED BEFORE ANY SLOT IS HANDED OUT. `slotFor`
        // numbers a method the first time it is asked about, so the only place this can happen is
        // before the walk starts -- afterwards the consumer has already given slot 0 to whichever
        // of its own methods it met first, and every dispatch into the library is off by however
        // many that was.
        for (const std::string& name : bundles_.vtableSlots) {
            if (!name.empty()) {
                slotFor(name);
            }
        }
    }

    Lowering run() {
        // THE TARGET AS THE DRIVER RESOLVED IT, not a guess from the program's own word. A
        // `freestanding` PROGRAM built for a hosted machine is still hosted -- the suite links
        // several of them against a real CRT to run them -- and writing "none" here made the
        // backend drop their entry point. Empty only when nobody said, which the backend reads as
        // the host.
        out_.module.triple =
            !triple_.empty() ? triple_
            : ast_.isFreestanding ? std::string("x86_64-unknown-none-elf")
                                  : std::string();
        // ...and the program's OWN word beside it, because the entry needs both answers. See
        // `Module::freestanding`.
        out_.module.freestanding = ast_.isFreestanding;
        indexClasses();    // before any name is resolved -- see `indexClasses`
        foldConstants();   // before anything reads a `static fixed` -- see below
        collectUnimportable();   // before any constructor or call site is emitted -- see below
        collectWeakTargets();    // before any class is laid out -- it adds a field to some of them
        collectReplaceable();    // before any vtable is built -- it decides which methods get slots
        collectPolymorphic();    // ...and after it, because a replaceable method needs a table
        indexEnums();            // before any SIGNATURE is built -- see `indexEnums`
        for (const ast::Bundle& b : ast_.bundles) {
            // THE PRELUDE IS COMPILED IN, not merely declared. Skipping it looked right -- it is
            // "the library", not the program -- and the differential oracle said otherwise: the
            // trusted path DEFINES `Object.Object`, `Exception.Exception` and the rest, because a
            // Polaron program carries its prelude. Only an IMPORTED bundle is genuinely elsewhere:
            // its bodies live in a `.polb`, and declaring them is the honest answer there.
            if (b.isImported) {
                declareOnly(b);
                continue;
            }
            if (!b.isPrelude) {
                out_.module.bundle = b.name;
            }
            for (const ast::Namespace& ns : b.namespaces) {
                declareNamespace(ns, b);
            }
        }
        // THE TABLES ARE BUILT AFTER EVERY CLASS IS DECLARED, because a table has to name the most
        // derived implementation of each slot and a subclass can be declared before its base.
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                currentBundle_ = b.name;
                currentNamespace_ = ns.name;
                for (const ast::ClassDecl& c : ns.classes) {
                    buildVtable(c);
                }
            }
        }
        padVtables();
        for (const ast::Bundle& b : ast_.bundles) {
            if (b.isImported) {
                continue;
            }
            for (const ast::Namespace& ns : b.namespaces) {
                currentBundle_ = b.name;
                currentNamespace_ = ns.name;
                for (const ast::ClassDecl& c : ns.classes) {
                    lowerSynthesizedConstructor(c);
                    lowerSynthesizedDestructor(c);
                    lowerClassBodies(c);
                }
                for (const ast::EnumDecl& e : ns.enums) {
                    lowerEnumBodies(e);
                }
            }
        }
        settleUnwinding();
        // ...AND AGAIN, NOW THAT THE NUMBERING IS FINAL. See `padVtables`.
        padVtables();
        emitHeapBridge();   // `heap class X` (§36) -- after every body, so its methods exist
        // ...AND THE `--use-dynamic` THUNKS, after `emitHeapBridge` because a thunk that has to
        // raise an exception allocates it, and on a freestanding target that allocation goes
        // through the bridge just installed.
        emitDynamicThunks();
        // A TARGET WITH NO C RUNTIME IS ENTERED DIRECTLY, NOT THROUGH `main`. There is no libc to
        // call it and no argc/argv to build, so the program's entry takes the symbol the boot code
        // names -- `kmain` -- and keeps external linkage, or dead-stripping deletes the one function
        // the whole image exists to reach. This is the counterpart of the hosted shim the backend
        // does NOT emit here (see `emitEntry`): between them, exactly one entry exists per target.
        if (!targetHasCRuntime()) {
            for (const std::unique_ptr<Function>& f : out_.module.functions) {
                if (f->key.size() > 5 && f->key.compare(f->key.size() - 5, 5, ".main") == 0 &&
                    !f->blocks.empty()) {
                    f->symbol = "kmain";
                    f->linkage = Linkage::External;
                    break;
                }
            }
        }
        // THE SLOT NUMBERING, AS AN ORDER. `vtableSlot_` maps a method name to its index; what a
        // `.polb` carries and a consumer seeds itself with is the list, where POSITION is the slot
        // and a gap is a number nothing uses. Built here rather than kept as a list all along
        // because the map is what every lookup wants and the order is wanted once.
        out_.vtableSlots.assign(vtableSlot_.size(), std::string());
        for (const auto& [method, at] : vtableSlot_) {
            if (at >= 0 && static_cast<size_t>(at) < out_.vtableSlots.size()) {
                out_.vtableSlots[static_cast<size_t>(at)] = method;
            }
        }
        markMergeable();
        return std::move(out_);
    }

    // WHICH BODIES A CONSUMER WILL COMPILE A SECOND COPY OF -- see `Function::mergeable`.
    //
    // In ONE sweep at the end, over the finished module, rather than at each of the twenty-odd
    // places a function is declared. The rule reads the KEY and one set, both of which are complete
    // only now, and a rule spread over twenty sites is a rule that drifts: the last one added forgets
    // it, and what that produces is a link error in a program nobody was working on.
    // Whether `name` is `<owner>.<member>` for an owner both sides of a bundle boundary compile.
    bool compiledOnBothSides(const std::string& name) const {
        const size_t lastDot = name.rfind('.');
        const std::string owner =
            lastDot == std::string::npos ? std::string() : name.substr(0, lastDot);
        // A MONOMORPHIZED INSTANCE, BY ITS `$`. `ArrayList$String` is not a class anyone wrote: it
        // is what this compilation made of a template, and the consumer will make the same thing of
        // the same template. The `$` is the only mark it carries, and it is reserved -- no
        // identifier the language accepts can contain one.
        //
        // ...AND THE PRELUDE, for the plainer reason that both sides carry it. `String.length` is
        // compiled into every Polaron artefact there is.
        //
        // `literal.` too: a literal suffix's owner is not a class, so `isPreludeClass` cannot answer
        // for it, and `64 kilobytes` is resolved by the same prelude code on both sides.
        return owner.find('$') != std::string::npos || isPreludeClass(owner) ||
               name.rfind("literal.", 0) == 0;
    }

    void markMergeable() {
        for (Global& g : out_.module.globals) {
            if ((g.linkage == Linkage::Public || g.linkage == Linkage::External) &&
                compiledOnBothSides(g.name)) {
                g.mergeable = true;
            }
        }
        for (const std::unique_ptr<Function>& f : out_.module.functions) {
            if (f->blocks.empty() || f->linkage != Linkage::Public) {
                continue;   // a declaration defines nothing to collide; a local publishes nothing
            }
            if (compiledOnBothSides(f->key)) {
                f->mergeable = true;
            }
        }
    }

    // EVERY COMPILE-TIME CONSTANT IN THE PROGRAM, folded before a single declaration is walked.
    //
    // `static fixed int DOUBLED = Cfg.MAX * 2;` is a value, not code: spec 28.1 says it is folded
    // and carries no runtime storage. Only bare LITERALS were being folded here, so a constant
    // defined in terms of another -- which is most of them -- became a zeroed global, and the
    // program printed `DOUBLED=0` with nothing to say it had gone wrong.
    //
    // Through `comptime::evalInt` rather than a second evaluator written here, because what counts
    // as a compile-time constant is a property of the LANGUAGE and it already lives in one place --
    // arithmetic, the magic-constant bases, references to siblings, calls to `comptime` methods,
    // and the step budget that stops a runaway recursion. A second copy would answer differently
    // the first time either was changed.
    //
    // TO A FIXED POINT, because a constant may be defined in terms of one declared later in the
    // file, and the order a walk happens to visit them in is not the order they depend on.
    void foldConstants() {
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    for (const ast::MemberPtr& m : c.members) {
                        const auto* method = dynamic_cast<const ast::MethodDecl*>(m.get());
                        if (method != nullptr && method->isComptime && !method->isAbstract) {
                            comptimeMethods_.emplace(method->name, method);
                        }
                    }
                }
            }
        }

        std::vector<std::pair<const ast::ConstDecl*, std::string>> waiting;
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ConstDecl& k : ns.consts) {
                    waiting.push_back({&k, std::string()});
                }
                for (const ast::ClassDecl& c : ns.classes) {
                    for (const ast::MemberPtr& m : c.members) {
                        if (const auto* k = dynamic_cast<const ast::ConstDecl*>(m.get())) {
                            waiting.push_back({k, c.name});
                        }
                        // A PLAIN `static` WITH A CONSTANT INITIALISER FOLDS TOO. Only `fixed`
                        // parses as a `ConstDecl`; `public static int HAMLET = Rules.VILLAGE / 4;`
                        // is a FIELD, and it was reaching the global as a zero -- so a program
                        // whose rules are written in terms of each other ran with all of them at
                        // nought. The evaluator is the same one; what was missing was the walk.
                        if (const auto* f = dynamic_cast<const ast::FieldDecl*>(m.get());
                            f != nullptr && f->isStatic && f->init != nullptr) {
                            staticFields_.push_back({f, c.name});
                        }
                    }
                }
            }
        }

        bool moved = true;
        while (moved && (!waiting.empty() || !staticFields_.empty())) {
            moved = false;
            std::vector<std::pair<const ast::ConstDecl*, std::string>> again;
            for (const auto& [k, owner] : waiting) {
                if (foldOneConstant(*k, owner)) {
                    moved = true;
                } else {
                    again.push_back({k, owner});
                }
            }
            waiting = std::move(again);
            // ...and the static FIELDS, in the same fixed point and against the same maps, because
            // one may be written in terms of the other in either order.
            std::vector<std::pair<const ast::FieldDecl*, std::string>> stillOpen;
            for (const auto& [f, owner] : staticFields_) {
                if (foldOneStatic(*f, owner)) {
                    moved = true;
                } else {
                    stillOpen.push_back({f, owner});
                }
            }
            staticFields_ = std::move(stillOpen);
        }
        // Whatever is still unfolded is not a constant, and the analyzer has already said so. This
        // pass stays quiet about it rather than reporting the same thing a second time.
    }

    // The same fold, for a plain `static` field. Written as its own entry point rather than by
    // making `foldOneConstant` take a name and an expression, because what differs is only where
    // the two facts come from and the two declarations do not share a base.
    bool foldOneStatic(const ast::FieldDecl& f, const std::string& owner) {
        ast::ConstDecl as;
        as.loc = f.loc;
        as.name = f.name;
        as.type = f.type;
        // BORROWED, NOT OWNED. `ConstDecl::init` is a `unique_ptr`; the expression belongs to the
        // field, so it is put back before this returns rather than freed with the temporary.
        as.init = ast::ExprPtr(const_cast<ast::Expr*>(f.init.get()));
        const bool folded = foldOneConstant(as, owner);
        (void)as.init.release();
        return folded;
    }

    // WHAT THE COMPILE-TIME EVALUATOR IS ALLOWED TO KNOW. One place, because two callers ask the
    // same question at different times: a namespace `const` (spec 28.1) and a `comptime` local
    // (spec 28.3). Only a stage that knows the layout may answer for `sizeof`, and this one does --
    // the type table has the size of everything it has interned.
    comptime::Context comptimeContext() {
        comptime::Context ctx;
        ctx.consts = &constInts_;
        ctx.dconsts = &constDoubles_;
        ctx.methods = &comptimeMethods_;
        ctx.sizeOfType = [this](const std::string& name, long long& out) {
            const Type* t = baseTypeOf(name);
            if (t == nullptr || t->facts.size == 0) {
                return false;
            }
            out = static_cast<long long>(t->facts.size);
            return true;
        };
        ctx.enumCount = [this](const std::string& name, long long& out) {
            auto e = enums_.find(name);
            if (e == enums_.end()) {
                return false;
            }
            out = static_cast<long long>(e->second->constants.size());
            return true;
        };
        return ctx;
    }

    bool foldOneConstant(const ast::ConstDecl& k, const std::string& owner) {
        const std::string key = owner.empty() ? k.name : owner + "." + k.name;
        if (k.init == nullptr || constInts_.count(key) != 0 || constDoubles_.count(key) != 0) {
            return true;
        }
        comptime::Context ctx = comptimeContext();
        const std::string spelled = ast::mangleGeneric(k.type.name, k.type.typeArgs);
        if (spelled == "float" || spelled == "double") {
            double d = 0;
            if (!comptime::evalDouble(*k.init, d, ctx)) {
                return false;
            }
            constDoubles_[key] = d;
            return true;
        }
        long long v = 0;
        if (!comptime::evalInt(*k.init, v, ctx)) {
            return false;
        }
        constInts_[key] = v;
        return true;
    }

    // WHICH FUNCTIONS CAN THROW, worked out from what they actually contain rather than from what
    // they declare. `unwind(never)` becomes `nounwind` in the backend, and `nounwind` on a function
    // that does throw is a promise LLVM is entitled to act on: it deletes the unwind edge at every
    // call to it, so the handler around the call becomes unreachable and the exception leaves the
    // program. A method with no `throws` clause that contains a `throw` is exactly that case, and
    // it is the common one -- `throws` is documentation in this language, not a contract.
    //
    // A fixpoint, because throwing is transitive: a method that calls a method that throws throws.
    void settleUnwinding() {
        bool changed = true;
        while (changed) {
            changed = false;
            for (const std::unique_ptr<Function>& f : out_.module.functions) {
                if (f->unwind == Unwind::May || f->blocks.empty()) {
                    continue;
                }
                bool throws = false;
                for (const Block& b : f->blocks) {
                    for (const Inst& in : b.insts) {
                        if (in.op == Op::Raise || in.op == Op::Resume ||
                            in.op == Op::CallUnwind || in.op == Op::CallIndirect) {
                            throws = true;
                        } else if (in.op == Op::Call) {
                            const Function* callee = out_.module.find(in.text);
                            throws = throws || (callee != nullptr && callee->unwind == Unwind::May);
                        }
                        if (throws) {
                            break;
                        }
                    }
                    if (throws) {
                        break;
                    }
                }
                if (throws) {
                    f->unwind = Unwind::May;
                    changed = true;
                }
            }
        }
    }

private:
    // WHAT A LAMBDA CARRIES. The name alone is not enough: the body has to allocate a slot of the
    // right WIDTH for each capture and read the environment word back as that type, and recording
    // only names meant every capture was read as a pointer -- a captured `int n` arrived as an
    // address. The two ends of a closure have to agree about the shape of every word between them.
    // Declared here, before anything returns one, because a member's TYPE has to be known where
    // the member function is declared even though its body may look further down.
    struct Captured {
        std::string name;
        const Type* type = nullptr;
        std::string typeName;
        bool byRef = false;
    };

    // WHAT A VALUE WAS DECLARED AS, both halves of it. The name answers which class it is -- a
    // `T*` is a `T` for that question, which is why `noteName` drops the outer stars -- and the
    // depth answers how many of those stars there were, which is a DIFFERENT question and had no
    // answer at all. One value, two facts: keeping them as two maps keyed by the same id would be
    // this type in pieces.
    struct DeclaredType {
        std::string name;
        int pointerDepth = 0;
    };

    // WHAT A `cascade` WALK DOES AT EACH NODE. The walk itself -- the null guard, the visited set,
    // the owned children, the depth -- is the same for all of them (§37.1 says so in as many words:
    // "they visit each node exactly once"), so it is one helper with the action as a parameter
    // rather than three walkers that would drift apart at the first fix to any of them.
    enum class CascadeAction { Delete, Println, Validate };

    // A BIT FIELD'S STORAGE IS NOT ITS OWN (§11.1): it is a slice of a unit it shares with the
    // fields declared beside it. All four numbers are needed at once by both the read and the write
    // -- which element, how wide that element is, where in it this field starts and how many bits
    // it takes -- so they travel as one record. Four maps keyed by the same name would be this type
    // with its name left off, and they would be free to disagree.
    struct BitField {
        int64_t index = 0;       // which element of the struct holds the unit
        uint32_t unitBits = 0;   // how wide that element is
        uint32_t offset = 0;     // where this field starts inside it
        uint32_t width = 0;      // how many bits it occupies
        bool isUnsigned = false; // decides whether the read sign-extends
    };

    // A STACK OBJECT WHOSE SCOPE WILL END. Destroyed in reverse when it does -- and a `try` needs
    // the same list a second time, for the way out through its landing block.
    struct ScopedObject {
        ValueId slot = kNoValue;
        std::string cls;
        // WHETHER THE SCOPE ALSO OWNS THE STORAGE. False for everything a declaration puts in a
        // frame slot -- the closing brace runs the destructor and the frame reclaims the bytes.
        // True for an object the scope MINTED on the heap and nothing else names: a `foreach`'s
        // iterator is the case, and for it the closing brace has to release as well as destruct.
        bool heap = false;
    };

    // The `cls` a String local is filed under in `scoped_`. Not a name a user could collide with:
    // every other entry is looked up with `findClass`, and a `$` cannot be written in a class name.
    static constexpr const char* kStringOwner = "$string";

    // ...and the prefix a REGION local is filed under, with its own name after it. The name is
    // needed because what a release does depends on the region's shape -- registry, ring, sub,
    // growable -- and the shape table is keyed by name.
    static constexpr const char* kRegionOwner = "$region:";
    static std::string regionOwnerKey(const std::string& name) {
        return std::string(kRegionOwner) + name;
    }



    // A `defer` BLOCK AND WHETHER IT HAS ALREADY RUN. The flag is a frame slot, zero until the
    // block runs. It exists because a `defer` written inside a `try` has TWO exits that can reach
    // it -- the closing brace and an exception passing through -- and running it twice is as wrong
    // as not running it at all. The closing brace sets the flag; the unwinding copy reads it.
    struct DeferSite {
        const ast::Block* body = nullptr;
        ValueId ran = kNoValue;
        // §32.10: `defer within milliseconds(100) { ... }` -- a soft deadline for the cleanup, in
        // milliseconds, evaluated where the `defer` is WRITTEN and checked when it runs. kNoValue
        // for the plain form. The spec allows an exception or an alert and Polaron alerts: a
        // soft-real-time cleanup must still finish, and killing a scope exit that may itself be an
        // unwind would be worse than the overrun it reports.
        ValueId budgetMs = kNoValue;
    };

    // One exception object of a prelude class, built where it is thrown. The class carries its own
    // message, so there is nothing to pass it.
    ValueId newRuntimeException(const std::string& cls, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
        const ValueId obj =
            callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                         {shape != nullptr ? sizeOfClass(shape, loc) : constLong(16, loc)}, loc);
        if (const Function* ctor = resolveKey(cls + "." + cls)) {
            emitCall(ctor, {obj}, loc);
        }
        noteName(obj, cls);
        return obj;
    }

    // `obj?.member`: the field when the object is there, and null when it is not (spec 3.7). The
    // whole point of the question mark is that the read does not happen at all on the null side --
    // so it is a branch, not a select, and the join carries whichever answer was reached.
    ValueId safeMember(ValueId object, const std::string& field, SourceLocation loc) {
        if (object == kNoValue) {
            return kNoValue;
        }
        const BlockId present = fn_->addBlock(fresh("safe.some"));
        const BlockId absent = fn_->addBlock(fresh("safe.none"));
        const BlockId join = fn_->addBlock(fresh("safe.join"));
        // The result type is the FIELD's, which is only known once the address is formed -- so the
        // present side is lowered first and the join takes its shape from it.
        branchOn(cmp(Op::CmpEq, object, nullPointer(loc), loc), absent, present);

        here_ = present;
        const ValueId addr = fieldAddress(object, field, loc);
        if (addr == kNoValue) {
            gap("MemberExpr(untranslatable object)", loc);
            return kNoValue;
        }
        const ValueId got = loadFrom(addr, loc);
        const Type* result = fn_->value(got)->type;
        const ValueId answer = fn_->addValue(result, ValueOrigin::BlockParam, join, 0, "");
        fn_->block(join)->params.push_back(answer);
        Inst fromPresent;
        fromPresent.op = Op::Br;
        Edge some{join, {}};
        some.args.push_back(got);
        fromPresent.edges.push_back(some);
        fromPresent.loc = loc;
        emit(std::move(fromPresent));

        here_ = absent;
        Inst fromAbsent;
        fromAbsent.op = Op::Br;
        Edge none{join, {}};
        // ZERO IS ABSENT for a pointer and for a number alike: `a?.next` on a null `a` is null, and
        // `a?.id` is nothing, which is the only answer that does not read through the null.
        none.args.push_back(result != nullptr && result->kind == TypeKind::Ptr
                                ? nullPointer(loc)
                                : constInt(0, result != nullptr && result->bits != 0 ? result->bits
                                                                                     : 32,
                                           loc));
        fromAbsent.edges.push_back(none);
        fromAbsent.loc = loc;
        emit(std::move(fromAbsent));

        here_ = join;
        noteName(answer, declaredName(got), pointerDepthOf(got));
        return answer;
    }

    // WHAT KIND OF REGION A NAME DECLARES (spec 17, the flavours). "" is the historical bump: a
    // cursor over a reservation, no per-object header, nothing to reclaim before the whole block
    // goes. Everything else is the runtime's: free-lists, a destructor registry, a grow chain.
    struct RegionShape {
        std::string flavor;
        bool growable = false;
        // THE PARENT, when this region's block was carved out of another one (`itself.allocate(n)
        // in region outer`). Empty for a region that stands on its own. It belongs here rather than
        // in a set beside this table because "whose memory is this" is the same question as "what
        // kind of region is this", and a second container keyed by the same name is this field with
        // the name of its type left off.
        std::string parent;
        bool isSub() const { return !parent.empty(); }
        // WHETHER THE REGION IS A FIELD, which is half of the registry question below.
        bool isField = false;
        // A `stack` region ALWAYS has a registry -- mark/rollback is built on it -- and a `ring`
        // never does, because all its entries share one destructor that its teardown runs.
        //
        // AND A FIELD REGION ALWAYS DOES, whatever its flavour. This half was missing, and what it
        // cost is exactly what the trusted path's own note predicts: "a parse tree assembled across
        // method calls had NO destructor run at all -- silently, because everything the compiler
        // could see was handled".
        //
        // The reason is the asymmetry between the two kinds. A LOCAL region cannot outlive the
        // function that declares it and cannot be passed anywhere, so every object that enters it is
        // written in that one block and the compiler's own list already has all of them -- tracking
        // them at run time would buy nothing and cost a call each. A FIELD region lives as long as
        // the object owning it, so objects enter it from any method, and the block that releases it
        // sees none of them. The registry is the only thing that can know.
        //
        // Measured: a `Pool` with a `region arena` field, a `makeDog` that allocates into it and a
        // `~Pool` that releases it, printed `~Dog 22 / ~Dog 11` on the trusted path and nothing at
        // all here.
        bool registry() const { return flavor == "stack" || (isField && flavor != "ring"); }
        // Whether the block needs the runtime's 448-byte descriptor rather than the lean 24-byte
        // header. Anything with free-lists, a registry or a grow chain does.
        //
        // `registry()` IS IN THE LIST, and it was the sentence above being true and the code below
        // not saying it: the flavours were enumerated by name, so a plain bump FIELD region -- which
        // now keeps a registry -- still got the lean header. `__polaron_region_track` then wrote a
        // track entry into a descriptor that was not there, and the program exited 0xC0000005.
        //
        // The descriptor is compatible with the inline cursor by construction: "its first three
        // fields ARE the lean header, so the inline cursor still reads them the same way".
        bool descriptor() const {
            return growable || registry() || flavor == "pool" || flavor == "stack" ||
                   flavor == "fixedslot" || flavor == "ring";
        }
        // WHETHER OBJECTS ARE ALLOCATED BY THE RUNTIME rather than bumped inline -- which is a
        // DIFFERENT question from whether the block has a descriptor, and the two shared one
        // predicate until a field region needed the first without the second.
        //
        // Adding `registry()` here as well sent every allocation in a plain bump field region
        // through `__polaron_region_new`, which gives each object the runtime's sixteen-byte slot
        // header. `Pool<T>` indexes its region by arithmetic, so its slots have to be uniform and
        // headerless: `arena_pool` corrupted the heap and exited 0xC0000374.
        //
        // A registry does not need the header. Teardown calls `dtor(ptr)` straight out of the track
        // entry; it is `rollback` -- the `stack` flavour, already in this list -- that identifies a
        // slot by `ptr - 16` and therefore needs one.
        bool runtimeAlloc() const {
            return growable || flavor == "pool" || flavor == "stack" || flavor == "fixedslot" ||
                   flavor == "ring";
        }
    };

    // Where `break` and `continue` go, innermost last.
    struct LoopTargets {
        BlockId breakTo = kNoBlock;
        BlockId continueTo = kNoBlock;
        // The label the loop was written with, if any -- `outer: while (...)`. What makes
        // `break outer;` reach past the innermost loop, which is the only reason to write one.
        std::string label;
        // HOW DEEP THE SCOPE WAS WHEN THE LOOP STARTED. A `break` LEAVES the loop's body, so
        // everything the body declared has to be torn down on the way out -- which is what a
        // fall-through end of the body already does and what a `break` was jumping straight past:
        // `for (...) { Res r = ...; if (i == 1) break; }` never ran `r`'s destructor on the
        // iteration that broke.
        size_t objects = 0;
        size_t defers = 0;
    };

    // Where a `yield` inside a `match` arm lands, and what the arm's value is typed as.
    struct YieldTarget {
        BlockId join = kNoBlock;
        const Type* type = nullptr;
    };

    // THE ENCLOSING `try`, AND HOW DEEP THE FRAME WAS WHEN IT STARTED. The depth is what a `throw`
    // needs: everything declared since then is being left behind and has to be torn down, and
    // everything older is still live and must not be.
    struct Handler {
        BlockId landing = kNoBlock;
        size_t objects = 0;
        size_t defers = 0;
    };

    // WHERE THE STORAGE UNDER A VALUE CAME FROM -- see `storage_`, which is where the three states
    // are explained and why two of them were not enough.
    enum class Storage { Unknown, Heap, Frame };

    // EVERYTHING THE LOWERING OF ONE BODY KEEPS.
    //
    // A body can be lowered in the MIDDLE of another -- a lambda, a `cascade` helper -- and every
    // one of these has to be put away and given back. Saving them one at a time is a list that has
    // to grow whenever a field is added, and twice already it did not: `declaredAs_` and
    // `storage_` were added later and left out, so a method containing a lambda lost the
    // declared type of every value after it and bound `nums.add(1)` to a different instantiation
    // than `nums.forEach(...)`. A partial save is worse than none: it works until it does not.
    //
    // ONE TYPE instead, so the compiler carries the list. Adding a field to the lowering and
    // forgetting it here is now a build error rather than a silent miscompile.
    struct BodyState {
        Function* fn = nullptr;
        BlockId here = kNoBlock;
        BlockId entry = kNoBlock;
        size_t allocaAt = 0;
        ValueId self = kNoValue;
        const Type* selfClass = nullptr;
        std::string selfClassName;
        std::unordered_map<std::string, ValueId> locals;
        std::unordered_map<ValueId, const Type*> slotTypes;
        std::unordered_map<ValueId, const Type*> pointee;
        std::unordered_map<ValueId, const Type*> pointeeOfSlot;
        std::unordered_map<ValueId, BitField> packedAt;
        std::unordered_map<ValueId, std::string> narrowAt;
        std::unordered_map<ValueId, std::string> weakSlotAt;
        std::unordered_map<ValueId, const ast::LambdaExpr*> cCallable;
        std::unordered_map<std::string, BlockId> labels;
        std::vector<LoopTargets> loops;
        std::vector<DeferSite> deferred;
        std::vector<ScopedObject> scoped;
        std::vector<ScopedObject> unwindObjects;
        std::vector<DeferSite> unwindDefers;
        std::unordered_map<ValueId, DeclaredType> declaredAs;
        std::unordered_map<ValueId, Storage> storage;
        std::vector<std::pair<ValueId, BlockId>> stringTemps;
        std::unordered_set<ValueId> stringSlots;
        std::unordered_map<std::string, ValueId> statics;
        std::vector<Handler> handlers;
        std::vector<YieldTarget> yields;
        std::unordered_map<std::string, const Type*> paramTypes;
    };

    // ---- types ----
    //
    // A `TypeRef` names a type the analyzer has already resolved; here it is turned into a PIR type
    // entry. The five facts are set from what the declaration says -- a struct is a value, a class
    // with a destructor owns, a `unique` is unique -- which is the point of §3.3: the facts are
    // decided ONCE, here, rather than re-derived by every pass that wants one.
    // TWO FACTS, NOT ONE VALUE. "I handled this" and "the result is nothing" are different answers,
    // and `kNoValue` was being asked to carry both: `Allocator.free` and the two `Raw` writes return
    // void, so a correct lowering of them read as "not mine", fell through to the generic path, and
    // came out as a call to a symbol nothing defines. `Allocator.alloc` worked and `Allocator.free`
    // did not, in the same program, for no reason visible at the call site.
    //
    // Declared HERE, at the top, because every builtin family below answers in it.
    struct Lowered {
        bool handled = false;
        ValueId value = kNoValue;
    };
    static Lowered nothing() { return {}; }
    static Lowered done(ValueId v = kNoValue) { return {true, v}; }

    // WHICH KIND OF THING THE NAME DECLARES. A `class` is a reference -- a value of it is a pointer
    // -- while a `struct`, `record` or `union` IS the bytes and travels by value. The question is
    // put to the DECLARATION rather than to the interned type: a class can be named before it is
    // declared, and the type's facts are only filled in when its declaration is walked, so asking
    // the type gives the wrong answer for exactly the forward references that need it most.
    // A name the language builds in. Asked so `typeOf` can skip the class lookup for the common
    // case and, more importantly, so `int` is never mistaken for a class nobody declared.
    static bool isPrimitiveName(const std::string& n) {
        return n.empty() || n == "void" || n == "boolean" || n == "char" || n == "float" ||
               n == "double" || n == "String" || n == "string" || n == "region" ||
               semutil::isIntName(n) || n.find('[') != std::string::npos ||
               // A trailing `*` is a pointer only when it is not part of a mangled instantiation.
               (!n.empty() && n.back() == '*' && n.find('$') == std::string::npos);
    }

    // An OBJECT parameter written without `&` and without `*`: the callee gets its own copy. A
    // value type copies anyway (it is the bytes), and a primitive has nothing to copy.
    bool passedByValue(const ast::TypeRef& t) const {
        if (t.isRef || t.pointerDepth > 0 || t.isArray) {
            return false;
        }
        const std::string named = ast::mangleGeneric(t.name, t.typeArgs);
        return !isPrimitiveName(named) && !isValueClass(named) && findClass(named) != nullptr;
    }

    bool isValueClass(const std::string& name) const {
        const ast::ClassDecl* d = findClass(name);
        return d != nullptr && (d->isStruct || d->isRecord || d->isUnion);
    }

    const Type* typeOf(const ast::TypeRef& t) {
        TypeTable& tt = out_.module.types;
        if (t.pointerDepth > 0) {
            return tt.ptrType();
        }
        // `nullable T` IS A POINTER whatever T is -- the value is boxed and absent is the null
        // pointer. The flag lives on the `TypeRef`; only `canonicalType` folds it into the NAME, so
        // asking the name alone (as `baseTypeOf` does) sees a plain `int` and gives back four bytes
        // that cannot hold "absent".
        if (t.isNullable && !t.isArray) {
            return tt.ptrType();
        }
        // A CLASS USED AS A VALUE IS A POINTER. The nominal struct is the LAYOUT -- what an `alloca`
        // makes and what a `gep` indexes -- and it was being handed out as the value type too, so a
        // method returning `ArrayList<int>` returned the whole aggregate by value and its caller
        // stored an eight-byte struct into a slot it thought held one. `%r = alloca %ArrayList`
        // beside `call %ArrayList @Range.stepBy(...)`: consistent, well-formed, and not a pointer to
        // anything, so every method called on it read from a copy of nothing.
        //
        // A `struct`, `record` or `union` is the exception, because those ARE values -- asked of
        // the declaration rather than of the interned type, since a class can be referenced before
        // it is declared and the type's facts are only set when it is.
        // ASKED BEFORE THE TYPE IS INTERNED, not after. Calling `baseTypeOf` first meant that a
        // class named before its declaration was walked got an OPAQUE nominal struct interned under
        // its name -- and when the real one arrived it was a different entry with the same name.
        // The backend then emitted two LLVM structs, LLVM renamed the second, and an `alloca` that
        // still pointed at the empty one asked the allocator for eight bytes for a three-field
        // object. A reference class is a pointer and never needed the struct at all.
        //
        // THE MANGLED NAME is what the declaration is filed under: `ArrayList<Row*>` is declared as
        // `ArrayList$Row*`, and asking for `ArrayList` finds nothing -- so a generic field looked
        // like an undeclared name and went back to interning an opaque struct, which is the very
        // thing this is here to avoid.
        const std::string named = ast::mangleGeneric(t.name, t.typeArgs);
        // A TUPLE TRAVELS AS A POINTER TO ITS STORAGE, like every other aggregate in this lowering.
        // The struct is the LAYOUT -- what the `alloca` makes and what a `gep` indexes -- and
        // handing it out as the value type too would return the whole aggregate by value, which
        // this backend has no `insertvalue`/`extractvalue` case for.
        if (cgutil::isTupleType(named)) {
            return tt.ptrType();
        }
        // AN ENUM OF THAT NAME IS NOT A CLASS OF THAT NAME.
        //
        // `findClass` answers for the standard library too, so a program that declares its own
        // `enum Color` -- which the library also has as a CLASS -- got the library's answer and the
        // parameter became a pointer. The ordinal was then passed into a pointer slot and
        // `cast<int>` read it back as an address: `shadow_stdlib_wide` printed `chain=8` where the
        // language says 10, and only at -O1 and above, where the arithmetic on a truncated address
        // folds to something stable enough to notice. Shadowing a standard-library name is what that
        // sample exists to check, and this is the rule it was checking.
        const bool ordinalEnum = [&] {
            auto e = enums_.find(named);
            if (e == enums_.end()) {
                if (const size_t dot = named.rfind('.'); dot != std::string::npos) {
                    e = enums_.find(named.substr(dot + 1));
                }
            }
            return e != enums_.end() && !e->second->isJavaStyle;
        }();
        // §21: `Result<int,int>` WITHOUT A STAR IS A VALUE -- the star is the only thing that
        // separates the two forms, and `value_compat` writes both a line apart to say so. Read as
        // a reference, every fallible return allocated: `Main.makeValue` called the allocator on
        // each of its two paths where the other back end returns `%__polaron_variant` in registers.
        if (const Type* asValue = valueVariantType(named); asValue != nullptr && t.arrayExtent == 0) {
            return asValue;
        }
        const bool reference = !ordinalEnum && !isPrimitiveName(named) && !isValueClass(named) &&
                               findClass(named) != nullptr;
        const Type* base = reference ? tt.ptrType() : baseTypeOf(named);
        if (t.arrayExtent > 0) {
            // `int[16]`: the extent is IN the type, so it is an inline array -- no header, no
            // pointer, nothing to release. See §3.2; conflating this with `int[]` is a double-free
            // or a leak depending on which way round it goes.
            //
            // NESTED, THROUGH THE NAME. The parser folds the FIRST group into the base name, so
            // `int[3][4]` arrives as name `int[3]` with extent 4 -- and wrapping the base in the
            // extent directly builds it inside out, four of three rather than three of four. The
            // spelling is the one place the order is unambiguous, so it is what decides.
            return baseTypeOf(named + "[" + std::to_string(t.arrayExtent) + "]");
        }
        if (t.isArray) {
            // ONCE PER DIMENSION. This wrapped exactly once however many `[]` were written, so an
            // `int[][]` parameter arrived as an `int[]`: indexing it produced an `i32` where the
            // second index needed a pointer, and the second `gep` was given `undef` as its base.
            // `arrayDims` is the count and it was being ignored; `isArray` only says "at least one".
            const Type* made = base;
            for (int d = std::max(1, t.arrayDims); d > 0; --d) {
                made = tt.sliceType(made);
            }
            return made;
        }
        return base;
    }

    // HOW ONE OF THESE IS STORED, as opposed to what it IS. A reference class occupies a POINTER
    // wherever it is kept -- in a local, in a field, and in an array element -- because a class is
    // a handle; only a `struct`, `record` or `union` sits inline. `typeOf` already decides this for
    // a `TypeRef`, and every place that had only the NAME decided differently: `new Node[2]()`
    // stepped by sixteen bytes and stored each element as a truncated 32-bit integer, so the first
    // read through it was a wild pointer.
    const Type* storageTypeOf(const std::string& name) {
        // AN ORDINAL ENUM'S VALUE IS THE ORDINAL: four bytes, not a handle. A catalog enum with
        // methods is also declared as a class, so the reference test below says pointer for it and
        // `Cell[] cells` became an array of eight-byte slots holding `inttoptr (i32 1)`.
        if (auto e = enums_.find(name); e != enums_.end() && !e->second->isJavaStyle) {
            return out_.module.types.intType(32);
        }
        // A `boolean` HAS THREE SIZES IN THIS ABI, and they are three different questions. As a
        // VALUE it is one bit -- what a comparison produces and a branch consumes. As an ARRAY
        // ELEMENT it is one BYTE: measured, `new boolean[4]()` asks the allocator for twelve, which
        // is the eight-byte header and four bytes of elements. As a FIELD it is FOUR, which is why
        // that one is decided at the field and not here. Answering four here made every
        // `boolean[]` four times its size and every `ArrayList<boolean>` disagree with the runtime
        // about where its second element is.
        // §21: THE VALUE FORM OF `Result`/`Option` IS A VALUE, so it is not reached through a
        // pointer. Asked as a class -- which `Result$int$int` is, monomorphised -- the test below
        // answers "reference" and every fallible return went to the allocator: one
        // `__polaron_malloc(16)` per return path, and a vtable per instantiation. `value_compat`
        // came out with 292 vtables against the other path's ONE.
        if (const Type* asValue = valueVariantType(name); asValue != nullptr) {
            return asValue;
        }
        const bool reference =
            !isPrimitiveName(name) && !isValueClass(name) && findClass(name) != nullptr;
        return reference ? out_.module.types.ptrType() : baseTypeOf(name);
    }

    // The `{ tag, payload }` entry for a `Result`/`Option` written WITHOUT a star, or null when the
    // name is not one. The rule is `cgutil::isValueVariant`'s and is shared with the other back end
    // deliberately: a `function<Result<int,int>>` value crosses between code compiled by both, so
    // the two must agree about which spellings are values down to the character.
    const Type* valueVariantType(const std::string& name) {
        if (!cgutil::isValueVariant(name)) {
            return nullptr;
        }
        if (auto seen = valueVariants_.find(name); seen != valueVariants_.end()) {
            return seen->second;
        }
        // The cases are what the tag selects between, in `permits` order -- `Ok` is 0 and `Err` is
        // 1, `Some` is 0 and `None` is 1 -- which is the order the other path assigns and the order
        // a `match` arm is compared against.
        std::vector<Field> cases;
        const ast::ClassDecl* decl = findClass(name);
        if (decl != nullptr) {
            for (const std::string& permitted : decl->permits) {
                Field c;
                c.name = permitted;
                c.type = out_.module.types.intType(64);
                cases.push_back(c);
            }
        }
        const Type* made = out_.module.types.variantType(name, std::move(cases));
        TypeFacts facts = made->facts;
        facts.isValue = true;
        facts.size = 16;   // { i32 tag, i64 payload }, padded to the payload's alignment
        facts.align = 8;
        out_.module.types.setFacts(made, facts);
        valueVariants_[name] = made;
        return made;
    }
    std::unordered_map<std::string, const Type*> valueVariants_;

    // The shape every value variant has: one tag, one payload. The NAME on a variant entry is what
    // keeps two different ones distinct as types; a constructed `Ok(x)` does not know which Result
    // it is about to become -- the declaration it flows into does -- so it is built in the common
    // shape and the slot it lands in says what it means.
    const Type* anyVariantType() {
        if (anyVariant_ == nullptr) {
            std::vector<Field> cases;
            for (const char* which : {"ok", "err"}) {
                Field c;
                c.name = which;
                c.type = out_.module.types.intType(64);
                cases.push_back(c);
            }
            anyVariant_ = out_.module.types.variantType("variant", std::move(cases));
            TypeFacts facts = anyVariant_->facts;
            facts.isValue = true;
            facts.size = 16;
            facts.align = 8;
            out_.module.types.setFacts(anyVariant_, facts);
        }
        return anyVariant_;
    }
    const Type* anyVariant_ = nullptr;

    // A METHOD CALLED ON THE VALUE FORM OF `Option`/`Result`.
    //
    // `Option<T>` written plain is `{ tag, payload }`, not an object -- and a method call wants an
    // object: `opt.isSome()` would read a table pointer out of the tag slot and dispatch through
    // address 1. It is the most ordinary use of the library there is, `list.find(...).isSome()`,
    // and `isNone`/`valueOr`/`errorOr`/`isOk`/`isErr`/`present` with it.
    //
    // The tag names the case EXACTLY, so the object is built rather than found: one frame slot per
    // case, its table stored, the payload decoded into whichever field that case carries -- `value`
    // for `Some`/`Ok`, `error` for `Err`, nothing for `None`. The two arms write the same slot and
    // the ordinary dispatch then runs against a real object, so an inherited method whose body
    // calls another of its own -- `Option.isNone` calls `this.isSome()` -- works unchanged.
    //
    // Answering kNoValue leaves the caller's existing path alone, which is what should happen when
    // the case classes were never instantiated.
    ValueId materialiseVariantCase(ValueId subject, const std::string& sumKey, SourceLocation loc) {
        const bool result = sumKey.rfind("Result", 0) == 0;
        const bool option = sumKey.rfind("Option", 0) == 0;
        if (!result && !option) {
            return kNoValue;
        }
        const size_t dollar = sumKey.find('$');
        const std::string tail = dollar == std::string::npos ? std::string() : sumKey.substr(dollar);
        const std::string okKey = (result ? "Ok" : "Some") + tail;
        const std::string elseKey = (result ? "Err" : "None") + tail;
        const Type* okShape = named_.count(okKey) != 0 ? named_[okKey] : nullptr;
        const Type* elseShape = named_.count(elseKey) != 0 ? named_[elseKey] : nullptr;
        if (okShape == nullptr || elseShape == nullptr) {
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;
        const ValueId held = allocaFor("vs.recv", tt.ptrType());

        Inst tag;
        tag.op = Op::VariantTag;
        tag.type = tt.intType(32);
        tag.operands.push_back(subject);
        tag.loc = loc;
        const ValueId which = cmp(Op::CmpEq, emit(std::move(tag)), constInt(0, 32, loc), loc);

        const BlockId good = fn_->addBlock(fresh("vs.ok"));
        const BlockId other = fn_->addBlock(fresh("vs.else"));
        const BlockId join = fn_->addBlock(fresh("vs.cont"));
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(which);
        br.edges.push_back(Edge{good, {}});
        br.edges.push_back(Edge{other, {}});
        br.loc = loc;
        emit(std::move(br));

        auto build = [&](BlockId where, const Type* shape, const std::string& key,
                         const char* field) {
            here_ = where;
            Inst room;
            room.op = Op::Alloca;
            room.type = shape;
            room.text = key + ".vs";
            room.loc = loc;
            const ValueId obj = emit(std::move(room));
            slotType_[obj] = shape;
            // NAMED BEFORE ANY FIELD IS ASKED FOR. `fieldAddress` finds the offset by looking the
            // object's class up from its declared name, and with no name it answered offset zero --
            // so the payload was written over the vtable pointer and the dispatch below read a
            // table at address 4.
            noteName(obj, key);
            if (hasVtable_.count(key) != 0) {
                Inst table;
                table.op = Op::ConstFn;
                table.type = tt.ptrType();
                table.text = key + ".vtable";
                table.loc = loc;
                storeAt(obj, 0, emit(std::move(table)), loc);
            }
            if (auto declared = fieldTypeName_.find(key + "." + field);
                declared != fieldTypeName_.end()) {
                const Type* want = declared->second.pointerDepth > 0
                                       ? tt.ptrType()
                                       : storageTypeOf(classNameOf(declared->second.name));
                Inst pl;
                pl.op = Op::VariantPayload;
                pl.type = want;
                pl.operands.push_back(subject);
                pl.loc = loc;
                const ValueId got = emit(std::move(pl));
                if (const ValueId at = fieldAddress(obj, field, loc); at != kNoValue) {
                    storeInto(at, got, loc);
                }
            }
            storeInto(held, obj, loc);
            gotoIfOpen(join);
        };
        build(good, okShape, okKey, "value");
        build(other, elseShape, elseKey, result ? "error" : "value");

        here_ = join;
        const ValueId recv = loadFrom(held, loc);
        noteName(recv, sumKey);
        return recv;
    }

    // Does evaluating this expression suspend? Only a body that is a state machine cares, and only
    // about what comes AFTER a value it already holds -- see `spillAcrossAwait`.
    static bool containsAwait(const ast::Expr* e) {
        if (e == nullptr) {
            return false;
        }
        if (dynamic_cast<const ast::AwaitExpr*>(e) != nullptr) {
            return true;
        }
        if (const auto* b = dynamic_cast<const ast::BinaryExpr*>(e)) {
            return containsAwait(b->lhs.get()) || containsAwait(b->rhs.get());
        }
        if (const auto* u = dynamic_cast<const ast::UnaryExpr*>(e)) {
            return containsAwait(u->operand.get());
        }
        if (const auto* c = dynamic_cast<const ast::CallExpr*>(e)) {
            if (containsAwait(c->callee.get())) {
                return true;
            }
            for (const auto& a : c->args) {
                if (containsAwait(a.get())) {
                    return true;
                }
            }
            return false;
        }
        if (const auto* m = dynamic_cast<const ast::MemberExpr*>(e)) {
            return containsAwait(m->object.get());
        }
        if (const auto* ix = dynamic_cast<const ast::IndexExpr*>(e)) {
            return containsAwait(ix->array.get()) || containsAwait(ix->index.get());
        }
        if (const auto* t = dynamic_cast<const ast::TernaryExpr*>(e)) {
            return containsAwait(t->cond.get()) || containsAwait(t->thenExpr.get()) ||
                   containsAwait(t->elseExpr.get());
        }
        return false;
    }

    // A value about to cross a suspension, put somewhere that survives one. Answers the slot it
    // went to, or -1 when there was nothing to do -- no state machine, or the scratch is full.
    int64_t spillAcrossAwait(ValueId v) {
        if (v == kNoValue || asyncStateObj_ == kNoValue || asyncScratchTop_ >= kAsyncScratch) {
            return -1;
        }
        const int64_t slot = asyncScratchBase_ + asyncScratchTop_++;
        Inst g;
        g.op = Op::Gep;
        g.type = out_.module.types.ptrType();
        g.operands.push_back(asyncStateObj_);
        g.aggregate = asyncStateTy_;
        g.imm = slot;
        g.text = "spill";
        const ValueId at = emit(std::move(g));
        slotType_[at] = fn_->value(v)->type;
        storeInto(at, v, SourceLocation{});
        spilled_[slot] = fn_->value(v)->type;
        return slot;
    }

    // THE ADDRESS IS COMPUTED AGAIN ON THIS SIDE, not carried across. A `gep` is an instruction like
    // any other: taken before the suspension it belongs to a block the resume does not come from,
    // and using it here is the very dominance failure the spill exists to fix -- moved one level
    // down, from the value to the address of the value.
    ValueId reloadSpill(int64_t slot, ValueId original) {
        auto held = spilled_.find(slot);
        if (slot < 0 || held == spilled_.end() || asyncStateObj_ == kNoValue) {
            return original;
        }
        --asyncScratchTop_;
        Inst g;
        g.op = Op::Gep;
        g.type = out_.module.types.ptrType();
        g.operands.push_back(asyncStateObj_);
        g.aggregate = asyncStateTy_;
        g.imm = slot;
        g.text = "reload";
        const ValueId at = emit(std::move(g));
        slotType_[at] = held->second;
        const ValueId back = loadFrom(at, SourceLocation{});
        if (const std::string was = declaredName(original); !was.empty()) {
            noteName(back, was, pointerDepthOf(original));
        }
        return back;
    }
    std::unordered_map<int64_t, const Type*> spilled_;

    // Whether a lowered value IS a value variant -- asked of the type it carries rather than of the
    // name it was declared with, because that is the fact the instructions below need: there is no
    // object to read a table out of, and no address to gep through.
    bool isVariantValue(ValueId v) const {
        if (v == kNoValue || fn_ == nullptr) {
            return false;
        }
        const Type* t = fn_->value(v)->type;
        return t != nullptr && t->kind == TypeKind::Variant;
    }

    // THE SIGN IS NOT IN THE PIR TYPE, by design: §3.1 puts the width in the type and the sign on
    // the OPERATION, because that is what the hardware does and what LLVM does. The consequence is
    // that this pass -- the last place that still holds the name the programmer wrote -- is the
    // only place that can decide `rem.u` over `rem.s`. Once the name is gone the choice is gone
    // with it, and the default here was signed: `(a + b) % 65521` over `uint` gave a NEGATIVE
    // checksum, and nothing failed except the answer.
    // WHAT A NAME IS MADE OF, chasing `newtype` down to the primitive under it.
    //
    // `isUnsignedName` below is a list of primitive SPELLINGS, and a newtype is not one of them --
    // so `newtype Batch = uint` answered "signed" to every question the lowering asks about a
    // value's sign: which shift, which comparison, which division, and which conversion on the way
    // to a printer. `cast<Batch>(cast<uint>(4000000000))` came out as -294967296.
    //
    // A chain, because a newtype over a newtype over an int is still an int, and bounded because a
    // cycle in the table would otherwise be an infinite loop rather than a diagnostic.
    std::string groundName(const std::string& name) const {
        std::string at = name;
        for (int hops = 0; hops < 16; ++hops) {
            auto it = newtypeGround_.find(at);
            if (it == newtypeGround_.end() || it->second == at) {
                return at;
            }
            at = it->second;
        }
        return at;
    }
    std::unordered_map<std::string, std::string> newtypeGround_;

    static bool isUnsignedName(const std::string& name) {
        return name == "ubyte" || name == "ushort" || name == "uint" || name == "ulong" ||
               name == "uint8" || name == "uint16" || name == "uint32" || name == "uint64" ||
               // An address has no sign. Comparing two of them signed puts every address above the
               // half-way mark below everything under it -- which, in a kernel, is most of memory.
               name == "address" || name == "halfaddress" || name == "shortaddress" ||
               name == "byteaddress" ||
               // A `char` is a code point. Sign-extending one turns every byte above 0x7F negative
               // on the way to the comparison that was about to classify it.
               name == "char";
    }

    // Records what a value -- or a slot, which is a value too -- was DECLARED as, in the words the
    // programmer used. Two facts are read back off it, and neither survives in the interned type:
    // the sign (`uint` and `int` are both `int<32>`) and the class (`String`, like every object, is
    // a `ptr`). Losing the second is what made `data.length()` on a `String` bind to `Buffer.length`
    // -- the first method in the module whose name happened to end that way.
    // BY VALUE, deliberately: every caller but one passes `declaredName(other)`, which is a
    // reference INTO this map, and `operator[]` can rehash before the assignment reads it.
    void noteName(ValueId v, std::string typeName, int pointerDepth = 0) {
        if (v != kNoValue && !typeName.empty()) {
            declaredAs_[v] = DeclaredType{std::move(typeName), pointerDepth};
        }
    }

    void noteName(ValueId v, const ast::TypeRef& t) {
        // THE TYPE AS WRITTEN, brackets and stars included -- `canonicalType` is the one spelling
        // both the analyzer and the trusted path already agree on, so it also carries the generic
        // mangling (`ArrayList<int>` -> `ArrayList$int`, without which `nums.add(10)` bound to
        // `ArrayList$long.add`). What each caller wants is DERIVED from it rather than recorded
        // separately: `classNameOf` for a receiver, `elementNameOf` for what an index yields.
        //
        // Recording only unadorned names meant `String[] argv` recorded nothing at all, so
        // `argv[i].equals(flag)` had no idea its receiver was a String and resolved `equals` by
        // bare name -- one of the reasons `Args.has` answered no for a flag that was there.
        //
        // THE OUTER `*`s ARE DROPPED HERE rather than stripped later, because they cannot be told
        // apart from the ones INSIDE a mangled name: `ArrayList<Row*>` is `ArrayList$Row*`, and a
        // rule that removes a trailing star turns it into `ArrayList$Row`, a class that does not
        // exist. `ast.h` says as much where it explains why multi-level pointers are refused on
        // generics. A pointer to a `T` is a `T` for every question asked of this map, so the depth
        // is not information anything downstream wants.
        //
        // The DEPTH is kept beside the name rather than thrown away with the stars. `Box b` and
        // `Box* p` recorded the identical string, so `&b` -- which must yield the object, since an
        // object's identity IS its pointer -- and `&p` -- which must yield the address of the slot
        // holding p -- were the same question with one answer, and one of them was always wrong.
        ast::TypeRef bare = t;
        const int depth = t.pointerDepth > 0 ? t.pointerDepth : (t.isPointer ? 1 : 0);
        bare.pointerDepth = 0;
        bare.isPointer = false;
        bare.isRef = false;
        // ...AND THE NAME IS THE KEY. Where two classes answer to one name, what is recorded is
        // WHICH of them this value is -- resolved from where the type was written. Everything
        // downstream then looks up a class, a field or a method by that key and gets the right one,
        // without any of those sites having to know that a collision exists.
        noteName(v, resolveClassKey(ast::canonicalType(bare)), depth);
    }

    // A `T*` IS A `T`: a pointer to an object is the object, for every question about which class
    // it is. A `T[]` IS NOT -- an array of `T` has no members of `T`, and treating it as one is how
    // an array ends up looking like whatever its element type declares.
    static std::string classNameOf(std::string name) {
        // `nullable T` IS A `T` that may be absent; which class it is does not change.
        if (ast::typeIsNullable(name)) {
            name = name.substr(std::strlen(ast::kNullablePrefix));
        }
        // NO STAR-STRIPPING: `noteName` already dropped the outer pointers, and a `*` that is still
        // here belongs to a mangled type argument (`ArrayList$Row*`) where removing it names a
        // class nobody declared.
        return !name.empty() && name.back() == ']' ? std::string() : name;
    }

    // `String[]` -> `String`; one dimension only, because that is what one index removes.
    static std::string elementNameOf(const std::string& name) {
        return name.size() > 2 && name.compare(name.size() - 2, 2, "[]") == 0
                   ? name.substr(0, name.size() - 2)
                   : std::string();
    }

    // ...AND THE ELEMENT AS SOMETHING THAT CAN BE NAMED: `Window*[]` indexed once is a `Window`
    // held through ONE POINTER, and those are two facts. `classNameOf` deliberately strips no
    // stars -- a `*` left in a name belongs to a mangled type argument like `ArrayList$Row*`,
    // where removing it names a class nobody declared -- so an element spelled `Window*` asked
    // `findClass("Window*")`, got nothing, and the call on it resolved BY BARE NAME.
    //
    // In a program with one `identity()` that is invisible. pico has several, and
    // `this.stack[i].identity()` on the compositor's window stack bound to `NvmeQueue.identity`:
    // a Window passed as an NVMe queue, whose `invariant this.phase == 0 || this.phase == 1` read
    // a window field and stopped the machine. The depth belongs on the VALUE, which `noteName`
    // has always carried separately; only this one split was missing.
    static DeclaredType elementDeclOf(const std::string& name) {
        std::string elem = elementNameOf(name);
        int depth = 0;
        while (!elem.empty() && elem.back() == '*') {
            elem.pop_back();
            ++depth;
        }
        return DeclaredType{elem, depth};
    }

    const std::string& declaredName(ValueId v) const {
        static const std::string none;
        auto it = declaredAs_.find(v);
        return it != declaredAs_.end() ? it->second.name : none;
    }

    // HOW MANY STARS were written on it. Zero for a value or an object handle; one for a `T*`.
    int pointerDepthOf(ValueId v) const {
        auto it = declaredAs_.find(v);
        return it != declaredAs_.end() ? it->second.pointerDepth : 0;
    }

    // A SIGN BELONGS TO AN INTEGER. `declaredAs_` also carries class names and pointer targets now,
    // and a `uint*` is a pointer -- asking the name alone would call it unsigned and pick `div.u`
    // for arithmetic on an address.
    bool isUnsignedValue(ValueId v) const {
        if (!isUnsignedName(groundName(declaredName(v)))) {
            return false;
        }
        const ValueDef* d = fn_ != nullptr ? fn_->value(v) : nullptr;
        // AN ADDRESS IS ITS OWN KIND, and this asked only about `Int` -- so the four spellings of
        // `address` above were listed as unsigned and then thrown away one line later, on every
        // one of them. Every `>>` on an address came out arithmetic, every `<` signed, every `/`
        // and `%` signed: exactly the smearing the comment above says the entry exists to prevent,
        // in the one kind of program where addresses reach past the half-way mark.
        return d != nullptr && d->type != nullptr &&
               (d->type->kind == TypeKind::Int || d->type->kind == TypeKind::Addr);
    }

    // How many lanes a SIMD type name has, or 0 when the name is not one. One table, because every
    // question about these types -- what it interns to, how many arguments its constructor takes,
    // whether `.z` names a lane of it -- is this same number.
    static uint64_t vectorLanes(const std::string& name) {
        if (name == "vec2") return 2;
        if (name == "vec3") return 3;
        if (name == "vec4") return 4;
        if (name == "mat4") return 16;
        return 0;
    }

    // Which lane a swizzle name reads, or -1. `x y z w` in order, which is the GLSL convention the
    // language took and the one the samples are written against.
    static int laneOfSwizzle(const std::string& member) {
        if (member.size() != 1) {
            return -1;
        }
        switch (member[0]) {
            case 'x': return 0;
            case 'y': return 1;
            case 'z': return 2;
            case 'w': return 3;
            default: return -1;
        }
    }

    // HOW BIG AN AGGREGATE IS, WHICH IS NOT THE SUM OF ITS FIELDS.
    //
    // A field begins at the next offset its OWN alignment allows, and the whole is rounded up to
    // the aggregate's alignment -- that tail is not decoration, it is what makes an ARRAY of them
    // step evenly. `struct Cell { int tag; double value; }` sums to twelve and measures sixteen.
    //
    // Summing was silent because it disagreed with only half the compiler. The LLVM struct type is
    // `{ i32, double }`, so a `gep` to a FIELD used the real offset -- 8 -- while the backend scaled
    // an INDEX by this number -- 12. Element one therefore began four bytes before it lived, and
    // each write of a tag landed inside the previous element's double: `struct_array_stride.pol`
    // printed `0.0 0.0 0.0 3.5`, four right answers' worth of arithmetic on three wrong reads. The
    // allocation was short too -- `4 * 12` for data needing 64 -- so the last element wrote past
    // the block.
    //
    // A `layout` IS THE EXCEPTION AND SAYS SO. It describes a register block or a wire format,
    // where a hole the compiler inserted is a field at the wrong offset, so `packed` means summed.
    // A LAYOUT'S BYTE CEILING, CHECKED AGAINST WHAT THE TYPE ACTUALLY MEASURES.
    //
    // `implements Tick` where `layout Tick` says `itself.fitWithin(8 bytes)` is a promise about the
    // target's real arrangement, so only this stage can settle it -- which is also why the analyzer
    // defers it, and why a blown budget shows up at build time rather than in the editor's live
    // check. One authority on layout instead of two models that can disagree.
    //
    // Reordering by hand is explicitly ruled out in the message because the compiler has already
    // done it: the fields were laid out widest-first precisely to make the budget fit, so a reader
    // who has just been told the number needs to know that the obvious next move is not available.
    void checkLayoutBudget(const ast::ClassDecl& c, uint64_t measured) {
        if (c.layouts.empty() || measured == 0) {
            return;
        }
        for (const std::string& ln : c.layouts) {
            const ast::ClassDecl* decl = findClass(ln);
            if (decl == nullptr || !decl->isLayout) {
                continue;
            }
            Arrangement want;
            (void)readArrangement(*decl, want);   // malformed is already reported by the analyzer
            if (want.maxBytes < 0 || static_cast<long long>(measured) <= want.maxBytes) {
                continue;
            }
            std::string msg = "`" + c.name + "` is arranged by `" + ln + "`, which fits it within " +
                              std::to_string(want.maxBytes) + " bytes -- it measures " +
                              std::to_string(measured) +
                              ". The fields were already ordered widest-first to make it fit, so "
                              "reordering them by hand will not help: something has to be narrower, "
                              "or leave";
            if (!want.refuseMessage.empty()) {
                msg += " (" + want.refuseMessage + ")";
            }
            refuse(msg, c.loc);
        }
    }

    static void measureAggregate(const std::vector<Field>& fields, bool packed, TypeFacts& facts) {
        uint64_t size = 0;
        uint64_t align = 1;
        for (const Field& f : fields) {
            const uint64_t width = f.type != nullptr ? f.type->facts.size : 0;
            const uint64_t want =
                packed ? 1 : std::max<uint64_t>(1, f.type != nullptr ? f.type->facts.align : 1);
            size = (size + want - 1) / want * want;   // the padding BEFORE this field
            size += width;
            align = std::max(align, want);
        }
        facts.size += (size + align - 1) / align * align;
        facts.align = static_cast<uint32_t>(std::max<uint64_t>(facts.align, align));
    }

    const Type* baseTypeOf(const std::string& name) {
        TypeTable& tt = out_.module.types;
        // A TRAILING `*` ARRIVES AS PART OF THE NAME from a cast: `cast<int*>(x)` hands this the
        // string "int*", and with no case for it the name fell through to "an unknown class" and
        // became an opaque nominal struct. The conversion then matched nothing -- neither
        // `addr -> ptr` nor anything else -- so the cast emitted no instruction at all and an
        // address was used as a pointer, which the backend turns into `undef`.
        // ...but NOT when the star belongs to a mangled type argument. `ArrayList$Row*` is a class
        // whose element is a pointer, not a pointer to an `ArrayList$Row`, and reading it as one
        // made `new ArrayList<Row*>()` allocate eight bytes for a three-field object.
        if (name.size() > 1 && name.back() == '*' && findClass(name) == nullptr &&
            (name.find('$') == std::string::npos ||
             // ...UNLESS WHAT IS LEFT NAMES A CLASS. `ArrayList<Row*>` mangles to `ArrayList$Row*`
             // and so does `ArrayList<Row>*`: one is an instantiation whose element is a pointer,
             // the other is a pointer to an instantiation, and the two spellings are identical. The
             // tie is broken by asking which of them EXISTS -- if `ArrayList$Row` is a declared
             // class and `ArrayList$Row*` is not, the star is the outer one. Read the other way,
             // `HashMap<String, ArrayList<int>*>` gave its value type an opaque struct nobody
             // declared, and `m.put("a", xs)` went out as `put(ptr, %"ArrayList$int*" undef)`.
             findClass(name.substr(0, name.size() - 1)) != nullptr)) {
            return tt.ptrType();
        }
        // `int[3]` ARRIVES AS A NAME sometimes -- a fixed-extent array whose spelling the analyzer
        // carried through as a string rather than as a `TypeRef` with an extent. Read as an opaque
        // class it became a nominal struct with no fields, and every `gep` into one was "index 0 is
        // past the end". The brackets say what it is; parsing them here is the whole fix.
        // THE FIRST BRACKET GROUP IS THE OUTER ONE, so `int[3][4]` is three of `int[4]` -- the way
        // C, Java and C# all read it, and the way the trusted path reads it. Taking everything
        // between the first `[` and the LAST `]` made `int[3][4]` unparseable, and the TypeRef
        // route built it inside out: `grid.length()` answered 4 and `grid[0].length()` answered 3.
        const size_t open = name.find('[');
        const size_t close = open == std::string::npos ? std::string::npos : name.find(']', open);
        if (open != std::string::npos && close != std::string::npos) {
            const std::string inner = name.substr(open + 1, close - open - 1);
            // The element is everything else: the base with THIS group removed, so a second group
            // stays where it is and becomes the element's own extent.
            const std::string rest = name.substr(0, open) + name.substr(close + 1);
            if (inner.empty()) {
                return tt.sliceType(storageTypeOf(rest));
            }
            if (inner.find_first_not_of("0123456789") == std::string::npos) {
                return tt.arrayType(storageTypeOf(rest), std::strtoull(inner.c_str(), nullptr, 10),
                                    ArrayStorage::Inline);
            }
        }
        if (name == "void" || name.empty()) return tt.voidType();
        if (name == "boolean") return tt.boolType();
        if (name == "byte") return tt.intType(8);
        if (name == "short") return tt.intType(16);
        if (name == "int") return tt.intType(32);
        if (name == "long") return tt.intType(64);
        // `Decimal` IS A 128-BIT MANTISSA SCALED BY 10^18 (§34) -- fixed point, not floating. That
        // is the whole reason the type exists: money that adds up. Unrecognised here it fell to a
        // `double`, which prints the same for `12.34` and is a different NUMBER: the sample that
        // divides five by two printed 2 where the language says 2.5, because the cast that should
        // have scaled produced an `int` and the division was integer division.
        if (name == "Decimal") return tt.intType(kDecimalBits);
        // THE UNSIGNED FAMILY, which this pass did not recognise at all -- every one of them fell
        // through to "an unknown class" and became an opaque nominal struct. A checksum that adds
        // bytes and takes a remainder then produced a negative number, because the arithmetic was
        // signed and the type that said otherwise had been thrown away.
        //
        // §3.1: the WIDTH is the type, the SIGN is the operation. So the width is decided here and
        // the sign travels beside the value -- see `unsigned_`.
        if (name == "ubyte" || name == "uint8" || name == "int8") return tt.intType(8);
        if (name == "ushort" || name == "uint16" || name == "int16") return tt.intType(16);
        if (name == "uint" || name == "uint32" || name == "int32") return tt.intType(32);
        if (name == "ulong" || name == "uint64" || name == "int64") return tt.intType(64);
        if (name == "char") return tt.intType(32);       // a codepoint
        if (name == "float") return tt.floatType(32);
        if (name == "double") return tt.floatType(64);
        // THE NARROW ADDRESSES, IN BOTH SPELLINGS. A `short address` is two words in the source and
        // ONE in every canonical name the rest of the compiler builds -- `canonicalType` closes the
        // gap, and `ast.h` and `cgutil.cpp` both spell it `shortaddress`. Listing only the spaced
        // form meant the canonical one fell through to "an unknown class" and became an opaque
        // nominal struct: pico's `Cpu.outb(short address port, ...)` passed `%shortaddress` to an
        // `asm` block that reads `$0` into `dx`, the register allocator gave it a 64-bit register,
        // and the assembler refused `mov dx, rcx`. Sixteen bits of port number, in a struct nobody
        // declared.
        if (name == "address") return tt.addrType(64);
        if (name == "half address" || name == "halfaddress") return tt.addrType(32);
        if (name == "short address" || name == "shortaddress") return tt.addrType(16);
        if (name == "byte address" || name == "byteaddress") return tt.addrType(8);
        if (name == "region") return tt.regionType();
        // THE SIMD FAMILY (§34.6): N lanes of `float`, in one register. A `mat4` is sixteen of them
        // in row-major order -- the same shape the trusted path uses, because a `mat4` crossing
        // between code compiled by both paths has to be one thing.
        if (const uint64_t lanes = vectorLanes(name); lanes != 0) {
            return tt.vectorType(tt.floatType(32), lanes);
        }
        // BOTH SPELLINGS ARE THE SAME REPRESENTATION: a pointer to the three-word object. Only the
        // capital one was listed, so a `string` -- the mutable one -- fell through to the opaque
        // nominal struct at the bottom and got a size of ZERO. `string[] args` then had a stride of
        // one byte, so `args[1]` read one byte past `args[0]` and `main_args` segfaulted on the
        // first element it printed.
        if (name == "String" || name == "string") return tt.ptrType();
        // AN ORDINAL ENUM'S VALUE IS FOUR BYTES. Its entry in `named_` is a VARIANT -- the closed
        // case set §9's rule 18 checks exhaustiveness against -- and that is the type's SHAPE for
        // the verifier, not what a variable of it holds. Handed out as the value type, a `Quarry`
        // parameter became `{i32, i64}` and every call passed `undef` into it.
        //
        // ...AND ITS NAME MAY ARRIVE QUALIFIED. `enums_` is filed under the name the enum was
        // declared with; a type written inside a namespace resolves to `Main.App.Color`. Looked up
        // only by the long form the enum was not found, the name fell through to the class rule, and
        // a `Color` parameter became a POINTER -- with the ordinal passed into it and `cast<int>`
        // reading the pointer back. `shadow_stdlib_wide` printed `chain=8` where the language says
        // 10, and only at -O1 and above, where arithmetic on a truncated address folds to something
        // stable enough to see. The qualified form is tried FIRST, because where both a local enum
        // and a standard-library class answer to one name the specific answer is the right one --
        // which is the whole subject of that sample.
        auto e = enums_.find(name);
        if (e == enums_.end()) {
            if (const size_t dot = name.rfind('.'); dot != std::string::npos) {
                e = enums_.find(name.substr(dot + 1));
            }
        }
        if (e != enums_.end() && !e->second->isJavaStyle) {
            return tt.intType(32);
        }
        // A TUPLE IS AN ANONYMOUS VALUE STRUCT (§22.5), spelled `(T0,T1,...)`. Nothing declares it,
        // so it fell through to the opaque-nominal case and came out with no fields and no size:
        // `(int q, int r) = divmod(17,5)` read both components out of zero bytes. Interned under
        // its own spelling, which is what makes two identical tuples the same type.
        if (cgutil::isTupleType(name)) {
            if (auto seen = named_.find(name); seen != named_.end()) {
                return seen->second;
            }
            std::vector<Field> parts;
            int at = 0;
            for (const std::string& part : cgutil::tupleElems(name)) {
                Field f;
                f.type = storageTypeOf(part);
                f.name = "_" + std::to_string(at++);
                parts.push_back(f);
            }
            const Type* made = tt.structType(name, std::move(parts), true);
            TypeFacts facts = made->facts;
            facts.isValue = true;
            measureAggregate(made->fields, made->packed, facts);
            tt.setFacts(made, facts);
            named_[name] = made;
            return made;
        }
        // THE REFLECTION TOKENS ARE REFERENCES (§31), and nothing declares them: they are blocks of
        // words the compiler builds and hands out, not classes with a layout anybody wrote. Read as
        // undeclared classes they became opaque nominal structs, so `ArrayList<Field>.add` took its
        // element BY VALUE as an empty aggregate -- `call void @add(ptr %l, %Field undef)` -- and
        // every token put in a list was thrown away on the way in.
        if (name == "Type" || name == "Method" || name == "Field" || name == "Annotation") {
            return tt.ptrType();
        }
        // `nullable T` IS A POINTER: the value is boxed, and absent IS the null pointer. Read as an
        // unknown class it became an opaque nominal struct, so `nullable int x = null;` allocated
        // eight bytes of nothing and `x ?? 99` read whatever the frame held.
        if (ast::typeIsNullable(name)) {
            return tt.ptrType();
        }
        // A CALLABLE VALUE IS A POINTER. `function<int,int>` was read as an unknown class and
        // became an opaque nominal struct, so a lambda passed to a method was passed BY VALUE as
        // an empty aggregate -- `call i32 @apply(%"function<int,int>" undef, i32 21)`. Behind the
        // pointer is `{code, env}`; `funcptr` is the bare code pointer, which is also one word.
        if (name.rfind("function<", 0) == 0 || name.rfind("funcptr<", 0) == 0) {
            return tt.ptrType();
        }
        // A CATALOG IS AN INTERFACE FOR ENUMS, and a value of one is a TAGGED ORDINAL -- a 64-bit
        // integer, not an object. Read as an undeclared class it became an opaque nominal struct,
        // so `Tier t = AppLevel.a;` allocated a struct and stored an integer into it.
        if (catalogs_.count(name) != 0) {
            return tt.intType(64);
        }
        // WHICH CLASS OF THAT NAME, decided from where the name was written -- and only when two
        // of them exist, which is nearly never.
        const std::string key = resolveClassKey(name);
        auto it = named_.find(key);
        if (it != named_.end()) {
            return it->second;
        }
        // A class not yet seen: an opaque nominal struct, filled in when its declaration is walked.
        const Type* made = tt.structType(key, {}, true);
        named_.emplace(key, made);
        return made;
    }

    // ---- declarations ----

    // A class holds ONE `members` vector, not one per kind, so every walk here filters it. Done in
    // one place rather than at each of the five call sites, because five copies of a dynamic_cast
    // chain is five places for a member kind to be forgotten.
    template <typename T, typename F>
    static void forEachMember(const ast::ClassDecl& c, F&& fn) {
        for (const auto& m : c.members) {
            if (auto* typed = dynamic_cast<const T*>(m.get())) {
                fn(*typed);
            }
        }
    }

    // AN IMPORTED BUNDLE IS DECLARED THE SAME WAY EVERY OTHER ONE IS, and then not defined.
    //
    // This used to walk `MethodDecl` alone, which is the same omission `declareClass` has a comment
    // about three hundred lines below: a `ClassDecl` keeps every member in one vector, so a walk
    // that looks for one member kind silently drops the others. What it dropped here was the
    // CONSTRUCTOR -- and a constructor that is not declared is a constructor no `new` can call.
    //
    //     Counter* c = new Counter(10) on heap;  c.increment(); c.increment();
    //
    // printed `value = 2`. Not a crash, not a link error: the object was allocated, zeroed, and
    // handed over unbuilt, so the ten the programmer passed was simply never written. Every field
    // of every imported class was reading whatever a fresh block happens to hold.
    //
    // It also dropped the field LAYOUT and the vtable, which is why the four tests that read a
    // field across the bundle boundary and the one that dispatches virtually failed together.
    //
    // Going through `declareNamespace` is not a shortcut -- it is the point. What a consumer needs
    // to know about an imported class is exactly what a compiler knows about a local one MINUS the
    // bodies, and the bodies are already skipped, once, in the loop that lowers them. Two walks that
    // are meant to agree about what a class IS should not be two walks.
    void declareOnly(const ast::Bundle& b) {
        const size_t before = out_.module.functions.size();
        for (const ast::Namespace& ns : b.namespaces) {
            declareNamespace(ns, b);
        }
        // ...AND EVERYTHING IT DECLARED LIVES ELSEWHERE. `declareNamespace` files a method the way a
        // local one is filed -- public or internal, to be defined here -- and nothing defines these.
        // External is the honest linkage for a body in a `.polb`, and it is what stops the module's
        // own dead-stripping from deleting a declaration nobody in this module calls yet.
        for (size_t i = before; i < out_.module.functions.size(); ++i) {
            out_.module.functions[i]->linkage = Linkage::External;
            // ...UNLESS IT IS LOADED AT RUN TIME, in which case nothing will define it at link time
            // either and the declaration has to become a thunk. Recorded here rather than
            // rediscovered later because THIS is the walk that knows which functions belong to which
            // bundle: afterwards the module is one flat list and the boundary is gone.
            if (b.isDynamic) {
                dynamicFns_[b.name].push_back(out_.module.functions[i].get());
            }
        }
    }

    // §2.4: A BUNDLE THAT IS LOADED AT RUN TIME IS CALLED THROUGH A THUNK.
    //
    // `--use-dynamic` means the consumer links against nothing: the `.polb` is opened on first use,
    // its ABI fingerprint checked against the one the consumer was compiled with, and each method
    // looked up by name. The trusted path builds these in `emitDynamicThunks`; this path built none,
    // so the program linked against `Calc.square` and no definition of it existed anywhere.
    //
    // Built as PIR functions rather than as LLVM emitted at the end, which is the choice worth
    // stating: the failure path THROWS -- a catchable `BundleNotLoadedException`, because a missing
    // plug-in is an ordinary thing for a program to handle -- and a throw is exactly the construct
    // whose lowering differs between the two backends. Expressed here it is `Op::Raise`, and
    // whichever exception model the target uses is the backend's business, once, where it already
    // lives. The optimiser also gets to see the thunk, which an LLVM-level afterthought would hide.
    void emitDynamicThunks() {
        if (bundles_.dynamic.empty()) {
            return;
        }
        for (const DynamicBundle& info : bundles_.dynamic) {
            auto found = dynamicFns_.find(info.name);
            if (found == dynamicFns_.end()) {
                continue;
            }
            // ONE HANDLE PER BUNDLE, not per method: the container is opened once and every thunk
            // into it reads the same cache. A per-method handle would reload and re-verify the same
            // file for every symbol, and -- worse -- a bundle holding state would get one copy of it
            // per method called.
            const std::string handleName = "__dynh_" + info.name;
            bool haveGlobal = false;
            for (const Global& g : out_.module.globals) {
                haveGlobal = haveGlobal || g.name == handleName;
            }
            if (!haveGlobal) {
                Global h;
                h.name = handleName;
                h.type = out_.module.types.ptrType();
                h.linkage = Linkage::Internal;
                h.zeroInit = true;
                out_.module.globals.push_back(std::move(h));
            }
            for (Function* fn : found->second) {
                if (fn == nullptr || !fn->blocks.empty()) {
                    continue;
                }
                // A CONSTRUCTOR AND A DESTRUCTOR ARE METHODS TOO, and the `.polb` exports them under
                // the same keys. What is skipped is an `extern` the header declares -- a C symbol
                // the consumer resolves for itself, which is not the bundle's code at all.
                if (fn->kind != FnKind::Method && fn->kind != FnKind::Constructor &&
                    fn->kind != FnKind::Destructor && fn->kind != FnKind::Operator) {
                    continue;
                }
                dynamicThunk(fn, info, handleName);
            }
        }
    }

    // One thunk. The shape is the trusted path's, statement for statement, because the two have to
    // fail the same way as well as succeed the same way -- `bundle_absent_caught` and
    // `bundle_abi_mismatch_caught` are tests about which exception comes out.
    void dynamicThunk(Function* fn, const DynamicBundle& info, const std::string& handleName) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i32 = tt.intType(32);
        const Type* ret = fn->signature != nullptr ? fn->signature->element : tt.voidType();
        const SourceLocation loc{};

        // A THUNK THROWS, AND `settleUnwinding` HAS ALREADY RUN. It settled a DECLARATION -- a
        // function with no body cannot be shown to unwind, so it was marked `Unwind::Never` and the
        // backend wrote `nounwind` on it. Then this gave it a body that raises, and `nounwind` on a
        // function that unwinds is not a missed optimisation: MSVC's unwinder reaches a frame it was
        // told could not be there and calls `__fastfail`. The program died with 0xC0000409 having
        // printed nothing, and `bundle_absent_caught` -- whose whole subject is catching this very
        // exception -- read it as "the exception was not caught". It was never allowed to be raised.
        fn->unwind = Unwind::May;

        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        statics_.clear();
        stringTemps_.clear();
        stringSlots_.clear();
        scoped_.clear();
        unwindObjects_.clear();
        handlers_.clear();
        deferred_.clear();
        selfSlot_ = kNoValue;
        selfClass_ = nullptr;
        selfClassName_.clear();

        // The parameters, forwarded verbatim. Whatever the signature says arrives here and leaves
        // for the real method unchanged: a thunk that converted anything would be a second opinion
        // about the ABI, and the whole point of the fingerprint is that there is only one.
        std::vector<ValueId> incoming;
        if (fn->signature != nullptr) {
            for (uint32_t i = 0; i < fn->signature->fields.size(); ++i) {
                const Field& p = fn->signature->fields[i];
                const ValueId v =
                    fn->addValue(p.type, ValueOrigin::BlockParam, here_, i, p.name);
                fn_->block(here_)->params.push_back(v);
                incoming.push_back(v);
            }
        }

        // The loader writes WHY it failed here, and the two reasons are different exceptions.
        const ValueId statusSlot = allocaFor("dyn.status", i32);
        {
            Inst zero;
            zero.op = Op::Store;
            zero.operands.push_back(constInt(0, 32, loc));
            zero.operands.push_back(statusSlot);
            zero.loc = loc;
            emit(std::move(zero));
        }

        const BlockId loadBlock = fn->addBlock("dyn.load");
        const BlockId contBlock = fn->addBlock("dyn.cont");
        const ValueId handleAddr = constFnInEntry(handleName, loc);
        branchIfNull(loadValue(handleAddr, ptr, loc), loadBlock, contBlock, loc);

        here_ = loadBlock;
        const ValueId opened =
            callExternal("polaron_bundle_load", ptr, {ptr, ptr, ptr},
                         {rawBytes(info.path, loc), escapedBytes(fingerprintText(info), loc),
                          convertWord(statusSlot, ptr, loc)},
                         loc);
        {
            Inst keep;
            keep.op = Op::Store;
            keep.operands.push_back(opened);
            keep.operands.push_back(constFnInEntry(handleName, loc));
            keep.loc = loc;
            emit(std::move(keep));
            Inst go;
            go.op = Op::Br;
            go.edges.push_back(Edge{contBlock, {}});
            go.loc = loc;
            emit(std::move(go));
        }

        here_ = contBlock;
        const ValueId handle = loadValue(constFnInEntry(handleName, loc), ptr, loc);
        const ValueId sym = callExternal("polaron_bundle_sym", ptr, {ptr, ptr},
                                         {handle, rawBytes(fn->key, loc)}, loc);
        const BlockId failBlock = fn->addBlock("dyn.fail");
        const BlockId callBlock = fn->addBlock("dyn.call");
        branchIfNull(sym, failBlock, callBlock, loc);

        // WHICH FAILURE IT WAS. Status 2 is "the container is there and its ABI is not ours", which
        // a program can act on -- rebuild the plug-in -- and everything else is "no bundle". Two
        // exceptions rather than one because the fixes are different.
        here_ = failBlock;
        const BlockId abiBlock = fn->addBlock("dyn.abi");
        const BlockId goneBlock = fn->addBlock("dyn.notloaded");
        {
            Inst cmp;
            cmp.op = Op::CmpEq;
            cmp.type = tt.boolType();
            cmp.operands.push_back(loadValue(statusSlot, i32, loc));
            cmp.operands.push_back(constInt(2, 32, loc));
            cmp.loc = loc;
            const ValueId isAbi = emit(std::move(cmp));
            Inst pick;
            pick.op = Op::BrCond;
            pick.operands.push_back(isAbi);
            pick.edges.push_back(Edge{abiBlock, {}});
            pick.edges.push_back(Edge{goneBlock, {}});
            pick.loc = loc;
            emit(std::move(pick));
        }
        here_ = abiBlock;
        raiseNamed("BundleAbiMismatchException", loc);
        here_ = goneBlock;
        raiseNamed("BundleNotLoadedException", loc);

        here_ = callBlock;
        Inst call;
        call.op = Op::CallIndirect;
        call.type = ret;
        call.operands.push_back(sym);
        for (const ValueId a : incoming) {
            call.operands.push_back(a);
        }
        call.loc = loc;
        const ValueId got = emit(std::move(call));
        Inst back;
        back.op = Op::Ret;
        if (ret != nullptr && ret->kind != TypeKind::Void && got != kNoValue) {
            back.operands.push_back(got);
        }
        back.loc = loc;
        emit(std::move(back));
        restoreBody(std::move(outer));
    }

    // The 32-byte ABI fingerprint, spelled so that the backend's `\xNN` reader gives back exactly
    // those bytes. It travels as a string constant rather than as a byte GLOBAL because a byte
    // global is laid out `[i64 length | bytes...]` -- the array shape every Polaron array has -- and
    // the loader wants the bytes, not a header in front of them.
    static std::string fingerprintText(const DynamicBundle& info) {
        static const char* const kHex = "0123456789abcdef";
        std::string out;
        for (const std::uint8_t b : info.fingerprint) {
            out += "\\x";
            out += kHex[b >> 4];
            out += kHex[b & 0xF];
        }
        return out;
    }

    // A pointer to bytes, not to a `String` object, from text whose escapes are ALREADY the ones
    // meant to be resolved -- the fingerprint's `\xNN`, and nothing else.
    ValueId escapedBytes(const std::string& text, SourceLocation loc) {
        Inst lit;
        lit.op = Op::ConstStr;
        lit.type = out_.module.types.ptrType();
        lit.text = text;
        lit.imm = 1;   // the bytes themselves, with no String header around them
        lit.loc = loc;
        return emit(std::move(lit));
    }

    // The same, from LITERAL text: every backslash is doubled first, because the backend resolves
    // escapes on the way out and a Windows path is full of them. `C:\Users\...` would otherwise
    // arrive with a tab where `\t` was never written, and lose `\U` entirely.
    ValueId rawBytes(const std::string& text, SourceLocation loc) {
        std::string escaped;
        for (const char c : text) {
            if (c == '\\') {
                escaped += '\\';
            }
            escaped += c;
        }
        return escapedBytes(escaped, loc);
    }

    ValueId loadValue(ValueId address, const Type* t, SourceLocation loc) {
        Inst in;
        in.op = Op::Load;
        in.type = t;
        in.operands.push_back(address);
        in.loc = loc;
        return emit(std::move(in));
    }

    void branchIfNull(ValueId v, BlockId whenNull, BlockId otherwise, SourceLocation loc) {
        Inst cmp;
        cmp.op = Op::CmpEq;
        cmp.type = out_.module.types.boolType();
        cmp.operands.push_back(v);
        cmp.operands.push_back(nullPointer(loc));
        cmp.loc = loc;
        const ValueId isNull = emit(std::move(cmp));
        Inst pick;
        pick.op = Op::BrCond;
        pick.operands.push_back(isNull);
        pick.edges.push_back(Edge{whenNull, {}});
        pick.edges.push_back(Edge{otherwise, {}});
        pick.loc = loc;
        emit(std::move(pick));
    }

    // `throw new <cls>()` where the class is one the prelude declares, built by hand because there
    // is no AST here to lower. Allocate, zero, run the constructor, raise. No unwind edge: a thunk
    // has no `try` of its own, so it propagates to whoever called the method.
    void raiseNamed(const std::string& cls, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const std::string key = resolveClassKey(cls);
        const Type* shape = named_.count(key) != 0 ? named_.at(key) : nullptr;
        if (shape == nullptr) {
            // A PROGRAM WHOSE PRELUDE HAS NO SUCH CLASS still needs a terminated block. Unreachable
            // is honest here: the branch that leads to it cannot be taken by a program that could
            // not name the exception either.
            Inst dead;
            dead.op = Op::Unreachable;
            dead.loc = loc;
            emit(std::move(dead));
            return;
        }
        const int64_t size = shape->facts.size > 0 ? static_cast<int64_t>(shape->facts.size) : 16;
        const ValueId obj = callExternal("__polaron_malloc", ptr, {tt.intType(64)},
                                         {constLong(size, loc)}, loc);
        callExternal("memset", ptr, {ptr, tt.intType(32), tt.intType(64)},
                     {obj, constInt(0, 32, loc), constLong(size, loc)}, loc);
        pointee_[obj] = shape;
        noteName(obj, key);
        if (const Function* ctor = resolveKey(key + "." + key)) {
            emitCall(ctor, {obj}, loc);
        }
        Inst raise;
        raise.op = Op::Raise;
        raise.operands.push_back(obj);
        raise.loc = loc;
        emit(std::move(raise));
    }

    void declareNamespace(const ast::Namespace& ns, const ast::Bundle& bundle) {
        // WHOSE CODE THIS IS, so a shared class name resolves to the one declared here.
        currentBundle_ = bundle.name;
        currentNamespace_ = ns.name;
        for (const ast::ConstDecl& k : ns.consts) {
            Global g;
            g.name = k.name;
            g.type = typeOf(k.type);
            g.linkage = k.visibility == "public" ? Linkage::Public : Linkage::Internal;
            g.isConst = true;
            g.zeroInit = true;
            // ...WITH ITS VALUE IN IT. A namespace const was declared and then zeroed, which is a
            // constant that is not the one the program wrote.
            if (auto folded = constInts_.find(k.name); folded != constInts_.end()) {
                g.initInt = folded->second;
                g.zeroInit = false;
            } else if (auto real = constDoubles_.find(k.name); real != constDoubles_.end()) {
                g.initFloat = real->second;
                g.zeroInit = false;
            }
            out_.module.globals.push_back(std::move(g));
        }
        // NAMESPACE-LEVEL `extern` DECLARATIONS. Missed entirely at first, and the symptom named
        // itself: `System.IO.Console.printf` linked against nothing, because the prelude declares
        // `printf` as an extern in the namespace rather than as a method on a class, and a walk
        // that only visits `ns.classes` never sees it.
        for (const ast::ExternDecl& x : ns.externs) {
            std::vector<Field> params;
            std::vector<Function::Param> plist;
            for (const ast::Param& p : x.params) {
                Field f;
                f.type = typeOf(p.type);
                params.push_back(f);
                plist.push_back({p.name, resolvedTypeName(p.type), passedByValue(p.type),
                                 pointerDepthOfType(p.type)});
            }
            if (out_.module.find(x.name) != nullptr) {
                continue;
            }
            Function* fn = out_.module.addFunction(
                x.name, out_.module.types.fnType(typeOf(x.returnType), std::move(params)));
            fn->params = std::move(plist);
            fn->linkage = Linkage::External;
            fn->conv = Conv::Cdecl;
            // The FOREIGN SYMBOL is the name itself: an `extern printf` binds `printf`, and the
            // backend must emit that rather than a Polaron key. §6's `symbol`.
            fn->symbol = x.name;
        }

    // A CATALOG IS AN INTERFACE FOR ENUMS (spec 12.3), and a value of one is a TAGGED ORDINAL:
        // the implementing enum's id in the high half, the constant's ordinal in the low half. That
        // is the only way one `Heavy` can be an `Ingot` on one line and a `Stone` on the next, and
        // it has to be recorded here because a catalog is neither a class nor an enum.
        for (const ast::CatalogDecl& cat : ns.catalogs) {
            catalogs_.insert(cat.name);
        }
        // `newtype Vector = int;` (§24) IS AN `int` WITH A DIFFERENT NAME -- a distinct entry over
        // the same representation, which is exactly what `TypeTable::newType` is for. Left
        // undeclared it fell through to "an unknown class" and became an opaque nominal struct, so
        // `fixed Vector TimerVector = cast<Vector>(32)` emitted a zeroed aggregate and every
        // interrupt vector in the program read 0. A plain `typealias` is the same shape without the
        // distinct identity, and both want the target's type here.
        for (const ast::TypeAliasDecl& a : ns.typeAliases) {
            // WHAT IT IS MADE OF, recorded whether or not the name is already interned. Every
            // question the lowering asks about a value's SIGN is asked of a primitive spelling, and
            // a newtype is not one -- so this is the only thing standing between `newtype Batch =
            // uint` and every shift, comparison, division and conversion in its program being
            // signed. Recorded before the `continue` below, because a name already interned still
            // needs its ground known. See `groundName`.
            newtypeGround_[a.name] = a.target.name;
            if (named_.count(a.name) != 0) {
                continue;
            }
            if (const Type* over = typeOf(a.target); over != nullptr) {
                named_[a.name] = a.isNewtype ? out_.module.types.newType(a.name, over) : over;
            }
        }
        for (const ast::EnumDecl& e : ns.enums) {
            declareEnum(e);
        }
        for (const ast::ClassDecl& c : ns.classes) {
            declareClass(c, bundle);
        }
    }

    // EVERY ENUM IN THE PROGRAM, BEFORE ANY SIGNATURE IS BUILT.
    //
    // A class is declared before the enums of its own namespace are, and a method's parameter type
    // is resolved AT DECLARATION -- so `constructor Peripheral(Role r)` asked what a `Role` is while
    // `enums_` was still empty, got "an unknown class", and took an opaque nominal struct. Every
    // call then passed `%Role undef`: pico brought up eight devices and reported every one of them
    // as `unclassified`, because the role each driver handed its base class never arrived.
    //
    // The same shape `indexClasses` exists for, and the same fix: the question "what names a type"
    // is answered before anything asks it.
    // DOES SOMETHING CALL `main`? A question about the TARGET, never about the program: a
    // `freestanding` program says nothing hands it an argv, which is a different claim, and running
    // the two together renames `main` to `kmain` for a freestanding program built for a hosted
    // machine -- leaving it with no entry point at all. A triple naming no OS has no C runtime, and
    // so does wasm outside WASI.
    bool targetHasCRuntime() const {
        const std::string& t = out_.module.triple;
        if (t.find("none") != std::string::npos) {
            return false;
        }
        if (t.rfind("wasm", 0) == 0 && t.find("wasi") == std::string::npos) {
            return false;
        }
        return true;
    }

    void indexEnums() {
        // ...AND THE TYPE ALIASES WITH THEM, for the same reason and with the same symptom one file
        // further away. `newtype Vector = int` was registered when its OWN namespace was declared,
        // so a class in a namespace declared earlier saw an unknown name: pico's `fixed Vector
        // TimerVector` became an opaque struct, `vector == Irq.TimerVector` compared an `i32` with
        // it, and the timer interrupt incremented nothing. The kernel printed `T:NO` and stopped
        // there -- a machine with no clock.
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::TypeAliasDecl& a : ns.typeAliases) {
                    if (named_.count(a.name) != 0) {
                        continue;
                    }
                    if (const Type* over = typeOf(a.target); over != nullptr) {
                        named_[a.name] =
                            a.isNewtype ? out_.module.types.newType(a.name, over) : over;
                    }
                }
            }
        }
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::EnumDecl& e : ns.enums) {
                    enums_[e.name] = &e;
                    for (size_t i = 0; i < e.constants.size(); ++i) {
                        enumOrdinal_[e.name + "." + e.constants[i]] = static_cast<int64_t>(i);
                    }
                    if (enumTypeId_.count(e.name) == 0) {
                        enumTypeId_[e.name] = static_cast<int64_t>(enumTypeId_.size());
                    }
                }
                for (const ast::CatalogDecl& c : ns.catalogs) {
                    catalogs_.insert(c.name);
                }
            }
        }
    }

    void declareEnum(const ast::EnumDecl& e) {
        // A `sealed enum` is a VARIANT with a closed case set, which is what makes `switch total`
        // checkable (verifier rule 18) -- the exhaustiveness of a `match` becomes a property of the
        // IR rather than of a check that ran earlier and left nothing behind.
        std::vector<Field> cases;
        for (const std::string& name : e.constants) {
            Field f;
            f.type = out_.module.types.intType(32);
            f.name = name;
            cases.push_back(f);
        }
        const Type* v = out_.module.types.variantType(e.name, std::move(cases));
        named_[e.name] = v;
        // THE ORDINALS, KEPT SEPARATELY. `named_` is one map for every kind of named type, and a
        // `ClassDecl` with the same name -- which is what an enum with methods becomes -- overwrote
        // this entry, so by the time a body was lowered `Color` was a struct and `Color.BLUE`
        // resolved as an external global that nothing initialises. Every enum constant read 0.
        for (size_t i = 0; i < e.constants.size(); ++i) {
            enumOrdinal_[e.name + "." + e.constants[i]] = static_cast<int64_t>(i);
        }
        // THE DECLARATION ITSELF, for the built-ins. `Color.count()` and `Color.values()` are not
        // methods anybody wrote -- they are questions about the constant list -- so answering them
        // needs the list, not the interned type, which has thrown the order away.
        enums_[e.name] = &e;
        // A STABLE ID PER ENUM, in declaration order, so a tagged catalog value can say which enum
        // it came from. Assigned once: the same enum declared twice would otherwise be two ids.
        if (enumTypeId_.count(e.name) == 0) {
            enumTypeId_[e.name] = static_cast<int64_t>(enumTypeId_.size());
        }
        for (const std::string& cat : e.extendsCatalogs) {
            catalogImplementers_[cat].push_back(e.name);
        }
        // AN ENUM CAN HAVE METHODS (spec 12.4). A java-style one's live on its twin class and take
        // a singleton; a catalog enum's take the ordinal, which IS the value.
        if (!e.isJavaStyle) {
            for (const ast::MemberPtr& member : e.members) {
                const auto* m = dynamic_cast<const ast::MethodDecl*>(member.get());
                if (m != nullptr && !m->isAbstract) {
                    declareMethodOn(e.name, out_.module.types.intType(32), *m);
                }
            }
        }
    }

    // The base's fields, in order, deepest ancestor first -- found by NAME, because a class can be
    // declared after the one that extends it and this walk does not get to choose the order. The
    // declaration is looked up rather than the interned type, since the base may not be interned
    // yet when this runs.
    void appendInheritedFields(const ast::ClassDecl& c, std::vector<Field>& into,
                               std::vector<Field>& persisted, const std::string& cls) {
        if (c.superclass.empty()) {
            return;
        }
        const ast::ClassDecl* base = findClass(c.superclass);
        if (base == nullptr || base == &c) {
            return;
        }
        appendInheritedFields(*base, into, persisted, cls);
        forEachMember<ast::FieldDecl>(*base, [&](const ast::FieldDecl& f) {
            // A STATIC IS NOT PART OF THE OBJECT and a `persistent` lives outside it -- both of
            // which the DECLARING class already worked out. Inheriting has to reach the same two
            // answers or the layouts disagree: a base holding a static grew a phantom member in
            // every subclass, and every field after it moved.
            if (f.isStatic) {
                return;
            }
            if (f.isPersistent) {
                persisted.push_back(pirField(f));
                persistOrder_[cls].push_back(f.name);
                return;
            }
            into.push_back(pirField(f));
        });
    }

    // THE SHAPE OF ONE FIELD, DECIDED IN ONE PLACE. It used to be decided in two, and the second
    // one -- the copy that runs when a SUBCLASS inherits a field -- knew none of the rules: that a
    // `boolean` field is four bytes of storage holding one bit, that a `weak T*` field is a
    // sixteen-byte list node, that `: 5` declares five bits. So `Peripheral.live` was four bytes
    // in `Peripheral` and one BIT in `Framebuffer`, and every field after it in the subclass sat
    // at an offset the base disagreed with. In a 66 000-line kernel that read as `this.base`
    // returning the neighbouring word, and the display filling from an address the card does not
    // decode.
    Field pirField(const ast::FieldDecl& f) {
        Field pf;
        pf.type = typeOf(f.type);
        pf.name = f.name;
        pf.weak = f.isWeak;
        // `int species : 5` DECLARES FIVE BITS, not four bytes. Carried on the field so the run
        // grouping in the class declaration can find it -- the shape is decided after every field
        // is known, because a run is a property of the SEQUENCE, not of any one member of it.
        pf.bitWidth = static_cast<uint32_t>(f.bitWidth);
        // A FIELD IS STORAGE, so its type is the STORAGE type: a `boolean` field is four bytes
        // holding one bit, not one bit. See `storageTypeOf`.
        if (f.type.pointerDepth == 0 && !f.type.isNullable && !f.type.isArray &&
            f.type.name == "boolean") {
            pf.type = out_.module.types.intType(32);
        }
        // A `weak T*` FIELD IS A LIST NODE, not a pointer: two words, `{target, next}`, chained
        // off the target's own head. The node lives IN the field, which is what makes a weak
        // reference cost no allocation -- and what makes its size sixteen and not eight.
        if (f.isWeak) {
            pf.type = weakSlotType();
        }
        // A NARROW `A*` FIELD HOLDS A 32-BIT OFFSET INTO A's ARENA. §region: a `region class` puts
        // every instance in one reservation, so a pointer between two of them is an offset from a
        // base both already know -- and half the width. The win is entirely about how much of a
        // structure fits in a cache line, which is why it applies to FIELDS and to nothing else: a
        // local or an argument lives in a register, where 32 bits buy nothing and the widening
        // would be pure cost.
        //
        // Weak wins where both apply, and a bit field wins too: each already decides its own
        // storage shape, and two rewrites of one field would fight.
        else if (pf.bitWidth == 0 && !narrowTargetOf(f.type).empty()) {
            pf.type = out_.module.types.intType(32);
        }
        return pf;
    }

    // The region class a field's declared type points at, or "" when the field is an ordinary
    // pointer. Exactly `A*` -- one level of pointer, no array, no reference -- because anything else
    // is either not a single object or not addressed from the arena's base.
    //
    // The name that comes back is the class's own KEY, not the type as written: a tree's children
    // are `nullable Node*`, and answering "nullable Node" would look up an arena global of that
    // name -- a second, empty reservation that no `new Node()` ever allocated from, so every child
    // read back as an offset into the wrong base. The other backend has a comment saying exactly
    // this, having made the mistake first.
    std::string narrowTargetOf(const ast::TypeRef& t) const {
        if (t.pointerDepth != 1 || t.isArray || t.isRef) {
            return {};
        }
        return narrowTargetNamed(t.name);
    }

    std::string narrowTargetNamed(const std::string& declared) const {
        const std::string key = resolveClassKey(classNameOf(declared));
        const ast::ClassDecl* decl = findClass(key);
        if (decl == nullptr || !decl->isRegionClass) {
            return {};
        }
        // An interface- or abstract-typed reference can point into a DIFFERENT family's arena, and
        // an offset is only meaningful against one base. Those keep their sixty-four bits.
        if (decl->isInterface || decl->isAbstract) {
            return {};
        }
        return key;
    }

    // Read one: `off == 0 ? null : arenaBase + off`. Offset zero is null, which is why the arena
    // never hands out offset zero.
    ValueId narrowLoad(ValueId addr, const std::string& target, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        Inst ld;
        ld.op = Op::Load;
        ld.type = tt.intType(32);
        ld.operands.push_back(addr);
        ld.loc = loc;
        const ValueId off = emit(std::move(ld));
        const ValueId arena = classArena(target, loc);
        const ValueId base =
            callExternal("__polaron_arena_base", tt.ptrType(), {tt.ptrType()}, {arena}, loc);
        const ValueId wide = rawOffset(base, off, loc);
        Inst pick;
        pick.op = Op::Select;
        pick.type = tt.ptrType();
        pick.operands.push_back(cmp(Op::CmpEq, off, constInt(0, 32, loc), loc));
        pick.operands.push_back(nullPointer(loc));
        pick.operands.push_back(wide);
        pick.loc = loc;
        const ValueId got = emit(std::move(pick));
        noteName(got, target, 1);
        if (named_.count(target) != 0) {
            pointee_[got] = named_.at(target);
        }
        return got;
    }

    // Write one: `p == null ? 0 : (u32)(p - arenaBase)`. Letting a plain store run instead would
    // write eight bytes into a four-byte slot and take the next field with it.
    void narrowStore(ValueId addr, ValueId value, const std::string& target, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const ValueId arena = classArena(target, loc);
        const ValueId base =
            callExternal("__polaron_arena_base", tt.ptrType(), {tt.ptrType()}, {arena}, loc);
        Inst asAddr;
        asAddr.op = Op::PtrToAddr;
        asAddr.type = tt.addrType(64);
        asAddr.operands.push_back(value);
        asAddr.loc = loc;
        const ValueId at = emit(std::move(asAddr));
        Inst baseAddr;
        baseAddr.op = Op::PtrToAddr;
        baseAddr.type = tt.addrType(64);
        baseAddr.operands.push_back(base);
        baseAddr.loc = loc;
        const ValueId from = emit(std::move(baseAddr));
        Inst diff;
        diff.op = Op::SubWrap;
        diff.type = tt.addrType(64);
        diff.operands.push_back(at);
        diff.operands.push_back(from);
        diff.loc = loc;
        Inst narrow;
        narrow.op = Op::Trunc;
        narrow.type = tt.intType(32);
        narrow.operands.push_back(emit(std::move(diff)));
        narrow.loc = loc;
        const ValueId off = emit(std::move(narrow));
        Inst pick;
        pick.op = Op::Select;
        pick.type = tt.intType(32);
        pick.operands.push_back(cmp(Op::CmpEq, value, nullPointer(loc), loc));
        pick.operands.push_back(constInt(0, 32, loc));
        pick.operands.push_back(off);
        pick.loc = loc;
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(emit(std::move(pick)));
        put.operands.push_back(addr);
        put.loc = loc;
        emit(std::move(put));
    }

    std::string superclassName() const {
        if (selfClassName_.empty()) {
            return {};
        }
        const ast::ClassDecl* here = findClass(selfClassName_);
        return here != nullptr ? here->superclass : std::string();
    }

    const ast::ClassDecl* findClass(const std::string& name) const {
        auto found = classesByKey_.find(name);
        if (found != classesByKey_.end()) {
            return found->second.decl;
        }
        found = classesByKey_.find(resolveClassKey(name));
        return found != classesByKey_.end() ? found->second.decl : nullptr;
    }

    // EVERY CLASS IN THE PROGRAM, BY ITS KEY -- built once, before anything is declared.
    //
    // A name declared ONCE is its own key. A name declared TWICE is keyed by path for BOTH of
    // them, so neither can silently answer for the other. This is the shape the trusted path
    // settled on, and for the reason its own comment gives: letting the first declaration keep the
    // bare name is one rule with two cases, and every later pass has to know which case it is in.
    //
    // Before this, `named_` kept whichever class was declared LAST and `findClass` returned
    // whichever came FIRST -- so the two could disagree about the same name. A program with its own
    // `Matrix` beside the standard library's read `this.n` at the offset of the OTHER `Matrix`'s
    // first field, which is the vtable pointer: `matmul_class_interchange` multiplied matrices of
    // size "whatever a function address truncates to".
    // ---- `weak T*` (§19): a non-owning edge that NULLS ITSELF when its target dies ----
    //
    // The mechanism is an intrusive singly-linked list and no allocation: a `weak T*` field IS a
    // two-word node `{ptr target, ptr next}`, and every such node pointing at one object is chained
    // off a LIST HEAD carried by that object. Deleting the object walks its list and nulls each
    // node, which is how `w.target == null` becomes true the moment `n` is deleted without anyone
    // holding a reference count.
    //
    // WHICH CLASSES CARRY A HEAD is the whole subtlety. `weak_link` computes the head's offset from
    // the field's STATIC type, so a `weak Base*` holding a `Derived` must find the head where
    // `Base` says it is -- which means every class in a family agrees, and the mark spreads both
    // ways along the super/interface relation. The head then sits right behind the vtable, at 8 for
    // everybody, rather than after the fields where it would land somewhere different in each.
    void collectWeakTargets() {
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    forEachMember<ast::FieldDecl>(c, [&](const ast::FieldDecl& f) {
                        if (f.isWeak) {
                            weakTargets_.insert(classNameOf(resolvedTypeName(f.type)));
                        }
                    });
                }
            }
        }
        if (weakTargets_.empty()) {
            return;
        }
        // The connected component of the super/sub and interface/implementer relation: a marked
        // class marks what it is built on, and everything built on a marked class is marked.
        for (bool grew = true; grew;) {
            grew = false;
            for (const ast::Bundle& b : ast_.bundles) {
                for (const ast::Namespace& ns : b.namespaces) {
                    for (const ast::ClassDecl& c : ns.classes) {
                        std::vector<std::string> kin;
                        if (!c.superclass.empty()) {
                            kin.push_back(classNameOf(c.superclass));
                        }
                        for (const std::string& i : c.interfaces) {
                            kin.push_back(classNameOf(i));
                        }
                        const bool self = weakTargets_.count(c.name) != 0;
                        for (const std::string& k : kin) {
                            if (self && weakTargets_.count(k) == 0 && findClass(k) != nullptr) {
                                weakTargets_.insert(k);
                                grew = true;
                            } else if (!self && weakTargets_.count(k) != 0) {
                                weakTargets_.insert(c.name);
                                grew = true;
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    bool carriesWeakHead(const std::string& cls) const {
        if (weakTargets_.empty()) {
            return false;
        }
        const ast::ClassDecl* decl = findClass(cls);
        if (decl == nullptr || decl->isStruct || decl->isRecord || decl->isUnion ||
            decl->isLayout || decl->isTransformer || decl->isInterface) {
            return false;   // no vtable, so nothing can point weakly at one anyway
        }
        return weakTargets_.count(decl->name) != 0;
    }

    // `{ptr target, ptr next}` -- the node a weak field IS. One entry in the table, so every field
    // of every class that declares one is the same type and the same 16 bytes.
    const Type* weakSlotType() {
        std::vector<Field> parts(2);
        parts[0].type = out_.module.types.ptrType();
        parts[0].name = "target";
        parts[1].type = out_.module.types.ptrType();
        parts[1].name = "next";
        return out_.module.types.structType("WeakSlot", std::move(parts), true);
    }

    void indexClasses() {
        std::unordered_map<std::string, int> declaredTimes;
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    ++declaredTimes[c.name];
                }
            }
        }
        for (const auto& [name, times] : declaredTimes) {
            if (times > 1) {
                sharedNames_.insert(name);
            }
        }
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    const std::string key = classKey(b.name, ns.name, c.name);
                    classesByKey_.emplace(key, ClassEntry{&c, b.name, ns.name, b.isPrelude});
                    // The FIRST declared one, recorded in source order. Deterministic on purpose:
                    // a fallback that has to pick must pick the same thing every time, or the bug
                    // it creates is one nobody can reproduce.
                    firstOwner_.emplace(c.name, key);
                    // WHICH MEMBER NAMES COULD NAME AN INTERRUPT HANDLER. Collected here so that
                    // reading an ORDINARY member never has to evaluate its object to find out --
                    // see `interruptEntryPoint`, which used to answer that question the expensive
                    // way and cost every member read in the program a second evaluation.
                    forEachMember<ast::MethodDecl>(c, [&](const ast::MethodDecl& mm) {
                        if (mm.isInterrupt) {
                            interruptNames_.insert(mm.name);
                        }
                    });
                }
            }
        }
    }

    std::string classKey(const std::string& bundle, const std::string& ns,
                         const std::string& name) const {
        return sharedNames_.count(name) == 0 ? name : bundle + "." + ns + "." + name;
    }

    // A TYPE AS WRITTEN, AND AS KEYED. Every table this pass keeps -- the interned types, the field
    // types, the return types, the parameter types -- is looked up by the recorded name, so the
    // recorded name has to be the KEY. Recording the bare one worked until two classes answered to
    // it, and then `this.tool.seen` looked up a class called `Scanner` that the module does not
    // have under that name: no owner, no field index, and the read fell back to offset zero.
    // HOW MANY STARS, from the declaration. Two spellings reach the same place -- `Node* p` sets
    // `pointerDepth`, a bare `T*` in some positions sets only `isPointer` -- and reading one of
    // them is how a pointer parameter ended up looking like a value.
    // AND A REFERENCE IS ONE OF THEM, which is the third spelling and was the one missing. `Param`
    // says it in its own comment -- "`f(Box& b)` and `f(Box* b)` reach the caller's. Every one of
    // them is a pointer in the IR" -- and this function, which is where that fact is turned into a
    // number, read `pointerDepth` and `isPointer` and never asked about `isRef`. So a `T&` arrived
    // at depth zero, indistinguishable from a value, and assignment DEEP-COPIED it: exactly the
    // defect the comment above describes for `Node*`, in the spelling nobody had written yet.
    //
    // Found by the standard library's own cursor. `ArrayListIterator` held its list BY VALUE until
    // it was made a borrow, so no program in the corpus had a reference field for this to be wrong
    // about; the moment one did, a `foreach` through PIR walked a COPY of the collection and printed
    // the list as it stood when the cursor was made -- `seen 3 total 6` where the trusted path says
    // `seen 4 total 108`. The two backends disagreeing is what caught it, which is what the
    // differential is for.
    static uint8_t pointerDepthOfType(const ast::TypeRef& t) {
        if (t.pointerDepth > 0) {
            return static_cast<uint8_t>(t.pointerDepth);
        }
        return (t.isPointer || t.isRef) ? 1 : 0;
    }

    // WHAT A DECLARATION SAYS, as the two facts a value carries: the class, and how many stars.
    //
    // Those two come apart when a GENERIC IS INSTANTIATED. Substituting `T` = `FileNode*` puts the
    // star inside the NAME -- `ArrayList<FileNode*>.get` returns something spelled `FileNode*` with
    // a pointer depth of zero -- and `classNameOf` strips no stars, deliberately: a `*` left in a
    // name usually belongs to a mangled type ARGUMENT (`ArrayList$Row*` is `ArrayList<Row*>`, and
    // removing that star names a different instantiation). So `findClass("FileNode*")` found
    // nothing, the receiver arrived with no class at all, and `troot.children.get(0).children`
    // read the FileNode's first four bytes as though they were the field -- then called `.size()`
    // on them, which resolved by bare name to `Queue$int.size`.
    //
    // The `$` is what tells the two cases apart: a mangled name keeps its stars, a plain one moves
    // them to the depth, where every reader already looks for them.
    static DeclaredType declaredTypeOf(std::string name, uint8_t depth) {
        if (name.find('$') == std::string::npos) {
            while (!name.empty() && name.back() == '*') {
                name.pop_back();
                ++depth;
            }
        }
        return DeclaredType{std::move(name), depth};
    }

    std::string resolvedTypeName(const ast::TypeRef& t) const {
        ast::TypeRef bare = t;
        bare.pointerDepth = 0;
        bare.isPointer = false;
        bare.isRef = false;
        return resolveClassKey(ast::canonicalType(bare));
    }

    // The key of THIS declaration, whichever of the classes sharing its name it happens to be.
    // Found by identity rather than by name, because the name is exactly what is ambiguous.
    std::string keyOfClass(const ast::ClassDecl& c) const {
        if (sharedNames_.count(c.name) == 0) {
            return c.name;
        }
        for (const auto& [key, entry] : classesByKey_) {
            if (entry.decl == &c) {
                return key;
            }
        }
        return c.name;
    }

    // WHICH OF THEM A NAME MEANS, HERE. Composing the path of whoever is asking -- there is no
    // "unless it was declared first" branch for a later pass to get wrong.
    std::string resolveClassKey(const std::string& name) const {
        if (sharedNames_.empty() || sharedNames_.count(name) == 0) {
            return name;   // the ordinary case: one type, one key, no work at all
        }
        if (const std::string here = currentBundle_ + "." + currentNamespace_ + "." + name;
            classesByKey_.count(here) != 0) {
            return here;
        }
        auto first = firstOwner_.find(name);
        return first != firstOwner_.end() ? first->second : name;
    }

    // ---- virtual dispatch ----
    //
    // ONE SLOT NUMBER PER METHOD NAME, shared by every class in the program. That is what makes a
    // base's slot and an override's slot the same number without either having to know about the
    // other, and it is the same scheme the trusted path uses (its tables are 556 entries because
    // that is how many distinct method names a program plus its prelude has).
    //
    // Without any of this, a call to a method with no body -- an interface method, an abstract one
    // -- was emitted as a DIRECT call to a symbol nothing defines, and the program failed to link
    // naming `Greeter.name`. Worse than the link error is what it says about the ones that DID
    // link: an override could not win, because the call never asked the object what it was.
    int64_t slotFor(const std::string& method) {
        auto it = vtableSlot_.find(method);
        if (it != vtableSlot_.end()) {
            return it->second;
        }
        const int64_t n = static_cast<int64_t>(vtableSlot_.size());
        vtableSlot_.emplace(method, n);
        return n;
    }

    // Which body answers `method` for `c`: its own if it has one, otherwise its base's, all the way
    // up. An interface's default counts as a body, which is the whole point of a default.
    std::string implementationOf(const ast::ClassDecl& c, const std::string& method) const {
        bool has = false;
        forEachMember<ast::MethodDecl>(c, [&](const ast::MethodDecl& m) {
            if (m.name == method && !m.isAbstract && !m.isExtern) {
                has = true;
            }
        });
        if (has) {
            return keyOfClass(c) + "." + method;
        }
        // THE SUPERCLASS FIRST, THEN THE INTERFACES -- and the interfaces UNCONDITIONALLY, which is
        // the part that was wrong: this only looked at them when there was no superclass, and every
        // class has one (`Object`), so an interface's DEFAULT body was never found. `Alice
        // implements Greeter` got a table with no `greet` slot at all, and the dispatch for it read
        // past the end of that table into whatever followed.
        if (const ast::ClassDecl* up = c.superclass.empty() ? nullptr : findClass(c.superclass)) {
            if (std::string got = implementationOf(*up, method); !got.empty()) {
                return got;
            }
        }
        for (const std::string& i : c.interfaces) {
            if (const ast::ClassDecl* iface = findClass(i); iface != nullptr) {
                if (std::string got = implementationOf(*iface, method); !got.empty()) {
                    return got;
                }
            }
        }
        return {};
    }

    // Every method name reachable on `c` -- its own, its bases', and its interfaces'.
    void collectMethodNames(const ast::ClassDecl& c, std::vector<std::string>& into) const {
        forEachMember<ast::MethodDecl>(c, [&](const ast::MethodDecl& m) {
            if (std::find(into.begin(), into.end(), m.name) == into.end()) {
                into.push_back(m.name);
            }
        });
        if (const ast::ClassDecl* up = c.superclass.empty() ? nullptr : findClass(c.superclass)) {
            collectMethodNames(*up, into);
        }
        for (const std::string& i : c.interfaces) {
            if (const ast::ClassDecl* iface = findClass(i); iface != nullptr) {
                collectMethodNames(*iface, into);
            }
        }
    }

    // Does a call on a receiver of class `cls` have to ask the object which body to run?
    //
    // Yes when the class itself provides no body -- an interface method or an abstract one, which
    // is also the case that cannot be linked any other way -- and yes when some class BELOW it
    // overrides the method, because then the static class is not the answer. Anything else is a
    // single implementation and a direct call, which is what lets the optimiser inline it.
    // Whether this class, or one it is built on, declares `method` as an `extern` -- a name whose
    // body lives outside the class. See `needsDispatch`.
    bool declaresExtern(const ast::ClassDecl& c, const std::string& method) const {
        for (const ast::ClassDecl* at = &c; at != nullptr;) {
            for (const ast::MemberPtr& m : at->members) {
                const auto* md = dynamic_cast<const ast::MethodDecl*>(m.get());
                if (md != nullptr && md->name == method) {
                    return md->isExtern;
                }
            }
            const std::string up = cgutil::baseType(at->superclass);
            at = up.empty() ? nullptr : findClass(up);
        }
        return false;
    }

    // CAN A CONSUMER THAT DOES NOT EXIST YET OVERRIDE THIS? Only ever true under `--lib`, and it is
    // the one question closed-world reasoning cannot answer.
    //
    // Devirtualization -- "nothing below this class overrides the method, so call it directly" --
    // reads the whole program to prove there is a single implementation. For a PROGRAM the whole
    // program really is in front of it. For a BUNDLE it is not: the consumer is compiled later, from
    // sources this compilation never sees, and it may extend any public class here and override any
    // method it can reach. Proving "no override" over the library alone proves nothing about it.
    //
    // What that cost was `bundle_inherit_runs` printing `total = 17` where the program prints 57.
    // `Widget.total` is compiled HERE and calls `this.weight()`; nothing in the library overrides
    // `weight`, so the call went straight to `Widget.weight` and returned 1. The consumer's
    // `Button.weight` -- the override, returning 5 -- was never reachable from the library's own
    // code, and 1*10+7 is exactly the 17 that printed. `weight` and `label`, called from the
    // CONSUMER's side where the world is closed again, were both right: only the call compiled on
    // the library side of the boundary was wrong, which is why the number was wrong and nothing
    // crashed.
    //
    // `carriesVtable` already asks this question for the LAYOUT (a public class gets a vtable
    // pointer even if this compilation never dispatches on it). The layout answer without this one
    // is the worst of the three states: the table exists, `buildVtable` leaves the slot empty
    // because nothing "dispatches" the method, and the call is direct anyway.
    bool overridableFromOutside(const ast::ClassDecl& c, const std::string& method) const {
        if (!bundles_.library || c.visibility != "public" || c.isFinal || c.isSealed) {
            return false;
        }
        // The method has to be reachable from a subclass AND replaceable by one. `private` is not
        // inherited, `static` is not dispatched at all, and `final` is the author saying outright
        // that this one may not be overridden -- which is a promise the compiler may rely on.
        for (const ast::ClassDecl* at = &c; at != nullptr;) {
            for (const ast::MemberPtr& m : at->members) {
                const auto* md = dynamic_cast<const ast::MethodDecl*>(m.get());
                if (md == nullptr || md->name != method) {
                    continue;
                }
                return !md->isStatic && !md->isFinal && !md->isExtern && md->visibility != "private";
            }
            const std::string up = cgutil::baseType(at->superclass);
            at = up.empty() ? nullptr : findClass(up);
        }
        return false;
    }

    bool needsDispatch(const std::string& cls, const std::string& method) {
        const ast::ClassDecl* here = findClass(cls);
        if (here == nullptr || here->isStruct || here->isRecord || here->isUnion) {
            return false;
        }
        if (overridableFromOutside(*here, method)) {
            return true;
        }
        // A METHOD THAT CAN BE REPLACED MUST BE DISPATCHED (§32.8). `Dog.methods.replace("bark",
        // ...)` points a dispatch slot at the replacement, and a method nothing overrides has no
        // slot -- it is called directly, which is right for every other method and leaves this one
        // with nowhere for the patch to take effect. Worse than nowhere: the write went to slot
        // zero, which belongs to something else.
        if (replaceable_.count(method) != 0) {
            return true;
        }
        // AN `extern` METHOD IS A SYMBOL, NOT A SLOT. It has no body in this class because its body
        // is somewhere else entirely -- a foreign function, or, for a generator, the state machine
        // the earlier pass split out of it. There is nothing to put in a table and nothing to
        // override, so the call goes straight to the name.
        //
        // Read as "nothing here answers it: only the object knows" it became a virtual dispatch on
        // a slot `buildVtable` had deliberately not filled -- and once every table was padded to the
        // same width, that slot was a legitimate, null entry. `Sequences$evens$Gen.pump` called
        // `*0x2360(%rax)` and jumped to zero: `generator` printed nothing at all.
        if (declaresExtern(*here, method)) {
            return false;
        }
        if (implementationOf(*here, method).empty()) {
            return true;   // nothing here answers it: only the object knows
        }
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& k : ns.classes) {
                    if (&k == here || !descendsFrom(k, cls)) {
                        continue;
                    }
                    bool overrides = false;
                    forEachMember<ast::MethodDecl>(k, [&](const ast::MethodDecl& m) {
                        if (m.name == method && !m.isAbstract && !m.isExtern) {
                            overrides = true;
                        }
                    });
                    if (overrides) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    // Whether ANYTHING a `cls`-typed value could really be has a destructor: the class itself, an
    // ancestor, or any class that extends it. A `delete` through a base pointer has to dispatch
    // whenever the answer is yes, because which one it is, is the object's to say.
    bool hierarchyHasDestructor(const std::string& cls) {
        const ast::ClassDecl* here = findClass(cls);
        if (here != nullptr && !destructorOf(*here).empty()) {
            return true;
        }
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& k : ns.classes) {
                    if (descendsFrom(k, cls) && !destructorOf(k).empty()) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    bool descendsFrom(const ast::ClassDecl& k, const std::string& base) const {
        for (const ast::ClassDecl* at = &k; at != nullptr;) {
            if (at->superclass == base) {
                return true;
            }
            if (std::find(at->interfaces.begin(), at->interfaces.end(), base) !=
                at->interfaces.end()) {
                return true;
            }
            at = at->superclass.empty() ? nullptr : findClass(at->superclass);
        }
        return false;
    }

    // The store the synthesized constructor could not emit when it was made: `const.fn @X.vtable`,
    // a `gep` to field zero, a `store`. Written straight into the entry block, ahead of its `ret`.
    BodyState saveBody() {
        BodyState kept;
        kept.fn = fn_;
        kept.here = here_;
        kept.entry = entryBlock_;
        kept.allocaAt = allocaAt_;
        kept.self = selfSlot_;
        kept.selfClass = selfClass_;
        kept.selfClassName = selfClassName_;
        kept.locals = std::move(locals_);
        kept.slotTypes = std::move(slotType_);
        kept.pointee = std::move(pointee_);
        kept.pointeeOfSlot = std::move(pointeeOfSlot_);
        kept.packedAt = std::move(packedAt_);
        kept.narrowAt = std::move(narrowAt_);
        kept.weakSlotAt = std::move(weakSlotAt_);
        kept.cCallable = std::move(cCallable_);
        kept.labels = std::move(labels_);
        kept.loops = std::move(loops_);
        kept.deferred = std::move(deferred_);
        kept.scoped = std::move(scoped_);
        kept.unwindObjects = std::move(unwindObjects_);
        kept.unwindDefers = std::move(unwindDefers_);
        kept.declaredAs = std::move(declaredAs_);
        kept.storage = std::move(storage_);
        kept.stringTemps = std::move(stringTemps_);
        kept.stringSlots = std::move(stringSlots_);
        stringTemps_.clear();   // a nested body's strings are its own
        stringSlots_.clear();
        kept.statics = std::move(statics_);
        kept.handlers = std::move(handlers_);
        kept.yields = std::move(yields_);
        kept.paramTypes = std::move(paramTypes_);
        return kept;
    }

    void restoreBody(BodyState&& kept) {
        fn_ = kept.fn;
        here_ = kept.here;
        entryBlock_ = kept.entry;
        allocaAt_ = kept.allocaAt;
        selfSlot_ = kept.self;
        selfClass_ = kept.selfClass;
        selfClassName_ = std::move(kept.selfClassName);
        locals_ = std::move(kept.locals);
        slotType_ = std::move(kept.slotTypes);
        pointee_ = std::move(kept.pointee);
        pointeeOfSlot_ = std::move(kept.pointeeOfSlot);
        packedAt_ = std::move(kept.packedAt);
        narrowAt_ = std::move(kept.narrowAt);
        weakSlotAt_ = std::move(kept.weakSlotAt);
        cCallable_ = std::move(kept.cCallable);
        labels_ = std::move(kept.labels);
        loops_ = std::move(kept.loops);
        deferred_ = std::move(kept.deferred);
        scoped_ = std::move(kept.scoped);
        unwindObjects_ = std::move(kept.unwindObjects);
        unwindDefers_ = std::move(kept.unwindDefers);
        declaredAs_ = std::move(kept.declaredAs);
        storage_ = std::move(kept.storage);
        stringTemps_ = std::move(kept.stringTemps);
        stringSlots_ = std::move(kept.stringSlots);
        statics_ = std::move(kept.statics);
        handlers_ = std::move(kept.handlers);
        yields_ = std::move(kept.yields);
        paramTypes_ = std::move(kept.paramTypes);
    }

    // Whether a statement is the `super(...)` that opens a constructor. `super` is its own AST node
    // rather than an identifier that happens to spell it, so matching on the name finds nothing.
    static bool beginsWithSuperCall(const ast::Stmt* s) {
        const auto* expr = dynamic_cast<const ast::ExprStmt*>(s);
        if (expr == nullptr) {
            return false;
        }
        const auto* call = dynamic_cast<const ast::CallExpr*>(expr->expr.get());
        return call != nullptr &&
               dynamic_cast<const ast::SuperExpr*>(call->callee.get()) != nullptr;
    }

    // THE DEFAULTS A CLASS STATES AT ITS FIELDS, written into the object. Inherited ones first, so
    // a subclass's own initialiser wins over a base's for a field it re-states -- the same order
    // the fields themselves are laid out in.
    void applyFieldInitialisers(const std::string& owner) {
        const ast::ClassDecl* decl = findClass(owner);
        if (decl == nullptr || selfSlot_ == kNoValue) {
            return;
        }
        forEachMember<ast::FieldDecl>(*decl, [&](const ast::FieldDecl& f) {
            if (f.init == nullptr || f.isStatic) {
                return;   // a static has one storage location and is initialised as a global
            }
            // A `lazy` FIELD IS BUILT ON FIRST ACCESS, NOT HERE (§28.4). Its storage starts null --
            // which is the sentinel -- and the initialiser runs at the first read. Run in the
            // constructor it printed `constructing` before the line that follows the declaration,
            // which is exactly the ordering the word exists to change.
            if (f.isLazy) {
                lazyFieldInit_[owner + "." + f.name] = f.init.get();
                if (const ValueId at = fieldAddress(selfLoad(f.loc), f.name, f.loc);
                    at != kNoValue) {
                    const Type* held = slotType_.count(at) != 0 ? slotType_[at] : nullptr;
                    Inst blank;
                    blank.op = Op::Store;
                    blank.operands.push_back(held != nullptr && held->kind == TypeKind::Ptr
                                                 ? nullPointer(held, f.loc)
                                                 : constInt(0, 64, f.loc));
                    blank.operands.push_back(at);
                    blank.loc = f.loc;
                    emit(std::move(blank));
                }
                return;
            }
            // A `persistent` FIELD'S INITIALISER IS ITS STARTING VALUE, NOT ITS EVERY-TIME VALUE
            // (§18.2). Reattaching is the point: running `chassi = 0` in the constructor of every
            // `Car` puts the counter back to zero on each one, which is exactly what the object
            // being deleted and rebuilt is supposed to survive. The block is zeroed once when it
            // is created, and that IS the initialiser being honoured.
            if (f.isPersistent || f.isEternal) {
                return;
            }
            const ValueId value = lowerExpr(f.init.get());
            if (value == kNoValue) {
                return;
            }
            const ValueId at = fieldAddress(selfLoad(f.loc), f.name, f.loc);
            if (at != kNoValue) {
                storeInto(at, value, f.loc);
            }
        });
    }

    // A DEFAULT CONSTRUCTOR IS AN ORDINARY CONSTRUCTOR WITH AN EMPTY BODY. Lowered through the
    // same path as every other one, so it writes the vtable pointer and applies the class's inline
    // field initialisers without either being a second implementation that can drift.
    void lowerSynthesizedConstructor(const ast::ClassDecl& c) {
        const std::string cls = keyOfClass(c);
        if (std::find(synthesized_.begin(), synthesized_.end(), cls) == synthesized_.end()) {
            return;
        }
        Function* fn = out_.module.find(cls + "." + cls);
        if (fn == nullptr || !fn->blocks.empty()) {
            return;
        }
        const ast::Block empty;
        lowerBodyOf(*fn, cls, empty);
    }

    // ...AND SO IS A SYNTHESISED DESTRUCTOR. A COUNTED CLASS NEEDS ONE WHETHER IT WROTE ONE OR NOT,
    // because the destructor is the only place its live-instance count comes down -- and a region
    // class whose count only ever climbs refuses every `release region` of its own arena, which is
    // what `region_class_release` printed: the panic, on a program that had deleted both nodes.
    void lowerSynthesizedDestructor(const ast::ClassDecl& c) {
        const std::string cls = keyOfClass(c);
        if (std::find(synthesizedDtors_.begin(), synthesizedDtors_.end(), cls) ==
            synthesizedDtors_.end()) {
            return;
        }
        Function* fn = out_.module.find(cls + ".~" + cls);
        if (fn == nullptr || !fn->blocks.empty()) {
            return;
        }
        const ast::Block empty;
        lowerBodyOf(*fn, cls, empty);
    }

    // A SLOT IS NEEDED WHEREVER THE CALL COULD BE WRITTEN, not only where the override is. A call
    // through an `Animal*` dispatches slot k; the object might be a `Dog`, so `Dog`'s table needs
    // slot k too -- even though nothing overrides `Dog.sound` and a call written on a `Dog` would
    // be direct. Asking only about the class itself gave `Dog` a table with no `sound` in it, and
    // the dispatch read past the end.
    bool dispatchedAnywhereAbove(const ast::ClassDecl& c, const std::string& method) {
        if (needsDispatch(c.name, method)) {
            return true;
        }
        if (const ast::ClassDecl* up = c.superclass.empty() ? nullptr : findClass(c.superclass)) {
            if (dispatchedAnywhereAbove(*up, method)) {
                return true;
            }
        }
        for (const std::string& i : c.interfaces) {
            if (const ast::ClassDecl* iface = findClass(i); iface != nullptr) {
                if (dispatchedAnywhereAbove(*iface, method)) {
                    return true;
                }
            }
        }
        return false;
    }

    // The destructor that answers for `c`: its own if it declares one, otherwise its base's.
    std::string destructorOf(const ast::ClassDecl& c) const {
        bool has = false;
        forEachMember<ast::DestructorDecl>(c, [&](const ast::DestructorDecl&) { has = true; });
        // ...OR THE ONE IT WAS GIVEN. A counted class has a destructor whether it wrote one or not,
        // and reporting only the declared ones sent `delete leaf` up to the base class's -- so
        // `Leaf`'s own count never came down and `release region Node` refused an arena whose every
        // object had been deleted.
        if (has || countsInstances(c)) {
            const std::string cls = keyOfClass(c);
            return cls + ".~" + cls;
        }
        if (const ast::ClassDecl* up = c.superclass.empty() ? nullptr : findClass(c.superclass)) {
            return destructorOf(*up);
        }
        return {};
    }

    // EVERY TABLE IS THE SAME LENGTH, because the slot numbering is global and a dispatch reads a
    // fixed index. A table sized only to the slots ITS class fills is shorter than some other
    // class's, and a call through that index reads whatever the linker laid down next -- which is
    // how a `greet()` on one object returned another object's `name`.
    //
    // AND IT HAS TO RUN AGAIN AFTER THE BODIES. `slotFor` hands out a number the first time a method
    // name is dispatched, and a CALL SITE can be the first mention of one -- so the numbering keeps
    // growing while bodies are lowered, past the width the tables were padded to before any body
    // existed. `generator` ended with 1130-entry tables and a `call *0x2360(%rax)`, which is slot
    // 1132: two slots handed out after the padding, and a virtual call reading two words past the
    // end of the table into whatever followed it. It jumped to zero.
    void padVtables() {
        const size_t slots = vtableSlot_.size();
        for (Global& g : out_.module.globals) {
            if (!g.initFns.empty() && g.initFns.size() < slots) {
                g.initFns.resize(slots);
            }
        }
    }

    // Whether anything in the program rewrites this class's dispatch table at run time -- its own
    // slots, or slots it inherited from a class that is patched or unimported. See `buildVtable`.
    bool rewritesItsVtable(const ast::ClassDecl& c) const {
        for (const ast::ClassDecl* at = &c; at != nullptr;) {
            if (unimportable_.count(at->name) != 0 || patched_.count(at->name) != 0) {
                return true;
            }
            const std::string up = cgutil::baseType(at->superclass);
            at = up.empty() ? nullptr : findClass(up);
        }
        return false;
    }

    void buildVtable(const ast::ClassDecl& c) {
        if (c.isStruct || c.isRecord || c.isUnion || c.isInterface) {
            return;   // a value type has no identity to dispatch on; an interface has no instances
        }
        if (!carriesVtable(c)) {
            return;   // ...and a class with nowhere to put the pointer cannot have a table either
        }
        std::vector<std::string> names;
        collectMethodNames(c, names);
        std::vector<std::pair<int64_t, std::string>> entries;
        for (const std::string& n : names) {
            // ONLY WHAT IS ACTUALLY DISPATCHED gets a slot. Numbering every method name in the
            // program gave 1122 slots, and since every table is padded to that width, each class
            // carried nine kilobytes of mostly-null pointers. A method nothing overrides is called
            // directly and needs no slot at all.
            if (!dispatchedAnywhereAbove(c, n)) {
                continue;
            }
            const std::string body = implementationOf(c, n);
            if (!body.empty()) {
                entries.emplace_back(slotFor(n), body);
            }
        }
        // THE DESTRUCTOR IS DISPATCHED TOO. `delete base` on a `Derived` must run `~Derived`, and
        // the destructor is not a `MethodDecl` so the walk above never sees it -- `virtual_dtor`
        // printed `~Base` where the program prints `~Derived` then `~Base`. It gets a slot under
        // the reserved name `~`, which no method can be called.
        if (const std::string dtor = destructorOf(c); !dtor.empty()) {
            entries.emplace_back(slotFor("~"), dtor);
        }
        // NO ENTRIES IS STILL A TABLE, because the LAYOUT already reserved the pointer.
        //
        // `carriesVtable` above decided that this class's instances have a slot at offset zero, and
        // the constructor writes `<class>.vtable` into it only when a table was built. Returning
        // here left the two disagreeing: the slot exists and nothing initialises it, so it holds
        // whatever the allocator last put there, and a virtual call reads that as a function
        // pointer. `Object` is the class this bites -- nobody declares it, every program has it,
        // and nothing overrides `equals`/`hashCode`/`toString`, so it reaches here with no entries
        // every time. `Object* a = new Object() on heap; a.equals(a)` exited 0xC0000005.
        //
        // The cost is one pointer, not the nine kilobytes the slot-numbering fix above removed:
        // that was about a table's WIDTH (1122 slots padded into every class), and this is about
        // whether an eight-byte one exists at all. Identity needs it to: `x is T` compares the
        // instance's slot against `T.vtable`, and a class with no table has nothing to compare to.
        int64_t widest = 0;
        for (const auto& [slot, key] : entries) {
            widest = std::max(widest, slot);
        }
        Global g;
        g.name = keyOfClass(c) + ".vtable";
        g.type = out_.module.types.ptrType();
        g.linkage = Linkage::Internal;
        // A TABLE THAT GETS REWRITTEN CANNOT LIVE IN READ-ONLY MEMORY.
        //
        // Two things rewrite one. `X.methods.replace("m", fn)` (§32.8) points a slot at a thunk, and
        // `unimport X` (§30) poisons every slot so a call into a class that is gone reports itself
        // instead of jumping into freed code. Emitted `constant`, both of those are stores into
        // `.rdata`: the program segfaulted on `mov %rax, 0x35c4b(%rip)` with nothing printed,
        // because the output it had produced was still in a buffer when the process died.
        //
        // A SUBCLASS INHERITS THE PROPERTY, since what is rewritten is the slot it inherited. The
        // trusted path decides it the same way and for the same reasons; this side was deciding it
        // by not asking.
        g.isConst = !rewritesItsVtable(c);
        g.zeroInit = false;
        g.initFns.assign(static_cast<size_t>(widest) + 1, std::string());
        for (const auto& [slot, key] : entries) {
            g.initFns[static_cast<size_t>(slot)] = key;
        }
        out_.module.globals.push_back(std::move(g));
        hasVtable_.insert(keyOfClass(c));
    }

    // A class-level static, as a module global under `<Class>.<field>` -- the same key the call
    // sites already build from the qualified name. A LITERAL initialiser is folded in here, because
    // that is what `static fixed` means: one value, known now, and the reader is a constant.
    // Anything else needs code to run before `main`, which is a module init hook and is recorded as
    // a gap rather than silently zeroed.
    void declareStatic(const std::string& owner, const std::string& visibility,
                       const ast::TypeRef& type, const std::string& name, const ast::Expr* init,
                       bool isConst, SourceLocation loc) {
        const std::string key = owner + "." + name;
        // THE TYPE AS WRITTEN, in the same table an instance field's goes into -- a static IS a
        // field of the class, it merely has one storage location instead of one per object, and
        // every question asked of the name afterwards is the same question.
        fieldTypeName_[key] = declaredTypeOf(resolvedTypeName(type), pointerDepthOfType(type));
        for (const Global& g : out_.module.globals) {
            if (g.name == key) {
                return;
            }
        }
        Global g;
        g.name = key;
        g.type = typeOf(type);
        g.linkage = visibility == "public" ? Linkage::Public : Linkage::Internal;
        g.isConst = isConst;
        g.zeroInit = true;
        // THE FOLDED VALUE FIRST. `foldConstants` has already evaluated every `static fixed` in the
        // program -- including the ones written in terms of each other, which is most of them --
        // so the literal cases below are only what is left: a plain `static` that is not `fixed`.
        if (auto folded = constInts_.find(key); folded != constInts_.end()) {
            g.initInt = folded->second;
            g.zeroInit = false;
        } else if (auto real = constDoubles_.find(key); real != constDoubles_.end()) {
            g.initFloat = real->second;
            g.zeroInit = false;
        } else if (const auto* n = dynamic_cast<const ast::IntLiteralExpr*>(init)) {
            g.initInt = parseIntLexeme(n->text);
            g.zeroInit = false;
        } else if (const auto* d = dynamic_cast<const ast::FloatLiteralExpr*>(init)) {
            g.initFloat = std::strtod(d->text.c_str(), nullptr);
            g.zeroInit = false;
        } else if (const auto* b = dynamic_cast<const ast::BoolLiteralExpr*>(init)) {
            g.initInt = b->value ? 1 : 0;
            g.zeroInit = false;
        } else if (init != nullptr) {
            // AN INITIALIZER THAT WAS WRITTEN AND CANNOT BE EVALUATED is the failure this whole
            // step exists to stop being silent. Zeroing it is never what was meant, and the
            // resulting program is wrong in a way no test of the program's OUTPUT can localise back
            // to this line.
            //
            // It was a `gap` here, which is the wrong report entirely: a gap says the lowering has
            // not learned a construct and the program is still emitted. This program is WRONG.
            // `static int EARLY = Rules.LATER / 4;` beside `static int LATER = Rules.EARLY * 2;` is
            // a cycle with no value at the bottom of it, and both fields were quietly zeroed.
            //
            // The second sentence is for the half that ALLOCATES, and it is a different fault
            // wearing the same shape: a `String` or a `new T[n]()` is not unevaluable because the
            // folder is weak, but because a value that must be ALLOCATED cannot exist before the
            // process does. `static mutable String tag = "hello";` compiled clean and took the
            // process down with an access violation.
            const std::string spelled = resolvedTypeName(type);
            const bool numeric = cgutil::isIntName(spelled) || cgutil::isFloatType(spelled) ||
                                 spelled == "boolean" || spelled == "char";
            refuse("the initializer for static field '" + key +
                       "' cannot be evaluated before the program starts: it is neither a constant "
                       "nor built from other static fields without a cycle" +
                       (numeric ? ""
                                : ". A value that must be ALLOCATED cannot exist before the program "
                                  "runs -- give it a value in `onClassLoad`, which is where the "
                                  "standard library builds its own tables"),
                   loc);
        }
        out_.module.globals.push_back(std::move(g));
    }

    void declareClass(const ast::ClassDecl& c, const ast::Bundle& bundle) {
        // WHAT THIS CLASS IS FILED UNDER. Its own name when nothing else answers to it, and its
        // full path when something does -- see `indexClasses`. Everything derived from the class's
        // identity uses this: the interned type, the method keys, the field table, the vtable.
        const std::string cls = keyOfClass(c);
        std::vector<Field> fields;
        std::vector<Field> persisted;   // §18.2: the ones that live outside the object
        // THE VTABLE POINTER IS FIELD ZERO of every reference class, which is where the trusted
        // path puts it and therefore where a `Tagged*` used as a `Particle*` expects to find it.
        // A `struct`, `record` or `union` is a value and gets none.
        // ...and NOT a `layout`, whose whole purpose is to state an exact arrangement of bytes: a
        // hidden pointer in front of it is precisely the thing that declaration exists to forbid.
        // Nor a transformer, which has no instances.
        if (carriesVtable(c)) {
            Field vt;
            vt.type = out_.module.types.ptrType();
            vt.name = "__vtable";
            fields.push_back(vt);
        }
        // THE WEAK-LIST HEAD GOES SECOND, right behind the vtable, for every class that can be the
        // target of a `weak` field. At offset 8 for everybody -- see `collectWeakTargets` for why it
        // may not go after the fields, where it would land somewhere different in each class and a
        // `weak Base*` would write the head over a subclass's data. Zero for the vtable-less, which
        // is the same place the other backend puts it and for the same reason.
        //
        // OUTSIDE the vtable test, not inside it: a class can be a weak target without being in any
        // inheritance relationship at all, and while both were decided by one `if` it lost its head
        // pointer the moment the vtable became conditional.
        if (!c.isStruct && !c.isRecord && !c.isUnion && !c.isLayout && !c.isTransformer &&
            carriesWeakHead(c.name)) {
            Field head;
            head.type = out_.module.types.ptrType();
            head.name = "__weakhead";
            fields.push_back(head);
        }
        // A SUBCLASS BEGINS WITH ITS BASE. `Tagged extends Particle` was laid out with its own one
        // field and nothing else, so `this.x` -- inherited -- matched no field at all, fell back to
        // offset zero, and read the same four bytes as `this.tag`: every member of a subclassed
        // object came back as the last value written. That a subclass's storage starts with exactly
        // the base's is not an optimisation, it is what makes a `Tagged*` usable as a `Particle*`.
        appendInheritedFields(c, fields, persisted, cls);
        // A `comptime literal` IS ITS OWN MEMBER KIND TOO, and it is what makes `1 kilobytes` mean
        // anything: the suffix is a one-parameter static that builds the value. Never declared, so
        // the call resolved to nothing and became an indirect call to address 1 -- which is what a
        // region's size expression evaluated to before every region sample died.
        forEachMember<ast::LiteralDecl>(c, [&](const ast::LiteralDecl& l) {
            // ONE KEY PER OVERLOAD, and the parameter's type is what distinguishes them (§17.10
            // rule 6). Keyed by name alone, `literal scaled(int)` and `literal scaled(double)`
            // collapsed to one function -- the second declaration was silently dropped, and
            // `Scale.scaled(1.5)` ran the integer body: 2 where the program computes 15.
            const std::string param = ast::mangleGeneric(l.param.type.name, l.param.type.typeArgs);
            const std::string key = cls + "." + l.name + "$" + param;
            if (out_.module.find(key) != nullptr) {
                return;
            }
            literalOverloads_[cls + "." + l.name].push_back({param, key});
            Field p;
            p.type = typeOf(l.param.type);
            p.name = l.param.name;
            Function* fn = out_.module.addFunction(
                key, out_.module.types.fnType(typeOf(l.returnType), {p}));
            fn->params = {{l.param.name, ast::mangleGeneric(l.param.type.name,
                                                            l.param.type.typeArgs),
                           passedByValue(l.param.type)}};
            fn->linkage = l.visibility == "public" ? Linkage::Public : Linkage::Internal;
            returnName_[key] =
                declaredTypeOf(resolvedTypeName(l.returnType), pointerDepthOfType(l.returnType));
            // A LITERAL SUFFIX IS NOT A METHOD ON WHOEVER WRITES IT. `1 kilobytes` inside a method
            // reads as a call to a bare name, and a bare name was being treated as a method on
            // `this` -- so it went out as a VIRTUAL call through the writer's own table, at a slot
            // number no table has. Recorded here so the name resolves to the class that declared
            // the suffix, which is the only class it could ever mean.
            literalSuffix_[l.name] = cls + "." + l.name;
        });

        // A CLASS-LEVEL CONSTANT IS ITS OWN MEMBER KIND. `public static fixed int MAX = 100;`
        // parses to a `ConstDecl`, not to a `FieldDecl` with a flag -- so a walk that only looks at
        // fields never saw one, and `Limits.MAX` resolved to an external the lowering invented and
        // zeroed. `a=100 b=200 r=15` printed as `a=0 b=0 r=0`.
        forEachMember<ast::ConstDecl>(c, [&](const ast::ConstDecl& k) {
            declareStatic(cls, k.visibility, k.type, k.name, k.init.get(), /*isConst=*/true,
                          k.loc);
        });
        forEachMember<ast::FieldDecl>(c, [&](const ast::FieldDecl& f) {
            // A STATIC IS NOT PART OF THE OBJECT. It has one storage location for the whole
            // program, so it belongs in the module's globals -- and it was in neither: not a field
            // and not a global, so `Limits.MAX` resolved to an external the lowering invented and
            // zeroed, and `a=100 b=200 r=15` printed as `a=0 b=0 r=0`.
            if (f.isStatic) {
                declareStatic(cls, f.visibility, f.type, f.name, f.init.get(), !f.isMutable,
                              f.loc);
                return;
            }
            Field pf = pirField(f);
            // A `persistent` FIELD IS NOT PART OF THE OBJECT (§18.2). Its lifetime is decoupled
            // from the object's -- that is the whole of what the word means -- so it cannot live in
            // storage that `delete` frees. It goes into a BLOCK the object points at, and the block
            // outlives the object: create a `Car`, bump `chassi`, delete the car, create another,
            // and `chassi` is where the last one left it. Held in the object it read 1, 1, 1.
            //
            // `eternal` IS NOT THAT WORD. It says a REGION is not torn down when its scope ends --
            // a lifetime rule about the region's contents, and the trusted path reads it in exactly
            // one place, deciding whether a scope exit destroys a local. On a field it says nothing
            // about where the field lives, so moving `eternal` fields out of the object put
            // `Framebuffer.aperture` at the end of the class where the trusted path has it fifth,
            // and the two paths disagreed on the offset of every field after it.
            if (f.isPersistent) {
                persisted.push_back(pf);
                persistOrder_[cls].push_back(f.name);
            } else {
                fields.push_back(pf);
            }
            if (f.isTransient) {
                transientFields_[cls].insert(f.name);
            }
            // §37.5: `private eternal volatile mutable region aperture;` -- an access to this field
            // is an access to hardware, and it must not be moved, merged or deleted.
            if (f.isVolatile) {
                volatileFields_.insert(cls + "." + f.name);
                // ...AND IF IT IS A REGION, WHAT LIVES IN IT IS VOLATILE TOO. `private eternal
                // volatile mutable region aperture;` is how a driver says "this memory is a
                // device": every object placed there is a register file, and every field access on
                // one is an access to hardware -- not just the handle that finds it.
                volatileRegions_.insert(f.name);
            }
            // THE FIELD'S TYPE AS WRITTEN, kept beside the layout. The interned type says `ptr` for
            // every object field, so a read of `this.rows` arrived with no class at all and the
            // call on it resolved by bare name: an `ArrayList<Row*>` field had `add` bound to
            // `ArrayList$long.add`, a different instantiation with a different element size.
            ast::TypeRef bare = f.type;
            bare.pointerDepth = 0;
            bare.isPointer = false;
            bare.isRef = false;
            fieldTypeName_[cls + "." + f.name] =
                declaredTypeOf(resolvedTypeName(f.type), pointerDepthOfType(f.type));
            // A REGION CAN BE A FIELD (spec 17): `private mutable pool region nodes;`. Its flavour
            // is on the field's declaration, and everything that asks about a region -- how big a
            // header its block needs, whether an allocation goes through the runtime, whether a
            // release must tear down a registry -- has to be able to find it by name.
            //
            // EVERY REGION FIELD IS RECORDED, not only a flavoured one. The condition used to be
            // "has a flavour or grows", which left a plain `public region arena;` out of the table
            // entirely -- so every question asked about it by name got the default bump answer, and
            // one of those questions is whether it keeps a destructor registry. It has to (see
            // `RegionShape::registry`), and answering no meant a `~Pool` that released the arena
            // destroyed nothing in it.
            if (!f.regionFlavor.empty() || f.regionGrowable ||
                ast::mangleGeneric(f.type.name, f.type.typeArgs) == "region") {
                RegionShape shape{f.regionFlavor, f.regionGrowable};
                shape.isField = true;
                regionShape_[f.name] = std::move(shape);
            }
            // AN `external` FIELD IS AN ASSOCIATION, not a part: the object on the other end
            // belongs to somebody else, and a `cascade delete` that followed it would free it.
            if (f.isExternal) {
                externalFields_.insert(cls + "." + f.name);
            }
            // A `unique` FIELD IS NOT READ HERE. It says the field holds the only reference to
            // what it points at -- a fact about the POINTEE, not about this class, and one that
            // would earn `!noalias` metadata on the loads of it. The class's own discipline is
            // read from `c.isUnique` where the facts are settled.
        });
        // IMPLEMENTING A `layout` AUTHORISES THE COMPILER TO ORDER THE FIELDS (§11.1), and that is
        // the point of writing one: a `byte` between two `int`s costs six bytes of padding as
        // declared and none at all widest-first. `Tick` measured sixteen where the layout fits it
        // within twelve -- and the trusted path reorders, so the two disagreed on every offset.
        // Widest-first by ALIGNMENT, stably, so fields of equal width keep the order they were
        // written in and the arrangement is the same on every run.
        if (!c.layouts.empty() && fields.size() > 1) {
            std::stable_sort(fields.begin(), fields.end(), [](const Field& a, const Field& b) {
                const uint32_t la = a.type != nullptr ? a.type->facts.align : 1;
                const uint32_t lb = b.type != nullptr ? b.type->facts.align : 1;
                return la > lb;
            });
        }
        // ...and the object gets ONE MORE FIELD: the pointer to that block. Last, so every offset a
        // subclass or an existing read computed stays where it was.
        if (!persisted.empty()) {
            persistIndex_[cls] = static_cast<int64_t>(fields.size());
            persistBlock_[cls] =
                out_.module.types.structType("persistblock." + cls, std::move(persisted), true);
            Field slot;
            slot.type = out_.module.types.ptrType();
            slot.name = "__persist";
            fields.push_back(slot);
        }
        // A NAME MENTIONED BEFORE ITS DECLARATION already has an entry -- an empty nominal struct
        // interned so the mention had something to point at -- and interning a second one leaves
        // every earlier mention pointing at the empty one. `ByteSize` is mentioned by its own
        // `comptime literal` members, which are declared a few lines above this: its return type
        // was the empty entry, so `8 kilobytes` had no `bytes` field and `itself.allocate(...)`
        // asked the allocator for `undef` bytes.
        // CONSECUTIVE BIT FIELDS SHARE ONE STORAGE UNIT (§11.1) -- that is the whole reason to write
        // them. `struct TwoNibbles { int a : 4; int b : 4; }` is ONE BYTE; laid out as two `int`s it
        // measured eight, and a `Packed` designed to fit three to a cache line measured 24 where its
        // own `demand` says 20. The unit is the smallest power-of-two byte size that holds the run,
        // every field of the run shares that one element, and each keeps its offset inside it.
        //
        // The grouping happens HERE, after every field is known, because a run is a property of the
        // SEQUENCE: whether `b` shares `a`'s unit depends on what sits between them.
        {
            std::vector<Field> packed;
            for (size_t at = 0; at < fields.size();) {
                if (fields[at].bitWidth == 0) {
                    packed.push_back(fields[at]);
                    ++at;
                    continue;
                }
                size_t end = at;
                uint32_t bits = 0;
                while (end < fields.size() && fields[end].bitWidth != 0 &&
                       bits + fields[end].bitWidth <= 64) {
                    bits += fields[end].bitWidth;
                    ++end;
                }
                uint32_t unitBits = 8;
                while (unitBits < bits) {
                    unitBits *= 2;
                }
                const int64_t index = static_cast<int64_t>(packed.size());
                uint32_t offset = 0;
                for (size_t k = at; k < end; ++k) {
                    BitField rec;
                    rec.index = index;
                    rec.unitBits = unitBits;
                    rec.offset = offset;
                    rec.width = fields[k].bitWidth;
                    rec.isUnsigned = isUnsignedName(
                        groundName(fieldTypeName_.count(cls + "." + fields[k].name)
                                       ? fieldTypeName_[cls + "." + fields[k].name].name
                                       : std::string()));
                    bitFields_[cls + "." + fields[k].name] = rec;
                    offset += fields[k].bitWidth;
                }
                // ONE ELEMENT FOR THE RUN, named after the field that starts it: the members do not
                // each have storage, they have a share of this one.
                Field unit;
                unit.type = out_.module.types.intType(unitBits);
                unit.name = fields[at].name;
                packed.push_back(unit);
                at = end;
            }
            fields = std::move(packed);
        }
        // A `union` IS ONE STORAGE ITS FIELDS SHARE (§13), so its shape is the WIDEST field and not
        // all of them in sequence. Laid out in sequence, `v.asFloat = 1.5` wrote at offset four and
        // `v.asInt` read offset zero: the sample that exists to state the rule printed `bits = 0`
        // where the reinterpretation is the whole point. The names do not go into the shape at all
        // -- every one of them is offset zero -- so they stay in `fieldTypeName_`, which is where
        // `fieldAddress` reads what a field HOLDS as opposed to where it sits.
        // THIS NAME IS A CLASS, which the backend needs to know to spell its struct the way the
        // other path does -- see `Module::ClassShape`. Recorded for every class, union or not.
        Module::ClassShape& shape = out_.module.classes[cls];
        if (c.isUnion && !fields.empty()) {
            // ...AND ITS FIELDS OVERLAP, because after this the shape keeps one field and nothing
            // in it still says the others shared the offset. The backend's alias metadata must
            // leave a union alone.
            shape.overlapping = true;
            const Field* widest = &fields.front();
            for (const Field& f : fields) {
                if (f.type != nullptr && widest->type != nullptr &&
                    f.type->facts.size > widest->type->facts.size) {
                    widest = &f;
                }
            }
            unions_.insert(cls);
            Field one = *widest;
            one.name = "__storage";
            fields.assign(1, one);
        }
        const Type* t = nullptr;
        if (auto seen = named_.find(cls);
            seen != named_.end() && seen->second != nullptr &&
            seen->second->kind == TypeKind::Struct && seen->second->nominal &&
            seen->second->fields.empty() && !fields.empty()) {
            out_.module.types.completeStruct(seen->second, std::move(fields));
            t = seen->second;
        } else {
            t = out_.module.types.structType(cls, std::move(fields), true);
        }
        named_[cls] = t;

        bool hasDestructor = false;
        forEachMember<ast::DestructorDecl>(c, [&](const ast::DestructorDecl&) { hasDestructor = true; });

        // A `layout` STATES AN EXACT ARRANGEMENT OF BYTES (§11.1), which is the whole reason to
        // write one: it describes a register block or a wire format, and a padding hole the
        // compiler inserted is a field at the wrong offset. Twelve declared bytes measured sixteen.
        if (c.isLayout) {
            out_.module.types.setPacked(t, true);
        }
        TypeFacts facts = t->facts;
        facts.isValue = c.isStruct || c.isRecord || c.isUnion;
        // `owns` -- destroying one does work. Decided HERE, once, from the declaration, because it
        // is one of the five facts §3.3 puts on the type entry, and because `T.owns()` answering it
        // at compile time proves the compiler already knows.
        facts.owns = hasDestructor || facts.owns;
        // `unique` -- AT MOST ONE LIVE REFERENCE (spec 19.9). It is the fact behind `noalias`, the
        // strongest single thing an alias analysis can be told.
        //
        // OFF THE CLASS, NOT OFF ITS FIELDS. `unique` is spelled in two places and they say two
        // different things: `unique class FileHandle` is the ownership DISCIPLINE -- "apenas uma
        // referência viva por vez em todo o programa" -- while `unique Buffer* b` says the FIELD
        // holds the only reference to the object on its far end. This read the second and recorded
        // it as the first, so `facts.isUnique` meant "has a unique field", and:
        //
        //   - `T.isUnique()` answered a different question here than in the trusted path, which
        //     reads the class's own flag. Two backends, one reflection method, two answers.
        //   - the `noalias` it is supposed to feed could never fire from it anyway: the attribute
        //     goes on a parameter, and a parameter's type is `ptr`, whose facts are nobody's.
        //
        // A class that merely OWNS a unique field is not itself unique -- its instances may be
        // referenced from anywhere -- so reading the fields could only ever have been wrong in the
        // unsafe direction.
        facts.isUnique = c.isUnique;
        for (const Field& f : t->fields) {
            if (f.type != nullptr && f.type->facts.owns && !f.weak) {
                facts.owns = true;
            }
        }
        measureAggregate(t->fields, t->packed, facts);
        out_.module.types.setFacts(t, facts);
        checkLayoutBudget(c, facts.size);

        forEachMember<ast::MethodDecl>(c, [&](const ast::MethodDecl& m) {
            // A GENERATOR'S PARKED BODY IS NOT A METHOD AT ALL (§22.6). An earlier pass split
            // `evens()` into the iterator it returns and a `$body` twin holding the part with the
            // `yield`s in it; `lowerGenerator` turns that twin into the four state-machine
            // functions, and the twin itself never becomes anything. Declared here it got a
            // function with no body AND A VTABLE SLOT POINTING AT IT -- so the module carried a
            // private declaration ("Global is external, but doesn't have external or weak linkage!
            // ptr @Sequences.evens$body") and, once that was papered over, a link failure on a
            // symbol the source never mentions. The trusted path skips it in the same place for
            // the same reason.
            if (m.isGeneratorBody) {
                return;
            }
            Function* fn = declareMethod(c, m);
            if (fn != nullptr && bundle.isFreestanding && m.isNaked) {
                fn->noRedZone = true;
            }
        });
        // CONSTRUCTORS AND DESTRUCTORS ARE FUNCTIONS, and forgetting them is not a small omission:
        // the Stage 3 differential oracle found `Key.Key` defined by the trusted path and absent
        // from PIR the first time it ran. A `ClassDecl` keeps every member in one vector, so a walk
        // that only looks for `MethodDecl` silently drops two whole member kinds.
        forEachMember<ast::ConstructorDecl>(c, [&](const ast::ConstructorDecl& k) {
            std::vector<Field> params;
            std::vector<Function::Param> plist;
            Field self;
            self.type = out_.module.types.ptrType();
            self.name = "this";
            params.push_back(self);
            plist.push_back({"this", cls});
            for (const ast::Param& p : k.params) {
                Field f;
                f.type = typeOf(p.type);
                f.name = p.name;
                params.push_back(f);
                plist.push_back({p.name, resolvedTypeName(p.type), passedByValue(p.type),
                                 pointerDepthOfType(p.type)});
            }
            // `<key>.<key>`, not `<key>.<simple name>`: every site that names a constructor builds
            // it the same way from the resolved class name, and one spelling everywhere is worth
            // more than a tidier symbol that half the compiler would then have to special-case.
            const std::string key = cls + "." + cls;
            if (out_.module.find(key) != nullptr) {
                return;
            }
            Function* fn = out_.module.addFunction(
                key, out_.module.types.fnType(out_.module.types.voidType(), std::move(params)));
            fn->params = std::move(plist);
            fn->kind = FnKind::Constructor;
            fn->linkage = k.visibility == "public" ? Linkage::Public : Linkage::Internal;
            // AN EMPTY BODY IS A BODY. `public constructor Dog() {}` is a constructor that does
            // nothing, not a declaration of one defined elsewhere -- and calling it external meant
            // nothing emitted it, so every program that built such an object failed to link naming
            // a constructor written three lines above. The `{}` is the definition.
            for (const auto& rq : k.requiresClauses) {
                Contract kk;
                kk.kind = Contract::Kind::Requires;
                kk.text = describe(rq.get());
                fn->contracts.push_back(kk);
            }
        });
        // THE IMPLICIT CONSTRUCTOR. A class that declares none still HAS one -- the front end
        // synthesises it, and the differential oracle found `Object.Object` defined by the trusted
        // path and absent here. A lowering that only reproduces what the programmer wrote is a
        // lowering that cannot replace the path that also produces what the compiler wrote.
        bool hasCtor = false;
        forEachMember<ast::ConstructorDecl>(c, [&](const ast::ConstructorDecl&) { hasCtor = true; });
        if (!hasCtor && !c.isInterface && !c.isLayout && !c.isTransformer) {
            const std::string key = cls + "." + cls;
            if (out_.module.find(key) == nullptr) {
                Field self;
                self.type = out_.module.types.ptrType();
                self.name = "this";
                Function* fn = out_.module.addFunction(
                    key, out_.module.types.fnType(out_.module.types.voidType(), {self}));
                fn->params = {{"this", cls}};
                fn->kind = FnKind::Constructor;
                // AS VISIBLE AS THE CLASS, because that is what the language says it is. `public
                // class Square { }` may be constructed by anyone who can name `Square` -- there is
                // no `constructor` line to carry a visibility of its own, and the one the compiler
                // synthesises stands in for the one the author did not have to write.
                //
                // Left `Internal` it was invisible past the object it was compiled into, which in a
                // program is exactly right and nobody could tell. In a `--lib` it is the difference
                // between a usable bundle and `lld-link: error: undefined symbol: Square.Square`:
                // the consumer writes `new Square()` -- legal, and the analyzer agrees -- and the
                // library published no such symbol.
                fn->linkage = c.visibility == "public" ? Linkage::Public : Linkage::Internal;
                // NO BODY HERE. It IS defined -- and it is lowered like every other constructor,
                // from an empty block, once the tables exist. Built by hand instead, it wrote the
                // vtable pointer and NOTHING ELSE: a class with inline field initialisers and no
                // constructor written -- `public mutable int width = 80;` -- got an object with
                // every field zero, and `class_field_init` printed `area = 0` for 80 by 24.
                synthesized_.push_back(cls);
            }
        }

        // A COUNTED CLASS GETS A DESTRUCTOR IT NEVER WROTE, for the one reason: that is where the
        // live-instance count comes down, and `release region A` and `unimport A` both refuse while
        // the count is above zero. Not by analogy with unimport -- it is the same counter and the
        // same refusal.
        if (hasDestructor || countsInstances(c)) {
            Field self;
            self.type = out_.module.types.ptrType();
            self.name = "this";
            const std::string key = cls + ".~" + cls;
            if (out_.module.find(key) == nullptr) {
                Function* fn = out_.module.addFunction(
                    key, out_.module.types.fnType(out_.module.types.voidType(), {self}));
                fn->params = {{"this", cls}};
                fn->kind = FnKind::Destructor;
                bool empty = true;
                forEachMember<ast::DestructorDecl>(c, [&](const ast::DestructorDecl& d) {
                    empty = d.body.statements.empty();
                });
                if (!hasDestructor) {
                    // Nothing declared it, so nothing else will lower it: an empty body through the
                    // ordinary path, which is what puts the decrement in.
                    synthesizedDtors_.push_back(cls);
                } else if (empty) {
                    fn->linkage = Linkage::External;
                }
            }
        }
    }

    Function* declareMethod(const ast::ClassDecl& c, const ast::MethodDecl& m) {
        return declareMethodOn(keyOfClass(c), out_.module.types.ptrType(), m);
    }

    // The ABI world an `extern` declaration named, as the enum §6 keeps it in. `syscall:N` is not a
    // calling convention at all -- it is the machine's own instruction with N in the number
    // register -- but it arrives spelled like one, so it is recognised here and refused a symbol.
    static Conv externConv(const std::string& world) {
        if (world == "stdcall") {
            return Conv::Stdcall;
        }
        if (world == "fastcall") {
            return Conv::Fastcall;
        }
        if (world == "cppdecl") {
            return Conv::Cppdecl;
        }
        if (world == "rustdecl") {
            return Conv::Rustdecl;
        }
        if (world == "zigdecl") {
            return Conv::Zigdecl;
        }
        return Conv::Cdecl;
    }

    // THE OWNER IS A NAME AND A `this` TYPE, nothing more -- which is what lets an ENUM have
    // methods. A catalog enum's instance method receives the ORDINAL as `this`, not a pointer: the
    // value of `Motor.DIESEL` is the number 1, and there is no object anywhere for it to point at.
    // Declared through the same path as a class's so the two cannot drift on linkage, contracts,
    // unwinding or the return-name table, all of which used to be one method's worth of detail.
    // The integer a small value struct travels as at a C boundary, or null when the type is not one
    // -- which is every type that is not a value struct, and every struct too big for a register.
    // Anything larger goes by address, which is what a `ptr` already is here.
    // A struct's bytes, read as one integer. The value is either the storage's address -- which is
    // what an object is everywhere inside a method -- or the struct itself, in which case it needs
    // somewhere to be read FROM.
    ValueId readAsWord(ValueId v, const Type* word, SourceLocation loc) {
        const Type* have = fn_->value(v)->type;
        ValueId at = v;
        if (have != nullptr && have->kind == TypeKind::Struct) {
            Inst room;
            room.op = Op::Alloca;
            room.type = have;
            room.text = "ffi.byval";
            room.loc = loc;
            at = emit(std::move(room));
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(v);
            put.operands.push_back(at);
            put.loc = loc;
            emit(std::move(put));
        }
        Inst ld;
        ld.op = Op::Load;
        ld.type = word;
        ld.operands.push_back(at);
        ld.loc = loc;
        return emit(std::move(ld));
    }

    // ...and the reverse: an integer that came back from C, put into fresh storage of the struct
    // it really is, so everything downstream sees an ordinary object.
    ValueId wordAsStruct(ValueId v, const Type* shape, SourceLocation loc) {
        Inst room;
        room.op = Op::Alloca;
        room.type = shape;
        room.text = "ffi.ret";
        room.loc = loc;
        const ValueId at = emit(std::move(room));
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(v);
        put.operands.push_back(at);
        put.loc = loc;
        emit(std::move(put));
        pointee_[at] = shape;
        return at;
    }

    const Type* ffiWord(const Type* t) {
        if (t == nullptr || t->kind != TypeKind::Struct || !t->facts.isValue) {
            return nullptr;
        }
        const uint64_t size = t->facts.size;
        if (size != 1 && size != 2 && size != 4 && size != 8) {
            return nullptr;
        }
        return out_.module.types.intType(static_cast<uint32_t>(size) * 8);
    }

    Function* declareMethodOn(const std::string& owner, const Type* selfType,
                              const ast::MethodDecl& m) {
        // The one `extern` that is not a foreign symbol -- see `lowerSyscallStub`. Read twice
        // below, because it changes both what the function is named and whether it is a
        // declaration.
        const bool isSyscall = m.isExtern && m.externConvention.rfind("syscall:", 0) == 0;
        std::vector<Field> params;
        std::vector<Function::Param> plist;
        if (!m.isStatic) {
            Field self;
            self.type = selfType;
            self.name = "this";
            params.push_back(self);
            plist.push_back({"this", owner});
        }
        for (const ast::Param& p : m.params) {
            Field f;
            f.type = typeOf(p.type);
            f.name = p.name;
            // AT A C BOUNDARY A SMALL STRUCT TRAVELS IN A REGISTER (§26). Win64 puts a struct of
            // 1, 2, 4 or 8 bytes into one integer register and passes anything larger by address;
            // the declaration has to say so, because a `declare i32 @f(%Point)` and a `declare i32
            // @f(i64)` are two different calling conventions and only one of them is the C one.
            if (m.isExtern) {
                if (const Type* asWord = ffiWord(f.type); asWord != nullptr) {
                    f.type = asWord;
                }
            }
            params.push_back(f);
            plist.push_back({p.name, resolvedTypeName(p.type), passedByValue(p.type),
                             pointerDepthOfType(p.type)});
        }
        const std::string key = owner + "." + m.name;
        if (out_.module.find(key) != nullptr) {
            return nullptr;   // an overload set collapses to one key at this stage
        }
        // AN `async` METHOD IS TWO FUNCTIONS (§20.2). The one the program calls RETURNS A TASK and
        // returns immediately; the body lives in a `$resume` the scheduler calls with the saved
        // state. Declared as one, the call returned an `int` where a `Task<int>` was expected and
        // `await` read the result out of a number.
        if (m.isAsync) {
            Field state;
            state.type = out_.module.types.ptrType();
            state.name = "state";
            Function* body = out_.module.addFunction(
                key + "$resume", out_.module.types.fnType(out_.module.types.voidType(), {state}));
            body->params = {{"state", "", false, 0}};
            body->linkage = Linkage::Internal;
            body->unwind = Unwind::May;
        }
        const Type* returns = typeOf(m.returnType);
        // ...AND ITS SIGNATURE SAYS SO. An `async method f() returns int` hands back a `Task<int>`
        // -- an OBJECT -- and the comment above has said so since the `$resume` twin was written,
        // while the signature went on saying `int`. So the call returned a pointer into a
        // thirty-two bit slot, and `await` turned the surviving half back into an address:
        //
        //     %1 = call i32 @Main.sumA()
        //     %4 = zext i32 %3 to i64
        //     %5 = inttoptr i64 %4 to ptr      <- a Task built from half of one
        //
        // Every `async` sample ran to completion and printed nothing, because what it awaited was
        // never the task it had started.
        if (m.isAsync) {
            returns = out_.module.types.ptrType();
        }
        if (m.isExtern) {
            if (const Type* asWord = ffiWord(returns); asWord != nullptr) {
                returns = asWord;   // ...and it comes back in one too
            }
        }
        Function* fn =
            out_.module.addFunction(key, out_.module.types.fnType(returns, std::move(params)));
        fn->params = std::move(plist);
        // MANGLED, and without the outer pointers -- the same spelling `noteName` records, or a
        // call's result is filed under `Result` where every other use says `Result$int$int` and the
        // two never meet. `try?` asked for `Ok` and found no table.
        returnName_[key] =
            declaredTypeOf(resolvedTypeName(m.returnType), pointerDepthOfType(m.returnType));
        // ...AND THE SAME TYPE UNSTRIPPED, on the function, for the backend's return attributes.
        // `returnName_` above is deliberately reduced to a class key -- every table here is keyed
        // that way -- and the reduction throws away exactly the two things an attribute needs: the
        // pointer depth and the `nullable`.
        fn->returnTypeName = ast::canonicalType(m.returnType);
        // ...AND AN `async` ONE HANDS BACK A `Task<T>`, BY NAME AS WELL AS BY TYPE.
        //
        // `await` decides what to do by asking what the thing it was handed IS -- a value whose
        // declared name is not a `Task$...` is already the result and passes straight through. With
        // the name still saying `int`, `await Main.val(10)` INSIDE another async method returned the
        // task object itself and the `ptrtoint` beside it turned it into a number: `sum=60` came out
        // as `sum=-1970429136`. Awaiting from a non-async method worked all along, because there the
        // local is declared `Task<int>` in the source and the name comes from the declaration.
        if (m.isAsync) {
            returnName_[key] = {"Task$" + resolvedTypeName(m.returnType), 0};
        }

        fn->linkage = m.visibility == "public"     ? Linkage::Public
                      : m.visibility == "private"  ? Linkage::Private
                                                   : Linkage::Internal;
        fn->kind = m.isInterrupt ? FnKind::Interrupt : FnKind::Method;
        if (m.isInterrupt) {
            requireTargetFeature("interrupt", "`" + owner + "." + m.name + "`", m.loc);
        }
        // `[Cold]`: THIS PATH IS RARELY TAKEN. The inliner costs a method by its SIZE, which is a
        // poor proxy when the bulk of one runs log(n) times in n -- see the note beside the other
        // backend's copy of this, and `ArrayList.ensureCapacity`, which is what asked for it.
        // `Affinity::Cold` already reached LLVM from here (§12 counts it); nothing set it.
        if (cgutil::hasAnnotation(m, "Cold")) {
            fn->affinity = Affinity::Cold;
            fn->inlineNever = true;
        }
        // WHETHER IT CAN UNWIND, from what the declaration says. `nounwind` on the way out is one of
        // the fifteen rows of §12, and this is where the fact is decided rather than guessed.
        fn->unwind = m.throwsTypes.empty() ? Unwind::Never : Unwind::May;
        // `syscall(N)` IS NOT A FOREIGN SYMBOL. It arrives spelled like a calling convention and it
        // is the machine's own instruction; this method gets a BODY (see `lowerSyscallStub`), so it
        // keeps its own key, its own internal linkage, and no linker name at all. Given the extern
        // treatment below it became an external declaration of the bare name `socket` -- which
        // nothing defines, and which would collide with libc's if anything did.
        if (m.isExtern && !isSyscall) {
            fn->linkage = Linkage::External;
            fn->conv = externConv(m.externConvention);
            // THE LINKER NAME IS NOT THE POLARON NAME. `private extern cdecl static method
            // __polaron_secure_random()` declared on `SecureRandom` binds the C symbol
            // `__polaron_secure_random`; emitted under its key it asked the linker for
            // `SecureRandom.__polaron_secure_random`, which nothing anywhere defines. The whole
            // point of `symbol("...")` is that the two can differ -- binding `SDL_CreateWindow`
            // must not force a Polaron method to be CALLED that -- so both spellings are recorded
            // and the foreign one goes on the function, where the backend already looks for it.
            fn->symbol = m.externSymbol.empty() ? m.name : m.externSymbol;
            fn->variadic = m.isVariadic;
        }
        // A FUNCTION WITH NO BODY IS A DECLARATION, whatever made it one: `abstract`, an interface
        // method, or a body the front end left empty. Verifier rule 2 says so, and it said so out
        // loud the first time this lowering met a real program -- forty-odd interface methods
        // declared `internal` with nothing in them.
        if ((m.isAbstract || m.body.statements.empty()) && !isSyscall) {
            fn->linkage = Linkage::External;
        }
        if (m.isNaked) {
            fn->conv = Conv::Naked;
        }
        // [unknown-abi] A method declared `unknown <world>` IS A BOUNDARY THE FOREIGN WORLD CALLS
        // INTO -- the other direction from `unknown <world> funcptr`, which is us calling out. Two
        // consequences, and the declaration means nothing without either: it takes its BARE name as
        // the linker symbol (the foreign world knows `syscall_entry`, not `Syscall.entry` -- it has
        // no idea our classes exist), and it keeps external linkage, or dead-stripping deletes the
        // very entry point the declaration promised. This is what lets a kernel define `_start`, an
        // ISR or `__polaron_malloc` in Polaron; without it pico's link failed on all eight of them.
        if (m.externConvention.rfind("unknown:", 0) == 0) {
            fn->symbol = m.name;
            fn->linkage = Linkage::External;
        }
        for (const auto& r : m.requiresClauses) {
            Contract k;
            k.kind = Contract::Kind::Requires;
            k.text = describe(r.get());
            fn->contracts.push_back(k);
        }
        for (const auto& e : m.ensuresClauses) {
            Contract k;
            k.kind = Contract::Kind::Ensures;
            k.text = describe(e.get());
            fn->contracts.push_back(k);
        }
        return fn;
    }

    // THE BODY OF AN `extern syscall(N)` METHOD: the number in `rax`, the arguments in the kernel's
    // six registers, one `syscall` instruction, the answer back out of `rax`.
    //
    // This is the clearest case in the language for an architecture gate, and the trusted path
    // makes the same argument in the same words: the sequence below is Linux/x86-64, and on Windows
    // there is no stable syscall ABI at all while on ARM both the registers and the instruction are
    // different. Emitting it anywhere else would produce a program that assembles and then does
    // something arbitrary.
    void lowerSyscallStub(Function& fn, const ast::MethodDecl& m) {
        TypeTable& tt = out_.module.types;
        // A SYSCALL IS THE MACHINE'S OWN INSTRUCTION, so there is nothing here to port
        // automatically: Windows publishes no stable syscall ABI at all, and another architecture
        // numbers and passes them differently. Refused where the target is named rather than left to
        // emit an instruction the assembler will reject much later.
        const std::string& triple = out_.module.triple;
        const bool linuxX64 = cgutil::archFamily(cgutil::archOfTriple(triple)) == "x86_64" &&
                              triple.find("linux") != std::string::npos;
        if (!linuxX64) {
            refuse("`extern syscall(...)` is available on Linux/x86-64 and this target is " +
                       triple +
                       ". A syscall is the machine's own instruction with its own register contract, "
                       "so there is nothing here to port automatically: Windows publishes no stable "
                       "syscall ABI at all, and another architecture numbers and passes them "
                       "differently",
                   m.loc);
            return;
        }
        const int64_t number = std::strtoll(m.externConvention.c_str() + 8, nullptr, 10);
        if (m.params.size() > 6) {
            gap("extern syscall(" + std::to_string(number) + ") takes at most six arguments; '" +
                    m.name + "' declares " + std::to_string(m.params.size()),
                m.loc);
            return;
        }
        BodyState outer = saveBody();
        fn_ = &fn;
        here_ = fn.addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        declaredAs_.clear();
        pointee_.clear();
        pointeeOfSlot_.clear();
        clearFieldShapes();
        weakSlotAt_.clear();
        cCallable_.clear();
        statics_.clear();

        const Type* i64 = tt.intType(64);
        Block* head = fn.block(here_);
        // THE ARGUMENTS GO STRAIGHT INTO REGISTERS, so they need no frame slots -- there is nothing
        // in this body that could read one. Every argument is widened to the machine word first:
        // the constraint says a 64-bit register and an `int` handed to it is thirty-two bits of the
        // wrong shape.
        std::vector<ValueId> widened;
        for (uint32_t i = 0; i < fn.signature->fields.size(); ++i) {
            const Field& p = fn.signature->fields[i];
            const ValueId v = fn.addValue(p.type, ValueOrigin::BlockParam, here_, i,
                                          i < fn.params.size() ? fn.params[i].name : std::string());
            head->params.push_back(v);
            widened.push_back(p.type == i64 ? v : lowerConversion(v, p.type, i64, m.loc));
        }

        // The kernel's argument registers, in its order, taken only as far as the method declares.
        static const char* kArgRegs[6] = {"{di}", "{si}", "{dx}", "{r10}", "{r8}", "{r9}"};
        std::string cons = "={ax},{ax}";
        std::vector<ValueId> operands{constInt(number, 64, m.loc)};
        for (size_t i = 0; i < widened.size(); ++i) {
            cons += ",";
            cons += kArgRegs[i];
            operands.push_back(widened[i]);
        }
        // `rcx` AND `r11` ARE NOT SAVED ACROSS A SYSCALL: the instruction itself puts the return
        // address in one and the flags in the other. Memory too, because the call may write
        // anything the caller can see -- a `read` into a buffer is exactly that.
        cons += ",~{rcx},~{r11},~{memory}";

        Inst sys;
        sys.op = Op::Asm;
        sys.text = "syscall";
        sys.type = i64;
        sys.imm = static_cast<int64_t>(operands.size());
        sys.operands = std::move(operands);
        sys.extra.push_back(cons);
        // AT&T, named rather than inferred: an `asm` block written by hand in this language is
        // Intel by default, and this one is not written by hand.
        sys.extra.push_back("att");
        sys.loc = m.loc;
        const ValueId got = emit(std::move(sys));

        const Type* returns = fn.signature->element;
        Inst back;
        back.op = Op::Ret;
        if (returns != nullptr && returns->kind != TypeKind::Void) {
            back.operands.push_back(returns == i64 ? got
                                                   : lowerConversion(got, i64, returns, m.loc));
        }
        back.loc = m.loc;
        emit(std::move(back));
        restoreBody(std::move(outer));
    }

    static int64_t parseIntLexeme(const std::string& text) {
        std::string s;
        for (char c : text) {
            if (c != '_') {
                s += c;   // Polaron allows digit separators; `strtoll` does not
            }
        }
        // UNSIGNED, then reinterpreted. `strtoll` SATURATES at `INT64_MAX`, so
        // `ulong huge = 18000000000000000000;` -- a value the language accepts and the type holds --
        // silently became 9223372036854775807. Reading the digits as unsigned keeps all 64 bits;
        // the sign is decided by the operation, not by the literal, so storing the same bits in an
        // `int64_t` here loses nothing. `0xFFFFFFFFFFFFFFFF` had the same problem for the same
        // reason.
        auto digits = [](const char* p, int base) {
            return static_cast<int64_t>(std::strtoull(p, nullptr, base));
        };
        if (s.size() > 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
            return digits(s.c_str() + 2, 16);
        }
        if (s.size() > 2 && s[0] == '0' && (s[1] == 'b' || s[1] == 'B')) {
            return digits(s.c_str() + 2, 2);
        }
        if (!s.empty() && s[0] == '-') {
            return std::strtoll(s.c_str(), nullptr, 10);   // a negative literal is signed by sight
        }
        return digits(s.c_str(), 10);
    }

    static std::string describe(const ast::Expr* e) {
        if (e == nullptr) {
            return "";
        }
        std::string out;
        e->dump(out, 0);
        return out;
    }

    // ---- bodies ----

    void lowerClassBodies(const ast::ClassDecl& c) {
        // A constructor's and a destructor's bodies are ordinary bodies; what differs is only the
        // key they live under and that neither returns a value. `lowerBodyOf` takes the parts they
        // share so there is one lowering rather than three that drift.
        // NOT SKIPPED WHEN EMPTY. A body with no statements still needs an entry block and a
        // return; skipping it left the function declared and never defined, which the module is
        // perfectly happy with and the linker is not.
        // THE SAME KEY THE DECLARATION USED. Looking a body up by the bare name would find the
        // OTHER class of that name and fill its function with this one's statements.
        const std::string cls = keyOfClass(c);
        // DECLARED BEFORE ANY BODY THAT CALLS THEM. A constructor calls its class's
        // `__onFirstInstance`, so the function has to exist by the time the constructor is lowered;
        // the bodies come after, once nothing else is mid-lowering.
        declareLifecycleHooks(c, cls);
        forEachMember<ast::ConstructorDecl>(c, [&](const ast::ConstructorDecl& k) {
            Function* fn = out_.module.find(cls + "." + cls);
            if (fn != nullptr && fn->blocks.empty()) {
                lowerBodyOf(*fn, cls, k.body);
            }
        });
        forEachMember<ast::DestructorDecl>(c, [&](const ast::DestructorDecl& d) {
            Function* fn = out_.module.find(cls + ".~" + cls);
            if (fn != nullptr && fn->blocks.empty()) {
                lowerBodyOf(*fn, cls, d.body);
            }
        });
        forEachMember<ast::LiteralDecl>(c, [&](const ast::LiteralDecl& l) {
            // BY THE OVERLOAD'S OWN KEY -- see the declaration walk. Looking it up by name alone
            // would find the first overload and fill it with the second's body.
            const std::string param = ast::mangleGeneric(l.param.type.name, l.param.type.typeArgs);
            Function* fn = out_.module.find(cls + "." + l.name + "$" + param);
            if (fn != nullptr && fn->blocks.empty()) {
                lowerBodyOf(*fn, cls, l.body);
            }
        });
        forEachMember<ast::MethodDecl>(c, [&](const ast::MethodDecl& m) {
            // `extern syscall(N)` IS THE ONE `extern` THAT GETS A BODY. Every other one names a
            // symbol somebody else defines; this one names the machine's own instruction with N in
            // the number register, and there is nothing anywhere to link against. Left as a
            // declaration it became `undefined symbol: socket` -- and `sendTo`, `recvFrom`,
            // `setUid`, and every other syscall pico's ring-3 guest makes.
            if (m.isExtern && m.externConvention.rfind("syscall:", 0) == 0) {
                if (Function* fn = out_.module.find(cls + "." + m.name); fn != nullptr) {
                    lowerSyscallStub(*fn, m);
                }
                return;
            }
            // `isAbstract` and `isExtern` are the two that genuinely have NO body. An empty one is
            // a method that does nothing, and it still has to be emitted.
            if (m.isAbstract || m.isExtern) {
                return;
            }
            // BEFORE THE LOOKUP, because there is deliberately nothing to look up: the declaring
            // walk skips a generator's `$body` twin entirely (see there), and the four state-machine
            // functions this call builds are the whole of it.
            if (m.isGeneratorBody) {
                lowerGenerator(cls, m);
                return;
            }
            Function* fn = out_.module.find(cls + "." + m.name);
            if (fn == nullptr) {
                return;
            }
            if (m.isAsync) {
                lowerAsyncMethod(cls, m, *fn);
                return;
            }
            // A GENERATOR'S BODY IS NOT THIS FUNCTION'S. `Sequences.evens` builds the iterator
            // object and returns it; the body -- the part with the `yield`s in it -- becomes a
            // state machine somewhere else. An earlier pass already rewrote the method to call
            // `<genSym>$start` and synthesised the iterator class around it; what was missing here
            // is the four functions that call names, so every generator failed to LINK.
            lowerBody(*fn, cls, m);
        });
        lowerLifecycleHooks(c, cls);
    }

    // `X.methods.replace("m", fn)` (§32.8): point X's dispatch slot at a thunk that calls `fn`.
    //
    // TYPE SAFETY IS NOT LOST -- the analyzer has already checked that the replacement has the
    // method's exact signature with the receiver as its first parameter. What is left here is the
    // indirection: a closure is `{code, env}` and a vtable slot holds a bare function of the
    // method's own shape, so a thunk of that shape stands in the slot and forwards to the closure
    // through a global. One global and one thunk per replace site, which is what lets the same
    // method be replaced twice.
    ValueId patchDispatchSlot(const std::string& cls, const ast::CallExpr& c) {
        const auto* named = dynamic_cast<const ast::StringLiteralExpr*>(c.args[0].get());
        const ast::ClassDecl* decl = findClass(cls);
        if (named == nullptr || decl == nullptr) {
            gap("methods.replace(name must be a literal)", c.loc);
            return kNoValue;
        }
        const std::string method = named->value;
        const std::string impl = implementationOf(*decl, method);
        const Function* body = impl.empty() ? nullptr : resolveKey(impl);
        auto slot = vtableSlot_.find(method);
        if (body == nullptr || slot == vtableSlot_.end()) {
            gap("methods.replace('" + cls + "." + method + "' has no dispatch slot)", c.loc);
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const std::string tag = cls + "." + method + ".patch" + std::to_string(patchSites_++);

        Global held;
        held.name = tag + ".fn";
        held.type = ptr;
        held.linkage = Linkage::Private;
        out_.module.globals.push_back(std::move(held));

        // The thunk: the METHOD'S signature, so it fits the slot, and inside it the closure's --
        // the environment first, then everything the caller passed.
        Function* thunk = out_.module.addFunction(tag + ".thunk", body->signature);
        thunk->params = body->params;
        thunk->linkage = Linkage::Internal;
        {
            BodyState outer = saveBody();
            fn_ = thunk;
            here_ = thunk->addBlock("entry");
            entryBlock_ = here_;
            allocaAt_ = 0;
            locals_.clear();
            slotType_.clear();
            declaredAs_.clear();
            clearFieldShapes();
            weakSlotAt_.clear();
            cCallable_.clear();
            statics_.clear();
            std::vector<ValueId> passed;
            Block* head = thunk->block(here_);
            for (uint32_t i = 0; i < body->signature->fields.size(); ++i) {
                const ValueId v =
                    thunk->addValue(body->signature->fields[i].type, ValueOrigin::BlockParam, here_,
                                    i, body->signature->fields[i].name);
                head->params.push_back(v);
                passed.push_back(v);
            }
            Inst at;
            at.op = Op::ConstFn;
            at.type = ptr;
            at.text = tag + ".fn";
            const ValueId cell = emit(std::move(at));
            slotType_[cell] = ptr;
            const ValueId closure = loadFrom(cell, c.loc);
            const ValueId code = loadAt(closure, 0, ptr, c.loc);
            const ValueId env = loadAt(closure, 8, ptr, c.loc);

            Inst call;
            call.op = Op::CallIndirect;
            call.type = body->signature->element;
            call.operands.push_back(code);
            call.operands.push_back(env);
            for (ValueId a : passed) {
                call.operands.push_back(a);
            }
            call.loc = c.loc;
            const ValueId got = emit(std::move(call));
            Inst back;
            back.op = Op::Ret;
            if (body->signature->element != nullptr &&
                body->signature->element->kind != TypeKind::Void) {
                back.operands.push_back(got);
            }
            emit(std::move(back));
            restoreBody(std::move(outer));
        }

        // The patch itself: keep the closure, then point the slot at the thunk -- in this class and
        // in every subclass that INHERITS the same implementation. A Poodle is a Dog, so replacing
        // `Dog.bark` must reach the Poodles too; one that overrides it has its own behaviour and is
        // deliberately left alone.
        const ValueId fnVal = lowerExpr(c.args[1].get());
        if (fnVal == kNoValue) {
            return kNoValue;
        }
        Inst cellAt;
        cellAt.op = Op::ConstFn;
        cellAt.type = ptr;
        cellAt.text = tag + ".fn";
        cellAt.loc = c.loc;
        const ValueId cell = emit(std::move(cellAt));
        slotType_[cell] = ptr;
        storePtr(cell, fnVal, c.loc);

        Inst code;
        code.op = Op::ConstFn;
        code.type = ptr;
        code.text = tag + ".thunk";
        code.loc = c.loc;
        const ValueId thunkAddr = emit(std::move(code));

        for (const auto& [name, entry] : classesByKey_) {
            if (entry.decl == nullptr || hasVtable_.count(name) == 0) {
                continue;
            }
            if (name != cls && !classIsSubtypeOf(name, decl->name)) {
                continue;
            }
            if (implementationOf(*entry.decl, method) != impl) {
                continue;   // it overrides the method: keep its own
            }
            // A TABLE THAT IS WRITTEN IS NOT CONSTANT. Left `constant`, the store is undefined and
            // the optimiser is entitled to read the old entry straight through it.
            for (Global& g : out_.module.globals) {
                if (g.name == name + ".vtable") {
                    g.isConst = false;
                }
            }
            Inst table;
            table.op = Op::ConstFn;
            table.type = ptr;
            table.text = name + ".vtable";
            table.loc = c.loc;
            const ValueId base = emit(std::move(table));
            const ValueId at = rawOffset(base, constLong(slot->second * 8, c.loc), c.loc);
            slotType_[at] = ptr;
            storePtr(at, thunkAddr, c.loc);
        }
        return kNoValue;   // a statement, not a value
    }

    // A function by the SYMBOL it links as, rather than by its key. The four functions a generator
    // needs are declared `extern` under names an earlier pass invented, and their keys carry
    // whichever class the declaration was hung on -- the symbol is the part both ends agree about.
    Function* findBySymbol(const std::string& symbol) {
        for (auto& fn : out_.module.functions) {
            if (fn->symbol == symbol || fn->key == symbol) {
                return fn.get();
            }
        }
        return nullptr;
    }

    // The value at a byte offset from a pointer, read as `held`. The counterpart of `storeAt`.
    ValueId loadAt(ValueId base, int64_t offset, const Type* held, SourceLocation loc) {
        const ValueId at = offset == 0 ? base : rawOffset(base, constLong(offset, loc), loc);
        slotType_[at] = held;
        return loadFrom(at, loc);
    }

    ValueId constBool(bool value, SourceLocation loc) {
        Inst b;
        b.op = Op::ConstBool;
        b.type = out_.module.types.boolType();
        b.imm = value ? 1 : 0;
        b.loc = loc;
        return emit(std::move(b));
    }

    // ---- §22.6, generators ----
    //
    // A GENERATOR IS FOUR FUNCTIONS AND A STATE OBJECT. `Sequences.evens(10)` returns an
    // `Iterator<int>`, and an earlier pass has already rewritten it into a factory that builds one
    // and synthesised the iterator class around it; the four raw functions it calls are declared
    // `extern` and were never DEFINED here, so every generator failed to link on `$start`.
    //
    //   $start(self?, args...) -> long   allocate the state, seed it, hand back the handle
    //   $resume(long) -> boolean         run until the next `yield`; false when the body is done
    //   $current(long) -> T              the element the last resume left behind
    //   $free(long) -> void              release the state
    //
    // The state is `{ int step, T current, self?, params..., locals... }`. Every LOCAL lives in it
    // rather than in the frame, because a frame does not survive a suspension -- which is the whole
    // difference between a generator and a method that returns a list.
    void lowerGenerator(const std::string& cls, const ast::MethodDecl& m) {
        Function* start = findBySymbol(m.genSym + "$start");
        Function* resume = findBySymbol(m.genSym + "$resume");
        Function* current = findBySymbol(m.genSym + "$current");
        Function* release = findBySymbol(m.genSym + "$free");
        if (start == nullptr || resume == nullptr || current == nullptr || release == nullptr) {
            gap("generator '" + m.genSym + "' has no state functions to define", m.loc);
            return;
        }
        TypeTable& tt = out_.module.types;
        const Type* i32 = tt.intType(32);
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        const Type* elem = storageTypeOf(m.genElem);

        std::vector<std::pair<std::string, ast::TypeRef>> locals;
        scanGeneratorLocals(m.body, locals);

        // The layout, once, so all four agree about where everything sits.
        std::vector<Field> fields;
        fields.push_back(Field{i32, "step"});
        fields.push_back(Field{elem, "current"});
        const bool hasSelf = !m.isStatic;
        if (hasSelf) {
            fields.push_back(Field{ptr, "self"});
        }
        const size_t argBase = fields.size();
        for (const ast::Param& p : m.params) {
            fields.push_back(Field{typeOf(p.type), p.name});
        }
        const size_t localBase = fields.size();
        for (const auto& [name, type] : locals) {
            fields.push_back(Field{storageTypeOf(classNameOf(resolvedTypeName(type))), name});
        }
        const Type* state = tt.structType(m.genSym + "$genstate", std::move(fields), true);

        auto beginBody = [&](Function& fn) {
            fn_ = &fn;
            fn.symbol.clear();   // it is DEFINED here, so it links by its own name
            here_ = fn.addBlock("entry");
            entryBlock_ = here_;
            allocaAt_ = 0;
            locals_.clear();
            slotType_.clear();
            declaredAs_.clear();
            storage_.clear();
            stringTemps_.clear();
            stringSlots_.clear();
            volatilePointee_.clear();
            volatilePointerSlots_.clear();
            pointee_.clear();
            pointeeOfSlot_.clear();
            clearFieldShapes();
            weakSlotAt_.clear();
            cCallable_.clear();
            paramTypes_.clear();
            labels_.clear();
            loops_.clear();
            handlers_.clear();
            yields_.clear();
            deferred_.clear();
            scoped_.clear();
            unwindObjects_.clear();
            unwindDefers_.clear();
            statics_.clear();
            lazyLocals_.clear();
            selfSlot_ = kNoValue;
            selfClass_ = nullptr;
            selfClassName_.clear();
        };
        auto stateField = [&](ValueId st, size_t index) {
            Inst g;
            g.op = Op::Gep;
            g.type = ptr;
            g.operands.push_back(st);
            g.aggregate = state;
            g.imm = static_cast<int64_t>(index);
            g.text = state->fields[index].name;
            const ValueId at = emit(std::move(g));
            slotType_[at] = state->fields[index].type;
            return at;
        };
        auto handleToState = [&](ValueId handle) {
            Inst as;
            as.op = Op::AddrToPtr;
            as.type = ptr;
            as.operands.push_back(handle);
            const ValueId st = emit(std::move(as));
            pointee_[st] = state;
            return st;
        };

        // --- $start
        {
            BodyState outer = saveBody();
            beginBody(*start);
            std::vector<ValueId> given;
            Block* head = start->block(here_);
            for (uint32_t i = 0; i < start->signature->fields.size(); ++i) {
                const ValueId v = start->addValue(start->signature->fields[i].type,
                                                  ValueOrigin::BlockParam, here_, i,
                                                  start->signature->fields[i].name);
                head->params.push_back(v);
                given.push_back(v);
            }
            const ValueId st = callExternal("__polaron_malloc", ptr, {i64},
                                            {sizeOfClass(state, m.loc)}, m.loc);
            pointee_[st] = state;
            storeInto(stateField(st, 0), constInt(0, 32, m.loc), m.loc);
            for (size_t i = 0; i < given.size() && 2 + i < state->fields.size(); ++i) {
                storeInto(stateField(st, 2 + i), given[i], m.loc);
            }
            Inst asNumber;
            asNumber.op = Op::PtrToAddr;
            asNumber.type = i64;
            asNumber.operands.push_back(st);
            Inst back;
            back.op = Op::Ret;
            back.operands.push_back(emit(std::move(asNumber)));
            emit(std::move(back));
            restoreBody(std::move(outer));
        }

        // --- $current
        {
            BodyState outer = saveBody();
            beginBody(*current);
            const ValueId handle =
                current->addValue(i64, ValueOrigin::BlockParam, here_, 0, "st");
            current->block(here_)->params.push_back(handle);
            const ValueId st = handleToState(handle);
            Inst back;
            back.op = Op::Ret;
            back.operands.push_back(loadFrom(stateField(st, 1), m.loc));
            emit(std::move(back));
            restoreBody(std::move(outer));
        }

        // --- $free
        {
            BodyState outer = saveBody();
            beginBody(*release);
            const ValueId handle =
                release->addValue(i64, ValueOrigin::BlockParam, here_, 0, "st");
            release->block(here_)->params.push_back(handle);
            callExternal("__polaron_free", tt.voidType(), {ptr}, {handleToState(handle)}, m.loc);
            Inst back;
            back.op = Op::Ret;
            emit(std::move(back));
            restoreBody(std::move(outer));
        }

        // --- $resume: the body, as a state machine.
        {
            BodyState outer = saveBody();
            beginBody(*resume);
            const ValueId handle = resume->addValue(i64, ValueOrigin::BlockParam, here_, 0, "st");
            resume->block(here_)->params.push_back(handle);
            const ValueId st = handleToState(handle);
            if (hasSelf) {
                selfSlot_ = stateField(st, 2);
                selfClass_ = named_.count(cls) != 0 ? named_[cls] : nullptr;
                selfClassName_ = cls;
                locals_["this"] = selfSlot_;
            }
            // EVERY NAME IS A FIELD OF THE STATE, not a frame slot. That substitution is the whole
            // of what makes a suspension possible: the frame goes and the state stays.
            for (size_t i = 0; i < m.params.size(); ++i) {
                const ValueId at = stateField(st, argBase + i);
                locals_[m.params[i].name] = at;
                noteName(at, resolvedTypeName(m.params[i].type),
                         pointerDepthOfType(m.params[i].type));
            }
            for (size_t i = 0; i < locals.size(); ++i) {
                const ValueId at = stateField(st, localBase + i);
                locals_[locals[i].first] = at;
                noteName(at, resolvedTypeName(locals[i].second),
                         pointerDepthOfType(locals[i].second));
            }

            genState_ = state;
            genStatePtr_ = st;
            genElem_ = elem;
            genResume_ = resume;
            genSteps_.clear();

            const BlockId body = resume->addBlock(fresh("gen.body"));
            genDone_ = resume->addBlock(fresh("gen.done"));
            // WHERE IT LEFT OFF. Step 0 is the top and -1 is exhausted; a chain of equality tests
            // rather than one `switch`, which is the shape the rest of this lowering uses and the
            // one the backend translates.
            const ValueId step = loadFrom(stateField(st, 0), m.loc);
            resumeAt_ = step;
            branchOn(cmp(Op::CmpEq, step, constInt(0, 32, m.loc), m.loc), body, genDone_);
            // The steps do not exist yet, so their tests are emitted after the body -- `genDone_`
            // stands in for "no case matched" until then and the last one keeps it.
            here_ = body;
            for (const auto& s : m.body.statements) {
                lowerStmt(s.get());
            }
            if (!blockClosed()) {
                // RAN OFF THE END: the sequence is exhausted and stays exhausted.
                storeInto(stateField(st, 0), constInt(-1, 32, m.loc), m.loc);
                gotoIfOpen(genDone_);
            }
            here_ = genDone_;
            Inst back;
            back.op = Op::Ret;
            back.operands.push_back(constBool(false, m.loc));
            emit(std::move(back));

            // ...and now the dispatch, with every step known. Emitted into the entry block's tail
            // by re-branching from a fresh chain: each test is `step == k -> that block`.
            rewireResumeDispatch(*resume, st, state);

            genState_ = nullptr;
            genStatePtr_ = kNoValue;
            genResume_ = nullptr;
            genSteps_.clear();
            restoreBody(std::move(outer));
        }
    }

    // Every local a generator body declares, with its written type: they move into the state
    // object, so the scan has to reach into every block that can hold one.
    void scanGeneratorLocals(const ast::Block& b,
                             std::vector<std::pair<std::string, ast::TypeRef>>& out) {
        for (const auto& s : b.statements) {
            scanGeneratorLocalsIn(s.get(), out);
        }
    }

    void scanGeneratorLocalsIn(const ast::Stmt* s,
                               std::vector<std::pair<std::string, ast::TypeRef>>& out) {
        if (s == nullptr) {
            return;
        }
        if (const auto* v = dynamic_cast<const ast::VarDeclStmt*>(s)) {
            out.push_back({v->name, v->type});
            return;
        }
        if (const auto* b = dynamic_cast<const ast::Block*>(s)) {
            scanGeneratorLocals(*b, out);
            return;
        }
        if (const auto* i = dynamic_cast<const ast::IfStmt*>(s)) {
            scanGeneratorLocals(i->thenBlock, out);
            if (i->elseBlock != nullptr) {
                scanGeneratorLocals(*i->elseBlock, out);
            }
            return;
        }
        if (const auto* w = dynamic_cast<const ast::WhileStmt*>(s)) {
            scanGeneratorLocals(w->body, out);
            return;
        }
        if (const auto* f = dynamic_cast<const ast::ForStmt*>(s)) {
            scanGeneratorLocalsIn(f->init.get(), out);
            scanGeneratorLocals(f->body, out);
            return;
        }
        if (const auto* fe = dynamic_cast<const ast::ForeachStmt*>(s)) {
            scanGeneratorLocals(fe->body, out);
            return;
        }
    }

    // The entry's dispatch, once every `yield` has a block. A chain of `step == k` tests ending in
    // "exhausted", spliced in front of the block the entry used to branch to.
    void rewireResumeDispatch(Function& fn, ValueId st, const Type* state) {
        (void)st;
        (void)state;
        if (genSteps_.empty()) {
            return;
        }
        // The entry's terminator sends 0 to the body and everything else to `genDone_`; the chain
        // replaces that second edge, one test per resume point.
        Block* entry = fn.block(entryBlock_);
        if (entry == nullptr || entry->insts.empty()) {
            return;
        }
        Inst& br = entry->insts.back();
        if (br.op != Op::BrCond || br.edges.size() != 2) {
            return;
        }
        BlockId chain = genDone_;
        for (size_t k = genSteps_.size(); k > 0; --k) {
            const BlockId test = fn.addBlock(fresh("gen.step"));
            here_ = test;
            Inst c;
            c.op = Op::CmpEq;
            c.type = out_.module.types.boolType();
            c.operands.push_back(resumeAt_);
            c.operands.push_back(constInt(static_cast<int64_t>(k), 32, SourceLocation{}));
            const ValueId same = emit(std::move(c));
            Inst pick;
            pick.op = Op::BrCond;
            pick.operands.push_back(same);
            pick.edges.push_back(Edge{genSteps_[k - 1], {}});
            pick.edges.push_back(Edge{chain, {}});
            emit(std::move(pick));
            chain = test;
        }
        br.edges[1] = Edge{chain, {}};
    }

    // ---- §20.2, `async` ----
    //
    // TWO FUNCTIONS, and the split is the whole feature. The one the program calls builds a task,
    // saves the arguments where the body can find them, hands the pair to the scheduler and RETURNS
    // AT ONCE with the task in hand. The body lives in `$resume`, which the scheduler calls; a
    // `return` in it completes the task rather than returning a value to anybody.
    //
    // The state object is `{ int step, ptr task, args... }`. `step` is zero here because this is
    // the form with no `await` inside -- a body that suspends needs the step to say where it left
    // off, and that is the state machine, which is not built yet.
    void lowerAsyncMethod(const std::string& cls, const ast::MethodDecl& m, Function& wrapper) {
        Function* body = out_.module.find(cls + "." + m.name + "$resume");
        if (body == nullptr) {
            return;
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i32 = tt.intType(32);
        const Type* i64 = tt.intType(64);
        std::vector<Field> stateFields;
        Field step;
        step.type = i32;
        step.name = "step";
        stateFields.push_back(step);
        Field task;
        task.type = ptr;
        task.name = "task";
        stateFields.push_back(task);
        if (!m.isStatic) {
            Field self;
            self.type = ptr;
            self.name = "this";
            stateFields.push_back(self);
        }
        for (const ast::Param& p : m.params) {
            Field f;
            f.type = typeOf(p.type);
            f.name = p.name;
            stateFields.push_back(f);
        }
        // §20.2: WHERE THE HANDLE OF THE TASK THIS ONE IS WAITING FOR IS KEPT, so the resume can
        // read the answer after the suspension. ONE slot, not one per `await`: a body can only be
        // suspended at a single point at a time, and which point that is is what `step` records.
        Field awaited;
        awaited.type = i64;
        awaited.name = "awaited";
        const int64_t awaitedAt = static_cast<int64_t>(stateFields.size());
        stateFields.push_back(awaited);
        // ...AND EVERY LOCAL WITH IT, because a suspension RETURNS. Whatever a frame slot held is
        // gone when the scheduler calls this function again, so a variable that is written before an
        // `await` and read after it cannot live in one. `async_loop` sums 1..5 across a suspension
        // and printed `loopsum=32774` -- the accumulator, read out of a fresh frame.
        //
        // ALL of them, not the ones that demonstrably cross a suspension: the narrower set needs a
        // liveness analysis across suspension points, and the cost of the wider one is state-object
        // bytes. This is the same list a generator's locals go into, collected by the same walk --
        // one mechanism for the two constructs that resume, rather than two that can disagree.
        std::vector<std::pair<std::string, ast::TypeRef>> scanned;
        scanGeneratorLocals(m.body, scanned);
        // A LOCAL WHOSE TYPE THIS PASS CANNOT NAME IS LEFT IN THE FRAME. A field of no type reaches
        // the backend as a struct member the type table cannot spell, and the compiler dies there
        // with no diagnostic at all -- which is what `async_value_struct` did.
        std::vector<std::pair<std::string, ast::TypeRef>> carried;
        for (auto& entry : scanned) {
            if (typeOf(entry.second) != nullptr) {
                carried.push_back(entry);
            }
        }
        const int64_t localBase = static_cast<int64_t>(stateFields.size());
        for (const auto& [name, declared] : carried) {
            Field f;
            // A VALUE AGGREGATE IS CARRIED BY ITS ADDRESS, and the object goes to the heap.
            //
            // Everywhere in this lowering a local of class type is the ADDRESS of its storage, so
            // the state field that stands in for it has to be an address too -- a field of the
            // struct's own type is a different shape, and `allocaFor` would decline to reuse it and
            // make a frame slot beside it. `new Vec(n)` in an async body is therefore promoted to
            // the heap (see `lowerNew`): its frame home belongs to one resume invocation and is
            // gone by the next, so the address the state kept would point at a dead frame.
            f.type = isValueClass(resolvedTypeName(declared)) ? ptr : typeOf(declared);
            f.name = name;
            stateFields.push_back(f);
        }
        // SCRATCH, for values that are not variables. `out = base + await val(5)` loads `base`,
        // then suspends, then adds -- and the loaded value is an SSA temporary in a block the
        // resume does not come from, so its use is not dominated by its definition and the module
        // does not verify. The same shape appears in `await a + await b + await c` and in a call
        // whose earlier argument is evaluated before a later one awaits.
        //
        // A local can be carried because it HAS a name; a temporary has to be spilled at the point
        // it would cross and reloaded on the other side. Sixty-four is the other path's number and
        // costs nothing when unused: the state object is allocated per invocation, and a slot no
        // one writes is a slot no one reads.
        const int64_t scratchBase = static_cast<int64_t>(stateFields.size());
        for (int i = 0; i < kAsyncScratch; ++i) {
            Field s;
            s.type = i64;
            s.name = "scratch" + std::to_string(i);
            stateFields.push_back(s);
        }
        const Type* stateTy =
            tt.structType(cls + "." + m.name + "$state", std::move(stateFields), true);

        // ---- the body, reading its arguments out of the state ----
        if (body->blocks.empty()) {
            BodyState outer = saveBody();
            fn_ = body;
            here_ = body->addBlock("entry");
            entryBlock_ = here_;
            allocaAt_ = 0;
            locals_.clear();
            slotType_.clear();
            declaredAs_.clear();
            storage_.clear();
            stringTemps_.clear();
            stringSlots_.clear();
            volatilePointee_.clear();
            volatilePointerSlots_.clear();
            pointee_.clear();
            paramTypes_.clear();
            pointeeOfSlot_.clear();
            labels_.clear();
            abstained_.clear();
            nextLabel_.clear();
            loops_.clear();
            handlers_.clear();
            statics_.clear();
        lazyLocals_.clear();
            scanLabels(m.body);
            const ValueId statePtr =
                body->addValue(ptr, ValueOrigin::BlockParam, here_, 0, "state");
            body->block(here_)->params.push_back(statePtr);
            pointee_[statePtr] = stateTy;
            // THE TASK HANDLE IS WHAT A `return` COMPLETES, and it is read once here rather than
            // at every return: a body may have several, and each would otherwise reload it.
            Inst taskAt;
            taskAt.op = Op::Gep;
            taskAt.type = ptr;
            taskAt.operands.push_back(statePtr);
            taskAt.aggregate = stateTy;
            taskAt.imm = 1;
            taskAt.text = "task";
            const ValueId taskSlot = emit(std::move(taskAt));
            slotType_[taskSlot] = ptr;
            asyncTask_ = loadFrom(taskSlot, m.loc);
            int64_t at = 2;
            if (!m.isStatic) {
                Inst self;
                self.op = Op::Gep;
                self.type = ptr;
                self.operands.push_back(statePtr);
                self.aggregate = stateTy;
                self.imm = at++;
                self.text = "this";
                const ValueId slot = emit(std::move(self));
                slotType_[slot] = ptr;
                noteName(slot, cls);
                locals_["this"] = slot;
                selfSlot_ = slot;
            }
            selfClass_ = named_.count(cls) != 0 ? named_[cls] : nullptr;
            selfClassName_ = cls;
            for (const ast::Param& p : m.params) {
                Inst g;
                g.op = Op::Gep;
                g.type = ptr;
                g.operands.push_back(statePtr);
                g.aggregate = stateTy;
                g.imm = at++;
                g.text = p.name;
                const ValueId slot = emit(std::move(g));
                slotType_[slot] = typeOf(p.type);
                noteName(slot, resolvedTypeName(p.type), pointerDepthOfType(p.type));
                locals_[p.name] = slot;
                paramTypes_[p.name] = typeOf(p.type);
            }
            // AN ESCAPING THROW FAILS THE TASK; IT DOES NOT LEAVE THE THREAD (§21).
            //
            // This body runs on a worker. An exception that walks out of it has no handler anywhere
            // above -- the code that cares is whoever awaits the task, in another frame entirely --
            // so letting it go takes the process down instead of arriving where it was expected.
            // What the language says happens is that the task COMPLETES WITH AN ERROR and `await`
            // re-throws it in the awaiter, which is what `rethrowFailedTask` is already there for.
            //
            // A handler pushed around the whole body is exactly that, and it costs nothing new: the
            // `throw` lowering, the call lowering and the defer teardown all already route to
            // `handlers_.back()`. Which is also why the `defer` in `async_defer_throw` runs -- the
            // landing block emits the pending teardown before it records the error, the same as any
            // other handler.
            const BlockId guard = fn_->addBlock(fresh("async.guard"));
            const size_t outerUnwindObjects = unwindObjects_.size();
            const size_t outerUnwindDefers = unwindDefers_.size();
            handlers_.push_back(Handler{guard, scoped_.size(), deferred_.size()});

            // §20.2: THE BODY IS A STATE MACHINE, and this is where it is entered.
            //
            // `await` inside an async body must SUSPEND -- register this function as the awaited
            // task's continuation and return, so the worker is freed -- and not block. Blocking is
            // what this did, through `__polaron_task_wait`, and with a bounded pool it is the
            // classic deadlock: every worker asleep on a task that needs a worker to run.
            //
            // The body therefore cannot start at the entry block. The entry reads `step` and jumps
            // to wherever the last suspension left off; the body proper begins after it. The chain
            // of tests is spliced in at the end, once every `await` has its resume block -- the
            // same shape `rewireResumeDispatch` gives a generator, for the same reason.
            const BlockId bodyStart = fn_->addBlock(fresh("async.body"));
            const BlockId suspend = fn_->addBlock(fresh("async.suspend"));
            const ValueId stepSlot = [&] {
                Inst g;
                g.op = Op::Gep;
                g.type = ptr;
                g.operands.push_back(statePtr);
                g.aggregate = stateTy;
                g.imm = 0;
                g.text = "step";
                const ValueId slot = emit(std::move(g));
                slotType_[slot] = i32;
                return slot;
            }();
            const ValueId awaitedSlot = [&] {
                Inst g;
                g.op = Op::Gep;
                g.type = ptr;
                g.operands.push_back(statePtr);
                g.aggregate = stateTy;
                g.imm = awaitedAt;
                g.text = "awaited";
                const ValueId slot = emit(std::move(g));
                slotType_[slot] = i64;
                return slot;
            }();
            // The carried locals, bound to their slots in the state before a single statement runs,
            // so a declaration finds the slot already there and writes into it (see `allocaFor`,
            // which reuses a slot of matching shape).
            for (size_t i = 0; i < carried.size(); ++i) {
                Inst g;
                g.op = Op::Gep;
                g.type = ptr;
                g.operands.push_back(statePtr);
                g.aggregate = stateTy;
                g.imm = localBase + static_cast<int64_t>(i);
                g.text = carried[i].first;
                g.loc = m.loc;
                const ValueId slot = emit(std::move(g));
                slotType_[slot] = isValueClass(resolvedTypeName(carried[i].second))
                                      ? ptr
                                      : typeOf(carried[i].second);
                noteName(slot, resolvedTypeName(carried[i].second),
                         pointerDepthOfType(carried[i].second));
                locals_[carried[i].first] = slot;
            }
            const ValueId resumedAt = loadFrom(stepSlot, m.loc);
            const BlockId entryOfBody = entryBlock_;
            gotoIfOpen(bodyStart);

            // A SUSPENSION SIMPLY RETURNS. The scheduler calls this function again when the awaited
            // task completes, and the entry chain sends control back to where it stopped.
            here_ = suspend;
            Inst park;
            park.op = Op::Ret;
            park.loc = m.loc;
            emit(std::move(park));

            here_ = bodyStart;
            asyncStatePtr_ = statePtr;
            asyncStepSlot_ = stepSlot;
            asyncAwaitedSlot_ = awaitedSlot;
            asyncSuspend_ = suspend;
            asyncResumeKey_ = body->key;
            asyncSteps_.clear();
            asyncStateObj_ = statePtr;
            asyncStateTy_ = stateTy;
            asyncScratchBase_ = scratchBase;
            asyncScratchTop_ = 0;

            for (const auto& s : m.body.statements) {
                lowerStmt(s.get());
            }
            if (!blockClosed()) {
                completeTask(kNoValue, m.loc);
                Inst ret;
                ret.op = Op::Ret;
                ret.loc = m.loc;
                emit(std::move(ret));
            }
            handlers_.pop_back();

            here_ = guard;
            const ValueId caught = fn_->addValue(ptr, ValueOrigin::Instruction, guard, 0, "exc");
            Inst land;
            land.op = Op::Landing;
            land.result = caught;
            land.type = ptr;
            land.loc = m.loc;
            fn_->block(guard)->insts.push_back(std::move(land));
            // ...AND EACH ONE GUARDED, which is the difference between running the teardown and
            // running it twice. The `throw` that got here already ran the defers it had passed --
            // that is what a `throw` does on the way out -- so an unguarded copy here printed
            // `defer ran` a second time. The flag each site carries is what makes the two paths
            // agree: whichever arrives first does the work, the other finds it done. The `try`
            // lowering says the same thing in the same words a few hundred lines below.
            {
                const std::vector<ScopedObject> unwound(unwindObjects_.begin() + outerUnwindObjects,
                                                        unwindObjects_.end());
                const std::vector<DeferSite> deferredHere(unwindDefers_.begin() + outerUnwindDefers,
                                                          unwindDefers_.end());
                for (auto it = deferredHere.rbegin(); it != deferredHere.rend(); ++it) {
                    runOneDefer(*it, /*guarded=*/true, m.loc);
                }
                destroyEach(unwound, m.loc);
            }
            Inst asAddr;
            asAddr.op = Op::PtrToAddr;
            asAddr.type = i64;
            asAddr.operands.push_back(asyncTask_);
            asAddr.loc = m.loc;
            Inst carrier;
            carrier.op = Op::PtrToAddr;
            carrier.type = i64;
            carrier.operands.push_back(caught);
            carrier.loc = m.loc;
            callExternal("__polaron_task_complete_error", tt.voidType(), {i64, i64},
                         {emit(std::move(asAddr)), emit(std::move(carrier))}, m.loc);
            Inst leave;
            leave.op = Op::Ret;
            leave.loc = m.loc;
            emit(std::move(leave));

            // THE ENTRY'S DISPATCH, now that every `await` has a resume block. A chain of
            // `step == k` tests in front of the jump the entry already makes to the body, so an
            // invocation with step zero -- the first -- falls through to the beginning.
            if (!asyncSteps_.empty()) {
                // THE BLOCK IS LOOKED UP AGAIN AFTERWARDS, never held across the loop. `addBlock`
                // grows the function's block vector and can move it, so a `Block*` taken before
                // the chain is built points at freed storage by the time the chain is done -- and
                // writing the new edge through it is a segfault in the compiler with no diagnostic
                // at all. It showed only when a body happened to allocate enough to force the
                // reallocation: a value struct declared beside the `await` was enough.
                BlockId chain = bodyStart;
                bool rewire = false;
                if (const Block* entry = fn_->block(entryOfBody);
                    entry != nullptr && !entry->insts.empty() &&
                    entry->insts.back().op == Op::Br) {
                    rewire = true;
                }
                for (size_t k = rewire ? asyncSteps_.size() : 0; k > 0; --k) {
                    const BlockId test = fn_->addBlock(fresh("async.step"));
                    here_ = test;
                    Inst c;
                    c.op = Op::CmpEq;
                    c.type = tt.boolType();
                    c.operands.push_back(resumedAt);
                    c.operands.push_back(constInt(static_cast<int64_t>(k), 32, m.loc));
                    c.loc = m.loc;
                    Inst pick;
                    pick.op = Op::BrCond;
                    pick.operands.push_back(emit(std::move(c)));
                    pick.edges.push_back(Edge{asyncSteps_[k - 1], {}});
                    pick.edges.push_back(Edge{chain, {}});
                    pick.loc = m.loc;
                    emit(std::move(pick));
                    chain = test;
                }
                if (rewire) {
                    if (Block* entry = fn_->block(entryOfBody);
                        entry != nullptr && !entry->insts.empty() &&
                        entry->insts.back().op == Op::Br) {
                        entry->insts.back().edges[0] = Edge{chain, {}};
                    }
                }
            }
            asyncStatePtr_ = kNoValue;
            asyncStepSlot_ = kNoValue;
            asyncAwaitedSlot_ = kNoValue;
            asyncSuspend_ = kNoBlock;
            asyncResumeKey_.clear();
            asyncSteps_.clear();
            asyncStateObj_ = kNoValue;
            asyncStateTy_ = nullptr;
            asyncScratchTop_ = 0;

            asyncTask_ = kNoValue;
            restoreBody(std::move(outer));
        }

        // ---- the wrapper: make the task, save the arguments, schedule, hand back a `Task<T>` ----
        if (!wrapper.blocks.empty()) {
            return;
        }
        BodyState outer = saveBody();
        fn_ = &wrapper;
        here_ = wrapper.addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        declaredAs_.clear();
        pointee_.clear();
        std::vector<ValueId> incoming;
        uint32_t index = 0;
        if (wrapper.signature != nullptr) {
            for (const Field& p : wrapper.signature->fields) {
                const std::string name =
                    index < wrapper.params.size() ? wrapper.params[index].name : std::string();
                const ValueId v =
                    wrapper.addValue(p.type, ValueOrigin::BlockParam, here_, index, name);
                wrapper.block(here_)->params.push_back(v);
                incoming.push_back(v);
                ++index;
            }
        }
        const ValueId handle = callExternal("__polaron_task_new", i64, {}, {}, m.loc);
        const int64_t bytes =
            stateTy->facts.size > 0 ? static_cast<int64_t>(stateTy->facts.size) : 64;
        const ValueId state =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(bytes, m.loc)}, m.loc);
        pointee_[state] = stateTy;
        auto put = [&](int64_t slot, const char* name, const Type* held, ValueId what) {
            Inst g;
            g.op = Op::Gep;
            g.type = ptr;
            g.operands.push_back(state);
            g.aggregate = stateTy;
            g.imm = slot;
            g.text = name;
            g.loc = m.loc;
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(what);
            st.operands.push_back(emit(std::move(g)));
            st.loc = m.loc;
            emit(std::move(st));
            (void)held;
        };
        put(0, "step", i32, constInt(0, 32, m.loc));
        Inst asPtr;
        asPtr.op = Op::AddrToPtr;
        asPtr.type = ptr;
        asPtr.operands.push_back(handle);
        asPtr.loc = m.loc;
        put(1, "task", ptr, emit(std::move(asPtr)));
        for (size_t i = 0; i < incoming.size(); ++i) {
            put(static_cast<int64_t>(2 + i), "arg", nullptr, incoming[i]);
        }
        callExternal("__polaron_schedule", tt.voidType(), {ptr, ptr},
                     {functionAddress(body->key, m.loc), state}, m.loc);

        // ...and the `Task<T>` the caller holds, whose `h` field is that same handle.
        const std::string taskCls =
            resolveClassKey(ast::mangleGeneric("Task", {resolvedTypeName(m.returnType)}));
        const Type* taskShape = named_.count(taskCls) != 0 ? named_.at(taskCls) : nullptr;
        ValueId obj = nullPointer(m.loc);
        if (taskShape != nullptr) {
            const int64_t size =
                taskShape->facts.size > 0 ? static_cast<int64_t>(taskShape->facts.size) : 16;
            obj = callExternal("__polaron_malloc", ptr, {i64}, {constLong(size, m.loc)}, m.loc);
            callExternal("memset", ptr, {ptr, i32, i64},
                         {obj, constInt(0, 32, m.loc), constLong(size, m.loc)}, m.loc);
            pointee_[obj] = taskShape;
            noteName(obj, taskCls);
            if (const Function* ctor = resolveKey(taskCls + "." + taskCls)) {
                emitCall(ctor, {obj}, m.loc);
            }
            if (const ValueId slot = fieldAddress(obj, "h", m.loc); slot != kNoValue) {
                Inst st;
                st.op = Op::Store;
                st.operands.push_back(handle);
                st.operands.push_back(slot);
                st.loc = m.loc;
                emit(std::move(st));
            }
        }
        Inst ret;
        ret.op = Op::Ret;
        ret.operands.push_back(obj);
        ret.loc = m.loc;
        emit(std::move(ret));
        restoreBody(std::move(outer));
    }

    // The awaited task's error, re-thrown where the awaiter can catch it.
    void rethrowFailedTask(ValueId handle, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const ValueId err =
            callExternal("__polaron_task_error", i64, {i64}, {handle}, loc);
        Inst bad;
        bad.op = Op::CmpNe;
        bad.type = tt.boolType();
        bad.operands.push_back(err);
        bad.operands.push_back(constLong(0, loc));
        bad.loc = loc;
        const BlockId fail = fn_->addBlock("await.throw");
        const BlockId ok = fn_->addBlock("await.ok");
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(bad)));
        br.edges.push_back(Edge{fail, {}});
        br.edges.push_back(Edge{ok, {}});
        br.loc = loc;
        emit(std::move(br));
        here_ = fail;
        Inst asPtr;
        asPtr.op = Op::AddrToPtr;
        asPtr.type = tt.ptrType();
        asPtr.operands.push_back(err);
        asPtr.loc = loc;
        // ...AND IT IS CAUGHT BY THE `try` AROUND THE `await`. A failed task re-throws in the
        // AWAITER's frame, which is the whole point of carrying the error rather than letting it out
        // of the worker -- so it has to reach the handler the awaiter wrote, exactly as a `throw`
        // written there would. Emitted with no unwind edge it left `main` instead, and
        // `async_defer_throw` -- which catches it two lines below the `await` -- printed nothing.
        emitRaise(emit(std::move(asPtr)), loc);
        here_ = ok;
    }

    // A `return` inside an async body completes the TASK. The value crosses as one word, which is
    // what the runtime's completion slot holds.
    void completeTask(ValueId value, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        Inst asAddr;
        asAddr.op = Op::PtrToAddr;
        asAddr.type = i64;
        asAddr.operands.push_back(asyncTask_);
        asAddr.loc = loc;
        callExternal("__polaron_task_complete", tt.voidType(), {i64, i64},
                     {emit(std::move(asAddr)),
                      value == kNoValue ? constLong(0, loc) : asWord(value, loc)},
                     loc);
    }

    // ---- §30, taking a class away while the program runs ----
    //
    // WHICH CLASSES ARE UNIMPORTABLE IS NOT WRITTEN ON THE DECLARATION. A class does not declare
    // itself removable -- it BECOMES removable because somewhere in the program a statement asks
    // for it to be removed. So the set is collected from the statements, once, before anything is
    // lowered: the alive flag, the live-instance counter and the guard on every use all depend on
    // knowing it, and all three are emitted long before the `unimport` itself is reached.
    //
    // The cost of getting this wrong in the cheap direction is a load and a branch on every use of
    // every class in the program, which is why it is a set and not a flag on all of them.
    // Every method some `X.methods.replace("m", ...)` names (§32.8). Collected from the STATEMENTS,
    // because being replaceable is not written on a declaration -- the same shape `unimport` has,
    // and for the same reason: a class does not say it can be taken away, a statement takes it.
    // WHICH CLASSES CARRY A VTABLE POINTER, which is a question about the LAYOUT and not about
    // dispatch.
    //
    // Every reference class was getting the pointer here, and the other backend gives it only to a
    // class in some inheritance or interface relationship. Eight bytes in front of every object of
    // every class that has no subtype, and -- far worse than the size -- every field of such a
    // class at a different offset in the two backends. `narrow_address` names it exactly:
    //
    //     %class.RealModePointer = type { i16, i16 }          the trusted path
    //     %class.RealModePointer = type { ptr, i16, i16 }     this one
    //
    // Two programs cannot agree about that and both be right, and the ABI is not the backend's to
    // choose: a `.polb` built by one and consumed by the other reads every field from the wrong
    // place. That the corpus stayed green throughout says only that each backend is consistent with
    // ITSELF, which is exactly the blindness a single-program differential has.
    void collectPolymorphic() {
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    // Recorded under the spelling the DECLARATION uses, and looked up under both
                    // that and the resolved key: a base may be named `Shape` here and keyed
                    // `art.shapes.Shape` there, and a set that holds only one of the two answers
                    // "no" to half the questions asked of it.
                    if (!c.superclass.empty()) {
                        bases_.insert(c.superclass);
                        bases_.insert(resolveClassKey(c.superclass));
                    }
                    for (const std::string& i : c.interfaces) {
                        bases_.insert(i);
                        bases_.insert(resolveClassKey(i));
                    }
                }
            }
        }
    }

    // A BUNDLE IS COMPILED INTO AN OPEN WORLD. Inside a program, "nothing extends this" is a
    // whole-program answer and the layout can act on it; inside `polc --lib` the classes that will
    // extend a public class do not exist yet, so every public, non-final, non-sealed class lays
    // itself out as though something will. The trusted path reasons identically -- see the comment
    // above its own `bases` -- and the two have to, or a library and its consumer disagree about
    // where a field is.
    bool carriesVtable(const ast::ClassDecl& c) const {
        if (c.isStruct || c.isRecord || c.isUnion || c.isLayout || c.isTransformer) {
            return false;
        }
        if (!c.superclass.empty() || !c.interfaces.empty() || c.isAbstract || c.isInterface) {
            return true;
        }
        if (bases_.count(c.name) != 0 || bases_.count(keyOfClass(c)) != 0) {
            return true;
        }
        // A REPLACEABLE METHOD IS DISPATCHED, and a dispatch needs somewhere to dispatch from.
        // `Dog.methods.replace("bark", ...)` writes into a slot; a class with no table has no slot,
        // and the write went to whatever sat at offset zero.
        for (const ast::MemberPtr& m : c.members) {
            const auto* md = dynamic_cast<const ast::MethodDecl*>(m.get());
            if (md != nullptr && replaceable_.count(md->name) != 0) {
                return true;
            }
        }
        if (bundles_.library && c.visibility == "public" && !c.isFinal && !c.isSealed) {
            return true;
        }
        return false;
    }

    void collectReplaceable() {
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    for (const ast::MemberPtr& m : c.members) {
                        if (const auto* md = dynamic_cast<const ast::MethodDecl*>(m.get())) {
                            scanReplace(md->body);
                        } else if (const auto* k =
                                       dynamic_cast<const ast::ConstructorDecl*>(m.get())) {
                            scanReplace(k->body);
                        }
                    }
                }
            }
        }
    }

    void scanReplace(const ast::Block& body) {
        for (const auto& s : body.statements) {
            scanReplaceIn(s.get());
        }
    }

    void scanReplaceIn(const ast::Stmt* s) {
        if (s == nullptr) {
            return;
        }
        if (const auto* es = dynamic_cast<const ast::ExprStmt*>(s)) {
            if (const auto* call = dynamic_cast<const ast::CallExpr*>(es->expr.get())) {
                if (const auto* rp = dynamic_cast<const ast::MemberExpr*>(call->callee.get());
                    rp != nullptr && rp->member == "replace" && call->args.size() == 2) {
                    if (const auto* tbl = dynamic_cast<const ast::MemberExpr*>(rp->object.get());
                        tbl != nullptr && tbl->member == "methods") {
                        if (const auto* lit =
                                dynamic_cast<const ast::StringLiteralExpr*>(call->args[0].get())) {
                            replaceable_.insert(lit->value);
                        }
                        // ...AND WHOSE TABLE IT IS. The method name decides which slots exist; the
                        // CLASS decides whether the table can live in read-only memory, because a
                        // `replace` writes into it. See `rewritesItsVtable`.
                        std::string owner;
                        if (flatten(tbl->object.get(), &owner)) {
                            patched_.insert(cgutil::baseType(owner));
                        }
                    }
                }
            }
            return;
        }
        if (const auto* b = dynamic_cast<const ast::Block*>(s)) {
            scanReplace(*b);
            return;
        }
        if (const auto* i = dynamic_cast<const ast::IfStmt*>(s)) {
            scanReplace(i->thenBlock);
            if (i->elseBlock != nullptr) {
                scanReplace(*i->elseBlock);
            }
            return;
        }
        if (const auto* w = dynamic_cast<const ast::WhileStmt*>(s)) {
            scanReplace(w->body);
            return;
        }
        if (const auto* f = dynamic_cast<const ast::ForStmt*>(s)) {
            scanReplace(f->body);
            return;
        }
        if (const auto* fe = dynamic_cast<const ast::ForeachStmt*>(s)) {
            scanReplace(fe->body);
            return;
        }
    }

    void collectUnimportable() {
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    for (const ast::MemberPtr& m : c.members) {
                        if (const auto* md = dynamic_cast<const ast::MethodDecl*>(m.get())) {
                            scanUnimport(md->body);
                        } else if (const auto* k = dynamic_cast<const ast::ConstructorDecl*>(m.get())) {
                            scanUnimport(k->body);
                        } else if (const auto* d = dynamic_cast<const ast::DestructorDecl*>(m.get())) {
                            scanUnimport(d->body);
                        }
                    }
                }
            }
        }
    }

    void scanUnimport(const ast::Block& body) {
        for (const auto& s : body.statements) {
            scanUnimportStmt(s.get());
        }
    }

    void scanUnimportStmt(const ast::Stmt* st) {
        if (st == nullptr) {
            return;
        }
        if (const auto* u = dynamic_cast<const ast::UnimportStmt*>(st)) {
            for (const std::string& t : unimportTargets(*u)) {
                unimportable_.insert(t);
            }
            return;
        }
        if (const auto* rv = dynamic_cast<const ast::ReimportValidateStmt*>(st)) {
            unimportable_.insert(cgutil::baseType(rv->target));
            if (rv->expecting != nullptr) {
                scanUnimport(*rv->expecting);
            }
            if (rv->onFailure != nullptr) {
                scanUnimport(*rv->onFailure);
            }
            return;
        }
        if (const auto* c = dynamic_cast<const ast::CascadeStmt*>(st)) {
            if (c->op == ast::CascadeOpKind::Unimport) {
                for (const std::string& t : cascadeUnimportTargets(c->typeName)) {
                    unimportable_.insert(t);
                }
            }
            return;
        }
        // ...and everything that CONTAINS statements, because an `unimport` inside a `try` is the
        // ordinary way to write one: the whole point is that using the class afterwards throws.
        // `unimport X expecting { ... }` IS AN EXPRESSION, so it hides in an initialiser rather
        // than standing on its own as a statement. Missed here, the class never enters the set and
        // the guard that makes using it afterwards throw is never emitted anywhere.
        if (const auto* vd = dynamic_cast<const ast::VarDeclStmt*>(st)) { scanExprUnimport(vd->init.get()); return; }
        if (const auto* es = dynamic_cast<const ast::ExprStmt*>(st)) { scanExprUnimport(es->expr.get()); return; }
        if (const auto* as = dynamic_cast<const ast::AssignStmt*>(st)) { scanExprUnimport(as->value.get()); return; }
        if (const auto* rs = dynamic_cast<const ast::ReturnStmt*>(st)) { scanExprUnimport(rs->value.get()); return; }
        if (const auto* b = dynamic_cast<const ast::Block*>(st)) { scanUnimport(*b); return; }
        if (const auto* i = dynamic_cast<const ast::IfStmt*>(st)) {
            scanUnimport(i->thenBlock);
            if (i->elseBlock != nullptr) { scanUnimport(*i->elseBlock); }
            return;
        }
        if (const auto* w = dynamic_cast<const ast::WhileStmt*>(st)) { scanUnimport(w->body); return; }
        if (const auto* d = dynamic_cast<const ast::DoWhileStmt*>(st)) { scanUnimport(d->body); return; }
        if (const auto* f = dynamic_cast<const ast::ForStmt*>(st)) { scanUnimport(f->body); return; }
        if (const auto* f = dynamic_cast<const ast::ForeachStmt*>(st)) { scanUnimport(f->body); return; }
        if (const auto* s = dynamic_cast<const ast::SynchronizedStmt*>(st)) { scanUnimport(s->body); return; }
        if (const auto* t = dynamic_cast<const ast::TryStmt*>(st)) {
            scanUnimport(t->body);
            for (const auto& c : t->catches) { scanUnimport(c.body); }
            if (t->finallyBlock != nullptr) { scanUnimport(*t->finallyBlock); }
            return;
        }
        if (const auto* sw = dynamic_cast<const ast::SwitchStmt*>(st)) {
            for (const auto& c : sw->cases) { scanUnimport(c.body); }
            if (sw->defaultBody != nullptr) { scanUnimport(*sw->defaultBody); }
            return;
        }
        if (const auto* m = dynamic_cast<const ast::MatchStmt*>(st)) {
            for (const auto& c : m->cases) { scanUnimport(c.body); }
            if (m->defaultBody != nullptr) { scanUnimport(*m->defaultBody); }
            return;
        }
    }

    void scanExprUnimport(const ast::Expr* e) {
        if (const auto* ux = dynamic_cast<const ast::UnimportExpr*>(e)) {
            unimportable_.insert(cgutil::baseType(ux->target));
            if (ux->expecting != nullptr) {
                scanUnimport(*ux->expecting);
            }
        }
    }

    // The individual types one `unimport` names (§30.1): the target itself, or every type in a
    // namespace (granularity 1) or a bundle (granularity 2).
    std::vector<std::string> unimportTargets(const ast::UnimportStmt& u) const {
        std::vector<std::string> out;
        if (u.granularity == 0) {
            out.push_back(cgutil::baseType(u.target));
            return out;
        }
        for (const ast::Bundle& b : ast_.bundles) {
            if (u.granularity == 2 && b.name != u.target) {
                continue;
            }
            for (const ast::Namespace& ns : b.namespaces) {
                if (u.granularity == 1 && ns.name != u.target) {
                    continue;
                }
                for (const ast::ClassDecl& c : ns.classes) {
                    out.push_back(c.name);
                }
                for (const ast::EnumDecl& e : ns.enums) {
                    out.push_back(e.name);
                }
            }
        }
        return out;
    }

    // `cascade unimport X` (§37.1): X, every subclass of it, and every monomorphization -- the
    // things that would still be reachable if only X itself went.
    std::vector<std::string> cascadeUnimportTargets(const std::string& x) const {
        std::vector<std::string> out{x};
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    if (c.name == x) {
                        continue;
                    }
                    if (c.superclass == x || c.name.rfind(x + "$", 0) == 0) {
                        out.push_back(c.name);
                    }
                }
            }
        }
        return out;
    }

    // IS THE CLASS STILL THERE. One word per unimportable class, starting at 1 and set to 0 by the
    // `unimport` that takes it away. Read at every use of the class, which is what turns "its code
    // was ripped from RAM" into an exception a program can catch rather than a jump into int3.
    std::string aliveFlag(const std::string& cls) {
        const std::string name = cls + ".__alive";
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                return name;
            }
        }
        Global g;
        g.name = name;
        g.type = out_.module.types.intType(32);
        g.linkage = Linkage::Internal;
        g.zeroInit = false;
        g.initInt = 1;
        out_.module.globals.push_back(std::move(g));
        return name;
    }

    // ---- `region class` (§17, region classes) ----
    //
    // EVERY INSTANCE OF THE CLASS COMES FROM ONE ARENA and the arena holds nothing else. That
    // totality is the feature: it is what lets `unimport` answer "is any A alive?" by asking the
    // region, what lets every instance be walked linearly, and what lets an `A*` be a 32-bit offset
    // from the arena's base. A single instance born anywhere else closes all three, which is why
    // `new A() on heap` and `new A() in region other` are refused rather than tolerated.
    //
    // Not lowered at all here, a region class was an ordinary class: its instances went on the
    // stack, the block's closing brace destroyed them, and `region_class_outlives_block` printed
    // its destructor line in the middle of the program rather than at the `delete` that asked for
    // it. The design says a local A "lives until it is deleted or the region dies -- not until the
    // block exits", and nothing here was saying it.
    bool livesInClassArena(const std::string& cls) const {
        const ast::ClassDecl* decl = findClass(cls);
        return decl != nullptr && decl->isRegionClass;
    }

    // THE FAMILY ROOT: the topmost class in the chain that is still a region class. `abstract region
    // class AstNode` declares a region shared by everything beneath it, so `Ident` and `Call` must
    // reach the SAME block -- one arena, one lifetime, which is the phase-arena case a single-type
    // region cannot express. A pure region class is its own root.
    std::string regionFamilyRoot(const std::string& cls) const {
        std::string root = cls;
        std::string at = cls;
        for (int hops = 0; hops < 64; ++hops) {
            const ast::ClassDecl* decl = findClass(at);
            if (decl == nullptr) {
                break;
            }
            if (decl->isRegionClass) {
                root = at;
            }
            const std::string up = classNameOf(decl->superclass);
            if (up.empty() || up == at) {
                break;
            }
            at = up;
        }
        return root;
    }

    // The family's arena, reserved on FIRST USE rather than by a static constructor, because bare
    // metal runs none. One contiguous reservation and never a chain: a narrow `A*` is an offset
    // from the base, and offsets are unique only while there is ONE base.
    // The global that holds one family's arena, as an address. Made on demand: a program that
    // declares a region class and never builds one of its instances should carry no reservation.
    ValueId arenaSlot(const std::string& root, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const std::string gname = root + ".region";
        bool known = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == gname) {
                known = true;
                break;
            }
        }
        if (!known) {
            Global g;
            g.name = gname;
            g.type = tt.ptrType();
            g.linkage = Linkage::Internal;
            out_.module.globals.push_back(std::move(g));
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = tt.ptrType();
        addr.text = gname;
        addr.loc = loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = tt.ptrType();
        return slot;
    }

    ValueId classArena(const std::string& cls, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const ValueId slot = arenaSlot(regionFamilyRoot(cls), loc);
        const ValueId cur = loadFrom(slot, loc);
        Inst absent;
        absent.op = Op::CmpEq;
        absent.type = tt.boolType();
        absent.operands.push_back(cur);
        absent.operands.push_back(nullPointer(loc));
        absent.loc = loc;
        const ValueId isNull = emit(std::move(absent));

        const BlockId init = fn_->addBlock(fresh("rgncls.init"));
        const BlockId ready = fn_->addBlock(fresh("rgncls.ready"));
        Inst pick;
        pick.op = Op::BrCond;
        pick.operands.push_back(isNull);
        pick.edges.push_back(Edge{init, {}});
        pick.edges.push_back(Edge{ready, {}});
        pick.loc = loc;
        emit(std::move(pick));

        here_ = init;
        const ValueId made =
            callExternal("__polaron_arena_reserve", tt.ptrType(), {}, {}, loc);
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(made);
        put.operands.push_back(slot);
        put.loc = loc;
        emit(std::move(put));
        gotoIfOpen(ready);

        here_ = ready;
        return loadFrom(slot, loc);
    }

    // `release region A` where `A` is a region class: refuse while anything in the FAMILY is still
    // alive, then give the one reservation back. Every class in the family shares the one block, so
    // every one of them must be empty -- releasing on the root's count alone would free an arena
    // still holding `Ident`s. Nulling the global is what makes a later `new` rebuild it, through
    // the same lazy path bare metal needs.
    void releaseClassArena(const std::string& cls, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const std::string root = regionFamilyRoot(cls);
        std::vector<std::string> family;
        for (const auto& [name, entry] : classesByKey_) {
            if (entry.decl != nullptr && entry.decl->isRegionClass &&
                regionFamilyRoot(name) == root) {
                family.push_back(name);
            }
        }
        std::sort(family.begin(), family.end());   // one order, whatever the map's happens to be

        ValueId anyLive = kNoValue;
        for (const std::string& name : family) {
            const ValueId n = loadFrom(counterSlot(name, loc), loc);
            Inst live;
            live.op = Op::CmpNe;
            live.type = tt.boolType();
            live.operands.push_back(n);
            live.operands.push_back(constInt(0, 32, loc));
            live.loc = loc;
            const ValueId one = emit(std::move(live));
            if (anyLive == kNoValue) {
                anyLive = one;
                continue;
            }
            Inst both;
            both.op = Op::Or;
            both.type = tt.boolType();
            both.operands.push_back(anyLive);
            both.operands.push_back(one);
            both.loc = loc;
            anyLive = emit(std::move(both));
        }

        const BlockId refused = fn_->addBlock(fresh("rgncls.live"));
        const BlockId allowed = fn_->addBlock(fresh("rgncls.free"));
        if (anyLive == kNoValue) {
            gotoIfOpen(allowed);
        } else {
            Inst pick;
            pick.op = Op::BrCond;
            pick.operands.push_back(anyLive);
            pick.edges.push_back(Edge{refused, {}});
            pick.edges.push_back(Edge{allowed, {}});
            pick.loc = loc;
            emit(std::move(pick));
        }

        here_ = refused;
        callExternal("__polaron_panic", tt.voidType(), {tt.ptrType()},
                     {literalText("cannot release the region of '" + root +
                                      "': instances of it are still alive",
                                  loc)},
                     loc);
        Inst stop;
        stop.op = Op::Unreachable;
        stop.loc = loc;
        emit(std::move(stop));

        here_ = allowed;
        // ONE RESERVATION GOES BACK IN ONE CALL -- there is no chain to walk, the arena being
        // contiguous by design. A slot that was never reserved holds null and there is nothing to
        // free, which is the ordinary case of releasing a region no instance ever used.
        const ValueId slot = arenaSlot(root, loc);
        const ValueId arena = loadFrom(slot, loc);
        Inst absent;
        absent.op = Op::CmpEq;
        absent.type = tt.boolType();
        absent.operands.push_back(arena);
        absent.operands.push_back(nullPointer(loc));
        absent.loc = loc;
        const ValueId none = emit(std::move(absent));

        const BlockId have = fn_->addBlock(fresh("rgncls.have"));
        const BlockId done = fn_->addBlock(fresh("rgncls.done"));
        Inst pick;
        pick.op = Op::BrCond;
        pick.operands.push_back(none);
        pick.edges.push_back(Edge{done, {}});
        pick.edges.push_back(Edge{have, {}});
        pick.loc = loc;
        emit(std::move(pick));

        here_ = have;
        callExternal("__polaron_arena_free", tt.voidType(), {tt.ptrType()}, {arena}, loc);
        Inst emptied;
        emptied.op = Op::Store;
        emptied.operands.push_back(nullPointer(loc));
        emptied.operands.push_back(slot);
        emptied.loc = loc;
        emit(std::move(emptied));
        gotoIfOpen(done);

        here_ = done;
    }

    // One instance out of the family's arena. The runtime hands back an OFFSET and the pointer is
    // base + offset -- the offset being the half a narrow `A*` keeps.
    ValueId classArenaAlloc(const std::string& cls, const Type* shape, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const ValueId arena = classArena(cls, loc);
        const ValueId off =
            callExternal("__polaron_arena_alloc", tt.intType(64), {tt.ptrType(), tt.intType(64)},
                         {arena, sizeOfClass(shape, loc)}, loc);
        const ValueId base =
            callExternal("__polaron_arena_base", tt.ptrType(), {tt.ptrType()}, {arena}, loc);
        return rawOffset(base, off, loc);
    }

    // Run a lazily imported class's load hook, once, on the first instance of it. A flag in the
    // image rather than a counter: the question is only "has it happened", and the branch is one
    // compare on a path that already allocates.
    void loadLazyImport(const std::string& cls, SourceLocation loc) {
        const ast::ClassDecl* decl = findClass(cls);
        if (decl == nullptr || decl->onClassLoad == nullptr || !isLazyImport(decl->name)) {
            return;
        }
        const Function* hook = resolveKey(cls + kHookSuffix[0]);
        if (hook == nullptr) {
            return;
        }
        TypeTable& tt = out_.module.types;
        const std::string name = cls + ".__loaded";
        bool known = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                known = true;
                break;
            }
        }
        if (!known) {
            Global g;
            g.name = name;
            g.type = tt.intType(32);
            g.linkage = Linkage::Internal;
            g.zeroInit = true;
            out_.module.globals.push_back(std::move(g));
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = tt.ptrType();
        addr.text = name;
        addr.loc = loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = tt.intType(32);

        const BlockId load = fn_->addBlock(fresh("lazyload"));
        const BlockId after = fn_->addBlock(fresh("lazyload.cont"));
        branchOn(cmp(Op::CmpEq, loadFrom(slot, loc), constInt(0, 32, loc), loc), load, after);
        here_ = load;
        emitCall(hook, {}, loc);
        Inst mark;
        mark.op = Op::Store;
        mark.operands.push_back(constInt(1, 32, loc));
        mark.operands.push_back(slot);
        mark.loc = loc;
        emit(std::move(mark));
        gotoIfOpen(after);
        here_ = after;
    }

    ValueId aliveSlot(const std::string& cls, SourceLocation loc) {
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = aliveFlag(cls);
        addr.loc = loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = out_.module.types.intType(32);
        return slot;
    }

    // USING A CLASS THAT IS GONE THROWS, rather than executing whatever is at the address its code
    // used to be. Emitted at construction and at every call whose static receiver type is one of
    // the unimportable classes -- and nowhere else, so a program with no `unimport` in it pays
    // exactly nothing.
    void guardAlive(const std::string& cls, SourceLocation loc) {
        if (cls.empty() || unimportable_.count(cls) == 0) {
            return;
        }
        Inst dead;
        dead.op = Op::CmpEq;
        dead.type = out_.module.types.boolType();
        dead.operands.push_back(loadFrom(aliveSlot(cls, loc), loc));
        dead.operands.push_back(constInt(0, 32, loc));
        dead.loc = loc;
        const ValueId isDead = emit(std::move(dead));
        const BlockId gone = fn_->addBlock("unimported");
        const BlockId ok = fn_->addBlock("alive.ok");
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(isDead);
        br.edges.push_back(Edge{gone, {}});
        br.edges.push_back(Edge{ok, {}});
        br.loc = loc;
        emit(std::move(br));
        here_ = gone;
        throwUnimported(loc);
        here_ = ok;
    }

    // The one exception a program can catch to find out it used something that is no longer there.
    // Built by hand rather than from a `throw` in source, because there is no source: the compiler
    // is the one raising it, at a use site the author wrote as an ordinary call.
    void throwUnimported(SourceLocation loc) {
        const std::string cls = resolveClassKey("UnimportedTypeException");
        const Type* t = baseTypeOf(cls);
        Inst obj;
        obj.op = Op::Alloca;
        obj.extra.push_back("heap");
        obj.type = t != nullptr && t->kind == TypeKind::Struct ? t : out_.module.types.ptrType();
        obj.text = cls;
        obj.loc = loc;
        const ValueId made = emit(std::move(obj));
        if (t != nullptr && t->kind == TypeKind::Struct) {
            pointee_[made] = t;
        }
        noteName(made, cls);
        // THE CONSTRUCTOR IS WHAT WRITES THE VTABLE, and the vtable is what `catch` matches on. An
        // object thrown without it is caught by nothing at all, and the program dies on an
        // exception it wrote a handler for.
        if (const Function* ctor = resolveKey(cls + "." + cls)) {
            emitCall(ctor, {made}, loc);
        }
        emitRaise(made, loc);
    }

    // A `throw` GOES TO THE ENCLOSING HANDLER, AND THAT IS AN EDGE.
    //
    // `raise` with no unwind successor becomes a plain `call @_CxxThrowException` -- and a call is
    // not a thing a `catch` can see. Written that way, every `throw` inside a `try` in the same
    // method walked straight past the handler written to stop it, out of `main`, into `terminate`:
    // exit code 0xC0000409 and not one line of the program's output, because what it had printed
    // was still in a buffer nobody flushed. `unimport` looks like this and there are seven of it.
    //
    // Four places in this file emit a `raise` and exactly ONE of them added the edge, which is how
    // the rule comes to live in a method: `handlers_` is the answer to "is there a handler here",
    // and asking it once is the only way all four ask it the same way.
    //
    // AND NOTHING AFTER IT. `raise` ends the block -- the backend emits the raiser and its own
    // `unreachable`, because neither `_CxxThrowException` nor `__cxa_throw` returns. A second
    // terminator in one block is a module LLVM refuses: `Terminator found in the middle of a basic
    // block! label %await.throw`.
    void emitRaise(ValueId obj, SourceLocation loc) {
        Inst raise;
        raise.op = Op::Raise;
        if (obj != kNoValue) {
            raise.operands.push_back(obj);
        }
        if (!handlers_.empty()) {
            raise.edges.push_back(Edge{handlers_.back().landing, {}});
        }
        raise.loc = loc;
        emit(std::move(raise));
    }

    // `unimport X;` -- §30. Refuse while anything is alive, run the unload hook while the code is
    // still there to run it, mark the class dead, and poison its dispatch table.
    //
    // THE TABLE IS THE PART THAT IS EASY TO FORGET, and forgetting it is a hole rather than
    // untidiness: the alive check is emitted from the STATIC type at the call site, so
    // `Shape s = new Dog(); unimport Dog; s.area();` never asks about `Dog` at all -- the receiver
    // is a `Shape`, and the call goes through the table into code that is gone.
    void unimportClass(const std::string& cls, SourceLocation loc) {
        const std::string key = resolveClassKey(cls);
        // REFUSED WHILE ANYTHING IS STILL ALIVE. This is the precondition the rest rests on: with
        // no live instance there is no object whose vtable, fields or destructor can outlive the
        // code being taken away. It is a run-time question -- how many exist is not something the
        // compiler can answer -- and the counter that answers it is the same one §32.5 keeps.
        if (unimportable_.count(cls) != 0 || unimportable_.count(key) != 0) {
            Inst live;
            live.op = Op::CmpNe;
            live.type = out_.module.types.boolType();
            live.operands.push_back(loadFrom(counterSlot(key, loc), loc));
            live.operands.push_back(constInt(0, 32, loc));
            live.loc = loc;
            const ValueId busy = emit(std::move(live));
            const BlockId refuse = fn_->addBlock("unimport.live");
            const BlockId go = fn_->addBlock("unimport.ok");
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(busy);
            br.edges.push_back(Edge{refuse, {}});
            br.edges.push_back(Edge{go, {}});
            br.loc = loc;
            emit(std::move(br));
            here_ = refuse;
            // A FREESTANDING PROGRAM HAS NOWHERE TO THROW TO. There is no runtime to catch an
            // `Unimported`, so bare metal states the refusal and stops -- which is what the other
            // backend has always done, and `unimport_freestanding` is the sample that reads it.
            // Throwing here emitted an unwind nothing handled, and the program printed nothing at
            // all where the message is the entire point of the test.
            if (out_.module.freestanding) {
                TypeTable& tt = out_.module.types;
                callExternal("__polaron_panic", tt.voidType(), {tt.ptrType()},
                             {literalText("cannot unimport '" + cls +
                                              "': instances of it are still alive",
                                          loc)},
                             loc);
                Inst stop;
                stop.op = Op::Unreachable;
                stop.loc = loc;
                emit(std::move(stop));
            } else {
                throwUnimported(loc);
            }
            here_ = go;
        }
        if (const Function* hook = out_.module.find(key + kHookSuffix[3])) {
            emitCall(hook, {}, loc);
        }
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(constInt(0, 32, loc));
        st.operands.push_back(aliveSlot(key, loc));
        st.loc = loc;
        emit(std::move(st));
        poisonVtable(key, loc);
        clearStatics(key, loc);
        physicalCodeOp(cls, key, "__polaron_unload_fn", loc);
    }

    // ---- §30: THE CODE ITSELF, RIPPED FROM MEMORY ----
    //
    // `unimport` is not a flag. The class's machine code is overwritten with `int3` in RAM, so a
    // call that reaches it by any route the compiler could not see -- a stale function pointer, a
    // vtable slot in an object that outlived the check -- traps instead of running freed code.
    // `reimport` reads it back from the executable on disk.
    //
    // This side did the bookkeeping (the alive flag, the poisoned table, the statics) and NOT the
    // code, so `unimport` looked like it worked and the first byte of the method still read 0x48
    // where the language says 0xCC. The sample checks that byte, which is the only honest way to
    // test a claim about memory.
    //
    // The runtime needs the bounds of one method's code and there is no portable way to ask for
    // them, so it is given a TABLE of every function's address: the one that follows in memory
    // bounds the one being erased. The table is filled by the backend, after every body exists.
    void physicalCodeOp(const std::string& cls, const std::string& key, const char* runtimeFn,
                        SourceLocation loc) {
        const ast::ClassDecl* decl = findClass(cls);
        if (decl == nullptr) {
            return;
        }
        declareCodeTable();
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        auto rip = [&](const std::string& fnKey) {
            const Function* target = out_.module.find(fnKey);
            if (target == nullptr || target->blocks.empty()) {
                return;
            }
            Inst at;
            at.op = Op::ConstFn;
            at.type = ptr;
            at.text = target->key;
            at.loc = loc;
            const ValueId code = emit(std::move(at));
            // THE SLOT'S TYPE TRAVELS WITH ITS ADDRESS. `constFnInEntry` hands back a bare address
            // and `loadFrom` then reads whatever the default width is -- `load i32, ptr
            // @__polaron_code_base` off a pointer-sized global, so the runtime was given the low
            // half of the table's address and walked into nothing.
            const ValueId baseAt = constFnInEntry("__polaron_code_base", loc);
            slotType_[baseAt] = ptr;
            const ValueId countAt = constFnInEntry("__polaron_code_count", loc);
            slotType_[countAt] = i64;
            const ValueId base = loadFrom(baseAt, loc);
            const ValueId count = loadFrom(countAt, loc);
            callExternal(runtimeFn, tt.voidType(), {ptr, ptr, i64}, {code, base, count}, loc);
        };
        for (const ast::MemberPtr& m : decl->members) {
            if (const auto* md = dynamic_cast<const ast::MethodDecl*>(m.get());
                md != nullptr && !md->isAbstract && !md->isExtern) {
                rip(key + "." + md->name);
            }
        }
        rip(key + "." + decl->name);          // the constructor
        rip(key + ".~" + decl->name);         // ...and the destructor
    }

    // The two globals the rip reads. Declared on demand -- a program with no `unimport` in it
    // should carry neither -- and filled by the backend once every function is emitted, because
    // "every function in this module" is not a question the lowering can answer.
    void declareCodeTable() {
        for (const Global& g : out_.module.globals) {
            if (g.name == "__polaron_code_base") {
                return;
            }
        }
        Global base;
        base.name = "__polaron_code_base";
        base.type = out_.module.types.ptrType();
        base.linkage = Linkage::Internal;
        base.zeroInit = true;
        out_.module.globals.push_back(std::move(base));
        Global count;
        count.name = "__polaron_code_count";
        count.type = out_.module.types.intType(64);
        count.linkage = Linkage::Internal;
        count.zeroInit = true;
        out_.module.globals.push_back(std::move(count));
    }

    // Every slot of the class's table pointed at ONE TRAP that names the class. A null slot faults
    // at address zero with nothing to say, and "which class did this belong to" is exactly the
    // question you have at that moment.
    void poisonVtable(const std::string& key, SourceLocation loc) {
        const std::string table = key + ".vtable";
        size_t slots = 0;
        for (const Global& g : out_.module.globals) {
            if (g.name == table) {
                slots = g.initFns.size();
                break;
            }
        }
        if (slots == 0) {
            return;
        }
        const Function* trap = unimportedTrap(key);
        if (trap == nullptr) {
            return;
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = table;
        addr.loc = loc;
        const ValueId base = emit(std::move(addr));
        Inst which;
        which.op = Op::ConstFn;
        which.type = out_.module.types.ptrType();
        which.text = trap->key;
        which.loc = loc;
        const ValueId poison = emit(std::move(which));
        for (size_t i = 0; i < slots; ++i) {
            Inst g;
            g.op = Op::Gep;
            g.type = out_.module.types.ptrType();
            g.operands.push_back(base);
            g.imm = static_cast<int64_t>(i * 8);
            g.loc = loc;
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(poison);
            st.operands.push_back(emit(std::move(g)));
            st.loc = loc;
            emit(std::move(st));
        }
    }

    // ...and the class's own storage goes with it. Static fields are the memory that belonged to
    // the TYPE rather than to any object; with nothing alive there is nobody left who could read
    // them, so leaving them holding their last values is leaving state behind for a type that no
    // longer exists. A later `reimport` gets the class back at its starting state, which is what
    // "loaded again" has to mean.
    void clearStatics(const std::string& key, SourceLocation loc) {
        const std::string prefix = key + ".";
        for (const Global& g : out_.module.globals) {
            if (g.name.rfind(prefix, 0) != 0 || g.name.size() <= prefix.size()) {
                continue;
            }
            const std::string tail = g.name.substr(prefix.size());
            // Not the machinery this pass put there itself: the alive flag, the counter and the
            // table are the class's bookkeeping, not its state, and zeroing them here would undo
            // the very `unimport` doing the zeroing.
            if (tail == "vtable" || tail == "__alive" || tail == "__instances" ||
                tail.rfind("__on", 0) == 0 || tail.find('.') != std::string::npos) {
                continue;
            }
            if (g.type == nullptr) {
                continue;
            }
            Inst addr;
            addr.op = Op::ConstFn;
            addr.type = out_.module.types.ptrType();
            addr.text = g.name;
            addr.loc = loc;
            const ValueId slot = emit(std::move(addr));
            slotType_[slot] = g.type;
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(g.type->kind == TypeKind::Ptr ? nullPointer(g.type, loc)
                                                                 : constInt(0, g.type->kind == TypeKind::Int
                                                                                    ? g.type->bits
                                                                                    : 64,
                                                                            loc));
            st.operands.push_back(slot);
            st.loc = loc;
            emit(std::move(st));
        }
    }

    // A VALUE AS SIXTY-FOUR BITS. A pointer becomes its address, an integer widens, a float is
    // reinterpreted -- nothing is rounded, because the point is to compare the bits and not the
    // number.
    ValueId asWord(ValueId v, SourceLocation loc) {
        const Type* t = v != kNoValue ? fn_->value(v)->type : nullptr;
        TypeTable& tt = out_.module.types;
        if (t == nullptr) {
            return v;
        }
        // §21 + §20.2: A VALUE VARIANT DOES NOT FIT IN A WORD, so crossing one is BOXING it. A task
        // hands its answer over as a single machine word, and `{ tag, payload }` is two -- widened
        // instead of boxed, the tag survived and the payload did not: `async_value_result` printed
        // `0 0` where the program computes `42 -5`. The block is read back and released by the
        // await, which is the only thing that ever sees this pointer.
        if (t->kind == TypeKind::Variant) {
            const ValueId room = callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                              {constInt(16, 64, loc)}, loc);
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(v);
            put.operands.push_back(room);
            put.loc = loc;
            emit(std::move(put));
            Inst asAddr;
            asAddr.op = Op::PtrToAddr;
            asAddr.type = tt.intType(64);
            asAddr.operands.push_back(room);
            asAddr.loc = loc;
            return emit(std::move(asAddr));
        }
        if (t->kind == TypeKind::Ptr) {
            Inst in;
            in.op = Op::PtrToAddr;
            in.type = tt.intType(64);
            in.operands.push_back(v);
            in.loc = loc;
            return emit(std::move(in));
        }
        if (t->kind == TypeKind::Float) {
            Inst in;
            in.op = Op::Bitcast;
            in.type = tt.intType(64);
            in.operands.push_back(t->bits == 64 ? v : lowerConversion(v, t, tt.floatType(64), loc));
            in.loc = loc;
            return emit(std::move(in));
        }
        return widen(v, 64, loc);
    }

    ValueId nullPointer(const Type* t, SourceLocation loc) {
        Inst in;
        in.op = Op::ConstNull;
        in.type = t;
        in.loc = loc;
        return emit(std::move(in));
    }

    // One trap method per unimported class: it reports the call by NAME and stops. A real method
    // rather than a null slot, because the name is the whole value of the report.
    const Function* unimportedTrap(const std::string& key) {
        const std::string sym = key + ".__unimportedCall";
        if (const Function* had = out_.module.find(sym)) {
            return had;
        }
        // The signature is a receiver and nothing else. Every slot of the table is stored the same
        // pointer, so it is called with whatever arguments that slot's method takes -- which is
        // fine on every calling convention here: the trap never returns.
        Field self;
        self.type = out_.module.types.ptrType();
        self.name = "this";
        Function* fn = out_.module.addFunction(
            sym, out_.module.types.fnType(out_.module.types.voidType(), {self}));
        fn->params = {{"this", key, false}};
        fn->linkage = Linkage::Internal;
        fn->unwind = Unwind::May;
        fn->noReturn = true;
        // Built with the SAME body-lowering the rest of the module uses, so the throw gets real
        // scope teardown and a real unwind edge rather than a hand-rolled block.
        // THE WHOLE PER-BODY STATE, for the same reason the field accessors save it: a new function
        // numbers its values from zero, so anything left in the id-keyed maps belongs to a
        // different function and answers wrongly for both.
        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        fn->addValue(out_.module.types.ptrType(), ValueOrigin::BlockParam, here_, 0, "this");
        fn->block(here_)->params.push_back(0);
        throwUnimported(SourceLocation{});
        restoreBody(std::move(outer));
        return fn;
    }

    // `reimport X;` -- the class comes back, at its starting state. The table is written back from
    // the same list the module built it with, so a virtual call through an object that survived
    // reaches the real method again rather than the trap.
    void reimportClass(const std::string& cls, SourceLocation loc) {
        const std::string key = resolveClassKey(cls);
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(constInt(1, 32, loc));
        st.operands.push_back(aliveSlot(key, loc));
        st.loc = loc;
        emit(std::move(st));
        // THE CODE COMES BACK FIRST, read from the executable on disk. Restoring the table below
        // while the bodies are still `int3` would point every slot at a trap.
        physicalCodeOp(cls, key, "__polaron_reload_fn", loc);
        const std::string table = key + ".vtable";
        std::vector<std::string> entries;
        for (const Global& g : out_.module.globals) {
            if (g.name == table) {
                entries = g.initFns;
                break;
            }
        }
        if (entries.empty()) {
            return;
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = table;
        addr.loc = loc;
        const ValueId base = emit(std::move(addr));
        for (size_t i = 0; i < entries.size(); ++i) {
            if (entries[i].empty() || out_.module.find(entries[i]) == nullptr) {
                continue;
            }
            Inst which;
            which.op = Op::ConstFn;
            which.type = out_.module.types.ptrType();
            which.text = entries[i];
            which.loc = loc;
            Inst g;
            g.op = Op::Gep;
            g.type = out_.module.types.ptrType();
            g.operands.push_back(base);
            g.imm = static_cast<int64_t>(i * 8);
            g.loc = loc;
            Inst store;
            store.op = Op::Store;
            store.operands.push_back(emit(std::move(which)));
            store.operands.push_back(emit(std::move(g)));
            store.loc = loc;
            emit(std::move(store));
        }
    }

    // WHERE AN OBJECT'S PERSISTENT FIELDS LIVE, wired into the object at construction.
    //
    // WHAT IDENTIFIES A BLOCK is the NAME the object is bound to, not the object: `Car c = new
    // Car()` in a method called three times is three objects and ONE `c`, and reattaching to what
    // `c` held last time is the entire feature. So the key is method-plus-variable, and a `new`
    // that is not bound to a name gets a fresh zeroed block instead -- a temporary has no identity
    // to reattach to, and leaving the pointer wild would fault on the first read.
    void attachPersistBlock(ValueId object, const std::string& cls, SourceLocation loc) {
        auto block = persistBlock_.find(cls);
        if (block == persistBlock_.end() || block->second == nullptr) {
            return;
        }
        TypeTable& tt = out_.module.types;
        ValueId held = kNoValue;
        const int64_t bytes0 = static_cast<int64_t>(block->second->facts.size);
        if (pendingPersistIndex_ != kNoValue && !pendingPersistKey_.empty()) {
            held = callExternal("__polaron_persist_slot", tt.ptrType(),
                                {tt.ptrType(), tt.intType(64), tt.intType(64)},
                                {literalText(pendingPersistKey_, loc),
                                 fitInt(pendingPersistIndex_, 64, loc),
                                 constInt(bytes0 > 0 ? bytes0 : 8, 64, loc)},
                                loc);
        } else if (!pendingPersistKey_.empty()) {
            const std::string name = pendingPersistKey_ + ".__pblock";
            bool have = false;
            for (const Global& g : out_.module.globals) {
                if (g.name == name) {
                    have = true;
                    break;
                }
            }
            if (!have) {
                Global g;
                g.name = name;
                g.type = block->second;
                g.linkage = Linkage::Internal;
                g.zeroInit = true;
                out_.module.globals.push_back(std::move(g));
            }
            Inst addr;
            addr.op = Op::ConstFn;
            addr.type = tt.ptrType();
            addr.text = name;
            addr.loc = loc;
            held = emit(std::move(addr));
        } else {
            const int64_t bytes = static_cast<int64_t>(block->second->facts.size);
            held = callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                {constInt(bytes > 0 ? bytes : 8, 64, loc)}, loc);
            Inst wipe;
            wipe.op = Op::MemSet;
            wipe.operands.push_back(held);
            wipe.operands.push_back(constInt(0, 8, loc));
            wipe.operands.push_back(constInt(bytes > 0 ? bytes : 8, 64, loc));
            wipe.loc = loc;
            emit(std::move(wipe));
        }
        pendingPersistKey_.clear();
        Inst slot;
        slot.op = Op::Gep;
        slot.type = tt.ptrType();
        slot.operands.push_back(object);
        slot.aggregate = named_.count(cls) != 0 ? named_[cls] : nullptr;
        slot.imm = persistIndex_.count(cls) != 0 ? persistIndex_[cls] : 0;
        slot.text = "__persist";
        slot.loc = loc;
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(held);
        st.operands.push_back(emit(std::move(slot)));
        st.loc = loc;
        emit(std::move(st));
    }

    // ---- §37.3, `lazy` ----
    //
    // The storage and the flag, made where the declaration stands; the initialiser is remembered
    // and emitted at the first READ. What it buys is that an expensive or side-effecting
    // construction happens only if the name is used, and only once.
    struct LazySite {
        ValueId flag = kNoValue;
        ValueId slot = kNoValue;
        const ast::Expr* init = nullptr;
        const ast::TypeRef* type = nullptr;
        bool done = false;   // its guard has been emitted; further reads are ordinary loads
    };

    void lowerLazyLocal(const ast::VarDeclStmt& v) {
        TypeTable& tt = out_.module.types;
        const Type* held = typeOf(v.type);
        const ValueId slot = allocaFor(v.name, held);
        slotType_[slot] = held;
        noteName(slot, resolvedTypeName(v.type), pointerDepthOfType(v.type));
        Inst blank;
        blank.op = Op::Store;
        blank.operands.push_back(
            held != nullptr && held->kind == TypeKind::Ptr
                ? nullPointer(held, v.loc)
                : constInt(0, held != nullptr && held->bits > 0 ? held->bits : 32, v.loc));
        blank.operands.push_back(slot);
        blank.loc = v.loc;
        emit(std::move(blank));
        Inst room;
        room.op = Op::Alloca;
        room.type = tt.intType(32);
        room.text = v.name + ".lazy";
        room.loc = v.loc;
        const ValueId flag = emit(std::move(room));
        slotType_[flag] = tt.intType(32);
        Inst clear;
        clear.op = Op::Store;
        clear.operands.push_back(constInt(0, 32, v.loc));
        clear.operands.push_back(flag);
        clear.loc = v.loc;
        emit(std::move(clear));
        lazyLocals_[v.name] = LazySite{flag, slot, v.init.get(), &v.type, false};
    }

    // The guard, at a use site: if the flag is clear, run the initialiser and set it. Emitted
    // ONCE per name rather than at every read -- the second read is already past the branch, and a
    // guard per read is a branch the optimiser has to prove redundant instead of one that was
    // never written.
    void ensureLazy(const std::string& name, SourceLocation loc) {
        auto it = lazyLocals_.find(name);
        if (it == lazyLocals_.end() || it->second.done || it->second.init == nullptr) {
            return;
        }
        LazySite& site = it->second;
        site.done = true;
        Inst set;
        set.op = Op::CmpEq;
        set.type = out_.module.types.boolType();
        set.operands.push_back(loadFrom(site.flag, loc));
        set.operands.push_back(constInt(0, 32, loc));
        set.loc = loc;
        const BlockId run = fn_->addBlock(fresh("lazyinit"));
        const BlockId after = fn_->addBlock(fresh("lazydone"));
        branchOn(emit(std::move(set)), run, after);
        here_ = run;
        if (const ValueId built = lowerExpr(site.init); built != kNoValue) {
            storeInto(site.slot, built, loc);
        }
        Inst mark;
        mark.op = Op::Store;
        mark.operands.push_back(constInt(1, 32, loc));
        mark.operands.push_back(site.flag);
        mark.loc = loc;
        emit(std::move(mark));
        gotoIfOpen(after);
        here_ = after;
    }

    // The guard for a `lazy` FIELD, at the read site: a null slot means "not built yet". Looked up
    // in the class and then up the chain, since an inherited field's initialiser is the base's.
    void ensureLazyField(ValueId object, const std::string& cls, const std::string& field,
                         ValueId addr, SourceLocation loc) {
        if (object == kNoValue || cls.empty()) {
            return;
        }
        const ast::Expr* init = nullptr;
        std::string key;
        // THE CHAIN IS WALKED WITH A SEEN SET. A class whose `superclass` names itself -- which the
        // prelude's root does -- turns this walk into a loop with no end.
        std::unordered_set<std::string> visited;
        for (std::string walk = cls; !walk.empty() && visited.insert(walk).second;) {
            if (auto it = lazyFieldInit_.find(walk + "." + field); it != lazyFieldInit_.end()) {
                init = it->second;
                key = walk + "." + field;
                break;
            }
            const ast::ClassDecl* up = findClass(walk);
            walk = up != nullptr ? up->superclass : std::string();
        }
        if (init == nullptr) {
            return;
        }
        // ...AND THE INITIALISER MAY MENTION THE FIELD ITSELF, which is how a memo is written. The
        // guard is emitted once per read site; without this the lowering of the initialiser walked
        // back into the same guard and the compiler ran out of stack.
        if (!buildingLazy_.insert(key).second) {
            return;
        }
        struct Leave {
            std::unordered_set<std::string>* set;
            const std::string* key;
            ~Leave() { set->erase(*key); }
        } leave{&buildingLazy_, &key};
        const Type* held = slotType_.count(addr) != 0 ? slotType_[addr] : nullptr;
        if (held == nullptr || held->kind != TypeKind::Ptr) {
            return;   // only a slot that can hold null carries the sentinel
        }
        Inst empty;
        empty.op = Op::CmpEq;
        empty.type = out_.module.types.boolType();
        empty.operands.push_back(loadFrom(addr, loc));
        empty.operands.push_back(nullPointer(held, loc));
        empty.loc = loc;
        const BlockId build = fn_->addBlock(fresh("lazyfinit"));
        const BlockId after = fn_->addBlock(fresh("lazyfdone"));
        branchOn(emit(std::move(empty)), build, after);
        here_ = build;
        if (const ValueId made = lowerExpr(init); made != kNoValue) {
            storeInto(addr, made, loc);
        }
        gotoIfOpen(after);
        here_ = after;
    }

    // The storage a `persistent` local binds to: one global per (method, name), seeded from the
    // initialiser if it is a compile-time constant and zero otherwise. Bound as the local's slot,
    // so every read and write in the body is an ordinary load and store and the body needs no
    // special case at all -- which is the point of doing it here rather than at every use.
    void lowerPersistentLocal(const ast::VarDeclStmt& v) {
        const std::string declared = ast::mangleGeneric(v.type.name, v.type.typeArgs);
        const Type* held = typeOf(v.type);
        if (held == nullptr) {
            held = out_.module.types.intType(32);
        }
        const std::string key = (fn_ != nullptr ? fn_->key : std::string()) + "." + v.name;
        bool have = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == key) {
                have = true;
                break;
            }
        }
        if (!have) {
            Global g;
            g.name = key;
            g.type = held;
            g.linkage = Linkage::Internal;
            g.zeroInit = true;
            // SEEDED, NOT STORED. A constant initialiser becomes the global's own starting value,
            // which happens once when the image is loaded; anything the compiler cannot fold is
            // zero, and the program has to say what it wants otherwise.
            if (v.init != nullptr) {
                comptime::Context ctx;
                ctx.consts = &constInts_;
                ctx.dconsts = &constDoubles_;
                ctx.methods = &comptimeMethods_;
                long long folded = 0;
                double dfolded = 0.0;
                if (held->kind == TypeKind::Float) {
                    if (comptime::evalDouble(*v.init, dfolded, ctx)) {
                        g.zeroInit = false;
                        g.initFloat = dfolded;
                    }
                } else if (comptime::evalInt(*v.init, folded, ctx)) {
                    g.zeroInit = false;
                    g.initInt = folded;
                }
            }
            out_.module.globals.push_back(std::move(g));
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = key;
        addr.loc = v.loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = held;
        locals_[v.name] = slot;
        noteName(slot, declared);
        declaredAs_[slot] = DeclaredType{declared, v.type.pointerDepth};
    }

    // `expecting { ... return v; }` (§30.18) RUN WHERE IT STANDS, as an expression. The block's
    // `return` names the value; the block itself is not a method and does not return from one.
    //
    // WHY THE VALUE AT ALL: the two sides of an `unimport`/`reimport` pair are two different
    // compilations of the same class, and the whole question is whether the new one still answers
    // the same. Producing a value in the OLD code, then the same expression in the NEW code, then
    // comparing them bit-for-bit, is the only check that does not require trusting either side.
    ValueId lowerExpecting(const ast::Block* block, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        if (block == nullptr) {
            return constInt(0, 32, loc);
        }
        // ONE MACHINE WORD, whatever the block produces. The comparison §30.18 asks for is
        // bit-for-bit, and every validation value that fits in a register -- an integer of any
        // width, a boolean, a handle -- compares exactly when its sixty-four bits do. The slot has
        // to exist before the block runs, and what the block returns is not known until it has been
        // lowered, so the alternative would be inferring the type of an expression a second time
        // here, with a second answer to disagree with the first.
        const Type* held = tt.intType(64);
        Inst room;
        room.op = Op::Alloca;
        room.type = held;
        room.text = "expecting.val";
        room.loc = loc;
        const ValueId slot = emit(std::move(room));
        slotType_[slot] = held;
        Inst zero;
        zero.op = Op::Store;
        zero.operands.push_back(held->kind == TypeKind::Ptr
                                    ? nullPointer(held, loc)
                                    : constInt(0, held->kind == TypeKind::Int ? held->bits : 64, loc));
        zero.operands.push_back(slot);
        zero.loc = loc;
        emit(std::move(zero));
        const BlockId end = fn_->addBlock("expecting.end");
        const ValueId savedSlot = expectingSlot_;
        const BlockId savedEnd = expectingEnd_;
        expectingSlot_ = slot;
        expectingEnd_ = end;
        for (const auto& s : block->statements) {
            lowerStmt(s.get());
        }
        if (!blockClosed()) {
            Inst go;
            go.op = Op::Br;
            go.edges.push_back(Edge{end, {}});
            go.loc = loc;
            emit(std::move(go));
        }
        expectingSlot_ = savedSlot;
        expectingEnd_ = savedEnd;
        here_ = end;
        return loadFrom(slot, loc);
    }

    // ---- §32.5, the four moments in a class's life ----
    //
    // `onClassLoad` before anything uses the class, `onFirstInstance` when the live count leaves
    // zero, `onLastInstanceDestroyed` when it comes back to zero, `onClassUnload` when `unimport`
    // takes the class away. None of them is a method anybody can call: each is a BLOCK attached to
    // the class, so it needs a function of its own to live in and somebody to call it.
    //
    // The hook block is STATIC CONTEXT -- it has no `this`, which is the whole point of a hook that
    // runs before any instance exists -- so it lowers as a void function of no arguments.
    static const char* kHookSuffix[4];

    // `w.interrupt` -- the entry point of a handler BOUND to `w`, as a raw address. Answers
    // kNoValue when the member is not an interrupt handler, which is how everything else goes on
    // being read as a field.
    //
    // The trampoline is what makes the two halves fit: an interrupt vector holds an address that is
    // called with the vector's arguments and no receiver, and a Polaron method needs one. So the
    // receiver goes into a global at the moment the address is taken -- which is the moment the
    // binding happens, and the reason the language makes them one act -- and the trampoline reads
    // it back. One handler per method, which is what a vector can hold anyway.
    // `lowered` receives the evaluated receiver when one had to be produced, so that the caller --
    // which needs the same receiver a few lines further down -- reuses it instead of producing a
    // second one. Answering kNoValue does NOT mean nothing was evaluated.
    ValueId interruptEntryPoint(const ast::MemberExpr& m, SourceLocation loc, ValueId* lowered) {
        if (m.object == nullptr) {
            return kNoValue;
        }
        // ASK BEFORE EVALUATING -- THE RECEIVER IS AN EXPRESSION, NOT A NAME.
        //
        // This runs on every member read in the program, and it used to evaluate the object first
        // and decide afterwards. So `return table().n;` -- one call in the source -- emitted two
        // calls to `table()`, kept the second and dropped the first. Nothing said so: the value
        // was right, both paths printed the same, and the census could only see it as a call count.
        //
        // A receiver that allocates, appends to a log, advances a cursor or is a generator's
        // `next()` DID IT TWICE. That is the objection AP-26 makes -- that you cannot see what code
        // runs -- arriving as a real defect rather than a worry.
        //
        // The question it was buying at that price has a cheap exact answer: if no class in the
        // program declares an `interrupt` handler by this name, no receiver can have one either.
        // The second demonstration switch (see `noteStringResult` for the first).
        //
        // D14 was fixed in two halves -- ask before evaluating, and hand the evaluated receiver back
        // so the caller reuses it -- and reintroducing it needs BOTH turned off, which is a fact
        // worth knowing: with only the first disabled the receiver is still lowered once, because
        // the cache catches it. `golden_ir_catches_reintroduced_defect` requires the recording of
        // `Holder.fieldOffCall` to stop matching, and it only does when the call is genuinely
        // emitted twice. Read only here, and only for that test.
        const bool demonstrating = std::getenv("POLARON_REINTRODUCE_D14") != nullptr;
        if (interruptNames_.count(m.member) == 0 && !demonstrating) {
            return kNoValue;
        }
        if (demonstrating) {
            lowered = nullptr;   // ...and the caller lowers it a second time, as it used to
        }
        const ValueId self = lowerExpr(m.object.get());
        if (lowered != nullptr) {
            *lowered = self;   // whatever this decides below, the caller reuses THIS one
        }
        if (self == kNoValue) {
            return kNoValue;
        }
        const std::string cls = classNameOf(declaredName(self));
        const ast::ClassDecl* decl = cls.empty() ? nullptr : findClass(cls);
        if (decl == nullptr) {
            return kNoValue;
        }
        const ast::MethodDecl* handler = nullptr;
        forEachMember<ast::MethodDecl>(*decl, [&](const ast::MethodDecl& mm) {
            if (mm.isInterrupt && mm.name == m.member) {
                handler = &mm;
            }
        });
        if (handler == nullptr) {
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;
        const std::string bound = cls + "$" + m.member + "$self";
        const std::string entry = cls + "$" + m.member;
        bool known = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == bound) {
                known = true;
                break;
            }
        }
        if (!known) {
            Global g;
            g.name = bound;
            g.type = tt.ptrType();
            g.linkage = Linkage::Internal;
            out_.module.globals.push_back(std::move(g));
        }
        // The trampoline, once: the vector's own signature, the receiver read back from the global.
        if (out_.module.find(entry) == nullptr) {
            std::vector<Field> params;
            std::vector<Function::Param> plist;
            for (const ast::Param& p : handler->params) {
                Field f;
                f.type = typeOf(p.type);
                f.name = p.name;
                params.push_back(f);
                plist.push_back({p.name, resolvedTypeName(p.type), passedByValue(p.type),
                                 pointerDepthOfType(p.type)});
            }
            Function* fn =
                out_.module.addFunction(entry, tt.fnType(tt.voidType(), std::move(params)));
            fn->params = std::move(plist);
            fn->linkage = Linkage::Public;
            fn->unwind = Unwind::Never;   // an exception out of an interrupt has nowhere to go
            // THE MEANING IS PORTABLE; ONLY THE LOWERING IS NOT.
            //
            //   freestanding -> `x86_intrcc`: LLVM writes the save of every register the body
            //                   clobbers, the `cld`, the pop of a pushed error code, the `iretq`.
            //   hosted       -> the ordinary C ABI, which is exactly what `signal()` takes on POSIX
            //                   and through the Windows CRT. One shape that installs on both.
            //
            // The MODE decides this and not the triple, and the difference is not pedantry: the
            // triple answers an ABI question (is there an OS to promise a red zone) while
            // `freestanding` answers a language one (is there a runtime at all). Unset here, the
            // entry came out as an ordinary function that returns with `ret` -- on a stack the CPU
            // laid out for `iret`.
            // ...AND IT TAKES THE FRAME EVEN WHEN THE HANDLER DOES NOT ASK FOR IT. `x86_intrcc` is
            // a promise about a stack the CPU already laid out, so the entry's shape is decided by
            // the hardware and not by whether the author wanted to read the `Trap`. A handler
            // declaring none produced `define x86_intrcc void @Spurious$interrupt()` -- a handler
            // for a frame that is there whether it is named or not.
            const bool needsFrameParam =
                out_.module.freestanding && fn->signature != nullptr &&
                fn->signature->fields.empty();
            if (out_.module.freestanding) {
                fn->conv = Conv::Interrupt;
            }
            if (needsFrameParam) {
                Field frame;
                frame.type = tt.ptrType();
                frame.name = "trap";
                fn->signature = tt.fnType(tt.voidType(), {frame});
                fn->params.push_back({"trap", "address", false, 0});
            }

            BodyState outer = saveBody();
            fn_ = fn;
            here_ = fn->addBlock("entry");
            entryBlock_ = here_;
            allocaAt_ = 0;
            locals_.clear();
            slotType_.clear();
            declaredAs_.clear();
            clearFieldShapes();
            weakSlotAt_.clear();
            cCallable_.clear();
            statics_.clear();
            std::vector<ValueId> passed;
            Block* head = fn->block(here_);
            for (uint32_t i = 0; i < handler->params.size(); ++i) {
                const ValueId v = fn->addValue(typeOf(handler->params[i].type),
                                               ValueOrigin::BlockParam, here_, i,
                                               handler->params[i].name);
                head->params.push_back(v);
                passed.push_back(v);
            }
            // The frame the hardware pushed, when the handler named no `Trap`. It is a parameter of
            // the ENTRY and not an argument to the handler -- nothing reads it -- but the entry's
            // shape has to match what the CPU laid out. See `needsFrameParam` above.
            if (needsFrameParam) {
                head->params.push_back(
                    fn->addValue(tt.ptrType(), ValueOrigin::BlockParam, here_, 0, "trap"));
            }
            Inst addr;
            addr.op = Op::ConstFn;
            addr.type = tt.ptrType();
            addr.text = bound;
            const ValueId slot = emit(std::move(addr));
            slotType_[slot] = tt.ptrType();
            std::vector<ValueId> all{loadFrom(slot, {})};
            for (ValueId a : passed) {
                all.push_back(a);
            }
            if (const Function* real = resolveKey(cls + "." + m.member)) {
                emitCall(real, std::move(all), {});
            }
            Inst back;
            back.op = Op::Ret;
            emit(std::move(back));
            restoreBody(std::move(outer));
        }

        // THE BINDING IS THE TAKING. `w.interrupt` records `w` and yields the trampoline's address.
        Inst at;
        at.op = Op::ConstFn;
        at.type = tt.ptrType();
        at.text = bound;
        at.loc = loc;
        const ValueId slot = emit(std::move(at));
        slotType_[slot] = tt.ptrType();
        storePtr(slot, self, loc);

        Inst code;
        code.op = Op::ConstFn;
        code.type = tt.ptrType();
        code.text = entry;
        code.loc = loc;
        const ValueId fnv = emit(std::move(code));
        // AN INTERRUPT VECTOR HOLDS A NUMBER. `Signals.answer(int, address)` takes the entry point
        // as an `address`, which is an integer here and not a pointer -- §3.1 keeps them apart.
        Inst asNumber;
        asNumber.op = Op::PtrToAddr;
        asNumber.type = tt.addrType(64);
        asNumber.operands.push_back(fnv);
        asNumber.loc = loc;
        return emit(std::move(asNumber));
    }

    // Whether `lazy import` named this class. Asked by NAME, because that is what an import path
    // ends with and the class key may be a full path.
    bool isLazyImport(const std::string& name) const {
        auto named = [&](const ast::ImportDecl& imp) {
            return imp.isLazy && !imp.path.empty() && imp.path.back() == name;
        };
        for (const ast::ImportDecl& imp : ast_.imports) {
            if (named(imp)) {
                return true;
            }
        }
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::ImportDecl& imp : b.imports) {
                if (named(imp)) {
                    return true;
                }
            }
        }
        return false;
    }

    // §21: A STRING FIELD STARTS NULL, and the constructor is where that becomes true.
    //
    // The ownership protocol's release half reads the field before overwriting it, and a field
    // that has never been written holds whatever the storage happened to contain -- `new Snap(...)
    // on stack` is an `alloca`, which contains the previous frame's bytes. `value_copy_string_field`
    // took an access violation inside `__polaron_str_free` on exactly that: the release was correct
    // and the premise under it was not. "String fields are null-defaulted" is a claim, and this is
    // the code that makes it true.
    //
    // THIS CLASS'S OWN FIELDS ONLY. The base's are nulled by the base's constructor, which the
    // `super(...)` above has already run.
    void nullStringFields(const std::string& owner, SourceLocation loc) {
        const ast::ClassDecl* here = findClass(owner);
        if (here == nullptr || selfSlot_ == kNoValue) {
            return;
        }
        forEachMember<ast::FieldDecl>(*here, [&](const ast::FieldDecl& f) {
            if (f.isStatic) {
                return;   // a static is one storage location for the class, not one per object
            }
            const auto held = fieldTypeName_.find(owner + "." + f.name);
            if (held == fieldTypeName_.end() || held->second.pointerDepth != 0 ||
                !isStringNamed(held->second.name)) {
                return;
            }
            if (const ValueId at = fieldAddress(selfLoad(loc), f.name, loc); at != kNoValue) {
                storeInto(at, nullPointer(out_.module.types.ptrType(), loc), loc);
            }
        });
    }

    // WHOSE BODY IS BEING LOWERED, as a class key. A function's key is `<class key>.<member>`, so
    // the owner is everything before the LAST dot -- the last, because a shared short name is filed
    // under its full path and reading the first segment would answer `System` for all of them.
    std::string enclosingClassKey() const {
        if (fn_ == nullptr) {
            return {};
        }
        const size_t lastDot = fn_->key.rfind('.');
        return lastDot == std::string::npos ? std::string() : fn_->key.substr(0, lastDot);
    }

    // Whether a class key names something the standard library declared rather than the program.
    bool isPreludeClass(const std::string& key) const {
        const auto found = classesByKey_.find(key);
        return found != classesByKey_.end() && found->second.prelude;
    }

    void declareLifecycleHooks(const ast::ClassDecl& c, const std::string& cls) {
        const ast::Block* blocks[4] = {c.onClassLoad.get(), c.onFirstInstance.get(),
                                       c.onLastInstanceDestroyed.get(), c.onClassUnload.get()};
        for (int i = 0; i < 4; ++i) {
            if (blocks[i] == nullptr) {
                continue;
            }
            const std::string key = cls + kHookSuffix[i];
            if (out_.module.find(key) != nullptr) {
                continue;
            }
            Function* fn =
                out_.module.addFunction(key, out_.module.types.fnType(out_.module.types.voidType(), {}));
            fn->linkage = Linkage::Internal;
            fn->kind = FnKind::Method;
            fn->unwind = Unwind::Never;
            // A LOAD HOOK IS A ROOT, and it is the only thing that keeps it -- and everything its
            // body reaches -- from being stripped as unreachable. §11.2's reachability already
            // walks `init`/`fini`; filling them is what this stage owed it.
            // ...UNLESS THE CLASS WAS IMPORTED LAZILY (§37.3), in which case the hook runs on its
            // FIRST INSTANCE and not at boot -- that is the whole of what the word buys, and a
            // program that says `start` before `server loaded` printed them the other way round.
            // The call site in `new` is what keeps it reachable there.
            // ...AND A FREESTANDING PROGRAM DOES NOT RUN THE PRELUDE'S LOAD HOOKS.
            //
            // The registration IS what keeps the hook alive: it is a root, so a prelude class
            // nobody touches stops being dead the moment the entry calls it, and everything its
            // body reaches comes with it. `Test` is the only prelude class with one, its body
            // assigns two static `String`s, and a String store lowers to
            // `__polaron_str_copy`/`__polaron_str_free` -- symbols no bare-metal image has. So an
            // empty kernel failed at LINK naming two symbols its author never wrote.
            //
            // This was invisible until the String protocol was implemented: the stores went out
            // bare, so the hook was emitted and named nothing a freestanding image lacked. The
            // absence test was green because of a second defect, which is the worst way to be
            // green.
            //
            // Precise rather than broad, and the same rule the other path settled on: the guard is
            // on the BUNDLE, not on the mode alone. A prelude class a freestanding program may
            // legitimately use keeps its hook; `Test` is one the analyzer already refuses there.
            if (i == 0 && !isLazyImport(c.name)) {
                if (!out_.module.freestanding || !isPreludeClass(cls)) {
                    out_.module.init.push_back({cls, key, 0});
                }
            } else if (i == 3) {
                out_.module.fini.push_back({cls, key, 0});
            }
        }
    }

    void lowerLifecycleHooks(const ast::ClassDecl& c, const std::string& cls) {
        const ast::Block* blocks[4] = {c.onClassLoad.get(), c.onFirstInstance.get(),
                                       c.onLastInstanceDestroyed.get(), c.onClassUnload.get()};
        for (int i = 0; i < 4; ++i) {
            if (blocks[i] == nullptr) {
                continue;
            }
            Function* fn = out_.module.find(cls + kHookSuffix[i]);
            if (fn != nullptr && fn->blocks.empty()) {
                lowerBodyOf(*fn, /*owner=*/std::string(), *blocks[i]);
            }
        }
    }

    // HOW MANY OF THIS CLASS ARE ALIVE. One counter per class that asked a question about its
    // instances; nothing at all for the classes that did not, which is every class in most
    // programs. `unimport` reads the same word to refuse taking a class away while objects of it
    // are still in use, so the counter is not only for the two hooks.
    std::string instanceCounter(const std::string& cls) {
        const std::string name = cls + ".__instances";
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                return name;
            }
        }
        Global g;
        g.name = name;
        g.type = out_.module.types.intType(32);
        g.linkage = Linkage::Internal;
        g.zeroInit = true;
        out_.module.globals.push_back(std::move(g));
        return name;
    }

    // ONLY THE CLASSES THAT ASKED. A counter on every class would be a load, an add and a store in
    // every constructor in the program for a question almost none of them ever ask.
    bool countsInstances(const ast::ClassDecl& c) const {
        // ...AND A REGION CLASS, which asks the same question `unimport` asks and over the same
        // counter: `release region A` is refused while an instance of A is alive, and without the
        // count there is nothing to refuse it on.
        return c.onFirstInstance != nullptr || c.onLastInstanceDestroyed != nullptr ||
               unimportable_.count(c.name) != 0 || c.isRegionClass;
    }

    // The counter's own storage, as an address to load from and store to.
    ValueId counterSlot(const std::string& cls, SourceLocation loc) {
        Inst addr;
        addr.op = Op::ConstFn;   // §7.1: the address of a named module-level thing
        addr.type = out_.module.types.ptrType();
        addr.text = instanceCounter(cls);
        addr.loc = loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = out_.module.types.intType(32);
        return slot;
    }

    // A CONSTRUCTOR RAISES THE COUNT; a destructor lowers it. The hook runs on the EDGE -- as the
    // count leaves zero, and as it returns to zero -- so it is read before the increment and after
    // the decrement, which is why these are not one method with a sign.
    void countInstanceIn(const ast::ClassDecl& c, const std::string& cls, SourceLocation loc) {
        if (!countsInstances(c)) {
            return;
        }
        const ValueId slot = counterSlot(cls, loc);
        const ValueId live = loadFrom(slot, loc);
        if (c.onFirstInstance != nullptr) {
            callHookWhenZero(live, cls + kHookSuffix[1], loc);
        }
        Inst up;
        up.op = Op::AddWrap;
        up.type = out_.module.types.intType(32);
        up.operands.push_back(live);
        up.operands.push_back(constInt(1, 32, loc));
        up.loc = loc;
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(emit(std::move(up)));
        st.operands.push_back(slot);
        st.loc = loc;
        emit(std::move(st));
    }

    void countInstanceOut(const ast::ClassDecl& c, const std::string& cls, SourceLocation loc) {
        if (!countsInstances(c)) {
            return;
        }
        const ValueId slot = counterSlot(cls, loc);
        Inst down;
        down.op = Op::SubWrap;
        down.type = out_.module.types.intType(32);
        down.operands.push_back(loadFrom(slot, loc));
        down.operands.push_back(constInt(1, 32, loc));
        down.loc = loc;
        const ValueId left = emit(std::move(down));
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(left);
        st.operands.push_back(slot);
        st.loc = loc;
        emit(std::move(st));
        if (c.onLastInstanceDestroyed != nullptr) {
            callHookWhenZero(left, cls + kHookSuffix[2], loc);
        }
    }

    void callHookWhenZero(ValueId count, const std::string& key, SourceLocation loc) {
        const Function* hook = out_.module.find(key);
        if (hook == nullptr) {
            return;
        }
        Inst zero;
        zero.op = Op::CmpEq;
        zero.type = out_.module.types.boolType();
        zero.operands.push_back(count);
        zero.operands.push_back(constInt(0, 32, loc));
        zero.loc = loc;
        const ValueId isFirst = emit(std::move(zero));
        const BlockId run = fn_->addBlock("hook.run");
        const BlockId after = fn_->addBlock("hook.cont");
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(isFirst);
        br.edges.push_back(Edge{run, {}});
        br.edges.push_back(Edge{after, {}});
        br.loc = loc;
        emit(std::move(br));
        here_ = run;
        emitCall(hook, {}, loc);
        Inst go;
        go.op = Op::Br;
        go.edges.push_back(Edge{after, {}});
        go.loc = loc;
        emit(std::move(go));
        here_ = after;
    }

    // A CATALOG ENUM'S METHODS ARE FUNCTIONS TOO, and this walk did not exist: an `enum Motor`
    // with a `carries()` had the method neither declared nor lowered, so every call to it resolved
    // by bare name to an external symbol and the link failed with `Motor.carries` undefined. An
    // instance method's `this` is the ORDINAL -- a java-style enum's is a singleton pointer, which
    // is a different mechanism and is not this one.
    void lowerEnumBodies(const ast::EnumDecl& e) {
        for (const ast::MemberPtr& member : e.members) {
            const auto* m = dynamic_cast<const ast::MethodDecl*>(member.get());
            if (m == nullptr || m->isAbstract || m->isExtern) {
                continue;
            }
            Function* fn = out_.module.find(e.name + "." + m->name);
            if (fn == nullptr || !fn->blocks.empty()) {
                continue;
            }
            lowerBody(*fn, e.name, *m);
        }
    }

    // A fresh copy of a value struct: fresh storage, the same bytes. `memcpy` rather than a
    // field-by-field assignment because the layout is what a copy must reproduce, padding included.
    //
    // WHERE THE STORAGE COMES FROM IS THE CALLER'S QUESTION, and it used to be answered `heap` for
    // everyone. A copy bound to a LOCAL lives exactly as long as the frame, so it belongs in the
    // frame -- and asking the allocator for it meant `Node n = nodes[i]` inside a walk over a
    // million nodes called `__polaron_malloc` twenty million times and freed none of them. The
    // trusted backend allocates it in the entry block; this now does the same. A copy that becomes
    // an OWNED FIELD of another object, or that is stored into an array, outlives the frame and
    // still takes the heap -- which is what the `heap` argument is for.
    ValueId copyValueStruct(ValueId original, const std::string& cls, SourceLocation at,
                            bool heap = true) {
        if (cls.empty() || named_.count(cls) == 0) {
            return original;
        }
        const Type* shape = named_[cls];
        if (shape == nullptr || shape->kind != TypeKind::Struct) {
            return original;
        }
        TypeTable& tt = out_.module.types;
        // A REGION CLASS'S COPY COMES OUT OF THAT CLASS'S ARENA, and neither the frame nor the heap
        // will do. A narrow `A*` field stores `(i32)(p - arenaBase)`, so a copy made anywhere else
        // has an offset that is not an offset. The heap got away with it -- the delta happened to
        // fit in 32 bits and round-tripped -- and the frame does not, which is how this surfaced:
        // `region_class_copy` died with no output. Totality is the feature; every A is in A's arena,
        // including the ones the compiler makes.
        ValueId copy = kNoValue;
        if (livesInClassArena(cls)) {
            copy = classArenaAlloc(cls, shape, at);
        } else {
            Inst fresh;
            fresh.op = Op::Alloca;
            fresh.type = shape;
            if (heap) {
                fresh.extra.push_back("heap");
            }
            fresh.text = cls + ".copy";
            fresh.loc = at;
            copy = emit(std::move(fresh));
        }
        callExternal("memcpy", tt.ptrType(), {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                     {copy, original, sizeOfClass(shape, at)}, at);
        pointee_[copy] = shape;
        noteName(copy, cls);
        // A `transient` FIELD IS NOT PART OF THE VALUE (§18). It is derived or scratch state -- a
        // cache, a memo, a handle -- and copying it hands the new object the OLD one's answer for
        // a question it has not been asked yet. The memcpy above cannot tell the difference, so
        // the transient fields are put back to zero afterwards, which is what "not canonical"
        // means when the object is duplicated.
        resetTransients(copy, shape, cls, at);
        // THE MEMCPY IS THE SHALLOW HALF. Assignment in this language is a DEEP copy (spec 5) --
        // that is what makes `T*` mean something -- so every field that OWNS storage has to be
        // duplicated too, or the two objects share it and whichever dies first takes the other's
        // data with it. Only owned storage: a pointer or reference field is shared on purpose.
        deepenFields(copy, original, shape, cls, at);
        return copy;
    }

    void resetTransients(ValueId copy, const Type* shape, const std::string& cls,
                         SourceLocation at) {
        auto which = transientFields_.find(cls);
        if (which == transientFields_.end()) {
            return;
        }
        TypeTable& tt = out_.module.types;
        for (size_t i = 0; i < shape->fields.size(); ++i) {
            if (which->second.count(shape->fields[i].name) == 0) {
                continue;
            }
            const Type* ft = shape->fields[i].type;
            Inst g;
            g.op = Op::Gep;
            g.type = tt.ptrType();
            g.operands.push_back(copy);
            g.text = shape->fields[i].name;
            g.aggregate = shape;
            g.imm = static_cast<int64_t>(i);
            g.loc = at;
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(ft != nullptr && ft->kind == TypeKind::Ptr
                                      ? nullPointer(ft, at)
                                      : constInt(0, ft != nullptr && ft->kind == TypeKind::Int
                                                        ? ft->bits
                                                        : 32,
                                                 at));
            st.operands.push_back(emit(std::move(g)));
            st.loc = at;
            emit(std::move(st));
        }
    }

    // WHAT A COPY MUST DUPLICATE RATHER THAN SHARE: an array field, a String field, and a field
    // holding another value object. Everything else -- a primitive, a pointer, an interface-typed
    // reference -- is copied by the memcpy and shared deliberately.
    void deepenFields(ValueId copy, ValueId original, const Type* shape, const std::string& cls,
                      SourceLocation at) {
        // A TYPE THAT CONTAINS ITSELF WOULD RECURSE FOREVER. A `Node` holding a `Node` field --
        // directly or through a collection -- stops at the shallow copy and shares the cyclic
        // sub-object, which is the same answer the trusted path gives and for the same reason.
        if (!copyChain_.insert(cls).second) {
            return;
        }
        TypeTable& tt = out_.module.types;
        for (size_t i = 0; i < shape->fields.size(); ++i) {
            const std::string& fname = shape->fields[i].name;
            // A `weak` FIELD IS A NON-OWNING EDGE (§19), so a deep copy SHARES what it points at
            // rather than duplicating it -- that is the difference the word buys, and it is what
            // keeps copying one node from copying the whole graph back through its parent link.
            if (shape->fields[i].weak) {
                continue;
            }
            auto written = fieldTypeName_.find(cls + "." + fname);
            if (written == fieldTypeName_.end()) {
                continue;
            }
            const std::string& ftype = written->second.name;
            auto readField = [&](ValueId from) {
                Inst g;
                g.op = Op::Gep;
                g.type = tt.ptrType();
                g.operands.push_back(from);
                g.text = fname;
                g.aggregate = shape;
                g.imm = static_cast<int64_t>(i);
                g.loc = at;
                const ValueId addr = emit(std::move(g));
                Inst ld;
                ld.op = Op::Load;
                ld.type = tt.ptrType();
                ld.operands.push_back(addr);
                ld.loc = at;
                return std::pair<ValueId, ValueId>{addr, emit(std::move(ld))};
            };

            ValueId owned = kNoValue;
            if (!elementNameOf(ftype).empty()) {
                owned = duplicateArray(readField(original).second, elementNameOf(ftype), at);
            } else if (ftype == "String" || ftype == "string") {
                owned = callExternal("__polaron_str_copy", tt.ptrType(), {tt.ptrType()},
                                     {readField(original).second}, at);
            } else if (isCopyableClass(ftype)) {
                owned = copyValueStruct(readField(original).second, ftype, at);
            }
            if (owned == kNoValue) {
                continue;
            }
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(owned);
            put.operands.push_back(readField(copy).first);
            put.loc = at;
            emit(std::move(put));
        }
        copyChain_.erase(cls);
    }

    // A FRESH ARRAY BLOCK with the same length and the same bytes. The elements themselves are
    // shared when they are references and copied when they are values -- which the memcpy already
    // does for primitives, and which is left shared for objects: a per-element deep copy needs a
    // loop, and the samples that would notice do not exist yet.
    ValueId duplicateArray(ValueId block, const std::string& elemType, SourceLocation at) {
        if (block == kNoValue) {
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;
        const Type* elem = storageTypeOf(elemType);
        const int64_t stride =
            static_cast<int64_t>(std::max<uint64_t>(1, elem != nullptr ? elem->facts.size : 1));
        Inst len;
        len.op = Op::Load;
        len.type = tt.intType(64);
        len.operands.push_back(block);
        len.loc = at;
        const ValueId count = emit(std::move(len));
        Inst bytes;
        bytes.op = Op::MulWrap;
        bytes.type = tt.intType(64);
        bytes.operands.push_back(count);
        bytes.operands.push_back(constLong(stride, at));
        bytes.loc = at;
        Inst total;
        total.op = Op::AddWrap;
        total.type = tt.intType(64);
        total.operands.push_back(emit(std::move(bytes)));
        total.operands.push_back(constLong(8, at));   // the length header
        total.loc = at;
        const ValueId size = emit(std::move(total));
        const ValueId made =
            callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)}, {size}, at);
        callExternal("memcpy", tt.ptrType(), {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                     {made, block, size}, at);
        // ...AND THE ELEMENTS, when they are objects. The memcpy duplicates the SLOTS -- and a slot
        // holding a `Node` holds its address, so both arrays pointed at the same nodes and
        // `b.nodes[0].v = 99` changed `a`'s. A deep copy is deep all the way down; only a primitive
        // or a deliberately shared reference stops here.
        if (isCopyableClass(elemType) && named_.count(elemType) != 0 && elem != nullptr &&
            elem->kind == TypeKind::Ptr) {
            const ValueId i = allocaFor(fresh("arr.copy.i"), tt.intType(64));
            Inst zero;
            zero.op = Op::Store;
            zero.operands.push_back(constLong(0, at));
            zero.operands.push_back(i);
            zero.loc = at;
            emit(std::move(zero));
            const BlockId head = fn_->addBlock(fresh("arrcopy"));
            const BlockId body = fn_->addBlock(fresh("arrcopyone"));
            const BlockId out = fn_->addBlock(fresh("arrcopied"));
            gotoIfOpen(head);
            here_ = head;
            Inst more;
            more.op = Op::CmpLtS;
            more.type = tt.boolType();
            more.operands.push_back(loadFrom(i, at));
            more.operands.push_back(count);
            more.loc = at;
            branchOn(emit(std::move(more)), body, out);
            here_ = body;
            const ValueId at_i = loadFrom(i, at);
            Inst cell;
            cell.op = Op::Gep;
            cell.type = tt.sliceType(elem);
            cell.operands.push_back(made);
            cell.operands.push_back(at_i);
            cell.loc = at;
            const ValueId slot = emit(std::move(cell));
            slotType_[slot] = elem;
            const ValueId original = loadFrom(slot, at);
            noteName(original, elemType);
            const ValueId copy = copyValueStruct(original, elemType, at);
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(copy);
            put.operands.push_back(slot);
            put.loc = at;
            emit(std::move(put));
            Inst next;
            next.op = Op::AddWrap;
            next.type = tt.intType(64);
            next.operands.push_back(at_i);
            next.operands.push_back(constLong(1, at));
            next.loc = at;
            Inst step;
            step.op = Op::Store;
            step.operands.push_back(emit(std::move(next)));
            step.operands.push_back(i);
            step.loc = at;
            emit(std::move(step));
            gotoIfOpen(head);
            here_ = out;
        }
        return made;
    }

    // AN EXPRESSION THAT NAMES SOMETHING THAT ALREADY EXISTS, as opposed to one that builds a
    // fresh object nobody else holds. `T b = a;`, `T b = o.f;` and `T b = xs[i];` all duplicate;
    // `T b = new T();` and `T b = make();` hand over something already unshared.
    static bool namesExistingObject(const ast::Expr* e) {
        return dynamic_cast<const ast::IdentifierExpr*>(e) != nullptr ||
               dynamic_cast<const ast::MemberExpr*>(e) != nullptr ||
               dynamic_cast<const ast::IndexExpr*>(e) != nullptr;
    }

    // HOW MANY STARS THE ASSIGNMENT'S TARGET WAS DECLARED WITH, asked without emitting anything.
    //
    // THE TARGET IS WHAT DECIDES SHARE-OR-COPY, and this is the question that was not being asked.
    // The language's rule is one sentence: assignment copies, and to share you write `T*` or `T&`.
    // So `this.direct = this` on a `Owner* direct` SHARES -- and the copy test beside it looked at
    // the VALUE's pointer depth instead, saw `this` at zero, and deep-copied the whole object.
    //
    // Inside a constructor that is not merely slow, it is a crash: the copy recurses into the
    // object's owned children, and in a constructor the other fields have not been written yet, so
    // it `memcpy`s from whatever the fresh allocation happened to contain. `lint_program.pol`
    // segfaulted on `this.only.owner = this`, after its `printf` had run -- and because stdout is
    // buffered to a pipe, the crash ate the output and the program looked like it printed nothing.
    //
    // A PURE QUERY, so the order of evaluation does not move. `fieldAddress` already notes the
    // declared depth on the address it returns, but that address is produced after the value, and
    // reordering an assignment to learn something about it is a bigger change than knowing it.
    // WHICH CLASS AN LVALUE STANDS IN, statically. Recursive, so `this.only.owner` can ask about
    // `this.only`. Empty when it cannot be answered without lowering, which is the honest reply.
    std::string staticClassOfExpr(const ast::Expr* e) const {
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            if (id->name == "this") {
                return selfClassName_;
            }
            if (auto local = locals_.find(id->name); local != locals_.end()) {
                return classNameOf(declaredName(local->second));
            }
            if (auto f = fieldTypeName_.find(selfClassName_ + "." + id->name);
                f != fieldTypeName_.end()) {
                return classNameOf(f->second.name);
            }
            return std::string();
        }
        if (const auto* mem = dynamic_cast<const ast::MemberExpr*>(e)) {
            std::string owner = staticClassOfExpr(mem->object.get());
            for (int hops = 0; hops < 32 && !owner.empty(); ++hops) {
                if (auto f = fieldTypeName_.find(owner + "." + mem->member);
                    f != fieldTypeName_.end()) {
                    return classNameOf(f->second.name);
                }
                const ast::ClassDecl* up = findClass(owner);
                owner = up != nullptr ? up->superclass : std::string();
            }
        }
        return std::string();
    }

    int declaredTargetDepth(const ast::Expr* e) const {
        if (const auto* mem = dynamic_cast<const ast::MemberExpr*>(e)) {
            // Up the chain: the field may be the base's, and `fieldTypeName_` is keyed by the class
            // that DECLARED it.
            std::string owner = staticClassOfExpr(mem->object.get());
            for (int hops = 0; hops < 32 && !owner.empty(); ++hops) {
                if (auto f = fieldTypeName_.find(owner + "." + mem->member);
                    f != fieldTypeName_.end()) {
                    return f->second.pointerDepth;
                }
                const ast::ClassDecl* up = findClass(owner);
                owner = up != nullptr ? up->superclass : std::string();
            }
            return 0;
        }
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            if (auto local = locals_.find(id->name); local != locals_.end()) {
                return pointerDepthOf(local->second);
            }
            // A bare name inside a method may be a field of `this` (implicit this).
            if (auto f = fieldTypeName_.find(selfClassName_ + "." + id->name);
                f != fieldTypeName_.end()) {
                return f->second.pointerDepth;
            }
        }
        return 0;
    }

    // A TYPE WHOSE ASSIGNMENT COPIES. An interface or an abstract class is a reference to something
    // whose real size is not known here, and copying it by the base's size does not truncate the
    // object -- it discards it. `String` is immutable, so sharing the buffer is not observable.
    // `movable` and `unique` transfer the pointer instead, which is what those words buy.
    bool isCopyableClass(const std::string& name) {
        if (name.empty() || name == "String" || name == "string" || name == "Object") {
            return false;
        }
        if (!elementNameOf(name).empty() || name.back() == '*') {
            return false;
        }
        const ast::ClassDecl* decl = findClass(name);
        if (decl == nullptr || decl->isInterface || decl->isAbstract || decl->isMovable ||
            decl->isUnique) {
            return false;
        }
        // A JAVA-STYLE ENUM'S VALUE IS A SHARED SINGLETON (spec 12.2). Copying it would break the
        // identity that `==` on two constants relies on.
        return enums_.count(name) == 0;
    }

    // Allocate a fresh object the same size as the one passed and copy the bytes into it, then
    // point the parameter's slot at the copy. `memcpy` rather than a field-by-field assignment
    // because the class's layout is exactly what a copy has to reproduce, padding included.
    void byValueCopy(const Function& fn, const std::string& name, ValueId slot, SourceLocation at) {
        std::string cls;
        for (const Function::Param& p : fn.params) {
            if (p.name == name && p.byValue) {
                cls = p.typeName;
                break;
            }
        }
        // AN INTERFACE-TYPED PARAMETER IS A REFERENCE, and copying one by the INTERFACE's size
        // does not truncate the object -- it discards it. `drain(Iterable<int> seq)` was handed an
        // `ArrayList`, copied eight bytes of it (an interface has only the dispatch pointer), and
        // every method called on the copy read fields that were no longer there. The same argument
        // rules out an abstract class, `Object`, and a `movable`/`unique` class, whose whole point
        // is that the pointer transfers rather than the bytes -- which is what `isCopyableClass`
        // already answers for every other site that copies.
        if (cls.empty() || named_.count(cls) == 0 || !isCopyableClass(cls)) {
            return;
        }
        const Type* shape = named_[cls];
        if (shape == nullptr || shape->kind != TypeKind::Struct) {
            return;
        }
        TypeTable& tt = out_.module.types;
        const ValueId original = loadFrom(slot, at);
        // AN `interrupt` HANDLER MAY NOT ALLOCATE, and it takes its `Trap` by value -- so this,
        // which runs in every prologue with a by-value aggregate parameter, called
        // `__polaron_malloc` on the entry path of a handler: on a freestanding target there is no
        // allocator, and on a hosted one the call happens at an IRQL where taking its lock is a
        // deadlock. Neither failure is one the handler's author could see.
        //
        // EVERYWHERE ELSE IT STILL COMES FROM THE ALLOCATOR, and that is a debt rather than a
        // choice. The copy outlives nothing, so the frame is where it belongs -- and putting it
        // there requires the ELEMENT STORE to copy too, because `ArrayList<T>.add` keeps the
        // pointer it is handed and a frame copy would be dead the moment the caller returned. The
        // two are one rule. Making both changes together was tried and it moves the language's
        // value semantics for aggregates: nine samples change behaviour, among them the ones that
        // deliberately SHARE a class through a collection. It needs the escape analysis of §11.5 to
        // separate the two cases, and belongs with it rather than here.
        //
        // What it costs meanwhile is measured, not guessed: one leaked copy per call taking an
        // aggregate by value -- `Dual.add` allocates twice where the other path allocates once.
        Inst fresh;
        fresh.op = Op::Alloca;
        fresh.type = shape;
        if (fn.kind != FnKind::Interrupt) {
            fresh.extra.push_back("heap");
        }
        fresh.text = name + ".copy";
        fresh.loc = at;
        const ValueId copy = emit(std::move(fresh));
        callExternal("memcpy", tt.ptrType(), {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                     {copy, original, sizeOfClass(shape, at)}, at);
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(copy);
        st.operands.push_back(slot);
        st.loc = at;
        emit(std::move(st));
    }

    // How many bytes a class occupies. The type table does not compute struct sizes -- the backend
    // asks LLVM's data layout, which is the only place that knows about padding -- so this asks for
    // it with the same trick C uses: the address of element one of a null pointer.
    ValueId sizeOfClass(const Type* shape, SourceLocation at) {
        TypeTable& tt = out_.module.types;
        Inst in;
        in.op = Op::SizeOf;
        in.type = tt.intType(64);
        in.aggregate = shape;
        in.loc = at;
        return emit(std::move(in));
    }

    static SourceLocation loc(const ast::Block& b) { return b.loc; }

    void lowerBody(Function& fn, const std::string& owner, const ast::MethodDecl& m) {
        // The CLAUSES, not just their text: `Function::contracts` keeps the source spelling for
        // diagnostics, and a check needs the expression. Handed across here because `lowerBodyOf`
        // is shared with constructors and destructors, which carry their own.
        pendingRequires_.clear();
        for (const auto& r : m.requiresClauses) {
            pendingRequires_.push_back(r.get());
        }
        // ...AND THE CLAUSES CHECKED ON THE WAY OUT. `ensures` is the method's own promise about the
        // state it leaves behind, and a class `invariant` is the type's; §29 checks both at every
        // exit of every non-static method. Only the `requires` half was being emitted, so a method
        // that deliberately breaks an invariant ran to completion and the program carried on holding
        // an object in the one state its type says it is never in -- `generic_invariant_enforced`
        // expects the program to STOP there and it printed the next line instead.
        stagedExit_.clear();
        for (const auto& e : m.ensuresClauses) {
            stagedExit_.push_back(ExitCheck{e.get(), "ensures"});
        }
        pendingInvariants_.clear();
        if (!m.isStatic) {
            const ast::ClassDecl* decl = findClass(owner);
            if (decl != nullptr) {
                for (const auto& inv : decl->invariants) {
                    pendingInvariants_.push_back(inv.get());   // all of them, for the entry assumes
                    // ...BUT ONLY THE ONES THIS METHOD COULD HAVE BROKEN. The rule is in `cgutil`
                    // with its reasoning; the short of it is that a method assigning none of the
                    // fields an invariant mentions leaves it exactly as it found it, and the
                    // invariant held on the way in. Without this, `HashMap$int$int.get` carried ten
                    // checks it can never fail, grew past what the inliner would take, and
                    // `coll_map` ran 1.25x behind the trusted path -- which has had the rule all
                    // along and emits none of them.
                    if (cgutil::invariantCanBreakIn(inv.get(), m.body)) {
                        stagedExit_.push_back(ExitCheck{inv.get(), "invariant"});
                    }
                }
            }
        }
        lowerBodyOf(fn, owner, m.body);
    }

    // WHAT `old(...)` REFERS TO, captured at entry.
    //
    // An `ensures this.count == old(this.count) + 1` is a statement about two moments, and only one
    // of them is still available when the check runs. The clause is evaluated at every exit, by
    // which time `this.count` is the NEW count; `old(this.count)` has to have been put somewhere
    // before the body touched it, and this is the only place where "before" is still true.
    //
    // The PIR path had none of this. The node fell through the expression lowering entirely, which
    // reported it (`struct polaron::ast::OldExpr x33`) and lowered the whole clause to nothing --
    // so every `ensures` mentioning `old` was a promise the second backend did not check, in a
    // standard library where they are the collections' central invariant. The traversal is
    // `cgutil::collectOld` rather than a second copy here, because a slot is allocated per node in
    // the order it comes back and two walks that disagree would silently pair up the wrong ones.
    void snapshotOldValues() {
        oldSlots_.clear();
        if (pendingExit_.empty()) {
            return;
        }
        std::vector<const ast::OldExpr*> olds;
        for (const ExitCheck& c : pendingExit_) {
            cgutil::collectOld(c.clause, olds);
        }
        for (const ast::OldExpr* o : olds) {
            const ValueId v = lowerExpr(o->inner.get());
            if (v == kNoValue || fn_ == nullptr || fn_->value(v) == nullptr) {
                continue;
            }
            const Type* held = fn_->value(v)->type;
            const ValueId slot = entryAlloca(held, "old");
            slotType_[slot] = held;
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(v);
            st.operands.push_back(slot);
            st.loc = o->loc;
            emit(std::move(st));
            oldSlots_[o] = slot;
        }
    }

    // Emitted at every exit: before a `return`, and on the fall-through end of the body. Guarded
    // against itself because an `ensures` clause is an expression that may call a method, and that
    // method's own exit checks must not re-enter this one for the frame it was called from.
    void emitExitChecks(SourceLocation at) {
        if (pendingExit_.empty() || inExitChecks_) {
            return;
        }
        inExitChecks_ = true;
        const std::vector<ExitCheck> checks = pendingExit_;
        for (const ExitCheck& c : checks) {
            emitContractGuard(c.clause, c.kind);
        }
        inExitChecks_ = false;
    }

    // Whether re-reading this expression on the failure path is free of consequences. A contract
    // that fails is about to stop the program and the most useful thing it can say is what the two
    // sides WERE -- but reading them means running the expression a second time, which is only
    // honest for an expression that does nothing but read. Anything else goes unquoted. The trusted
    // path decides this the same way and over the same list (`isPureToReread`), and it has to: the
    // differential compares the two reports, so a clause quoted here and not there is a difference.
    static bool pureToReread(const ast::Expr* e) {
        if (e == nullptr) {
            return false;
        }
        if (dynamic_cast<const ast::IdentifierExpr*>(e) != nullptr ||
            dynamic_cast<const ast::IntLiteralExpr*>(e) != nullptr ||
            dynamic_cast<const ast::BoolLiteralExpr*>(e) != nullptr ||
            dynamic_cast<const ast::CharLiteralExpr*>(e) != nullptr) {
            return true;
        }
        if (const auto* m = dynamic_cast<const ast::MemberExpr*>(e)) {
            return m->object == nullptr || pureToReread(m->object.get());
        }
        if (const auto* u = dynamic_cast<const ast::UnaryExpr*>(e)) {
            return u->op != "++" && u->op != "--" && pureToReread(u->operand.get());
        }
        if (const auto* ca = dynamic_cast<const ast::CastExpr*>(e)) {
            return pureToReread(ca->operand.get());
        }
        if (const auto* b = dynamic_cast<const ast::BinaryExpr*>(e)) {
            return pureToReread(b->lhs.get()) && pureToReread(b->rhs.get());
        }
        return false;
    }

    // The clause as the source spells it, trimmed. Empty when no lookup was handed in, or when the
    // clause came from the prelude, which has no file behind it.
    std::string clauseText(const SourceLocation& loc) const {
        if (!sourceLine_) {
            return "";
        }
        const std::string line = sourceLine_(loc.file, loc.line);
        const std::size_t first = line.find_first_not_of(" \t");
        if (first == std::string::npos) {
            return "";
        }
        const std::size_t last = line.find_last_not_of(" \t\r");
        return line.substr(first, last - first + 1);
    }

    // ONE contract check, wherever it is written. `requires` at the entry and `ensures`/`invariant`
    // at every exit are the same instruction with a different word in it, and the REPORT is the
    // whole of what makes them worth having: which clause, in whose method, at which line, and --
    // when the clause is a comparison that can be read twice -- what the two sides actually held.
    // Emitting only the boolean printed `contract violated: requires` and nothing else, which in a
    // file with three contracts is a bisection and across a codebase is a search.
    void emitContractGuard(const ast::Expr* clause, const char* kind) {
        const ValueId v = lowerExpr(clause);
        if (v == kNoValue) {
            return;
        }
        Inst g;
        g.op = Op::GuardContract;
        g.operands.push_back(asBoolean(v, clause->loc));
        g.text = kind;
        // The two spare strings the report needs and the instruction has nowhere else to put: the
        // clause as written, and the file it was written in. The backend composes the message,
        // because the one piece still missing there is the emitted name of the enclosing method.
        g.extra.push_back(clauseText(clause->loc));
        g.extra.push_back(std::string(clause->loc.file));
        const auto* cmp = dynamic_cast<const ast::BinaryExpr*>(clause);
        const bool comparison =
            cmp != nullptr && (cmp->op == "==" || cmp->op == "!=" || cmp->op == "<" ||
                               cmp->op == ">" || cmp->op == "<=" || cmp->op == ">=");
        if (comparison && pureToReread(cmp->lhs.get()) && pureToReread(cmp->rhs.get())) {
            const ValueId l = lowerExpr(cmp->lhs.get());
            const ValueId r = lowerExpr(cmp->rhs.get());
            if (l != kNoValue && r != kNoValue && isIntegral(l) && isIntegral(r)) {
                g.operands.push_back(l);
                g.operands.push_back(r);
            }
        }
        g.loc = clause->loc;
        emit(std::move(g));
    }

    bool isIntegral(ValueId v) const {
        if (fn_ == nullptr) {
            return false;
        }
        const ValueDef* d = fn_->value(v);
        return d != nullptr && d->type != nullptr &&
               (d->type->kind == TypeKind::Int || d->type->kind == TypeKind::Bool ||
                d->type->kind == TypeKind::Addr);
    }

    // THE OWNER IS A NAME. It used to be the whole `ClassDecl`, of which exactly one field was
    // read -- and a lambda had to invent an empty declaration to call this at all, while an enum's
    // method has no declaration to invent.
    void lowerBodyOf(Function& fn, const std::string& owner, const ast::Block& body) {
        fn_ = &fn;
        here_ = fn.addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        // Per-body state, all of it. A map left over from the previous method is a value id from
        // another function's numbering, which resolves to something and is wrong.
        //
        // The exit checks belong to the METHOD, and `lowerBodyOf` is also the constructor's and the
        // destructor's entry point -- neither of which was handed any. Taking the staged list here
        // and emptying it is what keeps the previous method's `ensures` from being checked at the
        // end of the next constructor, where the names it mentions do not even exist.
        pendingExit_ = std::move(stagedExit_);
        stagedExit_.clear();
        inExitChecks_ = false;
        locals_.clear();
        slotType_.clear();
        declaredAs_.clear();
        storage_.clear();
        stringTemps_.clear();
        stringSlots_.clear();
        volatilePointee_.clear();
        volatilePointerSlots_.clear();
        pointee_.clear();
        paramTypes_.clear();
        pointeeOfSlot_.clear();
        clearFieldShapes();
        weakSlotAt_.clear();
        cCallable_.clear();
        labels_.clear();
        abstained_.clear();
        nextLabel_.clear();
        scanLabels(body);   // before anything is lowered: see `scanLabels`
        // A LOCAL THAT IS RETURNED BY NAME ESCAPES ITS FRAME, and the `new` bound to it has to go
        // to the heap. The DIRECT form (`return new Vec(...)`) is caught where the return is
        // lowered; this is the builder shape -- `Vec v = new Vec(a, b); return v;` -- and it has to
        // be decided before the declaration is reached, which is why it is a walk and not a rule at
        // the return. Only for a method that hands back a POINTER: a value class is copied into the
        // caller's result, so nothing of this frame outlives it and promoting would allocate a
        // temporary, fill it, copy it out and drop the only pointer to it.
        //
        // The walk is `cgutil`'s, shared with the trusted path. While only that path ran it, this
        // one returned zeros at -O2 and the right numbers at -O0 -- the signature of reading a
        // frame nobody had reused yet.
        if (fn.signature != nullptr && fn.signature->element != nullptr &&
            fn.signature->element->kind == TypeKind::Ptr) {
            std::set<std::string> escaping;
            for (const auto& s : body.statements) {
                cgutil::collectReturnedNames(s.get(), escaping);
            }
            // ...and NOT a region class, which is the half the trusted path learned separately and
            // this one would otherwise have had to learn again. Its instances already outlive the
            // frame -- they come from the type's own region, released at program exit -- so there is
            // no promoting to do, and doing it made the other backend refuse the very line the
            // author wrote. The predicate is a parameter precisely so both consumers answer it from
            // their own tables; `livesInClassArena` here is the same question `Impl` asks there.
            for (const auto& s : body.statements) {
                cgutil::promoteEscapingNews(s.get(), escaping, [this](const std::string& cls) {
                    return livesInClassArena(cls);
                });
            }
        }
        loops_.clear();
        handlers_.clear();
        statics_.clear();
        lazyLocals_.clear();

        // The entry block's parameters ARE the function's -- §4. Declaring them twice would be two
        // sources for one fact.
        // A LOCAL HAS STORAGE, and a read of it is a `load`.
        //
        // The first version bound a name straight to an SSA value, which reads well and cannot
        // express `x = x + 1` -- a value is defined once, and assignment is not a definition. So
        // every local and every parameter gets an `alloca`, writes are `store` and reads are `load`.
        // What that costs is a slot per local in the unoptimised IR; what removes it is the
        // immutability pass of §11.4, which is where that decision belongs -- a lowering that tries
        // to be clever about which locals need storage is a lowering that is wrong occasionally.
        uint32_t index = 0;
        std::vector<std::pair<std::string, ValueId>> incoming;
        if (fn.signature != nullptr) {
            for (const Field& p : fn.signature->fields) {
                // The NAME comes from the function, not from the interned type -- see
                // `Function::Param`.
                const std::string name =
                    index < fn.params.size() ? fn.params[index].name : std::string();
                const ValueId v =
                    fn.addValue(p.type, ValueOrigin::BlockParam, here_, index, name);
                fn.block(here_)->params.push_back(v);
                if (index < fn.params.size()) {
                    noteName(v, fn.params[index].typeName, fn.params[index].pointerDepth);
                }
                if (!name.empty()) {
                    incoming.emplace_back(name, v);
                    paramTypes_[name] = p.type;
                }
                ++index;
            }
        }
        // A `naked` METHOD GETS NO PROLOGUE. Its body is raw assembly that owns the machine state
        // exactly as the hardware handed it over -- an entry point with no valid stack, or one
        // running on the caller's -- and a compiler-emitted prologue would corrupt precisely what
        // such a body exists to control. LLVM says the same in its own terms and refuses the module:
        // `cannot use argument of naked function`, which is what spilling `idt_lidt`'s `address ptr`
        // into a frame slot did. The parameters stay in the SIGNATURE, because that is the calling
        // convention the asm is written against; what does not happen is any code touching them.
        for (const auto& [name, v] : fn.conv == Conv::Naked
                                         ? std::vector<std::pair<std::string, ValueId>>{}
                                         : incoming) {
            const ValueId slot = allocaFor(name, fn.value(v)->type);
            // The declared type travels from the parameter into the slot every read of it goes
            // through -- a `String` parameter must still be a `String` when a method is called on
            // it, AND A `Node*` MUST STILL BE A POINTER. The stars were being dropped here, so
            // `this.tail = x` on a `Node* x` read as a value assignment and deep-copied the node.
            noteName(slot, declaredName(v), pointerDepthOf(v));
            // A BY-VALUE OBJECT PARAMETER IS COPIED ON ENTRY. Done here, in the callee, rather than
            // at every call site: one place, and it holds for an indirect call too. Without it,
            // `method byValue(Box b) { b.v = 99; }` wrote through the caller's pointer and the
            // caller saw 99 where the language says it sees 7.
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(v);
            st.operands.push_back(slot);
            emit(std::move(st));
            // AFTER the argument is in the slot, not before: the copy reads what the slot holds,
            // and reading it first copied an uninitialised frame and was then overwritten by the
            // very pointer the copy exists to avoid sharing.
            byValueCopy(fn, name, slot, loc(body));
        }
        selfSlot_ = locals_.count("this") != 0 ? locals_["this"] : kNoValue;
        selfClass_ = named_.count(owner) != 0 ? named_[owner] : nullptr;
        selfClassName_ = owner;   // `super(...)` needs the DECLARATION, not the interned type
        // Contracts, as facts. Emitted BEFORE anything reads them so the guard eliminator can use
        // them; the lowering to `llvm.assume` happens last, in the pass, not here.
        //
        // These carry the clause's TEXT and nothing else, which is all a `Contract` holds. The fact
        // the guard eliminator actually reads comes from the `guard.contract` below, because that
        // is the one with a condition attached to it -- see `provenBy` in the passes.
        for (const Contract& k : fn.contracts) {
            if (k.kind != Contract::Kind::Requires) {
                continue;
            }
            Inst f;
            f.op = Op::FactRequires;
            f.text = k.text;
            emit(std::move(f));
        }
        // `old(...)`, SNAPSHOTTED WHILE IT IS STILL OLD. Taken here -- after the parameters and
        // `this` are in their slots, before a single statement of the body has run -- because that
        // is the only moment at which the entry-time value is still readable.
        snapshotOldValues();
        // A CONTRACT IS ALSO A CHECK. The fact above is what §11.3 reads to delete a redundant
        // guard; it is not what stops a program whose precondition is false. Only the fact was
        // emitted, so `requires seats > 0` let a call through with zero and the program carried on
        // -- `contract_report` printed `seats 4` where the trusted path prints `contract violated:
        // requires`. Two different jobs, and the fact was doing one of them.
        for (const ast::Expr* clause : pendingRequires_) {
            emitContractGuard(clause, "requires");
        }
        pendingRequires_.clear();
        // A CONTRACT THAT PAYS FOR ITSELF: every declared `invariant` is handed to the optimiser at
        // method entry as a fact it may rely on.
        //
        // Sound because of something the language already does: every exit of every method checks
        // every invariant, and so does the constructor -- there is no switch that turns contracts
        // off. An object can therefore only be observed by a later method in a state some earlier
        // exit already verified. If an invariant were false, the program would have stopped at the
        // exit that broke it, before anything here could rely on it. So this assumes only what is
        // checked, and nothing is taken on trust.
        //
        // What it buys, on `HashMap`: the class declares `this.used.length() == this.cap` (and the
        // same for `keys`/`values`), plus `count >= 0` and `count < cap`. A probe indexes with
        // `h & (cap - 1)`, which lies in `[0, cap-1]`; with `length == cap` known, and `cap >= 1`
        // following from the other two, the bounds check on every probe is provably true and LLVM
        // deletes it. `HashMap$int$int.put` came out of the trusted path with ten of these and out
        // of this one with none, and `mapkeys` ran 1.23x behind because of it.
        //
        // As a FACT rather than as a new elision rule, on purpose: there is no new place where a
        // bounds check can be dropped by mistake. LLVM removes a check only where it can prove the
        // index in range, exactly as it always has; this stops hiding the facts from it. §11.10
        // turns `fact.invariant` into `llvm.assume` in the backend, after the guard eliminator has
        // had its own use of it.
        for (const ast::Expr* inv : pendingInvariants_) {
            const ValueId held = lowerExpr(inv);
            if (held == kNoValue) {
                continue;   // an invariant this cannot evaluate is simply not handed over
            }
            const Type* t = fn_->value(held)->type;
            if (t == nullptr || (t->kind != TypeKind::Bool && t->kind != TypeKind::Int)) {
                continue;
            }
            Inst f;
            f.op = Op::FactInvariant;
            f.operands.push_back(t->kind == TypeKind::Bool
                                     ? held
                                     : cmp(Op::CmpNe, held, constInt(0, t->bits, inv->loc),
                                           inv->loc));
            f.text = "invariant";
            f.loc = inv->loc;
            emit(std::move(f));
        }
        pendingInvariants_.clear();

        // A LAMBDA'S CAPTURES ARE READ OUT OF ITS ENVIRONMENT, in the order the creation site wrote
        // them, into locals of the same name -- so the body's references to them need no special
        // case at all, which is the whole reason to do it here rather than at every use.
        if (!pendingCaptures_.empty() && locals_.count("__env") != 0) {
            const ValueId env = loadFrom(locals_["__env"], SourceLocation{});
            int64_t at = 0;
            for (const Captured& cap : pendingCaptures_) {
                const Type* held = cap.type != nullptr ? cap.type : out_.module.types.ptrType();
                Inst g;
                g.op = Op::Gep;
                g.type = out_.module.types.ptrType();
                g.operands.push_back(env);
                g.imm = at;
                const ValueId addr = emit(std::move(g));
                // ONE MACHINE WORD PER CAPTURE, holding the value itself for a `byvalue` capture
                // and the variable's own storage for a `byref` one. Reading it back as the type it
                // was written as is the whole of the agreement between the two ends.
                if (cap.byRef) {
                    slotType_[addr] = out_.module.types.ptrType();
                    const ValueId shared = loadFrom(addr, SourceLocation{});
                    locals_[cap.name] = shared;
                    slotType_[shared] = held;
                    noteName(shared, cap.typeName);
                } else {
                    slotType_[addr] = held;
                    const ValueId slot = allocaFor(cap.name, held);
                    Inst st;
                    st.op = Op::Store;
                    st.operands.push_back(loadFrom(addr, SourceLocation{}));
                    st.operands.push_back(slot);
                    emit(std::move(st));
                    noteName(slot, cap.typeName);
                }
                at += 8;
            }
        }
        pendingCaptures_.clear();

        // THE VTABLE POINTER IS WRITTEN BY THE CONSTRUCTOR, after any `super(...)` has written the
        // base's -- so the most derived table is the one that survives, which is what makes an
        // override win. Written here rather than at the allocation site because a subclass's
        // constructor runs after its base's and must overwrite it.
        // ...AND `super(...)` RUNS FIRST, before that write. The base's constructor writes the
        // BASE's table, so a derived constructor that wrote its own table and then called `super`
        // had it overwritten: every object of a subclass carried its base's dispatch table, and
        // `acc.addInterest()` on a `Savings` through an `Account*` ran `Account`'s empty one.
        // `bank` printed 1500 where the program computes 1650, with nothing to say a virtual call
        // had gone to the wrong body.
        size_t firstStatement = 0;
        if (fn.kind == FnKind::Constructor && !body.statements.empty() &&
            beginsWithSuperCall(body.statements.front().get())) {
            lowerStmt(body.statements.front().get());
            firstStatement = 1;
        } else if (fn.kind == FnKind::Constructor) {
            // AND A CONSTRUCTOR THAT WRITES NO `super(...)` STILL BUILDS ITS BASE. A subclass's
            // object contains its base's part, and that part has an initialiser: `Derived() {}`
            // over a `Base` that allocates in its own constructor left the inherited field null,
            // so `cascade delete` found nothing to follow and `~Leaf` never ran. Only the
            // no-argument form is implicit -- a base that needs arguments must be written out, and
            // the analyzer says so.
            if (const ast::ClassDecl* here = findClass(owner);
                here != nullptr && !here->superclass.empty()) {
                if (const Function* base = resolveKey(here->superclass + "." + here->superclass);
                    base != nullptr && base->signature != nullptr &&
                    base->signature->fields.size() == 1) {
                    emitCall(base, {selfLoad(SourceLocation{})}, SourceLocation{});
                }
            }
        }
        if (fn.kind == FnKind::Constructor && hasVtable_.count(owner) != 0 &&
            selfSlot_ != kNoValue) {
            Inst addr;
            addr.op = Op::ConstFn;   // §7.1: the address of a named module-level thing
            addr.type = out_.module.types.ptrType();
            addr.text = owner + ".vtable";
            const ValueId table = emit(std::move(addr));
            storeAt(selfLoad(SourceLocation{}), 0, table, SourceLocation{});
        }
        // AN INLINE FIELD INITIALISER RUNS IN EVERY CONSTRUCTOR, before its body -- that is what
        // writing `public mutable int width = 80;` means. Nothing was running them, so a class that
        // states its defaults at the field and takes no arguments came out entirely zero.
        if (fn.kind == FnKind::Constructor) {
            nullStringFields(owner, loc(body));
            applyFieldInitialisers(owner);
        }
        // §32.5: the live-instance count moves at the two ends of an object's life, and the edge
        // hooks run on it. Before the body in both cases -- `onFirstInstance` must have run before
        // the constructor it precedes does anything, and a destructor's body is allowed to be the
        // last thing that observes the object.
        if (const ast::ClassDecl* here = findClass(owner); here != nullptr) {
            if (fn.kind == FnKind::Constructor) {
                countInstanceIn(*here, owner, loc(body));
            } else if (fn.kind == FnKind::Destructor) {
                countInstanceOut(*here, owner, loc(body));
            }
        }

        // THE METHOD BODY IS A SCOPE TOO, and a label written at its top level lives in it. Without
        // it on the stack a `goto` out of a nested block found no owning scope and tore nothing
        // down -- which is the ordinary shape of the construct, since a `goto` that leaves nothing
        // has no cleanup to owe.
        blockScopes_.push_back({&body, scoped_.size(), deferred_.size()});
        for (size_t at = firstStatement; at < body.statements.size(); ++at) {
            lowerStmt(body.statements[at].get());
        }
        // A DESTRUCTOR ENDS BY DESTROYING THE BASE. `~Derived` runs its own body and then the
        // base's, which the language guarantees and which nothing here was doing -- `virtual_dtor`
        // printed one line where the program prints two. Emitted after the body, before the
        // implicit return, so a `return` inside the body is the one case this misses; the language
        // does not allow one in a destructor.
        if (fn.kind == FnKind::Destructor && !blockClosed()) {
            const ast::ClassDecl* here = findClass(owner);
            const ast::ClassDecl* up =
                here != nullptr && !here->superclass.empty() ? findClass(here->superclass) : nullptr;
            if (up != nullptr) {
                if (const std::string base = destructorOf(*up); !base.empty()) {
                    if (const Function* target = resolveKey(base)) {
                        emitCall(target, {selfLoad(SourceLocation{})}, SourceLocation{});
                    }
                }
            }
        }
        // A body that fell off the end returns. `void` returns nothing; anything else is a gap the
        // analyzer would already have caught, so `unreachable` is honest here.
        if (!blockClosed()) {
            emitExitChecks(SourceLocation{});
            runDeferred(SourceLocation{});   // falling off the end is an exit like any other
            destroyScoped(0, SourceLocation{});
            Inst r;
            const Type* ret = fn.signature != nullptr ? fn.signature->element : nullptr;
            if (ret != nullptr && ret->kind == TypeKind::Void) {
                r.op = Op::Ret;
            } else {
                r.op = Op::Unreachable;
            }
            emit(std::move(r));
        }
        deferred_.clear();
        scoped_.clear();
        unwindObjects_.clear();
        unwindDefers_.clear();
        fn_ = nullptr;
    }

    bool blockClosed() const {
        const Block* b = fn_->block(here_);
        return b != nullptr && !b->insts.empty() && isTerminator(b->insts.back().op);
    }

    ValueId emit(Inst&& in) {
        Block* b = fn_->block(here_);
        if (b == nullptr) {
            return kNoValue;
        }
        // EVERY FRAME SLOT LIVES IN THE ENTRY BLOCK -- all of them, not just the named locals.
        //
        // `allocaFor` has always said this and only named locals went through it. A `new T() on
        // stack`, the `%ret.value` a by-value return copies through, the `ffi.byval` scratch a small
        // struct travels in at a C boundary -- each of those emitted its `alloca` where it stood,
        // which makes it a DYNAMIC stack allocation. One inside a loop grows the frame every
        // iteration and gives nothing back.
        //
        // Unoptimised that is bounded by the call: each frame is released on return. Inlined into a
        // caller's loop it is not, and a kernel with a few kilobytes of stack per CPU runs off the
        // end of it and starts writing over whatever is next -- which pico showed as a different
        // fault on every boot, the signature of a wild write rather than of a miscompiled
        // expression. Hoisting them all is one line here and matches what the trusted path emits.
        if (in.op == Op::Alloca &&
            std::find(in.extra.begin(), in.extra.end(), "heap") == in.extra.end()) {
            return entryAlloca(in.type, in.text);
        }
        // §37.5: AN ACCESS TO VOLATILE STORAGE IS NEVER MOVED, MERGED OR DELETED.
        //
        // `Inst::isVolatile` existed and the backend honoured it; nothing ever set it. At -O0 that
        // costs nothing -- an unoptimised module executes every load and store as written -- and it
        // is the whole difference in a kernel the moment an optimiser runs: a fill loop over a
        // framebuffer nobody reads is exactly what dead-store elimination exists to delete, a spin
        // on a status register becomes one read hoisted out of the loop, and two reads of a
        // hardware port become one. pico stopped after the graphics console with -O2 on and worked
        // with it off, which is that shape.
        //
        // Decided HERE because every load and store in this lowering goes through this method,
        // whatever path built it: a field, an index, a raw pointer, a spill. The address operand is
        // asked whether it points at volatile storage; `volatilePointee_` carries that, propagated
        // from the declaration through every `gep` derived from it.
        if (in.op == Op::Load && !in.operands.empty()) {
            in.isVolatile = in.isVolatile || volatilePointee_.count(in.operands[0]) != 0;
        } else if (in.op == Op::Store && in.operands.size() > 1) {
            in.isVolatile = in.isVolatile || volatilePointee_.count(in.operands[1]) != 0;
        }
        ValueId result = kNoValue;
        // A VOID RESULT IS NOT A RESULT. `call` is an opcode that produces a value, and a call to a
        // `void` method is the one case where it does not -- there is no such thing as a value of
        // type void. Emitting one made the second backend map an LLVM void CallInst as a usable
        // value, and the first use of it was a segmentation fault with no stack worth reading.
        const bool voidResult = in.type != nullptr && in.type->kind == TypeKind::Void;
        // AN ALLOCATION'S TYPE IS WHAT IT MAKES; ITS RESULT IS A POINTER TO THAT. §7.4 says so and
        // `allocaFor` has always done it by hand, but `new T()` came through here and took its
        // result type from `in.type` -- so an object value was typed as the CLASS rather than as a
        // pointer to it. The store then put a pointer into a slot declared to hold the whole
        // object, and the load beside it read the object where a pointer was wanted and passed
        // `undef` to the method. One sample printed nothing; nothing else noticed.
        const Type* resultType = (in.op == Op::Alloca || in.op == Op::RegionAlloc)
                                     ? out_.module.types.ptrType()
                                     : in.type;
        if (producesValue(in.op) && in.type != nullptr && !voidResult) {
            result = fn_->addValue(resultType, ValueOrigin::Instruction, here_,
                                   static_cast<uint32_t>(b->insts.size()), "");
            in.result = result;
        }
        // §37.5: VOLATILITY TRAVELS WITH THE ADDRESS. `px[i]` is a `gep` off `px`, and
        // `rawOffset` goes through a `ptrtoint`, an add and an `inttoptr` -- three instructions,
        // each of which has to hand the fact on or the store at the end of the chain is an
        // ordinary store. So any instruction that PRODUCES an address from one keeps it.
        //
        // Deliberately generous: marking one access volatile that need not be costs a little speed,
        // and missing one costs a device register. Over-approximating here is the safe direction.
        if (result != kNoValue && resultType != nullptr &&
            (resultType->kind == TypeKind::Ptr || resultType->kind == TypeKind::Addr)) {
            for (ValueId op : in.operands) {
                if (volatilePointee_.count(op) != 0) {
                    volatilePointee_.insert(result);
                    break;
                }
            }
        }
        b = fn_->block(here_);   // addValue does not reallocate blocks, but the habit is cheap
        b->insts.push_back(std::move(in));
        return result;
    }

    // A frame slot for a named local, made once. The slot's TYPE is the local's; the value the
    // slot yields is a pointer, which is why `slotType_` is kept -- a `load` needs to know what it
    // is loading, and asking the pointer is asking a type that was deliberately made opaque.
    // EVERY SLOT LIVES IN THE ENTRY BLOCK, whatever block declared the variable.
    //
    // Emitting the `alloca` where the declaration is reads naturally and is wrong: a variable
    // declared inside an `if` produces a slot in that branch, and every use after the join is a use
    // the definition does not dominate. Verifier rule 1 said so thirty-five times in one method the
    // first time the prelude was lowered.
    //
    // The entry block dominates every block by construction, so a slot placed there is available
    // everywhere -- which is also why every real lowering does this and why the immutability pass
    // (§11.4) is the right place to decide which slots deserve to exist at all.
    ValueId allocaFor(const std::string& name, const Type* type) {
        auto it = locals_.find(name);
        // THE SAME NAME IN TWO SCOPES IS TWO VARIABLES, and they need not agree on width. `locals_`
        // is flat per body, so `long v` in one branch and `int v` in another shared a slot: the
        // second stored four bytes into an eight-byte cell and read all eight back, and a field
        // holding 41 printed as 4294967337 -- the neighbouring boolean, read as the high half.
        // Reusing the slot is right when the type matches (a re-entered loop body, a re-declared
        // temporary); a different type means a different variable.
        if (it != locals_.end()) {
            const bool sameShape =
                type == nullptr || slotType_.count(it->second) == 0 || slotType_[it->second] == type;
            if (sameShape) {
                return it->second;
            }
        }
        Block* entry = fn_->block(entryBlock_);
        if (entry == nullptr) {
            return kNoValue;
        }
        // `Alloca`'s TYPE IS WHAT IT ALLOCATES; its RESULT is a pointer to that. The two were both
        // `ptr`, so a `slice<T>` local -- sixteen bytes -- got eight bytes of stack and the store
        // ran off the end of its own slot. The program linked, ran, and segfaulted.
        // NEVER `void`. A local whose type this pass could not work out arrived as `void`, and
        // `alloca void` is not a thing: LLVM asserts, and an assertion in a Release build is a
        // segmentation fault with no message. A slot has to hold something; a pointer is the
        // honest guess for a type we do not know.
        const bool usable = type != nullptr && type->kind != TypeKind::Void;
        Inst a;
        a.op = Op::Alloca;
        a.type = usable ? type : out_.module.types.ptrType();
        a.text = name;
        const ValueId slot = fn_->addValue(out_.module.types.ptrType(), ValueOrigin::Instruction,
                                           entryBlock_, allocaAt_, name);
        a.result = slot;
        entry->insts.insert(entry->insts.begin() + static_cast<long>(allocaAt_), std::move(a));
        ++allocaAt_;
        // The insertion moved everything after it, so the entry block's value table has to move too
        // -- rule 1 checks exactly that agreement.
        for (size_t i = 0; i < entry->insts.size(); ++i) {
            const ValueId r = entry->insts[i].result;
            if (r != kNoValue && r < fn_->values.size()) {
                fn_->values[r].indexInBlock = static_cast<uint32_t>(i);
            }
        }
        locals_[name] = slot;
        slotType_[slot] = usable ? type : out_.module.types.ptrType();
        // A local that holds an object carries the class with it, for the same reason a field does.
        if (type != nullptr && type->kind == TypeKind::Struct && type->nominal) {
            pointeeOfSlot_[slot] = type;
        }
        return slot;
    }

    // STORAGE IN THE FRAME FOR SOMETHING WITH NO NAME -- what `new T() on stack` makes.
    //
    // In the ENTRY BLOCK, for the reason above and one more that only shows with an optimiser: an
    // `alloca` anywhere else is a DYNAMIC stack allocation, and one inside a loop grows the frame on
    // every iteration with nothing to give it back. Unoptimised each call has its own frame and the
    // leak is bounded by the call; inlined into a caller's loop it is not, and a kernel with a few
    // kilobytes of stack per CPU runs off the end of it and starts writing over whatever is next.
    // pico showed that as a different fault on every boot -- the signature of a wild write, not of a
    // miscompiled expression. The trusted path has always put these in the entry block, one per
    // site, which is also what makes `new Rect(...) on stack` inside a paint loop free.
    ValueId entryAlloca(const Type* type, const std::string& label) {
        Block* entry = fn_->block(entryBlock_);
        if (entry == nullptr) {
            return kNoValue;
        }
        const bool usable = type != nullptr && type->kind != TypeKind::Void;
        Inst a;
        a.op = Op::Alloca;
        a.type = usable ? type : out_.module.types.ptrType();
        a.text = label;
        const ValueId slot = fn_->addValue(out_.module.types.ptrType(), ValueOrigin::Instruction,
                                           entryBlock_, allocaAt_, label);
        a.result = slot;
        entry->insts.insert(entry->insts.begin() + static_cast<long>(allocaAt_), std::move(a));
        ++allocaAt_;
        // The insertion moved everything after it, so the entry block's value table has to move too
        // -- rule 1 checks exactly that agreement.
        for (size_t i = 0; i < entry->insts.size(); ++i) {
            const ValueId r = entry->insts[i].result;
            if (r != kNoValue && r < fn_->values.size()) {
                fn_->values[r].indexInBlock = static_cast<uint32_t>(i);
            }
        }
        return slot;
    }

    // The bits this name owns, in the width its declaration gives them.
    // THE TWO MAPS THAT DESCRIBE A FIELD ADDRESS rather than a value -- what a plain load or store
    // at that address would get wrong. They are per-BODY, and they are cleared together because
    // forgetting one of them is not a small mistake: value numbers restart at each function, so a
    // stale entry does not go unused, it lands on a completely unrelated address.
    //
    // `narrowAt_` was added without adding it to the seven places `packedAt_` was already cleared,
    // and `Main.main` opened by loading the arena GLOBAL as a 32-bit offset and widening it -- the
    // address of `this.left`, in a method lowered earlier, had been given the same value number.
    // One method to clear both is the fix; two lines that must always be written together are a
    // rule the compiler cannot check, and this file has three thousand functions to forget it in.
    void clearFieldShapes() {
        packedAt_.clear();
        narrowAt_.clear();
    }

    ValueId bitFieldLoad(ValueId unitAddr, const BitField& bits, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* unitTy = tt.intType(bits.unitBits);
        Inst ld;
        ld.op = Op::Load;
        ld.type = unitTy;
        ld.operands.push_back(unitAddr);
        ld.loc = loc;
        const ValueId unit = emit(std::move(ld));

        auto shift = [&](Op op, ValueId v, uint32_t by) {
            if (by == 0) {
                return v;
            }
            Inst s;
            s.op = op;
            s.type = unitTy;
            s.operands.push_back(v);
            s.operands.push_back(constInt(by, bits.unitBits, loc));
            s.loc = loc;
            return emit(std::move(s));
        };
        const ValueId high = shift(Op::ShlWrap, unit, bits.unitBits - bits.offset - bits.width);
        const ValueId low =
            shift(bits.isUnsigned ? Op::ShrL : Op::ShrA, high, bits.unitBits - bits.width);
        // BACK TO THE DECLARED WIDTH. The unit is as wide as the run needs; `int state : 3` is an
        // `int` everywhere else in the program and has to arrive as one.
        const std::string declared = classNameOf(declaredName(unitAddr));
        const Type* asWritten = declared.empty() ? tt.intType(32) : baseTypeOf(declared);
        if (asWritten == nullptr || asWritten->kind != TypeKind::Int) {
            asWritten = tt.intType(32);
        }
        return asWritten == unitTy ? low : lowerConversion(low, unitTy, asWritten, loc);
    }

    // The same unit with this field's bits replaced and every other field's left alone.
    // Read-modify-write, and deliberately ONE access of the unit's natural size in each direction.
    void bitFieldStore(ValueId unitAddr, const BitField& bits, ValueId value, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* unitTy = tt.intType(bits.unitBits);
        Inst ld;
        ld.op = Op::Load;
        ld.type = unitTy;
        ld.operands.push_back(unitAddr);
        ld.loc = loc;
        const ValueId unit = emit(std::move(ld));

        const uint64_t low = bits.width >= 64 ? ~0ULL : ((1ULL << bits.width) - 1ULL);
        const uint64_t mask = low << bits.offset;
        auto binary = [&](Op op, ValueId a, ValueId b) {
            Inst i;
            i.op = op;
            i.type = unitTy;
            i.operands.push_back(a);
            i.operands.push_back(b);
            i.loc = loc;
            return emit(std::move(i));
        };
        const ValueId cleared =
            binary(Op::And, unit, constInt(static_cast<int64_t>(~mask), bits.unitBits, loc));
        const Type* given = fn_->value(value)->type;
        const ValueId asUnit =
            given != nullptr && given != unitTy ? lowerConversion(value, given, unitTy, loc) : value;
        const ValueId kept =
            binary(Op::And, asUnit, constInt(static_cast<int64_t>(low), bits.unitBits, loc));
        const ValueId placed =
            bits.offset == 0 ? kept
                             : binary(Op::ShlWrap, kept, constInt(bits.offset, bits.unitBits, loc));
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(binary(Op::Or, cleared, placed));
        put.operands.push_back(unitAddr);
        put.loc = loc;
        emit(std::move(put));
    }

    ValueId loadFrom(ValueId slot, SourceLocation loc) {
        // A VALUE STRUCT'S SLOT IS THE OBJECT. `Box a` allocates the struct inline, so reading the
        // name yields the ADDRESS of those bytes -- which is what every other part of this lowering
        // means by "an object" -- and not a register holding a copy of them. Loading it produced a
        // struct VALUE that the field access then used as a pointer: `a.v` became `load i64, ptr
        // poison`, and the program segfaulted before printing anything. Where a copy is genuinely
        // wanted -- binding one struct to a second name -- `copyValueStruct` makes it explicit.
        if (auto held = slotType_.find(slot); held != slotType_.end() && held->second != nullptr) {
            const Type* what = held->second;
            if (what->kind == TypeKind::Struct && what->nominal && what->facts.isValue) {
                pointee_[slot] = what;
                return slot;
            }
            // AN INLINE ARRAY IS ITS STORAGE TOO. `int[16] key` allocates sixteen words in the
            // frame; `key` names those words, and loading them into a register produced an
            // `[16 x i32]` value that every index then used as a pointer -- `load i64, ptr undef`.
            // The extent being in the type is the whole difference between `int[16]` and `int[]`,
            // and it is the reason there is no header here to read a length out of.
            if (what->kind == TypeKind::Array && what->storage == ArrayStorage::Inline) {
                return slot;
            }
        }
        // A BIT FIELD IS READ OUT OF ITS UNIT, not loaded whole. One access of the unit's natural
        // width, then left-justify and shift back down -- the same shape for both signednesses,
        // and the arithmetic shift is what makes a signed four-bit field holding 0b1111 read as -1
        // rather than 15. The declared width is part of the type, so the value has to come back the
        // way that type would hold it.
        if (auto bits = packedAt_.find(slot); bits != packedAt_.end()) {
            return bitFieldLoad(slot, bits->second, loc);
        }
        // ...AND A NARROW POINTER IS WIDENED HERE, at the one place every read of a field goes
        // through, rather than at every use of one.
        if (auto narrow = narrowAt_.find(slot); narrow != narrowAt_.end()) {
            return narrowLoad(slot, narrow->second, loc);
        }
        Inst ld;
        ld.op = Op::Load;
        ld.type = slotType_.count(slot) != 0 ? slotType_[slot] : out_.module.types.intType(32);
        ld.operands.push_back(slot);
        ld.loc = loc;
        const ValueId got = emit(std::move(ld));
        // WHAT IT POINTS AT, carried across the load. `this` reaches here two ways -- through
        // `selfLoad` and as an ordinary identifier -- and only one of them was recording the class,
        // so `this.data` resolved its field and `data` (implicit this) did not. Recording it HERE,
        // where every load goes through, is the one place it cannot be forgotten.
        if (slot == selfSlot_ && selfClass_ != nullptr) {
            pointee_[got] = selfClass_;
        } else if (auto it = pointeeOfSlot_.find(slot); it != pointeeOfSlot_.end()) {
            pointee_[got] = it->second;
        }
        // ...and the DECLARED type with it, for the same reason and in the same place. Reading a
        // `uint` local must produce a value that still knows it, or the `%` two lines later picks
        // `rem.s`; reading a `String` local must too, or the `.length()` beside it binds to
        // whichever class in the module declares that name first.
        noteName(got, declaredName(slot), pointerDepthOf(slot));
        // §37.5: ...AND THAT WHAT IT HOLDS POINTS AT HARDWARE. `volatile int* px` puts the fact on
        // the POINTER, so it is handed over here -- where the pointer comes out of its slot -- and
        // travels from there through every `gep` the accesses are built from.
        if (volatilePointerSlots_.count(slot) != 0) {
            volatilePointee_.insert(got);
        }
        // ...and where what it holds was allocated, for the same reason and by the same route: a
        // `delete` reads its target out of a slot, so the fact has to survive the load. `Unknown`
        // is not recorded -- it is what the absence of an entry already means.
        if (const Storage under = storageOf(slot); under != Storage::Unknown) {
            noteStorage(got, under);
        }
        return got;
    }

    void gap(std::string construct, SourceLocation loc) {
        out_.gaps.push_back(
            Gap{std::move(construct), fn_ != nullptr ? "@" + fn_->key : std::string(), loc});
    }

    // THE PROGRAM IS WRONG, which is a different report from `gap` above -- see `Lowering::errors`.
    // Lowering continues afterwards: the driver stops on a non-empty list, and reaching the end
    // means one compile reports every such fault rather than the first one, which is what the front
    // end already does and what the diagnostics chapter promises.
    void refuse(std::string message, SourceLocation loc) {
        out_.errors.push_back(CodegenError{std::move(message), loc});
    }

    // ONE PLACE THAT ANSWERS "does this machine have that", so a program built for an old or a small
    // target is told what it cannot have, at the line that asked, instead of finding out at link
    // time from a symbol nobody wrote -- or, worse, at run time from a module that traps.
    //
    // The port's whole premise is that a target may be missing something (see
    // docs/design/porting-architectures.md): a 1990s machine has no SSE, a bare wasm module has no
    // threads. Refusing with a sentence is the agreed answer, not a silent lowering to nothing.
    bool requireTargetFeature(std::string_view feature, const std::string& what, SourceLocation loc) {
        const std::string& triple = out_.module.triple;
        const std::string arch = cgutil::archFamily(cgutil::archOfTriple(triple));
        if (feature == "interrupt" && arch != "x86_64" && arch != "x86") {
            // AN INTERRUPT HANDLER IS AN X86 CALLING CONVENTION. `interrupt` lowers to `x86_intrcc`,
            // which LLVM implements for x86 and x86-64 and nowhere else -- the CPU pushes a specific
            // frame and the handler returns with `iret`, and no other architecture does either.
            //
            // Left ungated, the IR was emitted happily and clang's BACKEND died on it:
            //
            //     fatal error: error in backend: unsupported calling convention
            //     PLEASE submit a bug report to https://github.com/llvm/llvm-project/issues/
            //
            // No source line, no method name, and an invitation to file a bug against LLVM for
            // something this compiler chose. That is the exact shape of failure the port's feature
            // gates exist to replace: AArch64 and RISC-V have interrupt handling, but it is a
            // different mechanism with a different frame, so this is not a lowering we are missing
            // -- it is one that does not exist.
            refuse("`interrupt` is an x86 calling convention and this target is " + triple +
                       ". A handler declared this way expects the frame an x86 CPU pushes and "
                       "returns with `iret`; " + what +
                       " cannot be built for another architecture, which handles interrupts by a "
                       "different mechanism entirely. Build for x86, or write the handler for this "
                       "machine as a `naked` method with its own entry sequence",
                   loc);
            return false;
        }
        if (feature == "threads" && arch == "wasm") {
            // wasm32-unknown-unknown is a SINGLE-THREADED machine. Threads there need the atomics
            // and bulk-memory proposals AND a host that hands the module a shared memory and spawns
            // the workers -- none of which the bare target has. Without this the calls to
            // `__polaron_thread_spawn` are emitted and the module simply has no such import.
            refuse("threads are not available on " + triple +
                       ": a bare WebAssembly module runs on one thread, and spawning needs the "
                       "atomics and bulk-memory proposals plus a host that provides the shared "
                       "memory and the workers. " + what +
                       " has no meaning on this target -- build for a threaded target, or "
                       "restructure the work to run on the one thread wasm gives you",
                   loc);
            return false;
        }
        return true;
    }

    // ---- statements ----

    void lowerStmt(const ast::Stmt* s) {
        if (s == nullptr) {
            return;
        }
        // WHERE THE PROGRAM IS, for a guard that has to name the line it fired on. A bounds check
        // belongs to the STATEMENT, not to the bracket inside it: the other backend prints
        // `bounds_report.pol:25:17` -- the `return` -- and reading the index expression's own
        // location gave `25:34`, the `[`. Same file, same line, same method, different column, and
        // the differential compares the text.
        if (s->loc.line > 0) {
            stmtLoc_ = s->loc;
        }
        // ...AND THE STRINGS THE PREVIOUS STATEMENT BUILT ARE RELEASED BEFORE THIS ONE RUNS. At the
        // TOP rather than the bottom, because a statement can leave through a `return`, a `break`
        // or a throw, and the bottom is the one exit that is not always taken. Here, whatever the
        // last statement did, it is over.
        releaseStringTemps(stmtLoc_);
        // A LABEL IS WHERE FLOW STARTS AGAIN, so it is the one statement that survives a closed
        // block. Dropping everything after a `return` is right for ordinary statements -- they are
        // unreachable -- and wrong for a label: `return; label negative; println("negative");` left
        // the label's block empty, and the `goto` that jumped to it landed on `unreachable`.
        // ...AND SO IS A `comefrom`, which is ordinarily written after a `return` -- that is the
        // whole shape of the forward steal. Dropped as unreachable, its block never got a body and
        // the module failed rule 2 with no terminator.
        // A `demand` IS SETTLED HERE, AND IT EMITS NOTHING (§28.2).
        //
        // The analyzer folds every condition it can and defers exactly the ones mentioning `sizeof`,
        // because a size is only knowable against the TARGET's layout and this is the one stage that
        // has it. One authority on layout instead of two models that can disagree; the cost is that
        // a blown byte budget shows up at build time rather than in the editor's live check, and
        // that trade is written down in the test that guards it.
        //
        // Before the `blockClosed()` return below, deliberately: a demand is not code, so whether
        // control can REACH it has nothing to do with whether it holds. `sizeof_budget_bad.pol`
        // makes the same point one level up -- the demand sits in a method nothing calls, and says
        // so: "an assertion that cannot fire is worse than no assertion, because it reads as
        // protection."
        if (const auto* dm = dynamic_cast<const ast::DemandStmt*>(s)) {
            if (comptime::mentionsSizeof(*dm->condition)) {
                comptime::Context ctx = comptimeContext();
                long long v = 0;
                if (!comptime::evalInt(*dm->condition, v, ctx)) {
                    refuse("a demand is settled while the program is built, so its condition has to "
                           "be known then -- this one is not constant",
                           dm->loc);
                } else if (v == 0) {
                    refuse("demand not met: " + dm->message, dm->loc);
                }
            }
            return;
        }
        const bool startsFlow = dynamic_cast<const ast::LabelMarkStmt*>(s) != nullptr ||
                                dynamic_cast<const ast::LabeledStmt*>(s) != nullptr ||
                                dynamic_cast<const ast::ComefromStmt*>(s) != nullptr;
        if (blockClosed() && !startsFlow) {
            return;
        }
        if (auto* r = dynamic_cast<const ast::ReturnStmt*>(s)) {
            // INSIDE AN `expecting { ... }` BLOCK A `return` DOES NOT RETURN (§30.18). The block is
            // an expression the compiler runs where it stands, and its `return` names the
            // validation value: leaving the method there would abandon the `unimport` the block
            // exists to precede. The value goes into the slot and control joins the continuation.
            if (expectingSlot_ != kNoValue) {
                if (r->value != nullptr) {
                    if (const ValueId v = lowerExpr(r->value.get()); v != kNoValue) {
                        Inst st;
                        st.op = Op::Store;
                        st.operands.push_back(asWord(v, r->loc));
                        st.operands.push_back(expectingSlot_);
                        st.loc = r->loc;
                        emit(std::move(st));
                    }
                }
                Inst go;
                go.op = Op::Br;
                go.edges.push_back(Edge{expectingEnd_, {}});
                go.loc = r->loc;
                emit(std::move(go));
                return;
            }
            // INSIDE AN ASYNC BODY A `return` COMPLETES THE TASK (§20.2) and then returns nothing:
            // the resume function answers to the scheduler, not to whoever called the async
            // method -- that call came back long ago holding a Task.
            if (asyncTask_ != kNoValue) {
                const ValueId v = r->value != nullptr ? lowerExpr(r->value.get()) : kNoValue;
                runDeferred(r->loc, 0);
                destroyScoped(0, r->loc);
                completeTask(v, r->loc);
                Inst out;
                out.op = Op::Ret;
                out.loc = r->loc;
                emit(std::move(out));
                return;
            }
            Inst in;
            in.op = Op::Ret;
            in.loc = r->loc;
            if (r->value != nullptr) {
                // `return new T(...)` ESCAPES THE FRAME, so it cannot be a frame slot. The default
                // placement is the stack -- which is right for a local and dangling for a result:
                // `procedure into<Fahrenheit>` returned the address of its own frame, and the
                // caller read whatever the next call left there. Only the DIRECT form is promoted
                // here; a local that is returned by name needs escape analysis, which is a
                // different question and is not answered by pretending this one covers it.
                const bool wasReturning = returningNew_;
                returningNew_ = dynamic_cast<const ast::NewExpr*>(r->value.get()) != nullptr;
                ValueId v = lowerExpr(r->value.get());
                returningNew_ = wasReturning;
                // §21: RETURNING A STRING COPIES IT. The scope end runs a moment from here and
                // releases every String local, so returning one by name without a copy hands the
                // caller a buffer that is freed before it can be read. `ownedString` CLAIMS a fresh
                // one instead of copying, so the common `return a + b` costs nothing extra.
                if (v != kNoValue && fn_ != nullptr) {
                    bool handsBackAString = false;
                    if (const auto declared = returnName_.find(fn_->key);
                        declared != returnName_.end() && declared->second.pointerDepth == 0 &&
                        isStringNamed(declared->second.name)) {
                        handsBackAString = true;
                    }
                    // ...AND WHEN THE VALUE IS ONE, whatever the signature calls it. A method that
                    // `returns Object` and hands back a String hands back a buffer all the same,
                    // and the release below would free it out from under the caller.
                    if (!handsBackAString && pointerDepthOf(v) == 0 &&
                        isStringNamed(classNameOf(declaredName(v)))) {
                        handsBackAString = true;
                    }
                    if (handsBackAString) {
                        v = ownedString(v, r->loc);
                    }
                }
                // AND THE REST OF THE STATEMENT'S STRINGS GO BACK HERE.
                //
                // Temporaries are released at the TOP of the next statement, which is the one place
                // that always runs -- except in a method whose last statement is the `return`, and
                // that is most of them. `Main.chained` is `return "".concat("a")...` twenty-four
                // times: one statement, twenty-four fresh Strings, twenty-three of them abandoned.
                // The other path emitted 23 releases there and this one emitted none, and the
                // sample exited holding 1600 bytes in 59 blocks against 176 in 7.
                //
                // AFTER the claim above and BEFORE the scope teardown: the returned value has
                // already been taken off the temporary list, so what is left is exactly what
                // nothing names -- and `here_` is still the block the temporaries were born in,
                // which is what `releaseStringTemps` matches on.
                releaseStringTemps(r->loc);
                // A VALUE STRUCT IS RETURNED BY VALUE. Everywhere inside a method an object is a
                // pointer to its storage, including a `struct`; at the boundary the signature says
                // otherwise, and handing the pointer over produced `ret %Box undef` -- the callee
                // returned nothing and the caller read poison.
                if (v != kNoValue) {
                    // A METHOD DECLARED `returns <catalog>` HANDS BACK A TAGGED ORDINAL. It was
                    // handing back the enum's own value -- for a java-style implementer, its
                    // singleton POINTER -- so the module verifier refused the function outright and
                    // any method whose result is "one of a closed set of outcomes" failed to build.
                    if (auto declared = returnName_.find(fn_ != nullptr ? fn_->key : std::string());
                        declared != returnName_.end() && catalogs_.count(declared->second.name) != 0) {
                        if (const std::string from = classNameOf(declaredName(v));
                            enums_.count(from) != 0) {
                            v = tagForCatalog(v, from, r->loc);
                            noteName(v, declared->second.name, declared->second.pointerDepth);
                        }
                    }
                    const Type* want =
                        fn_ != nullptr && fn_->signature != nullptr ? fn_->signature->element
                                                                    : nullptr;
                    const Type* got = fn_->value(v)->type;
                    // POINTER-LIKE, not `Ptr` exactly. An element's address carries the ARRAY's
                    // type -- `elementAddress` stamps the gep with it, so the backend knows the
                    // stride -- and that type is a `Slice`. Testing for `Ptr` alone made
                    // `return this.data[i]` from a `returns T` monomorphised to a value struct fall
                    // through to the conversion below, which has nothing to convert a slice into a
                    // struct with: `ArrayList<Point>.get` came out as `ret %class.Point undef` and
                    // every element read back as zeros. The gep was right; only the load was missing.
                    if (want != nullptr && want->kind == TypeKind::Struct && want->facts.isValue &&
                        got != nullptr && got->isPointerLike()) {
                        Inst ld;
                        ld.op = Op::Load;
                        ld.type = want;
                        ld.operands.push_back(v);
                        ld.loc = r->loc;
                        v = emit(std::move(ld));
                    } else if (want != nullptr && got != nullptr && want != got) {
                        // ...AND EVERY OTHER RETURN IS CONVERTED TOO. A method declared `returns
                        // float` whose body yields a `double` -- a `match` over literals, say --
                        // handed the backend a value of the wrong width, and a `ret` whose operand
                        // does not match the signature becomes `ret float undef`. The conversion is
                        // an instruction the passes can see rather than a mismatch nobody records.
                        v = lowerConversion(v, got, want, r->loc);
                    }
                    in.operands.push_back(v);
                }
            }
            // `result` IS THIS VALUE, for as long as the postconditions are being emitted. The
            // returned value has already been computed and converted, so binding it costs nothing;
            // cleared straight after, because a sibling `return` binds its own.
            resultValue_ = in.operands.empty() ? kNoValue : in.operands[0];
            emitExitChecks(r->loc);   // `ensures` and the class invariant, §29: this is an exit
            resultValue_ = kNoValue;
            // EVERY `defer` RUNS BEFORE THE RETURN, innermost first -- that is the guarantee the
            // keyword makes, and it was making none: the body was recorded as a gap and simply
            // never emitted. The value has already been computed, so the cleanup cannot change it.
            runDeferred(r->loc);
            destroyScoped(0, r->loc);   // every open scope ends here too
            emit(std::move(in));
            return;
        }
        // `defer { ... }` IS NOT RUN WHERE IT IS WRITTEN. It is remembered, and emitted at every
        // exit from the scope -- which is why it is a statement that produces no code at its own
        // position and why lowering it as one produced nothing at all.
        // `cascade println(x)` and `cascade validate(x)` (§37.1): the same owned-graph walk a
        // `cascade delete` performs, with a different thing done at each node. Not lowered at all,
        // the statements vanished -- `cascade_ops` printed `done` and neither of the two lines the
        // walk exists to produce. `cascade unimport` is decided before any code is emitted (see
        // `scanUnimport`) and needs nothing here.
        if (auto* cs = dynamic_cast<const ast::CascadeStmt*>(s)) {
            if (cs->op == ast::CascadeOpKind::Println ||
                cs->op == ast::CascadeOpKind::Validate) {
                const ValueId root = lowerExpr(cs->target.get());
                if (root == kNoValue) {
                    return;
                }
                const std::string cls = classNameOf(declaredName(root));
                if (cls.empty() || findClass(cls) == nullptr) {
                    gap("CascadeStmt(unknown class: " + cls + ")", s->loc);
                    return;
                }
                lowerCascadeDelete(root, cls, cs->params, s->loc,
                                   cs->op == ast::CascadeOpKind::Println ? CascadeAction::Println
                                                                         : CascadeAction::Validate);
                return;
            }
            if (cs->op == ast::CascadeOpKind::Clone) {
                lowerCascadeClone(*cs);
                return;
            }
            // `cascade unimport X` TAKES THE FAMILY, not the one class (§37). A subclass's code is
            // reached through the base's dispatch table, so leaving `Dog` alive while `Animal` goes
            // is a table full of traps with a live class still pointing into it.
            //
            // This fell through to `return` and did nothing at all: the statement compiled, the
            // classes stayed, and `new Dog()` afterwards succeeded where the language says it
            // throws. `cascade_unimport` printed `woof` and then stopped, one line short.
            //
            // The set is `cascadeUnimportTargets`, which is the same one the collecting pass uses to
            // decide which classes need an alive flag in the first place -- so what is guarded and
            // what is unimported cannot drift apart.
            if (cs->op == ast::CascadeOpKind::Unimport) {
                for (const std::string& t : cascadeUnimportTargets(cs->typeName)) {
                    unimportClass(t, s->loc);
                }
                return;
            }
            return;
        }
        // `asm("x86_64") { ... }` -- THE RAW BODY, as a side-effecting inline asm that also clobbers
        // memory, so nothing reorders or elides it.
        //
        // Not lowered at all, an `asm` block simply VANISHED: pico's `_start` -- a hundred and sixty
        // lines carrying the PVH note, the multiboot2 header, the page tables and the whole
        // long-mode bring-up -- came out as a bare `ret`, and QEMU refused the image because the
        // note it looks for was not in it. Nothing in 844 samples noticed, because a sample that
        // uses `asm` uses it for something whose absence prints the same as its presence.
        //
        // The operands are the inputs, then the ADDRESSES the outputs are written back to; `imm`
        // says where the one list ends and the other begins. The constraint string is built here
        // rather than in the backend because it is the language's spelling of the operand list --
        // `out (lv)` is `=r`, `in (e)` is `r`, `clobber ("rax")` is `~{rax}` -- and the backend's
        // business is the InlineAsm object, not what a Polaron `asm` block means.
        if (auto* as = dynamic_cast<const ast::AsmStmt*>(s)) {
            // `as->arch` NAMES THE ARCHITECTURE THE BLOCK IS WRITTEN FOR, checked against the one
            // being built for.
            //
            // It used to be an unchecked "intent tag", which meant an x86 block compiled for ARM
            // travelled all the way to clang's assembler and failed there:
            //     <inline asm>:1:3: error: too few operands for instruction
            //             hlt
            // -- a message about a line of assembly, in a file called `<inline asm>`, with no path
            // back to the Polaron source that wrote it or the target that made it wrong. A
            // whole-program port consists mostly of finding these, so the compiler says it itself,
            // at the right place.
            if (!as->arch.empty() && as->arch != "arch") {   // "arch" is the docs' placeholder
                const std::string have = cgutil::archOfTriple(out_.module.triple);
                const std::string wantFamily = cgutil::archFamily(as->arch);
                const std::string haveFamily = cgutil::archFamily(have);
                if (!wantFamily.empty() && !haveFamily.empty() && wantFamily != haveFamily) {
                    refuse("this `asm` block is written for " + as->arch + ", and the target is " +
                               have +
                               ". Assembly cannot be ported by the compiler, and there is as yet no "
                               "way to carry one block per architecture in a program -- so this "
                               "block has to be written for " + have + ", or the program built for " +
                               as->arch,
                           as->loc);
                }
            }
            std::string cons;
            std::vector<ValueId> operands;
            std::vector<const Type*> outTypes;
            for (const auto& o : as->outputs) {
                outTypes.push_back(shapeOfLValue(o.get()));
                cons += cons.empty() ? "=r" : ",=r";
            }
            for (const auto& i : as->inputs) {
                const ValueId v = lowerExpr(i.get());
                if (v == kNoValue) {
                    gap("AsmStmt(an input did not lower)", s->loc);
                    return;
                }
                operands.push_back(v);
                cons += cons.empty() ? "r" : ",r";
            }
            const int64_t inputCount = static_cast<int64_t>(operands.size());
            for (const auto& o : as->outputs) {
                operands.push_back(addressOf(o.get()));
            }
            for (const std::string& c : as->clobbers) {
                cons += (cons.empty() ? "" : ",") + ("~{" + c + "}");
            }
            // MEMORY IS ALWAYS CLOBBERED. A block that writes a control register or a port has
            // effects nothing here can describe, and the one honest thing to tell the optimiser is
            // that it may not move loads and stores across it.
            cons += cons.empty() ? "~{memory}" : ",~{memory}";

            Inst in;
            in.op = Op::Asm;
            in.text = as->body;
            in.imm = inputCount;
            in.operands = std::move(operands);
            in.extra.push_back(cons);
            in.extra.push_back(as->dialect);
            in.type = outTypes.empty() ? out_.module.types.voidType()
                      : outTypes.size() == 1
                          ? outTypes[0]
                          : out_.module.types.structType("asm.out",
                                                         [&] {
                                                             std::vector<Field> parts;
                                                             for (const Type* t : outTypes) {
                                                                 parts.push_back(Field{t, ""});
                                                             }
                                                             return parts;
                                                         }(),
                                                         /*nominal=*/false);
            in.loc = s->loc;
            emit(std::move(in));
            return;
        }
        if (auto* df = dynamic_cast<const ast::DeferStmt*>(s)) {
            DeferSite site;
            site.body = &df->body;
            // THE BUDGET IS READ HERE, where the `defer` is written -- the duration is an ordinary
            // expression and the values it names may be gone by the time the cleanup runs.
            if (df->within != nullptr) {
                if (const ValueId d = lowerExpr(df->within.get()); d != kNoValue) {
                    const std::string dt = classNameOf(declaredName(d));
                    if (dt == "Duration") {   // a Duration: ask it for its milliseconds
                        if (const Function* toMs = resolveKey("Duration.toMillis")) {
                            site.budgetMs = emitCall(toMs, {d}, df->loc);
                        }
                    } else if (const Type* t = fn_->value(d)->type;
                               t != nullptr && t->kind == TypeKind::Int) {
                        site.budgetMs = t->bits == 64
                                            ? d
                                            : lowerConversion(d, t, out_.module.types.intType(64),
                                                              df->loc);
                    }
                }
            }
            // A FLAG ONLY WHERE ONE IS NEEDED: inside a `try`, where the block can be left twice.
            // Everywhere else a `defer` has exactly one exit and the flag would be dead weight.
            if (!handlers_.empty()) {
                site.ran = allocaFor(fresh("defer.ran"), out_.module.types.intType(32));
                zeroSlotAtEntry(site.ran, df->loc);
                unwindDefers_.push_back(site);
            }
            deferred_.push_back(site);
            return;
        }
        if (auto* e = dynamic_cast<const ast::ExprStmt*>(s)) {
            lowerExpr(e->expr.get());
            return;
        }
        if (auto* v = dynamic_cast<const ast::VarDeclStmt*>(s)) {
            // §28.3: A `comptime` LOCAL IS COMPUTED DURING COMPILATION AND EMBEDDED.
            //
            // The prefix was parsed, carried on the declaration, and read by nobody here, so
            // `comptime int x = Main.fib(10)` emitted a real `call @Main.fib(i32 10)`. It printed
            // the right answer, which is exactly why nothing caught it: a local that recomputes the
            // same value at run time is invisible to a test that compares OUTPUT. Only the IR shows
            // it, and only the other backend's IR was being looked at.
            //
            // The evaluator is `semantic/comptime` -- the same one the namespace consts use and the
            // same one the other backend calls. Nothing about it is a backend's business.
            if (v->isComptime && v->init != nullptr && !v->isVar) {
                const std::string dt = resolvedTypeName(v->type);
                comptime::Context ctx = comptimeContext();
                const Type* want = typeOf(v->type);
                ValueId folded = kNoValue;
                if (dt == "float" || dt == "double") {
                    double d = 0;
                    if (comptime::evalDouble(*v->init, d, ctx) && want != nullptr &&
                        want->kind == TypeKind::Float) {
                        Inst lit;
                        lit.op = Op::ConstFloat;
                        lit.type = want;
                        lit.fimm = d;
                        lit.loc = v->loc;
                        folded = emit(std::move(lit));
                    }
                } else {
                    long long n = 0;
                    if (comptime::evalInt(*v->init, n, ctx) && want != nullptr &&
                        want->kind == TypeKind::Int) {
                        folded = constInt(n, want->bits, v->loc);
                    }
                }
                if (folded != kNoValue) {
                    const ValueId slot = allocaFor(v->name, want);
                    slotType_[slot] = want;
                    locals_[v->name] = slot;
                    declaredAs_[slot] = declaredTypeOf(dt, pointerDepthOfType(v->type));
                    Inst put;
                    put.op = Op::Store;
                    put.operands.push_back(folded);
                    put.operands.push_back(slot);
                    put.loc = v->loc;
                    emit(std::move(put));
                    return;
                }
                // ...and a `comptime` the evaluator cannot settle falls through to the ordinary
                // lowering rather than failing: the analyzer is what reports one that must be
                // constant and is not, and reporting it twice in two voices helps nobody.
            }
            // A `persistent` LOCAL DOES NOT LIVE IN THE FRAME (§18). Its storage is a global keyed
            // by the method and the name, seeded once with the initialiser -- and the initialiser
            // is NEVER RE-RUN on entry. That omission is the whole feature: the variable reattaches
            // to what it held rather than starting again, which is why three calls to a counter
            // holding `persistent mutable int n = 0` answer 1, 2, 3 and not 1, 1, 1.
            // `eternal` is `persistent` that never has to be released, which is a difference in
            // what the program owes and not in where the storage is.
            // `eternal` IS NOT THAT WORD. It says the value's lifetime is the PROGRAM'S -- so the
            // scope end does not destroy it -- and says nothing about where it lives or about
            // reattaching to what a previous call left. The trusted path reads it in exactly one
            // kind of place, deciding whether a scope exit tears something down; the storage is
            // ordinary, and the initialiser runs every time control reaches the declaration.
            //
            // Sent down the `persistent` path it got the one thing that path exists NOT to do: the
            // initialiser was seeded once and never re-run. `eternal Desktop shell = new
            // Desktop(...)` therefore never constructed a desktop at all -- the first line of the
            // constructor never printed -- and the first method called on it read an object made
            // of zeros, which the class's own `invariant this.nextWindowId > 0` caught.
            if (v->isPersistent) {
                lowerPersistentLocal(*v);
                return;
            }
            // A `lazy` LOCAL RUNS ITS INITIALISER ON THE FIRST READ, not here (§37.3). The storage
            // and a "done" flag are made now; the expression is kept and emitted at the first use.
            // Run eagerly it printed `constructing 1 / constructing 2` before the line that says
            // `after decl` -- which is the one thing the word promises will not happen, and the
            // whole reason to write it.
            if (v->isLazy && v->init != nullptr &&
                ast::mangleGeneric(v->type.name, v->type.typeArgs) != "region") {
                lowerLazyLocal(*v);
                return;
            }
            // ...AND SO IS THE NAME AN OBJECT WITH PERSISTENT FIELDS IS ABOUT TO BE BOUND TO
            // (§18.2). The identity a persistent block reattaches to is the VARIABLE, and `new Car()`
            // has no idea what it is being assigned to -- so the name is handed down the same way
            // the region shape is, and cleared by whoever uses it.
            if (const auto* nw = dynamic_cast<const ast::NewExpr*>(v->init.get())) {
                if (persistBlock_.count(
                        resolveClassKey(ast::mangleGeneric(nw->className, nw->typeArgs))) != 0) {
                    pendingPersistKey_ = (fn_ != nullptr ? fn_->key : std::string()) + "." + v->name;
                }
            }
            // A REGION'S FLAVOUR IS ON ITS DECLARATION and is needed while its INITIALISER is
            // lowered -- `itself.allocate(...)` is what takes the block, and how big a header that
            // block needs depends on the flavour. The name does not exist yet, so the shape is
            // handed over rather than looked up.
            pendingRegion_ = RegionShape{v->regionFlavor, v->regionGrowable};
            // ...AND SO IS ITS PARENT, for the same reason: `itself.allocate(n) in region outer`
            // takes its block from `outer`, and the initialiser is where that happens.
            if (const auto* ri = dynamic_cast<const ast::RegionInitExpr*>(v->init.get())) {
                pendingRegion_.parent = ri->inRegion;
                // A MULTI-RANGE REGION IS RECORDED BEFORE ITS INITIALISER RUNS, because there is
                // nothing for the initialiser to do: §17.4's region has no block, only ranges and
                // one cursor each, and `new T in region r` routes among them at compile time.
                if (!ri->ranges.empty() &&
                    ast::mangleGeneric(v->type.name, v->type.typeArgs) == "region") {
                    declareMultiRange(v->name, ri->ranges, v->loc);
                }
            }
            ValueId init = v->init != nullptr ? lowerExpr(v->init.get()) : kNoValue;
            if (ast::mangleGeneric(v->type.name, v->type.typeArgs) == "region") {
                regionShape_[v->name] = pendingRegion_;
                // A RING RECORDS ITS ELEMENT TYPE'S DESTRUCTOR, once, here. Every entry in a ring
                // is the one type its `.accepts({T})` names -- that is what makes a single
                // destructor enough -- and both the moments a ring destroys something are the
                // runtime's: the eviction of the oldest entry when a new one overwrites it, and
                // the teardown at release. Without it `region_ring` evicted seven objects and ran
                // no destructor at all, so the count it prints was zero.
                if (v->regionFlavor == "ring" && init != kNoValue) {
                    TypeTable& types = out_.module.types;
                    ValueId dtor = nullPointer(v->loc);
                    if (const auto* ri = dynamic_cast<const ast::RegionInitExpr*>(v->init.get());
                        ri != nullptr && !ri->accepts.empty()) {
                        if (const ast::ClassDecl* elem = findClass(classNameOf(ri->accepts[0]));
                            elem != nullptr) {
                            if (const std::string key = destructorOf(*elem); !key.empty()) {
                                Inst which;
                                which.op = Op::ConstFn;
                                which.type = types.ptrType();
                                which.text = key;
                                which.loc = v->loc;
                                dtor = emit(std::move(which));
                            }
                        }
                    }
                    callExternal("__polaron_ring_set_dtor", types.voidType(),
                                 {types.ptrType(), types.ptrType()}, {init, dtor}, v->loc);
                }
            }
            pendingRegion_ = RegionShape{};
            // `Tier t = AppLevel.a;` TAGS ON THE WAY IN, and it has to happen HERE, before the
            // width conversion below: a catalog value is 64 bits and an ordinal is 32, so the
            // conversion produces a NEW value that no longer remembers which enum it came from.
            // Tagged afterwards, both `AppLevel.a` and `SysLevel.x` stored a bare zero and every
            // dispatch went to the first implementer.
            if (init != kNoValue &&
                catalogs_.count(ast::mangleGeneric(v->type.name, v->type.typeArgs)) != 0) {
                if (const std::string from = classNameOf(declaredName(init));
                    enums_.count(from) != 0) {
                    init = tagForCatalog(init, from, v->loc);
                    noteName(init, ast::mangleGeneric(v->type.name, v->type.typeArgs));
                }
            }
            // THE DECLARED TYPE WINS. This took the initialiser's type whenever there was one, so
            // `long a = 1;` allocated thirty-two bits because `1` is an `int` -- and then every
            // later `a + <something 64-bit>` was an add of two different widths, which the backend
            // turns into `undef` rather than a module LLVM would refuse. A checksum came out as
            // `196610`. The declaration is the answer; the initialiser is converted to it, which is
            // what the language says happens anyway.
            //
            // Only for the SCALARS, deliberately. For an object the initialiser is what says where
            // it lives -- `new T()` yields a pointer -- and letting the declared class win there
            // would turn every object local into an inline stack copy of its class.
            const Type* declared = v->type.name.empty() ? nullptr : typeOf(v->type);
            // ...and for a POINTER, which is a scalar too and was not in this list: `int* a =
            // cast<int*>(block);` took the initialiser's type, which was the `address` the cast had
            // failed to convert, so the slot held an integer and every write through it went to a
            // pointer the backend had to invent.
            const bool scalar = declared != nullptr &&
                                (declared->kind == TypeKind::Int || declared->kind == TypeKind::Float ||
                                 declared->kind == TypeKind::Bool || declared->kind == TypeKind::Addr ||
                                 // A `nullable T` local is a pointer even when its initialiser is
                                 // the bare value: `nullable int y = 5;` must have somewhere to put
                                 // "absent", and the initialiser's `int` has nowhere.
                                 (declared->kind == TypeKind::Ptr &&
                                  (v->type.pointerDepth > 0 || v->type.isNullable ||
                                   // A `function<...>` LOCAL IS A POINTER whatever the initialiser
                                   // came out as. `function<int,int> dbl = makeDoubler();` took the
                                   // call's return type, which this pass had guessed as `int`, and
                                   // put a closure address into four bytes.
                                   v->type.name.rfind("function<", 0) == 0 ||
                                   v->type.name.rfind("funcptr<", 0) == 0)));
            const Type* t = scalar ? declared
                                   : (init != kNoValue ? fn_->value(init)->type : typeOf(v->type));
            if (init != kNoValue) {
                // A VALUE GOING INTO A `nullable` SLOT IS BOXED, not converted: `nullable int y =
                // 5;` puts 5 somewhere and keeps the address. Converting instead would turn the
                // number into a pointer with the same bits, and `y == null` would then be asking
                // whether 5 is zero.
                const Type* was = fn_->value(init)->type;
                if (v->type.isNullable && t != nullptr && t->kind == TypeKind::Ptr &&
                    was != nullptr && was->kind != TypeKind::Ptr) {
                    TypeTable& tt = out_.module.types;
                    const ValueId box =
                        callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                     {constInt(8, 64, v->loc)}, v->loc);
                    Inst put;
                    put.op = Op::Store;
                    put.operands.push_back(init);
                    put.operands.push_back(box);
                    put.loc = v->loc;
                    emit(std::move(put));
                    init = box;
                } else {
                    init = lowerConversion(init, was, t, v->loc);
                }
            }
            const ValueId slot = allocaFor(v->name, t);
            // §37.5: `volatile` ON A LOCAL. Two different declarations wear the same word and they
            // mean different things, so both are recorded:
            //
            //   `volatile int flag;`    -- the VARIABLE is volatile: reading `flag` reads memory.
            //   `volatile int* px;`     -- what it POINTS AT is volatile: reading `px` is ordinary,
            //                              and `px[i]` is the access that must survive.
            //
            // The second is the shape a kernel writes, and it is the one that mattered: pico's
            // `Framebuffer.fill` walks `volatile int* px` over half a megabyte nobody reads back,
            // which is precisely what dead-store elimination exists to delete.
            if (v->isVolatile) {
                const bool throughPointer =
                    v->type.pointerDepth > 0 || v->type.isPointer || v->type.isArray;
                if (throughPointer) {
                    volatilePointerSlots_.insert(slot);
                } else {
                    volatilePointee_.insert(slot);
                }
            }
            // The DECLARED type governs even when the initialiser decided the width: the slot is
            // what later loads read, and `uint` -- or `String` -- is the word the programmer wrote.
            //
            // ...EXCEPT WHERE THE PROGRAMMER WROTE `var`, which says the initialiser decides. The
            // declaration then carries an EMPTY type, so recording it erased what the initialiser
            // already knew: `var r = 0..10 step 2;` left `r` nameless, and `r.size()` -- with no
            // class to look the method up in -- resolved by bare name to `Queue$int.size`.
            if (v->isVar && init != kNoValue) {
                noteName(slot, declaredName(init), pointerDepthOf(init));
            } else {
                noteName(slot, v->type);
            }
            // `mutable int[16] key;` IS ZEROED, exactly as `new int[16]()` is -- the declaration IS
            // the storage, and storage that says nothing about its contents is not what the
            // language promises. Nothing was zeroing it, so the sample that exists to state the
            // rule printed whatever the frame held.
            if (v->init == nullptr && t != nullptr && t->kind == TypeKind::Array &&
                t->storage == ArrayStorage::Inline) {
                TypeTable& tt = out_.module.types;
                callExternal("memset", tt.ptrType(), {tt.ptrType(), tt.intType(32), tt.intType(64)},
                             {slot, constInt(0, 32, v->loc),
                              constLong(static_cast<int64_t>(t->facts.size), v->loc)},
                             v->loc);
            }
            if (const Storage under = storageOf(init); under != Storage::Unknown) {
                noteStorage(slot, under);   // the slot holds what the initialiser allocated
            }
            // `Point q = p;` COPIES: a `struct`, `record` or `union` IS its bytes, so binding one to
            // a name makes an independent one. Aliasing it instead made `q.x = 100` write through to
            // `p`, and the sample that exists to prove they are independent printed the same number
            // twice. A class is a reference and is deliberately not copied here.
            //
            // ...AND SO DOES `Point b = a;` OVER A CLASS. This is the rule the language is built
            // on: assignment COPIES, and `T*`/`T&` is how you ask to share instead. Only value
            // classes were being copied here, so `b.x = 99` wrote through to `a` and `value_copy`
            // -- twenty lines, the sample that exists to state the rule -- printed `a=7 b=7` where
            // the two are meant to differ. What must NOT be copied is a fresh `new`, which nobody
            // else holds; the test is whether the initialiser names something that already exists.
            if (init != kNoValue && pointerDepthOf(slot) == 0 &&
                namesExistingObject(v->init.get())) {
                // ...AND SO DOES A MUTABLE `string`, WHICH AN ARRAY DOES NOT.
                //
                // `string b = a; b.append("y")` appends to `b` alone; `int[] b = a; b[0] = 99`
                // writes through to `a`, because an array IS a reference to its heap block and
                // binding one to a name binds the block. The two were copied together here on the
                // reading that both are owned storage -- true, and not the question. Measured on
                // the trusted path: `a0=99 b0=99` for the array, `s=hi t=hi!` for the string. The
                // copy cost `array_equality` its aliasing case, which is the sample that exists to
                // state exactly this. `String` -- the immutable one -- is shared deliberately,
                // which is why only the lower-case spelling is here.
                if (const std::string named = declaredName(init); named == "string") {
                    TypeTable& tt = out_.module.types;
                    const ValueId fresh = callExternal("__polaron_str_copy", tt.ptrType(),
                                                       {tt.ptrType()}, {init}, v->loc);
                    noteName(fresh, "string");
                    init = fresh;
                } else if (const std::string cls = classNameOf(named);
                    isCopyableClass(cls) && named_.count(cls) != 0) {
                    // A LOCAL'S COPY LIVES IN THE FRAME. The name being declared here is the only
                    // thing that holds it, and it dies with the scope.
                    init = copyValueStruct(init, cls, v->loc, /*heap=*/false);
                }
            }
            // §21: A STRING LOCAL OWNS WHAT IT HOLDS, and the scope end gives it back. `ownedString`
            // is copy-on-store at this one of its points; the slot then joins `scoped_` with the
            // objects, so both are released in one order at one exit.
            //
            // `persistent` and `eternal` are excluded because their storage OUTLIVES the scope --
            // that is what those words mean -- and the scope end has no business freeing it.
            if (init != kNoValue && !v->isPersistent && !v->isEternal &&
                pointerDepthOf(slot) == 0 && isStringNamed(resolvedTypeName(v->type))) {
                init = declaredName(init) == "string" ? (claimString(init), init)
                                                      : ownedString(init, v->loc);
                // ...AND THE SLOT STARTS EMPTY, for the reason `zeroSlotAtEntry` was written: the
                // release list is one list for the whole `try`, so the handler frees a local whose
                // declaration the exception never reached.
                //
                //     try { String never = Environment.require("NO_SUCH"); ... }
                //
                // `require` throws, `never` is never stored, and the catch block loaded the slot
                // and freed whatever the frame happened to hold. `system_environment` and
                // `file_control` both died there -- an access violation with the whole run's output
                // still sitting unflushed in stdout's buffer, which is why the differential saw two
                // programs that printed nothing rather than two that crashed.
                zeroSlotAtEntry(slot, v->loc);
                scoped_.push_back(ScopedObject{slot, kStringOwner});
                stringSlots_.insert(slot);
                if (!handlers_.empty()) {
                    unwindObjects_.push_back(ScopedObject{slot, kStringOwner});
                }
            }
            // A LOCAL BOUND TO A STACK OBJECT IS DESTROYED WHEN ITS SCOPE ENDS. Recorded here, run
            // by `destroyScoped`; a heap one is the programmer's to `delete` and is not recorded.
            // AN OBJECT IN A REGION WITHOUT A REGISTRY is still the compiler's to destroy -- at
            // the `release`, not at the closing brace, because that is when the region ends. A
            // plain bump region keeps no registry (nothing about it needs one until something is
            // deleted early), so the list of what to destroy is the list the compiler can see.
            if (const auto* made = dynamic_cast<const ast::NewExpr*>(v->init.get());
                init != kNoValue && made != nullptr && !made->region.empty() &&
                !regionShapeOf(made->region).registry()) {
                if (const std::string cls = classNameOf(declaredName(init));
                    !cls.empty() && findClass(cls) != nullptr &&
                    !destructorOf(*findClass(cls)).empty()) {
                    zeroSlotAtEntry(slot, v->loc);
                    regionObjects_[made->region].push_back(ScopedObject{slot, cls});
                }
            }
            // A SCOPE DESTROYS WHAT IT MADE, NOT WHAT IT WAS HANDED.
            //
            // This asked only whether the initialiser produced something of a class type, so every
            // borrowed pointer a method handed back was adopted by the block that received it:
            // `Surface* s = window.surface();` destroyed the window's surface at the closing brace.
            // The trusted path asks for a `new` and nothing else, and the difference showed up as
            // twelve methods in pico's compositor calling `~Surface` where the trusted kernel has
            // exactly one -- `Compositor.paint`, `Taskbar.paint`, `StartMenu.paint`, each freeing
            // the pixels of a surface it was only drawing into. The surface then held a null buffer
            // at its old size, which is the one shape its own `invariant` forbids, and the next
            // frame stopped the machine.
            // §17.7: A REGION LOCAL GIVES ITS BLOCK BACK AT THE CLOSING BRACE. `region pen =
            // itself.allocate(1 kilobytes);` with no explicit `release` is the ordinary way to
            // write one -- `region_raii` is the sample that says so, and its comment reads `pen
            // freed here by RAII`. This path emitted no release at all: the block was acquired and
            // never returned, and nothing in the program's OUTPUT could show it.
            //
            // Filed in `scoped_` beside the objects rather than in a list of its own, so that one
            // walk in one reverse order releases both. A region declared before the objects built
            // inside it is therefore released AFTER them, which is the only order that can be
            // right; two lists would have to be interleaved by hand to get the same answer.
            if (init != kNoValue && !v->isPersistent && !v->isEternal &&
                ast::mangleGeneric(v->type.name, v->type.typeArgs) == "region") {
                scoped_.push_back(ScopedObject{slot, regionOwnerKey(v->name)});
                if (!handlers_.empty()) {
                    unwindObjects_.push_back(ScopedObject{slot, regionOwnerKey(v->name)});
                }
            }
            if (const auto* built = dynamic_cast<const ast::NewExpr*>(v->init.get());
                built != nullptr && init != kNoValue && !fromAllocator(init) &&
                regionOwned_.count(init) == 0) {
                if (const std::string cls = classNameOf(declaredName(init));
                    !cls.empty() && findClass(cls) != nullptr) {
                    if (!isValueClass(cls)) {
                        zeroSlotAtEntry(slot, v->loc);
                    }
                    // ...UNLESS IT IS `eternal`, which is what the word means: the closing brace
                    // does not end this object's life. pico's desktop is declared inside an `if`,
                    // and destroyed there its compositor and every surface were freed while the
                    // frame timer still held the address -- a #GP in ring 0 on a pixel pointer that
                    // was no longer a pointer. `eternal` is the author saying so in the
                    // declaration, where the compiler can hold the claim.
                    if (!v->isEternal) {
                        scoped_.push_back(ScopedObject{slot, cls});
                        // ...and again for the unwinding path, if this declaration is inside a
                        // `try`. Its scope may be several braces deeper than the `try` itself, and
                        // an exception passing through leaves every one of them.
                        if (!handlers_.empty()) {
                            unwindObjects_.push_back(ScopedObject{slot, cls});
                        }
                    }
                }
            }
            if (init != kNoValue) {
                Inst st;
                st.op = Op::Store;
                st.operands.push_back(init);
                st.operands.push_back(slot);
                st.loc = v->loc;
                emit(std::move(st));
            }
            return;
        }
        // `(int q, int r) = divmod(17, 5);` -- §22.5. ONE evaluation of the tuple, then one local
        // per component. Not lowered at all, so the whole statement did nothing and both names read
        // whatever their slots happened to hold.
        if (auto* td = dynamic_cast<const ast::TupleDeclStmt*>(s)) {
            const ValueId agg = lowerExpr(td->init.get());
            if (agg == kNoValue) {
                gap("TupleDeclStmt(initialiser did not lower)", s->loc);
                return;
            }
            // THE BINDINGS SAY THE SHAPE when the value cannot. A call's result is a bare pointer
            // and carries no layout with it; the declaration on the left names one type per
            // component, which is the same tuple type the callee built.
            const Type* shape = shapeOf(agg);
            if (shape == nullptr || shape->kind != TypeKind::Struct) {
                std::string spelling = "(";
                for (size_t i = 0; i < td->bindings.size(); ++i) {
                    spelling += (i == 0 ? "" : ",") +
                                ast::mangleGeneric(td->bindings[i].type.name,
                                                   td->bindings[i].type.typeArgs);
                }
                spelling += ")";
                shape = baseTypeOf(spelling);
            }
            for (size_t i = 0; i < td->bindings.size(); ++i) {
                const ast::TupleBinding& b = td->bindings[i];
                const Type* want = typeOf(b.type);
                const ValueId slot = allocaFor(b.name, want);
                slotType_[slot] = want;
                noteName(slot, resolvedTypeName(b.type), pointerDepthOfType(b.type));
                if (shape == nullptr || shape->kind != TypeKind::Struct ||
                    i >= shape->fields.size()) {
                    continue;
                }
                Inst g;
                g.op = Op::Gep;
                g.type = out_.module.types.ptrType();
                g.operands.push_back(agg);
                g.aggregate = shape;
                g.imm = static_cast<int64_t>(i);
                g.text = shape->fields[i].name;
                g.loc = s->loc;
                const ValueId at = emit(std::move(g));
                slotType_[at] = shape->fields[i].type;
                storeInto(slot, loadFrom(at, s->loc), s->loc);
            }
            return;
        }
        if (auto* a = dynamic_cast<const ast::AssignStmt*>(s)) {
            // `arr[i] = new T()` FOR A T WITH PERSISTENT FIELDS KEYS THE BLOCK BY THE SLOT (§18.5),
            // not by a name -- the array has one name and as many identities as it has elements.
            // Index 0 counts 0, 1, 2 across delete-and-recreate while index 1 starts fresh, and
            // that is only expressible if the key carries the index. Which slot is a RUN-TIME
            // question, so the block comes from a registry rather than from a global.
            if (const auto* ix = dynamic_cast<const ast::IndexExpr*>(a->target.get())) {
                if (const auto* arrId = dynamic_cast<const ast::IdentifierExpr*>(ix->array.get())) {
                    if (const auto* nw = dynamic_cast<const ast::NewExpr*>(a->value.get())) {
                        if (persistBlock_.count(resolveClassKey(
                                ast::mangleGeneric(nw->className, nw->typeArgs))) != 0) {
                            pendingPersistKey_ =
                                (fn_ != nullptr ? fn_->key : std::string()) + "." + arrId->name;
                            pendingPersistIndex_ = lowerExpr(ix->index.get());
                        }
                    }
                }
            }
            lowerAssign(*a);
            pendingPersistIndex_ = kNoValue;
            return;
        }
        if (auto* f = dynamic_cast<const ast::ForStmt*>(s)) {
            lowerFor(*f);
            return;
        }
        if (auto* d = dynamic_cast<const ast::DeleteStmt*>(s)) {
            // `delete a, b, c;` DELETES EACH. Only the first was lowered, so the rest were leaked
            // and their destructors never ran -- `delete_multi` printed `~1` where the program
            // prints `~1` and `~2`. The extra targets take the same modifiers, which is why they
            // are on the statement rather than being three statements.
            // `delete x from region R` (spec 17.7) IS THE REGION'S BUSINESS. The destructor runs
            // now, and the memory goes back to the region -- to its free-list where it has one, so
            // the next allocation of that size reuses the slot. Treated as an ordinary `delete` it
            // handed a region-interior pointer to the global allocator, and a `pool` never got a
            // slot back: `region_pool_churn` filled a region sized for a hundred objects with ten
            // thousand and panicked.
            if (!d->fromRegion.empty()) {
                lowerDeleteFromRegion(*d);
                return;
            }
            lowerDelete(d->target.get(), d->isCascade, d->loc, &d->cascade);
            for (const ast::ExprPtr& more : d->moreTargets) {
                lowerDelete(more.get(), d->isCascade, d->loc, &d->cascade);
            }
            return;
        }
        if (auto* i = dynamic_cast<const ast::IncDecStmt*>(s)) {
            // `counter++` ON AN `atomic<T>` IS ONE INSTRUCTION (§20.6), not a read, an add and a
            // write -- which is the whole reason the type exists. Through the ordinary path it was
            // three, and two threads doing it lost updates exactly as an unguarded counter does.
            if (const ValueId target = namesAtomic(i->target.get()) ? lowerExpr(i->target.get())
                                                                    : kNoValue;
                target != kNoValue) {
                const std::string cls = classNameOf(declaredName(target));
                if (cls.rfind("atomic$", 0) == 0) {
                    if (const ValueId slot = fieldAddress(target, "value", s->loc);
                        slot != kNoValue) {
                        const Type* held = baseTypeOf(cls.substr(7));
                        const unsigned bits =
                            held != nullptr && held->bits > 0 ? held->bits : 32;
                        Inst in;
                        in.op = Op::AtomicRmw;
                        in.type = held != nullptr ? held : out_.module.types.intType(32);
                        in.operands.push_back(slot);
                        in.operands.push_back(constInt(i->isIncrement ? 1 : -1, bits, s->loc));
                        in.loc = s->loc;
                        emit(std::move(in));
                        return;
                    }
                }
            }
            lowerIncDec(*i);
            return;
        }
        // §30: `unimport X;` takes a class away while the program runs, `reimport X;` gives it
        // back. A namespace or bundle target expands to every type it holds -- the statement names
        // the granularity, and the set was already worked out before anything was lowered.
        if (auto* um = dynamic_cast<const ast::UnimportStmt*>(s)) {
            for (const std::string& cn : unimportTargets(*um)) {
                if (um->isReimport) {
                    reimportClass(cn, s->loc);
                } else {
                    unimportClass(cn, s->loc);
                }
            }
            return;
        }
        // `import X expecting <value> { ... } onFailure { ... };` (§30.18). The class comes back,
        // the block runs IN THE NEW CODE, and its value is compared bit-for-bit with the one the
        // matching `unimport expecting` produced in the old. A mismatch is not an error the
        // compiler can report -- it is the program finding out that the class it got back does not
        // answer the way the one it gave up did -- so there is no default and `onFailure` runs.
        if (auto* rv = dynamic_cast<const ast::ReimportValidateStmt*>(s)) {
            const std::string cn = cgutil::baseType(rv->target);
            reimportClass(cn, s->loc);
            const ValueId expected =
                rv->expected != nullptr ? asWord(lowerExpr(rv->expected.get()), s->loc)
                                        : constInt(0, 64, s->loc);
            const ValueId produced = lowerExpecting(rv->expecting.get(), s->loc);
            Inst same;
            same.op = Op::CmpEq;
            same.type = out_.module.types.boolType();
            same.operands.push_back(expected);
            same.operands.push_back(produced);
            same.loc = s->loc;
            const BlockId bad = fn_->addBlock("reimport.fail");
            const BlockId ok = fn_->addBlock("reimport.ok");
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(emit(std::move(same)));
            br.edges.push_back(Edge{ok, {}});
            br.edges.push_back(Edge{bad, {}});
            br.loc = s->loc;
            emit(std::move(br));
            here_ = bad;
            if (rv->onFailure != nullptr) {
                for (const auto& st : rv->onFailure->statements) {
                    lowerStmt(st.get());
                }
            }
            if (!blockClosed()) {
                Inst go;
                go.op = Op::Br;
                go.edges.push_back(Edge{ok, {}});
                go.loc = s->loc;
                emit(std::move(go));
            }
            here_ = ok;
            return;
        }
        // `using (T r = ...) { ... }` (§23.1): the resource is disposed at EVERY exit of the block
        // -- fall-through, `return`, `break` and an exception unwind alike. Not lowered at all, so
        // the whole statement including its BODY did nothing: `scoped` printed neither `inside
        // using` nor `closing 3`.
        if (auto* us = dynamic_cast<const ast::UsingStmt*>(s)) {
            const size_t before = scoped_.size();
            lowerStmt(us->decl.get());
            // THE RESOURCE IS DISPOSED WHETHER IT IS ON THE HEAP OR NOT, which is the difference
            // from an ordinary local: a `new R() on heap` bound by a plain declaration belongs to
            // whoever deletes it, and one bound by `using` belongs to the block. Registered here
            // because the declaration path deliberately leaves heap objects alone.
            //
            // ...AND THE STORAGE GOES BACK WITH IT. Reaching here at all is the test for whose
            // storage it is: the declaration path registers a FRAME object and deliberately leaves
            // a heap one alone, so a list that did not grow means the resource is on the heap and
            // this block is the only thing that will ever dispose it. Registered without that, the
            // destructor ran -- `scoped` printed `closing 3` on both paths -- and the block stayed:
            // 128 bytes in 6 against the other path's 112 in 5.
            if (scoped_.size() == before) {
                if (auto local = locals_.find(us->varName); local != locals_.end()) {
                    if (const std::string cls = classNameOf(declaredName(local->second));
                        !cls.empty() && findClass(cls) != nullptr) {
                        scoped_.push_back(ScopedObject{local->second, cls, /*heap=*/true});
                        if (!handlers_.empty()) {
                            unwindObjects_.push_back(ScopedObject{local->second, cls,
                                                                  /*heap=*/true});
                        }
                    }
                }
            }
            // `destroyScoped` already walks the list in reverse at every exit, so a `return` inside
            // the block disposes on the way out and nothing has to be repeated for it here.
            lowerScope(us->body);
            if (!blockClosed()) {
                destroyScoped(before, s->loc);
            }
            scoped_.resize(before);
            locals_.erase(us->varName);
            return;
        }
        // `synchronized (m) using T& x { ... }` (§20.5): hold the mutex for the block and bind the
        // name to the protected value ITSELF -- the local's storage is the field's address, so a
        // read or a write of the binding reaches the field with no copy in between. The release is
        // a scope cleanup rather than a statement at the end, so a `throw` out of the body does not
        // leave the mutex locked forever.
        if (auto* sy = dynamic_cast<const ast::SynchronizedStmt*>(s)) {
            const ValueId mutex = lowerExpr(sy->mutex.get());
            if (mutex == kNoValue) {
                gap("SynchronizedStmt(mutex did not lower)", s->loc);
                return;
            }
            TypeTable& tt = out_.module.types;
            const ValueId lockSlot = fieldAddress(mutex, "lock", s->loc);
            const ValueId valueSlot = fieldAddress(mutex, "value", s->loc);
            if (lockSlot == kNoValue || valueSlot == kNoValue) {
                gap("SynchronizedStmt(mutex has no lock/value)", s->loc);
                return;
            }
            const ValueId lock = loadFrom(lockSlot, s->loc);
            callExternal("__polaron_lock_acquire", tt.voidType(), {tt.intType(64)}, {lock}, s->loc);
            const bool had = locals_.count(sy->bindName) != 0;
            const ValueId saved = had ? locals_[sy->bindName] : kNoValue;
            locals_[sy->bindName] = valueSlot;
            slotType_[valueSlot] = typeOf(sy->bindType);
            noteName(valueSlot, ast::mangleGeneric(sy->bindType.name, sy->bindType.typeArgs));
            lowerScope(sy->body);
            if (had) {
                locals_[sy->bindName] = saved;
            } else {
                locals_.erase(sy->bindName);
            }
            callExternal("__polaron_lock_release", tt.voidType(), {tt.intType(64)}, {lock}, s->loc);
            return;
        }
        if (auto* rel = dynamic_cast<const ast::ReleaseStmt*>(s)) {
            // `release persistent obj.field` (§18.15). In an in-process persistent model this
            // DISCARDS the accumulated state: a later reattach starts from zero, exactly as the
            // first attach of the run did. The block itself cannot be freed -- it is a global, and
            // the stable address across reattach is the whole point of a named persistent -- so
            // releasing is ZEROING, which is the observable half and the honest one.
            //
            // ONE field, not the block. Zeroing everything would make `release a.x` discard `a.y`
            // and `a.z` too: a statement that names a field and then throws away its siblings.
            if (rel->isPersistent) {
                if (const auto* mem = dynamic_cast<const ast::MemberExpr*>(rel->target.get())) {
                    const ValueId obj = lowerExpr(mem->object.get());
                    if (obj != kNoValue) {
                        if (const ValueId at =
                                persistentFieldAddress(obj, ownerOf(obj), mem->member, s->loc);
                            at != kNoValue) {
                            const Type* ft = slotType_.count(at) != 0 ? slotType_[at] : nullptr;
                            Inst st;
                            st.op = Op::Store;
                            st.operands.push_back(
                                ft != nullptr && ft->kind == TypeKind::Ptr
                                    ? nullPointer(ft, s->loc)
                                    : constInt(0,
                                               ft != nullptr && ft->kind == TypeKind::Int ? ft->bits
                                                                                          : 32,
                                               s->loc));
                            st.operands.push_back(at);
                            st.loc = s->loc;
                            emit(std::move(st));
                        }
                    }
                }
                return;
            }
            // `release region R` IS AN INSTRUCTION (§7.6), which is the whole reason a region is a
            // first-class handle rather than a runtime call: the binder can then ask "does this
            // pointer outlive its region" as a dataflow question, and verifier rule 13 checks it.
            if (!rel->region.empty()) {
                // `release region Node` WHERE `Node` IS A CLASS releases the family's arena, and
                // this is the case explicit release was designed for: a phase arena is worth having
                // because it dies at the end of the phase, and "released at program exit" would not
                // solve the problem that motivated it.
                //
                // GATED BY THE SAME LIVE-INSTANCE PROOF `unimport` performs, over the same counter.
                // With nothing alive there is no object whose fields or destructor can outlive the
                // block; with something alive, freeing the arena hands every live reference a
                // dangling pointer, which is precisely the failure the language exists to make
                // impossible. Checked at RUN TIME for the same reason it is there: how many
                // instances exist is not a question the compiler can answer.
                if (livesInClassArena(rel->region)) {
                    releaseClassArena(rel->region, rel->loc);
                    return;
                }
                // A REGION MAY BE A FIELD (spec 17): `release region this.arena`. Looking only in
                // locals meant that release matched nothing and fell out of the branch entirely --
                // no teardown and no free, on the one statement whose whole job is both.
                if (const ValueId block = regionBlockFor(rel->region, rel->loc);
                    block != kNoValue) {
                    releaseRegionBlock(rel->region, block, rel->loc);
                    // ...AND THE SCOPE END MUST NOT DO IT AGAIN. A region declared as a local is
                    // released at the closing brace by RAII; an explicit `release` mid-method is
                    // the programmer saying "now, not then", not "twice". The entry is blanked
                    // rather than erased so every other entry keeps its position -- the trusted
                    // path clears its `className` for the same reason.
                    for (ScopedObject& live : scoped_) {
                        if (live.cls == regionOwnerKey(rel->region)) {
                            live.cls.clear();
                        }
                    }
                    // ...AND A FIELD IS NULLED, because blanking the scope entry only stops THIS
                    // method releasing it twice. A field region is released from wherever its owner
                    // decides -- `Pool<T>` has a `releaseAll()` that releases it and a `~Pool` that
                    // releases it again -- and no compile-time list spans two methods. The runtime
                    // is written for exactly this and says so at the top of its teardown: "an
                    // unallocated / already-released region (explicit release nulled it)". Nothing
                    // was doing the nulling, so the second release tore down and freed a block that
                    // was already gone: `arena_pool` exited 0xC0000374, heap corruption.
                    if (!locals_.count(bareRegionName(rel->region))) {
                        if (const ValueId self = selfLoad(rel->loc); self != kNoValue) {
                            if (const ValueId at =
                                    fieldAddress(self, bareRegionName(rel->region), rel->loc);
                                at != kNoValue) {
                                slotType_[at] = out_.module.types.ptrType();
                                storeInto(at, nullPointer(rel->loc), rel->loc);
                            }
                        }
                    }
                    return;
                }
            }
            // `release persistent obj.field` -- the storage class is on the global (§5), so what
            // this releases is the object the field holds.
            if (rel->target != nullptr) {
                const ValueId v = lowerExpr(rel->target.get());
                if (v != kNoValue) {
                    // A PRIMITIVE IS NOT DROPPED, which is the same rule `delete` follows two
                    // hundred lines up and this path did not: `release persistent this.hitCount`
                    // over an `int` emitted `drop i32`, and verifier rule 10 is right that nothing
                    // owning is being released. It went unseen only because the enclosing method
                    // was unreachable and the dead-code pass removed it before anyone looked --
                    // which is what changed when vtable entries became roots.
                    const Type* t = fn_->value(v)->type;
                    const bool primitive =
                        t != nullptr && (t->kind == TypeKind::Int || t->kind == TypeKind::Float ||
                                         t->kind == TypeKind::Bool || t->kind == TypeKind::Addr);
                    if (primitive) {
                        gap("ReleaseStmt(target is " + std::string(TypeTable::spell(t)) + ")",
                            rel->loc);
                        return;
                    }
                    Inst drop;
                    drop.op = Op::Drop;
                    drop.type = t;
                    drop.operands.push_back(v);
                    drop.loc = rel->loc;
                    emit(std::move(drop));
                }
                return;
            }
            gap("ReleaseStmt(region not in scope)", rel->loc);
            return;
        }
        if (auto* rb = dynamic_cast<const ast::RollbackStmt*>(s)) {
            auto it = locals_.find(rb->region);
            const ValueId mark = rb->checkpoint != nullptr ? lowerExpr(rb->checkpoint.get())
                                                           : constLong(0, rb->loc);
            if (it != locals_.end() && mark != kNoValue) {
                // THE RUNTIME DOES BOTH HALVES: destructors newest-first for everything allocated
                // after the checkpoint, then the cursor rewind. Rewinding without the destructors
                // would leak whatever those objects held, and running them here would need the
                // registry the runtime keeps.
                TypeTable& tt = out_.module.types;
                callExternal("__polaron_region_rollback", tt.voidType(),
                             {tt.ptrType(), tt.intType(64)},
                             {loadFrom(it->second, rb->loc), widenToLong(mark, rb->loc)}, rb->loc);
                return;
            }
            gap("RollbackStmt(region or mark not in scope)", rb->loc);
            return;
        }
        if (auto* fe = dynamic_cast<const ast::ForeachStmt*>(s)) {
            lowerForeach(*fe);
            return;
        }
        // `break` and `continue` are BRANCHES to blocks the enclosing loop already made. A stack of
        // them, because a loop inside a loop has two answers and the inner one wins -- which is the
        // rule, and a stack is what states it rather than describing it.
        if (auto* th = dynamic_cast<const ast::ThrowStmt*>(s)) {
            // A THROW LEAVES THE FUNCTION AND DOES NOT COME BACK. The object is built, handed to
            // the runtime, and the block ends `unreachable` -- which is what makes every path after
            // it dead and is why the trusted path emits the same shape.
            // `raise`, NOT a call to a name nobody defines. This called `__polaron_throw` -- a
            // symbol that exists in no runtime and never has; the module verified, because an
            // invented external is a legal declaration, and the failure arrived at link time with
            // no line number on it. How a throw is actually started is a TARGET question
            // (`_CxxThrowException` here, `__cxa_throw` elsewhere), which is precisely the kind of
            // question §7 leaves to the backend rather than answering once, wrongly, up here.
            const ValueId obj = lowerExpr(th->value.get());
            Inst raise;
            raise.op = Op::Raise;
            raise.loc = s->loc;
            if (obj != kNoValue) {
                raise.operands.push_back(obj);
            }
            // A `throw` LEAVES EVERY SCOPE BETWEEN HERE AND THE HANDLER, so their teardown runs
            // first -- `defer` blocks innermost first, then the stack objects in reverse. The
            // handler may be in this method or in a caller; either way what is left behind is
            // everything declared since the enclosing `try` began, and nothing older.
            //
            // Emitting it HERE rather than in a cleanup funclet is what makes it work across a
            // call: `risky()` declares two guards and throws, and its caller's `catch` is in
            // another frame entirely. `exceptions_raii` prints `dtor 2 / dtor 1` before its
            // handler runs, and this pass printed neither.
            {
                const size_t keepObjects = handlers_.empty() ? 0 : handlers_.back().objects;
                const size_t keepDefers = handlers_.empty() ? 0 : handlers_.back().defers;
                runDeferred(s->loc, keepDefers);
                destroyScoped(keepObjects, s->loc);
            }
            // A `throw` INSIDE A `try` IS CAUGHT BY THAT `try`. Emitted with no unwind edge it
            // left the function instead, so `try { throw new E(); } catch (E e) { ... }` -- the
            // shape every exception sample opens with -- ran the throw and never the handler.
            if (!handlers_.empty()) {
                raise.edges.push_back(Edge{handlers_.back().landing, {}});
            }
            emit(std::move(raise));
            return;
        }
        if (auto* tr = dynamic_cast<const ast::TryStmt*>(s)) {
            lowerTry(*tr);
            return;
        }
        // `break outer;` LEAVES THE LOOP THAT WEARS THAT LABEL, not the innermost one. The label was
        // being ignored, so a labelled break left one level and the search that should have stopped
        // kept going -- `labeled` found 32 where the program finds 23.
        // `break` AND `continue` LEAVE SCOPES, and everything those scopes declared is torn down on
        // the way out -- the same teardown the end of the body runs, at the same depth.
        if (auto* br = dynamic_cast<const ast::BreakStmt*>(s)) {
            if (const LoopTargets* t = loopFor(br->label); t != nullptr) {
                // EVERY FIELD READ BEFORE ANYTHING IS LOWERED. `runDeferred` lowers defer bodies,
                // which may contain loops of their own, and a `push_back` on `loops_` moves the
                // vector -- leaving `t` pointing at storage that was freed.
                const BlockId target = t->breakTo;
                const size_t objects = std::min(t->objects, scoped_.size());
                const size_t defers = std::min(t->defers, deferred_.size());
                runDeferred(s->loc, defers);
                destroyScoped(objects, s->loc);
                gotoIfOpen(target);
                here_ = fn_->addBlock(fresh("afterbreak"));
            }
            return;
        }
        if (auto* co = dynamic_cast<const ast::ContinueStmt*>(s)) {
            if (const LoopTargets* t = loopFor(co->label); t != nullptr) {
                const BlockId target = t->continueTo;
                const size_t objects = std::min(t->objects, scoped_.size());
                const size_t defers = std::min(t->defers, deferred_.size());
                runDeferred(s->loc, defers);
                destroyScoped(objects, s->loc);
                gotoIfOpen(target);
                here_ = fn_->addBlock(fresh("aftercont"));
            }
            return;
        }
        // THE CHAOS TETRAD IS CONTROL FLOW, so it is edges on the block and nothing else. §7.9: the
        // CFG becomes literally what the program says, with nothing to infer -- which is the whole
        // reason these are not a runtime mechanism.
        if (auto* lm = dynamic_cast<const ast::LabelMarkStmt*>(s)) {
            // The block may already exist -- a forward `goto` made it. Making a second one here
            // would leave the jump pointing at an empty block that falls nowhere.
            const BlockId named = blockForLabel(lm->name);
            gotoIfOpen(named);
            here_ = named;
            // A LABEL THAT SOMETHING ABSTAINS FROM CARRIES A GUARD: while the counter is non-zero,
            // control skips to the NEXT label (spec 7.11), which is where the abstained region
            // ends. A label nobody abstains from gets nothing, so the common case pays nothing.
            if (abstained_.count(lm->name) != 0) {
                guardAbstainedLabel(lm->name, s->loc);
            }
            // `comefrom L` STEALS CONTROL AT `label L` (§7.9). Reaching the label does not fall
            // through -- it goes to wherever the `comefrom` is written, and the statements between
            // never run. This was recorded as a field on the block that nothing reads, so the
            // construct did nothing at all and `comefrom` printed the line it exists to skip.
            if (comefromNames_.count(lm->name) != 0) {
                leaveScopesFor(comefromOwner_.count(lm->name) != 0 ? comefromOwner_[lm->name]
                                                                   : nullptr,
                               s->loc);
                gotoIfOpen(comefromBlockFor(lm->name));
                here_ = fn_->addBlock(fresh("stolen"));
            }
            return;
        }
        if (auto* cf = dynamic_cast<const ast::ComefromStmt*>(s)) {
            // ON THE WAY DOWN IT IS A NO-OP, and on the way back it is the landing point -- which
            // is the whole of the backward form: `comefrom` at the top plus `label` under a
            // condition is a loop whose exit is written where the condition is.
            const BlockId landing = comefromBlockFor(cf->name);
            gotoIfOpen(landing);
            here_ = landing;
            return;
        }
        if (auto* ab = dynamic_cast<const ast::AbstainfromStmt*>(s)) {
            // `abstainfrom` IS A RUNTIME MECHANISM, not a static edit of the CFG (spec 7.11). It
            // was recorded as a removed EDGE on the block, which nothing reads and which could not
            // express what the keyword means: whether the region runs is decided when control
            // reaches the label, and `if (mode == 1) { abstainfrom a; }` decides it differently on
            // different runs. As an edge, `AB|B` came out `AB|AB` -- the abstention never happened.
            //
            // A COUNTER, so that two abstentions stack and one `reinstate` does not undo both.
            //
            // ATOMICALLY. This was a load, an add and a store, which is three steps where the
            // counter needs one: two threads abstaining lose an update, and -- the case that
            // matters more, because the counter is GLOBAL BY NECESSITY (the compiler's own sample
            // abstains in one call and observes it in the next) -- anything that preempts the method
            // between the load and the store loses one too. On bare metal that is an interrupt, and
            // an interrupt is the reason the counter exists where it does.
            //
            // The trusted path emits `atomicrmw add ... seq_cst` and an atomic load beside it. Both
            // ops are already in this IR and already translated; nothing here needed inventing.
            const ValueId counter = abstainCounter(ab->name, s->loc);
            Inst step;
            step.op = Op::AtomicRmw;
            step.type = out_.module.types.intType(64);
            step.operands.push_back(counter);
            step.operands.push_back(constInt(ab->isReinstate ? -1 : 1, 64, s->loc));
            step.loc = s->loc;
            emit(std::move(step));
            abstained_.insert(ab->name);
            return;
        }
        if (auto* g = dynamic_cast<const ast::GotoStmt*>(s)) {
            // A `goto` OUT OF A SCOPE STILL LEAVES IT (§7.9). Everything declared between here and
            // the label's own block is torn down first -- `defer` bodies innermost-first, then the
            // stack objects in reverse -- or the jump leaks: `goto out` from inside a loop inside an
            // `if` skipped a defer and two destructors and printed `start` then `after`.
            gotoScopeCleanup(g->name, s->loc);
            // A FORWARD `goto` NAMES A LABEL THAT HAS NOT BEEN LOWERED YET. Looking it up and
            // giving up when absent made the jump vanish: `goto negative;` fell through and printed
            // `non-negative`. The block is created here on first mention and the label reuses it --
            // which is also what makes a backward jump and a forward one the same code.
            gotoIfOpen(blockForLabel(g->name));
            here_ = fn_->addBlock(fresh("after"));
            return;
        }
        if (auto* ls = dynamic_cast<const ast::LabeledStmt*>(s)) {
            const BlockId named = blockForLabel(ls->label);
            gotoIfOpen(named);
            here_ = named;
            // THE LABEL BELONGS TO THE LOOP INSIDE IT. Recorded before the statement is lowered so
            // that the loop, when it pushes its targets, can take the name with it -- that is what
            // `break outer;` looks up.
            pendingLoopLabel_ = ls->label;
            lowerStmt(ls->stmt.get());
            pendingLoopLabel_.clear();
            return;
        }
        if (auto* i = dynamic_cast<const ast::IfStmt*>(s)) {
            lowerIf(*i);
            return;
        }
        if (auto* w = dynamic_cast<const ast::WhileStmt*>(s)) {
            lowerWhile(*w);
            return;
        }
        if (auto* dw = dynamic_cast<const ast::DoWhileStmt*>(s)) {
            lowerDoWhile(*dw);
            return;
        }
        // `yield x` INSIDE A MATCH ARM is that arm's value: a branch to the join carrying it. It is
        // not a return and not a coroutine yield -- the enclosing `match` expression is what it
        // leaves.
        // `yield x` INSIDE A GENERATOR SUSPENDS IT. The element is buffered in the state, the step
        // is set to where execution resumes, and the function RETURNS -- which is what a generator
        // is and what no ordinary control flow can express. The block that follows is where the
        // next `$resume` comes back to, and the dispatch at the top learns of it here.
        if (auto* y = dynamic_cast<const ast::YieldStmt*>(s);
            y != nullptr && genState_ != nullptr && genResume_ != nullptr) {
            const ValueId v = y->value != nullptr ? lowerExpr(y->value.get()) : kNoValue;
            auto at = [&](size_t index) {
                Inst g;
                g.op = Op::Gep;
                g.type = out_.module.types.ptrType();
                g.operands.push_back(genStatePtr_);
                g.aggregate = genState_;
                g.imm = static_cast<int64_t>(index);
                g.text = genState_->fields[index].name;
                g.loc = s->loc;
                const ValueId a = emit(std::move(g));
                slotType_[a] = genState_->fields[index].type;
                return a;
            };
            if (v != kNoValue) {
                storeInto(at(1), v, s->loc);
            }
            const BlockId back = genResume_->addBlock(fresh("gen.at"));
            genSteps_.push_back(back);
            storeInto(at(0), constInt(static_cast<int64_t>(genSteps_.size()), 32, s->loc), s->loc);
            Inst give;
            give.op = Op::Ret;
            give.operands.push_back(constBool(true, s->loc));
            give.loc = s->loc;
            emit(std::move(give));
            here_ = back;
            return;
        }
        if (auto* y = dynamic_cast<const ast::YieldStmt*>(s); y != nullptr && !yields_.empty()) {
            const YieldTarget to = yields_.back();
            const ValueId v = y->value != nullptr ? lowerExpr(y->value.get()) : kNoValue;
            Inst go;
            go.op = Op::Br;
            Edge e{to.join, {}};
            e.args.push_back(v != kNoValue
                                 ? lowerConversion(v, fn_->value(v)->type, to.type, s->loc)
                                 : undefOf(to.type, s->loc));
            go.edges.push_back(e);
            go.loc = s->loc;
            emit(std::move(go));
            return;
        }
        if (auto* sw = dynamic_cast<const ast::SwitchStmt*>(s)) {
            lowerSwitch(*sw);
            return;
        }
        if (auto* mt = dynamic_cast<const ast::MatchStmt*>(s)) {
            lowerMatch(*mt);
            return;
        }
        if (auto* b = dynamic_cast<const ast::Block*>(s)) {
            lowerScope(*b);
            return;
        }
        gap(typeid(*s).name(), s->loc);
    }

    // `obj.name` where `name` is a computed property: the getter, called. Answers `kNoValue` when
    // the name is an ordinary field, which is the common case and must stay a plain `gep`.
    ValueId propertyRead(ValueId object, const std::string& name, SourceLocation loc) {
        if (object == kNoValue) {
            return kNoValue;
        }
        const std::string cls = classNameOf(declaredName(object));
        const ast::ClassDecl* decl = cls.empty() ? nullptr : findClass(cls);
        if (decl == nullptr) {
            return kNoValue;
        }
        bool isProperty = false;
        forEachMember<ast::MethodDecl>(*decl, [&](const ast::MethodDecl& m) {
            if (m.name == name && m.isProperty) {
                isProperty = true;
            }
        });
        if (!isProperty) {
            return kNoValue;
        }
        const Function* target = resolveKey(cls + "." + name);
        if (target == nullptr) {
            return kNoValue;
        }
        const ValueId out = emitCall(target, {object}, loc);
        if (auto it = returnName_.find(target->key); it != returnName_.end()) {
            noteName(out, it->second.name, it->second.pointerDepth);
        }
        return out;
    }

    // Is this name an `atomic<T>`, asked of the declaration rather than of a lowered value. A local
    // and a field of `this` are the two spellings that reach an atomic assignment.
    // AN `atomic<T>*` IS NOT AN `atomic<T>`.
    //
    // Assigning to an atomic writes its VALUE cell -- that is what makes `counter = 5` an atomic
    // store rather than a rebinding. Assigning to a POINTER to one rebinds the pointer, and the two
    // are opposite operations on the same spelling.
    //
    // The pointer depth was not being read, so `Guest.lockWord = &lockCell` -- a static holding the
    // address of a cell on a frame that outlives every thread using it -- did an atomic store
    // through the pointer it was about to be given, while that pointer was still null. pico's ring-3
    // guest died at CR2=0x8, offset eight of nothing, before it had spawned a thread.
    static bool atomicByValue(const std::string& name, uint8_t depth) {
        return depth == 0 && name.rfind("atomic$", 0) == 0;
    }

    bool namesAtomic(const ast::Expr* e) {
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            auto it = locals_.find(id->name);
            if (it != locals_.end()) {
                return atomicByValue(classNameOf(declaredName(it->second)),
                                     pointerDepthOf(it->second));
            }
            if (!selfClassName_.empty()) {
                auto f = fieldTypeName_.find(selfClassName_ + "." + id->name);
                return f != fieldTypeName_.end() &&
                       atomicByValue(f->second.name, f->second.pointerDepth);
            }
            return false;
        }
        if (const auto* m = dynamic_cast<const ast::MemberExpr*>(e)) {
            for (const auto& [key, held] : fieldTypeName_) {
                const size_t dot = key.rfind('.');
                if (dot != std::string::npos && key.substr(dot + 1) == m->member &&
                    atomicByValue(held.name, held.pointerDepth)) {
                    return true;
                }
            }
        }
        return false;
    }

    // `atomic<T>` ON THE LEFT OF AN `=`. Answers the value cell's address when it handled the
    // assignment, and nothing when the target is not an atomic or the value is another atomic
    // object -- in which case the store is an ordinary reference store.
    ValueId atomicValueSlot(const ast::AssignStmt& s) {
        // ASKED BEFORE ANYTHING IS LOWERED. Evaluating the target to find out what it is would emit
        // a full READ of it on every assignment in the program -- three extra loads on `**pp = 99`,
        // and a second evaluation of anything with a side effect.
        if (!namesAtomic(s.target.get())) {
            return kNoValue;
        }
        const ValueId target = lowerExpr(s.target.get());
        if (target == kNoValue) {
            return kNoValue;
        }
        const std::string cls = classNameOf(declaredName(target));
        if (cls.rfind("atomic$", 0) != 0) {
            return kNoValue;
        }
        // `a = b` between two atomics rebinds the handle. Recognised from the VALUE's declared
        // class, which is what the trusted path asks and the only thing that can tell the two
        // spellings apart.
        if (const auto* nw = dynamic_cast<const ast::NewExpr*>(s.value.get());
            nw != nullptr && ast::mangleGeneric(nw->className, nw->typeArgs).rfind("atomic", 0) == 0) {
            return kNoValue;
        }
        const ValueId slot = fieldAddress(target, "value", s.loc);
        if (slot == kNoValue) {
            return kNoValue;
        }
        const Type* held = baseTypeOf(cls.substr(7));
        const unsigned bits = held != nullptr && held->bits > 0 ? held->bits : 32;
        // `counter = counter + n` and `counter = counter - n` are the compound forms the parser
        // already rewrote; recognising them here is what turns `+=` into one instruction.
        if (const auto* bin = dynamic_cast<const ast::BinaryExpr*>(s.value.get())) {
            const auto* id = dynamic_cast<const ast::IdentifierExpr*>(s.target.get());
            auto same = [&](const ast::Expr* e) {
                const auto* other = dynamic_cast<const ast::IdentifierExpr*>(e);
                return id != nullptr && other != nullptr && other->name == id->name;
            };
            const ast::Expr* delta = nullptr;
            bool minus = false;
            if (bin->op == "+" && same(bin->lhs.get())) {
                delta = bin->rhs.get();
            } else if (bin->op == "+" && same(bin->rhs.get())) {
                delta = bin->lhs.get();
            } else if (bin->op == "-" && same(bin->lhs.get())) {
                delta = bin->rhs.get();
                minus = true;
            }
            if (delta != nullptr) {
                ValueId by = fitInt(lowerExpr(delta), bits, s.loc);
                if (minus) {
                    Inst neg;
                    neg.op = Op::NegWrap;
                    neg.type = out_.module.types.intType(bits);
                    neg.operands.push_back(by);
                    neg.loc = s.loc;
                    by = emit(std::move(neg));
                }
                Inst in;
                in.op = Op::AtomicRmw;
                in.type = held != nullptr ? held : out_.module.types.intType(32);
                in.operands.push_back(slot);
                in.operands.push_back(by);
                in.loc = s.loc;
                emit(std::move(in));
                return slot;
            }
        }
        const ValueId v = lowerExpr(s.value.get());
        if (v == kNoValue) {
            return kNoValue;
        }
        Inst st;
        st.op = Op::AtomicStore;
        st.operands.push_back(fitInt(v, bits, s.loc));
        st.operands.push_back(slot);
        st.loc = s.loc;
        emit(std::move(st));
        return slot;
    }

    // WHICH OVERLOAD OF A LITERAL SUFFIX (§17.10 rule 6): an exact match on the argument's spelled
    // type, and the first declared otherwise. Decided from the SPELLING rather than from the
    // lowered value, because `1.5` and `1` intern to different widths but `1` and `1u` do not --
    // and the declaration says which of those the author meant.
    const Function* literalOverloadFor(const std::string& base, const ast::Expr* arg) {
        auto set = literalOverloads_.find(base);
        if (set == literalOverloads_.end() || set->second.empty()) {
            return resolveKey(base);
        }
        const std::string want = spelledTypeOf(arg);
        for (const auto& [param, key] : set->second) {
            if (param == want) {
                return resolveKey(key);
            }
        }
        return resolveKey(set->second.front().second);
    }

    // What an argument's type is CALLED, from the expression alone. Enough for the one question
    // asked of it -- which of a handful of one-parameter overloads a literal names -- and honest
    // about answering nothing when the expression is not a literal.
    std::string spelledTypeOf(const ast::Expr* e) {
        if (const auto* f = dynamic_cast<const ast::FloatLiteralExpr*>(e)) {
            return !f->text.empty() && (f->text.back() == 'f' || f->text.back() == 'F') ? "float"
                                                                                       : "double";
        }
        if (dynamic_cast<const ast::IntLiteralExpr*>(e) != nullptr) {
            return "int";
        }
        if (dynamic_cast<const ast::StringLiteralExpr*>(e) != nullptr) {
            return "String";
        }
        if (dynamic_cast<const ast::BoolLiteralExpr*>(e) != nullptr) {
            return "boolean";
        }
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            auto it = locals_.find(id->name);
            if (it != locals_.end()) {
                return declaredName(it->second);
            }
        }
        return std::string();
    }

    // The setter a member routes through, looked up in the class and then up the chain -- an
    // inherited property is written through the base's setter, and the field is the base's too.
    std::string propertySetterOf(const std::string& cls, const std::string& member) {
        for (std::string walk = cls; !walk.empty();) {
            const ast::ClassDecl* decl = findClass(walk);
            if (decl == nullptr) {
                break;
            }
            std::string found;
            forEachMember<ast::MethodDecl>(*decl, [&](const ast::MethodDecl& m) {
                if (m.name == member && m.isProperty && !m.propertySetter.empty()) {
                    found = m.propertySetter;
                }
            });
            forEachMember<ast::FieldDecl>(*decl, [&](const ast::FieldDecl& f) {
                if (f.name == member && !f.propertySetter.empty()) {
                    found = f.propertySetter;
                }
            });
            if (!found.empty()) {
                return found;
            }
            walk = decl->superclass;
        }
        return std::string();
    }

    // The write half of §8.4. A property whose declaration wrote a `set { }` carries the setter's
    // name; one that did not is read-only and is not this. Returns false when the member is an
    // ordinary field, which is the overwhelming majority and must cost nothing.
    bool assignThroughSetter(const ast::MemberExpr& target, const ast::AssignStmt& s) {
        const ValueId object = lowerExpr(target.object.get());
        if (object == kNoValue) {
            return false;
        }
        const std::string cls = classNameOf(declaredName(object));
        const ast::ClassDecl* decl = cls.empty() ? nullptr : findClass(cls);
        if (decl == nullptr) {
            return false;
        }
        // TWO SHAPES REACH HERE. `get { } set { }` has no storage at all and becomes a getter
        // method carrying the setter's name; `get; set { }` keeps a real backing FIELD and puts
        // the setter's name on the field. Both mean the same thing at a write site, and looking
        // for only one of them left half the properties writing straight past their setter.
        std::string setter = propertySetterOf(cls, target.member);
        if (setter.empty()) {
            return false;
        }
        const Function* fn = resolveKey(cls + "." + setter);
        if (fn == nullptr) {
            return false;
        }
        // ...EXCEPT INSIDE THE SETTER ITSELF, which writes the backing field directly. Routing
        // there too is unbounded recursion -- `this.balance = 0` inside `balance$set` calling
        // `balance$set`.
        if (fn_ != nullptr && fn_->key == fn->key) {
            return false;
        }
        // `t.p += 1` needs no case of its own: the parser has already rewritten a compound
        // assignment into `t.p = t.p + 1`, and the read half goes through the getter by the
        // ordinary member-read path.
        const ValueId value = lowerExpr(s.value.get());
        if (value == kNoValue) {
            return false;
        }
        emitCall(fn, {object, value}, s.loc);
        return true;
    }

    // Is this the name of a callable value? `function<int,int>` and `funcptr<...>` are the two
    // spellings; a `funcptr` is the bare code pointer and a `function` is `{code, env}`.
    static bool isClosureName(const std::string& n) {
        return n.rfind("function<", 0) == 0;
    }

    // ---- §20.4, `Channel.select()` ----
    //
    // One arm of the chain: a channel and its handler, or a deadline and its handler.
    struct SelectArm {
        const ast::Expr* channel = nullptr;
        const ast::Expr* handler = nullptr;
        const ast::Expr* deadline = nullptr;
        bool isTimeout = false;
    };

    // Walks the chain BOTTOM-UP -- `.timeout(...)` is the outermost call and `Channel.select()` the
    // innermost -- collecting the arms back into source order. Answers false for a stray `.run()`
    // on anything else, which is what keeps this from claiming calls it has no business in.
    bool collectSelectChain(const ast::Expr* chain, std::vector<SelectArm>& arms) {
        const auto* call = dynamic_cast<const ast::CallExpr*>(chain);
        if (call == nullptr) {
            return false;
        }
        const auto* mem = dynamic_cast<const ast::MemberExpr*>(call->callee.get());
        if (mem == nullptr) {
            return false;
        }
        if (mem->member == "select" && call->args.empty()) {
            const auto* base = dynamic_cast<const ast::IdentifierExpr*>(mem->object.get());
            return base != nullptr && base->name == "Channel";
        }
        if (!collectSelectChain(mem->object.get(), arms)) {
            return false;
        }
        if (mem->member == "receive" && call->args.size() == 2) {
            arms.push_back({call->args[0].get(), call->args[1].get(), nullptr, false});
            return true;
        }
        if (mem->member == "timeout" && call->args.size() == 2) {
            arms.push_back({nullptr, call->args[1].get(), call->args[0].get(), true});
            return true;
        }
        return false;
    }

    // A POLL LOOP, not a blocking wait on several things at once: try each channel in turn, run the
    // first handler that gets a value, and yield when none does. The deadline is checked after the
    // channels so an arm that is ready wins over a timeout that has just expired -- which is what
    // "select" means and what makes the timeout the last resort rather than a race.
    void lowerSelect(const std::vector<SelectArm>& arms, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* i32 = tt.intType(32);
        const Type* ptr = tt.ptrType();
        struct Ready {
            ValueId handle = kNoValue;
            ValueId handler = kNoValue;
            std::string elem;
        };
        std::vector<Ready> waiting;
        ValueId timeoutHandler = kNoValue;
        ValueId deadline = kNoValue;
        // EVALUATED ONCE, BEFORE THE LOOP. A handler is a closure expression and a channel is an
        // object: re-evaluating either per iteration would build a fresh closure every spin.
        for (const SelectArm& a : arms) {
            if (a.isTimeout) {
                deadline = fitInt(lowerExpr(a.deadline), 64, loc);
                timeoutHandler = lowerExpr(a.handler);
                continue;
            }
            const ValueId chan = lowerExpr(a.channel);
            if (chan == kNoValue) {
                continue;
            }
            const std::string cls = classNameOf(declaredName(chan));
            const ValueId slot = fieldAddress(chan, "h", loc);
            if (slot == kNoValue) {
                continue;
            }
            waiting.push_back({loadFrom(slot, loc), lowerExpr(a.handler),
                               cls.rfind("Channel$", 0) == 0 ? cls.substr(8) : std::string("int")});
        }
        ValueId started = kNoValue;
        if (deadline != kNoValue) {
            started = callExternal("__polaron_now_ms", i64, {}, {}, loc);
        }
        Inst room;
        room.op = Op::Alloca;
        room.type = i64;
        room.text = "sel.tmp";
        room.loc = loc;
        const ValueId tmp = emit(std::move(room));
        slotType_[tmp] = i64;

        const BlockId spin = fn_->addBlock("sel.loop");
        const BlockId out = fn_->addBlock("sel.done");
        Inst enter;
        enter.op = Op::Br;
        enter.edges.push_back(Edge{spin, {}});
        enter.loc = loc;
        emit(std::move(enter));
        here_ = spin;
        for (const Ready& r : waiting) {
            const ValueId got = callExternal("__polaron_chan_try_receive", i32, {i64, ptr},
                                             {r.handle, tmp}, loc);
            Inst any;
            any.op = Op::CmpNe;
            any.type = tt.boolType();
            any.operands.push_back(got);
            any.operands.push_back(constInt(0, 32, loc));
            any.loc = loc;
            const BlockId take = fn_->addBlock("sel.recv");
            const BlockId next = fn_->addBlock("sel.next");
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(emit(std::move(any)));
            br.edges.push_back(Edge{take, {}});
            br.edges.push_back(Edge{next, {}});
            br.loc = loc;
            emit(std::move(br));
            here_ = take;
            callHandler(r.handler, fromWord(loadFrom(tmp, loc), r.elem, loc), loc);
            Inst leave;
            leave.op = Op::Br;
            leave.edges.push_back(Edge{out, {}});
            leave.loc = loc;
            emit(std::move(leave));
            here_ = next;
        }
        if (timeoutHandler != kNoValue) {
            const ValueId now = callExternal("__polaron_now_ms", i64, {}, {}, loc);
            Inst gone;
            gone.op = Op::SubWrap;
            gone.type = i64;
            gone.operands.push_back(now);
            gone.operands.push_back(started);
            gone.loc = loc;
            Inst late;
            late.op = Op::CmpGeS;
            late.type = tt.boolType();
            late.operands.push_back(emit(std::move(gone)));
            late.operands.push_back(deadline);
            late.loc = loc;
            const BlockId fire = fn_->addBlock("sel.timeout");
            const BlockId keep = fn_->addBlock("sel.cont");
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(emit(std::move(late)));
            br.edges.push_back(Edge{fire, {}});
            br.edges.push_back(Edge{keep, {}});
            br.loc = loc;
            emit(std::move(br));
            here_ = fire;
            callHandler(timeoutHandler, kNoValue, loc);
            Inst leave;
            leave.op = Op::Br;
            leave.edges.push_back(Edge{out, {}});
            leave.loc = loc;
            emit(std::move(leave));
            here_ = keep;
        }
        callExternal("__polaron_yield", tt.voidType(), {}, {}, loc);
        Inst again;
        again.op = Op::Br;
        again.edges.push_back(Edge{spin, {}});
        again.loc = loc;
        emit(std::move(again));
        here_ = out;
    }

    // A `function<void>` or `function<void, T>` closure, called with an optional argument. The
    // environment is argument zero; that is the whole of the convention.
    void callHandler(ValueId closure, ValueId arg, SourceLocation loc) {
        if (closure == kNoValue) {
            return;
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        Inst codeAt;
        codeAt.op = Op::Gep;
        codeAt.type = ptr;
        codeAt.operands.push_back(closure);
        codeAt.imm = 0;
        codeAt.loc = loc;
        const ValueId codeSlot = emit(std::move(codeAt));
        slotType_[codeSlot] = ptr;
        Inst envAt;
        envAt.op = Op::Gep;
        envAt.type = ptr;
        envAt.operands.push_back(closure);
        envAt.imm = 8;
        envAt.loc = loc;
        const ValueId envSlot = emit(std::move(envAt));
        slotType_[envSlot] = ptr;
        std::vector<ValueId> pass{loadFrom(envSlot, loc)};
        if (arg != kNoValue) {
            pass.push_back(arg);
        }
        callIndirect(loadFrom(codeSlot, loc), pass, tt.voidType(), loc);
    }

    // A channel slot back as the element type it was sent as -- the inverse of `asWord`.
    ValueId fromWord(ValueId word, const std::string& elem, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        // §21: A VALUE VARIANT CROSSED AS A BOX -- see `asWord` -- so it comes back through the
        // pointer and the block is released here. The awaiter is the only thing that ever holds
        // this address, which is what makes freeing it at the read safe rather than a guess.
        if (const Type* asValue = valueVariantType(elem); asValue != nullptr) {
            Inst back;
            back.op = Op::AddrToPtr;
            back.type = tt.ptrType();
            back.operands.push_back(word);
            back.loc = loc;
            const ValueId box = emit(std::move(back));
            Inst read;
            read.op = Op::Load;
            read.type = asValue;
            read.operands.push_back(box);
            read.loc = loc;
            const ValueId got = emit(std::move(read));
            callExternal("__polaron_free", tt.voidType(), {tt.ptrType()}, {box}, loc);
            noteName(got, elem);
            return got;
        }
        const Type* want = baseTypeOf(elem);
        if (want == nullptr) {
            return word;
        }
        if (want->kind == TypeKind::Ptr) {
            Inst back;
            back.op = Op::AddrToPtr;
            back.type = tt.ptrType();
            back.operands.push_back(word);
            back.loc = loc;
            const ValueId obj = emit(std::move(back));
            noteName(obj, elem);
            return obj;
        }
        if (want->kind == TypeKind::Float) {
            Inst bits;
            bits.op = Op::Bitcast;
            bits.type = tt.floatType(64);
            bits.operands.push_back(word);
            bits.loc = loc;
            const ValueId d = emit(std::move(bits));
            return want->bits == 64 ? d : lowerConversion(d, tt.floatType(64), want, loc);
        }
        return want->kind == TypeKind::Int && want->bits < 64 ? narrow(word, want->bits, loc)
                                                              : word;
    }

    ValueId callClosure(ValueId closure, const ast::CallExpr& c) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        Inst codeAddr;
        codeAddr.op = Op::Gep;
        codeAddr.type = ptr;
        codeAddr.operands.push_back(closure);
        codeAddr.imm = 0;
        codeAddr.loc = c.loc;
        const ValueId codeSlot = emit(std::move(codeAddr));
        slotType_[codeSlot] = ptr;
        const ValueId code = loadFrom(codeSlot, c.loc);

        Inst envAddr;
        envAddr.op = Op::Gep;
        envAddr.type = ptr;
        envAddr.operands.push_back(closure);
        envAddr.imm = 8;
        envAddr.loc = c.loc;
        const ValueId envSlot = emit(std::move(envAddr));
        slotType_[envSlot] = ptr;
        const ValueId env = loadFrom(envSlot, c.loc);

        // THE RETURN TYPE IS IN THE FUNCTION TYPE. `function<R, P...>` names its result FIRST, and
        // this used to assume `int` for every closure call -- so `function<int,int> dbl =
        // makeDoubler();` stored a pointer into a four-byte slot, and calling `dbl` afterwards
        // turned that truncated half of an address back into a pointer.
        const std::string written = declaredName(closure);
        const Type* result = returnOfFunctionType(written);
        Inst call;
        call.op = Op::CallIndirect;
        call.type = result != nullptr ? result : tt.intType(32);
        call.operands.push_back(code);
        call.operands.push_back(env);
        for (const auto& a : c.args) {
            const ValueId v = lowerExpr(a.get());
            if (v != kNoValue) {
                call.operands.push_back(v);
            }
        }
        call.loc = c.loc;
        // INSIDE A `try`, A CLOSURE CALL UNWINDS LIKE ANY OTHER.
        //
        // Nothing here knows what the closure will reach, so the safe answer is that it may throw --
        // and `Test.assertDoesNotThrow(action)` is a method whose ENTIRE PURPOSE is calling one
        // inside a `try`. Emitted as a plain `call.indirect` the handler had no edge into it, the
        // landing block became an orphan, and the backend built its funclet blocks with nothing to
        // terminate them: "Basic Block in function 'Test.assertDoesNotThrow' does not have
        // terminator!", and with it the whole module.
        //
        // The direct-call path a few hundred lines below reasons this out for itself and says so at
        // length; this one is the same rule and did not have it.
        ValueId out;
        if (!handlers_.empty()) {
            call.op = Op::CallUnwind;
            const BlockId normal = fn_->addBlock(fresh("resumed"));
            call.edges.push_back(Edge{normal, {}});
            call.edges.push_back(Edge{handlers_.back().landing, {}});
            out = emit(std::move(call));
            here_ = normal;
        } else {
            out = emit(std::move(call));
        }
        noteName(out, firstTypeArgOf(written));
        return out;
    }

    // The FIRST type argument of a `function<...>` -- its result. `function<int, int>` is
    // `(int) -> int` and `function<function<int,int>>` is `() -> function<int,int>`, so the split
    // has to count angle brackets: cutting at the first comma turns the second one into nonsense.
    static std::string firstTypeArgOf(const std::string& name) {
        const size_t open = name.find('<');
        if (open == std::string::npos || name.empty() || name.back() != '>') {
            return std::string();
        }
        int depth = 0;
        for (size_t i = open + 1; i + 1 < name.size(); ++i) {
            const char ch = name[i];
            if (ch == '<') {
                ++depth;
            } else if (ch == '>') {
                --depth;
            } else if (ch == ',' && depth == 0) {
                return trimmed(name.substr(open + 1, i - open - 1));
            }
        }
        return trimmed(name.substr(open + 1, name.size() - open - 2));
    }

    static std::string trimmed(std::string s) {
        while (!s.empty() && (s.front() == ' ' || s.front() == '\t')) {
            s.erase(s.begin());
        }
        while (!s.empty() && (s.back() == ' ' || s.back() == '\t')) {
            s.pop_back();
        }
        return s;
    }

    const Type* returnOfFunctionType(const std::string& name) {
        if (name.rfind("function<", 0) != 0 && name.rfind("funcptr<", 0) != 0) {
            return nullptr;
        }
        const std::string r = firstTypeArgOf(name);
        return r.empty() || r == "void" ? nullptr : storageTypeOf(r);
    }

    // `try? expr` (spec 5.4): evaluate a `Result`, and if it is the error case RETURN IT from the
    // enclosing method unchanged; otherwise carry on with the value inside the `Ok`. It was not
    // lowered at all, so `int v = try? parse(n);` produced nothing and the method returned zero.
    //
    // The test is the same one a `match` makes -- compare the object's table against `Ok`'s -- which
    // is why this could not be written before the tables existed.
    ValueId lowerTryExpr(const ast::TryExpr& t) {
        const ValueId result = lowerExpr(t.operand.get());
        if (result == kNoValue) {
            gap("TryExpr(operand did not lower)", t.loc);
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;
        const std::string subject = classNameOf(declaredName(result));
        // `Ok` for a `Result$int$int` is `Ok$int$int`: the instantiation travels with the case, the
        // same suffix rule a `match` arm follows.
        // AN `Option`'s SUCCESS SIDE IS `Some`, NOT `Ok` (§21.2). Both spellings reach `try?` --
        // the whole point is that it propagates either -- and this asked for `Ok` on both, so an
        // Option compared against a table that does not exist for it: `try?` on a `Some` took the
        // propagate branch and returned the Option where its payload was expected.
        const std::string good = subject.rfind("Option", 0) == 0 ? "Some" : "Ok";
        // §21: ON A VALUE VARIANT THE TEST IS THE TAG. There is no table and no object: reading a
        // vtable pointer out of one loads the first eight bytes of `{ tag, payload }` and compares
        // them against a table's address, which is an access violation on the first `try?` that
        // succeeds. The two halves are otherwise identical -- propagate on the error side, unwrap
        // on the other -- so only the test and the unwrap differ.
        if (isVariantValue(result)) {
            Inst tag;
            tag.op = Op::VariantTag;
            tag.type = tt.intType(32);
            tag.operands.push_back(result);
            tag.loc = t.loc;
            const ValueId isGood =
                cmp(Op::CmpEq, emit(std::move(tag)), constInt(0, 32, t.loc), t.loc);

            const BlockId open = fn_->addBlock(fresh("tryok"));
            const BlockId out = fn_->addBlock(fresh("tryerr"));
            Inst go;
            go.op = Op::BrCond;
            go.operands.push_back(isGood);
            go.edges.push_back(Edge{open, {}});
            go.edges.push_back(Edge{out, {}});
            go.loc = t.loc;
            emit(std::move(go));

            here_ = out;
            Inst back;
            back.op = Op::Ret;
            back.operands.push_back(result);
            back.loc = t.loc;
            emit(std::move(back));

            here_ = open;
            // WHAT THE PAYLOAD IS, from the success case's `value` field -- the same question the
            // boxed path answers by reading that field's declared type.
            const Type* want = tt.intType(32);
            std::string okName = good;
            if (const size_t dollar = subject.find('$'); dollar != std::string::npos) {
                okName = good + subject.substr(dollar);
            }
            if (auto held = fieldTypeName_.find(okName + ".value"); held != fieldTypeName_.end()) {
                want = held->second.pointerDepth > 0 ? tt.ptrType()
                                                     : storageTypeOf(classNameOf(held->second.name));
            }
            Inst pl;
            pl.op = Op::VariantPayload;
            pl.type = want;
            pl.operands.push_back(result);
            pl.loc = t.loc;
            return emit(std::move(pl));
        }
        std::string okClass = good;
        if (const size_t dollar = subject.find('$');
            dollar != std::string::npos && hasVtable_.count(good + subject.substr(dollar)) != 0) {
            okClass = good + subject.substr(dollar);
        }
        if (hasVtable_.count(okClass) == 0) {
            gap("TryExpr(no table for " + okClass + ")", t.loc);
            return kNoValue;
        }

        Inst want;
        want.op = Op::ConstFn;
        want.type = tt.ptrType();
        want.text = okClass + ".vtable";
        want.loc = t.loc;
        const ValueId table = emit(std::move(want));

        Inst got;
        got.op = Op::Load;
        got.type = tt.ptrType();
        got.operands.push_back(result);
        got.loc = t.loc;
        const ValueId mine = emit(std::move(got));

        Inst cmp;
        cmp.op = Op::CmpEq;
        cmp.type = tt.boolType();
        cmp.operands.push_back(mine);
        cmp.operands.push_back(table);
        cmp.loc = t.loc;
        const ValueId isOk = emit(std::move(cmp));

        const BlockId unwrap = fn_->addBlock(fresh("tryok"));
        const BlockId bail = fn_->addBlock(fresh("tryerr"));
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(isOk);
        br.edges.push_back(Edge{unwrap, {}});
        br.edges.push_back(Edge{bail, {}});
        br.loc = t.loc;
        emit(std::move(br));

        // THE ERROR PATH RETURNS THE RESULT UNCHANGED -- that is what `try?` propagates, and it is
        // why the enclosing method's return type has to be a `Result` too.
        here_ = bail;
        Inst ret;
        ret.op = Op::Ret;
        ret.operands.push_back(result);
        ret.loc = t.loc;
        emit(std::move(ret));

        here_ = unwrap;
        const Type* okShape = named_.count(okClass) != 0 ? named_[okClass] : nullptr;
        if (okShape == nullptr || okShape->kind != TypeKind::Struct) {
            gap("TryExpr(no layout for " + okClass + ")", t.loc);
            return kNoValue;
        }
        size_t at = 0;
        while (at < okShape->fields.size() && okShape->fields[at].name == "__vtable") {
            ++at;
        }
        if (at >= okShape->fields.size()) {
            gap("TryExpr(" + okClass + " carries no value)", t.loc);
            return kNoValue;
        }
        Inst g;
        g.op = Op::Gep;
        g.type = tt.ptrType();
        g.operands.push_back(result);
        g.imm = static_cast<int64_t>(at);
        g.aggregate = okShape;
        g.text = okShape->fields[at].name;
        g.loc = t.loc;
        const ValueId addr = emit(std::move(g));
        slotType_[addr] = okShape->fields[at].type;
        return loadFrom(addr, t.loc);
    }

    // The deferred blocks, INNERMOST FIRST -- the order the language specifies and the order a
    // reader expects: the last thing set up is the first thing taken down. Emitted at a `return`
    // and at the end of the body; the unwinding edge is not covered yet, which is a real gap and is
    // recorded as one rather than described as done.
    void runDeferred(SourceLocation loc, size_t downTo = 0) {
        for (size_t i = deferred_.size(); i > downTo; --i) {
            runOneDefer(deferred_[i - 1], /*guarded=*/false, loc);
        }
    }

    // One `defer` body, optionally behind its "already ran" flag. Guarded is what the unwinding
    // path uses: the block it belongs to may have been left normally before the exception reached
    // this far, in which case the deferred work is done and doing it again is a second `close()`.
    void runOneDefer(const DeferSite& site, bool guarded, SourceLocation loc) {
        if (site.body == nullptr) {
            return;
        }
        BlockId after = kNoBlock;
        if (guarded && site.ran != kNoValue) {
            const BlockId run = fn_->addBlock(fresh("defer.run"));
            after = fn_->addBlock(fresh("defer.done"));
            Inst already;
            already.op = Op::CmpEq;
            already.type = out_.module.types.boolType();
            already.operands.push_back(loadFrom(site.ran, loc));
            already.operands.push_back(constInt(0, 32, loc));
            already.loc = loc;
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(emit(std::move(already)));
            br.edges.push_back(Edge{run, {}});
            br.edges.push_back(Edge{after, {}});
            br.loc = loc;
            emit(std::move(br));
            here_ = run;
        }
        // §32.10: `defer within <duration>` TIMES THE CLEANUP and alerts if it overran. The clock
        // is read either side of the body; nothing is killed, because a scope exit that may itself
        // be an unwind has to finish.
        TypeTable& tt = out_.module.types;
        const ValueId startedAt =
            site.budgetMs == kNoValue
                ? kNoValue
                : callExternal("__polaron_now_ns", tt.intType(64), {}, {}, loc);
        for (const auto& inner : site.body->statements) {
            lowerStmt(inner.get());
        }
        if (startedAt != kNoValue && !blockClosed()) {
            Inst span;
            span.op = Op::SubWrap;
            span.type = tt.intType(64);
            span.operands.push_back(
                callExternal("__polaron_now_ns", tt.intType(64), {}, {}, loc));
            span.operands.push_back(startedAt);
            span.loc = loc;
            Inst toMs;
            toMs.op = Op::DivChecked;
            toMs.type = tt.intType(64);
            toMs.operands.push_back(emit(std::move(span)));
            toMs.operands.push_back(constLong(1000000, loc));
            toMs.loc = loc;
            const ValueId tookMs = emit(std::move(toMs));
            const BlockId over = fn_->addBlock(fresh("defer.over"));
            const BlockId fine = fn_->addBlock(fresh("defer.ok"));
            Inst tooLong;
            tooLong.op = Op::CmpGtS;
            tooLong.type = tt.boolType();
            tooLong.operands.push_back(tookMs);
            tooLong.operands.push_back(site.budgetMs);
            tooLong.loc = loc;
            Inst pick;
            pick.op = Op::BrCond;
            pick.operands.push_back(emit(std::move(tooLong)));
            pick.edges.push_back(Edge{over, {}});
            pick.edges.push_back(Edge{fine, {}});
            pick.loc = loc;
            emit(std::move(pick));
            here_ = over;
            callExternal("__polaron_defer_overrun", tt.voidType(),
                         {tt.intType(64), tt.intType(64)}, {site.budgetMs, tookMs}, loc);
            gotoIfOpen(fine);
            here_ = fine;
        }
        if (site.ran != kNoValue && !blockClosed()) {
            Inst mark;
            mark.op = Op::Store;
            mark.operands.push_back(constInt(1, 32, loc));
            mark.operands.push_back(site.ran);
            mark.loc = loc;
            emit(std::move(mark));
        }
        if (after != kNoBlock) {
            gotoIfOpen(after);
            here_ = after;
        }
    }

    // A BLOCK'S OWN `defer`s RUN WHEN THE BLOCK ENDS, not when the method does. Running them all at
    // the return put a loop's cleanup after the loop -- `block_raii` printed `body 0 / body 1 / end
    // / defer 2` where the program prints `body 0 / defer 0 / body 1 / defer 1 / end`, which is the
    // whole point of the keyword: the cleanup is beside the thing it cleans up.
    void lowerScope(const ast::Block& body) {
        const size_t outerDefers = deferred_.size();
        const size_t outerObjects = scoped_.size();
        // THE OPEN SCOPES, AS A STACK. A `goto` LEAVES every scope between here and the one the
        // label sits in, and each of those has to be torn down -- so the jump needs to know how
        // deep the label is, which is a property of the block that contains it.
        const size_t depth = blockScopes_.size();
        blockScopes_.push_back({&body, outerObjects, outerDefers});
        for (const auto& inner : body.statements) {
            lowerStmt(inner.get());
        }
        // BACK TO THE DEPTH THIS SCOPE FOUND, not one fewer. Lowering a nested BODY -- a generated
        // accessor, an async resume -- rescans labels and clears the stack, so a bare `pop_back`
        // could be popping an empty vector.
        if (blockScopes_.size() > depth) {
            blockScopes_.resize(depth);
        }
        if (!blockClosed()) {
            // §21: THE STRINGS THIS BLOCK BUILT GO BACK AT ITS CLOSING BRACE.
            //
            // Temporaries are released at the top of the NEXT statement, and a statement inside a
            // block whose next statement is OUTSIDE it never gets one: `releaseStringTemps` matches
            // on the block a temporary was born in, and by then the builder stands somewhere else.
            // `printf("caught: %s", e.message())` as the last line of a `catch` leaked its String on
            // every pass -- and so did the last line of every `if`, every loop body, every arm.
            releaseStringTemps(body.loc);
            runDeferred(body.loc, outerDefers);
            destroyScoped(outerObjects, body.loc);
        }
        deferred_.resize(outerDefers);
        // SHRINK ONLY. A `delete` inside the scope may already have taken an object off the list,
        // so restoring to the remembered depth would GROW it with default-constructed entries and
        // the next teardown would run a destructor on a null slot of no class.
        if (scoped_.size() > outerObjects) {
            scoped_.resize(outerObjects);
        }
    }

    // RAII: A STACK OBJECT IS DESTROYED WHEN ITS SCOPE ENDS, in reverse order of construction --
    // the default `new T()` is a frame slot and its destructor is the language's guarantee, not the
    // programmer's chore. Nothing was emitting it, so `class_dtor` printed `ctor / hello` and never
    // `dtor`, and every RAII sample was short by exactly the lines that prove the feature works.
    void destroyScoped(size_t downTo, SourceLocation loc) {
        // CLAMPED, because the list can SHRINK under a recorded depth: an explicit `delete` takes
        // its object off the list, so an enclosing scope that remembered "there were three" finds
        // two. `begin() + three` on a vector of two is not an iterator, and the compiler died on
        // it -- every program, because the prelude deletes.
        if (downTo >= scoped_.size()) {
            return;
        }
        destroyEach(std::vector<ScopedObject>(scoped_.begin() + static_cast<long>(downTo),
                                              scoped_.end()),
                    loc);
    }

    // THE SAME TEARDOWN, over a list that is not the live stack. An unwinding path leaves the same
    // block the closing brace does, and it needs the same objects destroyed in the same order --
    // but by the time it is emitted the live stack has already been unwound by the normal path.
    // Both spellings own a buffer: `String` is the immutable one and `string` the mutable, and they
    // differ in what may be done to the value, not in who releases it.
    static bool isStringNamed(const std::string& declared) {
        return declared == "String" || declared == "string";
    }

    bool isStringTemp(ValueId v) const {
        for (const auto& [value, born] : stringTemps_) {
            if (value == v) {
                return true;
            }
        }
        return false;
    }

    // A NAME TAKES OWNERSHIP OF THE STRING IT WAS GIVEN, so it stops being a temporary. Without
    // this the value would be released at the end of its own declaration and the name would hold a
    // dangling pointer -- not a leak but a use-after-free, which is strictly worse.
    void claimString(ValueId v) {
        for (size_t i = stringTemps_.size(); i > 0; --i) {
            if (stringTemps_[i - 1].first == v) {
                stringTemps_.erase(stringTemps_.begin() + static_cast<long>(i - 1));
                return;
            }
        }
    }

    // A String about to be stored somewhere that outlives this expression. A fresh one is claimed;
    // anything else is copied, because a literal is a STATIC String object and releasing a constant
    // is not a leak, it is corruption.
    ValueId ownedString(ValueId v, SourceLocation loc) {
        if (v == kNoValue) {
            return v;
        }
        if (isStringTemp(v)) {
            claimString(v);
            return v;
        }
        TypeTable& tt = out_.module.types;
        const std::string was = declaredName(v);
        const ValueId owned =
            callExternal("__polaron_str_copy", tt.ptrType(), {tt.ptrType()}, {v}, loc);
        noteName(owned, isStringNamed(was) ? was : std::string("String"));
        return owned;
    }

    // The temporaries built by the statement that has just ended, in reverse -- and only the ones
    // made in the block the builder stands in, because a temp built inside one arm of a branch is
    // not live in the other.
    void releaseStringTemps(SourceLocation loc) {
        if (stringTemps_.empty() || blockClosed()) {
            return;
        }
        TypeTable& tt = out_.module.types;
        std::vector<std::pair<ValueId, BlockId>> kept;
        std::vector<ValueId> release;
        for (const auto& [value, born] : stringTemps_) {
            if (born == here_) {
                release.push_back(value);
            } else {
                kept.emplace_back(value, born);
            }
        }
        stringTemps_ = std::move(kept);
        for (size_t i = release.size(); i > 0; --i) {
            callExternal("__polaron_str_free", tt.voidType(), {tt.ptrType()}, {release[i - 1]}, loc);
        }
    }

    // §17.7: WHAT A REGION GIVES BACK, and in which order. Its objects' destructors first when it
    // keeps a registry -- freeing the block alone reclaims the memory and skips every destructor in
    // it -- then the block itself.
    //
    // One method, called from `release region R` and from the scope end alike, because those two
    // are the same act at different moments. Written twice they would drift, and the way that drift
    // shows is a `growable` region freed with one call where its chain needed another: memory that
    // is neither leaked nor freed, but handed back in pieces the allocator does not recognise.
    void releaseRegionBlock(const std::string& name, ValueId block, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        if (regionShapeOf(name).registry()) {
            callExternal("__polaron_region_teardown", tt.voidType(), {tt.ptrType()}, {block}, loc);
        } else if (regionShapeOf(name).flavor == "ring") {
            // A RING KEEPS NO REGISTRY and needs none: every entry is the one type its `.accepts`
            // names, so one destructor covers all of them and the runtime knows which entries are
            // still live. `region_ring` released three live objects and destroyed none of them.
            callExternal("__polaron_ring_teardown", tt.voidType(), {tt.ptrType()}, {block}, loc);
        } else if (auto held = regionObjects_.find(name); held != regionObjects_.end()) {
            // A region WITHOUT a registry keeps no list of its own, so the list is the one the
            // compiler can see. Each is null-guarded and nulled after, so an object already
            // `delete`d from the region is passed over.
            destroyEach(held->second, loc);
        }
        // A SUB-REGION DOES NOT GIVE ITS BLOCK BACK, because the block is not its own: it was
        // carved out of the parent, and handing it to the allocator would put a slice of the
        // parent's LIVE memory in the free cache to be handed out again. Releasing it ends its
        // lifetime and runs what it owns; the bytes return when the parent is released, which is
        // the whole point of nesting them.
        if (regionShapeOf(name).isSub()) {
            return;
        }
        // A GROWABLE REGION IS A CHAIN OF BLOCKS, not one. Releasing only the head leaves every
        // block it grew into unreachable and unfreed.
        if (regionShapeOf(name).growable) {
            callExternal("__polaron_region_free_chain", tt.voidType(), {tt.ptrType()}, {block}, loc);
            return;
        }
        // ONE CALL, because a bump region's whole block goes back at once -- that is what the arena
        // buys and why nothing per-object is released. `RegionRelease` reached a backend that did
        // not translate it, so `release region pen` freed nothing and the memory grew until the
        // process was killed.
        callExternal("__polaron_region_release", tt.voidType(), {tt.ptrType()}, {block}, loc);
    }

    // §21: AN OBJECT'S STRING FIELDS GO BACK WHEN THE OBJECT DOES.
    //
    // A String field owns its buffer -- that is what makes storing one a copy -- so destroying the
    // object has to release it, or every object with a String field leaks one buffer per lifetime.
    // The other path emits exactly this, between the destructor and the free.
    //
    // Recorded on the `drop` rather than emitted here because the ORDER matters: the user's
    // destructor may still read the field, and the block must not be freed before the buffer inside
    // it is read. Only the backend is standing between those two.
    void noteStringFields(Inst& drop, const std::string& cls) {
        const Type* shape = named_.count(cls) != 0 ? named_[cls] : nullptr;
        if (shape == nullptr || shape->kind != TypeKind::Struct) {
            return;
        }
        for (size_t i = 0; i < shape->fields.size(); ++i) {
            const auto declared = fieldTypeName_.find(cls + "." + shape->fields[i].name);
            if (declared == fieldTypeName_.end() || declared->second.pointerDepth != 0 ||
                !isStringNamed(declared->second.name)) {
                continue;
            }
            drop.extra.push_back("sfree:" + std::to_string(i));
        }
        if (!drop.extra.empty()) {
            drop.aggregate = shape;
        }
    }

    // The teardown an explicit `delete` emits, for an object a SCOPE owns rather than a statement:
    // run the destructor -- through the table when the object is the one that decides which body
    // -- and release the block. Kept beside `lowerDelete`'s reasoning rather than duplicating it:
    // which slot, and whether the class has anything to dispatch to, are the same two questions.
    void emitScopedDrop(const std::string& cls, ValueId obj, SourceLocation loc) {
        nullifyWeakList(obj, cls, loc);
        Inst drop;
        drop.op = Op::Drop;
        drop.type = fn_->value(obj)->type;
        drop.operands.push_back(obj);
        drop.text = cls;
        const ast::ClassDecl* decl = cls.empty() ? nullptr : findClass(cls);
        const bool reference = decl != nullptr && !decl->isStruct && !decl->isRecord &&
                               !decl->isUnion && !decl->isLayout;
        drop.imm = reference && vtableSlot_.count("~") != 0 && hierarchyHasDestructor(cls)
                       ? vtableSlot_["~"]
                       : -1;
        noteStringFields(drop, cls);
        if (!livesInClassArena(cls)) {
            drop.extra.push_back("heap");
        }
        drop.loc = loc;
        emit(std::move(drop));
    }

    void destroyEach(const std::vector<ScopedObject>& objects, SourceLocation loc) {
        for (size_t i = objects.size(); i > 0; --i) {
            const ScopedObject& it = objects[i - 1];
            // A BLANKED ENTRY HAS ALREADY BEEN RELEASED, by an explicit `release region R` earlier
            // in the method. It stays in the list so nothing else shifts position.
            if (it.cls.empty()) {
                continue;
            }
            // A REGION LOCAL IS RELEASED AT THE CLOSING BRACE. `region pen = itself.allocate(1
            // kilobytes);` with no explicit `release` frees the block when the scope ends -- that is
            // what makes a region an ordinary local rather than a thing to remember. This path
            // emitted nothing at all, so `region_raii` acquired a block and never gave it back: the
            // sample whose comment says `pen freed here by RAII` did no such thing.
            if (it.cls.rfind(kRegionOwner, 0) == 0) {
                const std::string name = it.cls.substr(std::string(kRegionOwner).size());
                if (const ValueId block = loadFrom(it.slot, loc); block != kNoValue) {
                    releaseRegionBlock(name, block, loc);
                }
                continue;
            }
            // A `String` GIVES ITS BUFFER BACK HERE. `__polaron_str_free` IS a String's destructor,
            // so it is the one entry in this list released by name rather than by looking up a
            // class. It lives in this list so a scope holding an object and a string releases both
            // in the reverse of declaration order, whichever kind each one is.
            if (it.cls == kStringOwner) {
                TypeTable& tt = out_.module.types;
                callExternal("__polaron_str_free", tt.voidType(), {tt.ptrType()},
                             {loadFrom(it.slot, loc)}, loc);
                // AND THE SLOT IS EMPTIED, exactly as the object branch below does it and for the
                // same reason: a `try` runs its body's teardown a second time on the way out
                // through the landing block. `__polaron_str_free` is null-safe, so an emptied slot
                // makes the second pass a no-op instead of a double free.
                Inst emptied;
                emptied.op = Op::Store;
                emptied.operands.push_back(nullPointer(loc));
                emptied.operands.push_back(it.slot);
                emptied.loc = loc;
                emit(std::move(emptied));
                continue;
            }
            // HOW THIS CAME TO BE RIGHT, because two attempts at it were wrong and the reason is
            // worth keeping. A String owns its buffer (§21), and releasing every local is safe only
            // because of COPY-ON-STORE -- the language copies at every point a String crosses into
            // something outliving the expression, so no two names ever share one buffer.
            //
            // TWO ATTEMPTS, AND WHAT THEY ESTABLISHED. The rule the other backend follows is not
            // escape analysis -- it is COPY-ON-STORE. Every point where a String crosses into
            // something that outlives the expression makes its own copy, and then freeing every
            // local is always safe. Its copy points, read off `emitStringCopy`'s call sites, are
            // exactly five:
            //
            //   1. a declaration's initialiser          codegen_stmt.cpp
            //   2. an assignment, of any target shape   codegen_stmt.cpp
            //   3. a `return`                           codegen_stmt.cpp
            //   4. each arm of a ternary, when owned    codegen_emit.cpp
            //   5. a String FIELD inside a value-struct copy    -- `deepenFields` here already
            //                                              does this one, and arrays and copyable
            //                                              classes with it
            //
            //   The first attempt had the frees and NO copies: the leak probe went green and
            //   FORTY-SIX samples went red -- `out of memory`, text reading `pp$\<junk>`.
            //   The second added 1, 2 and 3. 648 samples became 662, and thirty-two stayed red.
            //
            // WHY THOSE THIRTY-TWO, found by reading one of them instead of guessing again.
            // `file_lines` reported `n=4 first= last=`: four strings in a list, all empty. They are
            // put there by `out.add(s.substring(start, i))` -- a fresh temporary handed to a
            // collection. Compare the two backends on `ArrayList$String.add`:
            //
            //     the other path      1 call to __polaron_str_copy
            //     this one            0
            //
            // The element store `this.data[this.count] = item` does not copy here. Attempt two
            // thought it had covered that: `lowerAssign` was taught to copy a String into an
            // element or a field. It never ran, because an `IndexExpr` target is handled in its own
            // branch at the TOP of `lowerAssign` and returns from there -- the copy sat in the tail
            // the branch never reaches.
            //
            // So the remaining work is one place, not a search: copy on the element-store path of
            // `lowerAssign`, and on the field-store path beside it. That gap is real TODAY,
            // independent of any of this -- a collection here shares the caller's String rather
            // than copying it -- and it is harmless only for as long as nothing frees.
            //
            // A leak is the least bad of the three states -- sharing without freeing is what this
            // path does today, and it is at least CORRECT -- so it stays until that is done.
            const ast::ClassDecl* decl = findClass(it.cls);
            if (decl == nullptr) {
                continue;
            }
            const std::string dtor = destructorOf(*decl);
            const Function* target = dtor.empty() ? nullptr : resolveKey(dtor);
            // A HEAP ENTRY IS STILL TORN DOWN WHEN IT DECLARES NO DESTRUCTOR, because the storage
            // is the other half of the teardown and it is owed either way. Only a frame entry with
            // no destructor has genuinely nothing to do here.
            if (!it.heap && target == nullptr) {
                continue;
            }
            const ValueId obj = loadFrom(it.slot, loc);
            const Type* held = obj != kNoValue ? fn_->value(obj)->type : nullptr;
            if (held == nullptr || held->kind != TypeKind::Ptr) {
                // A VALUE STRUCT IS ITS BYTES. There is no pointer to test and no way for it not to
                // exist: the local IS the object, so the destructor always has something to run on.
                emitCall(target, {obj}, loc);
                continue;
            }
            // A CONSTRUCTION THAT NEVER RAN HAS NOTHING TO DESTROY, and running the destructor on
            // the slot anyway reads uninitialised memory as if it were an object. `abstainfrom`
            // jumps over the declaration -- the alloca still happens, because allocas live in the
            // entry block, but the `new` does not -- and the scope end still arrives, so the
            // destructor was called on whatever the frame happened to hold. `abstain_raii` prints
            // the difference as `cbd|d!` against `cbd|!`: one `d` for an object that was never
            // built. The slot starts null (see `zeroSlotAtEntry`), so the test is exactly "did the
            // constructor get here", and where it plainly did the optimiser folds the branch away.
            const BlockId live = fn_->addBlock(fresh("dtor.live"));
            const BlockId after = fn_->addBlock(fresh("dtor.done"));
            Inst isNull;
            isNull.op = Op::CmpEq;
            isNull.type = out_.module.types.boolType();
            isNull.operands.push_back(obj);
            isNull.operands.push_back(nullPointer(loc));
            isNull.loc = loc;
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(emit(std::move(isNull)));
            br.edges.push_back(Edge{after, {}});
            br.edges.push_back(Edge{live, {}});
            br.loc = loc;
            emit(std::move(br));

            here_ = live;
            if (it.heap) {
                // THE SCOPE OWNS THE STORAGE TOO, so this is a `delete` and not a destructor call:
                // the same drop an explicit `delete` emits, dispatched through the table when the
                // object decides which destructor runs, and releasing the block afterwards. The
                // null guard above is what makes it safe on a path where the object was never
                // built -- and on the second pass a `try` makes over its own body's teardown.
                emitScopedDrop(it.cls, obj, loc);
            } else {
                emitCall(target, {obj}, loc);
            }
            // AND THE SLOT IS EMPTIED, so a second teardown of the same scope does nothing. There
            // is one: a `try` runs its body's teardown again on the way out through its landing
            // block, because an exception leaves the block too -- and an inner scope that had
            // already finished normally would otherwise have its destructor run twice.
            Inst emptied;
            emptied.op = Op::Store;
            emptied.operands.push_back(nullPointer(loc));
            emptied.operands.push_back(it.slot);
            emptied.loc = loc;
            emit(std::move(emptied));
            Inst go;
            go.op = Op::Br;
            go.edges.push_back(Edge{after, {}});
            go.loc = loc;
            emit(std::move(go));
            here_ = after;
        }
    }

    // THE SLOT OF A SCOPED OBJECT STARTS EMPTY. Written into the ENTRY block, right beside the
    // alloca, because that is the one place control cannot jump over: a declaration in the middle
    // of a method can be skipped by `abstainfrom` or a `goto`, and then the only thing standing
    // between the scope end and a destructor call on garbage is this store.
    void zeroSlotAtEntry(ValueId slot, SourceLocation loc) {
        Block* entry = fn_ != nullptr ? fn_->block(entryBlock_) : nullptr;
        if (entry == nullptr || slot == kNoValue) {
            return;
        }
        const Type* ptr = out_.module.types.ptrType();
        Inst z;
        z.op = Op::ConstNull;
        z.type = ptr;
        z.loc = loc;
        const ValueId empty =
            fn_->addValue(ptr, ValueOrigin::Instruction, entryBlock_, allocaAt_, "");
        z.result = empty;
        entry->insts.insert(entry->insts.begin() + static_cast<long>(allocaAt_), std::move(z));
        ++allocaAt_;
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(empty);
        st.operands.push_back(slot);
        st.loc = loc;
        entry->insts.insert(entry->insts.begin() + static_cast<long>(allocaAt_), std::move(st));
        ++allocaAt_;
        // Same renumbering `declareLocal` does, for the same reason: rule 1 checks that a value's
        // recorded position in its block is where the instruction actually sits.
        for (size_t i = 0; i < entry->insts.size(); ++i) {
            const ValueId r = entry->insts[i].result;
            if (r != kNoValue && r < fn_->values.size()) {
                fn_->values[r].indexInBlock = static_cast<uint32_t>(i);
            }
        }
    }

    // The counter's global name. Per method and label: two methods may each have a `label a`, and
    // abstaining from one must not silence the other.
    std::string abstainKey(const std::string& label) const {
        return "abstain." + (fn_ != nullptr ? fn_->key : std::string()) + "." + label;
    }

    // The counter itself: an internal 64-bit global, zero-initialised. `globalSlot` would declare
    // it EXTERNAL -- a name for the linker to find elsewhere -- and there is no elsewhere.
    ValueId abstainCounter(const std::string& label, SourceLocation loc) {
        // NOT CACHED, deliberately. The address is a constant, so emitting it again costs one
        // instruction the folder removes -- and reusing the first one means a value defined inside
        // one branch is used from another that it does not dominate, which verifier rule 1 refuses
        // and is right to.
        const std::string name = abstainKey(label);
        bool have = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                have = true;
                break;
            }
        }
        if (!have) {
            Global g;
            g.name = name;
            g.type = out_.module.types.intType(64);
            g.linkage = Linkage::Internal;
            g.zeroInit = true;
            out_.module.globals.push_back(std::move(g));
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = name;
        addr.loc = loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = out_.module.types.intType(64);
        return slot;
    }

    // WHICH LABELS ARE ABSTAINED FROM, AND WHAT FOLLOWS EACH -- both read off the body BEFORE it is
    // lowered, because `abstainfrom a;` may appear before `label a;` and the guard has to be at the
    // label either way.
    void scanLabels(const ast::Block& body) {
        std::string previous;
        walkLabels(body, previous);
        labelBlock_.clear();
        blockScopes_.clear();
        comefromNames_.clear();
        comefromBlock_.clear();
        comefromOwner_.clear();
        scanLabelBlocks(body);
    }

    // The teardown a `goto` owes: everything declared inside the scopes it is leaving, down to the
    // one the label itself sits in. Nothing at all when the label is in this same scope, which is
    // the ordinary backward jump and must not destroy anything.
    void gotoScopeCleanup(const std::string& label, SourceLocation loc) {
        auto owner = labelBlock_.find(label);
        if (owner == labelBlock_.end()) {
            return;
        }
        leaveScopesFor(owner->second, loc);
    }

    // Tear down every scope between here and the one `target` sits in. Nothing when the target is
    // in this same scope, which is the ordinary backward jump and must destroy nothing.
    void leaveScopesFor(const ast::Block* target, SourceLocation loc) {
        if (target == nullptr) {
            return;
        }
        int at = -1;
        for (int i = static_cast<int>(blockScopes_.size()) - 1; i >= 0; --i) {
            if (blockScopes_[i].block == target) {
                at = i;
                break;
            }
        }
        if (at < 0 || at + 1 >= static_cast<int>(blockScopes_.size())) {
            return;   // the same scope, or a label in a scope that is not open here
        }
        const OpenScope& inner = blockScopes_[static_cast<size_t>(at) + 1];
        runDeferred(loc, std::min(inner.defers, deferred_.size()));
        destroyScoped(std::min(inner.objects, scoped_.size()), loc);
    }

    // The block a `comefrom` lands in, made on first mention -- by the LABEL when the comefrom is
    // written later (the forward steal) and by the comefrom itself otherwise.
    BlockId comefromBlockFor(const std::string& name) {
        auto it = comefromBlock_.find(name);
        if (it != comefromBlock_.end()) {
            return it->second;
        }
        const BlockId made = fn_->addBlock(fresh("comefrom"));
        comefromBlock_[name] = made;
        return made;
    }

    // WHICH BLOCK EACH LABEL SITS IN, scanned before anything is lowered -- a forward `goto` names
    // a label the walk has not reached yet, and the jump has to know its depth to leave the right
    // number of scopes.
    void scanLabelBlocks(const ast::Block& body) {
        for (const auto& s : body.statements) {
            const ast::Stmt* st = s.get();
            if (const auto* lm = dynamic_cast<const ast::LabelMarkStmt*>(st)) {
                labelBlock_[lm->name] = &body;
                continue;
            }
            // WHICH LABELS SOMETHING COMES FROM, before anything is lowered: the label may be
            // written above the `comefrom` that steals it, and it has to know at the moment it is
            // reached.
            if (const auto* cf = dynamic_cast<const ast::ComefromStmt*>(st)) {
                comefromNames_.insert(cf->name);
                // ...and WHICH BLOCK it lands in, because the steal leaves every scope between the
                // label and there -- the same obligation a `goto` has and for the same reason.
                comefromOwner_[cf->name] = &body;
                continue;
            }
            if (const auto* ls = dynamic_cast<const ast::LabeledStmt*>(st)) {
                labelBlock_[ls->label] = &body;
            }
            if (const auto* b = dynamic_cast<const ast::Block*>(st)) { scanLabelBlocks(*b); continue; }
            if (const auto* i = dynamic_cast<const ast::IfStmt*>(st)) {
                scanLabelBlocks(i->thenBlock);
                if (i->elseBlock != nullptr) { scanLabelBlocks(*i->elseBlock); }
                continue;
            }
            if (const auto* w = dynamic_cast<const ast::WhileStmt*>(st)) { scanLabelBlocks(w->body); continue; }
            if (const auto* d = dynamic_cast<const ast::DoWhileStmt*>(st)) { scanLabelBlocks(d->body); continue; }
            if (const auto* f = dynamic_cast<const ast::ForStmt*>(st)) { scanLabelBlocks(f->body); continue; }
            if (const auto* f = dynamic_cast<const ast::ForeachStmt*>(st)) { scanLabelBlocks(f->body); continue; }
            if (const auto* y = dynamic_cast<const ast::SynchronizedStmt*>(st)) { scanLabelBlocks(y->body); continue; }
            if (const auto* u = dynamic_cast<const ast::UsingStmt*>(st)) { scanLabelBlocks(u->body); continue; }
            if (const auto* t = dynamic_cast<const ast::TryStmt*>(st)) {
                scanLabelBlocks(t->body);
                for (const auto& c : t->catches) { scanLabelBlocks(c.body); }
                if (t->finallyBlock != nullptr) { scanLabelBlocks(*t->finallyBlock); }
                continue;
            }
            if (const auto* sw = dynamic_cast<const ast::SwitchStmt*>(st)) {
                for (const auto& c : sw->cases) { scanLabelBlocks(c.body); }
                if (sw->defaultBody != nullptr) { scanLabelBlocks(*sw->defaultBody); }
            }
        }
    }

    void walkLabels(const ast::Block& body, std::string& previous) {
        for (const auto& s : body.statements) {
            const ast::Stmt* st = s.get();
            if (auto* lm = dynamic_cast<const ast::LabelMarkStmt*>(st)) {
                if (!previous.empty()) {
                    nextLabel_[previous] = lm->name;
                }
                previous = lm->name;
                continue;
            }
            if (auto* ab = dynamic_cast<const ast::AbstainfromStmt*>(st)) {
                if (!ab->isReinstate) {
                    abstained_.insert(ab->name);
                }
                continue;
            }
            if (auto* i = dynamic_cast<const ast::IfStmt*>(st)) {
                walkLabels(i->thenBlock, previous);
                if (i->elseBlock != nullptr) {
                    walkLabels(*i->elseBlock, previous);
                }
                continue;
            }
            if (auto* b = dynamic_cast<const ast::Block*>(st)) {
                walkLabels(*b, previous);
            }
        }
    }

    // While the counter is non-zero, jump past the region this label opens -- to the next label if
    // there is one, and otherwise to the end of the method.
    void guardAbstainedLabel(const std::string& label, SourceLocation loc) {
        const ValueId counter = abstainCounter(label, loc);
        // READ IT ATOMICALLY, for the same reason it is written that way: the counter is global, so
        // the reader and the writer need not be the same thread and need not even be the same
        // activation of the same method. A plain load beside an `atomicrmw` is half a guarantee.
        Inst read;
        read.op = Op::AtomicLoad;
        read.type = out_.module.types.intType(64);
        read.operands.push_back(counter);
        read.loc = loc;
        Inst zero;
        zero.op = Op::CmpEq;
        zero.type = out_.module.types.boolType();
        zero.operands.push_back(emit(std::move(read)));
        zero.operands.push_back(constInt(0, 64, loc));
        zero.loc = loc;
        const BlockId body = fn_->addBlock(fresh("labelon"));
        const BlockId skip = fn_->addBlock(fresh("labeloff"));
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(zero)));
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{skip, {}});
        br.loc = loc;
        emit(std::move(br));

        here_ = skip;
        if (const std::string next = nextLabel_[label]; !next.empty()) {
            gotoIfOpen(blockForLabel(next));
        } else {
            Inst r;
            r.op = Op::Ret;
            r.loc = loc;
            emit(std::move(r));   // no next label: the region runs to the end of the method
        }
        here_ = body;
    }

    // The block a label names, created on FIRST MENTION -- which may be the `goto` rather than the
    // label, when the jump goes forward.
    BlockId blockForLabel(const std::string& name) {
        auto it = labels_.find(name);
        if (it != labels_.end()) {
            return it->second;
        }
        const BlockId made = fn_->addBlock(name);
        labels_[name] = made;
        return made;
    }

    // The pending label, consumed: a loop claims it once, so a loop NESTED inside the labelled one
    // does not also answer to the name.
    std::string takeLoopLabel() {
        std::string got = std::move(pendingLoopLabel_);
        pendingLoopLabel_.clear();
        return got;
    }

    // Which loop a `break`/`continue` leaves: the one wearing the label, or the innermost when the
    // statement carries none.
    const LoopTargets* loopFor(const std::string& label) const {
        if (loops_.empty()) {
            return nullptr;
        }
        if (label.empty()) {
            return &loops_.back();
        }
        for (auto it = loops_.rbegin(); it != loops_.rend(); ++it) {
            if (it->label == label) {
                return &*it;
            }
        }
        return &loops_.back();   // an unknown label is the analyzer's to refuse, not this pass's
    }

    // `a ?? b`: the value inside `a` when it is present, `b` when it is not. A `nullable T` is a
    // BOXED value -- a pointer, null when absent -- so the test is a null check and the unwrap is a
    // load. Not lowered at all before, so `y ?? 99` produced nothing and `z` read its own frame.
    ValueId lowerNullCoalesce(const ast::NullCoalesceExpr& n) {
        TypeTable& tt = out_.module.types;
        const ValueId boxed = lowerExpr(n.lhs.get());
        if (boxed == kNoValue) {
            return lowerExpr(n.rhs.get());
        }
        const BlockId present = fn_->addBlock(fresh("some"));
        const BlockId absent = fn_->addBlock(fresh("none"));
        const BlockId join = fn_->addBlock(fresh("coalesce"));

        Inst isNull;
        isNull.op = Op::CmpEq;
        isNull.type = tt.boolType();
        isNull.operands.push_back(boxed);
        isNull.operands.push_back(nullPointer(n.loc));
        isNull.loc = n.loc;
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(isNull)));
        br.edges.push_back(Edge{absent, {}});
        br.edges.push_back(Edge{present, {}});
        br.loc = n.loc;
        emit(std::move(br));

        // The DEFAULT decides the result type: it is the unwrapped one, and the box has no type of
        // its own that says what is inside.
        here_ = absent;
        const ValueId fallback = lowerExpr(n.rhs.get());
        const Type* result = fallback != kNoValue ? fn_->value(fallback)->type : tt.intType(32);
        const ValueId out = fn_->addValue(result, ValueOrigin::BlockParam, join, 0, "");
        fn_->block(join)->params.push_back(out);
        Inst goAbsent;
        goAbsent.op = Op::Br;
        Edge fromAbsent{join, {}};
        fromAbsent.args.push_back(fallback != kNoValue ? fallback : undefOf(result, n.loc));
        goAbsent.edges.push_back(fromAbsent);
        goAbsent.loc = n.loc;
        emit(std::move(goAbsent));

        here_ = present;
        // ONLY A PRIMITIVE IS BOXED. `nullable Dog*` is a pointer that may be null -- the absence
        // is the null pointer itself, with nothing wrapped around it -- so unwrapping it loaded the
        // object's first word and used THAT as the object. `nullable int` really is a box, and the
        // load is right for it; the difference is what the value's declared type says.
        const std::string inside = classNameOf(declaredName(boxed));
        const bool boxedValue =
            result != nullptr && result->kind != TypeKind::Ptr && findClass(inside) == nullptr;
        ValueId unwrapped = boxed;
        if (boxedValue) {
            Inst unbox;
            unbox.op = Op::Load;
            unbox.type = result;
            unbox.operands.push_back(boxed);
            unbox.loc = n.loc;
            unwrapped = emit(std::move(unbox));
        }
        Inst goPresent;
        goPresent.op = Op::Br;
        Edge fromPresent{join, {}};
        fromPresent.args.push_back(unwrapped);
        goPresent.edges.push_back(fromPresent);
        goPresent.loc = n.loc;
        emit(std::move(goPresent));

        here_ = join;
        return out;
    }

    // ---- regions ----
    //
    // `region pen = itself.allocate(1 kilobytes);` was not lowered at all: the whole expression fell
    // through to the gap list and the region variable held nothing, so `new Dog(3) in region pen`
    // bumped a cursor inside an uninitialised block. Five samples in the census died there.
    //
    // A PLAIN BUMP REGION IS A BLOCK WITH A THREE-WORD HEADER: `used` at 0, `capacity` at 8, and
    // where the data begins at 16 -- the same lean layout the trusted path writes, because both
    // paths hand the block to the same `__polaron_region_release`. The flavoured regions (pool,
    // fixedslot, ring, growable) carry a 448-byte descriptor the runtime lays out, and are a gap
    // here rather than a guess.
    const RegionShape& regionShapeOf(const std::string& name) const {
        static const RegionShape bump;
        auto it = regionShape_.find(bareRegionName(name));
        return it != regionShape_.end() ? it->second : bump;
    }

    // `this.nodes` AND `nodes` NAME THE SAME REGION. A region may be a field, and the source writes
    // it either way; every question about a region is asked by name, so the two spellings have to
    // arrive as one.
    static std::string bareRegionName(const std::string& name) {
        const size_t dot = name.rfind('.');
        return dot == std::string::npos ? name : name.substr(dot + 1);
    }

    // THE BLOCK a region name refers to: a local's slot, or a field of `this`. Reading only locals
    // meant a region FIELD -- which is how the standard library's containers hold theirs -- was
    // never found, and `new LinkedNode<T>() in region this.nodes` produced no object at all.
    ValueId regionBlockFor(const std::string& name, SourceLocation loc) {
        if (auto local = locals_.find(name); local != locals_.end()) {
            return loadFrom(local->second, loc);
        }
        // `Class.field`: A STATIC REGION FIELD, whose storage is the class's own global -- one arena
        // for the whole program, with an owner's name on it. The qualifier is READ here rather than
        // dropped: `new X in region Other.arena` with the qualifier discarded addresses a
        // same-named field of whatever class the caller happens to be in, which is a different
        // region and no diagnostic. Declarable and not usable was the state this was in.
        if (const size_t dot = name.rfind('.');
            dot != std::string::npos && name.compare(0, dot, "this") != 0) {
            if (const ValueId shared = staticRegionSlot(name.substr(0, dot), name.substr(dot + 1),
                                                        loc);
                shared != kNoValue) {
                return loadFrom(shared, loc);
            }
        }
        const std::string field = bareRegionName(name);
        if (auto local = locals_.find(field); local != locals_.end()) {
            return loadFrom(local->second, loc);
        }
        const ValueId self = selfLoad(loc);
        if (self == kNoValue) {
            return kNoValue;
        }
        const ValueId at = fieldAddress(self, field, loc);
        if (at == kNoValue) {
            return kNoValue;
        }
        slotType_[at] = out_.module.types.ptrType();
        return loadFrom(at, loc);
    }

    // A STATIC REGION FIELD (`public static mutable pool region shared`), BUILT ON FIRST USE. The
    // global is null until something asks for the region and nothing else would ever fill it, so
    // before this the field parsed, type-checked and then faulted on the first allocation.
    //
    // Lazily, and not from a static constructor, for the same reason a region class's arena is:
    // bare metal runs none. The flavour and size match that arena too -- it is the other region in
    // the language with no lexical owner -- so a shared arena chains another block instead of
    // trapping when its first one fills. Returns kNoValue when the name is not one of these, which
    // is how the ordinary local-and-field lookup goes on being tried.
    ValueId staticRegionSlot(const std::string& owner, const std::string& field,
                             SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const std::string key = owner + "." + field;
        const Global* declared = nullptr;
        for (const Global& g : out_.module.globals) {
            if (g.name == key) {
                declared = &g;
                break;
            }
        }
        if (declared == nullptr) {
            return kNoValue;
        }
        const ast::ClassDecl* decl = findClass(owner);
        if (decl == nullptr) {
            return kNoValue;
        }
        bool isRegion = false;
        for (const auto& m : decl->members) {
            const auto* f = dynamic_cast<const ast::FieldDecl*>(m.get());
            if (f != nullptr && f->name == field && f->isStatic && f->type.name == "region") {
                isRegion = true;
                break;
            }
        }
        if (!isRegion) {
            return kNoValue;
        }

        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = tt.ptrType();
        addr.text = key;
        addr.loc = loc;
        const ValueId slot = emit(std::move(addr));
        slotType_[slot] = tt.ptrType();

        const ValueId cur = loadFrom(slot, loc);
        Inst absent;
        absent.op = Op::CmpEq;
        absent.type = tt.boolType();
        absent.operands.push_back(cur);
        absent.operands.push_back(nullPointer(loc));
        absent.loc = loc;
        const ValueId isNull = emit(std::move(absent));

        const BlockId init = fn_->addBlock(fresh("srgn.init"));
        const BlockId ready = fn_->addBlock(fresh("srgn.ready"));
        Inst pick;
        pick.op = Op::BrCond;
        pick.operands.push_back(isNull);
        pick.edges.push_back(Edge{init, {}});
        pick.edges.push_back(Edge{ready, {}});
        pick.loc = loc;
        emit(std::move(pick));

        here_ = init;
        const int64_t cap = 64 * 1024;
        const ValueId block =
            callExternal("__polaron_region_acquire", tt.ptrType(), {tt.intType(64)},
                         {constLong(cap + kFlavouredRegionHeader, loc)}, loc);
        callExternal("__polaron_region_init", tt.voidType(),
                     {tt.ptrType(), tt.intType(64), tt.intType(64), tt.intType(64)},
                     {block, constLong(flavorCode("pool"), loc), constLong(cap, loc),
                      constLong(1, loc)},
                     loc);
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(block);
        put.operands.push_back(slot);
        put.loc = loc;
        emit(std::move(put));
        gotoIfOpen(ready);

        here_ = ready;
        return slot;
    }

    static constexpr int64_t kRegionHeader = 24;
    // The FLAVOURED header: the runtime's `PolaronRegionDesc`, whose first three fields mirror the
    // lean one so an inline cursor reads them unchanged. MUST match POLARON_REGION_HDR in
    // runtime/polaron_region_core.hpp -- a mismatch puts every object in the region at the wrong
    // offset and the runtime's own free-lists somewhere inside the user's data.
    static constexpr int64_t kFlavouredRegionHeader = 448;

    // The flavour word as the runtime's descriptor records it.
    static int64_t flavorCode(const std::string& flavor) {
        if (flavor == "pool") {
            return 1;
        }
        if (flavor == "stack") {
            return 2;
        }
        if (flavor == "fixedslot") {
            return 3;
        }
        if (flavor == "ring") {
            return 4;
        }
        return 0;   // bump
    }

    ValueId lowerRegionInit(const ast::RegionInitExpr& r) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        // `itself.atMultiple({...})` (§17.4) HAS NO BLOCK. It is a region over memory somebody else
        // owns, several fixed ranges of it, each constrained by type -- so there is nothing to
        // acquire and nothing to release, and the whole of it is the per-range cursors recorded by
        // the declaration. `regionAlloc` routes there instead of coming here.
        if (!r.ranges.empty()) {
            return kNoValue;
        }
        // `1 kilobytes` IS A `ByteSize`, not a number: the suffix builds an object whose `bytes`
        // field holds the count. Treating the object as an integer asked the allocator for a
        // pointer's worth of bytes. A plain `1024` is still a number, so both spellings work.
        ValueId bytes = constInt(0, 64, r.loc);
        if (r.size != nullptr) {
            const ValueId given = lowerExpr(r.size.get());
            const Type* holder = given != kNoValue ? ownerOf(given) : nullptr;
            bool fromField = false;
            if (holder != nullptr && holder->kind == TypeKind::Struct) {
                for (const Field& f : holder->fields) {
                    if (f.name == "bytes") {
                        bytes = widenToLong(loadFrom(fieldAddress(given, "bytes", r.loc), r.loc),
                                            r.loc);
                        fromField = true;
                        break;
                    }
                }
            }
            if (!fromField) {
                bytes = widenToLong(given, r.loc);
            }
        }

        // A SUB-REGION TAKES ITS BLOCK FROM ITS PARENT (§17). Everything else about it is
        // identical -- the same header, the same init, the same allocation for objects inside it --
        // so the only difference is where the bytes come from, which is exactly what `in region
        // outer` says. That buys a per-phase arena inside a per-world one at no second allocation,
        // and releasing the world reclaims every arena in it at once.
        auto takeBlock = [&](ValueId total) -> ValueId {
            if (r.inRegion.empty()) {
                return callExternal("__polaron_region_acquire", ptr, {i64}, {total}, r.loc);
            }
            const ValueId parent = regionBlockFor(r.inRegion, r.loc);
            if (parent == kNoValue) {
                gap("RegionInitExpr(parent region not in scope: " + r.inRegion + ")", r.loc);
                return kNoValue;
            }
            return regionAllocBytes(parent, total, r.loc, r.inRegion);
        };

        ValueId block = kNoValue;
        ValueId dataBase = kNoValue;
        if (r.atAddress != nullptr) {
            // `itself.at(addr, size)`: the DATA belongs to somebody else and only the header is
            // ours, so the block is a bare 24 bytes and the data base is the address given.
            block = callExternal("__polaron_malloc", ptr, {i64}, {constInt(24, 64, r.loc)}, r.loc);
            Inst toPtr;
            toPtr.op = Op::AddrToPtr;
            toPtr.type = ptr;
            toPtr.operands.push_back(widenToLong(lowerExpr(r.atAddress.get()), r.loc));
            toPtr.loc = r.loc;
            dataBase = emit(std::move(toPtr));
        } else if (pendingRegion_.descriptor()) {
            // A FLAVOURED OR GROWABLE REGION CARRIES THE RUNTIME'S DESCRIPTOR: free-lists, the
            // destructor registry, the grow chain. It is 448 bytes and the runtime lays it out --
            // and its first three fields ARE the lean header, so the inline cursor still reads
            // them the same way. Built by hand as 24 bytes, a `stack` region had nowhere to record
            // what it had allocated, so `rollback` destroyed nothing and every `pool` bumped past
            // the end of its own reservation.
            block = takeBlock(addLong(bytes, kFlavouredRegionHeader, r.loc));
            if (block == kNoValue) {
                return kNoValue;
            }
            callExternal("__polaron_region_init", tt.voidType(), {ptr, i64, i64, i64},
                         {block, constLong(flavorCode(pendingRegion_.flavor), r.loc), bytes,
                          constLong(pendingRegion_.growable ? 1 : 0, r.loc)},
                         r.loc);
            return block;
        } else {
            block = takeBlock(addLong(bytes, kRegionHeader, r.loc));
            if (block == kNoValue) {
                return kNoValue;
            }
            dataBase = rawOffset(block, constInt(kRegionHeader, 64, r.loc), r.loc);
        }
        storeAt(block, 0, constInt(0, 64, r.loc), r.loc);    // used
        storeAt(block, 8, bytes, r.loc);                     // capacity
        storeAt(block, 16, dataBase, r.loc);                 // where the data begins
        return block;
    }

    // `itself.atMultiple({ a0 accepts {Dog}, a1 accepts {Cat} })` (§17.4): a region over SEVERAL
    // fixed address ranges, each constrained by type. There is no block and nothing to release --
    // the memory belongs to whoever gave the addresses -- so all a declaration leaves behind is one
    // bump cursor per range, and `new T in region r` picks the range at COMPILE time from the type.
    //
    // The ranges and their cursors travel together because they are one thing. Two containers keyed
    // by the region's name, one holding the clauses and one the cursors, is this record with the
    // name of its type left off, and the two would be free to disagree about how many ranges there
    // are -- which is the one fact every routing decision reads.
    struct MultiRange {
        const std::vector<ast::RegionInitExpr::Range>* ranges = nullptr;
        std::vector<ValueId> cursors;   // one frame slot per range, holding its `used` count
    };

    void declareMultiRange(const std::string& name,
                           const std::vector<ast::RegionInitExpr::Range>& ranges,
                           SourceLocation loc) {
        MultiRange made;
        made.ranges = &ranges;
        for (size_t i = 0; i < ranges.size(); ++i) {
            const ValueId cursor =
                allocaFor(name + "#used" + std::to_string(i), out_.module.types.intType(64));
            zeroSlotAtEntry(cursor, loc);
            made.cursors.push_back(cursor);
        }
        multiRegions_[name] = std::move(made);
    }

    // Whether `cls` IS a `want`, by the declaration chain: the type itself, anything it extends, or
    // any interface it or an ancestor implements. Compile-time and by name, which is all a range
    // constraint needs -- §17.4 routes at compile time and there is no object yet to ask.
    bool classIsSubtypeOf(const std::string& cls, const std::string& want) const {
        if (cls == want) {
            return true;
        }
        std::string at = cls;
        for (int hops = 0; hops < 64 && !at.empty(); ++hops) {
            const ast::ClassDecl* decl = findClass(at);
            if (decl == nullptr) {
                return false;
            }
            for (const std::string& i : decl->interfaces) {
                if (classNameOf(i) == want) {
                    return true;
                }
            }
            at = classNameOf(decl->superclass);
            if (at == want) {
                return true;
            }
        }
        return false;
    }

    // Which range takes a `T`, or -1 when none does. An `accepts` list is a whitelist and anything
    // else is open unless `rejects` names the type -- both by subtype, so a range that accepts a
    // base class takes everything under it.
    int rangeFor(const MultiRange& region, const std::string& cls) const {
        for (size_t i = 0; i < region.ranges->size(); ++i) {
            const ast::RegionInitExpr::Range& r = (*region.ranges)[i];
            bool ok = true;
            if (!r.accepts.empty()) {
                ok = false;
                for (const std::string& a : r.accepts) {
                    if (classIsSubtypeOf(cls, classNameOf(a))) {
                        ok = true;
                        break;
                    }
                }
            } else {
                for (const std::string& rj : r.rejects) {
                    if (classIsSubtypeOf(cls, classNameOf(rj))) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) {
                return static_cast<int>(i);
            }
        }
        return -1;
    }

    // Bump-allocate at the matching range's fixed address, using that range's own cursor.
    ValueId multiRangeAlloc(const std::string& named, const std::string& cls, const Type* shape,
                            SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const MultiRange& region = multiRegions_.at(named);
        const int idx = rangeFor(region, cls);
        if (idx < 0) {
            gap("NewExpr(no range in region " + named + " accepts a '" + cls + "')", loc);
            return kNoValue;
        }
        const ValueId base = widenToLong(lowerExpr((*region.ranges)[idx].address.get()), loc);
        const ValueId cursor = region.cursors[static_cast<size_t>(idx)];
        const ValueId used = loadFrom(cursor, loc);
        Inst at;
        at.op = Op::AddWrap;
        at.type = tt.intType(64);
        at.operands.push_back(base);
        at.operands.push_back(used);
        at.loc = loc;
        const ValueId objAddr = emit(std::move(at));

        Inst grow;
        grow.op = Op::AddWrap;
        grow.type = tt.intType(64);
        grow.operands.push_back(used);
        grow.operands.push_back(alignUpTo8(sizeOfClass(shape, loc), loc));
        grow.loc = loc;
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(emit(std::move(grow)));
        put.operands.push_back(cursor);
        put.loc = loc;
        emit(std::move(put));

        Inst toPtr;
        toPtr.op = Op::AddrToPtr;
        toPtr.type = tt.ptrType();
        toPtr.operands.push_back(objAddr);
        toPtr.loc = loc;
        return emit(std::move(toPtr));
    }

    // ---- SIMD (§34.6) ----
    //
    // Every one of these is short because the TYPE carries the lane count. That is the whole return
    // on making `Vector` a kind: there is no pattern to recognise, no struct to take apart, and the
    // element-wise operations need no code here at all -- `fadd` over two vector-typed values IS
    // the element-wise add, and the backend translates it as one instruction.

    // A lane, as a float. `v.x`, `v[i]`, and every element read inside `multiply`/`transform`.
    ValueId laneOf(ValueId vec, ValueId index, SourceLocation loc) {
        Inst at;
        at.op = Op::VecExtract;
        at.type = out_.module.types.floatType(32);
        at.operands.push_back(vec);
        at.operands.push_back(index);
        at.loc = loc;
        return emit(std::move(at));
    }

    ValueId laneOf(ValueId vec, int64_t index, SourceLocation loc) {
        return laneOf(vec, constInt(index, 32, loc), loc);
    }

    // The same vector with one lane replaced. A vector is a VALUE, so this yields a new one rather
    // than writing through -- `v.y = 20.0` is a build-and-store, which is what keeps a lane write
    // from needing the vector to have an address at all.
    ValueId withLane(ValueId vec, ValueId index, ValueId lane, SourceLocation loc) {
        Inst set;
        set.op = Op::VecInsert;
        set.type = fn_->value(vec)->type;
        set.operands.push_back(vec);
        set.operands.push_back(asFloat32(lane, loc));
        set.operands.push_back(index);
        set.loc = loc;
        return emit(std::move(set));
    }

    ValueId asFloat32(ValueId v, SourceLocation loc) {
        const Type* f32 = out_.module.types.floatType(32);
        const Type* got = v != kNoValue ? fn_->value(v)->type : nullptr;
        return got != nullptr && got != f32 ? lowerConversion(v, got, f32, loc) : v;
    }

    // N lanes from N values -- or from ONE, which broadcasts it across every lane. That second form
    // is what `v * 2.0` needs, and giving it the same opcode keeps the splat from being a separate
    // thing that means the same.
    ValueId buildVector(const Type* vt, std::vector<ValueId> lanes, SourceLocation loc) {
        Inst make;
        make.op = Op::VecBuild;
        make.type = vt;
        for (ValueId l : lanes) {
            make.operands.push_back(asFloat32(l, loc));
        }
        make.loc = loc;
        return emit(std::move(make));
    }

    ValueId zeroVector(const Type* vt, SourceLocation loc) {
        Inst zero;
        zero.op = Op::ConstFloat;
        zero.type = out_.module.types.floatType(32);
        zero.fimm = 0.0;
        zero.loc = loc;
        return buildVector(vt, {emit(std::move(zero))}, loc);
    }

    static bool isVector(const Type* t) { return t != nullptr && t->kind == TypeKind::Vector; }

    // Whether an expression's value is a vector, WITHOUT lowering it. Asked where the answer decides
    // which path an expression takes, and a path decision may not evaluate its subject twice: `v.x`
    // has to know before it starts whether `v` is a vector or an object with a field called `x`.
    bool isVectorExpr(const ast::Expr* e) {
        if (e == nullptr) {
            return false;
        }
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            if (auto it = locals_.find(id->name); it != locals_.end()) {
                if (auto held = slotType_.find(it->second); held != slotType_.end()) {
                    return isVector(held->second);
                }
            }
            return false;
        }
        // A call whose callee is a vector's own name or one of its products. These are the two
        // spellings a lane read can sit directly on -- `vec4(...).x` and `m.transform(p).y`.
        if (const auto* call = dynamic_cast<const ast::CallExpr*>(e)) {
            if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(call->callee.get())) {
                return vectorLanes(id->name) != 0;
            }
            if (const auto* mem = dynamic_cast<const ast::MemberExpr*>(call->callee.get())) {
                return mem->member == "transform" || mem->member == "multiply" ||
                       mem->member == "identity";
            }
        }
        return false;
    }

    // Lane-by-lane product of two vectors of the same width.
    ValueId fmulVec(ValueId a, ValueId b, SourceLocation loc) {
        Inst mul;
        mul.op = Op::FMul;
        mul.type = fn_->value(a)->type;
        mul.operands.push_back(a);
        mul.operands.push_back(b);
        mul.loc = loc;
        return emit(std::move(mul));
    }

    // Every lane of a vector added together, as a scalar. What `dot` and `length` both end in.
    ValueId horizontalAdd(ValueId v, int64_t lanes, SourceLocation loc) {
        ValueId sum = laneOf(v, static_cast<int64_t>(0), loc);
        for (int64_t i = 1; i < lanes; ++i) {
            Inst add;
            add.op = Op::FAdd;
            add.type = out_.module.types.floatType(32);
            add.operands.push_back(sum);
            add.operands.push_back(laneOf(v, i, loc));
            add.loc = loc;
            sum = emit(std::move(add));
        }
        return sum;
    }

    // The 3D cross product, written out: three differences of products, one per lane.
    ValueId cross3(ValueId a, ValueId b, const Type* vt, SourceLocation loc) {
        auto term = [&](int64_t i, int64_t j) {
            Inst mul;
            mul.op = Op::FMul;
            mul.type = out_.module.types.floatType(32);
            mul.operands.push_back(laneOf(a, i, loc));
            mul.operands.push_back(laneOf(b, j, loc));
            mul.loc = loc;
            return emit(std::move(mul));
        };
        auto lane = [&](int64_t i, int64_t j, int64_t k, int64_t l) {
            Inst sub;
            sub.op = Op::FSub;
            sub.type = out_.module.types.floatType(32);
            sub.operands.push_back(term(i, j));
            sub.operands.push_back(term(k, l));
            sub.loc = loc;
            return emit(std::move(sub));
        };
        const ValueId x = lane(1, 2, 2, 1);
        const ValueId y = lane(2, 0, 0, 2);
        const ValueId z = lane(0, 1, 1, 0);
        const ValueId made = buildVector(vt, {x, y, z}, loc);
        noteName(made, "vec3");
        return made;
    }

    const Type* mat4Type() {
        return out_.module.types.vectorType(out_.module.types.floatType(32), 16);
    }

    // 1.0 down the diagonal, which in row-major sixteen is every fifth lane.
    ValueId mat4Identity(SourceLocation loc) {
        Inst one;
        one.op = Op::ConstFloat;
        one.type = out_.module.types.floatType(32);
        one.fimm = 1.0;
        one.loc = loc;
        const ValueId unit = emit(std::move(one));
        ValueId m = zeroVector(mat4Type(), loc);
        for (int64_t i = 0; i < 4; ++i) {
            m = withLane(m, constInt(i * 5, 32, loc), unit, loc);
        }
        noteName(m, "mat4");
        return m;
    }

    // Row-major matrix product, written out. Sixteen dot products of four terms.
    ValueId mat4Multiply(ValueId a, ValueId b, SourceLocation loc) {
        ValueId r = zeroVector(mat4Type(), loc);
        for (int64_t i = 0; i < 4; ++i) {
            for (int64_t j = 0; j < 4; ++j) {
                ValueId sum = kNoValue;
                for (int64_t k = 0; k < 4; ++k) {
                    Inst mul;
                    mul.op = Op::FMul;
                    mul.type = out_.module.types.floatType(32);
                    mul.operands.push_back(laneOf(a, i * 4 + k, loc));
                    mul.operands.push_back(laneOf(b, k * 4 + j, loc));
                    mul.loc = loc;
                    const ValueId term = emit(std::move(mul));
                    if (sum == kNoValue) {
                        sum = term;
                        continue;
                    }
                    Inst add;
                    add.op = Op::FAdd;
                    add.type = out_.module.types.floatType(32);
                    add.operands.push_back(sum);
                    add.operands.push_back(term);
                    add.loc = loc;
                    sum = emit(std::move(add));
                }
                r = withLane(r, constInt(i * 4 + j, 32, loc), sum, loc);
            }
        }
        return r;
    }

    // m * v: each lane of the answer is one row of the matrix dotted with the vector.
    ValueId mat4Transform(ValueId m, ValueId v, SourceLocation loc) {
        const Type* vec4 = out_.module.types.vectorType(out_.module.types.floatType(32), 4);
        ValueId r = zeroVector(vec4, loc);
        for (int64_t i = 0; i < 4; ++i) {
            ValueId sum = kNoValue;
            for (int64_t k = 0; k < 4; ++k) {
                Inst mul;
                mul.op = Op::FMul;
                mul.type = out_.module.types.floatType(32);
                mul.operands.push_back(laneOf(m, i * 4 + k, loc));
                mul.operands.push_back(laneOf(v, k, loc));
                mul.loc = loc;
                const ValueId term = emit(std::move(mul));
                if (sum == kNoValue) {
                    sum = term;
                    continue;
                }
                Inst add;
                add.op = Op::FAdd;
                add.type = out_.module.types.floatType(32);
                add.operands.push_back(sum);
                add.operands.push_back(term);
                add.loc = loc;
                sum = emit(std::move(add));
            }
            r = withLane(r, constInt(i, 32, loc), sum, loc);
        }
        return r;
    }

    // `new T in region R`: bump the region's cursor by the object's size and hand back the slot.
    // No per-object header -- that is what a region buys, and it is why the cursor lives in the
    // block rather than beside each object.
    ValueId regionAlloc(ValueId region, const Type* shape, SourceLocation loc,
                        const std::string& named = std::string()) {
        return regionAllocBytes(region, sizeOfClass(shape, loc), loc, named);
    }

    // THE SAME BUMP, ASKED FOR IN BYTES. A sub-region's block comes out of its parent, and a block
    // is a byte count and not a class -- but it must travel the SAME path every `new T in region R`
    // travels, because only a flavoured region's block is one `__polaron_region_new` understands.
    // Calling the runtime on a plain bump parent reads the wrong header fields and hands back a
    // pointer overlapping live objects.
    ValueId regionAllocBytes(ValueId region, ValueId size, SourceLocation loc,
                             const std::string& named = std::string()) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);

        // A FLAVOURED REGION ALLOCATES THROUGH ITS RUNTIME. `pool` and `fixedslot` keep free-lists
        // and hand back a reused slot; `ring` overwrites its oldest entry; a `growable` one chains
        // a new block when it fills. None of that is an inline cursor bump, and bumping one anyway
        // walked straight past the end of the reservation.
        const RegionShape& shaped = regionShapeOf(named);
        if (shaped.flavor == "ring") {
            return callExternal("__polaron_ring_new", tt.ptrType(), {tt.ptrType(), i64},
                                {region, size}, loc);
        }
        // ...AND A `stack` REGION TOO, even though its allocation IS a bump. Its slots carry the
        // sixteen-byte header the destructor registry identifies them by -- `rollback` compares
        // `ptr - 16` against the mark -- so bumping the cursor inline here produced objects the
        // registry could not place: the release teardown found nothing older than the mark to
        // destroy and the counter came back one short.
        // `runtimeAlloc`, not `descriptor`: a plain bump FIELD region carries the descriptor so its
        // registry has somewhere to live, and still bumps its objects inline. See the two predicates.
        if (shaped.runtimeAlloc()) {
            return callExternal("__polaron_region_new", tt.ptrType(), {tt.ptrType(), i64},
                                {region, size}, loc);
        }

        Inst usedAddr;
        usedAddr.op = Op::Gep;
        usedAddr.type = tt.ptrType();
        usedAddr.operands.push_back(region);
        usedAddr.imm = 0;
        usedAddr.loc = loc;
        const ValueId cursor = emit(std::move(usedAddr));
        slotType_[cursor] = i64;
        const ValueId used = loadFrom(cursor, loc);

        Inst baseLoad;
        baseLoad.op = Op::Gep;
        baseLoad.type = tt.ptrType();
        baseLoad.operands.push_back(region);
        baseLoad.imm = 16;
        baseLoad.loc = loc;
        const ValueId baseAddr = emit(std::move(baseLoad));
        slotType_[baseAddr] = tt.ptrType();
        const ValueId dataBase = loadFrom(baseAddr, loc);

        const ValueId slot = rawOffset(dataBase, used, loc);
        // ALIGNED TO EIGHT, because the next object after an odd-sized one must still land on a
        // boundary its fields can be read from.
        Inst grow;
        grow.op = Op::AddWrap;
        grow.type = i64;
        grow.operands.push_back(used);
        grow.operands.push_back(alignUpTo8(size, loc));
        grow.loc = loc;
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(emit(std::move(grow)));
        put.operands.push_back(cursor);
        put.loc = loc;
        emit(std::move(put));
        return slot;
    }

    ValueId alignUpTo8(ValueId n, SourceLocation loc) {
        Inst up;
        up.op = Op::AddWrap;
        up.type = out_.module.types.intType(64);
        up.operands.push_back(n);
        up.operands.push_back(constInt(7, 64, loc));
        up.loc = loc;
        Inst mask;
        mask.op = Op::And;
        mask.type = out_.module.types.intType(64);
        mask.operands.push_back(emit(std::move(up)));
        mask.operands.push_back(constInt(-8, 64, loc));
        mask.loc = loc;
        return emit(std::move(mask));
    }

    // ---- `switch` and `match` ----
    //
    // NEITHER OF THESE WAS LOWERED AT ALL. `MatchStmt`, `MatchExpr` and `SwitchStmt` fell through to
    // the "unhandled statement" gap, so a program whose whole shape is a `match` compiled to a body
    // that did nothing and returned -- and since the gap is recorded rather than fatal, it linked
    // and ran and printed whatever the uninitialised result slot held. These are not corner
    // constructs: a `sealed enum` exists to be matched, and matching is how the language spells
    // what other languages spell with a chain of casts.
    //
    // A `switch` is a chain of equality tests. Written as a chain rather than as `Op::Switch`
    // because a case value need not be an integer -- `switch` over a `String` compares content --
    // and one shape that always works beats two that each work sometimes.
    void lowerSwitch(const ast::SwitchStmt& s) {
        const ValueId subject = lowerExpr(s.subject.get());
        if (subject == kNoValue) {
            gap("SwitchStmt(subject did not lower)", s.loc);
            return;
        }
        const BlockId done = fn_->addBlock(fresh("switchend"));
        // `break` inside a case leaves the switch, which is the same target `done` serves.
        loops_.push_back(LoopTargets{done, done, std::string(), scoped_.size(), deferred_.size()});

        // A CASE THAT DOES NOT `break` FALLS INTO THE NEXT (§7.3), and that is why the tests and
        // the bodies are emitted as two passes rather than one. Interleaved, each body's only exit
        // was the end of the switch -- so `case 0` without a `break` printed `zero` and left,
        // where the language says it goes on to print `one` as well. The tests come first, as a
        // chain; then the bodies, in source order, each falling into its successor.
        std::vector<BlockId> bodies;
        std::vector<const ast::SwitchCase*> taken;
        for (const ast::SwitchCase& c : s.cases) {
            const ValueId want = lowerExpr(c.value.get());
            if (want == kNoValue) {
                continue;
            }
            const ValueId same = compareEqual(subject, want, c.loc);
            const BlockId body = fn_->addBlock(fresh("case"));
            const BlockId next = fn_->addBlock(fresh("nextcase"));
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(same);
            br.edges.push_back(Edge{body, {}});
            br.edges.push_back(Edge{next, {}});
            br.loc = c.loc;
            emit(std::move(br));
            bodies.push_back(body);
            taken.push_back(&c);
            here_ = next;
        }
        // Nothing matched: the default if there is one, and the end otherwise. The default's block
        // is made up front so a case falling off the last one can reach it, which is what falling
        // through the last case means.
        const BlockId fallback =
            s.defaultBody != nullptr ? fn_->addBlock(fresh("switchdefault")) : done;
        gotoIfOpen(fallback);
        for (size_t i = 0; i < bodies.size(); ++i) {
            here_ = bodies[i];
            lowerScope(taken[i]->body);
            gotoIfOpen(i + 1 < bodies.size() ? bodies[i + 1] : fallback);
        }
        if (s.defaultBody != nullptr) {
            here_ = fallback;
            lowerScope(*s.defaultBody);
            gotoIfOpen(done);
        }
        loops_.pop_back();
        here_ = done;
    }

    // Equality that knows what it is comparing: a `String` by CONTENT, everything else by value.
    // The same rule `==` follows, in one place, so `switch` over strings cannot drift from it.
    ValueId compareEqual(ValueId a, ValueId b, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const std::string an = classNameOf(declaredName(a));
        const std::string bn = classNameOf(declaredName(b));
        const bool text = (an == "String" || an == "string") || (bn == "String" || bn == "string");
        if (text) {
            const ValueId same = callExternal("__polaron_str_eq", tt.intType(32),
                                              {tt.ptrType(), tt.ptrType()}, {a, b}, loc);
            Inst cmp;
            cmp.op = Op::CmpNe;
            cmp.type = tt.boolType();
            cmp.operands.push_back(same);
            cmp.operands.push_back(constInt(0, 32, loc));
            cmp.loc = loc;
            return emit(std::move(cmp));
        }
        Inst cmp;
        cmp.op = Op::CmpEq;
        cmp.type = tt.boolType();
        cmp.operands.push_back(a);
        cmp.operands.push_back(b);
        cmp.loc = loc;
        return emit(std::move(cmp));
    }

    // A `match` ASKS THE OBJECT WHAT IT IS, and the answer is its vtable pointer: two objects of the
    // same class share one table, and no two classes share a table. Comparing that pointer against
    // each case class's table is the whole test -- the same one the trusted path makes, which is
    // why the tables had to exist before this could be written at all.
    //
    // An `enum` subject has no object and no table; it is an ordinal, and the case is a constant.
    void lowerMatch(const ast::MatchStmt& s) {
        const ValueId subject = lowerExpr(s.subject.get());
        if (subject == kNoValue) {
            gap("MatchStmt(subject did not lower)", s.loc);
            return;
        }
        const BlockId done = fn_->addBlock(fresh("matchend"));
        for (const ast::MatchCase& c : s.cases) {
            const ValueId is = caseTest(subject, s.subject.get(), c, s.loc);
            if (is == kNoValue) {
                continue;
            }
            const BlockId body = fn_->addBlock(fresh("arm"));
            const BlockId next = fn_->addBlock(fresh("nextarm"));
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(is);
            br.edges.push_back(Edge{body, {}});
            br.edges.push_back(Edge{next, {}});
            br.loc = c.loc;
            emit(std::move(br));

            here_ = body;
            bindCase(subject, c);
            lowerScope(c.body);
            gotoIfOpen(done);
            here_ = next;
        }
        if (s.defaultBody != nullptr) {
            for (const auto& inner : s.defaultBody->statements) {
                lowerStmt(inner.get());
            }
        }
        gotoIfOpen(done);
        here_ = done;
    }

    // Is `subject` this case? Either its table is the case class's table, or -- for an enum -- its
    // ordinal is the case constant's.
    ValueId caseTest(ValueId subject, const ast::Expr* subjectExpr, const ast::MatchCase& c,
                     SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        // §21: A VALUE VARIANT IS MATCHED BY ITS TAG. There is no object to read a table out of --
        // the subject is two registers -- so the class branch below would load a vtable pointer
        // from the first four bytes of the tag and compare it against a table's address.
        if (isVariantValue(subject)) {
            Inst tag;
            tag.op = Op::VariantTag;
            tag.type = tt.intType(32);
            tag.operands.push_back(subject);
            tag.loc = loc;
            return cmp(Op::CmpEq, emit(std::move(tag)),
                       constInt(c.typeName == "Ok" || c.typeName == "Some" ? 0 : 1, 32, loc), loc);
        }
        const std::string subjectClass = classNameOf(declaredName(subject));
        // A JAVA-STYLE ENUM IS MATCHED BY IDENTITY. Its value is a singleton, not an ordinal, and
        // the class branch below would compare the object's table -- which every constant of the
        // enum shares, so the FIRST arm matched every value. `case Slow -> 0.25` answered 0.25 for
        // `Fast` too, and the arm that should have run never did.
        if (auto decl = enums_.find(subjectClass);
            decl != enums_.end() && decl->second->isJavaStyle) {
            const std::vector<std::string>& consts = decl->second->constants;
            for (size_t i = 0; i < consts.size(); ++i) {
                if (consts[i] == c.typeName) {
                    return cmp(Op::CmpEq, subject, javaEnumSingleton(*decl->second, i, c.loc),
                               c.loc);
                }
            }
        }
        // An enum: the subject is an ordinal and the case names a constant of it.
        if (const Type* t = subjectClass.empty() ? nullptr
                                                 : (named_.count(subjectClass) != 0
                                                        ? named_[subjectClass]
                                                        : nullptr);
            t != nullptr && t->kind == TypeKind::Variant) {
            for (size_t i = 0; i < t->fields.size(); ++i) {
                if (t->fields[i].name == c.typeName) {
                    Inst cmp;
                    cmp.op = Op::CmpEq;
                    cmp.type = tt.boolType();
                    cmp.operands.push_back(subject);
                    cmp.operands.push_back(constInt(static_cast<int64_t>(i), 32, loc));
                    cmp.loc = c.loc;
                    return emit(std::move(cmp));
                }
            }
        }
        // AN ORDINARY ENUM IS MATCHED BY ITS ORDINAL. `sealed enum Quarry permits Caught, ...`
        // interns as an integer, not as a `Variant`, so the branch above never saw it and the arms
        // fell through to comparing vtables on a number: `case Caught` never matched and `worth`
        // answered zero for every outcome.
        if (auto decl = enums_.find(subjectClass);
            decl != enums_.end() && !decl->second->isJavaStyle) {
            const std::vector<std::string>& consts = decl->second->constants;
            for (size_t i = 0; i < consts.size(); ++i) {
                if (consts[i] == c.typeName) {
                    return cmp(Op::CmpEq, subject,
                               constInt(static_cast<int64_t>(i), 32, c.loc), c.loc);
                }
            }
        }
        (void)subjectExpr;
        // A class: compare the tables. The case name may need the subject's instantiation --
        // `case Ok(...)` over a `Result$int` means `Ok$int` -- which is the same suffix rule the
        // trusted path applies, and without it the comparison names a class that does not exist.
        std::string caseClass = c.typeName;
        if (hasVtable_.count(caseClass) == 0) {
            const size_t dollar = subjectClass.find('$');
            if (dollar != std::string::npos &&
                hasVtable_.count(c.typeName + subjectClass.substr(dollar)) != 0) {
                caseClass = c.typeName + subjectClass.substr(dollar);
            }
        }
        if (hasVtable_.count(caseClass) == 0) {
            gap("MatchCase(no table for " + c.typeName + ")", c.loc);
            return kNoValue;
        }
        Inst want;
        want.op = Op::ConstFn;
        want.type = tt.ptrType();
        want.text = caseClass + ".vtable";
        want.loc = c.loc;
        const ValueId table = emit(std::move(want));

        Inst got;
        got.op = Op::Load;
        got.type = tt.ptrType();
        got.operands.push_back(subject);   // the table pointer is field zero
        got.loc = c.loc;
        const ValueId mine = emit(std::move(got));

        Inst cmp;
        cmp.op = Op::CmpEq;
        cmp.type = tt.boolType();
        cmp.operands.push_back(mine);
        cmp.operands.push_back(table);
        cmp.loc = c.loc;
        const ValueId same = emit(std::move(cmp));
        caseClassOf_[&c] = caseClass;
        return same;
    }

    // `case Ok(int v)` binds v to the case class's first own field, and so on positionally.
    void bindCase(ValueId subject, const ast::MatchCase& c) {
        if (c.bindings.empty()) {
            return;
        }
        // §21: A VALUE VARIANT'S PAYLOAD IS ITS SECOND WORD, read back as the binding's declared
        // type. One binding, because one slot: a case that carries more than a single value keeps
        // the boxed form, which is the rule `cgutil::isValueVariant` states.
        if (isVariantValue(subject)) {
            const ast::Param& b = c.bindings.front();
            const Type* want = typeOf(b.type);
            Inst pl;
            pl.op = Op::VariantPayload;
            pl.type = want;
            pl.operands.push_back(subject);
            pl.loc = c.loc;
            const ValueId got = emit(std::move(pl));
            const ValueId slot = allocaFor(b.name, want);
            storeInto(slot, got, c.loc);
            noteName(slot, resolvedTypeName(b.type), pointerDepthOfType(b.type));
            locals_[b.name] = slot;
            return;
        }
        auto it = caseClassOf_.find(&c);
        if (it == caseClassOf_.end()) {
            return;
        }
        const Type* owner = named_.count(it->second) != 0 ? named_[it->second] : nullptr;
        if (owner == nullptr || owner->kind != TypeKind::Struct) {
            return;
        }
        // The FIRST field is the vtable pointer, which is not one of the class's own -- the
        // bindings start after it.
        size_t at = 0;
        while (at < owner->fields.size() && owner->fields[at].name == "__vtable") {
            ++at;
        }
        for (size_t i = 0; i < c.bindings.size() && at + i < owner->fields.size(); ++i) {
            const Field& f = owner->fields[at + i];
            Inst g;
            g.op = Op::Gep;
            g.type = out_.module.types.ptrType();
            g.operands.push_back(subject);
            g.imm = static_cast<int64_t>(at + i);
            g.aggregate = owner;
            g.text = f.name;
            g.loc = c.loc;
            const ValueId addr = emit(std::move(g));
            slotType_[addr] = f.type;
            const ValueId v = loadFrom(addr, c.loc);
            const ValueId slot = allocaFor(c.bindings[i].name, f.type);
            noteName(slot, c.bindings[i].type);
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(v);
            st.operands.push_back(slot);
            st.loc = c.loc;
            emit(std::move(st));
        }
    }

    // The EXPRESSION form: every arm produces a value and the join block takes it as a parameter.
    // That is what §1.2 chose block arguments for -- no phi to keep in step with a predecessor list,
    // and the arms need not know about each other.
    ValueId lowerMatchExpr(const ast::MatchExpr& m) {
        const ValueId subject = lowerExpr(m.subject.get());
        if (subject == kNoValue) {
            gap("MatchExpr(subject did not lower)", m.loc);
            return kNoValue;
        }
        const Type* result = m.resultType.empty() ? out_.module.types.intType(32)
                                                  : baseTypeOf(m.resultType);
        const BlockId join = fn_->addBlock(fresh("matchval"));
        const ValueId out = fn_->addValue(result, ValueOrigin::BlockParam, join, 0, "");
        fn_->block(join)->params.push_back(out);

        auto arrive = [&](ValueId v, SourceLocation loc) {
            Inst go;
            go.op = Op::Br;
            Edge e{join, {}};
            e.args.push_back(v != kNoValue ? lowerConversion(v, fn_->value(v)->type, result, loc)
                                           : undefOf(result, loc));
            go.edges.push_back(e);
            go.loc = loc;
            emit(std::move(go));
        };

        for (const ast::MatchCase& c : m.cases) {
            const ValueId is = caseTest(subject, m.subject.get(), c, m.loc);
            if (is == kNoValue) {
                continue;
            }
            const BlockId body = fn_->addBlock(fresh("armval"));
            const BlockId next = fn_->addBlock(fresh("nextarmval"));
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(is);
            br.edges.push_back(Edge{body, {}});
            br.edges.push_back(Edge{next, {}});
            br.loc = c.loc;
            emit(std::move(br));

            here_ = body;
            bindCase(subject, c);
            if (c.result != nullptr) {
                arrive(lowerExpr(c.result.get()), c.loc);
            } else {
                // The block form (`-> { ... yield x; }`): the arm's statements run and a `yield`
                // inside them is what arrives at the join.
                yields_.push_back(YieldTarget{join, result});
                for (const auto& inner : c.body.statements) {
                    lowerStmt(inner.get());
                }
                yields_.pop_back();
                if (!blockClosed()) {
                    arrive(kNoValue, c.loc);
                }
            }
            here_ = next;
        }
        if (m.defaultResult != nullptr) {
            arrive(lowerExpr(m.defaultResult.get()), m.loc);
        } else if (m.defaultBody != nullptr) {
            yields_.push_back(YieldTarget{join, result});
            for (const auto& inner : m.defaultBody->statements) {
                lowerStmt(inner.get());
            }
            yields_.pop_back();
            if (!blockClosed()) {
                arrive(kNoValue, m.loc);
            }
        } else if (!blockClosed()) {
            // NO DEFAULT means the analyzer proved the cases exhaustive; the edge is unreachable
            // but the block still needs a terminator, and an honest `undef` says which it is.
            arrive(kNoValue, m.loc);
        }
        here_ = join;
        return out;
    }

    // ---- lvalues ----
    //
    // An assignment needs the ADDRESS of its target, not its value, and the three targets are a
    // local, a field of `this`, and a field of something else. Answered once here so `AssignStmt`,
    // `IncDecStmt` and a compound assignment cannot each work it out slightly differently.
    // What an lvalue HOLDS, without lowering it -- the type an `asm` output is written back as.
    const Type* shapeOfLValue(const ast::Expr* e) {
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            if (auto it = locals_.find(id->name); it != locals_.end()) {
                if (auto held = slotType_.find(it->second); held != slotType_.end()) {
                    return held->second;
                }
            }
        }
        return out_.module.types.intType(64);
    }

    ValueId addressOf(const ast::Expr* e) {
        // `*p = v` AND `**pp = v` ARE ASSIGNMENTS TO WHAT THE POINTER NAMES. The address to store
        // into is the pointer's own value -- one dereference fewer than reading through it. This
        // was not an addressable shape at all, so `*slot = target` and `**pp = 99` recorded a gap
        // and did nothing: an out-parameter never came back and a write through two levels was
        // silently dropped.
        if (auto* u = dynamic_cast<const ast::UnaryExpr*>(e); u != nullptr && u->op == "*") {
            const ValueId inner = lowerExpr(u->operand.get());
            if (inner == kNoValue) {
                return kNoValue;
            }
            const std::string written = declaredName(inner);
            const int depth = pointerDepthOf(inner);
            // THE OPERAND'S VALUE IS THE ADDRESS, whatever the depth. `*slot = v` stores AT `slot`;
            // `**pp = v` stores at `*pp`, and the inner star has already been taken by lowering the
            // operand. Stepping again per level of depth wrote one dereference too far -- through
            // `x`'s VALUE as if it were an address.
            // ...AND WHAT IS STORED IS WHAT THE VALUE IS. Recording a held type here would have to
            // agree with the recorded pointer depth, and the depth of a value that has already been
            // dereferenced once is exactly the thing this pass keeps getting wrong: `**pp = 99`
            // wrote `store ptr inttoptr(99)` because the slot claimed to hold a pointer. Leaving it
            // unset lets the store take the value's own shape, which is what `*X = v` means.
            noteName(inner, written, depth > 0 ? depth - 1 : 0);
            return inner;
        }
        if (auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            auto it = locals_.find(id->name);
            if (it != locals_.end()) {
                return it->second;
            }
            return fieldAddress(selfLoad(e->loc), id->name, e->loc);
        }
        if (auto* m = dynamic_cast<const ast::MemberExpr*>(e)) {
            // A STATIC IS NOT A FIELD OF AN OBJECT -- the same rule the READ path applies, and it
            // was missing here. `Test.criterion = ""` walked `Test` as a value, found neither a
            // local nor a field of `this`, and recorded an unresolved name; the assignment then had
            // no address and recorded a second gap for the same line. Both halves of an lvalue have
            // to agree about what a qualified name means.
            //
            // ...AND ONLY WHEN ONE OF THAT NAME WAS DECLARED. See the read path for what this cost.
            std::string qualified;
            if (namesAQualifier(m) && flatten(m, &qualified) && globalExists(qualified)) {
                return globalSlot(qualified, e->loc);
            }
            const ValueId obj = lowerExpr(m->object.get());
            guardReceiver(obj, e->loc);   // §3.7: assigning through a nullable receiver derefs it
            return fieldAddress(obj, m->member, e->loc);
        }
        if (auto* ix = dynamic_cast<const ast::IndexExpr*>(e)) {
            return elementAddress(*ix);
        }
        return kNoValue;
    }

    // §3.7: DEREFERENCING A NULLABLE RECEIVER IS CHECKED.
    //
    // The check is what turns the failure into a diagnostic naming the line, instead of a segfault
    // -- and on a target with no MMU, instead of nothing at all, which is where the no-UB rule
    // stops being a slogan. The other path emits it at every field read, method call and
    // assignment through a nullable receiver; this one emitted it NOWHERE, on any program.
    //
    // ONLY A NULLABLE RECEIVER PAYS. A non-nullable one cannot hold null, so the branch would be
    // arithmetic nothing can reach; and a boxable primitive (`int?`) is not dereferenced at all.
    // `&x` takes an address without reading through it and never arrives here.
    void guardReceiver(ValueId obj, SourceLocation loc) {
        if (obj == kNoValue || fn_ == nullptr) {
            return;
        }
        const std::string declared = declaredName(obj);
        if (!ast::typeIsNullable(declared)) {
            return;
        }
        const Type* held = fn_->value(obj)->type;
        if (held == nullptr || held->kind != TypeKind::Ptr) {
            return;
        }
        if (const Type* bare = baseTypeOf(classNameOf(ast::stripNullable(declared)));
            bare != nullptr && (bare->kind == TypeKind::Int || bare->kind == TypeKind::Float ||
                                bare->kind == TypeKind::Bool)) {
            return;   // a boxed primitive: the access is to the box, not through it
        }
        Inst check;
        check.op = Op::GuardNull;
        check.operands.push_back(obj);
        // WHICH KIND OF NULL FAILURE THIS IS. A broken `cast<T*>` promise and a dereference of
        // something that was declared able to be null are two different diagnostics, and the other
        // path spells them differently; the backend reads this to say the same words.
        check.extra.push_back("dereference");
        check.loc = loc.line > 0 ? loc : stmtLoc_;
        emit(std::move(check));
    }

    ValueId selfLoad(SourceLocation loc) {
        if (selfSlot_ == kNoValue) {
            return kNoValue;
        }
        const ValueId self = loadFrom(selfSlot_, loc);
        if (selfClass_ != nullptr) {
            pointee_[self] = selfClass_;   // `this` points at the enclosing class, and we know which
        }
        return self;
    }

    // The address of a persistent field, or nothing when the name is not one. Two geps: the
    // object's `__persist` slot, then the field's place inside the block it points at.
    ValueId persistentFieldAddress(ValueId object, const Type* owner, const std::string& field,
                                   SourceLocation loc) {
        auto order = persistOrder_.find(owner->name);
        if (order == persistOrder_.end()) {
            return kNoValue;
        }
        int64_t at = -1;
        for (size_t i = 0; i < order->second.size(); ++i) {
            if (order->second[i] == field) {
                at = static_cast<int64_t>(i);
                break;
            }
        }
        if (at < 0) {
            return kNoValue;
        }
        const Type* block = persistBlock_.count(owner->name) != 0 ? persistBlock_[owner->name]
                                                                  : nullptr;
        Inst hold;
        hold.op = Op::Gep;
        hold.type = out_.module.types.ptrType();
        hold.operands.push_back(object);
        hold.aggregate = owner;
        hold.imm = persistIndex_.count(owner->name) != 0 ? persistIndex_[owner->name] : 0;
        hold.text = "__persist";
        hold.loc = loc;
        const ValueId slot = emit(std::move(hold));
        slotType_[slot] = out_.module.types.ptrType();
        const ValueId base = loadFrom(slot, loc);
        Inst g;
        g.op = Op::Gep;
        g.type = out_.module.types.ptrType();
        g.operands.push_back(base);
        g.aggregate = block;
        g.imm = at;
        g.text = field;
        g.loc = loc;
        const ValueId addr = emit(std::move(g));
        if (block != nullptr && static_cast<size_t>(at) < block->fields.size()) {
            slotType_[addr] = block->fields[at].type;
        }
        if (auto n = fieldTypeName_.find(owner->name + "." + field); n != fieldTypeName_.end()) {
            noteName(addr, n->second.name, n->second.pointerDepth);
        }
        return addr;
    }

    ValueId fieldAddress(ValueId object, const std::string& field, SourceLocation loc) {
        if (object == kNoValue) {
            return kNoValue;
        }
        // THE OWNER FIRST, because it is what says WHERE the field is. This used to emit the `gep`
        // and then look the owner up afterwards, so the instruction went out with no aggregate and
        // no index -- and the backend, having only a byte offset of zero, put every field of every
        // class at the start of the object. `StringBuilder`'s `cap`, `buf` and `count` were one
        // machine word: the constructor wrote 16, then a pointer, then 0 over each other, `cap`
        // read back as 0, and `while (n < count + extra) { n = n * 2; }` never left zero. A sample
        // that had merely failed to link now hung, which is how it was found.
        const Type* owner = ownerOf(object);
        // A `persistent` FIELD IS ONE INDIRECTION FURTHER OUT (§18.2). It is not in the object at
        // all: the object holds a pointer to a block, and the field is in the block. Both `this.f`
        // and `var.f` come through here, so saying it once here is what makes both work.
        if (owner != nullptr && owner->kind == TypeKind::Struct) {
            if (const ValueId inBlock = persistentFieldAddress(object, owner, field, loc);
                inBlock != kNoValue) {
                return inBlock;
            }
        }
        int64_t index = -1;
        // EVERY FIELD OF A UNION IS AT OFFSET ZERO -- that is what the declaration means. The
        // aggregate holds one member and the name decides only how the bytes are READ, which is
        // what the slot type below says.
        const bool union_ = owner != nullptr && unions_.count(owner->name) != 0;
        // A BIT FIELD'S ADDRESS IS ITS UNIT'S. There is no address of five bits, so what this hands
        // back is where the shared unit lives, and the record is filed against that address so the
        // load and the store that follow know to shift and mask instead of reading the whole unit.
        auto packed = owner != nullptr ? bitFields_.find(owner->name + "." + field)
                                       : bitFields_.end();
        if (packed != bitFields_.end()) {
            index = packed->second.index;
        } else if (union_) {
            index = 0;
        } else if (owner != nullptr && owner->kind == TypeKind::Struct) {
            for (size_t i = 0; i < owner->fields.size(); ++i) {
                if (owner->fields[i].name == field) {
                    index = static_cast<int64_t>(i);
                    break;
                }
            }
        }

        Inst g;
        g.op = Op::Gep;
        g.type = out_.module.types.ptrType();
        g.operands.push_back(object);
        g.text = field;
        if (index >= 0) {
            g.aggregate = owner;
            g.imm = index;
        }
        g.loc = loc;
        const ValueId addr = emit(std::move(g));
        if (packed != bitFields_.end()) {
            // The unit's own width, so the load and the store touch it as one natural access --
            // which is what an MMIO register packed into bit fields requires -- and the record, so
            // both know which bits of it belong to this name.
            slotType_[addr] = out_.module.types.intType(packed->second.unitBits);
            packedAt_[addr] = packed->second;
            if (auto n = fieldTypeName_.find(owner->name + "." + field);
                n != fieldTypeName_.end()) {
                noteName(addr, n->second.name, n->second.pointerDepth);
            }
            return addr;
        }
        // A `weak` FIELD'S ADDRESS IS ITS NODE'S, and the node's first word IS the target -- so a
        // READ needs nothing special, and only the write does. Which class it points at is recorded
        // with it, because the head's offset is computed from the field's STATIC type.
        if (index >= 0 && owner != nullptr && static_cast<size_t>(index) < owner->fields.size() &&
            owner->fields[static_cast<size_t>(index)].weak) {
            slotType_[addr] = out_.module.types.ptrType();
            if (auto n = fieldTypeName_.find(owner->name + "." + field);
                n != fieldTypeName_.end()) {
                noteName(addr, n->second.name, n->second.pointerDepth);
                weakSlotAt_[addr] = classNameOf(n->second.name);
            }
            return addr;
        }
        // A NARROW `A*` FIELD'S ADDRESS IS A FOUR-BYTE SLOT holding an offset. Filed here, against
        // the address, for the same reason a bit field is: what comes back from `fieldAddress` is
        // where the storage lives, and only the load and the store that follow can know that the
        // storage is not the declared type. See `narrowLoad` / `narrowStore`.
        if (index >= 0 && owner != nullptr) {
            if (auto n = fieldTypeName_.find(owner->name + "." + field);
                n != fieldTypeName_.end() && n->second.pointerDepth == 1) {
                if (const std::string nt = narrowTargetNamed(n->second.name); !nt.empty()) {
                    slotType_[addr] = out_.module.types.intType(32);
                    narrowAt_[addr] = nt;
                    noteName(addr, n->second.name, n->second.pointerDepth);
                    return addr;
                }
            }
        }

        // WHAT THE ADDRESS POINTS AT, remembered so the `load` that follows knows its own type. A
        // `ptr` is opaque by design, so the alternative is a load that guesses -- and a guess of
        // `i32` for a `T[]` field is what turned every `delete` of one into a rule-10 failure.
        if (owner != nullptr && owner->kind == TypeKind::Struct) {
            // ...and the DECLARED type with it, so a read of the field knows which class it holds.
            if (auto n = fieldTypeName_.find(owner->name + "." + field);
                n != fieldTypeName_.end()) {
                noteName(addr, n->second.name, n->second.pointerDepth);
                // ...and for a union that is also what says how WIDE the read is. The aggregate has
                // one member, so the loop below would type every field as the widest one and
                // `v.asInt` over a `{ float }` union would come back as a float's bits read as a
                // float. The declared type of THIS name is the answer.
                if (union_) {
                    slotType_[addr] = n->second.pointerDepth > 0 ? out_.module.types.ptrType()
                                                                 : baseTypeOf(n->second.name);
                    return addr;
                }
            }
            for (size_t i = 0; i < owner->fields.size(); ++i) {
                if (owner->fields[i].name == field) {
                    const Type* ft = owner->fields[i].type;
                    slotType_[addr] = ft;
                    // AND WHAT IT POINTS AT, when the field holds another object. Without this the
                    // chain stops at one hop: `this.a.b` typed `a` and then guessed at `b`, which
                    // is why a hundred and thirty-three `delete`s could not say what they were
                    // deleting. A type known once is a type known all the way down.
                    if (ft != nullptr && ft->kind == TypeKind::Struct && ft->nominal) {
                        pointeeOfSlot_[addr] = ft;
                    }
                    break;
                }
            }
        }
        // §37.5: A `volatile` FIELD IS VOLATILE STORAGE. The console's cell buffer, a device's
        // shadow register, the framebuffer's base -- reading one twice must read it twice.
        if (owner != nullptr && volatileFields_.count(owner->name + "." + field) != 0) {
            volatilePointee_.insert(addr);
        }
        return addr;
    }

    // The class a value points at, when that is known. Known for `this` -- which is the receiver of
    // most field accesses -- and for anything loaded out of a slot whose type was recorded.
    const Type* ownerOf(ValueId v) {
        if (v == kNoValue) {
            return nullptr;
        }
        auto it = pointee_.find(v);
        if (it != pointee_.end()) {
            return it->second;
        }
        const ValueDef* d = fn_->value(v);
        if (d != nullptr && d->type != nullptr && d->type->kind == TypeKind::Struct) {
            return d->type;
        }
        // ...and failing both, THE NAME IT WAS DECLARED WITH. An object local is a `ptr` and a
        // `ptr` is opaque, so `pointee_` only knows about values this pass happened to watch being
        // created; a `Point p` read back out of its slot is not one of those. Without this,
        // `p.x` had no owner, its `gep` fell back to offset zero and its `load` guessed `i32` --
        // so both coordinates of every point read the same four bytes.
        if (const std::string name = classNameOf(declaredName(v)); !name.empty()) {
            auto it = named_.find(name);
            if (it != named_.end() && it->second != nullptr &&
                it->second->kind == TypeKind::Struct) {
                return it->second;
            }
        }
        return nullptr;
    }

    // `a[i]` OVER A CLASS THAT DECLARES `operator []` is a method call, not an element address.
    // The receiver is already lowered when this is asked -- lowering it a second time to answer the
    // question is what made an earlier version of the same check on `.` spin polc forever.
    const Function* indexOperator(ValueId receiver, const std::string& name) const {
        const std::string written = declaredName(receiver);
        // ONLY A PLAIN OBJECT. `Row* rows` and `int[] a` both index by stepping, and asking whether
        // `Row` happens to declare an `operator []` would hijack them: the star and the brackets say
        // this value is a walk over memory, whatever the element type declares.
        if (written.empty() || written.back() == '*' || written.find('[') != std::string::npos) {
            return nullptr;
        }
        const std::string cls = classNameOf(written);
        return cls.empty() ? nullptr : resolveKey(cls + "." + name);
    }

    // THE METHODS A VALUE HAS WITHOUT A CLASS TO DECLARE THEM.
    //
    // `3.hash()`, `a.equalsKey(b)`, `n.compareTo(m)`, `x.toString()`, `n.wrappingAdd(m)`: an
    // integer, a boolean, a char, a float, a String and an array all answer these, and none of
    // them is a class whose key a lookup could find. Without this the resolver fell through to
    // matching by bare NAME and took whichever class in the module happened to declare `.hash`
    // first -- the standard library's `ByteSize` -- so `HashSet<int>.add` handed an `int` to a
    // method expecting a pointer and the program died on its first insert. Every hashed collection
    // over a primitive key was affected; none of them said so.
    // ---- §20.3 and §20.6 ----
    //
    // `atomic<T>` holds one field and the operations on it are INSTRUCTIONS: an atomic load, an
    // atomic store, an add that answers the new value, and a compare-and-set. `Channel<T>` holds a
    // handle and its send/receive are the runtime's blocking queue. Neither has a body to call.
    Lowered concurrencyMethod(ValueId receiver, const std::string& cls, const std::string& key,
                              const std::vector<ValueId>& args, SourceLocation loc) {
        if (receiver == kNoValue) {
            return nothing();
        }
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        if (cls.rfind("atomic$", 0) == 0) {
            const Type* held = baseTypeOf(cls.substr(7));
            if (held == nullptr) {
                held = tt.intType(32);
            }
            const ValueId slot = fieldAddress(receiver, "value", loc);
            if (slot == kNoValue) {
                return nothing();
            }
            if (key == "get") {
                Inst in;
                in.op = Op::AtomicLoad;
                in.type = held;
                in.operands.push_back(slot);
                in.loc = loc;
                return done(emit(std::move(in)));
            }
            if (key == "set" && args.size() == 2) {
                Inst in;
                in.op = Op::AtomicStore;
                in.operands.push_back(fitInt(args[1], held->bits > 0 ? held->bits : 32, loc));
                in.operands.push_back(slot);
                in.loc = loc;
                emit(std::move(in));
                return done();
            }
            if (key == "increment" || (key == "add" && args.size() == 2)) {
                const ValueId by = key == "increment"
                                       ? constInt(1, held->bits > 0 ? held->bits : 32, loc)
                                       : fitInt(args[1], held->bits > 0 ? held->bits : 32, loc);
                Inst in;
                in.op = Op::AtomicRmw;
                in.type = held;
                in.operands.push_back(slot);
                in.operands.push_back(by);
                in.loc = loc;
                return done(emit(std::move(in)));
            }
            if (key == "compareAndSet" && args.size() == 3) {
                const unsigned bits = held->bits > 0 ? held->bits : 32;
                Inst in;
                in.op = Op::AtomicCmpXchg;
                in.type = tt.intType(32);
                in.operands.push_back(slot);
                in.operands.push_back(fitInt(args[1], bits, loc));
                in.operands.push_back(fitInt(args[2], bits, loc));
                in.loc = loc;
                return done(emit(std::move(in)));
            }
            return nothing();
        }
        if (cls.rfind("Channel$", 0) == 0) {
            const ValueId slot = fieldAddress(receiver, "h", loc);
            if (slot == kNoValue) {
                return nothing();
            }
            const ValueId handle = loadFrom(slot, loc);
            if (key == "send" && args.size() == 2) {
                // ONE SLOT IS SIXTY-FOUR BITS, whatever T is: the queue carries words, and an
                // object crosses as its address. Widening here rather than in the runtime keeps the
                // queue from having to know anything about the element type.
                callExternal("__polaron_chan_send", tt.voidType(), {i64, i64},
                             {handle, asWord(args[1], loc)}, loc);
                return done();
            }
            if (key == "receive") {
                const ValueId got =
                    callExternal("__polaron_chan_receive", i64, {i64}, {handle}, loc);
                const std::string elem = cls.substr(8);
                const Type* want = baseTypeOf(elem);
                if (want != nullptr && want->kind == TypeKind::Ptr) {
                    Inst back;
                    back.op = Op::AddrToPtr;
                    back.type = ptr;
                    back.operands.push_back(got);
                    back.loc = loc;
                    const ValueId obj = emit(std::move(back));
                    noteName(obj, elem);
                    return done(obj);
                }
                if (want != nullptr && want->kind == TypeKind::Float) {
                    Inst bits;
                    bits.op = Op::Bitcast;
                    bits.type = tt.floatType(64);
                    bits.operands.push_back(got);
                    bits.loc = loc;
                    const ValueId d = emit(std::move(bits));
                    return done(want->bits == 64 ? d : lowerConversion(d, tt.floatType(64), want, loc));
                }
                return done(want != nullptr && want->kind == TypeKind::Int && want->bits < 64
                                ? narrow(got, want->bits, loc)
                                : got);
            }
            return nothing();
        }
        return nothing();
    }

    Lowered primitiveMethod(ValueId receiver, const std::string& cls, const std::string& key,
                            const std::vector<ValueId>& args, SourceLocation loc) {
        if (receiver == kNoValue) {
            return nothing();
        }
        const Type* rt = fn_->value(receiver)->type;
        if (rt == nullptr) {
            return nothing();
        }
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* i32 = tt.intType(32);
        const bool text = cls == "String" || cls == "string";
        // A DECLARED CLASS WITH THE METHOD WINS. A `record` that writes its own `equalsKey` means
        // that one; only a receiver nothing declares reaches the built-in answers.
        if (!cls.empty() && !text && resolveKey(cls + "." + key) != nullptr) {
            return nothing();
        }
        const ValueId other = args.size() > 1 ? args[1] : kNoValue;
        // A `String` RECEIVER ALREADY HAS ONE PLACE THAT ANSWERS EVERYTHING IT CAN BE ASKED.
        const bool pointerLike = rt->kind == TypeKind::Ptr;
        if (text) {
            return nothing();
        }

        if (rt->kind == TypeKind::Int || rt->kind == TypeKind::Bool) {
            if (key == "hash") {
                return done(widen(receiver, 64, loc));
            }
            if (key == "toString") {
                // A `boolean` HAS TWO WORDS, not two numbers. `true` and `false` are the only
                // spellings the language has for it, and the integer path printed `-1 0` -- the
                // same value reading differently depending on how it was asked for, with the lossy
                // answer as the default.
                if (rt->kind == TypeKind::Bool || cls == "boolean") {
                    return done(pickString(receiver, "true", "false", loc));
                }
                return done(intToString(widen(receiver, 64, loc), loc));
            }
            if (other == kNoValue) {
                return nothing();
            }
            if (key == "equalsKey") {
                Inst eq;
                eq.op = Op::CmpEq;
                eq.type = tt.boolType();
                eq.operands.push_back(receiver);
                eq.operands.push_back(sameWidth(other, rt, loc));
                eq.loc = loc;
                return done(widen(emit(std::move(eq)), 32, loc));
            }
            if (key == "compareTo") {
                return done(compareValues(receiver, sameWidth(other, rt, loc), false, loc));
            }
            if (cgutil::isIntOverflowMethod(key)) {
                return done(overflowMethod(key, receiver, sameWidth(other, rt, loc), rt, loc));
            }
            return nothing();
        }

        if (rt->kind == TypeKind::Float) {
            if (key == "hash") {
                Inst bits;
                bits.op = Op::Bitcast;
                bits.type = rt->bits == 32 ? i32 : i64;
                bits.operands.push_back(receiver);
                bits.loc = loc;
                return done(widen(emit(std::move(bits)), 64, loc));
            }
            if (key == "toString") {
                return done(floatToString(receiver, loc));
            }
            if (other == kNoValue) {
                return nothing();
            }
            if (key == "equalsKey") {
                Inst eq;
                eq.op = Op::CmpEq;
                eq.type = tt.boolType();
                eq.operands.push_back(receiver);
                eq.operands.push_back(other);
                eq.loc = loc;
                return done(widen(emit(std::move(eq)), 32, loc));
            }
            if (key == "compareTo") {
                return done(compareValues(receiver, other, true, loc));
            }
            return nothing();
        }

        // AN ARRAY IS KEYED BY IDENTITY. Two arrays with equal elements are still two arrays, and a
        // collection that conflated them would take the wrong one out on `remove`.
        if (pointerLike && (key == "hash" || key == "equalsKey") && cls.empty()) {
            if (key == "hash") {
                Inst asNumber;
                asNumber.op = Op::PtrToAddr;
                asNumber.type = tt.addrType(64);
                asNumber.operands.push_back(receiver);
                asNumber.loc = loc;
                return done(emit(std::move(asNumber)));
            }
            if (other != kNoValue) {
                Inst eq;
                eq.op = Op::CmpEq;
                eq.type = tt.boolType();
                eq.operands.push_back(receiver);
                eq.operands.push_back(other);
                eq.loc = loc;
                return done(widen(emit(std::move(eq)), 32, loc));
            }
        }
        return nothing();
    }

    // `a <=> b` as an integer: -1, 0 or 1. Two comparisons and two selects, which is what the
    // trusted path emits and what the folder collapses when both sides are known.
    ValueId compareValues(ValueId a, ValueId b, bool floating, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        auto compare = [&](Op op) {
            Inst in;
            in.op = op;
            in.type = tt.boolType();
            in.operands.push_back(a);
            in.operands.push_back(b);
            in.loc = loc;
            return emit(std::move(in));
        };
        const ValueId less = compare(floating ? Op::CmpLtF : Op::CmpLtS);
        const ValueId greater = compare(floating ? Op::CmpGtF : Op::CmpGtS);
        Inst high;
        high.op = Op::Select;
        high.type = tt.intType(32);
        high.operands.push_back(greater);
        high.operands.push_back(constInt(1, 32, loc));
        high.operands.push_back(constInt(0, 32, loc));
        high.loc = loc;
        Inst pick;
        pick.op = Op::Select;
        pick.type = tt.intType(32);
        pick.operands.push_back(less);
        pick.operands.push_back(constInt(-1, 32, loc));
        pick.operands.push_back(emit(std::move(high)));
        pick.loc = loc;
        return emit(std::move(pick));
    }

    // `wrappingAdd` and its family: the same arithmetic with the overflow rule stated on the
    // METHOD instead of on the expression -- which is exactly what the opcode suffix already says,
    // so each one is a single instruction rather than a call.
    ValueId overflowMethod(const std::string& key, ValueId a, ValueId b, const Type* type,
                           SourceLocation loc) {
        Inst in;
        in.type = type;
        in.operands.push_back(a);
        in.operands.push_back(b);
        in.loc = loc;
        if (key == "wrappingAdd" || key == "uncheckedAdd") {
            in.op = Op::AddWrap;
        } else if (key == "wrappingSub" || key == "uncheckedSub") {
            in.op = Op::SubWrap;
        } else if (key == "wrappingMul" || key == "uncheckedMul") {
            in.op = Op::MulWrap;
        } else if (key == "wrappingDiv" || key == "uncheckedDiv") {
            // DIVISION HAS EXACTLY ONE OVERFLOW CASE: `INT_MIN / -1`, whose true answer does not
            // fit. `wrappingDiv` wraps it -- the answer is `INT_MIN` again -- and a plain `sdiv`
            // there is not a wrong number but a HARDWARE TRAP: the process dies with no output.
            // Dividing by one instead, only in that case, produces exactly the wrapped answer.
            Inst safe;
            safe.op = Op::Select;
            safe.type = type;
            Inst lowest;
            lowest.op = Op::ConstInt;
            lowest.type = type;
            lowest.imm = type->bits >= 64
                             ? std::numeric_limits<int64_t>::min()
                             : -(static_cast<int64_t>(1) << (type->bits - 1));
            lowest.loc = loc;
            Inst minusOne;
            minusOne.op = Op::ConstInt;
            minusOne.type = type;
            minusOne.imm = -1;
            minusOne.loc = loc;
            Inst both;
            both.op = Op::And;
            both.type = out_.module.types.boolType();
            both.operands.push_back(cmp(Op::CmpEq, a, emit(std::move(lowest)), loc));
            both.operands.push_back(cmp(Op::CmpEq, b, emit(std::move(minusOne)), loc));
            both.loc = loc;
            Inst one;
            one.op = Op::ConstInt;
            one.type = type;
            one.imm = 1;
            one.loc = loc;
            safe.operands.push_back(emit(std::move(both)));
            safe.operands.push_back(emit(std::move(one)));
            safe.operands.push_back(b);
            safe.loc = loc;
            in.operands[1] = emit(std::move(safe));
            in.op = Op::DivChecked;
        } else if (key == "saturatingAdd") {
            in.op = Op::AddSaturate;
        } else if (key == "saturatingSub") {
            in.op = Op::SubSaturate;
        } else {
            in.op = Op::MulSaturate;
        }
        return emit(std::move(in));
    }

    // The same width as the value it is about to be compared with. A literal arrives as `i32` and
    // a `long` receiver is `i64`; the comparison opcodes take two of one width and nothing else.
    ValueId sameWidth(ValueId v, const Type* want, SourceLocation loc) {
        const Type* have = v != kNoValue ? fn_->value(v)->type : nullptr;
        if (have == nullptr || want == nullptr || have == want || want->kind != TypeKind::Int ||
            have->kind != TypeKind::Int) {
            return v;
        }
        return have->bits < want->bits ? widen(v, want->bits, loc) : narrow(v, want->bits, loc);
    }

    // WHAT SHAPE A VALUE INDEXES AS. An inline array's name IS its storage, so the value is a
    // pointer and the array-ness is in what that storage holds; a heap array's value is the slice
    // itself. Asking the value's own type answered `ptr` for the first, and every question after
    // that -- the stride, the header, the length -- was answered for the wrong shape.
    // What a lowered value's type is CALLED in the language, for the one place that has to build a
    // type spelling out of values: a tuple literal, whose components name its type.
    static std::string nameOfType(const Type* t) {
        if (t == nullptr) {
            return "int";
        }
        switch (t->kind) {
            case TypeKind::Bool:  return "boolean";
            case TypeKind::Float: return t->bits == 32 ? "float" : "double";
            case TypeKind::Ptr:   return "Object";
            case TypeKind::Int:
                return t->bits == 8    ? "byte"
                       : t->bits == 16 ? "short"
                       : t->bits == 64 ? "long"
                                       : "int";
            default: return "int";
        }
    }

    const Type* shapeOf(ValueId v) {
        if (auto it = slotType_.find(v); it != slotType_.end() && it->second != nullptr &&
                                         (it->second->kind == TypeKind::Array ||
                                          it->second->kind == TypeKind::Slice)) {
            return it->second;
        }
        return v != kNoValue ? fn_->value(v)->type : nullptr;
    }

    ValueId elementAddress(const ast::IndexExpr& ix, ValueId already = kNoValue) {
        const ValueId arr = already != kNoValue ? already : lowerExpr(ix.array.get());
        const ValueId idx = lowerExpr(ix.index.get());
        if (arr == kNoValue || idx == kNoValue) {
            return kNoValue;
        }
        // THE BOUNDS CHECK IS AN INSTRUCTION, not a branch. That is what lets §11.3 delete a
        // redundant one and what unblocks the hoisting the open-coded form prevents -- and
        // `unchecked` is a fact on the index expression rather than a flag threaded through an
        // emitter.
        // A RAW POINTER HAS NO LENGTH TO CHECK AGAINST. The guard reads the eight-byte header an
        // array carries, and a `T*` has none: `low_level_memory` panicked with `index = 0,
        // length = 0` on its first read, having found whatever those eight bytes happened to be.
        // That a `T*` is unchecked is the point of writing one -- spec 27 says so.
        // THE ARRAY'S TYPE TRAVELS WITH THE GEP, because the backend needs the element size to
        // scale the index and the header size to skip. A `gep` whose type says `ptr` cannot know
        // either, and the first version indexed every element to offset zero.
        const Type* base = shapeOf(arr);
        if (!ix.unchecked && !isRawPointer(arr)) {
            Inst g;
            g.op = Op::GuardBounds;
            g.operands.push_back(idx);
            g.operands.push_back(arr);
            // AND THE SHAPE WITH IT. An inline array's extent is in its type and there is no
            // header to read a length out of; the value itself is only a pointer, so the guard
            // cannot recover the shape from its operand and has to be told.
            g.aggregate = base;
            // THE STATEMENT'S LOCATION, not the bracket's -- see `lowerStmt`. This is what the
            // panic prints, and the two backends have to print the same thing.
            g.loc = stmtLoc_.line > 0 ? stmtLoc_ : ix.loc;
            emit(std::move(g));
        }
        // A RAW POINTER HAS NO LENGTH HEADER. `a[i]` on an `int*` was stepping over eight bytes of
        // header that is only there for a `T[]`, so every element read came from one element too
        // far in and the last one ran off the allocation. The element type is what says how far one
        // step is, and a bare `ptr` cannot say -- it is opaque by design -- so the declaration does.
        const Type* pointee = nullptr;
        if (base != nullptr && base->kind == TypeKind::Ptr) {
            // THE POINTEE, with the star taken off. `declaredName` now holds the type as written --
            // `int*` -- and reading that straight back gave `baseTypeOf("int*")`, a pointer, so the
            // step over an `int*` became eight bytes instead of four.
            if (const std::string n = classNameOf(declaredName(arr)); !n.empty()) {
                pointee = storageTypeOf(n);
            }
        }

        Inst gep;
        gep.op = Op::Gep;
        gep.type = base;
        gep.aggregate = pointee;   // what this `gep` steps over; null for a slice, which knows
        gep.operands.push_back(arr);
        gep.operands.push_back(idx);
        gep.loc = ix.loc;
        const ValueId at = emit(std::move(gep));
        slotType_[at] = pointee != nullptr ? pointee : elementOf(base);
        // ONE INDEX REMOVES ONE DIMENSION, and the element keeps what it was declared as. Without
        // this an element of a `String[]` arrived with no type at all, so `argv[i].equals(flag)`
        // could not tell that its receiver was a String and resolved `equals` by bare name.
        if (const DeclaredType elem = elementDeclOf(declaredName(arr)); !elem.name.empty()) {
            noteName(at, elem.name, elem.pointerDepth);
        }
        return at;
    }

    // `cascade delete x` -- DELETE THE OBJECT AND EVERYTHING IT OWNS (spec 37.1).
    //
    // Ownership by COMPOSITION: a value-typed class field, or a class pointer that is not
    // `external`. A reference, an array and an `external` pointer are associations and are left
    // alone -- deleting through them would free somebody else's object. `DropCascade` was reaching
    // the backend as a plain `drop`, so `cascade delete` deleted the root and nothing else and
    // every owned object leaked with its destructor unrun.
    //
    // One helper per (call site, class), memoised BEFORE its body is built so a type that contains
    // itself resolves rather than recursing forever. A visited set makes a shared or cyclic graph
    // delete each node once; `depth` bounds how far the walk goes (-1 is unlimited).
    void lowerCascadeDelete(ValueId root, const std::string& cls, const ast::CascadeParams& params,
                            SourceLocation loc,
                            CascadeAction action = CascadeAction::Delete) {
        TypeTable& tt = out_.module.types;
        const int csid = cascadeSites_++;
        Function* walk = cascadeHelper(csid, cls, params, action);
        if (walk == nullptr) {
            return;
        }
        const ValueId seen =
            callExternal("__polaron_ptrset_new", tt.ptrType(), {}, {}, loc);
        emitCall(walk, {root, seen, constInt(params.depth, 32, loc)}, loc);
        callExternal("__polaron_ptrset_free", tt.voidType(), {tt.ptrType()}, {seen}, loc);
    }

    // `cascade clone X into Y` (§37.1): a DEEP copy of X's owned graph, with the sharing kept.
    //
    // The map from original to clone is what makes that true: a node reached twice is cloned once
    // and both edges point at the one clone, so a shared or cyclic graph comes out the same shape
    // it went in rather than expanded or looping forever. Everything that is NOT owned -- a
    // primitive, an array, an `external` pointer -- is left as the shallow copy of the bytes made
    // it, which is the same rule the ordinary deep copy follows.
    void lowerCascadeClone(const ast::CascadeStmt& cs) {
        TypeTable& tt = out_.module.types;
        const ValueId src = lowerExpr(cs.target.get());
        if (src == kNoValue) {
            return;
        }
        const std::string cls = classNameOf(declaredName(src));
        if (cls.empty() || named_.count(cls) == 0) {
            gap("CascadeStmt(clone of an unknown class: " + cls + ")", cs.loc);
            return;
        }
        Function* walk = cloneHelper(cascadeSites_++, cls, cs.params);
        if (walk == nullptr) {
            return;
        }
        const ValueId map = callExternal("__polaron_ptrmap_new", tt.ptrType(), {}, {}, cs.loc);
        const ValueId made =
            emitCall(walk, {src, map, constInt(cs.params.depth, 32, cs.loc)}, cs.loc);
        callExternal("__polaron_ptrmap_free", tt.voidType(), {tt.ptrType()}, {map}, cs.loc);
        noteName(made, cls);
        noteStorage(made, Storage::Heap);
        if (const ValueId dest = addressOf(cs.dest.get()); dest != kNoValue) {
            storeInto(dest, made, cs.loc);
        }
    }

    // One clone helper per (site, class), memoised BEFORE its body is built so a type that contains
    // itself resolves rather than recursing forever. Answers the clone of `src`.
    Function* cloneHelper(int csid, const std::string& cls, const ast::CascadeParams& params) {
        const std::string key = "__clone." + std::to_string(csid) + "." + cls;
        if (auto made = cascadeFns_.find(key); made != cascadeFns_.end()) {
            return made->second;
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i32 = tt.intType(32);
        const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
        if (shape == nullptr) {
            return nullptr;
        }
        std::vector<Field> args3;
        args3.push_back(Field{ptr, "src"});
        args3.push_back(Field{ptr, "map"});
        args3.push_back(Field{i32, "depth"});
        Function* fn = out_.module.addFunction(key, tt.fnType(ptr, std::move(args3)));
        fn->params = {{"src", cls, false}, {"map", "", false}, {"depth", "int", false}};
        fn->linkage = Linkage::Private;
        fn->kind = FnKind::Method;
        cascadeFns_[key] = fn;

        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        declaredAs_.clear();
        storage_.clear();
        stringTemps_.clear();
        stringSlots_.clear();
        volatilePointee_.clear();
        volatilePointerSlots_.clear();
        pointee_.clear();
        pointeeOfSlot_.clear();
        clearFieldShapes();
        weakSlotAt_.clear();
        cCallable_.clear();
        paramTypes_.clear();
        labels_.clear();
        loops_.clear();
        handlers_.clear();
        yields_.clear();
        deferred_.clear();
        scoped_.clear();
        unwindObjects_.clear();
        unwindDefers_.clear();
        statics_.clear();
        lazyLocals_.clear();
        selfSlot_ = kNoValue;
        selfClass_ = nullptr;
        selfClassName_.clear();

        const ValueId src = fn->addValue(ptr, ValueOrigin::BlockParam, here_, 0, "src");
        const ValueId map = fn->addValue(ptr, ValueOrigin::BlockParam, here_, 1, "map");
        const ValueId depth = fn->addValue(i32, ValueOrigin::BlockParam, here_, 2, "depth");
        fn->block(here_)->params = {src, map, depth};
        noteName(src, cls);
        pointee_[src] = shape;

        const BlockId live = fn_->addBlock(fresh("cln.live"));
        const BlockId again = fn_->addBlock(fresh("cln.again"));
        const BlockId fresh1 = fn_->addBlock(fresh("cln.new"));
        const BlockId out = fn_->addBlock(fresh("cln.out"));
        const ValueId answer = fn_->addValue(ptr, ValueOrigin::BlockParam, out, 0, "");
        fn_->block(out)->params.push_back(answer);

        auto leaveWith = [&](ValueId v) {
            Inst go;
            go.op = Op::Br;
            Edge e{out, {}};
            e.args.push_back(v);
            go.edges.push_back(e);
            emit(std::move(go));
        };

        // NULL CLONES TO NULL, and a node already cloned answers with the clone it already has --
        // that is what keeps the sharing and what stops a cycle.
        {
            Inst pick;
            pick.op = Op::BrCond;
            pick.operands.push_back(cmp(Op::CmpNe, src, nullPointer({}), {}));
            pick.edges.push_back(Edge{live, {}});
            Edge none{out, {}};
            none.args.push_back(nullPointer({}));
            pick.edges.push_back(none);
            emit(std::move(pick));
        }

        here_ = live;
        const ValueId seenAs =
            callExternal("__polaron_ptrmap_get", ptr, {ptr, ptr}, {map, src}, {});
        {
            Inst pick;
            pick.op = Op::BrCond;
            pick.operands.push_back(cmp(Op::CmpNe, seenAs, nullPointer({}), {}));
            Edge had{out, {}};
            had.args.push_back(seenAs);
            pick.edges.push_back(had);
            pick.edges.push_back(Edge{fresh1, {}});
            emit(std::move(pick));
        }
        (void)again;

        // THE BYTES FIRST, then the owned edges repointed at their clones. Copying the bytes is
        // what carries the primitives, and recording the clone BEFORE recursing is what lets a
        // cycle find it.
        here_ = fresh1;
        const ValueId size = sizeOfClass(shape, {});
        const ValueId copy = callExternal("__polaron_malloc", ptr, {tt.intType(64)}, {size}, {});
        callExternal("memcpy", ptr, {ptr, ptr, tt.intType(64)}, {copy, src, size}, {});
        callExternal("__polaron_ptrmap_put", tt.voidType(), {ptr, ptr, ptr}, {map, src, copy}, {});
        noteName(copy, cls);
        pointee_[copy] = shape;

        const BlockId deeper = fn_->addBlock(fresh("cln.into"));
        const BlockId done = fn_->addBlock(fresh("cln.done"));
        branchOn(cmp(Op::CmpNe, depth, constInt(0, 32, {}), {}), deeper, done);

        here_ = deeper;
        Inst step;
        step.op = Op::SubWrap;
        step.type = i32;
        step.operands.push_back(depth);
        step.operands.push_back(constInt(1, 32, {}));
        const ValueId lowered = emit(std::move(step));
        Inst endless;
        endless.op = Op::CmpLtS;
        endless.type = tt.boolType();
        endless.operands.push_back(depth);
        endless.operands.push_back(constInt(0, 32, {}));
        Inst choose;
        choose.op = Op::Select;
        choose.type = i32;
        choose.operands.push_back(emit(std::move(endless)));
        choose.operands.push_back(depth);
        choose.operands.push_back(lowered);
        const ValueId next = emit(std::move(choose));
        for (const Field& f : shape->fields) {
            const std::string owned = ownedChildClass(cls, f.name, params);
            if (owned.empty()) {
                continue;
            }
            const ValueId at = fieldAddress(copy, f.name, {});
            if (at == kNoValue) {
                continue;
            }
            Function* into = cloneHelper(csid, owned, params);
            if (into == nullptr) {
                continue;
            }
            const ValueId child = loadFrom(at, {});
            storePtr(at, emitCall(into, {child, map, next}, {}), {});
        }
        gotoIfOpen(done);

        here_ = done;
        leaveWith(copy);

        here_ = out;
        Inst give;
        give.op = Op::Ret;
        give.operands.push_back(answer);
        emit(std::move(give));

        restoreBody(std::move(outer));
        return fn;
    }

    // The three operations the weak list needs, generated ONCE into the module. Generated rather
    // than called into the runtime because the list is the compiler's own layout -- the head's
    // offset and the node's shape are decided here -- and a runtime that had to be told both would
    // be a second place for the layout to live.
    //
    // A fresh body is lowered inside each, so the enclosing method's state is saved and put back
    // the way `cascadeHelper` does it: a value id from another function's numbering resolves to
    // something and is wrong.
    Function* weakHelper(const std::string& key, std::vector<Field> params,
                         const std::function<void(Function&, const std::vector<ValueId>&)>& build) {
        if (Function* made = out_.module.find(key)) {
            return made;
        }
        TypeTable& tt = out_.module.types;
        std::vector<Function::Param> names;
        for (const Field& f : params) {
            names.push_back({f.name, "", false});
        }
        Function* fn = out_.module.addFunction(key, tt.fnType(tt.voidType(), params));
        fn->params = std::move(names);
        fn->linkage = Linkage::Private;
        fn->kind = FnKind::Method;

        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        declaredAs_.clear();
        storage_.clear();
        stringTemps_.clear();
        stringSlots_.clear();
        volatilePointee_.clear();
        volatilePointerSlots_.clear();
        pointee_.clear();
        pointeeOfSlot_.clear();
        clearFieldShapes();
        weakSlotAt_.clear();
        cCallable_.clear();
        paramTypes_.clear();
        labels_.clear();
        loops_.clear();
        handlers_.clear();
        yields_.clear();
        deferred_.clear();
        scoped_.clear();
        unwindObjects_.clear();
        unwindDefers_.clear();
        statics_.clear();
        lazyLocals_.clear();
        selfSlot_ = kNoValue;
        selfClass_ = nullptr;
        selfClassName_.clear();

        std::vector<ValueId> args;
        Block* entry = fn->block(here_);
        for (uint32_t i = 0; i < params.size(); ++i) {
            const ValueId v =
                fn->addValue(params[i].type, ValueOrigin::BlockParam, here_, i, params[i].name);
            entry->params.push_back(v);
            args.push_back(v);
        }
        build(*fn, args);
        if (!blockClosed()) {
            Inst r;
            r.op = Op::Ret;
            emit(std::move(r));
        }
        restoreBody(std::move(outer));
        return fn;
    }

    // WHERE A CLASS KEEPS ITS WEAK-LIST HEAD, in bytes from the object's start. Right behind the
    // vtable for every class that carries one, so a `weak Base*` holding a `Derived` finds it where
    // `Base` says it is.
    static constexpr int64_t kWeakHeadOffset = 8;

    // Unlink the node from wherever it was, then link it to the new target unless that is null.
    void weakRelink(ValueId slot, const std::string& targetClass, ValueId value,
                    SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        emitCall(weakUnlinkFn(), {slot, constLong(kWeakHeadOffset, loc)}, loc);
        if (value == kNoValue) {
            return;
        }
        const BlockId link = fn_->addBlock(fresh("weak.link"));
        const BlockId after = fn_->addBlock(fresh("weak.set"));
        branchOn(cmp(Op::CmpNe, value, nullPointer(loc), loc), link, after);
        here_ = link;
        // The head's offset is known here and not inside the helper, because it is a fact about the
        // FIELD'S DECLARED TYPE -- the one thing the helper cannot see.
        (void)targetClass;
        emitCall(weakLinkFn(), {slot, value, constLong(kWeakHeadOffset, loc)}, loc);
        gotoIfOpen(after);
        here_ = after;
        (void)tt;
    }

    // Empty every weak reference to this object, if anything can hold one. A class that is not a
    // weak target carries no head and there is nothing to walk.
    void nullifyWeakList(ValueId obj, const std::string& cls, SourceLocation loc) {
        if (obj == kNoValue || !carriesWeakHead(cls)) {
            return;
        }
        const ValueId head = rawOffset(obj, constLong(kWeakHeadOffset, loc), loc);
        slotType_[head] = out_.module.types.ptrType();
        emitCall(weakNullifyFn(), {head}, loc);
    }

    // The address of one word of a WeakSlot: 0 is the target, 1 is the next node.
    ValueId weakWord(ValueId slot, int64_t which, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        Inst g;
        g.op = Op::Gep;
        g.type = tt.ptrType();
        g.operands.push_back(slot);
        g.aggregate = weakSlotType();
        g.imm = which;
        g.text = which == 0 ? "target" : "next";
        g.loc = loc;
        const ValueId at = emit(std::move(g));
        slotType_[at] = tt.ptrType();
        return at;
    }

    void storePtr(ValueId addr, ValueId value, SourceLocation loc) {
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(value);
        put.operands.push_back(addr);
        put.loc = loc;
        emit(std::move(put));
    }

    // Link `slot` into the list hanging off `target + headOff`, recording what it points at.
    Function* weakLinkFn() {
        TypeTable& tt = out_.module.types;
        return weakHelper("__polaron_weak_link",
                          {Field{tt.ptrType(), "slot"}, Field{tt.ptrType(), "target"},
                           Field{tt.intType(64), "headOff"}},
                          [&](Function&, const std::vector<ValueId>& a) {
                              const ValueId slot = a[0];
                              const ValueId target = a[1];
                              storePtr(weakWord(slot, 0, {}), target, {});
                              const ValueId head = rawOffset(target, a[2], {});
                              slotType_[head] = tt.ptrType();
                              storePtr(weakWord(slot, 1, {}), loadFrom(head, {}), {});
                              storePtr(head, slot, {});
                          });
    }

    // Walk the list at `headAddr`, empty every node, then empty the head. This is what makes a weak
    // reference read null the moment its target dies.
    Function* weakNullifyFn() {
        TypeTable& tt = out_.module.types;
        return weakHelper(
            "__polaron_weak_nullify", {Field{tt.ptrType(), "headAddr"}},
            [&](Function& fn, const std::vector<ValueId>& a) {
                const ValueId headAddr = a[0];
                slotType_[headAddr] = tt.ptrType();
                const ValueId cursor = allocaFor("weak.n", tt.ptrType());
                slotType_[cursor] = tt.ptrType();
                storePtr(cursor, loadFrom(headAddr, {}), {});

                const BlockId test = fn.addBlock(fresh("weak.test"));
                const BlockId body = fn.addBlock(fresh("weak.body"));
                const BlockId out = fn.addBlock(fresh("weak.done"));
                gotoIfOpen(test);

                here_ = test;
                const ValueId n = loadFrom(cursor, {});
                branchOn(cmp(Op::CmpNe, n, nullPointer({}), {}), body, out);

                here_ = body;
                const ValueId next = loadFrom(weakWord(n, 1, {}), {});
                storePtr(weakWord(n, 0, {}), nullPointer({}), {});
                storePtr(weakWord(n, 1, {}), nullPointer({}), {});
                storePtr(cursor, next, {});
                gotoIfOpen(test);

                here_ = out;
                storePtr(headAddr, nullPointer({}), {});
            });
    }

    // Remove `slot` from whichever list it is in, and empty it. Called before a weak field is
    // written: the node is about to point somewhere else, and leaving it on the old target's list
    // would have that target null a field that no longer refers to it.
    Function* weakUnlinkFn() {
        TypeTable& tt = out_.module.types;
        return weakHelper(
            "__polaron_weak_unlink",
            {Field{tt.ptrType(), "slot"}, Field{tt.intType(64), "headOff"}},
            [&](Function& fn, const std::vector<ValueId>& a) {
                const ValueId slot = a[0];
                const BlockId has = fn.addBlock(fresh("weak.has"));
                const BlockId isFirst = fn.addBlock(fresh("weak.first"));
                const BlockId scan = fn.addBlock(fresh("weak.scan"));
                const BlockId step = fn.addBlock(fresh("weak.step"));
                const BlockId clear = fn.addBlock(fresh("weak.clear"));

                const ValueId slotNext = loadFrom(weakWord(slot, 1, {}), {});
                const ValueId target = loadFrom(weakWord(slot, 0, {}), {});
                branchOn(cmp(Op::CmpNe, target, nullPointer({}), {}), has, clear);

                here_ = has;
                const ValueId head = rawOffset(target, a[1], {});
                slotType_[head] = tt.ptrType();
                const ValueId cursor = allocaFor("weak.p", tt.ptrType());
                slotType_[cursor] = tt.ptrType();
                storePtr(cursor, loadFrom(head, {}), {});
                branchOn(cmp(Op::CmpEq, loadFrom(head, {}), slot, {}), isFirst, scan);

                here_ = isFirst;
                storePtr(head, slotNext, {});
                gotoIfOpen(clear);

                // ...OTHERWISE IT IS SOMEWHERE FURTHER ALONG, and the scan looks for the node whose
                // `next` is this one. O(n), and deliberately: a weak field is unlinked when it is
                // rewritten or destroyed, which is rare, and the alternative is a back pointer in
                // every node -- another word per weak field, paid always, to save a walk paid
                // seldom.
                here_ = scan;
                const ValueId at = loadFrom(cursor, {});
                branchOn(cmp(Op::CmpNe, at, nullPointer({}), {}), step, clear);

                here_ = step;
                const ValueId atNext = loadFrom(weakWord(at, 1, {}), {});
                const BlockId found = fn.addBlock(fresh("weak.found"));
                const BlockId onward = fn.addBlock(fresh("weak.on"));
                branchOn(cmp(Op::CmpEq, atNext, slot, {}), found, onward);

                here_ = found;
                storePtr(weakWord(at, 1, {}), slotNext, {});
                gotoIfOpen(clear);

                here_ = onward;
                storePtr(cursor, atNext, {});
                gotoIfOpen(scan);

                here_ = clear;
                storePtr(weakWord(slot, 0, {}), nullPointer({}), {});
                storePtr(weakWord(slot, 1, {}), nullPointer({}), {});
            });
    }

    // ---- `heap class X` (§36): the bridge between generated code and the program's own allocator ----
    //
    // BARE METAL HAS NO LIBC, so a freestanding program NOMINATES a class to be its heap and the
    // compiler's own allocation calls land there. Every `new ... on heap`, every dynamic array and
    // every `delete` in this backend becomes a call to `__polaron_malloc`/`__polaron_free`; those
    // names are the boundary, and something has to give them bodies.
    //
    // Nothing did. The trusted path has written this bridge all along and this one never had it, so
    // the symbol resolved to the FALLBACK in the compiler's own freestanding runtime -- a bump
    // allocator over a static array -- and pico's kernel ran on it without a word.
    //
    // What that looks like is worth writing down, because it took a hardware watchpoint to see. The
    // machine booted perfectly: every driver, the network stack, the whole desktop, a window with
    // its title drawn. Then it took a #GP DELIVERING THE TIMER INTERRUPT and triple-faulted. The
    // static array the fallback allocates from is laid out over the low memory pico puts its IDT in,
    // so `Typeface.outlineFor` asking for one 2 KiB glyph buffer -- `memset(0x401d00, 0, 2048)` --
    // zeroed the interrupt table out from under the running kernel. The kernel's real allocator was
    // sitting there correctly initialised, brk at 0x1823710, with nothing calling it.
    //
    // The check for a second heap class, and the errors for a heap class that is missing a method,
    // belong to the analyzer and the trusted path already reports them; this side takes what it is
    // given and stays quiet, because two compilers reporting one error prints it twice.
    void emitHeapBridge() {
        if (!ast_.isFreestanding) {
            return;   // hosted: `on heap` is the runtime's pooled allocator, and it has one
        }
        const ast::ClassDecl* heapCls = nullptr;
        for (const ast::Bundle& b : ast_.bundles) {
            for (const ast::Namespace& ns : b.namespaces) {
                for (const ast::ClassDecl& c : ns.classes) {
                    if (c.isHeap && heapCls == nullptr) {
                        heapCls = &c;
                    }
                }
            }
        }
        if (heapCls == nullptr) {
            return;
        }
        TypeTable& tt = out_.module.types;
        heapBridge("__polaron_malloc", heapCls->name + ".allocate", tt.ptrType(),
                   {Field{tt.intType(64), "size"}});
        heapBridge("__polaron_free", heapCls->name + ".release", tt.voidType(),
                   {Field{tt.ptrType(), "block"}});
        // `checkLive` is OPTIONAL, and `heapBridge` writes nothing when the class has not got one:
        // the runtime already defines that symbol, and a second definition is a link failure.
        heapBridge("__polaron_check_live", heapCls->name + ".checkLive", tt.voidType(),
                   {Field{tt.ptrType(), "block"}});
    }

    // One bridge: a method named `sym`, taking `params`, forwarding to `target` and handing back
    // what it returns. The two sides speak different views of a machine word -- the allocator is
    // written in Polaron and says `address`, the symbol is what generated code calls and says
    // `ptr` -- so each value is converted rather than assumed.
    void heapBridge(const char* sym, const std::string& target, const Type* ret,
                    std::vector<Field> params) {
        TypeTable& tt = out_.module.types;
        const Function* to = out_.module.find(target);
        // A METHOD THE HEAP CLASS DOES NOT HAVE IS NOT BRIDGED AT ALL.
        //
        // `checkLive` is optional -- pico's `Kmalloc` has no such method -- and the runtime already
        // carries a definition of the symbol for exactly that case. Emitting an empty one here as
        // well gave the linker two, and it said so: `duplicate symbol: __polaron_check_live`. The
        // bridge exists to point a symbol at the program's own heap; where there is nothing to
        // point at, the right amount of code to write is none.
        if (to == nullptr) {
            return;
        }
        // THE DECLARATION THAT IS ALREADY THERE IS THE ONE THAT GETS THE BODY.
        //
        // Every `new ... on heap` in the program has already asked for `__polaron_malloc` by name,
        // and `callExternal` files one declaration under that key the first time. Adding a second
        // function of the same name here does not replace it -- the call sites keep pointing at the
        // empty one, the backend emits `declare` for it, and the linker resolves it to whatever
        // else in the image happens to define that symbol. Which is exactly what went wrong: the
        // compiler's own fallback allocator answered, and it allocates from a static array laid
        // over the kernel's interrupt table.
        Function* fn = out_.module.find(sym);
        if (fn == nullptr) {
            fn = out_.module.addFunction(sym, tt.fnType(ret, std::vector<Field>(params)));
        } else if (!fn->blocks.empty()) {
            return;   // already bridged
        }
        fn->signature = tt.fnType(ret, std::vector<Field>(params));
        fn->symbol = sym;
        fn->linkage = Linkage::External;   // the boundary generated code calls across
        fn->kind = FnKind::Method;
        fn->conv = Conv::Cdecl;
        fn->params.clear();
        for (const Field& p : params) {
            fn->params.push_back({p.name, "", false});
        }

        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        statics_.clear();
        selfSlot_ = kNoValue;
        selfClass_ = nullptr;
        selfClassName_.clear();

        std::vector<ValueId> incoming;
        for (uint32_t i = 0; i < params.size(); ++i) {
            const ValueId v =
                fn->addValue(params[i].type, ValueOrigin::BlockParam, here_, i, params[i].name);
            fn_->block(here_)->params.push_back(v);
            incoming.push_back(v);
        }
        // A HEAP CLASS THAT DOES NOT DEFINE THE METHOD gets a body that does nothing rather than a
        // call to a name the module has not got -- verifier rule 15 refuses the second, and
        // `checkLive` is deliberately allowed to be absent.
        Inst call;
        call.op = Op::Call;
        call.text = to->key;
        call.type = to->signature != nullptr && to->signature->element != nullptr
                        ? to->signature->element   // a function type's `element` IS its result
                        : tt.voidType();
        for (size_t i = 0; i < incoming.size(); ++i) {
            const Type* want = to->signature != nullptr && i < to->signature->fields.size()
                                   ? to->signature->fields[i].type
                                   : nullptr;
            call.operands.push_back(convertWord(incoming[i], want, {}));
        }
        const ValueId got = emit(std::move(call));
        Inst back;
        back.op = Op::Ret;
        if (ret->kind != TypeKind::Void && got != kNoValue) {
            back.operands.push_back(convertWord(got, ret, {}));
        }
        emit(std::move(back));
        restoreBody(std::move(outer));
    }

    // A machine word seen as the other kind of thing. `address` and `ptr` are the same sixty-four
    // bits and two different types, and PIR keeps them apart on purpose -- so crossing between them
    // is an instruction rather than a silent reinterpretation.
    ValueId convertWord(ValueId v, const Type* want, SourceLocation loc) {
        if (v == kNoValue || want == nullptr || fn_ == nullptr) {
            return v;
        }
        const ValueDef* had = fn_->value(v);
        if (had == nullptr || had->type == nullptr || had->type == want) {
            return v;
        }
        const bool fromPtr = had->type->kind == TypeKind::Ptr;
        const bool toPtr = want->kind == TypeKind::Ptr;
        if (fromPtr == toPtr) {
            return v;
        }
        Inst as;
        as.op = toPtr ? Op::AddrToPtr : Op::PtrToAddr;
        as.type = want;
        as.operands.push_back(v);
        as.loc = loc;
        return emit(std::move(as));
    }

    Function* cascadeHelper(int csid, const std::string& cls, const ast::CascadeParams& params,
                            CascadeAction action = CascadeAction::Delete) {
        const std::string key = "__cascade." + std::to_string(csid) + "." +
                                (action == CascadeAction::Delete    ? "d."
                                 : action == CascadeAction::Println ? "p."
                                                                    : "v.") +
                                cls;
        if (auto made = cascadeFns_.find(key); made != cascadeFns_.end()) {
            return made->second;
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i32 = tt.intType(32);
        std::vector<Field> params3;
        params3.push_back(Field{ptr, "obj"});
        params3.push_back(Field{ptr, "seen"});
        params3.push_back(Field{i32, "depth"});
        Function* fn = out_.module.addFunction(key, tt.fnType(tt.voidType(), std::move(params3)));
        fn->params = {{"obj", cls, false}, {"seen", "", false}, {"depth", "int", false}};
        fn->linkage = Linkage::Private;
        fn->kind = FnKind::Method;
        cascadeFns_[key] = fn;   // before the body, so a self-referential type terminates

        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        locals_.clear();
        slotType_.clear();
        declaredAs_.clear();
        storage_.clear();
        stringTemps_.clear();
        stringSlots_.clear();
        volatilePointee_.clear();
        volatilePointerSlots_.clear();
        pointee_.clear();
        pointeeOfSlot_.clear();
        paramTypes_.clear();
        labels_.clear();
        loops_.clear();
        handlers_.clear();
        yields_.clear();
        deferred_.clear();
        scoped_.clear();
        unwindObjects_.clear();
        unwindDefers_.clear();
        statics_.clear();
        lazyLocals_.clear();
        selfSlot_ = kNoValue;
        selfClass_ = nullptr;
        selfClassName_.clear();

        const ValueId obj = fn->addValue(ptr, ValueOrigin::BlockParam, here_, 0, "obj");
        const ValueId seen = fn->addValue(ptr, ValueOrigin::BlockParam, here_, 1, "seen");
        const ValueId depth = fn->addValue(i32, ValueOrigin::BlockParam, here_, 2, "depth");
        Block* entry = fn_->block(here_);
        entry->params = {obj, seen, depth};
        noteName(obj, cls);
        if (named_.count(cls) != 0) {
            pointee_[obj] = named_[cls];
        }

        const BlockId live = fn_->addBlock(fresh("cas.live"));
        const BlockId fresh1 = fn_->addBlock(fresh("cas.fresh"));
        const BlockId recurse = fn_->addBlock(fresh("cas.into"));
        const BlockId leave = fn_->addBlock(fresh("cas.ret"));

        branchOn(cmp(Op::CmpNe, obj, nullPointer({}), {}), live, leave);

        // ALREADY VISITED means stop: a shared child reached twice must be deleted once, and a
        // cycle would otherwise not terminate at all.
        here_ = live;
        const ValueId first = callExternal("__polaron_ptrset_add", i32, {ptr, ptr}, {seen, obj}, {});
        branchOn(cmp(Op::CmpNe, first, constInt(0, 32, {}), {}), fresh1, leave);

        // THE CHILDREN ARE READ BEFORE THE NODE IS FREED, because freeing it makes its fields
        // unreadable -- and they are what the walk continues through.
        here_ = fresh1;
        std::vector<std::pair<ValueId, std::string>> children;
        if (const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
            shape != nullptr) {
            for (const Field& f : shape->fields) {
                const std::string owned = ownedChildClass(cls, f.name, params);
                if (owned.empty()) {
                    continue;
                }
                const ValueId at = fieldAddress(obj, f.name, {});
                if (at != kNoValue) {
                    children.push_back({loadFrom(at, {}), owned});
                }
            }
        }
        // THE ACTION, owner before owned -- which is destructor order, and the order the other two
        // read best in: a node describes itself before what it holds, and a broken invariant is
        // reported at the node that broke it rather than after its children.
        switch (action) {
            case CascadeAction::Delete:
                lowerDeleteObject(obj, cls, {});
                break;
            case CascadeAction::Println:
                // `describe()` is what §37.1 says a node answers with; the analyzer has already
                // refused a class that does not have one, so a missing method here is nothing to
                // report a second time.
                if (const Function* say = resolveKey(cls + ".describe")) {
                    emitCall(say, {obj}, {});
                }
                break;
            case CascadeAction::Validate: {
                // `this` IS THE NODE THIS WALKER WAS HANDED. An `invariant` is written about `this`
                // -- `invariant this.id >= 0` -- and this body has no `this` of its own, so the
                // clause has to be told which object it is being checked against before it is
                // lowered. Without it `this.id` resolved to nothing and the walker read `load i32,
                // ptr null`: `cascade validate(a)` segfaulted before printing a character.
                //
                // A SLOT rather than the parameter, because `selfLoad` loads through one -- the same
                // shape every ordinary method's `this` has, so nothing downstream needs a special
                // case for being inside a cascade.
                const ValueId self = entryAlloca(ptr, "this");
                slotType_[self] = ptr;
                noteName(self, cls);
                Inst st;
                st.op = Op::Store;
                st.operands.push_back(obj);
                st.operands.push_back(self);
                emit(std::move(st));
                locals_["this"] = self;
                selfSlot_ = self;
                selfClass_ = named_.count(cls) != 0 ? named_[cls] : nullptr;
                selfClassName_ = cls;
                // ITS OWN CLAUSES AND ITS ANCESTORS'. A subclass is bound by the contracts of the
                // classes it is built on (§29), so the chain is walked upward and every clause on
                // the way checked against this node.
                for (const ast::ClassDecl* at = findClass(cls); at != nullptr;) {
                    for (const auto& inv : at->invariants) {
                        emitContractGuard(inv.get(), "invariant");
                    }
                    const std::string up = classNameOf(at->superclass);
                    at = up.empty() ? nullptr : findClass(up);
                }
                break;
            }
        }

        branchOn(cmp(Op::CmpNe, depth, constInt(0, 32, {}), {}), recurse, leave);
        here_ = recurse;
        // `depth` counts DOWN, and -1 stays -1: unlimited is the default and the common case.
        Inst step;
        step.op = Op::SubWrap;
        step.type = i32;
        step.operands.push_back(depth);
        step.operands.push_back(constInt(1, 32, {}));
        const ValueId lowered = emit(std::move(step));
        Inst endless;
        endless.op = Op::CmpLtS;
        endless.type = tt.boolType();
        endless.operands.push_back(depth);
        endless.operands.push_back(constInt(0, 32, {}));
        Inst pick;
        pick.op = Op::Select;
        pick.type = i32;
        pick.operands.push_back(emit(std::move(endless)));
        pick.operands.push_back(depth);
        pick.operands.push_back(lowered);
        const ValueId next = emit(std::move(pick));
        for (const auto& [child, childClass] : children) {
            if (Function* into = cascadeHelper(csid, childClass, params, action)) {
                emitCall(into, {child, seen, next}, {});
            }
        }
        gotoIfOpen(leave);

        here_ = leave;
        Inst done;
        done.op = Op::Ret;
        emit(std::move(done));

        restoreBody(std::move(outer));
        return fn;
    }

    // WHICH CLASS A FIELD OWNS, or "" when the field is not an owned child. Ownership by
    // composition: a value-typed class field or a non-`external` class pointer. A reference, an
    // array and an `external` pointer are associations. `types:`/`except:` prune it further, by
    // static type, which is what those clauses are for.
    std::string ownedChildClass(const std::string& owner, const std::string& field,
                                const ast::CascadeParams& params) {
        // THE FIELD MAY BE THE BASE'S. `fieldTypeName_` is keyed by the class that DECLARED the
        // field, and a subclass's layout begins with its base's fields -- so asking under the
        // subclass's name found nothing and an inherited owned child was never followed.
        std::string declaringClass = owner;
        auto written = fieldTypeName_.end();
        while (!declaringClass.empty()) {
            written = fieldTypeName_.find(declaringClass + "." + field);
            if (written != fieldTypeName_.end()) {
                break;
            }
            const ast::ClassDecl* up = findClass(declaringClass);
            declaringClass = up != nullptr ? up->superclass : std::string();
        }
        if (written == fieldTypeName_.end()) {
            return std::string();
        }
        const std::string& type = written->second.name;
        if (type.find('&') != std::string::npos || !elementNameOf(type).empty()) {
            return std::string();
        }
        const std::string child = classNameOf(type);
        if (child.empty() || findClass(child) == nullptr || isPrimitiveName(child)) {
            return std::string();
        }
        if (externalFields_.count(declaringClass + "." + field) != 0) {
            return std::string();
        }
        if (!params.onlyTypes.empty() &&
            std::find(params.onlyTypes.begin(), params.onlyTypes.end(), child) ==
                params.onlyTypes.end()) {
            return std::string();
        }
        if (std::find(params.exceptTypes.begin(), params.exceptTypes.end(), child) !=
            params.exceptTypes.end()) {
            return std::string();
        }
        return child;
    }

    // One `drop` on an object whose class is known: the destructor, dispatched when it might be
    // overridden, and the free. Shared by `delete` and by the cascade walk, so the two cannot
    // disagree about what deleting one object means.
    void lowerDeleteObject(ValueId obj, const std::string& cls, SourceLocation loc) {
        Inst drop;
        drop.op = Op::Drop;
        drop.type = out_.module.types.ptrType();
        drop.operands.push_back(obj);
        drop.text = cls;
        const ast::ClassDecl* decl = cls.empty() ? nullptr : findClass(cls);
        const bool reference = decl != nullptr && !decl->isStruct && !decl->isRecord &&
                               !decl->isUnion && !decl->isLayout;
        drop.imm = reference && vtableSlot_.count("~") != 0 && hierarchyHasDestructor(cls)
                       ? vtableSlot_["~"]
                       : -1;
        drop.extra.push_back("heap");   // a cascade walks heap objects; that is what it deletes
        drop.loc = loc;
        emit(std::move(drop));
    }

    ValueId cmp(Op op, ValueId a, ValueId b, SourceLocation loc) {
        Inst in;
        in.op = op;
        in.type = out_.module.types.boolType();
        in.operands.push_back(a);
        in.operands.push_back(b);
        in.loc = loc;
        return emit(std::move(in));
    }

    void branchOn(ValueId cond, BlockId yes, BlockId no) {
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(cond);
        br.edges.push_back(Edge{yes, {}});
        br.edges.push_back(Edge{no, {}});
        emit(std::move(br));
    }

    // One target of a `delete`. Extracted because `delete a, b, c;` deletes EACH -- only the first
    // was being lowered, so the rest were leaked and their destructors never ran.
    // `delete x from region R`: the destructor, then the memory back to the region.
    void lowerDeleteFromRegion(const ast::DeleteStmt& s) {
        TypeTable& tt = out_.module.types;
        const RegionShape& shaped = regionShapeOf(s.fromRegion);
        std::vector<const ast::Expr*> targets{s.target.get()};
        for (const ast::ExprPtr& more : s.moreTargets) {
            targets.push_back(more.get());
        }
        for (const ast::Expr* target : targets) {
            const ValueId obj = lowerExpr(target);
            if (obj == kNoValue) {
                continue;
            }
            const std::string cls = classNameOf(declaredName(obj));
            const ast::ClassDecl* decl = cls.empty() ? nullptr : findClass(cls);
            if (decl != nullptr) {
                if (const Function* dtor = resolveKey(destructorOf(*decl))) {
                    emitCall(dtor, {obj}, s.loc);
                }
            }
            const ValueId block = regionBlockFor(s.fromRegion, s.loc);
            if (block == kNoValue) {
                gap("DeleteStmt(region not in scope: " + s.fromRegion + ")", s.loc);
                return;
            }
            const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
            if (shaped.flavor == "pool" || shaped.flavor == "fixedslot" || shaped.growable) {
                callExternal("__polaron_region_free", tt.voidType(),
                             {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                             {block, obj, shape != nullptr ? sizeOfClass(shape, s.loc)
                                                           : constLong(16, s.loc)},
                             s.loc);
            } else if (shaped.registry()) {
                // A bump or stack region reclaims only on release or rollback, but the registry
                // must FORGET this object now -- or the teardown destructs it a second time, on
                // memory whose destructor has already run.
                callExternal("__polaron_region_untrack", tt.voidType(),
                             {tt.ptrType(), tt.ptrType()}, {block, obj}, s.loc);
            } else if (const auto* named = dynamic_cast<const ast::IdentifierExpr*>(target)) {
                // ...and where the list is the COMPILER'S, forgetting means emptying the slot: the
                // release below walks that list and skips whatever is null.
                if (auto slot = locals_.find(named->name); slot != locals_.end()) {
                    Inst emptied;
                    emptied.op = Op::Store;
                    emptied.operands.push_back(nullPointer(s.loc));
                    emptied.operands.push_back(slot->second);
                    emptied.loc = s.loc;
                    emit(std::move(emptied));
                }
            }
        }
    }

    void lowerDelete(const ast::Expr* targetExpr, bool cascade, SourceLocation loc,
                     const ast::CascadeParams* limits = nullptr) {
        // AN EXPLICIT `delete` TAKES THE OBJECT OFF THE SCOPE'S LIST. It has been destroyed; the
        // end of the block must not destroy it again. `stack_delete` printed `dtor 1` twice --
        // once where the program deletes and once more at the end of `main`.
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(targetExpr)) {
            if (auto local = locals_.find(id->name); local != locals_.end()) {
                const ValueId slot = local->second;
                scoped_.erase(std::remove_if(scoped_.begin(), scoped_.end(),
                                             [slot](const ScopedObject& o) { return o.slot == slot; }),
                              scoped_.end());
                unwindObjects_.erase(
                    std::remove_if(unwindObjects_.begin(), unwindObjects_.end(),
                                   [slot](const ScopedObject& o) { return o.slot == slot; }),
                    unwindObjects_.end());
            }
        }
        const ValueId target = lowerExpr(targetExpr);
        if (target == kNoValue) {
            return;
        }
        // `cascade delete` IS A WALK, not a flag on one `drop`. It was reaching the backend as an
        // ordinary delete, so the root went and everything it owned leaked with its destructor
        // unrun -- `~Outer` printed and `~Mid` and `~Leaf` did not.
        if (cascade) {
            if (const std::string cls = classNameOf(declaredName(target));
                !cls.empty() && findClass(cls) != nullptr) {
                static const ast::CascadeParams everything;
                lowerCascadeDelete(target, cls, limits != nullptr ? *limits : everything, loc);
                return;
            }
        }
        // A `delete` on a PRIMITIVE is the only case the lowering refuses: everything else is a
        // destructor call, and whether this pass resolved the class is not the question. See
        // verifier rule 10.
        const Type* dt = fn_->value(target)->type;
        const bool primitive =
            dt != nullptr && (dt->kind == TypeKind::Int || dt->kind == TypeKind::Float ||
                              dt->kind == TypeKind::Bool || dt->kind == TypeKind::Addr);
        if (primitive) {
            // THE VERIFIER IS RIGHT AND THE LOWERING DOES NOT KNOW ENOUGH. Rule 10 says a `drop`
            // names a type whose `owns` is true, and it does -- what is missing is this pass's type
            // propagation, which loses a `T[]` through a local whose initialiser it could not type.
            // Emitting the `drop` anyway would make the verifier cry wolf on every `delete` in the
            // standard library; recording a gap says exactly what is unfinished.
            gap("DeleteStmt(target is " + std::string(TypeTable::spell(dt)) + ")", loc);
            return;
        }
        // EVERY WEAK REFERENCE TO THIS OBJECT NULLS ITSELF, before the memory goes. That is the
        // whole promise of the word: `w.target` reads null the moment `n` is deleted, and it reads
        // it without anyone counting references. Done here, ahead of the drop, because the list
        // lives IN the object being freed.
        nullifyWeakList(target, classNameOf(declaredName(target)), loc);
        Inst drop;
        // `cascade delete` walks the owned graph; a plain `delete` does not. Two opcodes, because
        // the difference is what verifier rule 11 is about -- a cascade through a `weak` field
        // frees somebody else's object.
        drop.op = cascade ? Op::DropCascade : Op::Drop;
        drop.type = dt;
        drop.operands.push_back(target);
        // WHICH CLASS, so the backend can name the destructor; and WHICH SLOT holds it, so it can
        // dispatch instead -- `delete base` on an object that is really a `Derived` has to run
        // `~Derived`. -1 means "no table", and the class's own destructor is called by name.
        drop.text = classNameOf(declaredName(target));
        // ...and ONLY WHEN THERE IS A DESTRUCTOR TO DISPATCH TO. The slot number is global, so a
        // class that declares none still has that index in its table -- holding null. Jumping there
        // is a call to address zero, and eleven samples that had been passing began to crash the
        // moment `delete` started using the table. Asking the declaration is the whole check.
        // ...AND A SUBCLASS'S DESTRUCTOR COUNTS. `abstract class Shape` declares none and `Square
        // extends Shape` declares one: asking only about the STATIC class said "nothing to
        // dispatch to", so `delete s` on a `Shape*` holding a `Square` called `Shape`'s destructor
        // by name -- and there is none, so nothing ran and `~Square` never printed. Which body runs
        // is the object's to decide; what the static class decides is only the slot number.
        // ...AND THE STATIC CLASS NEED NOT HAVE A TABLE OF ITS OWN. `abstract class Shape` is never
        // instantiated, so no `Shape.vtable` is emitted -- but a `Shape*` always points at
        // something that HAS a table, because every reference class carries one at field zero. The
        // static class supplies only the slot number.
        const ast::ClassDecl* deleted = drop.text.empty() ? nullptr : findClass(drop.text);
        const bool reference = deleted != nullptr && !deleted->isStruct && !deleted->isRecord &&
                               !deleted->isUnion && !deleted->isLayout;
        const bool dispatchable =
            reference && vtableSlot_.count("~") != 0 && hierarchyHasDestructor(drop.text);
        drop.imm = dispatchable ? vtableSlot_["~"] : -1;
        // AND WHETHER THERE IS ANYTHING TO FREE.
        //
        // This asked "is the target in the set of things this method watched come out of an
        // `on heap`", and freed only those. It is the wrong question, because the commonest
        // `delete` in any program is of something the method did not allocate:
        //
        //     public static method free(Tree* t) returns void {
        //         if (t.left != null) { Main.free(...); Main.free(...); }
        //         delete t;                      // `t` is a PARAMETER: allocated elsewhere
        //     }
        //
        // so `binarytrees` freed nothing at all -- LLVM even marked `Main.free` `readonly`, a fair
        // description of a method that does nothing -- and the benchmark ran 1.5x slower while
        // leaking every node of thirty trees. Nothing failed and no output changed, which is how it
        // survived a corpus that compares what programs PRINT.
        //
        // The question that IS right is asked of all three states:
        //
        //   Heap    -- this method watched it come out of the allocator. Release it.
        //   Frame   -- this method watched it be given a frame slot. Run the destructor and leave
        //              the allocator alone; `stack_delete` exists to hold exactly this line.
        //   Unknown -- it arrived from somewhere else, and the DECLARATION is what is left to ask.
        //              A `*` is Polaron's boxed form and it is the one that owns heap storage:
        //              `Result<int,int>` and `Result<int,int>*` are the same class, written twice
        //              in `value_compat`, and a `delete` of the first is a no-op by design while a
        //              `delete` of the second frees. Nothing but the star separates them.
        //
        // ...and never for a class whose instances live in an arena, which owns their storage.
        noteStringFields(drop, drop.text);
        const Storage where = storageOf(target);
        // ...AND AN INTERFACE IS BOXED WITHOUT A STAR.
        //
        // The star is what separates the two forms of a CONCRETE class, and an interface has only
        // one: `Iterator<int> it = Sequences.evens(4);` names a heap object however it is written,
        // because an interface has no size to put in a frame slot -- the same reason `byValueCopy`
        // refuses to copy one. Asked only about the star, `delete it` ran the destructor through
        // the vtable and left the memory: `generator.pol` exited 304 bytes in 12 blocks against the
        // other path's 112 in 5, on identical output.
        //
        // AN INTERFACE, AND NOT MERELY AN ABSTRACT CLASS. `sealed abstract class Result<T,E>` HAS a
        // value form -- that is what §21's variant is -- and for it the star really is the only
        // difference: `delete` of the unstarred one is a no-op by design. Reading `abstract` as
        // "boxed" freed a value Result and `value_compat` printed `v=0` where the program says 7.
        const std::string deletedName = classNameOf(declaredName(target));
        const ast::ClassDecl* asWritten =
            deletedName.empty() ? nullptr : findClass(deletedName);
        // ...AND A `T[]` IS ALWAYS THE ALLOCATOR'S. `new T[n]()` is a heap block with a length
        // header -- §3.2 says so, there is no other way to make one -- so `delete` of an array
        // releases whatever this pass happened to learn about where it came from. Asked only about
        // storage it had WATCHED, an array handed back by a call was `Unknown`: `random_shuffle`
        // wrote `delete check` on an `Arrays.copyOf` result and the block stayed.
        const bool isArray = [&] {
            if (const Type* t = fn_->value(target)->type;
                t != nullptr && (t->kind == TypeKind::Slice ||
                                 (t->kind == TypeKind::Array && t->storage == ArrayStorage::Heap))) {
                return true;
            }
            return !elementNameOf(declaredName(target)).empty();
        }();
        // ...AND SO IS A REFERENCE CLASS WRITTEN WITHOUT ONE. The star separates the two forms of
        // something that HAS two: a value variant (`Result<int,int>` beside `Result<int,int>*`) and
        // a value aggregate. A `class` has one form, and it is a reference -- so `ArrayList<String>
        // want = Strings.split(...)` names a heap object however it is spelled, and `delete want`
        // owes the block. Read as "no star, so a value", the two `delete`s at the end of
        // `Router.matches` freed nothing and every request leaked both of its split lists.
        const bool referenceClass =
            asWritten != nullptr && !asWritten->isStruct && !asWritten->isRecord &&
            !asWritten->isUnion && !asWritten->isLayout && enums_.count(deletedName) == 0 &&
            valueVariantType(deletedName) == nullptr;
        const bool boxed = pointerDepthOf(target) > 0 || isArray || referenceClass ||
                           (asWritten != nullptr && asWritten->isInterface);
        const bool release = where == Storage::Heap || (where == Storage::Unknown && boxed);
        if (release && !livesInClassArena(drop.text)) {
            drop.extra.push_back("heap");
        }
        drop.loc = loc;
        emit(std::move(drop));
    }

    // WRITING TO A SLOT THAT HOLDS A VALUE STRUCT IS A COPY, not a pointer store. The slot IS the
    // object -- that is what a `struct` means -- so putting an address in it leaves the struct
    // untouched and the next read returns whatever it held. `c++` over a `Counter` counted to zero
    // that way: every step wrote an address into the four bytes the counter lived in.
    void storeInto(ValueId addr, ValueId value, SourceLocation loc) {
        // A CATALOG-TYPED SLOT HOLDS A TAGGED ORDINAL, so an enum value going into one is tagged
        // on the way in. A field declared `Heavy` that received a bare `Ingot.Iron` lost which
        // enum it was the moment it was stored, and the method call that read it back dispatched
        // to whichever implementer happens to be first.
        if (value != kNoValue && catalogs_.count(classNameOf(declaredName(addr))) != 0) {
            if (const std::string from = classNameOf(declaredName(value)); enums_.count(from) != 0) {
                value = tagForCatalog(value, from, loc);
            }
        }
        if (value == kNoValue || addr == kNoValue) {
            return;
        }
        // A BIT FIELD IS WRITTEN BACK INTO ITS UNIT, leaving the fields beside it untouched. A plain
        // store would put the whole value over all of them.
        if (auto bits = packedAt_.find(addr); bits != packedAt_.end()) {
            bitFieldStore(addr, bits->second, value, loc);
            return;
        }
        // ...AND A NARROW POINTER IS STORED AS ITS OFFSET, for the same reason: a plain store here
        // would write eight bytes into a four-byte slot and take the next field with it.
        if (auto narrow = narrowAt_.find(addr); narrow != narrowAt_.end()) {
            narrowStore(addr, value, narrow->second, loc);
            return;
        }
        // WRITING A `weak` FIELD IS RELINKING IT, not storing a pointer. The field is a node on the
        // old target's list; leaving it there would have that target null a field that no longer
        // refers to it, and never putting it on the new one would mean the new target's death goes
        // unnoticed. Null is a legitimate value and links nothing.
        if (auto slot = weakSlotAt_.find(addr); slot != weakSlotAt_.end()) {
            weakRelink(addr, slot->second, value, loc);
            return;
        }
        const Type* held = slotType_.count(addr) != 0 ? slotType_[addr] : nullptr;
        const Type* given = fn_->value(value)->type;
        // A PRIMITIVE GOING INTO A `nullable` SLOT IS BOXED. The slot holds a pointer -- null when
        // absent -- so writing the number itself would make the value indistinguishable from an
        // address, and `x == null` would be asking whether the number is zero.
        if (held != nullptr && held->kind == TypeKind::Ptr && given != nullptr &&
            (given->kind == TypeKind::Int || given->kind == TypeKind::Float ||
             given->kind == TypeKind::Bool) &&
            ast::typeIsNullable(declaredName(addr))) {
            TypeTable& tt = out_.module.types;
            const ValueId box = callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                             {constInt(8, 64, loc)}, loc);
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(value);
            put.operands.push_back(box);
            put.loc = loc;
            emit(std::move(put));
            value = box;
            // ...AND IT IS A POINTER NOW. `given` was read before the box existed and still said
            // `int<32>`, so the conversion below was asked to turn the box's ADDRESS into an `int`
            // and then into a `ptr` -- a pair it does not have a case for, which is `undef`. The
            // field then held `undef`, and the difference between -O0 and -O2 is only whether the
            // machine happens to still have the right value in the register: `b.slot = 7` read
            // back as 7 unoptimised and turned the whole method into `unreachable` at -O2.
            given = tt.ptrType();
        }
        // ...AND ANY ADDRESS COUNTS AS ONE. An element of an array of value structs arrives as a
        // `gep` whose type is the ARRAY's -- a `slice<Cell>`, because that is what the instruction
        // steps over -- so testing for `Ptr` alone let `mirror[2] = cells[0]` through as a plain
        // pointer store, which the backend then dropped: the copy simply did not happen, and the
        // sample that exists to prove the two elements are independent scored six of seven.
        if (held != nullptr && held->kind == TypeKind::Struct && held->facts.isValue &&
            given != nullptr && given->isPointerLike()) {
            TypeTable& tt = out_.module.types;
            callExternal("memcpy", tt.ptrType(), {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                         {addr, value, sizeOfClass(held, loc)}, loc);
            return;
        }
        if (held != nullptr && held->kind == TypeKind::Struct && given != nullptr &&
            given->kind == TypeKind::Ptr) {
            TypeTable& tt = out_.module.types;
            callExternal("memcpy", tt.ptrType(), {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                         {addr, value, sizeOfClass(held, loc)}, loc);
            return;
        }
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(held != nullptr ? lowerConversion(value, given, held, loc) : value);
        st.operands.push_back(addr);
        st.loc = loc;
        emit(std::move(st));
    }

    // `v.y = e` or `v[i] = e` where `v` is a vector local: rebuild and store back. Answers kNoValue
    // when this is not a lane write, which is how the ordinary assignment paths go on being tried.
    ValueId lowerLaneWrite(const ast::AssignStmt& s) {
        const ast::Expr* subject = nullptr;
        ValueId index = kNoValue;
        if (const auto* mem = dynamic_cast<const ast::MemberExpr*>(s.target.get())) {
            const int lane = laneOfSwizzle(mem->member);
            if (lane < 0 || !isVectorExpr(mem->object.get())) {
                return kNoValue;
            }
            subject = mem->object.get();
            index = constInt(lane, 32, s.loc);
        } else if (const auto* ix = dynamic_cast<const ast::IndexExpr*>(s.target.get())) {
            if (!isVectorExpr(ix->array.get())) {
                return kNoValue;
            }
            subject = ix->array.get();
            index = lowerExpr(ix->index.get());
        }
        const auto* named = dynamic_cast<const ast::IdentifierExpr*>(subject);
        if (named == nullptr || index == kNoValue) {
            return kNoValue;
        }
        auto slot = locals_.find(named->name);
        if (slot == locals_.end()) {
            return kNoValue;
        }
        const ValueId held = loadFrom(slot->second, s.loc);
        const ValueId value = lowerExpr(s.value.get());
        if (held == kNoValue || value == kNoValue || !isVector(fn_->value(held)->type)) {
            return kNoValue;
        }
        const ValueId rebuilt = withLane(held, index, value, s.loc);
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(rebuilt);
        put.operands.push_back(slot->second);
        put.loc = s.loc;
        emit(std::move(put));
        return rebuilt;
    }

    void lowerAssign(const ast::AssignStmt& s) {
        // A LANE WRITE IS A REBUILD, NOT A STORE THROUGH AN ADDRESS. A vector is a value in a
        // register; `v.y = 20.0` and `v[2] = 30.0` make a new vector with that one lane replaced
        // and put it back in the variable. There is no address of a lane to write through, which is
        // exactly why the ordinary element path -- a `gep` into a heap block -- would have written
        // four bytes into whatever the register was spilled onto.
        if (const ValueId lane = lowerLaneWrite(s); lane != kNoValue) {
            return;
        }
        // AN INDEX ON THE LEFT OF AN `=` MAY BE A METHOD. A class that declares `operator []=`
        // means `p[0] = 10` is `p.operator[]=(0, 10)`; this pass went straight for an element
        // address, and since `p` is a pointer to an OBJECT rather than to an array, the store
        // landed on whatever field sat at offset zero -- so both elements aliased and the second
        // write overwrote the first. `addressOf` cannot express this case at all: there is no
        // address to hand back, only a call to make, which is why the interception is here.
        if (auto* ix = dynamic_cast<const ast::IndexExpr*>(s.target.get())) {
            const ValueId arr = lowerExpr(ix->array.get());
            if (arr == kNoValue) {
                gap("AssignStmt(cannot address element)", s.loc);
                return;
            }
            if (const Function* op = indexOperator(arr, "operator[]=")) {
                const ValueId idx = lowerExpr(ix->index.get());
                const ValueId val = lowerExpr(s.value.get());
                if (idx == kNoValue || val == kNoValue) {
                    gap("AssignStmt(operator []= argument did not lower)", s.loc);
                    return;
                }
                emitCall(op, {arr, idx, val}, s.loc);
                return;
            }
            const ValueId addr = elementAddress(*ix, arr);
            ValueId held = lowerExpr(s.value.get());
            if (addr == kNoValue || held == kNoValue) {
                gap("AssignStmt(element)", s.loc);
                return;
            }
            // §21: STORING A STRING INTO AN ELEMENT COPIES IT. An array owns its elements, so a
            // slot that shares the caller's buffer is a slot that outlives what it points at.
            //
            // `ArrayList.add` is where this shows: `this.data[this.count] = item`, with `item`
            // handed in by `out.add(s.substring(...))` -- a temporary the caller built. The other
            // backend copies here and this one did not, so the list held the caller's String and
            // `file_lines` read back four empty lines the moment anything released it.
            //
            // The interception is HERE and not in the tail of this method, which is where it was
            // put the first time and where an element store never arrives: the branch above returns
            // from inside itself.
            if (isStringNamed(elementNameOf(declaredName(arr)))) {
                TypeTable& tt = out_.module.types;
                const ValueId owned =
                    callExternal("__polaron_str_copy", tt.ptrType(), {tt.ptrType()}, {held}, s.loc);
                noteName(owned, elementNameOf(declaredName(arr)));
                held = owned;
                // AND THE SLOT GIVES BACK WHAT IT HELD, for the same reason a field does: an
                // element owns its buffer, so overwriting one without releasing it loses that
                // buffer. `new String[n]()` zero-initialises and the free is null-safe, so the
                // first write to a fresh slot releases nothing.
                callExternal("__polaron_str_free", tt.voidType(), {tt.ptrType()},
                             {loadFrom(addr, s.loc)}, s.loc);
            }
            storeInto(addr, held, s.loc);
            return;
        }
        // `this.den = itself.allocate(...)` CREATES THE FIELD'S REGION, and how big a header its
        // block needs depends on the field's declared flavour. The flavour was only being handed
        // over for a LOCAL, so a `pool region` field got the lean 24-byte header and the runtime
        // then read its free-lists out of the user's data.
        if (const auto* target = dynamic_cast<const ast::MemberExpr*>(s.target.get())) {
            pendingRegion_ = regionShapeOf(target->member);
            // `t.fahrenheit = 212` IS A CALL, NOT A STORE (§8.4). A property with a custom `set`
            // desugars to a method `fahrenheit$set(value)`, and the whole point is that the write
            // goes through it -- the backing field is private and may not even be the one named.
            // Written as a field store it found no field, fell back to offset zero, and the setter
            // never ran: `f=32`, the getter's answer for a celsius nobody had set.
            if (assignThroughSetter(*target, s)) {
                pendingRegion_ = RegionShape{};
                return;
            }
        }
        // `counter = counter + n` ON AN `atomic<T>` IS AN ATOMIC ADD, and `counter = v` an atomic
        // STORE (§20.6). Binding the atomic OBJECT itself -- `a = b` between two atomics, or a
        // field taking a fresh one -- is an ordinary reference store and must not come here, which
        // is what the second half of the test says.
        if (const ValueId slot = atomicValueSlot(s); slot != kNoValue) {
            return;
        }
        ValueId value = lowerExpr(s.value.get());
        pendingRegion_ = RegionShape{};
        // `b = a;` COPIES TOO. Assignment is a deep copy in this language whether it is the
        // declaration that binds the name or a later reassignment -- the rule is about the `=`,
        // not about where it appears. Only declarations were copying, so `b = a` aliased and
        // `b.set(0, 999)` changed `a` as well.
        // ...AND THE TARGET IS WHAT SAYS WHETHER IT COPIES. `T* f = x` shares, `T f = x` copies:
        // that is the whole rule, and it is a fact about the LEFT side. Asking only the right one
        // deep-copied `this.direct = this` on a `Owner*` field -- see `declaredTargetDepth`.
        if (value != kNoValue && namesExistingObject(s.value.get()) &&
            pointerDepthOf(value) == 0 && declaredTargetDepth(s.target.get()) == 0) {
            if (const std::string cls = classNameOf(declaredName(value));
                isCopyableClass(cls) && named_.count(cls) != 0) {
                // AND THE FRAME HOLDS IT WHEN THE FRAME IS WHAT NAMES IT. `b = a` where `b` is a
                // local dies with the scope, so the copy is a frame slot; a field or an element
                // outlives the frame and takes the heap. Answering `heap` for both leaked one
                // allocation per assignment, and an assignment can be inside a loop.
                bool intoLocal = false;
                if (auto* id = dynamic_cast<const ast::IdentifierExpr*>(s.target.get())) {
                    intoLocal = locals_.count(id->name) != 0;
                }
                value = copyValueStruct(value, cls, s.loc, /*heap=*/!intoLocal);
            }
        }
        const ValueId addr = addressOf(s.target.get());
        if (addr == kNoValue) {
            // A TARGET THIS PASS CANNOT ADDRESS. The three it can are a local, a field and an
            // element; anything else -- a static through a namespace, a property with a setter --
            // is a real gap and says which.
            std::string what;
            if (!flatten(s.target.get(), &what)) {
                what = "expression";
            }
            gap("AssignStmt(cannot address " + what + ")", s.loc);
            return;
        }
        if (value == kNoValue) {
            gap("AssignStmt(value did not lower)", s.loc);
            return;
        }
        // THE VALUE IS CONVERTED TO WHAT THE TARGET HOLDS. A store of an `i32` into an `i64` slot
        // wrote four bytes and left the other four as they were; the backend's `coerce` papers over
        // some of it but only where it happens to look, and a store is not one of those places.
        // Doing it here means the conversion is a `trunc`/`extend` in the IR -- something the passes
        // can see and fold -- rather than a width mismatch nobody records.
        //
        // §21: ASSIGNING A STRING TO A LOCAL COPIES IT, AND RELEASES WHAT WAS THERE. Both halves
        // matter and they fail differently: without the copy the target shares the source's buffer
        // and whichever is released first leaves the other holding freed memory; without the
        // release the buffer the target used to own is lost, and `s = "a"; s = "b";` in a loop
        // grows for ever.
        //
        // Only a slot this lowering KNOWS to own a String is released -- a parameter is not one,
        // the caller owns what it passed. Elements and fields are copied on their own paths above,
        // where an `IndexExpr` target returns from before ever reaching here.
        if (stringSlots_.count(addr) != 0) {
            TypeTable& tt = out_.module.types;
            callExternal("__polaron_str_free", tt.voidType(), {tt.ptrType()},
                         {loadFrom(addr, s.loc)}, s.loc);
            value = ownedString(value, s.loc);
        } else if (isStringNamed(assignedFieldType(s.target.get()))) {
            // A FIELD OWNS ITS STRING TOO. `this.message = message` inside a constructor was
            // keeping the caller's buffer, so the object outlived what it pointed at the moment
            // anything released the caller's local. `IoException.IoException` is where this showed:
            // two copies in the other backend, none here.
            //
            // AND OVERWRITING ONE RELEASES THE PREVIOUS -- the second half of the protocol the
            // runtime states, and the half this omitted. Without it `this.field = producer()` in a
            // loop grows for ever: every iteration allocates a copy and abandons the one before.
            //
            // What made it look unsafe was not knowing what the field held. It holds one of two
            // things and both are fine: a String field is null-defaulted and `new String[n]()` is
            // zero-initialised, and `__polaron_str_free` is null-safe; anything else came through
            // this same branch and is a copy this owns. The copy is taken BEFORE the release so a
            // self-assign `f = f` stays correct -- the fresh buffer is distinct from the old one.
            TypeTable& tt = out_.module.types;
            value = ownedString(value, s.loc);
            callExternal("__polaron_str_free", tt.voidType(), {tt.ptrType()},
                         {loadFrom(addr, s.loc)}, s.loc);
        }
        storeInto(addr, value, s.loc);
    }

    // A field's declared type, looked up on `owner` and then on what `owner` extends -- the table
    // is keyed by the class that DECLARED the field, so a subclass asking about an inherited one
    // finds nothing at its own name. Empty for a pointer field: `String* s` shares by declaration,
    // and copying it would be answering a question the author already answered.
    std::string fieldTypeUp(std::string owner, const std::string& field) const {
        for (int hops = 0; hops < 32 && !owner.empty(); ++hops) {
            if (const auto held = fieldTypeName_.find(owner + "." + field);
                held != fieldTypeName_.end()) {
                return held->second.pointerDepth != 0 ? std::string() : held->second.name;
            }
            const ast::ClassDecl* up = findClass(owner);
            owner = up != nullptr ? up->superclass : std::string();
        }
        return {};
    }

    // The declared type of an assignment's target when that target NAMES A FIELD, resolved from
    // the AST rather than from the lowered address -- re-lowering the object expression here would
    // emit its side effects a second time.
    //
    // IT USED TO ASK ONLY ABOUT `<local>.<field>`, which is one of the four ways a field is named
    // and not the one the census caught. `Table.tag = "hello"` inside an `onClassLoad` names a
    // CLASS-LEVEL static: the qualifier is not a local, so the question answered "not a field" and
    // the store shared the literal's buffer instead of owning a copy of it. `Test.__onClassLoad`
    // came out as two bare stores against the other path's two copies -- the D1 line of the census.
    //
    // All four now: a local's field, `this`'s field, a field named bare inside its own class, and
    // a static named through its class. Inherited fields included, which the first version also
    // missed.
    std::string assignedFieldType(const ast::Expr* target) const {
        if (const auto* member = dynamic_cast<const ast::MemberExpr*>(target)) {
            if (std::string byReceiver =
                    fieldTypeUp(staticClassOfExpr(member->object.get()), member->member);
                !byReceiver.empty()) {
                return byReceiver;
            }
            // Not a value, then -- so the qualifier may be naming a CLASS. Asked second, because a
            // local whose name happens to match a class's is still a local.
            std::string owner;
            if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(member->object.get())) {
                owner = id->name;
            } else {
                std::string chain;
                if (flatten(member->object.get(), &chain)) {
                    const size_t dot = chain.rfind('.');
                    owner = dot == std::string::npos ? chain : chain.substr(dot + 1);
                }
            }
            if (const ast::ClassDecl* c = owner.empty() ? nullptr : findClass(owner); c != nullptr) {
                return fieldTypeUp(keyOfClass(*c), member->member);
            }
            return {};
        }
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(target)) {
            // A LOCAL IS `stringSlots_`'S BUSINESS, and it releases the old value as well as
            // copying the new one -- answering here would make the field branch run instead.
            if (locals_.count(id->name) != 0) {
                return {};
            }
            return fieldTypeUp(selfClassName_, id->name);
        }
        return {};
    }

    void lowerIncDec(const ast::IncDecStmt& s) {
        const ValueId addr = addressOf(s.target.get());
        if (addr == kNoValue) {
            gap("IncDecStmt(untranslatable target)", s.loc);
            return;
        }
        const ValueId cur = loadFrom(addr, s.loc);
        // `c++` OVER A CLASS THAT DECLARES `operator ++` calls it and stores what it returns. The
        // integer path added one to a pointer -- `struct_incr` counted to zero because every step
        // moved an address instead of a number.
        if (const std::string cls = classNameOf(declaredName(cur)); !cls.empty()) {
            const std::string want = s.isIncrement ? "operator++" : "operator--";
            if (const Function* op = resolveKey(cls + "." + want)) {
                storeInto(addr, emitCall(op, {cur}, s.loc), s.loc);
                return;
            }
        }
        // `p++` ON A POINTER STEPS BY ONE ELEMENT (spec 27), not by one byte. The integer path
        // below added the literal 1 to an address, so `p++` over an `int[]` moved a quarter of an
        // element and every read through it afterwards was misaligned garbage.
        if (isRawPointer(cur)) {
            const Type* elem = pointeeOf(cur);
            const int64_t stride = static_cast<int64_t>(
                std::max<uint64_t>(1, elem != nullptr ? elem->facts.size : 1));
            const ValueId moved =
                rawOffset(cur, constLong(s.isIncrement ? stride : -stride, s.loc), s.loc);
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(moved);
            put.operands.push_back(addr);
            put.loc = s.loc;
            emit(std::move(put));
            return;
        }
        Inst one;
        one.op = Op::ConstInt;
        one.type = fn_->value(cur)->type;
        one.imm = 1;
        const ValueId oneV = emit(std::move(one));

        Inst step;
        step.op = s.isIncrement ? Op::AddChecked : Op::SubChecked;
        step.type = fn_->value(cur)->type;
        step.operands.push_back(cur);
        step.operands.push_back(oneV);
        step.loc = s.loc;
        const ValueId next = emit(std::move(step));

        Inst st;
        st.op = Op::Store;
        st.operands.push_back(next);
        st.operands.push_back(addr);
        st.loc = s.loc;
        emit(std::move(st));
    }

    // `for (T x in xs)` is the indexed loop it desugars to, written out here rather than left to the
    // backend: the index, the bound, the element load and the bounds guard are all things §11's
    // passes want to see as ordinary instructions. A loop shape the optimiser has to recognise is a
    // loop shape it will sometimes fail to recognise.
    // `for (x in it)` OVER AN ITERATOR: ask, take, repeat. No snapshot and no index -- which is
    // what lets the sequence be infinite, and what makes a lazy stream a sequence at all.
    void lowerForeachIterable(const ast::ForeachStmt& s, ValueId subject, const std::string& cls) {
        ValueId walker = subject;
        std::string walkerClass = cls;
        // WHO OWNS THE ITERATOR? The loop does whenever it is FRESH -- either the loop called
        // `iterator()` itself, or the subject is an expression that minted one: a generator, a
        // `new`, an explicit `list.iterator()`. A returned object is the caller's to own, and here
        // the caller is this loop. A subject that is a NAME -- a variable, a field -- is borrowed
        // and has to outlive the loop, so it is left alone.
        //
        // Nothing was disposing either kind. `generator.pol` runs three `foreach`es over
        // generators and exited holding all three: 304 bytes in 12 blocks against the other path's
        // 112 in 5, with identical output, which is why the corpus called it correct.
        bool ownsWalker = dynamic_cast<const ast::CallExpr*>(s.iterable.get()) != nullptr ||
                          dynamic_cast<const ast::NewExpr*>(s.iterable.get()) != nullptr;
        // `iterator()` MINTS ONE; a class that already answers `hasNext()` IS one.
        if (const Function* mint = resolveKey(cls + ".iterator")) {
            walker = emitCall(mint, {subject}, s.loc);
            if (auto named = returnName_.find(mint->key); named != returnName_.end()) {
                noteName(walker, named->second.name, named->second.pointerDepth);
                walkerClass = classNameOf(named->second.name);
            }
            ownsWalker = true;   // this loop made it; the subject it came from is untouched
        }
        const Function* more = resolveKey(walkerClass + ".hasNext");
        const Function* take = resolveKey(walkerClass + ".next");
        if (walker == kNoValue || more == nullptr || take == nullptr) {
            gap("ForeachStmt(iterable without hasNext/next: " + walkerClass + ")", s.loc);
            return;
        }

        // REGISTERED AS A SCOPE OBJECT, not released at the loop's end block: that way it is
        // disposed on EVERY exit -- falling off the end, `break`, `return`, or an exception passing
        // through. `generator.pol`'s second loop leaves by `break`, which an end-block release
        // would miss, and its third leaves normally; both have to give the generator back.
        //
        // The slot is what the teardown reads, and it starts null so a path that never reached the
        // loop destroys nothing.
        size_t walkerDepth = scoped_.size();
        if (ownsWalker && !walkerClass.empty() && findClass(walkerClass) != nullptr) {
            const ValueId held = allocaFor("fe.it", out_.module.types.ptrType());
            zeroSlotAtEntry(held, s.loc);
            Inst keepIt;
            keepIt.op = Op::Store;
            keepIt.operands.push_back(walker);
            keepIt.operands.push_back(held);
            keepIt.loc = s.loc;
            emit(std::move(keepIt));
            scoped_.push_back(ScopedObject{held, walkerClass, /*heap=*/true});
            if (!handlers_.empty()) {
                unwindObjects_.push_back(ScopedObject{held, walkerClass, /*heap=*/true});
            }
        }
        const BlockId head = fn_->addBlock(fresh("iter"));
        const BlockId body = fn_->addBlock(fresh("iterbody"));
        const BlockId done = fn_->addBlock(fresh("iterdone"));
        gotoIfOpen(head);

        here_ = head;
        // VIRTUAL WHEN THE OBJECT DECIDES: the walker is usually an interface-typed value, so the
        // implementation is its own to choose.
        const ValueId again = callMethodOn(walker, walkerClass, "hasNext", more, s.loc);
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(again);
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{done, {}});
        br.loc = s.loc;
        emit(std::move(br));

        here_ = body;
        const ValueId element = callMethodOn(walker, walkerClass, "next", take, s.loc);
        const Type* held = element != kNoValue ? fn_->value(element)->type
                                               : out_.module.types.intType(32);
        const ValueId slot = allocaFor(s.varName, held);
        if (auto named = returnName_.find(take->key); named != returnName_.end()) {
            noteName(slot, named->second.name, named->second.pointerDepth);
        }
        Inst keep;
        keep.op = Op::Store;
        keep.operands.push_back(element);
        keep.operands.push_back(slot);
        keep.loc = s.loc;
        emit(std::move(keep));

        loops_.push_back(LoopTargets{done, head, takeLoopLabel(), scoped_.size(), deferred_.size()});
        lowerScope(s.body);
        loops_.pop_back();
        gotoIfOpen(head);

        here_ = done;
        // THE ITERATOR IS DISPOSED IN `done`, which is where BOTH ordinary exits arrive: the
        // condition going false and every `break` in the body, since `done` is what `break` jumps
        // to. A `return` inside the body tears down the whole scope stack and takes it there
        // instead; an exception takes the unwind copy. Deliberately ABOVE the depth the loop
        // recorded, so a `continue` -- which leaves the body but not the loop -- walks past it.
        if (scoped_.size() > walkerDepth) {
            destroyScoped(walkerDepth, s.loc);
            scoped_.resize(walkerDepth);
        }
    }

    // One call on an object, dispatched through its table when the method might be overridden and
    // called by name when it cannot be.
    ValueId callMethodOn(ValueId receiver, const std::string& cls, const std::string& method,
                         const Function* target, SourceLocation loc) {
        if (!cls.empty() && needsDispatch(cls, method)) {
            TypeTable& tt = out_.module.types;
            Inst load;
            load.op = Op::VtableLoad;
            load.type = tt.ptrType();
            load.operands.push_back(receiver);
            load.imm = slotFor(method);
            load.text = cls;
            load.loc = loc;
            Inst call;
            call.op = Op::CallIndirect;
            call.type = target != nullptr && target->signature != nullptr
                            ? target->signature->element
                            : tt.intType(32);
            call.operands.push_back(emit(std::move(load)));
            call.operands.push_back(receiver);
            call.loc = loc;
            const ValueId answer = emit(std::move(call));
            noteStringResult(target, answer);
            return answer;
        }
        return emitCall(target, {receiver}, loc);
    }

    void lowerForeach(const ast::ForeachStmt& s) {
        // `for (int i in 0..10)` is a COUNTED LOOP, not a sequence walk: there is nothing to index
        // and nothing to bounds-check. Lowered as its own shape so the passes see a plain
        // comparison against a constant rather than a length load they cannot fold.
        if (auto* r = dynamic_cast<const ast::RangeExpr*>(s.iterable.get())) {
            lowerRangeLoop(s, *r);
            return;
        }
        ValueId seq = lowerExpr(s.iterable.get());
        // A COLLECTION IS ITERATED THROUGH ITS `toArray()` (spec 34): the loop walks a SNAPSHOT,
        // which is what makes removing from the collection inside the loop well defined. Any class
        // that has the method is iterable; this pass had no case for it at all and walked the
        // OBJECT as if it were an array, so `for (int x in nums)` read the ArrayList's first field
        // as a length and its second as element zero.
        if (seq != kNoValue) {
            const std::string cls = classNameOf(declaredName(seq));
            // AN `Iterable` IS WALKED LAZILY (spec 9.2): a class with no `toArray` but with an
            // `iterator()` -- or one that IS an iterator, with `hasNext()`/`next()` -- yields one
            // element at a time, so an infinite or expensive sequence works. There is no snapshot
            // to take and nothing to index; this pass had neither case and walked the OBJECT as if
            // it were an array.
            if (!cls.empty() && resolveKey(cls + ".toArray") == nullptr &&
                (resolveKey(cls + ".iterator") != nullptr ||
                 (resolveKey(cls + ".hasNext") != nullptr &&
                  resolveKey(cls + ".next") != nullptr))) {
                lowerForeachIterable(s, seq, cls);
                return;
            }
            if (!cls.empty()) {
                if (const Function* snapshot = resolveKey(cls + ".toArray")) {
                    const ValueId taken = emitCall(snapshot, {seq}, s.loc);
                    if (taken != kNoValue) {
                        seq = taken;
                        if (auto it = returnName_.find(snapshot->key); it != returnName_.end()) {
                            noteName(seq, it->second.name, it->second.pointerDepth);
                        }
                    }
                }
            }
        }
        if (seq == kNoValue) {
            // NO SEQUENCE, NO LOOP. Emitting the index arithmetic around a `gep` with no base
            // produces a module that fails verifier rule 6 -- a malformed loop over nothing, which
            // is worse than an honest gap because it reads as work that was done.
            gap("ForeachStmt(iterable did not lower)", s.loc);
            for (const auto& inner : s.body.statements) {
                lowerStmt(inner.get());
            }
            return;
        }
        const Type* i32 = out_.module.types.intType(32);

        Inst zero;
        zero.op = Op::ConstInt;
        zero.type = i32;
        zero.imm = 0;
        const ValueId start = emit(std::move(zero));
        const ValueId idx = allocaFor(s.indexName.empty() ? fresh("i") : s.indexName, i32);
        Inst st0;
        st0.op = Op::Store;
        st0.operands.push_back(start);
        st0.operands.push_back(idx);
        emit(std::move(st0));

        const BlockId head = fn_->addBlock(fresh("each"));
        const BlockId body = fn_->addBlock(fresh("eachbody"));
        const BlockId step = fn_->addBlock(fresh("eachstep"));
        const BlockId done = fn_->addBlock(fresh("eachdone"));
        gotoIfOpen(head);

        here_ = head;
        const ValueId i = loadFrom(idx, s.loc);
        // The bound comes off the sequence itself. A `slice<T>` carries its length; an inline array
        // has it in the type, and the constant folder collapses the comparison outright.
        Inst len;
        len.op = Op::Gep;
        len.type = out_.module.types.ptrType();
        len.text = "length";
        if (seq != kNoValue) {
            len.operands.push_back(seq);
        }
        const ValueId lenAddr = emit(std::move(len));
        // The header holds a 64-bit length; the index is 32. Narrowed here so the comparison the
        // guard eliminator matches on has both sides the same width.
        slotType_[lenAddr] = out_.module.types.intType(64);
        const ValueId wide = loadFrom(lenAddr, s.loc);
        Inst narrow;
        narrow.op = Op::Trunc;
        narrow.type = i32;
        narrow.operands.push_back(wide);
        narrow.loc = s.loc;
        const ValueId bound = emit(std::move(narrow));

        Inst cmp;
        cmp.op = Op::CmpLtS;
        cmp.type = out_.module.types.boolType();
        cmp.operands.push_back(i);
        cmp.operands.push_back(bound);
        cmp.loc = s.loc;
        const ValueId more = emit(std::move(cmp));

        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(more);
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{done, {}});
        br.loc = s.loc;
        emit(std::move(br));

        here_ = body;
        if (seq != kNoValue) {
            Inst guard;
            guard.op = Op::GuardBounds;
            guard.operands.push_back(i);
            guard.operands.push_back(seq);
            guard.loc = s.loc;
            emit(std::move(guard));

            // THE SEQUENCE'S TYPE, not `ptr`. A `gep` typed `ptr` tells the backend nothing about
            // how wide an element is or whether there is a length header to step over, so every
            // `foreach` walked four bytes at a time from offset zero: over a `long[]` it read each
            // value's low half and the length header as the first element. `dot=200` came out `80`.
            Inst at;
            at.op = Op::Gep;
            at.type = fn_->value(seq)->type;
            at.operands.push_back(seq);
            at.operands.push_back(i);
            at.loc = s.loc;
            const ValueId slot = emit(std::move(at));
            const Type* elem = elementOf(fn_->value(seq)->type);
            slotType_[slot] = elem;
            const ValueId v = loadFrom(slot, s.loc);
            const ValueId hold = allocaFor(s.varName, elem);
            // WHAT THE ELEMENT IS DECLARED AS, kept on its slot. Without it `for (Annotation a in
            // anns)` bound a name with no class at all, and `a.name()` resolved by BARE NAME to
            // whichever class in the program declares a `name` -- it reached `Xml.name`, with an
            // annotation token passed as an XML node. The declaration says `Annotation`; the loop
            // was simply throwing it away.
            const DeclaredType spelled =
                s.isVar ? elementDeclOf(declaredName(seq))
                        : DeclaredType{ast::mangleGeneric(s.elemType.name, s.elemType.typeArgs),
                                       s.elemType.pointerDepth > 0 ? s.elemType.pointerDepth
                                                                   : (s.elemType.isPointer ? 1 : 0)};
            if (!spelled.name.empty()) {
                noteName(hold, spelled.name, spelled.pointerDepth);
            }
            Inst keep;
            keep.op = Op::Store;
            keep.operands.push_back(v);
            keep.operands.push_back(hold);
            emit(std::move(keep));
        }
        loops_.push_back(LoopTargets{done, step, takeLoopLabel(), scoped_.size(), deferred_.size()});
        lowerScope(s.body);   // its own `defer`s run when it ends, not when the method does
        loops_.pop_back();
        gotoIfOpen(step);

        here_ = step;
        const ValueId cur = loadFrom(idx, s.loc);
        Inst one;
        one.op = Op::ConstInt;
        one.type = i32;
        one.imm = 1;
        const ValueId oneV = emit(std::move(one));
        Inst inc;
        inc.op = Op::AddChecked;
        inc.type = i32;
        inc.operands.push_back(cur);
        inc.operands.push_back(oneV);
        const ValueId next = emit(std::move(inc));
        Inst back;
        back.op = Op::Store;
        back.operands.push_back(next);
        back.operands.push_back(idx);
        emit(std::move(back));
        gotoIfOpen(head);

        here_ = done;
    }

    void lowerRangeLoop(const ast::ForeachStmt& s, const ast::RangeExpr& r) {
        const Type* i32 = out_.module.types.intType(32);
        const ValueId from = lowerExpr(r.start.get());
        const ValueId slot = allocaFor(s.varName, i32);
        if (from != kNoValue) {
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(from);
            st.operands.push_back(slot);
            st.loc = s.loc;
            emit(std::move(st));
        }
        // `for (index k, int n in 5..=8)` HAS TWO VARIABLES: `n` walks the range and `k` counts
        // from zero. This loop only ever made the first, so the index name resolved to the value
        // and `last = k` recorded 8 where the program means 3. They are not the same number and
        // only coincide when the range starts at zero -- which is why it read as correct.
        const ValueId counter =
            s.indexName.empty() ? kNoValue : allocaFor(s.indexName, i32);
        if (counter != kNoValue) {
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(constInt(0, 32, s.loc));
            st.operands.push_back(counter);
            st.loc = s.loc;
            emit(std::move(st));
        }

        const BlockId head = fn_->addBlock(fresh("range"));
        const BlockId body = fn_->addBlock(fresh("rangebody"));
        const BlockId step = fn_->addBlock(fresh("rangestep"));
        const BlockId done = fn_->addBlock(fresh("rangedone"));
        gotoIfOpen(head);

        here_ = head;
        const ValueId i = loadFrom(slot, s.loc);
        const ValueId to = lowerExpr(r.end.get());
        Inst cmp;
        cmp.op = r.inclusive ? Op::CmpLeS : Op::CmpLtS;
        cmp.type = out_.module.types.boolType();
        cmp.operands.push_back(i);
        if (to != kNoValue) {
            cmp.operands.push_back(to);
        }
        cmp.loc = s.loc;
        const ValueId more = emit(std::move(cmp));

        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(more);
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{done, {}});
        br.loc = s.loc;
        emit(std::move(br));

        here_ = body;
        loops_.push_back(LoopTargets{done, step, takeLoopLabel(), scoped_.size(), deferred_.size()});   // where break/continue go
        lowerScope(s.body);   // its own `defer`s run when it ends, not when the method does
        loops_.pop_back();
        gotoIfOpen(step);

        here_ = step;
        const ValueId cur = loadFrom(slot, s.loc);
        const ValueId by = r.step != nullptr ? lowerExpr(r.step.get()) : constInt(1, s.loc);
        Inst inc;
        inc.op = Op::AddChecked;
        inc.type = i32;
        inc.operands.push_back(cur);
        if (by != kNoValue) {
            inc.operands.push_back(by);
        }
        inc.loc = s.loc;
        const ValueId next = emit(std::move(inc));
        Inst back;
        back.op = Op::Store;
        back.operands.push_back(next);
        back.operands.push_back(slot);
        emit(std::move(back));
        if (counter != kNoValue) {
            // ...and the counter advances by ONE whatever the range's step is: it counts
            // iterations, not values.
            Inst bump;
            bump.op = Op::AddWrap;
            bump.type = i32;
            bump.operands.push_back(loadFrom(counter, s.loc));
            bump.operands.push_back(constInt(1, 32, s.loc));
            bump.loc = s.loc;
            Inst keep;
            keep.op = Op::Store;
            keep.operands.push_back(emit(std::move(bump)));
            keep.operands.push_back(counter);
            keep.loc = s.loc;
            emit(std::move(keep));
        }
        gotoIfOpen(head);

        here_ = done;
    }

    ValueId asBoolean(ValueId v, SourceLocation loc) {
        if (v == kNoValue) {
            return v;
        }
        const Type* t = fn_->value(v)->type;
        if (t != nullptr && t->kind == TypeKind::Bool) {
            return v;
        }
        Inst zero;
        zero.op = Op::ConstInt;
        zero.type = t != nullptr ? t : out_.module.types.intType(32);
        zero.imm = 0;
        zero.loc = loc;
        const ValueId z = emit(std::move(zero));

        Inst ne;
        ne.op = Op::CmpNe;
        ne.type = out_.module.types.boolType();
        ne.operands.push_back(v);
        ne.operands.push_back(z);
        ne.loc = loc;
        return emit(std::move(ne));
    }

    // ---- the small arithmetic the array machinery needs ----

    ValueId constLong(int64_t v, SourceLocation loc) {
        Inst in;
        in.op = Op::ConstInt;
        in.type = out_.module.types.intType(64);
        in.imm = v;
        in.loc = loc;
        return emit(std::move(in));
    }

    ValueId widenToLong(ValueId v, SourceLocation loc) {
        const Type* t = fn_->value(v)->type;
        const bool address = t != nullptr && t->kind == TypeKind::Addr;   // see `widen`: no sign
        if (t != nullptr && (t->kind == TypeKind::Int || address) && t->bits == 64) {
            return v;
        }
        Inst in;
        in.op = address ? Op::ExtendU : Op::ExtendS;
        in.type = address ? out_.module.types.addrType(64) : out_.module.types.intType(64);
        in.operands.push_back(v);
        in.loc = loc;
        return emit(std::move(in));
    }

    ValueId mulLong(ValueId v, int64_t by, SourceLocation loc) {
        const ValueId k = constLong(by, loc);
        Inst in;
        in.op = Op::MulChecked;
        in.type = out_.module.types.intType(64);
        in.operands.push_back(v);
        in.operands.push_back(k);
        in.loc = loc;
        return emit(std::move(in));
    }

    ValueId addLong(ValueId v, int64_t by, SourceLocation loc) {
        const ValueId k = constLong(by, loc);
        Inst in;
        in.op = Op::AddChecked;
        in.type = out_.module.types.intType(64);
        in.operands.push_back(v);
        in.operands.push_back(k);
        in.loc = loc;
        return emit(std::move(in));
    }

    Function* declareExternalTyped(const std::string& key, const Type* ret,
                                   std::vector<const Type*> params) {
        if (Function* had = out_.module.find(key)) {
            return had;
        }
        std::vector<Field> fields;
        for (const Type* p : params) {
            Field f;
            f.type = p;
            fields.push_back(f);
        }
        Function* fn = out_.module.addFunction(key,
                                               out_.module.types.fnType(ret, std::move(fields)));
        fn->linkage = Linkage::External;
        fn->conv = Conv::Cdecl;
        fn->symbol = key;
        fn->params.assign(params.size(), {});
        return fn;
    }

    // A STATIC, as a module-level global. Declared on first mention, because a static reached from
    // another bundle has no declaration this pass ever sees -- and a global the linker resolves is
    // the honest shape for it.
    // `Shared.before` -> `Main.App.Shared.before` where that is what the class is filed under. The
    // last dot separates the field from its owner; everything before it is a class name, which may
    // itself be qualified in the source and may be keyed by path in the module.
    std::string resolveStaticKey(const std::string& spelled) const {
        const size_t dot = spelled.rfind('.');
        if (dot == std::string::npos) {
            return spelled;
        }
        std::string owner = spelled.substr(0, dot);
        if (const size_t inner = owner.rfind('.'); inner != std::string::npos) {
            owner = owner.substr(inner + 1);
        }
        const std::string key = resolveClassKey(owner);
        return key == owner ? spelled : key + spelled.substr(dot);
    }

    // Whether a module-level thing of this name has been DECLARED. Asked where the answer decides
    // how a call is read, and it must not be `globalSlot`, which declares one on demand: a question
    // that creates its own answer would make every unresolved qualified name into a static field.
    bool globalExists(const std::string& spelled) const {
        const std::string name = resolveStaticKey(spelled);
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                return true;
            }
        }
        return false;
    }

    // The address of a named module-level thing, emitted at the TOP of the function. Same insertion
    // the allocas use, and for the same reason: a value the whole body may read has to be defined
    // where the whole body can see it.
    ValueId constFnInEntry(const std::string& name, SourceLocation loc) {
        Block* entry = fn_ != nullptr ? fn_->block(entryBlock_) : nullptr;
        if (entry == nullptr) {
            Inst addr;
            addr.op = Op::ConstFn;
            addr.type = out_.module.types.ptrType();
            addr.text = name;
            addr.loc = loc;
            return emit(std::move(addr));
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = name;
        addr.loc = loc;
        const ValueId slot = fn_->addValue(out_.module.types.ptrType(), ValueOrigin::Instruction,
                                           entryBlock_, allocaAt_, name);
        addr.result = slot;
        entry->insts.insert(entry->insts.begin() + static_cast<long>(allocaAt_), std::move(addr));
        ++allocaAt_;
        // The insertion moved everything after it, so the entry block's value table moves too --
        // rule 1 checks exactly that agreement.
        for (size_t i = 0; i < entry->insts.size(); ++i) {
            const ValueId r = entry->insts[i].result;
            if (r != kNoValue && r < fn_->values.size()) {
                fn_->values[r].indexInBlock = static_cast<uint32_t>(i);
            }
        }
        return slot;
    }

    ValueId globalSlot(const std::string& spelled, SourceLocation loc) {
        // THE OWNER IS RESOLVED TO ITS KEY, the same way every other lookup resolves one. Where two
        // classes answer to one name, `declareStatic` files the global under the full path -- and
        // the program still writes `Shared.before`, so taking the source spelling as the key
        // INVENTED A SECOND GLOBAL of the same name under the short one. `barrier_rwlock` had a
        // `@Main.App.Shared.before` that `onClassLoad` filled and a `@Shared.before` that every
        // read of it saw: the object was allocated, and the threads dereferenced null.
        const std::string name = resolveStaticKey(spelled);
        auto it = statics_.find(name);
        if (it != statics_.end()) {
            return it->second;
        }
        bool have = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                have = true;
                break;
            }
        }
        if (!have) {
            Global g;
            g.name = name;
            g.type = out_.module.types.intType(64);
            g.linkage = Linkage::External;
            g.zeroInit = true;
            out_.module.globals.push_back(std::move(g));
        }
        // ...AND IT IS TAKEN IN THE ENTRY BLOCK, not wherever it was first wanted.
        //
        // The address is MEMOISED for the body -- one instruction per global rather than one per
        // mention -- and a memo hands back a value id, which in SSA belongs to the block it was
        // emitted in. First wanted inside a branch, it was reused after the join, and the reuse is
        // not dominated by the definition. That is verifier rule 1, and it never fired on the 844
        // samples: they are small enough that the first mention of a static is almost always on the
        // straight path. pico is 66722 lines and produced 295 of them, every one this shape --
        // `Tone.HighestDivisor` taken inside `if (this.hz <= 0) { return ... }` and read again two
        // ifs later.
        //
        // The entry block is where it belongs anyway: the address of a global is a CONSTANT, so
        // hoisting it is always valid, and there it dominates every use by construction.
        const ValueId slot = constFnInEntry(name, loc);
        // THE GLOBAL'S OWN TYPE when the module has one. This always said `i64`, which is a guess
        // that happens to be right for an address and wrong for everything else -- a `double`
        // static read back as an integer, and a 32-bit one read eight bytes.
        const Type* held = out_.module.types.intType(64);
        for (const Global& g : out_.module.globals) {
            if (g.name == name && g.type != nullptr) {
                held = g.type;
                break;
            }
        }
        slotType_[slot] = held;
        // ...AND THE TYPE AS WRITTEN, which the interned one cannot answer. A `String` static is a
        // `ptr` like every other object, so a read of it arrived with no class at all and the
        // `println` beside it passed the OBJECT to `%s` instead of the `data` inside it:
        // `static_alloc_init` printed a blank line where the program prints `hello`.
        if (auto declared = fieldTypeName_.find(name); declared != fieldTypeName_.end()) {
            noteName(slot, declared->second.name, declared->second.pointerDepth);
        }
        statics_[name] = slot;
        return slot;
    }

    ValueId undefOf(const Type* t, SourceLocation loc) {
        Inst u;
        u.op = Op::Undef;
        u.type = t != nullptr ? t : out_.module.types.intType(32);
        u.loc = loc;
        return emit(std::move(u));
    }

    ValueId constInt(int64_t v, SourceLocation loc) {
        Inst in;
        in.op = Op::ConstInt;
        in.type = out_.module.types.intType(32);
        in.imm = v;
        in.loc = loc;
        return emit(std::move(in));
    }

    const Type* elementOf(const Type* t) {
        if (t == nullptr) {
            return out_.module.types.intType(32);
        }
        if (t->kind == TypeKind::Slice || t->kind == TypeKind::Array) {
            return t->element;
        }
        return out_.module.types.intType(32);
    }

    void lowerFor(const ast::ForStmt& s) {
        if (s.init != nullptr) {
            lowerStmt(s.init.get());
        }
        const BlockId head = fn_->addBlock(fresh("for"));
        const BlockId body = fn_->addBlock(fresh("forbody"));
        const BlockId step = fn_->addBlock(fresh("forstep"));
        const BlockId done = fn_->addBlock(fresh("fordone"));
        gotoIfOpen(head);

        here_ = head;
        if (s.cond != nullptr) {
            const ValueId cond = lowerExpr(s.cond.get());
            Inst br;
            br.op = Op::BrCond;
            br.loc = s.loc;
            if (cond != kNoValue) {
                br.operands.push_back(cond);
            }
            br.edges.push_back(Edge{body, {}});
            br.edges.push_back(Edge{done, {}});
            emit(std::move(br));
        } else {
            gotoIfOpen(body);
        }

        here_ = body;
        loops_.push_back(LoopTargets{done, step, takeLoopLabel(), scoped_.size(), deferred_.size()});   // where break/continue go
        lowerScope(s.body);   // its own `defer`s run when it ends, not when the method does
        loops_.pop_back();
        gotoIfOpen(step);

        here_ = step;
        if (s.update != nullptr) {
            lowerStmt(s.update.get());
        }
        gotoIfOpen(head);

        here_ = done;
    }

    // ---- §7.10: `try` / `catch` / `finally`, with the unwind edges ----
    //
    // A call inside a `try` becomes `call.unwind`: two successors, the normal one and a LANDING
    // block. The landing block starts with `landing`, which yields the exception, and then the
    // handlers test it in order; a handler that matches runs, and one that does not falls through to
    // `resume`, which continues unwinding to the caller.
    //
    // The edges are the whole point. Lowered as straight-line blocks -- which is what this did
    // before -- a program that throws never reaches its own `catch`, and nothing says so: the
    // handler is emitted, looks lowered, and is unreachable. Verifier rule 19 exists for exactly
    // that shape and now has something to check.
    // The class named by a `catch (T e)` clause, without pointers or brackets.
    std::string baseNameOf(const ast::TypeRef& t) const {
        return classNameOf(ast::mangleGeneric(t.name, t.typeArgs));
    }

    // `is this object a T?`, answered by comparing its table against T's and against every class
    // that extends T. A class with no table -- nothing to compare -- means "anything", which is
    // what `catch (Exception e)` over a non-polymorphic hierarchy has to mean.
    ValueId matchesCatchType(ValueId exc, const std::string& want, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        std::vector<std::string> accepted;
        for (const std::string& name : hasVtable_) {
            for (std::string walk = name; !walk.empty();) {
                if (walk == want) {
                    accepted.push_back(name);
                    break;
                }
                const ast::ClassDecl* up = findClass(walk);
                walk = up != nullptr ? up->superclass : std::string();
            }
        }
        // SORTED, because `hasVtable_` is a hash set and its order is not the same twice. A
        // compiler whose output depends on a hash seed is one whose bugs cannot be reproduced.
        std::sort(accepted.begin(), accepted.end());
        if (want.empty() || accepted.empty()) {
            Inst yes;
            yes.op = Op::ConstBool;
            yes.type = tt.boolType();
            yes.imm = 1;
            yes.loc = loc;
            return emit(std::move(yes));
        }
        // Field zero of every reference class is its table pointer -- the same word the constructor
        // wrote and the same one a virtual call reads.
        Inst at;
        at.op = Op::Gep;
        at.type = tt.ptrType();
        at.operands.push_back(exc);
        at.imm = 0;
        at.loc = loc;
        const ValueId slot = emit(std::move(at));
        slotType_[slot] = tt.ptrType();
        const ValueId mine = loadFrom(slot, loc);

        ValueId match = kNoValue;
        for (const std::string& name : accepted) {
            Inst table;
            table.op = Op::ConstFn;
            table.type = tt.ptrType();
            table.text = name + ".vtable";
            table.loc = loc;
            Inst eq;
            eq.op = Op::CmpEq;
            eq.type = tt.boolType();
            eq.operands.push_back(mine);
            eq.operands.push_back(emit(std::move(table)));
            eq.loc = loc;
            const ValueId one = emit(std::move(eq));
            if (match == kNoValue) {
                match = one;
                continue;
            }
            Inst any;
            any.op = Op::Or;
            any.type = tt.boolType();
            any.operands.push_back(match);
            any.operands.push_back(one);
            any.loc = loc;
            match = emit(std::move(any));
        }
        return match;
    }

    void lowerTry(const ast::TryStmt& s) {
        const BlockId landing = fn_->addBlock(fresh("landing"));
        const BlockId after = fn_->addBlock(fresh("tried"));

        // Every call lowered inside the body gets this landing block as its unwind successor.
        //
        // THE BODY IS LOWERED HERE RATHER THAN THROUGH `lowerScope`, because its cleanup has to
        // happen TWICE: once at the closing brace, and once on the way out through the landing
        // block. A `defer` and a stack object's destructor are promises the language makes about
        // leaving the block, and an exception is a way of leaving it -- `exceptions_raii` prints
        // `dtor 2 / dtor 1` before its handler runs, and this pass printed neither.
        const size_t outerDefers = deferred_.size();
        const size_t outerObjects = scoped_.size();
        const size_t outerUnwindObjects = unwindObjects_.size();
        const size_t outerUnwindDefers = unwindDefers_.size();
        // A `finally` RUNS ON EVERY WAY OUT OF THE BODY, and `return` is one of them. Registered as
        // a deferred block for the duration of the body, because `return`, `break` and `continue`
        // already run the deferred list down to the depth they are leaving -- and that is exactly
        // the rule `finally` states. `withReturn` printed nothing at all where it prints
        // `finally-return`, because the only copies were on the fall-through and unwinding paths
        // and a `return` takes neither.
        const bool guarded = s.finallyBlock != nullptr;
        if (guarded) {
            deferred_.push_back(DeferSite{s.finallyBlock.get(), kNoValue});
        }
        // THE HANDLER'S DEPTH IS RECORDED ABOVE THE `finally`, on purpose: a `throw` out of the body
        // reaches the landing block, which emits its own copy, so running it from the deferred list
        // as well would print it twice -- which is exactly what `exceptions_finally` showed.
        handlers_.push_back(
            Handler{landing, outerObjects, outerDefers + (guarded ? 1u : 0u)});
        for (const auto& inner : s.body.statements) {
            lowerStmt(inner.get());
        }
        releaseStringTemps(s.body.loc);   // see the handler below: no `lowerScope` runs here
        handlers_.pop_back();
        // Everything the body created, at every depth: the unwinding copy needs the same things in
        // the same order, and by the time the closing braces have run the live stacks are empty.
        const std::vector<ScopedObject> unwound(unwindObjects_.begin() + outerUnwindObjects,
                                                unwindObjects_.end());
        const std::vector<DeferSite> deferredHere(unwindDefers_.begin() + outerUnwindDefers,
                                                  unwindDefers_.end());
        unwindObjects_.resize(outerUnwindObjects);
        unwindDefers_.resize(outerUnwindDefers);
        if (!blockClosed()) {
            // DOWN TO JUST ABOVE THE `finally`, which sits at `outerDefers` and is emitted below
            // instead: running it from the deferred list here as well would print it twice.
            runDeferred(s.body.loc, outerDefers + (guarded ? 1 : 0));
            destroyScoped(outerObjects, s.body.loc);
        }
        deferred_.resize(outerDefers);
        // SHRINK ONLY. A `delete` inside the scope may already have taken an object off the list,
        // so restoring to the remembered depth would GROW it with default-constructed entries and
        // the next teardown would run a destructor on a null slot of no class.
        if (scoped_.size() > outerObjects) {
            scoped_.resize(outerObjects);
        }

        // `finally` runs on the normal path here, and again on the unwinding one below: two copies
        // rather than one shared block, because the unwinding copy ends in `resume` and the normal
        // one falls through. A single block cannot do both.
        if (s.finallyBlock != nullptr) {
            for (const auto& inner : s.finallyBlock->statements) {
                lowerStmt(inner.get());
            }
        }
        gotoIfOpen(after);

        // ^landing(%exc): the handlers, in source order.
        here_ = landing;
        const ValueId exc = fn_->addValue(out_.module.types.ptrType(), ValueOrigin::Instruction,
                                          landing, 0, "exc");
        Inst land;
        land.op = Op::Landing;
        land.result = exc;
        land.type = out_.module.types.ptrType();
        land.loc = s.loc;
        fn_->block(landing)->insts.push_back(std::move(land));

        // THE BLOCK IS BEING LEFT, so everything it promised to do on the way out happens here
        // too -- innermost first, the same order the closing braces use, and each one guarded so a
        // scope that already ended normally is not torn down a second time.
        for (auto it = deferredHere.rbegin(); it != deferredHere.rend(); ++it) {
            runOneDefer(*it, /*guarded=*/true, s.loc);
        }
        destroyEach(unwound, s.loc);

        for (const ast::CatchClause& handler : s.catches) {
            const BlockId run = fn_->addBlock(fresh("catch"));
            const BlockId next = fn_->addBlock(fresh("nextcatch"));

            // WHICH EXCEPTION THIS CLAUSE TAKES, decided by the OBJECT'S TABLE. A thrown object is
            // a class instance whose field zero is its vtable pointer, and `catch (IOError e)`
            // matches when that pointer is `IOError`'s or one of its subclasses' -- a handful of
            // constant comparisons the optimiser folds, and no runtime call at all.
            //
            // The call this replaces was `__polaron_exception_is(exc, <type>)` with the TYPE
            // ARGUMENT MISSING: one operand handed to a two-parameter function, so the answer came
            // off the stack and which handler ran was whatever the frame happened to hold.
            const ValueId which = matchesCatchType(exc, baseNameOf(handler.type), s.loc);

            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(which);
            br.edges.push_back(Edge{run, {}});
            br.edges.push_back(Edge{next, {}});
            br.loc = s.loc;
            emit(std::move(br));

            here_ = run;
            if (!handler.name.empty()) {
                const ValueId slot = allocaFor(handler.name, out_.module.types.ptrType());
                // WHAT `e` IS. Without the declared type the handler's `e.code` had no owner to
                // find the field in, so its `gep` fell back to offset zero and read the object's
                // vtable pointer as an integer: `caught code=1292382216`.
                noteName(slot, handler.type);
                if (const std::string caught = baseNameOf(handler.type);
                    !caught.empty() && named_.count(caught) != 0) {
                    pointeeOfSlot_[slot] = named_[caught];
                }
                Inst st;
                st.op = Op::Store;
                st.operands.push_back(exc);
                st.operands.push_back(slot);
                st.loc = s.loc;
                emit(std::move(st));
            }
            for (const auto& inner : handler.body.statements) {
                lowerStmt(inner.get());
            }
            // §21: AND THE HANDLER'S OWN STRINGS GO BACK. A `try` walks its statements directly
            // rather than through `lowerScope` -- its cleanup is not a scope's -- so the closing
            // brace that releases temporaries everywhere else does not run here. The last line of
            // a `catch` is the commonest place to build one: `printf("caught: %s", e.message())`.
            releaseStringTemps(handler.body.loc);
            if (s.finallyBlock != nullptr) {
                for (const auto& inner : s.finallyBlock->statements) {
                    lowerStmt(inner.get());
                }
                releaseStringTemps(s.finallyBlock->loc);
            }
            gotoIfOpen(after);
            here_ = next;
        }

        // Nothing matched: run `finally` and keep unwinding. That is what `resume` means, and it is
        // why a `finally` cannot be one shared block.
        if (s.finallyBlock != nullptr) {
            for (const auto& inner : s.finallyBlock->statements) {
                lowerStmt(inner.get());
            }
        }
        if (!blockClosed()) {
            // AN EXCEPTION LEAVING THE FUNCTION STILL LEAVES ITS SCOPES, and everything they hold
            // has to be torn down on the way. The body's own objects were handled above; these are
            // the ones declared OUTSIDE the `try` and still live -- `Guard g` sitting before it --
            // which nothing on this edge was destroying. `objCase` ran `~Guard` once, on the normal
            // return, where the trusted path runs it twice: once there and once in `rethrow`, as
            // `call void @"Guard.~Guard"(ptr %6) [ "funclet"(token %5) ]`.
            //
            // Only when the exception leaves the FUNCTION. With an enclosing `try`, the edge below
            // hands it to that handler's landing block, which runs the same teardown itself -- and
            // a second copy here would run every destructor twice, which is the failure the async
            // landing block's `guarded` flag exists to prevent.
            if (handlers_.empty()) {
                runDeferred(s.loc, 0);
                destroyScoped(0, s.loc);
            }
            Inst again;
            again.op = Op::Resume;
            again.operands.push_back(exc);
            // AN UNCAUGHT EXCEPTION INSIDE A NESTED `try` BELONGS TO THE OUTER ONE. Re-raising it
            // with nowhere to go named terminates the program instead, so the enclosing handler --
            // if this `try` is inside another one -- is recorded as where the re-raise unwinds to.
            if (!handlers_.empty()) {
                again.edges.push_back(Edge{handlers_.back().landing, {}});
            }
            again.loc = s.loc;
            emit(std::move(again));
        }

        here_ = after;
    }

    void lowerIf(const ast::IfStmt& s) {
        const ValueId cond = lowerExpr(s.cond.get());
        const BlockId thenB = fn_->addBlock(fresh("then"));
        const BlockId elseB = fn_->addBlock(fresh("else"));
        const BlockId join = fn_->addBlock(fresh("join"));

        Inst br;
        br.op = Op::BrCond;
        br.loc = s.loc;
        if (cond != kNoValue) {
            br.operands.push_back(cond);
        }
        br.edges.push_back(Edge{thenB, {}});
        br.edges.push_back(Edge{elseB, {}});
        emit(std::move(br));

        here_ = thenB;
        // SCOPED, both branches. A local declared inside one belongs to it: leaving it in the
        // enclosing scope meant an object built in a branch that never ran had its destructor
        // called at the end of the method, on a slot nothing had written.
        lowerScope(s.thenBlock);
        gotoIfOpen(join);

        here_ = elseB;
        if (s.elseBlock != nullptr) {
            lowerScope(*s.elseBlock);
        }
        gotoIfOpen(join);

        here_ = join;
    }

    void lowerWhile(const ast::WhileStmt& s) {
        const BlockId head = fn_->addBlock(fresh("loop"));
        const BlockId body = fn_->addBlock(fresh("body"));
        const BlockId done = fn_->addBlock(fresh("done"));
        gotoIfOpen(head);

        here_ = head;
        const ValueId cond = lowerExpr(s.cond.get());
        Inst br;
        br.op = Op::BrCond;
        br.loc = s.loc;
        if (cond != kNoValue) {
            br.operands.push_back(cond);
        }
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{done, {}});
        emit(std::move(br));

        here_ = body;
        loops_.push_back(LoopTargets{done, head, takeLoopLabel(), scoped_.size(), deferred_.size()});
        lowerScope(s.body);   // its own `defer`s run when it ends, not when the method does
        loops_.pop_back();
        gotoIfOpen(head);

        here_ = done;
    }

    // `do { ... } while (cond);` RUNS ITS BODY FIRST. It was not lowered at all -- no case for the
    // statement -- so the body never ran and every counter it kept stayed at its initial value:
    // `count = 0` where the program counts to five. The shape is the `while` above with the test
    // moved to the bottom, which is also what makes the first pass unconditional.
    void lowerDoWhile(const ast::DoWhileStmt& s) {
        const BlockId body = fn_->addBlock(fresh("dobody"));
        const BlockId test = fn_->addBlock(fresh("dotest"));
        const BlockId done = fn_->addBlock(fresh("dodone"));
        gotoIfOpen(body);

        here_ = body;
        // `continue` goes to the TEST, not back to the top: the condition decides whether there is
        // another pass, and skipping it would make `continue` an unconditional loop.
        loops_.push_back(LoopTargets{done, test, takeLoopLabel(), scoped_.size(), deferred_.size()});
        lowerScope(s.body);
        loops_.pop_back();
        gotoIfOpen(test);

        here_ = test;
        const ValueId cond = lowerExpr(s.cond.get());
        Inst br;
        br.op = Op::BrCond;
        br.loc = s.loc;
        if (cond != kNoValue) {
            br.operands.push_back(cond);
        }
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{done, {}});
        emit(std::move(br));

        here_ = done;
    }

    void gotoIfOpen(BlockId to) {
        if (blockClosed()) {
            return;
        }
        Inst br;
        br.op = Op::Br;
        br.edges.push_back(Edge{to, {}});
        emit(std::move(br));
    }

    std::string fresh(const char* stem) {
        return std::string(stem) + std::to_string(counter_++);
    }

    // ---- expressions ----

    ValueId lowerExpr(const ast::Expr* e) {
        if (e == nullptr) {
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;

        if (auto* n = dynamic_cast<const ast::IntLiteralExpr*>(e)) {
            Inst in;
            in.op = Op::ConstInt;
            // The AST keeps the raw lexeme; the value is parsed here. `0x` and `0b` are Polaron
            // spellings `strtoll` does not take on its own, so the base is decided first.
            in.imm = parseIntLexeme(n->text);
            // A LITERAL IS AS WIDE AS ITS VALUE. Every one of them was thirty-two bits, so
            // `a[0] = 5000000000` stored `705032704` -- the same number with its top bits gone --
            // and the array of `long` it went into never saw the value the program wrote.
            in.type = tt.intType(in.imm > 2147483647LL || in.imm < -2147483648LL ? 64 : 32);
            in.loc = e->loc;
            return emit(std::move(in));
        }
        if (auto* b = dynamic_cast<const ast::BoolLiteralExpr*>(e)) {
            Inst in;
            in.op = Op::ConstBool;
            in.type = tt.boolType();
            in.imm = b->value ? 1 : 0;
            in.loc = e->loc;
            return emit(std::move(in));
        }
        if (auto* s = dynamic_cast<const ast::StringLiteralExpr*>(e)) {
            Inst in;
            in.op = Op::ConstStr;
            in.type = tt.ptrType();
            in.text = s->value;
            in.loc = e->loc;
            // `b"..."` IS THE BYTES, NOT A `String` (spec 36): a `byte*` a kernel compares directly,
            // with no object and no runtime behind it. Marked as a String it went through the C
            // boundary conversion and handed over the pointer to its own header -- `len=10` read
            // back as `len=1`.
            //
            // ...AND ADDRESSED DIRECTLY, not read out of the wrapper's `data` field. That field
            // lives in a global holding a pointer, which a position-independent image has to
            // RELOCATE before it means anything -- and pico's `ld.so` announces itself before it
            // relocates itself. `in.imm = 1` is the backend's signal to hand back the array.
            if (s->isBytes) {
                in.imm = 1;
                const ValueId data = emit(std::move(in));
                // ...AND IT IS A `byte*`, said out loud. A `ptr` is opaque, so the only thing that
                // can say how far one step of `b"/AJUDA.TXT"[i]` goes is the declared type -- and
                // with none, indexing fell back to four bytes an element: `[0]` read `0x554A412F`,
                // which is the first FOUR characters at once, and the comparison against a byte
                // was false on every index.
                noteName(data, "byte", 1);
                return data;
            }
            // Otherwise it IS a `String`, and saying so here is what lets `"abc".length()` find the
            // builtin and what makes the C boundary convert it -- see `emitCall`.
            const ValueId lit = emit(std::move(in));
            noteName(lit, "String");
            return lit;
        }
        if (auto* fl = dynamic_cast<const ast::FloatLiteralExpr*>(e)) {
            // `12.34m` IS NOT A FLOAT. The lexer already decided -- `isDecimal` is on the literal --
            // and what it denotes is the 128-bit mantissa `1234 * 10^16`, which no `double` holds
            // exactly and which is the entire point of the type. Carried as DIGITS in `text`
            // because `imm` is sixty-four bits and this number is not.
            if (fl->isDecimal) {
                Inst dec;
                dec.op = Op::ConstInt;
                dec.type = tt.intType(kDecimalBits);
                dec.text = cgutil::decimalScaledString(fl->text);
                dec.loc = e->loc;
                const ValueId v = emit(std::move(dec));
                noteName(v, "Decimal");
                return v;
            }
            Inst in;
            in.op = Op::ConstFloat;
            // `2.0f` is a float, `2.0` a double: the suffix decides the width, as it does in the
            // language. Reading it here rather than defaulting to double keeps a `float` field's
            // initialiser the size the field is.
            const bool isFloat = !fl->text.empty() &&
                                 (fl->text.back() == 'f' || fl->text.back() == 'F');
            in.type = tt.floatType(isFloat ? 32 : 64);
            in.fimm = std::strtod(fl->text.c_str(), nullptr);
            in.loc = e->loc;
            return emit(std::move(in));
        }
        if (auto* t = dynamic_cast<const ast::TernaryExpr*>(e)) {
            // `c ? a : b` IS A BRANCH, and the two arms must not both be evaluated -- one of them
            // may divide, allocate or fault. Block arguments carry the result out, exactly as they
            // do for `&&`.
            const ValueId c = lowerExpr(t->cond.get());
            const BlockId thenB = fn_->addBlock(fresh("tern"));
            const BlockId elseB = fn_->addBlock(fresh("terne"));
            const BlockId join = fn_->addBlock(fresh("ternj"));

            Inst br;
            br.op = Op::BrCond;
            if (c != kNoValue) {
                br.operands.push_back(c);
            }
            br.edges.push_back(Edge{thenB, {}});
            br.edges.push_back(Edge{elseB, {}});
            br.loc = e->loc;
            emit(std::move(br));

            here_ = thenB;
            const ValueId a = lowerExpr(t->thenExpr.get());
            const Type* rt = a != kNoValue ? fn_->value(a)->type : tt.intType(32);
            // The join's parameter is typed from the arm, and both edges are supplied AFTER it
            // exists -- verifier rule 3 checks exactly that agreement.
            const ValueId out = fn_->addValue(rt, ValueOrigin::BlockParam, join, 0, "");
            fn_->block(join)->params.push_back(out);

            Inst goA;
            goA.op = Op::Br;
            Edge ea{join, {}};
            ea.args.push_back(a != kNoValue ? a : undefOf(rt, e->loc));
            goA.edges.push_back(ea);
            emit(std::move(goA));

            here_ = elseB;
            ValueId bv = lowerExpr(t->elseExpr.get());
            // THE TWO ARMS ARE CONVERTED TO ONE TYPE, NOT DISCARDED FOR NOT ALREADY BEING IT.
            //
            // This required the else arm's type to match the then arm's EXACTLY and substituted
            // `undef` when it did not -- so `cond ? SomeAddress : 0`, where the literal is an `int`
            // and the other arm an `address`, put an undefined value on that edge. Not a wrong
            // number: a value the optimiser is entitled to make anything of, which at -O0 is one
            // thing and at -O1 another.
            //
            // pico is where it mattered. `this.loadAt(this.isDynamic() ? Elf.ProgramBase : 0)` --
            // an ET_EXEC image is linked at fixed addresses and takes no bias -- handed `undef` to
            // every static guest, and the kernel loaded them at 0x80001000 where the file says
            // 0x40001000. The assembly oracle guest, which cannot itself be miscompiled, reported
            // `auxv WRONG`: AT_ENTRY did not equal its own load address, because it had been loaded
            // somewhere else entirely.
            // NUMBERS ONLY. Converting freely between the two arms is more than this needs and less
            // than it can afford: a ternary whose arms are two different CLASSES is a pair of
            // pointers the type table already agrees about, and running them through the general
            // conversion turned three collection samples into programs that print nothing. What the
            // bug above requires is the numeric case -- an `int` literal meeting an `address` -- and
            // that is all this does.
            auto numeric = [](const Type* t) {
                return t != nullptr &&
                       (t->kind == TypeKind::Int || t->kind == TypeKind::Addr ||
                        t->kind == TypeKind::Float || t->kind == TypeKind::Bool);
            };
            if (bv != kNoValue && rt != nullptr && fn_->value(bv)->type != rt &&
                numeric(rt) && numeric(fn_->value(bv)->type)) {
                bv = lowerConversion(bv, fn_->value(bv)->type, rt, e->loc);
            }
            Inst goB;
            goB.op = Op::Br;
            Edge eb{join, {}};
            eb.args.push_back(bv != kNoValue && fn_->value(bv)->type == rt ? bv
                                                                          : undefOf(rt, e->loc));
            goB.edges.push_back(eb);
            emit(std::move(goB));

            here_ = join;
            // WHAT THE ARMS ARE, carried out with the value. A ternary produces a BLOCK PARAMETER,
            // which knows its machine shape and nothing else -- so `cond ? "under 200 ms" : "too
            // slow"` handed `printf` a value with no class, the C-boundary conversion did not fire,
            // and what reached `%s` was the String OBJECT rather than the bytes in it: an empty
            // line where the program prints a sentence. Only when the two agree; where they differ
            // there is no one answer and saying nothing is honest.
            if (a != kNoValue && bv != kNoValue) {
                const std::string left = declaredName(a);
                const std::string right = declaredName(bv);
                auto text = [](const std::string& n) { return n == "String" || n == "string"; };
                if (left == right) {
                    noteName(out, left, pointerDepthOf(a));
                } else if (text(left) && text(right)) {
                    // `args.length() > 1 ? args[1] : ""` -- an element of a `string[]` is spelled
                    // `string` and a literal is spelled `String`, and the two are ONE
                    // representation: the three-word text object. Requiring the spellings to match
                    // let this one through nameless, and `printf`'s `%s` was handed the object.
                    noteName(out, "String");
                }
            }
            return out;
        }
        if (auto* ch = dynamic_cast<const ast::CharLiteralExpr*>(e)) {
            // AN ESCAPE IS TWO CHARACTERS IN THE SOURCE AND ONE VALUE. This took the first byte of
            // the lexeme, so `'\n'` was the BACKSLASH -- 0x5C where 0x0A was meant. Every
            // `sb.appendChar('\n')` wrote a backslash, and JSON's pretty printer produced a
            // document with `\` wherever it puts a line break. Through the same decoder the trusted
            // path uses, because what an escape means is a property of the LANGUAGE.
            const std::string bytes = cgutil::resolveEscapes(ch->value);
            Inst in;
            in.op = Op::ConstInt;
            in.type = tt.intType(32);   // a char is a codepoint
            in.imm = bytes.empty() ? 0 : static_cast<unsigned char>(bytes[0]);
            in.loc = e->loc;
            return emit(std::move(in));
        }
        if (auto* nc = dynamic_cast<const ast::NullCoalesceExpr*>(e)) {
            return lowerNullCoalesce(*nc);
        }
        if (auto* tr = dynamic_cast<const ast::TryExpr*>(e)) {
            return lowerTryExpr(*tr);
        }
        if (auto* od = dynamic_cast<const ast::OldExpr*>(e)) {
            // `old(e)` IS A READ OF A SLOT, not an expression to evaluate here. The value it names
            // is the one the method was handed, and by the time an `ensures` runs the body has
            // already changed it -- so evaluating the inner expression at this point answers the
            // question the clause exists to ask with the one number it must not use.
            //
            // The snapshot is taken at entry (`snapshotOldValues`); this end only reads it back.
            auto it = oldSlots_.find(od);
            if (it == oldSlots_.end()) {
                // Outside an `ensures` there is nothing to have snapshotted. The trusted path
                // reports the same thing in the same words.
                gap("OldExpr(outside an ensures clause)", e->loc);
                return kNoValue;
            }
            return loadFrom(it->second, e->loc);
        }
        if (auto* ri = dynamic_cast<const ast::RegionInitExpr*>(e)) {
            return lowerRegionInit(*ri);
        }
        if (auto* mx = dynamic_cast<const ast::MatchExpr*>(e)) {
            return lowerMatchExpr(*mx);
        }
        if (auto* is = dynamic_cast<const ast::InterpStringExpr*>(e)) {
            // A FORMAT STRING, not a chain of concatenations. Written as concatenation this joined
            // a literal to whatever the embedded expression happened to be -- and `concat` reads a
            // length out of the first eight bytes of its argument, so `$"{d.x}"` over an `int` read
            // 3 as a length of two hundred million and the allocator refused. It also lost the
            // formatting entirely: a `boolean` interpolates as `true`, not as 1.
            return lowerInterpAsString(*is, e->loc);
        }
        if (dynamic_cast<const ast::NullLiteralExpr*>(e) != nullptr) {
            Inst in;
            in.op = Op::ConstNull;
            in.type = tt.ptrType();
            in.loc = e->loc;
            return emit(std::move(in));
        }
        if (auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            auto it = locals_.find(id->name);
            if (it != locals_.end()) {
                // §37.3: A `lazy` NAME BUILDS ITSELF THE FIRST TIME IT IS READ.
                ensureLazy(id->name, e->loc);
                return loadFrom(it->second, e->loc);
            }
            // `result` INSIDE AN `ensures` CLAUSE IS THE VALUE THE RETURN HANDS BACK (§29).
            //
            // Nothing here bound it, so the name fell through to the implicit-`this` rule below and
            // was read as a FIELD of the receiver -- whatever happened to be at that offset. pico's
            // `Rect.area` says `ensures result >= 0`, and the kernel stopped with `contract
            // violated: ensures ... left = -1, right = 0` on a rectangle whose area is zero.
            //
            // Bound only while the exit checks are being emitted, so everywhere else the name means
            // itself: a local called `result` is found by the lookup above and shadows nothing.
            if (id->name == "result" && resultValue_ != kNoValue) {
                return resultValue_;
            }
            // INSIDE AN ENUM'S OWN METHOD, A BARE NAME MAY BE ONE OF ITS CONSTANTS. §12.4 lets
            // `Item.cheap` be written unqualified in a body that belongs to `Item`, and the enum's
            // constants include the ones its `byCatalog` block adopts -- so `if (this == cheap)`
            // and `if (this == Item.cheap)` are the same test. Read as a field of `this` instead --
            // which is what the implicit-this rule below does with any unknown name -- it became
            // an `inttoptr` of the receiver's ordinal followed by a load, so `catalog_methods` died
            // dereferencing the number 2. Asked BEFORE the field rule, because an enum value's
            // ordinal is not an object and has no fields to find.
            if (!selfClassName_.empty()) {
                if (auto ord = enumOrdinal_.find(selfClassName_ + "." + id->name);
                    ord != enumOrdinal_.end()) {
                    const ValueId v = constInt(ord->second, 32, e->loc);
                    noteName(v, selfClassName_);
                    return v;
                }
            }
            // NOT A LOCAL, so it is a field of `this` -- which is the implicit-this rule the front
            // end already applies. A bare name that is neither is a genuine gap.
            const ValueId self = selfLoad(e->loc);
            if (self != kNoValue) {
                const ValueId addr = fieldAddress(self, id->name, e->loc);
                if (addr != kNoValue) {
                    return loadFrom(addr, e->loc);
                }
            }
            // A CLASS NAME IS A QUALIFIER, NOT A VALUE, and the member access above it already
            // knows that: `Paging.PageMask` lowers its object first, gets here, and then resolves
            // the static perfectly well through the path that reads a qualified name. Recorded as
            // a gap anyway, the report filled with work that does not exist -- pico's list was 69
            // entries of which 67 were this, and a work queue that lies is not one. The value
            // returned is unchanged; only the entry goes.
            const std::string bare = id->name;
            if (findClass(bare) == nullptr && enums_.count(bare) == 0 &&
                catalogs_.count(bare) == 0 && named_.count(bare) == 0) {
                // A GAP THAT STILL PRODUCES A VALUE. Returning nothing made one unresolved name
                // into three gap entries -- the name, the member access that used it, and the
                // assignment that used that -- which reads as three times the work and is one.
                // `undef` is honest (the value is not known) and lets the rest of the method lower.
                gap("IdentifierExpr(unresolved: " + bare + ")", e->loc);
            }
            Inst u;
            u.op = Op::Undef;
            u.type = tt.intType(32);
            u.text = id->name;
            u.loc = e->loc;
            return emit(std::move(u));
        }
        if (auto* m = dynamic_cast<const ast::MemberExpr*>(e)) {
            // `w.interrupt` NAMES AN ENTRY POINT, not a field. Binding a handler and taking its
            // address are ONE act (§ interrupts): a vector holds an address and nothing else, so
            // there is no way to get the address without saying whose handler it is. What crosses
            // is a trampoline of the vector's own shape -- `void(int)`, no receiver -- which reads
            // the bound object out of a global and calls the real method. Read as a field, it
            // loaded the first four bytes of the object and handed THOSE to `Signals.answer`.
            //
            // THE RECEIVER IS EVALUATED AT MOST ONCE, and every path below that needs it takes it
            // from here. Three of them used to evaluate it for themselves, and two of those three
            // threw the result away when their guess turned out wrong.
            ValueId receiverOnce = kNoValue;
            if (const ValueId entry = interruptEntryPoint(*m, e->loc, &receiverOnce);
                entry != kNoValue) {
                return entry;
            }
            // `v.x` NAMES A LANE (§34.6's swizzle names), not a field. Decided from the object's
            // declared type BEFORE it is lowered, so the ordinary member path is left untouched for
            // everything that merely happens to have a one-letter field called `x`.
            //
            // `isVectorExpr` is a GUESS from the declared type, and when it is wrong this falls
            // through to the ordinary member path -- so the value it produced has to survive the
            // fall-through rather than be evaluated a second time down there.
            if (const int lane = laneOfSwizzle(m->member);
                lane >= 0 && isVectorExpr(m->object.get())) {
                if (receiverOnce == kNoValue) {
                    receiverOnce = lowerExpr(m->object.get());
                }
                const ValueId on = receiverOnce;
                if (on != kNoValue && isVector(fn_->value(on)->type) &&
                    static_cast<uint64_t>(lane) < fn_->value(on)->type->extent) {
                    return laneOf(on, static_cast<int64_t>(lane), e->loc);
                }
            }
            // A STATIC IS NOT A FIELD OF AN OBJECT. `Style.Bold` names a global; walking it as
            // `load (gep Bold (load Style))` evaluates a CLASS as a value, which is what left
            // twenty-three names undefined -- `Test`, `Style`, `IpcServer`, `TlsClient`, all of them
            // class names used as qualifiers.
            // AN ENUM CONSTANT IS ITS ORDINAL, known now. `Color.Blue` was resolved as a qualified
            // NAME -- an external global the lowering invented and zeroed -- so every enum constant
            // read back as 0 and only the first case of any `switch` on one could ever match.
            //
            // The owner is taken from the FLATTENED chain, not from the immediate object: the
            // analyzer may hand this a qualified `app.Color.BLUE`, whose object is another member
            // expression rather than a bare name.
            {
                std::string chain;
                if (flatten(m->object.get(), &chain)) {
                    const size_t dot = chain.rfind('.');
                    const std::string owner =
                        dot == std::string::npos ? chain : chain.substr(dot + 1);
                    if (auto it = enumOrdinal_.find(owner + "." + m->member);
                        it != enumOrdinal_.end()) {
                        // AN ENUM CAN BE UNIMPORTED TOO (§30.4), and reading one of its constants
                        // is the only way to use it -- there is no `new` and no method call to hang
                        // the check on. Without it `unimport enum Color` took the type away and
                        // `Color.GREEN` on the next line still answered: `unimport_granularity`
                        // printed `no` where it must print `enum caught`.
                        guardAlive(owner, e->loc);
                        // A JAVA-STYLE ENUM'S CONSTANT IS AN OBJECT, not a number (spec 12.2):
                        // `Planet.EARTH` is a singleton with fields, built once and shared, and
                        // `Planet.EARTH.density` reads one of them. Handing back the ordinal made
                        // the field read dereference the number 2.
                        if (auto decl = enums_.find(owner);
                            decl != enums_.end() && decl->second->isJavaStyle) {
                            return javaEnumSingleton(*decl->second,
                                                     static_cast<size_t>(it->second), e->loc);
                        }
                        const ValueId v = constInt(it->second, 32, e->loc);
                        noteName(v, owner);
                        return v;
                    }
                }
            }
            // A QUALIFIED NAME IS A STATIC ONLY IF ONE OF THAT NAME WAS DECLARED.
            //
            // `Shared.one.value` is not a static called `Shared.one.value`. It is the static
            // `Shared.one` -- a pointer -- and then the field `value` of what it points at. Asked
            // without the `globalExists` guard, `globalSlot` ANSWERS BY DECLARING: it invented an
            // external `i64` named `@Shared.one.value`, and the read came back as whatever the
            // linker put there, which was zero. The store beside it wrote to that invented global
            // too, so the program was internally consistent and completely wrong -- it printed
            // `one 0` and left the object it was supposedly writing untouched.
            //
            // pico is where this surfaced. Its ring-3 guest shares two `atomic<int>` cells between
            // threads by putting them on the frame that outlives every thread and holding their
            // addresses in statics; `Guest.lockWord.compareAndSet(0, 1)` went through an invented
            // global, and the kernel reported a user page fault at CR2=0x8 -- offset eight of
            // nothing. The 844 samples never wrote a static holding a pointer to an object.
            //
            // Falling through is the whole fix: `Shared.one` is itself a member expression, and it
            // takes this same path one level down, where the name DOES exist.
            std::string qualified;
            if (namesAQualifier(m) && flatten(m, &qualified) && globalExists(qualified)) {
                return loadFrom(globalSlot(qualified, e->loc), e->loc);
            }
            // A METHOD NAMED WITHOUT PARENTHESES IS ITS ADDRESS (§22.3).
            //
            // `cast<address>(ApBoot.apMain)` is how pico tells the second processor's trampoline
            // where to jump, and how its ring-3 guest seeds a new thread's stack with an entry
            // point -- `slot[0] = cast<address>(Guest.threadBody)`. Both are the machine's own rule
            // for entering code: put an address somewhere and let the hardware go there.
            //
            // Read as a FIELD of a receiver -- which is what the fall-through below does with any
            // qualified name that is not a static -- it became `undef` of the class, a `gep` for a
            // field called `apMain`, and a load from it. The second processor started, read three
            // as its entry point, and executed address 3: `v=06 invalid opcode, pc=0x3`, then a
            // double fault. The kernel had already brought its whole desktop up by then.
            if (!qualified.empty()) {
                if (const Function* fnAddr = resolveKey(qualified)) {
                    Inst at;
                    at.op = Op::ConstFn;
                    at.type = tt.ptrType();
                    at.text = fnAddr->key;
                    at.loc = e->loc;
                    return emit(std::move(at));
                }
            }
            const ValueId obj =
                receiverOnce != kNoValue ? receiverOnce : lowerExpr(m->object.get());
            // ...and reading a member THROUGH it is a dereference (§3.7). Not for `obj?.member`,
            // which exists precisely to yield null instead of reading through one.
            if (!m->safe) {
                guardReceiver(obj, e->loc);
            }
            // A PROPERTY IS A METHOD READ WITHOUT PARENTHESES (spec 8.4). `r.area` names a computed
            // getter, not a field -- and reading it as a field found nothing, fell back to offset
            // zero and returned whatever was there: `area = 893988872`.
            if (const ValueId got = propertyRead(obj, m->member, e->loc); got != kNoValue) {
                return got;
            }
            // `obj?.member` YIELDS NULL WHEN `obj` IS NULL (spec 3.7) instead of reading through
            // it. The question mark was being ignored, so a safe navigation dereferenced exactly
            // the null it exists to avoid.
            if (m->safe) {
                return safeMember(obj, m->member, e->loc);
            }
            const ValueId addr = fieldAddress(obj, m->member, e->loc);
            if (addr == kNoValue) {
                gap("MemberExpr(untranslatable object)", e->loc);
                return kNoValue;
            }
            // §28.4: a `lazy` field builds itself the first time it is read. NULL IS THE SENTINEL,
            // which is why the constructor writes one there and why this needs no extra flag.
            if (!lazyFieldInit_.empty()) {
                ensureLazyField(obj, classNameOf(declaredName(obj)), m->member, addr, e->loc);
            }
            return loadFrom(addr, e->loc);
        }
        if (auto* ix = dynamic_cast<const ast::IndexExpr*>(e)) {
            const ValueId arr = lowerExpr(ix->array.get());
            if (arr == kNoValue) {
                return kNoValue;
            }
            // `v[i]` ON A VECTOR IS A LANE, not an element of a heap block. There is no length
            // header in front of it and nothing to bounds-check against at run time -- the lane
            // count is on the type -- so the array path's `gep` would have read four bytes past
            // whatever register the vector happened to be in.
            if (isVector(fn_->value(arr)->type)) {
                const ValueId idx = lowerExpr(ix->index.get());
                if (idx == kNoValue) {
                    return kNoValue;
                }
                return laneOf(arr, idx, e->loc);
            }
            if (const Function* op = indexOperator(arr, "operator[]")) {
                const ValueId idx = lowerExpr(ix->index.get());
                if (idx == kNoValue) {
                    return kNoValue;
                }
                const ValueId out = emitCall(op, {arr, idx}, e->loc);
                if (auto it = returnName_.find(op->key); it != returnName_.end()) {
                    noteName(out, it->second.name, it->second.pointerDepth);
                }
                return out;
            }
            const ValueId addr = elementAddress(*ix, arr);
            return addr == kNoValue ? kNoValue : loadFrom(addr, e->loc);
        }
        if (auto* u = dynamic_cast<const ast::UnaryExpr*>(e)) {
            // `&x` AND `*p` WERE NOT LOWERED AT ALL -- both fell through to the "unhandled
            // operator" gap, which yields nothing, so `Box* p = &b;` allocated a slot and stored
            // nothing into it and the first use of `p` dereferenced whatever the frame held. The
            // sample called `pointers` -- thirty lines, the simplest one in the corpus that has a
            // pointer in it -- segfaulted, along with every other one that takes an address.
            if (u->op == "&") {
                return addressExpr(*u);
            }
            if (u->op == "*") {
                return dereference(*u);
            }
            const ValueId v = lowerExpr(u->operand.get());
            if (v == kNoValue) {
                return kNoValue;
            }
            // `-a` ON A CLASS IS ITS `operator -` (§13). A class has no arithmetic of its own, so
            // negating one emitted `neg.checked` on a POINTER -- which the backend answers with the
            // operand unchanged, and `-a` on a `Vec2(3,4)` printed 3 and 4. The overload is a method
            // on the class taking nothing but its receiver.
            if (const std::string cls = classNameOf(declaredName(v)); !cls.empty()) {
                if (const Function* op = resolveKey(cls + ".operator" + u->op)) {
                    const ValueId out = emitCall(op, {v}, e->loc);
                    if (auto it = returnName_.find(op->key); it != returnName_.end()) {
                        noteName(out, it->second.name, it->second.pointerDepth);
                    }
                    return out;
                }
            }
            Inst in;
            in.type = fn_->value(v)->type;
            in.operands.push_back(v);
            in.loc = e->loc;
            const Type* vt = fn_->value(v)->type;
            const bool floating = vt != nullptr && vt->kind == TypeKind::Float;
            // A NEGATED FLOAT IS `fneg`, not the integer one. `-2.0` emitted `neg.checked`, which
            // the backend refuses on a floating value and answers `undef` for -- so `sign=-1.0`
            // printed as `1.0` and everything computed from it followed.
            // `!x` IS `x == 0`, NOT `~x`. The two coincide on one bit and on nothing wider, and a
            // `boolean` is not one bit here: a method answering `boolean` returns a 32-bit word
            // (§3.1 -- it is four bytes in the ABI, measured), and so does every runtime predicate
            // the compiler binds. `~1` is -2, which is true, so `if (!File.exists(p))` took the
            // absent branch for a file that was RIGHT THERE -- and `Files.copy` returned false
            // without copying anything, silently, on a path where the file it was told to read
            // existed. Comparing against zero is right at every width and is what `!` means.
            if (u->op == "-") { in.op = floating ? Op::FNeg : Op::NegChecked; }
            else if (u->op == "+") { return v; }   // unary plus is the value itself
            else if (u->op == "!") {
                in.op = Op::CmpEq;
                in.type = tt.boolType();
                in.operands.push_back(zeroLike(v, e->loc));
            }
            else if (u->op == "~") { in.op = Op::Not; }
            else { gap("UnaryExpr(unhandled operator " + u->op + ")", e->loc); return kNoValue; }
            return emit(std::move(in));
        }
        if (auto* cast = dynamic_cast<const ast::CastExpr*>(e)) {
            const ValueId v = lowerExpr(cast->operand.get());
            if (v == kNoValue) {
                return kNoValue;
            }
            // §37.5: `cast<volatile int*>(base)` NAMES HARDWARE. An MMIO pointer with no variable
            // behind it -- the framebuffer aperture, a device register, video memory -- and every
            // access through it must survive the optimiser exactly as written.
            if (cast->targetVolatile) {
                volatilePointee_.insert(v);
            }
            const Type* from = fn_->value(v)->type;
            const Type* to = baseTypeOf(cast->targetType);
            // `cast<int>(someObject)` READS THE BOXED VALUE (§3.4), and it has to be asked before
            // the pointer-to-integer reinterpret below -- that one would hand back the BOX's own
            // address, which is a large number that changes between runs. `Field.get` answers with
            // an Object, so this is the one way a reflective read ever becomes an `int`.
            if (declaredName(v) == "Object" && to != nullptr &&
                (to->kind == TypeKind::Int || to->kind == TypeKind::Float) &&
                from != nullptr && from->kind == TypeKind::Ptr) {
                return unboxWord(v, to, cast->loc);
            }
            // `cast<int>` OF A JAVA-STYLE ENUM IS ITS ORDINAL, NOT ITS ADDRESS (§12.2).
            //
            // A java-style enum's constant is a singleton OBJECT -- that is what gives it fields and
            // methods -- so the value in hand is a pointer, and the generic pointer-to-integer rule
            // turned it into the low half of that pointer. `cast<int>(Color.BLUE)` came out as an
            // address rather than 2, and `shadow_stdlib_wide` printed `chain=8` where the language
            // says 10. Only at `-O1` and above, because that is where the arithmetic on a truncated
            // address gets folded to something stable enough to notice.
            if (to != nullptr && to->kind == TypeKind::Int && from != nullptr &&
                from->kind == TypeKind::Ptr) {
                // BY THE BARE NAME AS WELL. A declared type arrives qualified once a namespace is
                // involved -- `Main.App.Color` -- and `enums_` is filed under the name the enum was
                // declared with.
                std::string cls = classNameOf(declaredName(v));
                auto found = enums_.find(cls);
                if (found == enums_.end()) {
                    if (const size_t dot = cls.rfind('.'); dot != std::string::npos) {
                        found = enums_.find(cls.substr(dot + 1));
                    }
                }
                if (found != enums_.end() && found->second->isJavaStyle) {
                    return javaEnumOrdinal(*found->second, v, cast->loc);
                }
            }
            // §34: A CAST TO OR FROM `Decimal` MOVES THE SCALE. `cast<Decimal>(5)` is not the
            // number five in a wider register -- it is five times 10^18, and without the multiply
            // `cast<Decimal>(5) / cast<Decimal>(2)` is integer division and answers 2. The other
            // direction divides it back out, which is what makes `cast<int>(price)` the whole
            // units.
            if (const std::string want = cgutil::baseType(cast->targetType);
                want == "Decimal" || classNameOf(declaredName(v)) == "Decimal") {
                if (const ValueId scaled = lowerDecimalCast(v, want, cast->loc);
                    scaled != kNoValue) {
                    return scaled;
                }
            }
            // `x is T` AND `x as? T` ARE NOT CASTS (§6.4), though they parse as one. The first
            // ASKS -- it answers a boolean and converts nothing; the second answers the value or
            // null. Both fell through to the plain reinterpret, so `a is Dog` was the pointer's
            // bits read as a boolean (always true) and `c as? Dog` handed back the Cat.
            if (cast->op == 1 || cast->op == 2) {
                const std::string want = cgutil::baseType(cast->targetType);
                const ValueId same = matchesCatchType(v, want, e->loc);
                if (cast->op == 1) {
                    return widen(same, 32, e->loc);
                }
                const BlockId yes = fn_->addBlock(fresh("as.yes"));
                const BlockId no = fn_->addBlock(fresh("as.no"));
                const BlockId join = fn_->addBlock(fresh("as.join"));
                const ValueId answer =
                    fn_->addValue(out_.module.types.ptrType(), ValueOrigin::BlockParam, join, 0, "");
                fn_->block(join)->params.push_back(answer);
                branchOn(same, yes, no);
                here_ = yes;
                {
                    Inst go;
                    go.op = Op::Br;
                    Edge edge{join, {}};
                    edge.args.push_back(v);
                    go.edges.push_back(edge);
                    go.loc = e->loc;
                    emit(std::move(go));
                }
                here_ = no;
                {
                    Inst go;
                    go.op = Op::Br;
                    Edge edge{join, {}};
                    edge.args.push_back(nullPointer(e->loc));
                    go.edges.push_back(edge);
                    go.loc = e->loc;
                    emit(std::move(go));
                }
                here_ = join;
                noteName(answer, want, 1);
                return answer;
            }
            // A CLASS MAY DEFINE THE CONVERSION ITSELF (§13.3). `operator explicit cast<Fahrenheit>()`
            // parses as a method named `operator cast$Fahrenheit`, and `cast<Fahrenheit>(c)` means
            // CALL IT -- not reinterpret the pointer, which is what happened: the Celsius came back
            // as a Fahrenheit reading the same field, so 100C printed as 100F.
            if (const std::string from = classNameOf(declaredName(v)); !from.empty()) {
                const std::string want = cgutil::baseType(cast->targetType);
                const std::string bare = want.substr(want.rfind('.') + 1);
                if (const Function* conv = resolveKey(from + ".operator cast$" + bare)) {
                    const ValueId out = emitCall(conv, {v}, cast->loc);
                    if (auto it = returnName_.find(conv->key); it != returnName_.end()) {
                        noteName(out, it->second.name, it->second.pointerDepth);
                    }
                    return out;
                }
            }
            // `cast<int>(planet)` ASKS FOR THE ORDINAL (spec 12.5), not for the singleton's
            // address. A java-style enum's value is an object, so the generic pointer-to-integer
            // reinterpret below truncates a heap address -- a number that means nothing, and one
            // that changes between runs.
            if (const std::string was = classNameOf(declaredName(v)); !was.empty()) {
                if (auto decl = enums_.find(was);
                    decl != enums_.end() && decl->second->isJavaStyle && to != nullptr &&
                    to->kind == TypeKind::Int) {
                    const ValueId which = javaEnumOrdinal(*decl->second, v, e->loc);
                    return lowerConversion(which, out_.module.types.intType(32), to, e->loc);
                }
            }
            // `cast<T*>(maybe)` IS A PROMISE THE PROGRAM MAKES, and a cast that survives in the
            // source is a DELIBERATE claim -- flow narrowing means an ordinary null check needs no
            // cast at all. So it is checked: null here is a broken promise, reported where it was
            // made rather than dereferenced somewhere later with no trace of who promised what.
            if (ast::typeIsNullable(declaredName(v)) || pointerDepthOf(v) > 0) {
                if (to != nullptr && to->kind == TypeKind::Ptr && !cast->targetType.empty() &&
                    !ast::typeIsNullable(cast->targetType)) {
                    Inst check;
                    check.op = Op::GuardNull;
                    check.operands.push_back(v);
                    check.text = "NullReferenceException";
                    if (auto raised = named_.find(check.text); raised != named_.end()) {
                        check.aggregate = raised->second;
                    }
                    if (!handlers_.empty()) {
                        check.edges.push_back(Edge{handlers_.back().landing, {}});
                    }
                    check.loc = e->loc;
                    emit(std::move(check));
                }
            }
            // A DOWNCAST IS CHECKED. `cast<Dog>(a)` on an `Animal*` that is really a `Cat` is a
            // claim the object refutes, and the object is the only thing that can: its table says
            // what it is. Unchecked, the program went on calling `Dog`'s methods on a `Cat`.
            if (const std::string want = classNameOf(cast->targetType),
                                  have = classNameOf(declaredName(v));
                !want.empty() && want != have && findClass(want) != nullptr &&
                findClass(have) != nullptr && hasVtable_.count(want) != 0 &&
                descendsFrom(*findClass(want), have)) {
                const BlockId wrong = fn_->addBlock(fresh("cast.wrong"));
                const BlockId right = fn_->addBlock(fresh("cast.right"));
                branchOn(matchesCatchType(v, want, e->loc), right, wrong);
                here_ = wrong;
                Inst raise;
                raise.op = Op::Raise;
                raise.operands.push_back(newRuntimeException("ClassCastException", e->loc));
                if (!handlers_.empty()) {
                    raise.edges.push_back(Edge{handlers_.back().landing, {}});
                }
                raise.loc = e->loc;
                emit(std::move(raise));
                here_ = right;
            }
            const ValueId got = lowerConversion(v, from, to, e->loc);
            // `cast<uint>(x)` IS where the sign enters most programs -- the standard library writes
            // its unsigned arithmetic that way rather than declaring a `uint` for every temporary.
            // A conversion that changes nothing hands the same value back, so this can re-mark the
            // original; that is the right answer, since the cast is what said what it is.
            //
            // THE OUTER STAR IS NOT PART OF THE NAME. `cast<Leaf*>(x)` recorded `Leaf*`, and every
            // table here is keyed by the class -- so the field lookup found nothing and fell back
            // to offset zero: `cast<Leaf*>(this.held).value` read the vtable pointer as an `int`.
            // Stripped only when what remains is a class, because a star can also belong INSIDE a
            // mangled type argument (`ArrayList$Row*`), where removing it names nothing.
            std::string spelled = cast->targetType;
            int depth = 0;
            while (spelled.size() > 1 && spelled.back() == '*' && findClass(spelled) == nullptr &&
                   findClass(spelled.substr(0, spelled.size() - 1)) != nullptr) {
                spelled.pop_back();
                ++depth;
            }
            noteName(got, spelled, depth);
            return got;
        }
        if (auto* lam = dynamic_cast<const ast::LambdaExpr*>(e)) {
            return lowerLambda(*lam);
        }
        if (auto* mr = dynamic_cast<const ast::MethodRefExpr*>(e)) {
            // `methodref obj.method` is a closure whose capture is the receiver and whose code is
            // the method. Exactly the same shape as a lambda that captures one thing.
            const ValueId recv = lowerExpr(mr->object.get());
            const Function* target = resolveSuffix(mr->method);
            if (target == nullptr) {
                gap("MethodRefExpr(unresolved method)", e->loc);
                return kNoValue;
            }
            // WHICH BODY, decided by the OBJECT when the method is overridden. `methodref
            // cat.speak` on an `Animal` holding a `Cat` must carry `Cat.speak`, and reading the
            // name statically carried `Animal.speak` -- the bound reference silently lost the
            // override that the same call written out in full would have taken.
            ValueId code = kNoValue;
            const std::string cls = classNameOf(declaredName(recv));
            if (recv != kNoValue && !cls.empty() && needsDispatch(cls, mr->method)) {
                Inst load;
                load.op = Op::VtableLoad;
                load.type = tt.ptrType();
                load.operands.push_back(recv);
                load.imm = slotFor(mr->method);
                load.text = cls;   // rule 15: the class whose table this names
                load.loc = e->loc;
                code = emit(std::move(load));
            } else {
                Inst fnv;
                fnv.op = Op::ConstFn;
                fnv.type = tt.ptrType();
                fnv.text = target->key;
                fnv.loc = e->loc;
                code = emit(std::move(fnv));
            }

            // THE SAME `{code, env}` PAIR A LAMBDA BUILDS, because the two are the same kind of
            // value and every caller reads them the same way. `closure.make` was an opcode the
            // backend has no case for, so a bound method reference came out as `undef` and calling
            // it jumped to whatever the frame held.
            //
            // The environment IS the receiver: a method's first parameter is `this`, and a closure
            // call passes the environment word in exactly that position.
            const Type* i64 = tt.intType(64);
            const Type* ptr = tt.ptrType();
            const ValueId bound =
                callExternal("__polaron_malloc", ptr, {i64}, {constInt(16, 64, e->loc)}, e->loc);
            storeAt(bound, 0, code, e->loc);
            storeAt(bound, 8, recv != kNoValue ? recv : nullPointer(e->loc), e->loc);
            if (auto it = returnName_.find(target->key); it != returnName_.end()) {
                noteName(bound, "function<" + it->second.name + ">");
            }
            return bound;
        }
        if (auto* call = dynamic_cast<const ast::CallExpr*>(e)) {
            return lowerCall(*call);
        }
        if (auto* n = dynamic_cast<const ast::NewExpr*>(e)) {
            return lowerNew(*n);
        }
        // `(a, b)` -- a tuple literal (§22.5). Built in STORAGE like every other value struct here,
        // so it needs no `insertvalue` the backend has no case for and so its components are
        // addressed exactly as a struct's fields are.
        if (auto* tup = dynamic_cast<const ast::TupleExpr*>(e)) {
            std::vector<ValueId> parts;
            std::vector<std::string> spellings;
            for (const auto& piece : tup->elements) {
                parts.push_back(lowerExpr(piece.get()));
                spellings.push_back(spelledTypeOf(piece.get()));
            }
            std::string spelling = "(";
            for (size_t i = 0; i < parts.size(); ++i) {
                const std::string part =
                    spellings[i].empty()
                        ? (parts[i] != kNoValue ? nameOfType(fn_->value(parts[i])->type) : "int")
                        : spellings[i];
                spelling += (i == 0 ? "" : ",") + part;
            }
            spelling += ")";
            const Type* shape = baseTypeOf(spelling);
            if (shape == nullptr || shape->kind != TypeKind::Struct) {
                gap("TupleExpr(no shape for " + spelling + ")", e->loc);
                return kNoValue;
            }
            Inst room;
            room.op = Op::Alloca;
            room.type = shape;
            room.extra.push_back("heap");   // a tuple is returned by value and must outlive the frame
            room.text = "tuple";
            room.loc = e->loc;
            const ValueId obj = emit(std::move(room));
            pointee_[obj] = shape;
            noteName(obj, spelling);
            for (size_t i = 0; i < parts.size() && i < shape->fields.size(); ++i) {
                if (parts[i] == kNoValue) {
                    continue;
                }
                Inst g;
                g.op = Op::Gep;
                g.type = out_.module.types.ptrType();
                g.operands.push_back(obj);
                g.aggregate = shape;
                g.imm = static_cast<int64_t>(i);
                g.text = shape->fields[i].name;
                g.loc = e->loc;
                const ValueId slot = emit(std::move(g));
                slotType_[slot] = shape->fields[i].type;
                storeInto(slot, parts[i], e->loc);
            }
            return obj;
        }
        // `await t` -- §20.2. Outside an async body it BLOCKS until the task completes and reads
        // its result; `await` on something that is not a Task is a pass-through, because the
        // operand already produces its value by blocking (a channel receive, §20.7).
        if (auto* aw = dynamic_cast<const ast::AwaitExpr*>(e)) {
            const ValueId task = lowerExpr(aw->operand.get());
            if (task == kNoValue) {
                return kNoValue;
            }
            const std::string cls = classNameOf(declaredName(task));
            if (cls.rfind("Task$", 0) != 0) {
                return task;
            }
            const ValueId slot = fieldAddress(task, "h", aw->loc);
            if (slot == kNoValue) {
                gap("AwaitExpr(task has no handle)", aw->loc);
                return kNoValue;
            }
            TypeTable& tt = out_.module.types;
            const ValueId handle = loadFrom(slot, aw->loc);
            // §20.2: INSIDE AN ASYNC BODY, `await` SUSPENDS -- it does not block.
            //
            // `__polaron_await` registers this function as the awaited task's continuation and
            // answers whether it parked; if it did, returning frees the worker. `__polaron_task_wait`
            // sleeps on a condition variable instead, which holds the worker for as long as the
            // awaited task takes -- and with a bounded pool, tasks awaiting tasks that need a worker
            // is the classic deadlock. The output is identical right up until the pool runs out,
            // which is why no sample in the corpus ever showed it.
            if (asyncStatePtr_ != kNoValue && !asyncResumeKey_.empty()) {
                const size_t k = asyncSteps_.size() + 1;
                storeInto(asyncAwaitedSlot_, handle, aw->loc);
                storeInto(asyncStepSlot_, constInt(static_cast<int64_t>(k), 32, aw->loc), aw->loc);
                Inst where;
                where.op = Op::ConstFn;   // §7.1: the address of a named module-level thing
                where.type = tt.ptrType();
                where.text = asyncResumeKey_;
                where.loc = aw->loc;
                const ValueId resumeFn = emit(std::move(where));
                const ValueId parked = callExternal(
                    "__polaron_await", tt.intType(32),
                    {tt.intType(64), tt.ptrType(), tt.ptrType()},
                    {handle, resumeFn, asyncStatePtr_}, aw->loc);
                const BlockId back = fn_->addBlock(fresh("async.resume"));
                Inst go;
                go.op = Op::BrCond;
                go.operands.push_back(
                    cmp(Op::CmpNe, parked, constInt(0, 32, aw->loc), aw->loc));
                go.edges.push_back(Edge{asyncSuspend_, {}});
                go.edges.push_back(Edge{back, {}});
                go.loc = aw->loc;
                emit(std::move(go));
                asyncSteps_.push_back(back);

                here_ = back;
                // THE HANDLE IS READ BACK OUT OF THE STATE, not kept in a register: the suspension
                // returned from this function and everything a register held is gone.
                //
                // ...AND READ AGAIN FOR THE SECOND USE. `rethrowFailedTask` splits the block --
                // it has to, a failed task throws here -- so a handle loaded before it is defined
                // in one block and used in another that the throw path also reaches. Reloading is
                // a load from a slot that has not changed, and it is what makes the two uses each
                // dominated by their own definition.
                rethrowFailedTask(loadFrom(asyncAwaitedSlot_, aw->loc), aw->loc);
                const ValueId answer =
                    callExternal("__polaron_task_result", tt.intType(64), {tt.intType(64)},
                                 {loadFrom(asyncAwaitedSlot_, aw->loc)}, aw->loc);
                return fromWord(answer, cls.substr(5), aw->loc);
            }
            const ValueId got = callExternal("__polaron_task_wait", tt.intType(64),
                                             {tt.intType(64)}, {handle}, aw->loc);
            // A TASK THAT FAILED RE-THROWS HERE (§21), in the awaiter's frame. Letting the
            // exception escape the worker thread instead would take the process down with no
            // handler anywhere near the code that asked for the result.
            rethrowFailedTask(handle, aw->loc);
            return fromWord(got, cls.substr(5), aw->loc);
        }
        // `unimport X expecting { ... }` IN EXPRESSION POSITION (§30.18): the block runs first, in
        // the code that is about to be taken away, and its value is what the expression yields.
        // The order is the whole point -- run it after the unimport and there is nothing left to
        // run it in.
        if (auto* ux = dynamic_cast<const ast::UnimportExpr*>(e)) {
            const ValueId proof = lowerExpecting(ux->expecting.get(), e->loc);
            unimportClass(cgutil::baseType(ux->target), e->loc);
            return proof;
        }
        if (auto* na = dynamic_cast<const ast::NewArrayExpr*>(e)) {
            // `new T[n]` IS AN ALLOCATION WITH A HEADER, not a frame slot. It was lowering to
            // `alloca`, which gave a stack pointer where the runtime expects heap storage whose
            // first eight bytes are the length -- so `xs.length` read whatever the stack had and
            // every element access was off by the header.
            const ValueId n = lowerExpr(na->size.get());
            const Type* elem = storageTypeOf(na->elementType);
            const Type* arr = tt.sliceType(elem);
            const uint64_t stride = elem != nullptr ? (elem->facts.size > 0 ? elem->facts.size : 4)
                                                    : 4;

            const ValueId wide = n != kNoValue ? widenToLong(n, e->loc) : constLong(0, e->loc);
            const ValueId bytes = mulLong(wide, static_cast<int64_t>(stride), e->loc);
            const ValueId total = addLong(bytes, 8, e->loc);

            Inst alloc;
            alloc.op = Op::Call;
            alloc.text = declareExternalTyped("__polaron_malloc", tt.ptrType(),
                                              {tt.intType(64)})->key;
            // THE CALL'S RESULT IS THE ARRAY. Typing it `ptr` and then rewriting the value's type
            // afterwards made the instruction and its result disagree -- which is exactly what
            // verifier rule 5 is for, and it said so five times.
            alloc.type = arr;
            alloc.operands.push_back(total);
            alloc.loc = e->loc;
            const ValueId mem = emit(std::move(alloc));
            noteStorage(mem, Storage::Heap);   // an array is always heap storage; `delete` frees it

            // The LENGTH, at offset zero. Everything that asks how long the array is reads it there.
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(wide);
            put.operands.push_back(mem);
            put.loc = e->loc;
            emit(std::move(put));

            // AND THE ELEMENTS ARE ZERO. `new T[n]()` says so -- the parentheses are the default
            // initialiser -- and the allocator does not: `HashMap`'s `used` array came back full of
            // whatever the heap held, so `while (this.used[i] != 0)` walked into slots that had
            // never been written and compared a garbage pointer as a String. Every hashed
            // collection over anything but a freshly zeroed heap crashed on its first insert.
            Inst start;
            start.op = Op::Gep;
            start.type = tt.ptrType();
            start.operands.push_back(mem);
            start.imm = 8;   // past the length header
            start.loc = e->loc;
            callExternal("memset", tt.ptrType(),
                         {tt.ptrType(), tt.intType(32), tt.intType(64)},
                         {emit(std::move(start)), constInt(0, 32, e->loc), bytes}, e->loc);
            return mem;
        }
        if (auto* al = dynamic_cast<const ast::ArrayLiteralExpr*>(e)) {
            // `[10, 20, 30]` -- the SAME shape `new T[3]` produces, filled in. It lowered to
            // nothing at all: the local was allocated, never stored to, and the first read of it
            // dereferenced whatever the frame happened to hold. The element type comes from the
            // first element, which is what the language says (spec 25).
            const size_t count = al->elements.size();
            std::vector<ValueId> values;
            values.reserve(count);
            for (const ast::ExprPtr& piece : al->elements) {
                values.push_back(lowerExpr(piece.get()));
            }
            const Type* elem = tt.intType(32);
            for (const ValueId v : values) {
                if (v != kNoValue && fn_->value(v)->type != nullptr) {
                    elem = fn_->value(v)->type;
                    break;
                }
            }
            return makeArray(elem, values, e->loc);
        }
        if (auto* bin = dynamic_cast<const ast::BinaryExpr*>(e)) {
            return lowerBinary(*bin);
        }
        // `mark of region R` IS THE REGION'S CURSOR, read out of the header's first word. It was
        // not lowered at all, so the `checkpoint` it produced was nothing and the `rollback` that
        // used it recorded a gap and emitted no code -- `region_stack` then pushed a hundred
        // thousand objects through a region with room for a few hundred.
        if (auto* mk = dynamic_cast<const ast::MarkExpr*>(e)) {
            auto it = locals_.find(mk->region);
            if (it == locals_.end()) {
                gap("MarkExpr(region not in scope: " + mk->region + ")", e->loc);
                return kNoValue;
            }
            const ValueId block = loadFrom(it->second, e->loc);
            Inst at;
            at.op = Op::Gep;
            at.type = tt.ptrType();
            at.operands.push_back(block);
            at.imm = 0;   // the cursor is the header's first word
            at.loc = e->loc;
            const ValueId cursor = emit(std::move(at));
            slotType_[cursor] = tt.intType(64);
            return loadFrom(cursor, e->loc);
        }
        // `extract X from region R` (§17): RELOCATE the object out of the region onto the heap and
        // hand back the owning pointer. It is a MOVE of the bytes -- so an owned String or array
        // field travels with it, its pointer being among those bytes -- and the source is not
        // destructed, only forgotten: the vacated slot goes back to the region and the handle is
        // nulled. Not lowered at all, the whole statement vanished: `region_extract` read an
        // uninitialised `out` and segfaulted before printing a line.
        if (auto* ex = dynamic_cast<const ast::ExtractExpr*>(e)) {
            const ValueId src = lowerExpr(ex->target.get());
            if (src == kNoValue) {
                return kNoValue;
            }
            const std::string cls = classNameOf(declaredName(src));
            const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
            if (shape == nullptr) {
                gap("ExtractExpr(unknown class: " + cls + ")", e->loc);
                return kNoValue;
            }
            const ValueId size = sizeOfClass(shape, e->loc);
            const ValueId heap =
                callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)}, {size}, e->loc);
            callExternal("memcpy", tt.ptrType(), {tt.ptrType(), tt.ptrType(), tt.intType(64)},
                         {heap, src, size}, e->loc);
            // THE SOURCE IS NO LONGER THE SCOPE'S TO DESTROY. Its bytes now live at `heap` and the
            // caller owns them; running the destructor at the end of the block would destroy the
            // moved-out object through the region's copy of the pointer.
            if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(ex->target.get())) {
                if (auto local = locals_.find(id->name); local != locals_.end()) {
                    const ValueId slot = local->second;
                    scoped_.erase(
                        std::remove_if(scoped_.begin(), scoped_.end(),
                                       [slot](const ScopedObject& o) { return o.slot == slot; }),
                        scoped_.end());
                    unwindObjects_.erase(
                        std::remove_if(unwindObjects_.begin(), unwindObjects_.end(),
                                       [slot](const ScopedObject& o) { return o.slot == slot; }),
                        unwindObjects_.end());
                    // ...and the handle reads as a clean null afterwards rather than as a dangling
                    // pointer into a slot the region is free to hand out again.
                    Inst emptied;
                    emptied.op = Op::Store;
                    emptied.operands.push_back(nullPointer(e->loc));
                    emptied.operands.push_back(slot);
                    emptied.loc = e->loc;
                    emit(std::move(emptied));
                }
            }
            // The vacated slot goes back to whichever region kept it. Only a flavoured region has
            // somewhere to put it -- a bump region reclaims on release and nowhere else -- and the
            // same call is what takes the object off the destructor registry, so a later `release`
            // does not destruct bytes that are no longer there.
            const RegionShape& shaped = regionShapeOf(ex->region);
            if (shaped.descriptor()) {
                const ValueId block = regionBlockFor(ex->region, e->loc);
                if (block != kNoValue) {
                    callExternal("__polaron_region_free", tt.voidType(),
                                 {tt.ptrType(), tt.ptrType(), tt.intType(64)}, {block, src, size},
                                 e->loc);
                }
            }
            noteName(heap, cls);
            return heap;
        }
        // A RANGE IS A VALUE (§7.5), not only a loop header. `0..10 step 2` stored in a variable is
        // a `Range` object that answers `size()` and `contains(n)` and can be iterated later --
        // which is why the prelude declares the class. Lowered only where a `foreach` consumes it
        // directly, `var r = 0..10 step 2;` produced nothing at all and the first `r.size()` read
        // an uninitialised local.
        if (auto* rg = dynamic_cast<const ast::RangeExpr*>(e)) {
            const Type* shape = named_.count("Range") != 0 ? named_.at("Range") : nullptr;
            const Function* ctor = resolveKey("Range.Range");
            if (shape == nullptr || ctor == nullptr) {
                gap("RangeExpr(the prelude's Range is not available)", e->loc);
                return kNoValue;
            }
            const Type* i32 = tt.intType(32);
            auto asInt = [&](const ast::Expr* x, int64_t fallback) {
                if (x == nullptr) {
                    return constInt(fallback, 32, e->loc);
                }
                const ValueId v = lowerExpr(x);
                if (v == kNoValue) {
                    return constInt(fallback, 32, e->loc);
                }
                const Type* got = fn_->value(v)->type;
                return got != nullptr && got != i32 ? lowerConversion(v, got, i32, e->loc) : v;
            };
            const ValueId start = asInt(rg->start.get(), 0);
            const ValueId end = asInt(rg->end.get(), 0);
            const ValueId step = asInt(rg->step.get(), 1);
            const ValueId inclusive = constInt(rg->inclusive ? 1 : 0, 32, e->loc);
            const ValueId obj = callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                             {sizeOfClass(shape, e->loc)}, e->loc);
            emitCall(ctor, {obj, start, end, step, inclusive}, e->loc);
            pointee_[obj] = shape;
            noteName(obj, "Range");
            noteStorage(obj, Storage::Heap);
            return obj;
        }
        if (auto* mv = dynamic_cast<const ast::MoveExpr*>(e)) {
            const ValueId src = lowerExpr(mv->operand.get());
            // `move x into region R` IS `in region R` SPELLED AS A MOVE, and a region class refuses
            // it for the same reason and in the same words: it has one arena, and an instance
            // anywhere else is the one thing the whole feature is built on not existing. A rule that
            // held at `new` and not here would be a rule with a spelling that gets around it.
            if (!mv->toRegion.empty()) {
                const std::string cls = classNameOf(declaredName(src));
                if (!cls.empty() && livesInClassArena(cls)) {
                    refuse("`" + cls + "` is a `region class`, so `into region " + mv->toRegion +
                               "` would move it out of the only region its instances may be in -- "
                               "the same thing `in region` is refused for at `new`",
                           mv->loc);
                }
            }
            Inst in;
            in.op = Op::Move;
            in.type = src != kNoValue ? fn_->value(src)->type : tt.ptrType();
            in.loc = e->loc;
            if (src != kNoValue) {
                in.operands.push_back(src);
            }
            return emit(std::move(in));
        }
        gap(typeid(*e).name(), e->loc);
        return kNoValue;
    }

    // A conversion is never implicit and never wrapping unless it says so: the language's rule is
    // that a cast SATURATES, and here that is the opcode rather than emitted clamping code the
    // optimiser then has to understand.
    ValueId lowerConversion(ValueId v, const Type* from, const Type* to, SourceLocation loc) {
        if (from == to || to == nullptr || from == nullptr) {
            return v;
        }
        Inst in;
        in.type = to;
        in.operands.push_back(v);
        in.loc = loc;
        // A BOOLEAN IS ONE BIT AND THAT BIT IS NOT A SIGN. Widening it must be `extend.u`, or
        // `true` arrives as -1 wherever a predicate's result is used as a number.
        if (from->kind == TypeKind::Bool && to->kind == TypeKind::Int) {
            in.op = Op::ExtendU;
            return emit(std::move(in));
        }
        if (from->kind == TypeKind::Int && to->kind == TypeKind::Bool) {
            in.op = Op::Trunc;
            return emit(std::move(in));
        }
        if (from->kind == TypeKind::Int && to->kind == TypeKind::Int) {
            // CROSSING A NEWTYPE IS NOT AN EXTEND, and this is where §9's rule 8 is obeyed rather
            // than merely enforced. `newtype Batch = uint` and `uint` are the same width and the
            // same bits; only the nominal identity differs -- so there is nothing to widen and
            // nothing to narrow, and emitting `extend` for it is exactly the implicit conversion
            // the rule refuses. `cast<Batch>(cast<uint>(4000000000))` produced four of them.
            //
            // `Bitcast` is the named crossing, which is what the rule asks for: the value is the
            // same, the TYPE it is known by is not. It also keeps the width honest -- an
            // `extend.s` of the same width is a no-op on the bits and a lie about the intent, and
            // the printer downstream read the result back as signed and put 4000000000 on screen
            // as -294967296.
            if (from->bits == to->bits && from->nominal != to->nominal) {
                in.op = Op::Bitcast;
                return emit(std::move(in));
            }
            // WIDENING READS THE SOURCE'S SIGN. A `ubyte` reaching a 32-bit slot must be zero-
            // extended: sign-extending it turns every byte above 0x7F into a large negative number,
            // which is exactly the shape a checksum feeds straight into its accumulator.
            in.op = to->bits < from->bits ? Op::Trunc
                    : isUnsignedValue(v)  ? Op::ExtendU
                                          : Op::ExtendS;
        } else if (from->kind == TypeKind::Float && to->kind == TypeKind::Int) {
            in.op = Op::FpToIntSaturate;
        } else if (from->kind == TypeKind::Int && to->kind == TypeKind::Float) {
            in.op = Op::IntToFp;
        } else if (from->kind == TypeKind::Float && to->kind == TypeKind::Float) {
            in.op = to->bits < from->bits ? Op::FpTrunc : Op::FpExtend;
        } else if (from->kind == TypeKind::Ptr && to->kind == TypeKind::Addr) {
            in.op = Op::PtrToAddr;
        } else if ((from->kind == TypeKind::Addr || from->kind == TypeKind::Int) &&
                   to->kind == TypeKind::Ptr) {
            // AN INTEGER TOO, not only an `address`: freestanding code writes `cast<T*>(0xB8000)`
            // and a `long` holding a machine address is the same conversion by another spelling.
            in.op = Op::AddrToPtr;
        } else if (from->kind == TypeKind::Ptr &&
                   (to->kind == TypeKind::Addr || to->kind == TypeKind::Int)) {
            in.op = Op::PtrToAddr;
        } else if (from->kind == TypeKind::Addr && to->kind == TypeKind::Addr) {
            // AN ADDRESS HAS NO SIGN, AT ANY WIDTH -- `addr.widen` is a zero-extension, which is the
            // whole reason it is its own opcode rather than a reuse of `extend.s`.
            //
            // This rule was right and was not being ASKED. `emitCall` converts an argument to what
            // the parameter declares only when both sides are `Int` or `Float`, so a `short address`
            // reaching an `address` parameter travelled with nothing emitted at all and the backend's
            // last-ditch coercion guessed -- and it guesses `sext`, because by then all it can see is
            // `i16` and `i64`. pico writes `public fixed short address TrampolineAt = 0x8000` for the
            // page below 64 KiB it copies the second processor's trampoline into; 0x8000 became
            // 0xFFFFFFFFFFFF8000, and the kernel brought up its entire desktop and then page-faulted
            // copying the trampoline to minus thirty-two kilobytes. CR2 in the report WAS the
            // constant, sign-extended.
            in.op = to->bits < from->bits ? Op::AddrNarrow : Op::AddrWiden;
        } else if (from->kind == TypeKind::Int && to->kind == TypeKind::Addr) {
            // A NUMBER BECOMING AN ADDRESS CHANGES WIDTH, and this fell through to "nothing to
            // emit". §3.1 keeps the two kinds apart on purpose, so the case has to be written out --
            // and left out, `address idtr = 0x402800;` stored the literal's THIRTY-TWO bits into a
            // sixty-four-bit slot and left the top half holding whatever the frame did. pico wrote
            // its interrupt descriptor table to 0x6000402800 and triple-faulted before printing its
            // second line.
            //
            // WIDENED BY THE SOURCE'S SIGN, which is the same rule `int` to `int` uses two arms up.
            // It used to zero-extend unconditionally, on the reasoning that an address has no sign
            // -- true of the destination and not of what is being converted. pico's syscall layer
            // returns its errnos as an `address`: `cast<address>(v.rmdir(...))` on -39 (ENOTEMPTY)
            // produced 0x00000000FFFFFFD9, and the ring-3 oracle -- hand-written assembly, which
            // cannot itself be miscompiled -- compared it against -39 and said `namespace ops
            // WRONG`. A positive value is unaffected either way, which is why `0x402800` above is
            // still right.
            in.op = to->bits < from->bits ? Op::Trunc
                    : isUnsignedValue(v)  ? Op::ExtendU
                                          : Op::ExtendS;
        } else if (from->kind == TypeKind::Addr && to->kind == TypeKind::Int) {
            // ...and back. `cast<int>(h & 0xFFFF)` on an `address` is the same question the other
            // way round, and it was the same silence.
            in.op = to->bits < from->bits ? Op::Trunc : Op::ExtendU;
        } else {
            // A cast between two class pointers is a reinterpretation the type table already agrees
            // with; nothing is emitted for it.
            return v;
        }
        return emit(std::move(in));
    }

    // A dotted chain, flattened: `System.IO.Console.println` -> "System.IO.Console.println". Used to
    // tell a QUALIFIED NAME from a RECEIVER, which is the distinction that was missing.
    static bool flatten(const ast::Expr* e, std::string* out) {
        if (auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            *out = id->name;
            return true;
        }
        if (auto* m = dynamic_cast<const ast::MemberExpr*>(e)) {
            std::string base;
            if (!flatten(m->object.get(), &base)) {
                return false;
            }
            *out = base + "." + m->member;
            return true;
        }
        return false;
    }

    // A LAMBDA IS A TOP-LEVEL FUNCTION PLUS A CAPTURE SET (§7.8). Lowered as one here rather than
    // left to the backend because the capture set is what escape analysis reads: a closure that
    // does not escape can have its environment on the stack, and a backend that had to work out
    // what was captured would have to do it once per backend.
    // WHAT A LAMBDA ACTUALLY CARRIES: the captures it declares, plus every free name its body
    // reads that resolves to an enclosing local. A capture list is an option in this language, not
    // an obligation -- `lambda(int x) returns int { return x + n; }` captures `n` by saying `n` --
    // so a lowering that carried only the declared ones carried nothing at all for most lambdas.
    // An auto-capture is by value, which is what keeps an escaping lambda from pointing at a frame
    // that has gone.
    std::vector<Captured> effectiveCaptures(const ast::LambdaExpr& lam) {
        std::vector<Captured> carried;
        std::unordered_set<std::string> already;
        auto take = [&](const std::string& name, bool byRef) {
            auto it = locals_.find(name);
            if (it == locals_.end() || !already.insert(name).second) {
                return;
            }
            Captured c;
            c.name = name;
            c.byRef = byRef;
            c.typeName = declaredName(it->second);
            auto held = slotType_.find(it->second);
            c.type = held != slotType_.end() ? held->second : out_.module.types.ptrType();
            carried.push_back(std::move(c));
        };
        for (const ast::Capture& cap : lam.captures) {
            take(cap.name, cap.byRef);
        }
        // A parameter of the lambda is not a capture: it shadows whatever the enclosing scope
        // called by that name.
        for (const ast::Param& p : lam.params) {
            already.insert(p.name);
        }
        std::set<std::string> mentioned;
        cgutil::collectRefs(lam.body, mentioned);
        for (const std::string& name : mentioned) {
            take(name, false);
        }
        return carried;
    }

    ValueId lowerLambda(const ast::LambdaExpr& lam) {
        TypeTable& tt = out_.module.types;
        const std::string key = "lambda$" + std::to_string(lambdaCount_++);

        // A CLOSURE IS `{ code, env }` BEHIND A POINTER, and its body takes the environment as its
        // FIRST parameter. This gave the body one parameter per capture instead, which is a
        // different calling convention from the one every caller uses -- so a lambda passed to a
        // method was called with the arguments in the wrong places, and one passed to the standard
        // library was called with none at all. The shape here is the trusted path's, because a
        // `function<...>` value crosses between code compiled by both.
        std::vector<Field> params;
        std::vector<Function::Param> plist;
        {
            Field env;
            env.type = tt.ptrType();
            env.name = "__env";
            params.push_back(env);
            plist.push_back({"__env", "", false});
        }
        for (const ast::Param& p : lam.params) {
            Field f;
            f.type = typeOf(p.type);
            params.push_back(f);
            plist.push_back({p.name, resolvedTypeName(p.type), passedByValue(p.type),
                             pointerDepthOfType(p.type)});
        }
        Function* body = out_.module.addFunction(
            key, tt.fnType(typeOf(lam.returnType), std::move(params)));
        body->params = std::move(plist);
        body->linkage = Linkage::Private;

        // The body is lowered with its OWN state -- a lambda inside a method must not see that
        // method's locals except through its captures, which is what the capture list is for.
        //
        // EVERY field, saved and restored. Saving four of them and forgetting `entryBlock_` meant
        // that after the lambda, the enclosing method's next `alloca` was inserted into the
        // LAMBDA's entry block -- a write into another function's storage, and the compiler died
        // with no message at all. A partial save is worse than none: it works until it does not.
        // EVERY PER-BODY FIELD, and the list has to grow when a field is added -- which is exactly
        // what went wrong again: `declaredAs_` and `storage_` were added later and not added
        // here, and `lowerBodyOf` CLEARS them. So a method that contained a lambda lost the declared
        // type of every value after it: `nums.add(1)` before the lambda resolved to
        // `ArrayList$int.add` and `nums.forEach(...)` after it resolved to `ArrayList$long.forEach`,
        // a different instantiation with a different element size.
        // WHAT THIS LAMBDA CARRIES, worked out BEFORE the outer frame is put away. The types come
        // from the enclosing locals, and the save below moves that map out from under this -- so
        // asking afterwards found nothing and every lambda came out capturing nothing at all.
        // Only the explicitly declared captures were being carried even then; a lambda that merely
        // MENTIONS an enclosing name got a null environment, and `makeAdder(5)` returned a closure
        // whose body read `n` out of address zero.
        const std::vector<Captured> carried = effectiveCaptures(lam);

        BodyState outer = saveBody();

        // The captured values, read out of the environment at the top of the body -- one slot each,
        // in declaration order, which is the order the creation site writes them.
        pendingCaptures_ = carried;
        fn_ = body;
        // WHICH FUNCTION `itself(...)` MEANS while this body is being lowered, and only while: a
        // lambda nested in another one is its own entity, and the outer key has to come back when
        // it ends.
        const std::string outerSelf = lambdaSelfKey_;
        lambdaSelfKey_ = key;
        lowerBodyOf(*body, "", lam.body);
        lambdaSelfKey_ = outerSelf;

        restoreBody(std::move(outer));

        Inst code;
        code.op = Op::ConstFn;
        code.type = tt.ptrType();
        code.text = key;
        code.loc = lam.loc;
        const ValueId fnv = emit(std::move(code));

        // THE ENVIRONMENT, one machine word per capture. Null when there is nothing to capture --
        // and most lambdas capture nothing, so the common case allocates one block, not two.
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        ValueId env = nullPointer(lam.loc);
        if (!carried.empty()) {
            env = callExternal(
                "__polaron_malloc", ptr, {i64},
                {constInt(static_cast<int64_t>(carried.size()) * 8, 64, lam.loc)}, lam.loc);
            int64_t at = 0;
            for (const Captured& cap : carried) {
                auto it = locals_.find(cap.name);
                if (it != locals_.end()) {
                    // `byref` SHARES THE VARIABLE, so what goes into the environment is its
                    // storage; `byvalue` copies, so what goes in is what the storage holds.
                    storeAt(env, at, cap.byRef ? it->second : loadFrom(it->second, lam.loc),
                            lam.loc);
                }
                at += 8;
            }
        }
        // A LAMBDA THAT CAPTURES NOTHING IS A CONSTANT, and belongs in the image rather than on the
        // heap. `{ code, null }` never changes, so there is one of it for the whole program instead
        // of one per evaluation -- and `forEach(x => x + 1)` inside a loop was allocating sixteen
        // bytes per iteration and never freeing them.
        //
        // BEING CONSTANT IS THE LARGER HALF. A closure the optimiser can read through is one it can
        // propagate into the higher-order method that receives it (IPSCCP), turning the per-element
        // indirect call into a direct and inlinable one. A fresh `malloc` every time is opaque by
        // construction: nothing downstream can prove what is in it.
        //
        // Spelled as a function table because that is what it is -- one code pointer and one empty
        // slot -- and the backend already emits those after the functions are declared, which is
        // exactly when a table naming one can be built.
        if (carried.empty()) {
            const std::string held = key + "$closure";
            Global g;
            g.name = held;
            g.type = ptr;
            g.linkage = Linkage::Internal;
            g.isConst = true;
            g.zeroInit = false;
            g.initFns = {key, std::string()};   // { code, env = null }
            out_.module.globals.push_back(std::move(g));
            Inst at;
            at.op = Op::ConstFn;   // §7.1: the address of a named module-level thing
            at.type = ptr;
            at.text = held;
            at.loc = lam.loc;
            const ValueId still = emit(std::move(at));
            cCallable_[still] = &lam;
            return still;
        }
        const ValueId closure =
            callExternal("__polaron_malloc", ptr, {i64}, {constInt(16, 64, lam.loc)}, lam.loc);
        storeAt(closure, 0, fnv, lam.loc);
        storeAt(closure, 8, env, lam.loc);
        // ...AND WHETHER IT COULD CROSS TO C, recorded against the closure value. A lambda that
        // captures nothing can be handed to a C callback as a raw function pointer -- see
        // `cCallbackFor` -- and only the creation site knows both facts: which body it is, and that
        // there was nothing to capture.
        if (carried.empty()) {
            cCallable_[closure] = &lam;
        }
        return closure;
    }

    // The C-callable form of a capture-free lambda: the same body, WITHOUT the environment
    // parameter, so a C caller's first argument lands in the first parameter. One per lambda,
    // emitted on demand -- a lambda that never crosses to C never gets one.
    ValueId cCallbackFor(ValueId closure, SourceLocation loc) {
        auto site = cCallable_.find(closure);
        if (site == cCallable_.end()) {
            return kNoValue;
        }
        const ast::LambdaExpr& lam = *site->second;
        auto made = cCallbacks_.find(&lam);
        const std::string key = made != cCallbacks_.end()
                                    ? made->second
                                    : "__polaron_cb_" + std::to_string(cCallbacks_.size());
        if (made == cCallbacks_.end()) {
            cCallbacks_[&lam] = key;
            TypeTable& tt = out_.module.types;
            std::vector<Field> params;
            std::vector<Function::Param> plist;
            for (const ast::Param& p : lam.params) {
                Field f;
                f.type = typeOf(p.type);
                f.name = p.name;
                params.push_back(f);
                plist.push_back({p.name, resolvedTypeName(p.type), passedByValue(p.type),
                                 pointerDepthOfType(p.type)});
            }
            Function* fn = out_.module.addFunction(
                key, tt.fnType(typeOf(lam.returnType), std::move(params)));
            fn->params = std::move(plist);
            fn->linkage = Linkage::Internal;
            fn->unwind = Unwind::Never;   // an exception crossing into C has nowhere to go
            BodyState outer = saveBody();
            fn_ = fn;
            lowerBodyOf(*fn, /*owner=*/std::string(), lam.body);
            restoreBody(std::move(outer));
        }
        Inst code;
        code.op = Op::ConstFn;
        code.type = out_.module.types.ptrType();
        code.text = key;
        code.loc = loc;
        return emit(std::move(code));
    }

    // ---- the String family ----
    //
    // A `String` METHOD IS NOT A METHOD. `s.length()` is not declared anywhere in the prelude: the
    // trusted path open-codes it, and the whole family with it. This pass had none of that, so a
    // call on a string resolved by bare name -- `data.length()` bound to `Buffer.length`, because
    // that key happened to come first -- and `data.charAt(i)` resolved to nothing and lowered to
    // `undef`. The checksum that added it produced a number, which is the worst possible outcome:
    // no crash, no diagnostic, a wrong answer that looks like an answer.
    //
    // A `String` is `{ i64 length, ptr data, i64 hash }` behind a pointer, which is the layout the
    // runtime and the trusted path both already agree on. The offsets below are that agreement.
    static constexpr int64_t kStrLength = 0;
    static constexpr int64_t kStrData = 8;
    static constexpr int64_t kStrHash = 16;
    static constexpr int64_t kStrSize = 24;

    ValueId strField(ValueId s, int64_t offset, const Type* held, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        Inst g;
        g.op = Op::Gep;
        g.type = tt.ptrType();
        g.operands.push_back(s);
        g.imm = offset;
        // NOT the text "length": the backend reads that word as "the array header", and a String is
        // not an array. The offset says the same thing without the coincidence of spelling.
        g.loc = loc;
        const ValueId addr = emit(std::move(g));
        Inst ld;
        ld.op = Op::Load;
        ld.type = held;
        ld.operands.push_back(addr);
        ld.loc = loc;
        return emit(std::move(ld));
    }

    // The address `base + offset` for a RAW byte buffer. `gep` cannot express this: its indexed form
    // skips an eight-byte array header, and a string's characters have none.
    ValueId rawOffset(ValueId base, ValueId offset, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        Inst toAddr;
        toAddr.op = Op::PtrToAddr;
        toAddr.type = tt.addrType(64);
        toAddr.operands.push_back(base);
        toAddr.loc = loc;
        const ValueId a = emit(std::move(toAddr));

        Inst wide;
        wide.op = Op::ExtendS;
        wide.type = tt.addrType(64);
        wide.operands.push_back(offset);
        wide.loc = loc;
        const ValueId off = emit(std::move(wide));

        Inst sum;
        sum.op = Op::AddWrap;
        sum.type = tt.addrType(64);
        sum.operands.push_back(a);
        sum.operands.push_back(off);
        sum.loc = loc;
        const ValueId at = emit(std::move(sum));

        Inst back;
        back.op = Op::AddrToPtr;
        back.type = tt.ptrType();
        back.operands.push_back(at);
        back.loc = loc;
        return emit(std::move(back));
    }

    ValueId callExternal(const std::string& symbol, const Type* ret,
                         std::vector<const Type*> paramTypes, std::vector<ValueId> args,
                         SourceLocation loc) {
        Function* fn = declareExternalTyped(symbol, ret, std::move(paramTypes));
        Inst in;
        in.op = Op::Call;
        in.text = fn->key;
        in.type = ret;
        in.operands = std::move(args);
        in.loc = loc;
        return emit(std::move(in));
    }

    // A fresh `String` over a buffer the caller owns, which is what every transform returns.
    ValueId makeString(ValueId length, ValueId data, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        Inst size;
        size.op = Op::ConstInt;
        size.type = tt.intType(64);
        size.imm = kStrSize;
        size.loc = loc;
        const ValueId bytes = emit(std::move(size));
        const ValueId obj = callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                         {bytes}, loc);
        storeAt(obj, kStrLength, length, loc);
        storeAt(obj, kStrData, data, loc);
        Inst zero;
        zero.op = Op::ConstInt;
        zero.type = tt.intType(64);
        zero.imm = 0;
        zero.loc = loc;
        storeAt(obj, kStrHash, emit(std::move(zero)), loc);   // content is new: no cached hash
        // IT IS A `String`, said here so every caller does not have to remember. Without it a
        // result used directly as an argument -- `printf("%s", a.toUpper())` -- crossed the C
        // boundary as the OBJECT rather than its bytes, and printed the header.
        noteName(obj, "String");
        // EVERY FRESH STRING IS A TEMPORARY UNTIL SOMETHING CLAIMS IT. The one funnel all fourteen
        // string-building sites go through, which is why the tracking is here rather than at each:
        // a site added later is tracked without anybody remembering to.
        stringTemps_.emplace_back(obj, here_);
        return obj;
    }

    void storeAt(ValueId object, int64_t offset, ValueId value, SourceLocation loc) {
        Inst g;
        g.op = Op::Gep;
        g.type = out_.module.types.ptrType();
        g.operands.push_back(object);
        g.imm = offset;
        g.loc = loc;
        const ValueId addr = emit(std::move(g));
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(value);
        st.operands.push_back(addr);
        st.loc = loc;
        emit(std::move(st));
    }

    // NOTHING, IN THE SHAPE THE VALUE HAS. `!x` compares against zero, and what zero IS depends on
    // what `x` is: an integer's, a float's, or a null pointer -- and `!p` on a handle asks whether
    // it is null, which is the same comparison written the same way.
    ValueId zeroLike(ValueId v, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* t = v != kNoValue ? fn_->value(v)->type : nullptr;
        if (t != nullptr && t->kind == TypeKind::Ptr) {
            Inst in;
            in.op = Op::ConstNull;
            in.type = t;
            in.loc = loc;
            return emit(std::move(in));
        }
        if (t != nullptr && t->kind == TypeKind::Float) {
            Inst in;
            in.op = Op::ConstFloat;
            in.type = t;
            in.fimm = 0.0;
            in.loc = loc;
            return emit(std::move(in));
        }
        return constInt(0, t != nullptr && t->kind == TypeKind::Int ? t->bits : 32, loc);
    }

    ValueId constInt(int64_t v, unsigned bits, SourceLocation loc) {
        Inst in;
        in.op = Op::ConstInt;
        in.type = out_.module.types.intType(bits);
        in.imm = v;
        in.loc = loc;
        return emit(std::move(in));
    }

    ValueId narrow(ValueId v, unsigned bits, SourceLocation loc) {
        Inst in;
        in.op = Op::Trunc;
        in.type = out_.module.types.intType(bits);
        in.operands.push_back(v);
        in.loc = loc;
        return emit(std::move(in));
    }

    // THE SAME NUMBER IN MORE BITS. Sign-extended, because Polaron's default integer is signed and
    // the one unsigned case that matters -- a `char` codepoint -- is never negative anyway.
    //
    // ...EXCEPT AN ADDRESS, WHICH HAS NO SIGN. `half/short/byte address` are narrow ADDRESSES, and
    // the top bit of one is part of the address rather than a minus. pico writes
    //
    //     public fixed short address TrampolineAt = 0x8000;
    //
    // -- the page below 64 KiB it copies the AP's real-mode trampoline to -- and sign-extending
    // sixteen bits of that gives 0xFFFFFFFFFFFF8000. The kernel brought up the entire desktop and
    // then page-faulted at exactly that address, copying the trampoline to minus thirty-two
    // kilobytes. CR2 in the report IS the constant, sign-extended.
    //
    // The KIND travels too. Widened into an `Int`, the result stops being an address for every rule
    // that asks afterwards -- including the one that decides the next widening.
    ValueId widen(ValueId v, unsigned bits, SourceLocation loc) {
        const Type* have = v != kNoValue ? fn_->value(v)->type : nullptr;
        const bool address = have != nullptr && have->kind == TypeKind::Addr;
        if (have != nullptr && (have->kind == TypeKind::Int || address) && have->bits >= bits) {
            return v;
        }
        Inst in;
        in.op = address ? Op::ExtendU : Op::ExtendS;
        in.type = address ? out_.module.types.addrType(bits) : out_.module.types.intType(bits);
        in.operands.push_back(v);
        in.loc = loc;
        return emit(std::move(in));
    }

    // A NUMBER AS TEXT: the runtime writes the digits, and the String object is built around them.
    // The same two helpers the trusted path calls, so the two agree down to the formatting.
    ValueId intToString(ValueId wide, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        const ValueId buf =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(24, loc)}, loc);
        const ValueId len =
            callExternal("__polaron_itoa", i64, {i64, ptr}, {wide, buf}, loc);
        const ValueId made = makeString(len, buf, loc);
        noteName(made, "String");
        return made;
    }

    ValueId floatToString(ValueId v, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        const Type* f64 = tt.floatType(64);
        ValueId wide = v;
        if (const Type* have = fn_->value(v)->type;
            have != nullptr && have->kind == TypeKind::Float && have->bits < 64) {
            Inst up;
            up.op = Op::FpExtend;
            up.type = f64;
            up.operands.push_back(v);
            up.loc = loc;
            wide = emit(std::move(up));
        }
        const ValueId buf =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(32, loc)}, loc);
        const ValueId len = callExternal("__polaron_ftoa", i64, {f64, ptr}, {wide, buf}, loc);
        const ValueId made = makeString(len, buf, loc);
        noteName(made, "String");
        return made;
    }

    // `args[0]` is the receiver; the rest are the call's own arguments, already lowered.
    ValueId lowerStringCall(const std::string& member, const std::vector<ValueId>& args,
                            SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i32 = tt.intType(32);
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        const ValueId s = args[0];
        const ValueId other = args.size() > 1 ? args[1] : kNoValue;

        if (member == "length") {
            return narrow(strField(s, kStrLength, i64, loc), 32, loc);
        }
        if (member == "isEmpty") {
            Inst eq;
            eq.op = Op::CmpEq;
            eq.type = tt.boolType();
            eq.operands.push_back(strField(s, kStrLength, i64, loc));
            eq.operands.push_back(constInt(0, 64, loc));
            eq.loc = loc;
            return emit(std::move(eq));
        }
        if (member == "charAt" && other != kNoValue) {
            const ValueId at = rawOffset(strField(s, kStrData, ptr, loc), other, loc);
            Inst ld;
            ld.op = Op::Load;
            ld.type = tt.intType(8);
            ld.operands.push_back(at);
            ld.loc = loc;
            const ValueId ch = emit(std::move(ld));
            // ZERO-extended: a `char` is a code point, and sign-extending byte 0xC3 gives -61.
            Inst up;
            up.op = Op::ExtendU;
            up.type = i32;
            up.operands.push_back(ch);
            up.loc = loc;
            return emit(std::move(up));
        }
        if (member == "equals" && other != kNoValue) {
            return callExternal("__polaron_str_eq", i32, {ptr, ptr}, {s, other}, loc);
        }
        // THE OBJECT FORM, and it is a different symbol. `__polaron_str_hash` takes the DATA and a
        // LENGTH -- two arguments -- and this was calling it with the String object and nothing
        // else: the object pointer was read as the text and the length came off the stack, so the
        // hash loop walked gigabytes of whatever was next in memory. Every `HashMap<String, ...>`
        // crashed on its first `put`. `__polaron_str_hash_obj` takes the object, caches the answer
        // in its third word, and is what the trusted path has always called.
        if (member == "hash" || member == "hashCode") {
            return callExternal("__polaron_str_hash_obj", i64, {ptr}, {s}, loc);
        }
        // ORDER, not equality: negative, zero or positive, which is what every sorted container
        // asks a key for. `strcmp` over the data pointers answers exactly that.
        if (member == "compareTo" && other != kNoValue) {
            return callExternal("strcmp", i32, {ptr, ptr},
                                {strField(s, kStrData, ptr, loc),
                                 strField(other, kStrData, ptr, loc)},
                                loc);
        }
        // `equalsKey` IS `equals` FOR A String -- the hook a hash container calls to compare two
        // keys. The prelude declares it on `Object` and overrides it here, and this pass had no
        // case for it, so every program in the corpus recorded the same gap: 137 samples, one each.
        if (member == "equalsKey" && other != kNoValue) {
            return callExternal("__polaron_str_eq", i32, {ptr, ptr}, {s, other}, loc);
        }
        if (member == "toInt") {
            return callExternal("atoi", i32, {ptr}, {strField(s, kStrData, ptr, loc)}, loc);
        }
        if (member == "toDouble") {
            return callExternal("atof", tt.floatType(64), {ptr},
                                {strField(s, kStrData, ptr, loc)}, loc);
        }
        if ((member == "indexOf" || member == "contains" || member == "startsWith") &&
            other != kNoValue) {
            const ValueId idx = callExternal(
                "__polaron_str_index", i64, {ptr, i64, ptr, i64},
                {strField(s, kStrData, ptr, loc), strField(s, kStrLength, i64, loc),
                 strField(other, kStrData, ptr, loc), strField(other, kStrLength, i64, loc)},
                loc);
            if (member == "indexOf") {
                return narrow(idx, 32, loc);
            }
            Inst cmp;
            cmp.op = member == "contains" ? Op::CmpGeS : Op::CmpEq;
            cmp.type = tt.boolType();
            cmp.operands.push_back(idx);
            cmp.operands.push_back(constInt(0, 64, loc));
            cmp.loc = loc;
            return emit(std::move(cmp));
        }
        if (member == "endsWith" && other != kNoValue) {
            return callExternal(
                "__polaron_str_ends", i32, {ptr, i64, ptr, i64},
                {strField(s, kStrData, ptr, loc), strField(s, kStrLength, i64, loc),
                 strField(other, kStrData, ptr, loc), strField(other, kStrLength, i64, loc)},
                loc);
        }
        // Every String method that RETURNS a String marks its result, so a chained call or a direct
        // argument keeps its identity: `trim` and `repeat` come straight from the runtime and need
        // saying so, since they do not go through `makeString`.
        // BOTH TAKE THE DATA AND THE LENGTH, and both WRITE the new length back through a pointer:
        // `__polaron_str_trim(d, len, &out)` and `__polaron_str_repeat(d, len, count, &out)`. They
        // were being called with the String OBJECT and nothing else, so the object's first word --
        // its length -- was read as the text, the length came off whatever the stack held, and the
        // result was a raw buffer marked as a String object. Three mistakes in one call, and the
        // only symptom was a wrong answer or a crash depending on the stack.
        if (member == "trim" || member == "repeat") {
            if (member == "repeat" && other == kNoValue) {
                return kNoValue;
            }
            Inst room;
            room.op = Op::Alloca;
            room.type = i64;
            room.text = "str.len";
            room.loc = loc;
            const ValueId outLen = emit(std::move(room));
            slotType_[outLen] = i64;
            const ValueId data = strField(s, kStrData, ptr, loc);
            const ValueId len = strField(s, kStrLength, i64, loc);
            const ValueId buf =
                member == "trim"
                    ? callExternal("__polaron_str_trim", ptr, {ptr, i64, ptr}, {data, len, outLen},
                                   loc)
                    : callExternal("__polaron_str_repeat", ptr, {ptr, i64, i64, ptr},
                                   {data, len, widen(other, 64, loc), outLen}, loc);
            const ValueId made = makeString(loadFrom(outLen, loc), buf, loc);
            noteName(made, "String");
            return made;
        }
        if (member == "toUpper" || member == "toLower") {
            const ValueId len = strField(s, kStrLength, i64, loc);
            const ValueId data = strField(s, kStrData, ptr, loc);
            // Both return a fresh BUFFER of the same length -- the case of a letter never changes
            // how many bytes it takes -- so the String is built around it here.
            const char* sym =
                member == "toUpper" ? "__polaron_str_upper" : "__polaron_str_lower";
            return makeString(len, callExternal(sym, ptr, {ptr, i64}, {data, len}, loc), loc);
        }
        if (member == "concat" && other != kNoValue) {
            return concat(s, other, loc);
        }
        // `append` MUTATES THE RECEIVER and hands it back for chaining (spec 4). Treated as `concat`
        // it built a new String and threw it away, so `s.append(t)` left `s` exactly as it was --
        // every builder in every program silently did nothing.
        if (member == "append" && other != kNoValue) {
            const ValueId joined = concat(s, other, loc);
            storeAt(s, kStrLength, strField(joined, kStrLength, i64, loc), loc);
            storeAt(s, kStrData, strField(joined, kStrData, ptr, loc), loc);
            storeAt(s, kStrHash, constInt(0, 64, loc), loc);   // the content changed: drop the hash
            // THE JOINED STRING IS CONSUMED, NOT DISCARDED. `concat` builds it with `makeString`,
            // which files it as a statement temporary to be freed at the next statement -- and the
            // three stores above have just handed its BUFFER to the receiver. Freeing the temporary
            // would free that buffer out from under `s`, so `s` reads freed memory and the scope end
            // frees it a second time. `mutable_string` caught it exactly there: "double free of a
            // heap block", then `a=x b=` where `b=xy` was expected.
            //
            // Claiming it leaks the 24-byte header, which is what the trusted path does too: its
            // `append` allocates the same header and never frees it either. Making the buffer's owner
            // unambiguous is the fix; reclaiming the header is a separate question, and one the two
            // backends have to answer the same way or the differential will say so.
            claimString(joined);
            return s;
        }
        if (member == "substring" && args.size() > 2) {
            const ValueId from = args[1];
            const ValueId to = args[2];
            Inst span;
            span.op = Op::SubWrap;
            span.type = i32;
            span.operands.push_back(to);
            span.operands.push_back(from);
            span.loc = loc;
            const ValueId n = emit(std::move(span));

            Inst wide;
            wide.op = Op::ExtendS;
            wide.type = i64;
            wide.operands.push_back(n);
            wide.loc = loc;
            const ValueId n64 = emit(std::move(wide));

            Inst plus;
            plus.op = Op::AddWrap;
            plus.type = i64;
            plus.operands.push_back(n64);
            plus.operands.push_back(constInt(1, 64, loc));   // room for the terminator
            plus.loc = loc;
            const ValueId room = emit(std::move(plus));

            const ValueId buf = callExternal("__polaron_malloc", ptr, {i64}, {room}, loc);
            const ValueId src = rawOffset(strField(s, kStrData, ptr, loc), from, loc);
            callExternal("memcpy", ptr, {ptr, ptr, i64}, {buf, src, n64}, loc);
            // NUL-terminated, because every runtime helper that takes the data pointer expects it.
            Inst nul;
            nul.op = Op::Store;
            nul.operands.push_back(constInt(0, 8, loc));
            nul.operands.push_back(rawOffset(buf, n, loc));
            nul.loc = loc;
            emit(std::move(nul));
            return makeString(n64, buf, loc);
        }
        return kNoValue;
    }

    // WHAT ONE STEP OVER THIS POINTER COVERS. A `T*` steps by a whole `T`; a bare `ptr` is opaque
    // by design and cannot say, so the DECLARATION is what answers.
    const Type* pointeeOf(ValueId v) {
        const Type* base = v != kNoValue ? fn_->value(v)->type : nullptr;
        if (base == nullptr || base->kind != TypeKind::Ptr) {
            return nullptr;
        }
        const std::string n = classNameOf(declaredName(v));
        return n.empty() ? nullptr : baseTypeOf(n);
    }

    // A RAW POINTER: a `T*` the programmer wrote, as opposed to an object handle (depth zero) or
    // an array (which carries a length header and is not walked this way).
    bool isRawPointer(ValueId v) {
        const Type* t = v != kNoValue ? fn_->value(v)->type : nullptr;
        return t != nullptr && t->kind == TypeKind::Ptr && pointerDepthOf(v) > 0;
    }

    // POINTER ARITHMETIC (spec 27). `p + n` and `p - n` step by whole ELEMENTS, and `q - p` is the
    // number of elements between two pointers -- not bytes, either way. None of it was lowered:
    // both sides went to the integer opcodes, so `p = p + 2` added two to an ADDRESS and the read
    // through it landed two bytes into the first element instead of at the third.
    Lowered pointerArith(const ast::BinaryExpr& b, ValueId l, ValueId r) {
        if (b.op != "+" && b.op != "-") {
            return nothing();
        }
        const bool leftIsPtr = isRawPointer(l);
        const bool rightIsPtr = isRawPointer(r);
        if (!leftIsPtr && !rightIsPtr) {
            return nothing();
        }
        TypeTable& tt = out_.module.types;
        const Type* elem = pointeeOf(leftIsPtr ? l : r);
        const int64_t stride = static_cast<int64_t>(
            std::max<uint64_t>(1, elem != nullptr ? elem->facts.size : 1));

        if (leftIsPtr && rightIsPtr) {
            if (b.op != "-") {
                return nothing();   // `p + q` is not an operation on two addresses
            }
            Inst here;
            here.op = Op::PtrToAddr;
            here.type = tt.addrType(64);
            here.operands.push_back(l);
            here.loc = b.loc;
            Inst there;
            there.op = Op::PtrToAddr;
            there.type = tt.addrType(64);
            there.operands.push_back(r);
            there.loc = b.loc;
            Inst span;
            span.op = Op::SubWrap;
            span.type = tt.intType(64);
            span.operands.push_back(emit(std::move(here)));
            span.operands.push_back(emit(std::move(there)));
            span.loc = b.loc;
            Inst count;
            count.op = Op::DivChecked;
            count.type = tt.intType(64);
            count.operands.push_back(emit(std::move(span)));
            count.operands.push_back(constLong(stride, b.loc));
            count.loc = b.loc;
            const ValueId out = emit(std::move(count));
            noteName(out, "long");
            return done(out);
        }

        const ValueId base = leftIsPtr ? l : r;
        ValueId steps = leftIsPtr ? r : l;
        if (steps == kNoValue) {
            return nothing();
        }
        if (b.op == "-") {
            Inst back;
            back.op = Op::NegWrap;
            back.type = fn_->value(steps)->type;
            back.operands.push_back(steps);
            back.loc = b.loc;
            steps = emit(std::move(back));
        }
        Inst scaled;
        scaled.op = Op::MulWrap;
        scaled.type = fn_->value(steps)->type;
        scaled.operands.push_back(steps);
        scaled.operands.push_back(
            constInt(stride, fn_->value(steps)->type->bits != 0 ? fn_->value(steps)->type->bits : 32,
                     b.loc));
        scaled.loc = b.loc;
        const ValueId out = rawOffset(base, emit(std::move(scaled)), b.loc);
        noteName(out, declaredName(base), pointerDepthOf(base));
        slotType_[out] = fn_->value(base)->type;
        return done(out);
    }

    // `&x` -- THE ADDRESS OF SOMETHING.
    //
    // An OBJECT's identity is already a pointer: `Box b` names a slot holding the address of the
    // object, so `&b` is that address, not the address of the slot. Anything else -- an int local,
    // an array element, a field, and a pointer variable, whose `&` must yield a `T**` -- is the
    // address of its STORAGE. Reading the object out for those would hand back the VALUE and use
    // it as a pointer, which is a silent memory-safety hole rather than a wrong number.
    ValueId addressExpr(const ast::UnaryExpr& u) {
        const ValueId slot = addressOf(u.operand.get());
        if (slot == kNoValue) {
            std::string what;
            if (!flatten(u.operand.get(), &what)) {
                what = "expression";
            }
            gap("AddressOf(cannot address " + what + ")", u.loc);
            return kNoValue;
        }
        const std::string written = declaredName(slot);
        const std::string cls = classNameOf(written);
        const Type* held = slotType_.count(slot) != 0 ? slotType_.at(slot) : nullptr;
        // `&x` ON AN OBJECT VARIABLE IS THE OBJECT'S ADDRESS, not the address of the handle that
        // holds it. The variable is a slot containing a pointer; taking the slot instead hands the
        // callee somewhere to write that is not the object, and a callee that writes -- an out
        // parameter -- then destroys the handle.
        //
        // ...AND THE CLASS IS LOOKED UP BY THE BARE NAME TOO. A declared type arrives qualified once
        // a namespace is involved, `findClass` missed it, and the rule fell through to "give the
        // slot". pico's ring-3 guest calls `said.takeHeader(&back, &saidFlags)` to fill a DNS
        // header: it filled the two locals themselves, and the next line read the header's id as if
        // it were the object's address.
        // The question is about the REPRESENTATION, and the slot answers it: a slot that holds a
        // POINTER for a variable declared with no stars is a handle to an object living elsewhere,
        // so its address is the pointer it holds. One that holds the thing itself has `held` as the
        // struct, and the slot IS the address.
        //
        // It used to also require the class to be findable by name and not a value type, and both
        // halves of that were wrong here. `DnsHeader` is a `struct` -- a value type -- but pico's
        // guest writes `DnsHeader back = new DnsHeader(0) on stack`, which puts the struct behind a
        // pointer like any other object; and the name arrives qualified once a namespace is
        // involved, so the lookup missed it anyway. Between them the rule fell through to "give the
        // slot", `said.takeHeader(&back, &saidFlags)` filled the two LOCALS instead of the header,
        // and the next line read the header's id as if it were the object's address.
        // A VALUE CLASS BEHIND A POINTER IS STILL BEHIND A POINTER. `DnsHeader` is a `struct`, and
        // pico's guest writes `DnsHeader back = new DnsHeader(0) on stack` -- which puts it behind a
        // handle like any other object, so `&back` is the pointer that handle holds. Excluding value
        // classes outright answered with the SLOT, and `said.takeHeader(&back, &saidFlags)` filled
        // the two locals instead of the header the DNS reply had to be read into.
        //
        // `held->kind == Ptr` is what separates the two cases and it is already required above: a
        // value class stored INLINE has the struct as its slot type, not a pointer, and takes the
        // other branch untouched.
        auto classNamed = [&](const std::string& n) {
            const ast::ClassDecl* d = findClass(n);
            if (d == nullptr) {
                if (const size_t dot = n.rfind('.'); dot != std::string::npos) {
                    d = findClass(n.substr(dot + 1));
                }
            }
            return d;
        };
        const bool handle = held != nullptr && held->kind == TypeKind::Ptr &&
                            pointerDepthOf(slot) == 0 && !cls.empty() &&
                            classNamed(cls) != nullptr;
        const ValueId out = handle ? loadFrom(slot, u.loc) : slot;
        // ONE MORE STAR THAN WHAT WAS ADDRESSED -- except for the object case, where the pointer
        // the slot already held IS the answer and its depth is unchanged.
        noteName(out, written, handle ? pointerDepthOf(slot) : pointerDepthOf(slot) + 1);
        if (const Type* inner = held; inner != nullptr && !handle) {
            slotType_[out] = inner;   // `*(&x)` reads back exactly what `x` holds
        }
        return out;
    }

    // `*p` -- ONE STAR PEELED OFF. A depth-one pointer to a reference class holds the object
    // pointer directly, so `*p` IS `p` and there is nothing to load; everything else is a load of
    // whatever the pointer points at.
    ValueId dereference(const ast::UnaryExpr& u) {
        const ValueId p = lowerExpr(u.operand.get());
        if (p == kNoValue) {
            return kNoValue;
        }
        const std::string written = declaredName(p);
        const std::string cls = classNameOf(written);
        const int depth = pointerDepthOf(p);
        if (depth <= 1 && !cls.empty() && findClass(cls) != nullptr && !isValueClass(cls)) {
            return p;
        }
        // WHAT COMES OUT OF A `T**` IS A `T*`, not a `T`. The load's type was taken from the base
        // name at every level, so `***ppp` loaded an `int` from the outermost pointer and then used
        // those four bytes as an address: `triple deref` faulted on the first read. Only the LAST
        // step yields the base type; every step above it yields a pointer.
        if (depth > 1) {
            slotType_[p] = out_.module.types.ptrType();
        } else if (slotType_.count(p) == 0 && !written.empty()) {
            if (const Type* base = baseTypeOf(cls.empty() ? written : cls); base != nullptr) {
                slotType_[p] = isValueClass(cls) || findClass(cls) == nullptr
                                   ? base
                                   : out_.module.types.ptrType();
            }
        }
        const ValueId out = loadFrom(p, u.loc);
        noteName(out, written, depth > 0 ? depth - 1 : 0);
        return out;
    }

    // ONE ARRAY, BUILT AND FILLED. The header holds the length; element k sits one stride past the
    // one before it. Extracted from the array literal because `Color.values()` builds exactly the
    // same thing from a different list, and two places that lay out an array slightly differently
    // is the bug class this compiler keeps closing.
    ValueId makeArray(const Type* elem, const std::vector<ValueId>& values, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const size_t count = values.size();
        // ONE SOURCE FOR THE STRIDE: the element type's own size, the same number the backend steps
        // by when it addresses element k. This used to special-case slices to eight here while the
        // type said sixteen, and the two disagreed by exactly one element.
        const uint64_t stride = std::max<uint64_t>(1, elem->facts.size);
        const Type* arr = tt.sliceType(elem);

        const ValueId total = constLong(static_cast<int64_t>(count * stride + 8), loc);
        Inst alloc;
        alloc.op = Op::Call;
        alloc.text = declareExternalTyped("__polaron_malloc", tt.ptrType(), {tt.intType(64)})->key;
        alloc.type = arr;
        alloc.operands.push_back(total);
        alloc.loc = loc;
        const ValueId mem = emit(std::move(alloc));
        noteStorage(mem, Storage::Heap);   // an array is always heap storage; `delete` frees it

        Inst put;
        put.op = Op::Store;
        put.operands.push_back(constLong(static_cast<int64_t>(count), loc));
        put.operands.push_back(mem);
        put.loc = loc;
        emit(std::move(put));

        for (size_t k = 0; k < count; ++k) {
            if (values[k] == kNoValue) {
                continue;
            }
            Inst at;
            at.op = Op::Gep;
            at.type = arr;
            at.operands.push_back(mem);
            at.operands.push_back(constInt(static_cast<int64_t>(k), 64, loc));
            at.loc = loc;
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(values[k]);
            st.operands.push_back(emit(std::move(at)));
            st.loc = loc;
            emit(std::move(st));
        }
        return mem;
    }

    // ONE CALL ON AN ENUM VALUE. The receiver is the ordinal, whether it came from a constant
    // written out in full or from a variable of the enum's type. `name()` is the built-in that
    // reads the declared identifier back out (spec 12.5) and is answered here rather than by a
    // symbol, because there is no method to call: with a constant ordinal it folds to one literal.
    ValueId callOnOrdinal(const std::string& en, const std::string& method, ValueId ordinal,
                          const ast::CallExpr& c) {
        if (const Function* target = resolveKey(en + "." + method)) {
            std::vector<ValueId> args;
            args.push_back(ordinal);
            for (const ast::ExprPtr& a : c.args) {
                args.push_back(lowerExpr(a.get()));
            }
            const ValueId out = emitCall(target, std::move(args), c.loc);
            if (auto it = returnName_.find(target->key); it != returnName_.end()) {
                noteName(out, it->second.name, it->second.pointerDepth);
            }
            return out;
        }
        auto found = enums_.find(en);
        // AN ORDINAL IS WHAT THESE ANSWER IN, and a java-style receiver is a singleton pointer --
        // so its ordinal is recovered by identity before either question can be asked of it.
        if ((method == "name" || method == "index" || method == "ordinal") &&
            found != enums_.end() && found->second->isJavaStyle) {
            ordinal = javaEnumOrdinal(*found->second, ordinal, c.loc);
        }
        if (method == "index" || method == "ordinal") {
            return ordinal;
        }
        if (method == "name" && c.args.empty()) {
            if (found == enums_.end()) {
                return kNoValue;
            }
            const std::vector<std::string>& consts = found->second->constants;
            // A chain of selects, one per constant, which is what the trusted path builds: no
            // branch, no allocation, and a constant ordinal folds the whole chain to one string.
            ValueId result = kNoValue;
            for (size_t i = 0; i < consts.size(); ++i) {
                Inst lit;
                lit.op = Op::ConstStr;
                lit.type = out_.module.types.ptrType();
                lit.text = consts[i];
                lit.loc = c.loc;
                const ValueId one = emit(std::move(lit));
                if (result == kNoValue) {
                    result = one;
                    continue;
                }
                Inst eq;
                eq.op = Op::CmpEq;
                eq.type = out_.module.types.boolType();
                eq.operands.push_back(ordinal);
                eq.operands.push_back(constInt(static_cast<int64_t>(i), 32, c.loc));
                eq.loc = c.loc;
                Inst pick;
                pick.op = Op::Select;
                pick.type = out_.module.types.ptrType();
                pick.operands.push_back(emit(std::move(eq)));
                pick.operands.push_back(one);
                pick.operands.push_back(result);
                pick.loc = c.loc;
                result = emit(std::move(pick));
            }
            noteName(result, "String");
            return result;
        }
        gap("EnumMethod(" + en + "." + method + ")", c.loc);
        return kNoValue;
    }

    // `Pair.sizeof()`, `Raw.sizeof(Pair)` and `Memory.sizeof(x)`: how many bytes one of these takes.
    // The first two NAME a type; the third names a value and asks about its type.
    Lowered lowerSizeOf(const std::string& qualified, const ast::CallExpr& c) {
        const size_t dot = qualified.rfind('.');
        if (dot == std::string::npos || qualified.substr(dot + 1) != "sizeof") {
            return nothing();
        }
        const std::string owner = qualified.substr(0, dot);
        std::string named;
        if (owner == "Raw" || owner == "Memory" || owner == "System.Memory") {
            if (c.args.empty()) {
                return nothing();
            }
            // `Raw.sizeof(Pair)` spells a TYPE in the argument position; `Memory.sizeof(x)` spells
            // a value. Reading the argument as a name first is what tells them apart.
            named = comptime::typeNameSpelled(*c.args.front());
            // A NAME THAT IS NOT A LOCAL IS A TYPE. Asking whether it is a CLASS is too narrow: a
            // `layout` is not one, and `Raw.sizeof(Packed)` over a layout is exactly the question
            // a `demand` about a wire format asks.
            if (named.empty() || locals_.count(named) != 0) {
                const ValueId v = lowerExpr(c.args.front().get());
                named = classNameOf(declaredName(v));
            }
        } else {
            if (!c.args.empty()) {
                return nothing();
            }
            named = owner;
        }
        const size_t inner = named.rfind('.');
        if (inner != std::string::npos) {
            named = named.substr(inner + 1);
        }
        const Type* shape = named.empty() ? nullptr : storageTypeOf(named);
        if (shape == nullptr) {
            return nothing();
        }
        // A class is a HANDLE, and `Pair.sizeof()` asks about the OBJECT, not about the pointer to
        // it -- so the struct is what the size is taken of.
        if (shape->kind == TypeKind::Ptr && named_.count(named) != 0) {
            shape = named_.at(named);
        }
        return done(narrow(sizeOfClass(shape, c.loc), 32, c.loc));
    }

    // `T.typeName()`, `T.isValue()`, `T.owns()`, `T.isMovable()`, `T.isUnique()`, `T.align()` and
    // an enum's `T.length()` -- a TYPE ANSWERING ABOUT ITSELF, at compile time.
    //
    // These are the five facts of §3.3 plus two, and this pass is the one place that already holds
    // all of them: the type table decided them once when the entry was made, which is the whole
    // reason the facts live on the entry rather than being re-derived by whoever asks. Unanswered,
    // each one was resolved as a qualified name, declared as an external, and failed to link on
    // `int.typeName` and `int.isValue` -- a call to a method on a primitive.
    Lowered lowerTypeQuery(const std::string& qualified, const ast::CallExpr& c) {
        const size_t dot = qualified.rfind('.');
        if (dot == std::string::npos || !c.args.empty()) {
            return nothing();
        }
        const std::string member = qualified.substr(dot + 1);
        if (member != "typeName" && member != "isValue" && member != "owns" &&
            member != "isMovable" && member != "isUnique" && member != "align" &&
            member != "length") {
            return nothing();
        }
        std::string named = qualified.substr(0, dot);
        if (const size_t inner = named.rfind('.'); inner != std::string::npos) {
            named = named.substr(inner + 1);
        }
        // A NAME THAT IS A LOCAL IS A VALUE, not a type: `pace.length()` on a variable is a method
        // call and has to stay one. Only a name nothing holds names a type here.
        if (named.empty() || locals_.count(named) != 0) {
            return nothing();
        }
        const ast::ClassDecl* decl = findClass(named);
        const auto enumeration = enums_.find(named);
        const bool primitive = isPrimitiveName(named);
        if (decl == nullptr && enumeration == enums_.end() && !primitive) {
            return nothing();
        }
        if (member == "typeName") {
            Inst text;
            text.op = Op::ConstStr;
            text.type = out_.module.types.ptrType();
            text.text = named;
            text.loc = c.loc;
            const ValueId lit = emit(std::move(text));
            noteName(lit, "String");
            return done(lit);
        }
        if (member == "length") {
            // Only an enum has one: it is how many constants it declares.
            if (enumeration == enums_.end()) {
                return nothing();
            }
            return done(constInt(static_cast<int64_t>(enumeration->second->constants.size()), 32,
                                 c.loc));
        }
        const Type* shape = storageTypeOf(named);
        if (shape != nullptr && shape->kind == TypeKind::Ptr && named_.count(named) != 0) {
            shape = named_.at(named);   // the OBJECT, not the handle to it
        }
        if (shape == nullptr) {
            return nothing();
        }
        if (member == "align") {
            return done(constInt(static_cast<int64_t>(shape->facts.align), 32, c.loc));
        }
        // A VALUE is copied where it stands; a class is reached through a pointer. Everything below
        // is read straight off the entry -- which is what having decided it once buys.
        bool answer = false;
        if (member == "isValue") {
            answer = decl == nullptr || decl->isStruct || decl->isUnion || decl->isRecord;
        } else if (member == "owns") {
            answer = shape->facts.owns;
        } else if (member == "isMovable") {
            answer = shape->facts.isMovable && decl != nullptr;
        } else {
            answer = shape->facts.isUnique;
        }
        Inst b;
        b.op = Op::ConstBool;
        b.type = out_.module.types.boolType();
        b.imm = answer ? 1 : 0;
        b.loc = c.loc;
        return done(emit(std::move(b)));
    }

    // A CATALOG-TYPED VALUE IS A TAGGED ORDINAL (spec 12.6): the implementing enum's id in the high
    // half of an i64, the constant's ordinal in the low half.
    //
    // It has to be tagged, because the ordinal ALONE cannot say which enum it came from -- and both
    // lower to a plain integer, so a value coerced only to the parameter's machine shape arrived
    // looking like the first implementer. `Scale.weigh(Stone.Slate)` read tag 0, dispatched as
    // `Ingot`, and answered 11 where the stone weighs 200. No error, no crash, wrong number.
    ValueId tagForCatalog(ValueId value, const std::string& fromEnum, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        auto id = enumTypeId_.find(fromEnum);
        if (id == enumTypeId_.end()) {
            return value;
        }
        // A JAVA-STYLE IMPLEMENTER'S VALUE IS A SINGLETON, so its ordinal is recovered first: what
        // travels inside a catalog value is always the ordinal, whichever form the enum has.
        ValueId ordinal = value;
        if (auto decl = enums_.find(fromEnum);
            decl != enums_.end() && decl->second->isJavaStyle) {
            ordinal = javaEnumOrdinal(*decl->second, value, loc);
        }
        Inst wide;
        wide.op = Op::ExtendU;   // the ordinal is a small non-negative number; zero-extend it
        wide.type = i64;
        wide.operands.push_back(ordinal);
        wide.loc = loc;
        Inst tagged;
        tagged.op = Op::Or;
        tagged.type = i64;
        tagged.operands.push_back(emit(std::move(wide)));
        tagged.operands.push_back(constLong(id->second << 32, loc));
        tagged.loc = loc;
        return emit(std::move(tagged));
    }

    // ...AND BACK. `h.weight()` on a `Heavy` unpacks the tag, then calls the implementer the tag
    // names -- directly when only one enum implements the catalog, and through a chain of
    // comparisons when several do.
    Lowered callThroughCatalog(const std::string& catalog, const std::string& method,
                               ValueId tagged, const ast::CallExpr& c) {
        auto implementers = catalogImplementers_.find(catalog);
        if (implementers == catalogImplementers_.end() || implementers->second.empty()) {
            return nothing();
        }
        TypeTable& tt = out_.module.types;
        const Type* i32 = tt.intType(32);
        const Type* i64 = tt.intType(64);

        std::vector<const Function*> bodies;
        std::vector<std::string> owners;
        for (const std::string& name : implementers->second) {
            if (const Function* body = resolveKey(name + "." + method)) {
                bodies.push_back(body);
                owners.push_back(name);
            }
        }
        if (bodies.empty()) {
            return nothing();
        }

        const ValueId ordinal = narrow(tagged, 32, c.loc);
        Inst high;
        high.op = Op::ShrL;
        high.type = i64;
        high.operands.push_back(tagged);
        high.operands.push_back(constLong(32, c.loc));
        high.loc = c.loc;
        const ValueId which = narrow(emit(std::move(high)), 32, c.loc);

        std::vector<ValueId> extra;
        for (const ast::ExprPtr& a : c.args) {
            extra.push_back(lowerExpr(a.get()));
        }

        const Type* result = bodies.front()->signature != nullptr
                                 ? bodies.front()->signature->element
                                 : tt.voidType();
        const bool produces = result != nullptr && result->kind != TypeKind::Void;
        const BlockId join = fn_->addBlock(fresh("cat.join"));
        ValueId answer = kNoValue;
        if (produces) {
            answer = fn_->addValue(result, ValueOrigin::BlockParam, join, 0, "");
            fn_->block(join)->params.push_back(answer);
        }
        auto arrive = [&](ValueId v) {
            Inst go;
            go.op = Op::Br;
            Edge e{join, {}};
            if (produces) {
                e.args.push_back(v != kNoValue ? v : undefOf(result, c.loc));
            }
            go.edges.push_back(e);
            go.loc = c.loc;
            emit(std::move(go));
        };

        for (size_t i = 0; i < bodies.size(); ++i) {
            const bool last = i + 1 == bodies.size();
            const BlockId run = fn_->addBlock(fresh("cat.run"));
            BlockId next = join;
            if (!last) {
                next = fn_->addBlock(fresh("cat.next"));
                branchOn(cmp(Op::CmpEq, which, constInt(enumTypeId_[owners[i]], 32, c.loc), c.loc),
                         run, next);
            } else {
                gotoIfOpen(run);   // the only one left: no test to make
            }
            here_ = run;
            // A JAVA-STYLE IMPLEMENTER'S METHOD TAKES ITS SINGLETON, recovered from the ordinal the
            // tag carries; an ordinal implementer's takes the ordinal itself.
            ValueId self = ordinal;
            if (auto decl = enums_.find(owners[i]);
                decl != enums_.end() && decl->second->isJavaStyle) {
                self = javaEnumFromOrdinal(*decl->second, ordinal, c.loc);
            }
            std::vector<ValueId> args;
            args.push_back(self);
            for (ValueId a : extra) {
                args.push_back(a);
            }
            const ValueId got = emitCall(bodies[i], std::move(args), c.loc);
            arrive(got);
            if (!last) {
                here_ = next;
            }
        }
        here_ = join;
        if (!produces) {
            return done(kNoValue);
        }
        if (auto named = returnName_.find(bodies.front()->key); named != returnName_.end()) {
            noteName(answer, named->second.name, named->second.pointerDepth);
        }
        return done(answer);
    }

    // The singleton an ordinal names: the inverse of `javaEnumOrdinal`, and a chain of selects for
    // the same reason -- a java-style enum's values are objects and the mapping is by identity.
    ValueId javaEnumFromOrdinal(const ast::EnumDecl& e, ValueId ordinal, SourceLocation loc) {
        ValueId answer = nullPointer(loc);
        for (size_t i = 0; i < e.constants.size(); ++i) {
            Inst pick;
            pick.op = Op::Select;
            pick.type = out_.module.types.ptrType();
            pick.operands.push_back(
                cmp(Op::CmpEq, ordinal, constInt(static_cast<int64_t>(i), 32, loc), loc));
            pick.operands.push_back(javaEnumSingleton(e, i, loc));
            pick.operands.push_back(answer);
            pick.loc = loc;
            answer = emit(std::move(pick));
        }
        noteName(answer, e.name);
        return answer;
    }

    // WHICH CONSTANT A SINGLETON IS. A java-style enum's value is an object, so its ordinal is not
    // carried anywhere -- it is recovered by identity, comparing the pointer against each of the
    // enum's singletons. A chain of selects, which is what `name()`, `index()` and a `match` over
    // one all need underneath.
    ValueId javaEnumOrdinal(const ast::EnumDecl& e, ValueId object, SourceLocation loc) {
        ValueId answer = constInt(0, 32, loc);
        for (size_t i = 0; i < e.constants.size(); ++i) {
            const ValueId one = javaEnumSingleton(e, i, loc);
            Inst pick;
            pick.op = Op::Select;
            pick.type = out_.module.types.intType(32);
            pick.operands.push_back(cmp(Op::CmpEq, object, one, loc));
            pick.operands.push_back(constInt(static_cast<int64_t>(i), 32, loc));
            pick.operands.push_back(answer);
            pick.loc = loc;
            answer = emit(std::move(pick));
        }
        return answer;
    }

    // A JAVA-STYLE ENUM'S CONSTANT: one shared object, built the first time it is named.
    //
    // The parser has already desugared the enum into a twin CLASS carrying the fields, the
    // constructor and the methods, plus a light enum holding the constants and their constructor
    // arguments. So the singleton is an ordinary object of that class, kept in a global, and built
    // lazily -- which is what makes `==` on two constants an identity test and what lets a constant
    // be named before the program has run anything.
    ValueId javaEnumSingleton(const ast::EnumDecl& e, size_t index, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        if (index >= e.constants.size()) {
            return nullPointer(loc);
        }
        const std::string held = e.name + "." + e.constants[index] + "$singleton";
        bool declared = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == held) {
                declared = true;
                break;
            }
        }
        if (!declared) {
            Global g;
            g.name = held;
            g.type = ptr;
            g.linkage = Linkage::Internal;
            g.zeroInit = true;
            out_.module.globals.push_back(std::move(g));
        }
        Inst where;
        where.op = Op::ConstFn;   // §7.1: the address of a named module-level thing
        where.type = ptr;
        where.text = held;
        where.loc = loc;
        const ValueId slot = emit(std::move(where));
        slotType_[slot] = ptr;

        const BlockId build = fn_->addBlock(fresh("enum.build"));
        const BlockId ready = fn_->addBlock(fresh("enum.ready"));
        branchOn(cmp(Op::CmpEq, loadFrom(slot, loc), nullPointer(loc), loc), build, ready);

        here_ = build;
        const Type* shape = named_.count(e.name) != 0 ? named_.at(e.name) : nullptr;
        // THE SINGLETON'S BYTES ARE STATIC, not allocated. There is exactly one of each constant
        // and it lives as long as the program does, so the storage is a global and the lazy flag
        // above only says whether the constructor has run yet -- which is what the trusted path
        // builds (`@Resolution.socketRefused.__store`) and what makes a constant nameable from a
        // program that has no allocator at all. Asking `__polaron_malloc` for it made every enum
        // with data depend on a heap: pico's ring-3 guest, which deliberately has none, could not
        // link -- 253 references to a symbol its source never mentions, one per constant per use.
        ValueId object = kNoValue;
        if (shape != nullptr) {
            const std::string bytes = e.name + "." + e.constants[index] + "$store";
            bool haveStore = false;
            for (const Global& g : out_.module.globals) {
                if (g.name == bytes) {
                    haveStore = true;
                    break;
                }
            }
            if (!haveStore) {
                Global g;
                g.name = bytes;
                g.type = shape;
                g.linkage = Linkage::Internal;
                g.zeroInit = true;
                out_.module.globals.push_back(std::move(g));
            }
            Inst at;
            at.op = Op::ConstFn;
            at.type = ptr;
            at.text = bytes;
            at.loc = loc;
            object = emit(std::move(at));
            pointee_[object] = shape;
        } else {
            // No interned shape means no size to reserve, and a wrong size is worse than a heap.
            object = callExternal("__polaron_malloc", ptr, {tt.intType(64)}, {constLong(16, loc)},
                                  loc);
        }
        if (const Function* ctor = resolveKey(e.name + "." + e.name)) {
            std::vector<ValueId> args;
            args.push_back(object);
            if (index < e.constantArgs.size()) {
                for (const ast::ExprPtr& a : e.constantArgs[index]) {
                    const ValueId v = lowerExpr(a.get());
                    if (v != kNoValue) {
                        args.push_back(v);
                    }
                }
            }
            emitCall(ctor, std::move(args), loc);
        }
        Inst keep;
        keep.op = Op::Store;
        keep.operands.push_back(object);
        keep.operands.push_back(slot);
        keep.loc = loc;
        emit(std::move(keep));
        gotoIfOpen(ready);

        here_ = ready;
        const ValueId got = loadFrom(slot, loc);
        noteName(got, e.name);
        if (shape != nullptr) {
            pointee_[got] = shape;
        }
        return got;
    }

    // THE TYPE TOKEN (spec 31): what a class knows about itself, as a value a program can hold.
    //
    // Twenty-two machine words, the same shape the trusted path builds, of which this fills the
    // ones a program can currently ask for: the name, the method names and the field names with
    // their declared types. The rest are zero, which is what "this token cannot answer that" looks
    // like -- and a reflective call that needs one of them records a gap rather than reading a
    // slot that was never written.
    //
    // BUILT AT THE CALL SITE rather than as a constant global, because a String object and an array
    // of them are things this lowering already knows how to make. A constant version would be a
    // second way to lay out a String, and the two would have to agree forever.
    // ...ONCE PER CLASS, not once per call.
    //
    // `reflect.typeOf<Nic>()` built a fresh token every time it was written: a 176-byte block, a
    // `String` object per method and per field, and an array for each of those lists -- all of it
    // allocated, none of it freed, and every one of them describing exactly the same class as the
    // last. A `typeOf` inside a loop is a leak that grows with the loop.
    //
    // The trusted path does not have this problem because its token is a `private constant` in the
    // image (`typeGlobals`). This is the same idea reached the way this backend can reach it: one
    // internal global per class, filled on first use, read thereafter. The token is deliberately
    // immortal -- so is a constant in the image -- and it is one allocation per class per program
    // instead of one per call site executed.
    //
    // STILL NOT A STATIC TABLE, and the difference matters on bare metal: a kernel with no heap
    // cannot answer `typeOf` at all, and `codegen_reflect_freestanding` says so by looking for
    // `@type.Nic = private constant %ReflectType`. That is the remaining gap and it is named here
    // rather than papered over.
    ValueId buildTypeToken(const std::string& cls, SourceLocation loc) {
        const std::string gname = "type." + cls;
        bool known = false;
        for (const ReflectToken& t : out_.module.reflectTokens) {
            known = known || t.cls == cls;
        }
        if (!known) {
            // DESCRIBED ONCE PER CLASS, not once per call site. Two `typeOf<Nic>()` in a program are
            // the same token, and it is a constant, so there is nothing for the second one to build.
            out_.module.reflectTokens.push_back(describeType(cls));
            // A METHOD THAT ONLY THE TABLE NAMES IS STILL REACHABLE. The reachability pass walks
            // instructions, and a constant is not one: every body the token points at looked dead
            // and was removed, so the image referenced `Dog.Dog` and defined nothing.
            //
            // That reflection makes the whole class reachable is not an accident of the
            // implementation -- it is what `typeOf<T>()` MEANS. A program that can ask a class for
            // its methods at run time has, by writing that, said that all of them may be called.
            rootTheseFunctions(out_.module.reflectTokens.back().slots);
        }
        Inst addr;
        addr.op = Op::ConstFn;
        addr.type = out_.module.types.ptrType();
        addr.text = gname;
        addr.loc = loc;
        const ValueId got = emit(std::move(addr));
        noteName(got, "Type");
        return got;
    }

    void rootTheseFunctions(const std::vector<ConstNode>& nodes) {
        for (const ConstNode& n : nodes) {
            if (n.kind == ConstNode::Kind::Fn && !n.text.empty()) {
                out_.module.extraRoots.push_back(n.text);
            }
            rootTheseFunctions(n.items);
        }
    }

    ReflectToken describeType(const std::string& cls) {
        ReflectToken token;
        token.cls = cls;
        token.slots.resize(22);

        auto text = [](const std::string& s) {
            ConstNode n;
            n.kind = ConstNode::Kind::Text;
            n.text = s;
            return n;
        };
        auto number = [](int64_t v) {
            ConstNode n;
            n.kind = ConstNode::Kind::Int;
            n.number = v;
            return n;
        };
        // A function the module does not have is a null slot, not a dangling name: verifier rule 15
        // refuses a reference to a key nothing defines, and a reflective reader asking for a body
        // that is not there should get nothing rather than an address.
        auto body = [&](const std::string& key) {
            ConstNode n;
            if (out_.module.find(key) != nullptr) {
                n.kind = ConstNode::Kind::Fn;
                n.text = key;
            }
            return n;
        };
        auto list = [](std::vector<ConstNode> items, bool wide = false) {
            ConstNode n;
            n.kind = ConstNode::Kind::Array;
            n.items = std::move(items);
            n.wide = wide;
            return n;
        };
        token.slots[0] = text(cls);

        // METHODS, most-derived first, an override shadowing the declaration it overrides -- what a
        // reflective reader is asking for is the implementation it would actually reach.
        //
        // AND ITS BODY WITH IT. A name alone answers `methodName(i)` and nothing else: `invoke` has
        // to reach the code, so the address travels beside the name, and so does the RETURN TAG,
        // because an indirect call has to be made through the right signature and a boxed result
        // has to know what it is boxing. Four parallel arrays here rather than four unrelated
        // walks, so a method's row cannot end up holding its neighbour's body.
        std::vector<ConstNode> methodNames;
        std::vector<ConstNode> methodFns;
        std::vector<ConstNode> methodTags;
        std::vector<ConstNode> methodAnnCounts;
        std::vector<ConstNode> methodAnnNames;
        std::vector<ConstNode> methodAnnArgs;
        std::unordered_set<std::string> seenMethods;
        for (std::string walk = cls; !walk.empty();) {
            const ast::ClassDecl* here = findClass(walk);
            if (here == nullptr || (walk == "Object" && walk != cls)) {
                break;
            }
            for (const ast::MemberPtr& m : here->members) {
                const auto* method = dynamic_cast<const ast::MethodDecl*>(m.get());
                if (method == nullptr || !seenMethods.insert(method->name).second) {
                    continue;
                }
                methodNames.push_back(text(method->name));
                methodFns.push_back(body(keyOfClass(*here) + "." + method->name));
                methodTags.push_back(number(returnTag(resolvedTypeName(method->returnType))));
                std::vector<ConstNode> names;
                std::vector<ConstNode> args;
                for (const ast::AnnotationUse& a : method->annotations) {
                    names.push_back(text(a.name));
                    args.push_back(text(renderAnnotationArgs(a)));
                }
                methodAnnCounts.push_back(number(static_cast<int64_t>(names.size())));
                methodAnnNames.push_back(list(std::move(names)));
                methodAnnArgs.push_back(list(std::move(args)));
            }
            walk = here->superclass;
        }
        token.slots[1] = number(static_cast<int64_t>(methodNames.size()));
        token.slots[2] = list(std::move(methodNames));
        token.slots[3] = list(std::move(methodFns));
        token.slots[12] = list(std::move(methodAnnCounts), /*wide=*/true);
        token.slots[13] = list(std::move(methodAnnNames));
        token.slots[14] = list(std::move(methodTags), /*wide=*/true);
        token.slots[21] = list(std::move(methodAnnArgs));

        // FIELDS, in the object's physical order, so a per-field accessor lines up with the layout.
        // The vtable pointer is not a field the program declared and is not reported.
        //
        // A FIELD NEEDS A WAY IN AND A WAY OUT. Reading one reflectively means the value crosses as
        // an Object, and only code that knows the field's width and signedness can box it -- so a
        // getter and a setter are generated per field, and the pair of addresses travels with the
        // name. Without them `Field.get(obj)` had nothing to call.
        std::vector<ConstNode> fieldNames;
        std::vector<ConstNode> fieldTypes;
        std::vector<ConstNode> fieldGet;
        std::vector<ConstNode> fieldSet;
        std::vector<ConstNode> fieldAnnCounts;
        std::vector<ConstNode> fieldAnnNames;
        std::vector<ConstNode> fieldAnnArgs;
        if (const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
            shape != nullptr) {
            for (const Field& f : shape->fields) {
                if (f.name == "__vtable" || f.name == "__persist") {
                    continue;
                }
                fieldNames.push_back(text(f.name));
                fieldTypes.push_back(text(fieldTypeSpelling(cls, f.name)));
                fieldGet.push_back(body(accessorKey(cls, f.name, /*setter=*/false)));
                fieldSet.push_back(body(accessorKey(cls, f.name, /*setter=*/true)));
                std::vector<ConstNode> names;
                std::vector<ConstNode> args;
                if (const std::vector<ast::AnnotationUse>* on = fieldAnnotations(cls, f.name);
                    on != nullptr) {
                    for (const ast::AnnotationUse& a : *on) {
                        names.push_back(text(a.name));
                        args.push_back(text(renderAnnotationArgs(a)));
                    }
                }
                fieldAnnCounts.push_back(number(static_cast<int64_t>(names.size())));
                fieldAnnNames.push_back(list(std::move(names)));
                fieldAnnArgs.push_back(list(std::move(args)));
            }
        }
        token.slots[4] = number(static_cast<int64_t>(fieldNames.size()));
        token.slots[5] = list(std::move(fieldNames));
        token.slots[10] = list(std::move(fieldGet));
        token.slots[11] = list(std::move(fieldSet));
        token.slots[16] = list(std::move(fieldTypes));
        token.slots[18] = list(std::move(fieldAnnCounts), /*wide=*/true);
        token.slots[19] = list(std::move(fieldAnnNames));
        token.slots[20] = list(std::move(fieldAnnArgs));

        // THE CLASS'S OWN ANNOTATIONS, and their arguments AS WRITTEN. An annotation that cannot
        // say what it was given is a marker and nothing more, so `[Range(min: 1)]` and
        // `[Range(min: 99)]` would be the same thing to a reader -- which is precisely the case a
        // declarative rule exists for.
        std::vector<ConstNode> annNames;
        std::vector<ConstNode> annArgs;
        if (const ast::ClassDecl* decl = findClass(cls); decl != nullptr) {
            for (const ast::AnnotationUse& a : decl->annotations) {
                annNames.push_back(text(a.name));
                annArgs.push_back(text(renderAnnotationArgs(a)));
            }
        }
        token.slots[8] = number(static_cast<int64_t>(annNames.size()));
        token.slots[9] = list(std::move(annNames));
        token.slots[17] = list(std::move(annArgs));

        // ...and how to MAKE one, for `instantiate()`: how many bytes an instance takes and which
        // function establishes it. A class whose name is only known at run time is still a class
        // the compiler laid out, so both are constants here.
        int64_t bytes = 8;
        if (const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
            shape != nullptr && shape->facts.size > 0) {
            bytes = static_cast<int64_t>(shape->facts.size);
        }
        token.slots[6] = number(bytes);
        token.slots[7] = body(cls + "." + cls);
        return token;
    }

    // The annotations written ON a field, found in whichever class up the chain declares it -- a
    // subclass's layout begins with its base's fields, and a rule written on one of those is
    // written in the base.
    // BORROWED, not copied: an annotation's arguments are expression nodes the AST owns, so the
    // list is not copyable and copying it would be wrong even if it were.
    const std::vector<ast::AnnotationUse>* fieldAnnotations(const std::string& owner,
                                                            const std::string& field) {
        for (std::string walk = owner; !walk.empty();) {
            const ast::ClassDecl* here = findClass(walk);
            if (here == nullptr) {
                break;
            }
            for (const ast::MemberPtr& m : here->members) {
                if (const auto* f = dynamic_cast<const ast::FieldDecl*>(m.get());
                    f != nullptr && f->name == field) {
                    return &f->annotations;
                }
            }
            walk = here->superclass;
        }
        return nullptr;
    }

    // An annotation's arguments as one string, `min=1,max=10`. Rendered rather than typed because
    // they are compile-time constants of several types and a reader wants them one at a time by
    // name -- keeping the parsing in the library means it can be tested and extended in Polaron.
    static std::string renderAnnotationArgs(const ast::AnnotationUse& a) {
        std::string out;
        for (const ast::AnnotationArg& arg : a.args) {
            if (!out.empty()) {
                out += ",";
            }
            out += arg.name + "=" + describeAnnotationValue(arg.value.get());
        }
        return out;
    }

    static std::string describeAnnotationValue(const ast::Expr* e) {
        if (const auto* i = dynamic_cast<const ast::IntLiteralExpr*>(e)) {
            return i->text;
        }
        if (const auto* f = dynamic_cast<const ast::FloatLiteralExpr*>(e)) {
            return f->text;
        }
        if (const auto* s = dynamic_cast<const ast::StringLiteralExpr*>(e)) {
            return s->value;
        }
        if (const auto* b = dynamic_cast<const ast::BoolLiteralExpr*>(e)) {
            return b->value ? "true" : "false";
        }
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(e)) {
            return id->name;
        }
        return std::string();
    }

    // WHAT AN INDIRECT CALL HAS TO KNOW about a method's result: not its name, which means nothing
    // at run time, but its shape -- which register it comes back in and what to box it as. Seven
    // tags, and 5 for "already a reference", where boxing would be wrapping a pointer twice.
    static int64_t returnTag(const std::string& rt) {
        const std::string b = cgutil::baseType(rt);
        if (b.empty() || b == "void") {
            return 0;
        }
        if (b == "long" || b == "int64" || b == "uint64" || b == "ulong") {
            return 2;
        }
        if (b == "double" || b == "float64") {
            return 3;
        }
        if (b == "float" || b == "float32" || b == "smallfloat") {
            return 4;
        }
        if (b == "byte" || b == "int8" || b == "ubyte" || b == "uint8") {
            return 6;
        }
        if (b == "short" || b == "int16" || b == "ushort" || b == "uint16") {
            return 7;
        }
        if (isBoxable(b)) {
            return 1;
        }
        return 5;
    }

    static bool isBoxable(const std::string& t) {
        const std::string b = cgutil::baseType(t);
        return b == "boolean" || b == "char" || cgutil::isIntName(b) || cgutil::isFloatType(b);
    }

    ValueId functionAddress(const std::string& key, SourceLocation loc) {
        Inst in;
        in.op = Op::ConstFn;
        in.type = out_.module.types.ptrType();
        in.text = key;
        in.loc = loc;
        return emit(std::move(in));
    }

    // The address of a per-field accessor, generating the accessor the first time it is asked for.
    ValueId accessorAddress(const std::string& cls, const std::string& field, bool setter,
                            SourceLocation loc) {
        const std::string key = accessorKey(cls, field, setter);
        return key.empty() ? nullPointer(loc) : functionAddress(key, loc);
    }

    // The same, as a NAME. The reflective token is a constant now, so what goes into it is the key
    // rather than an address -- and the accessor still has to be generated the first time anybody
    // asks, which is why this is not merely string concatenation.
    std::string accessorKey(const std::string& cls, const std::string& field, bool setter) {
        const std::string key = (setter ? "__fset." : "__fget.") + cls + "." + field;
        if (out_.module.find(key) == nullptr && !buildFieldAccessor(cls, field, setter, key)) {
            return {};
        }
        return key;
    }

    // ONE FUNCTION PER FIELD PER DIRECTION, and it is the only place that knows the field's width
    // and signedness -- which is exactly what a reflective read needs and what a caller holding a
    // `Field` token cannot know. A primitive is boxed on the way out and unboxed on the way in; a
    // reference crosses as itself.
    bool buildFieldAccessor(const std::string& cls, const std::string& field, bool setter,
                            const std::string& key) {
        const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
        if (shape == nullptr || shape->kind != TypeKind::Struct) {
            return false;
        }
        int64_t index = -1;
        for (size_t i = 0; i < shape->fields.size(); ++i) {
            if (shape->fields[i].name == field) {
                index = static_cast<int64_t>(i);
                break;
            }
        }
        if (index < 0) {
            return false;
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* held = shape->fields[static_cast<size_t>(index)].type;
        const std::string spelling = fieldTypeSpelling(cls, field);
        const bool prim = isBoxable(spelling);

        std::vector<Field> params;
        Field self;
        self.type = ptr;
        self.name = "obj";
        params.push_back(self);
        if (setter) {
            Field val;
            val.type = ptr;
            val.name = "value";
            params.push_back(val);
        }
        Function* fn = out_.module.addFunction(
            key, tt.fnType(setter ? tt.voidType() : ptr, std::move(params)));
        fn->params = setter ? std::vector<Function::Param>{{"obj", cls, false}, {"value", "", false}}
                            : std::vector<Function::Param>{{"obj", cls, false}};
        fn->linkage = Linkage::Internal;
        fn->unwind = Unwind::Never;

        // THE WHOLE PER-BODY STATE, not four fields of it. Value ids restart at zero in a new
        // function, so leaving `slotType_` and its siblings in place means the accessor's ids
        // collide with the ids of whatever body is halfway through being lowered: a `double` field's
        // address was filed under an id that, back in the caller, was a `Player*` local -- and the
        // load of that local came out `load double`, so the argument passed on was `undef`. That is
        // exactly the list `BodyState` exists to carry, and it had already been got wrong twice.
        BodyState outer = saveBody();
        fn_ = fn;
        here_ = fn->addBlock("entry");
        entryBlock_ = here_;
        allocaAt_ = 0;
        const ValueId object = fn->addValue(ptr, ValueOrigin::BlockParam, here_, 0, "obj");
        fn->block(here_)->params.push_back(object);
        ValueId incoming = kNoValue;
        if (setter) {
            incoming = fn->addValue(ptr, ValueOrigin::BlockParam, here_, 1, "value");
            fn->block(here_)->params.push_back(incoming);
        }
        Inst g;
        g.op = Op::Gep;
        g.type = ptr;
        g.operands.push_back(object);
        g.aggregate = shape;
        g.imm = index;
        g.text = field;
        const ValueId addr = emit(std::move(g));
        slotType_[addr] = held;
        if (setter) {
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(prim ? unboxWord(incoming, held, SourceLocation{}) : incoming);
            st.operands.push_back(addr);
            emit(std::move(st));
            Inst ret;
            ret.op = Op::Ret;
            emit(std::move(ret));
        } else {
            const ValueId got = loadFrom(addr, SourceLocation{});
            Inst ret;
            ret.op = Op::Ret;
            ret.operands.push_back(prim ? boxWord(got, spelling, SourceLocation{}) : got);
            emit(std::move(ret));
        }
        restoreBody(std::move(outer));
        return true;
    }

    // A BOX IS `{vtable, sixty-four bits}` -- the vtable so it answers to `Object`, and one word
    // because that is what holds any primitive the language has. Widened rather than reinterpreted
    // for an integer, and reinterpreted rather than converted for a float: the bits have to come
    // back out unchanged, and a conversion would round.
    ValueId boxWord(ValueId v, const std::string& from, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        const ValueId box =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(16, loc)}, loc);
        // THE `Object` TABLE, so the box answers to `Object` -- and null when the program has no
        // such table, which is honest rather than an address of nothing. Named through the same
        // `ConstFn` every vtable reference uses; asking for one that was never emitted produced
        // `store ptr undef`, and a box carrying `undef` as its dispatch table is a virtual call
        // into whatever the register held.
        bool haveObjectTable = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == "Object.vtable") {
                haveObjectTable = true;
                break;
            }
        }
        storeAt(box, 0, haveObjectTable ? functionAddress("Object.vtable", loc) : nullPointer(loc),
                loc);
        const Type* have = fn_->value(v)->type;
        ValueId word = v;
        if (have != nullptr && have->kind == TypeKind::Float) {
            Inst bits;
            bits.op = Op::Bitcast;
            bits.type = tt.intType(have->bits);
            bits.operands.push_back(v);
            bits.loc = loc;
            word = widen(emit(std::move(bits)), 64, loc);
        } else {
            word = widen(v, 64, loc);
        }
        storeAt(box, 8, word, loc);
        noteName(box, "Object");
        return box;
    }

    ValueId unboxWord(ValueId box, const Type* want, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        Inst at;
        at.op = Op::Gep;
        at.type = tt.ptrType();
        at.operands.push_back(box);
        at.imm = 8;
        at.loc = loc;
        const ValueId slot = emit(std::move(at));
        slotType_[slot] = tt.intType(64);
        const ValueId word = loadFrom(slot, loc);
        if (want == nullptr) {
            return word;
        }
        if (want->kind == TypeKind::Float) {
            Inst bits;
            bits.op = Op::Trunc;
            bits.type = tt.intType(want->bits);
            bits.operands.push_back(word);
            bits.loc = loc;
            Inst back;
            back.op = Op::Bitcast;
            back.type = want;
            back.operands.push_back(want->bits == 64 ? word : emit(std::move(bits)));
            back.loc = loc;
            return emit(std::move(back));
        }
        if (want->kind == TypeKind::Ptr) {
            Inst back;
            back.op = Op::AddrToPtr;
            back.type = want;
            back.operands.push_back(word);
            back.loc = loc;
            return emit(std::move(back));
        }
        // A `boolean` IS NOT AN INTEGER OF SOME WIDTH here -- it is its own kind, and its `bits` is
        // zero. Truncating to that width asked for `i0`, which is not a type LLVM has: the whole
        // module was refused with "bitwidth for integer type out of range" on a field the program
        // declared `boolean`.
        if (want->kind == TypeKind::Bool) {
            Inst zero;
            zero.op = Op::CmpNe;
            zero.type = want;
            zero.operands.push_back(word);
            zero.operands.push_back(constInt(0, 64, loc));
            zero.loc = loc;
            return emit(std::move(zero));
        }
        return want->bits >= 64 || want->bits == 0 ? word : narrow(word, want->bits, loc);
    }

    // A field's declared type as written, looked up under whichever class DECLARED it -- a
    // subclass's layout begins with its base's fields, and those are filed under the base.
    std::string fieldTypeSpelling(const std::string& owner, const std::string& field) {
        for (std::string walk = owner; !walk.empty();) {
            if (auto found = fieldTypeName_.find(walk + "." + field);
                found != fieldTypeName_.end()) {
                return found->second.name;
            }
            const ast::ClassDecl* up = findClass(walk);
            walk = up != nullptr ? up->superclass : std::string();
        }
        return std::string();
    }

    // WHAT A `Type` CAN BE ASKED. The token is a block of words; these are the reads of it. A
    // `Type` is a class the prelude declares, so without this the calls resolved to declarations
    // with no bodies and the link failed.
    Lowered reflectionMethod(ValueId receiver, const std::string& cls, const std::string& key,
                             const std::vector<ValueId>& args, SourceLocation loc) {
        if (receiver == kNoValue) {
            return nothing();
        }
        // IDENTITY IS EQUALITY FOR A TOKEN. All four are constants the compiler made, so a program
        // that keeps types or fields in a collection -- a registry is `HashMap<String, Type>` --
        // needs `hash` and `equalsKey`, and without them putting one in an ArrayList failed inside
        // the standard library on a method the token appears not to have.
        if (cls == "Type" || cls == "Method" || cls == "Field" || cls == "Annotation") {
            if (key == "hash" && args.size() == 1) {
                Inst in;
                in.op = Op::PtrToAddr;
                in.type = out_.module.types.intType(64);
                in.operands.push_back(receiver);
                in.loc = loc;
                return done(emit(std::move(in)));
            }
            if (key == "equalsKey" && args.size() == 2) {
                Inst in;
                in.op = Op::CmpEq;
                in.type = out_.module.types.boolType();
                in.operands.push_back(receiver);
                in.operands.push_back(args[1]);
                in.loc = loc;
                return done(widen(emit(std::move(in)), 32, loc));
            }
        }
        if (cls == "Method" || cls == "Field" || cls == "Annotation") {
            return tokenMethod(receiver, cls, key, args, loc);
        }
        if (cls != "Type") {
            return nothing();
        }
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        auto word = [&](int64_t slot, const Type* held) {
            Inst at;
            at.op = Op::Gep;
            at.type = ptr;
            at.operands.push_back(receiver);
            at.imm = slot * 8;
            at.loc = loc;
            const ValueId addr = emit(std::move(at));
            slotType_[addr] = held;
            return loadFrom(addr, loc);
        };
        auto nameAt = [&](int64_t slot) -> ValueId {
            if (args.size() < 2) {
                return kNoValue;
            }
            const ValueId table = word(slot, ptr);
            Inst step;
            step.op = Op::Gep;
            step.type = tt.sliceType(ptr);
            step.operands.push_back(table);
            step.operands.push_back(args[1]);
            step.loc = loc;
            const ValueId cell = emit(std::move(step));
            slotType_[cell] = ptr;
            const ValueId got = loadFrom(cell, loc);
            noteName(got, "String");
            return got;
        };

        if (key == "name") {
            const ValueId got = word(0, ptr);
            noteName(got, "String");
            return done(got);
        }
        if (key == "methodCount") {
            return done(narrow(word(1, i64), 32, loc));
        }
        if (key == "methodName") {
            return done(nameAt(2));
        }
        if (key == "fieldCount") {
            return done(narrow(word(4, i64), 32, loc));
        }
        if (key == "fieldName") {
            return done(nameAt(5));
        }
        if (key == "fieldTypeName") {
            return done(nameAt(16));
        }
        // `t.methods()` / `t.fields()` / `t.annotations()` -- the enumeration, as a list of tokens.
        // One loop, three shapes: which arrays to read and which token to build are the only
        // differences, and writing it three times is how the third one ends up reading the second
        // one's array.
        if (key == "methods" || key == "fields" || key == "annotations") {
            return done(buildTokenList(receiver, key, loc));
        }
        // `t.method(name)`: the Method token whose name matches, and a stop when none does. A
        // null-name token handed back instead would be dereferenced somewhere later, with nothing
        // left to say which lookup produced it.
        if (key == "method" && args.size() == 2) {
            return done(findMethodToken(receiver, args[1], loc));
        }
        // `t.instantiate()`: the size and the constructor are both in the token, so a class known
        // only at run time is still made the way the compiler lays it out.
        if (key == "instantiate") {
            const ValueId bytes = word(6, i64);
            const ValueId obj = callExternal("__polaron_malloc", ptr, {i64}, {bytes}, loc);
            callExternal("memset", ptr, {ptr, tt.intType(32), i64},
                         {obj, constInt(0, 32, loc), bytes}, loc);
            // ...AND WHATEVER THE CALLER PASSED, forwarded to the constructor. `instantiate(7)` on
            // a class whose constructor takes an `int` is the ordinary case, and dropping the 7
            // built the object with a zeroed field and nothing to say the argument went nowhere.
            std::vector<ValueId> all{obj};
            for (size_t i = 1; i < args.size(); ++i) {
                all.push_back(args[i]);
            }
            callIndirect(word(7, ptr), all, tt.voidType(), loc);
            noteName(obj, "Object");
            return done(obj);
        }
        return nothing();
    }

    // The three token lists a `Type` can hand out. Each row of the token's parallel arrays becomes
    // one token object, and the list is the standard `ArrayList` the program already knows.
    ValueId buildTokenList(ValueId type, const std::string& which, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        const bool methods = which == "methods";
        const bool anns = which == "annotations";
        const std::string listCls = resolveClassKey(methods       ? "ArrayList$Method"
                                                    : anns        ? "ArrayList$Annotation"
                                                                  : "ArrayList$Field");
        const Function* ctor = resolveKey(listCls + "." + listCls);
        const Function* add = resolveKey(listCls + ".add");
        if (ctor == nullptr || add == nullptr) {
            return nullPointer(loc);
        }
        const int64_t words = methods ? 6 : anns ? 2 : 7;
        const int64_t countSlot = methods ? 1 : anns ? 8 : 4;
        const int64_t namesSlot = methods ? 2 : anns ? 9 : 5;

        const Type* shape = named_.count(listCls) != 0 ? named_.at(listCls) : nullptr;
        const int64_t listBytes =
            shape != nullptr && shape->facts.size > 0 ? static_cast<int64_t>(shape->facts.size) : 64;
        const ValueId list =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(listBytes, loc)}, loc);
        callExternal("memset", ptr, {ptr, tt.intType(32), i64},
                     {list, constInt(0, 32, loc), constLong(listBytes, loc)}, loc);
        if (shape != nullptr) {
            pointee_[list] = shape;
        }
        noteName(list, listCls);
        emitCall(ctor, {list}, loc);

        auto slotOf = [&](int64_t at, const Type* held) {
            Inst g;
            g.op = Op::Gep;
            g.type = ptr;
            g.operands.push_back(type);
            g.imm = at * 8;
            g.loc = loc;
            const ValueId addr = emit(std::move(g));
            slotType_[addr] = held;
            return loadFrom(addr, loc);
        };
        const ValueId count = slotOf(countSlot, i64);
        // Every array the row needs, read ONCE before the loop: reading them inside would be the
        // same load per iteration and, worse, would put a definition in a block that does not
        // dominate its uses when the loop is entered from two edges.
        std::vector<ValueId> rows;
        std::vector<int64_t> rowSlots;
        rowSlots.push_back(namesSlot);
        if (methods) {
            rowSlots.insert(rowSlots.end(), {3, 12, 13, 14, 21});
        } else if (anns) {
            rowSlots.push_back(17);
        } else {
            rowSlots.insert(rowSlots.end(), {10, 11, 16, 18, 19, 20});
        }
        for (int64_t at : rowSlots) {
            rows.push_back(slotOf(at, ptr));
        }

        Inst room;
        room.op = Op::Alloca;
        room.type = i64;
        room.text = "tok.i";
        room.loc = loc;
        const ValueId iSlot = emit(std::move(room));
        slotType_[iSlot] = i64;
        Inst zero;
        zero.op = Op::Store;
        zero.operands.push_back(constLong(0, loc));
        zero.operands.push_back(iSlot);
        zero.loc = loc;
        emit(std::move(zero));
        const BlockId head = fn_->addBlock("tok.hdr");
        const BlockId body = fn_->addBlock("tok.body");
        const BlockId out = fn_->addBlock("tok.done");
        Inst go;
        go.op = Op::Br;
        go.edges.push_back(Edge{head, {}});
        go.loc = loc;
        emit(std::move(go));
        here_ = head;
        const ValueId i = loadFrom(iSlot, loc);
        Inst more;
        more.op = Op::CmpLtS;
        more.type = tt.boolType();
        more.operands.push_back(i);
        more.operands.push_back(count);
        more.loc = loc;
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(more)));
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{out, {}});
        br.loc = loc;
        emit(std::move(br));
        here_ = body;
        const ValueId at = loadFrom(iSlot, loc);
        const ValueId tok =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(words * 8, loc)}, loc);
        // The token's words come straight off the type's parallel arrays, in the order §31 puts
        // them in: name first for all three, then whatever that kind of token carries.
        for (size_t r = 0; r < rows.size(); ++r) {
            // Only slot 4 of a Field token and slot 2 of a Method token are counts; the rest are
            // pointers. Both are one machine word, and both are read and written as one.
            const bool isCount = (methods && r == 2) || (!methods && !anns && r == 4);
            Inst step;
            step.op = Op::Gep;
            step.type = tt.sliceType(isCount ? i64 : ptr);
            step.operands.push_back(rows[r]);
            step.operands.push_back(at);
            step.loc = loc;
            const ValueId cell = emit(std::move(step));
            slotType_[cell] = isCount ? i64 : ptr;
            storeAt(tok, static_cast<int64_t>(r) * 8, loadFrom(cell, loc), loc);
        }
        noteName(tok, methods ? "Method" : anns ? "Annotation" : "Field");
        emitCall(add, {list, tok}, loc);
        Inst next;
        next.op = Op::AddWrap;
        next.type = i64;
        next.operands.push_back(at);
        next.operands.push_back(constLong(1, loc));
        next.loc = loc;
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(emit(std::move(next)));
        put.operands.push_back(iSlot);
        put.loc = loc;
        emit(std::move(put));
        Inst again;
        again.op = Op::Br;
        again.edges.push_back(Edge{head, {}});
        again.loc = loc;
        emit(std::move(again));
        here_ = out;
        return list;
    }

    // `Type.method(name)`: a linear walk of the name array, and a panic when nothing matches.
    ValueId findMethodToken(ValueId type, ValueId want, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        auto slotOf = [&](int64_t at, const Type* held) {
            Inst g;
            g.op = Op::Gep;
            g.type = ptr;
            g.operands.push_back(type);
            g.imm = at * 8;
            g.loc = loc;
            const ValueId addr = emit(std::move(g));
            slotType_[addr] = held;
            return loadFrom(addr, loc);
        };
        const ValueId count = slotOf(1, i64);
        const ValueId names = slotOf(2, ptr);
        const ValueId fns = slotOf(3, ptr);
        const ValueId tags = slotOf(14, ptr);
        const ValueId annCounts = slotOf(12, ptr);
        const ValueId annNames = slotOf(13, ptr);
        const ValueId annArgs = slotOf(21, ptr);
        const ValueId tok =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(6 * 8, loc)}, loc);
        callExternal("memset", ptr, {ptr, tt.intType(32), i64},
                     {tok, constInt(0, 32, loc), constLong(6 * 8, loc)}, loc);
        const ValueId target = strField(want, kStrData, ptr, loc);

        Inst room;
        room.op = Op::Alloca;
        room.type = i64;
        room.text = "m.i";
        room.loc = loc;
        const ValueId iSlot = emit(std::move(room));
        slotType_[iSlot] = i64;
        Inst zero;
        zero.op = Op::Store;
        zero.operands.push_back(constLong(0, loc));
        zero.operands.push_back(iSlot);
        zero.loc = loc;
        emit(std::move(zero));
        const BlockId head = fn_->addBlock("m.hdr");
        const BlockId body = fn_->addBlock("m.body");
        const BlockId hit = fn_->addBlock("m.hit");
        const BlockId step = fn_->addBlock("m.next");
        const BlockId miss = fn_->addBlock("m.miss");
        const BlockId out = fn_->addBlock("m.end");
        Inst go;
        go.op = Op::Br;
        go.edges.push_back(Edge{head, {}});
        go.loc = loc;
        emit(std::move(go));
        here_ = head;
        Inst more;
        more.op = Op::CmpLtS;
        more.type = tt.boolType();
        more.operands.push_back(loadFrom(iSlot, loc));
        more.operands.push_back(count);
        more.loc = loc;
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(more)));
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{miss, {}});
        br.loc = loc;
        emit(std::move(br));

        here_ = body;
        const ValueId at = loadFrom(iSlot, loc);
        auto rowAt = [&](ValueId table, const Type* held) {
            Inst g;
            g.op = Op::Gep;
            g.type = tt.sliceType(held);
            g.operands.push_back(table);
            g.operands.push_back(at);
            g.loc = loc;
            const ValueId cell = emit(std::move(g));
            slotType_[cell] = held;
            return loadFrom(cell, loc);
        };
        const ValueId here = rowAt(names, ptr);
        Inst same;
        same.op = Op::CmpEq;
        same.type = tt.boolType();
        same.operands.push_back(callExternal("strcmp", tt.intType(32), {ptr, ptr},
                                             {strField(here, kStrData, ptr, loc), target}, loc));
        same.operands.push_back(constInt(0, 32, loc));
        same.loc = loc;
        Inst pick;
        pick.op = Op::BrCond;
        pick.operands.push_back(emit(std::move(same)));
        pick.edges.push_back(Edge{hit, {}});
        pick.edges.push_back(Edge{step, {}});
        pick.loc = loc;
        emit(std::move(pick));

        here_ = hit;
        storeAt(tok, 0, here, loc);
        storeAt(tok, 1 * 8, rowAt(fns, ptr), loc);
        storeAt(tok, 2 * 8, rowAt(annCounts, i64), loc);
        storeAt(tok, 3 * 8, rowAt(annNames, ptr), loc);
        storeAt(tok, 4 * 8, rowAt(tags, i64), loc);
        storeAt(tok, 5 * 8, rowAt(annArgs, ptr), loc);
        Inst found;
        found.op = Op::Br;
        found.edges.push_back(Edge{out, {}});
        found.loc = loc;
        emit(std::move(found));

        here_ = step;
        Inst next;
        next.op = Op::AddWrap;
        next.type = i64;
        next.operands.push_back(at);
        next.operands.push_back(constLong(1, loc));
        next.loc = loc;
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(emit(std::move(next)));
        put.operands.push_back(iSlot);
        put.loc = loc;
        emit(std::move(put));
        Inst again;
        again.op = Op::Br;
        again.edges.push_back(Edge{head, {}});
        again.loc = loc;
        emit(std::move(again));

        // NO METHOD OF THAT NAME IS A STOP, not a token with nothing in it. A null-fn token is
        // dereferenced somewhere later, with nothing left to say which lookup produced it.
        here_ = miss;
        callExternal("__polaron_panic", tt.voidType(), {tt.ptrType()},
                     {literalText("reflection: Type.method(name) found no method with that name",
                                  loc)},
                     loc);
        Inst stop;
        stop.op = Op::Br;
        stop.edges.push_back(Edge{out, {}});
        stop.loc = loc;
        emit(std::move(stop));

        here_ = out;
        noteName(tok, "Method");
        return tok;
    }

    // What a `Method`, a `Field` and an `Annotation` can be asked. Each is a block of words the
    // type token filled; these are the reads of it, plus the two that DO something -- `invoke` and
    // `get`/`set`, which reach the code and the storage the words point at.
    Lowered tokenMethod(ValueId receiver, const std::string& cls, const std::string& key,
                        const std::vector<ValueId>& args, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        auto word = [&](int64_t slot, const Type* held) {
            Inst at;
            at.op = Op::Gep;
            at.type = ptr;
            at.operands.push_back(receiver);
            at.imm = slot * 8;
            at.loc = loc;
            const ValueId addr = emit(std::move(at));
            slotType_[addr] = held;
            return loadFrom(addr, loc);
        };
        if (key == "name") {
            const ValueId got = word(0, ptr);
            noteName(got, "String");
            return done(got);
        }
        if (cls == "Annotation" && key == "args") {
            const ValueId got = word(1, ptr);
            noteName(got, "String");
            return done(got);
        }
        if (cls == "Field" && key == "typeName") {
            const ValueId got = word(3, ptr);
            noteName(got, "String");
            return done(got);
        }
        if (cls == "Field" && key == "get" && args.size() == 2) {
            const ValueId got = callIndirect(word(1, ptr), {args[1]}, ptr, loc);
            noteName(got, "Object");
            return done(got);
        }
        if (cls == "Field" && key == "set" && args.size() == 3) {
            // THE VALUE CROSSES AS AN OBJECT, so a primitive written through a `Field` has to be
            // boxed at the call site -- the setter on the other end knows the width and unboxes,
            // and it is the only thing that does.
            ValueId value = args[2];
            const Type* have = fn_->value(value)->type;
            if (have != nullptr && have->kind != TypeKind::Ptr) {
                value = boxWord(value, have->kind == TypeKind::Float ? "double" : "long", loc);
            }
            callIndirect(word(2, ptr), {args[1], value}, tt.voidType(), loc);
            return done();
        }
        if (key == "annotations") {
            return done(annotationList(receiver, cls, loc));
        }
        if (cls == "Method" && key == "invoke" && args.size() >= 2) {
            return done(invokeThroughToken(receiver, args, loc));
        }
        if (cls == "Method" && key == "firstByte") {
            Inst at;
            at.op = Op::Load;
            at.type = tt.intType(8);
            at.operands.push_back(word(1, ptr));
            at.loc = loc;
            const ValueId raw = emit(std::move(at));
            // A MACHINE-CODE BYTE HAS NO SIGN. `widen` extends by the source's sign, which is right
            // for an `int` and wrong for this: after an `unimport` the first byte is 0xCC, and the
            // whole point of the method is to be able to SEE that. Sign-extended it reads -52, which
            // is the same eight bits saying something the program did not ask.
            Inst up;
            up.op = Op::ExtendU;
            up.type = tt.intType(32);
            up.operands.push_back(raw);
            up.loc = loc;
            return done(emit(std::move(up)));
        }
        (void)i64;
        return nothing();
    }

    // A `Method`'s or a `Field`'s own annotations, out of the count/names/args triple it carries.
    ValueId annotationList(ValueId token, const std::string& cls, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        // A METHOD TOKEN'S ARGUMENTS ARE NOT NEXT TO ITS NAMES. Its slots are {name, fn, annCount,
        // annNames, retTag, annArgs} -- the return tag sits between the two -- so counting forward
        // from the count read the TAG as the argument array and dereferenced a small integer.
        const int64_t countSlot = cls == "Method" ? 2 : 4;
        const int64_t namesSlotAt = countSlot + 1;
        const int64_t argsSlotAt = cls == "Method" ? 5 : 6;
        const std::string listCls = resolveClassKey("ArrayList$Annotation");
        const Function* ctor = resolveKey(listCls + "." + listCls);
        const Function* add = resolveKey(listCls + ".add");
        if (ctor == nullptr || add == nullptr) {
            return nullPointer(loc);
        }
        auto word = [&](int64_t slot, const Type* held) {
            Inst at;
            at.op = Op::Gep;
            at.type = ptr;
            at.operands.push_back(token);
            at.imm = slot * 8;
            at.loc = loc;
            const ValueId addr = emit(std::move(at));
            slotType_[addr] = held;
            return loadFrom(addr, loc);
        };
        const ValueId count = word(countSlot, i64);
        const ValueId names = word(namesSlotAt, ptr);
        const ValueId argv = word(argsSlotAt, ptr);
        const Type* shape = named_.count(listCls) != 0 ? named_.at(listCls) : nullptr;
        const int64_t listBytes =
            shape != nullptr && shape->facts.size > 0 ? static_cast<int64_t>(shape->facts.size) : 64;
        const ValueId list =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(listBytes, loc)}, loc);
        callExternal("memset", ptr, {ptr, tt.intType(32), i64},
                     {list, constInt(0, 32, loc), constLong(listBytes, loc)}, loc);
        if (shape != nullptr) {
            pointee_[list] = shape;
        }
        noteName(list, listCls);
        emitCall(ctor, {list}, loc);

        Inst room;
        room.op = Op::Alloca;
        room.type = i64;
        room.text = "ann.i";
        room.loc = loc;
        const ValueId iSlot = emit(std::move(room));
        slotType_[iSlot] = i64;
        Inst zero;
        zero.op = Op::Store;
        zero.operands.push_back(constLong(0, loc));
        zero.operands.push_back(iSlot);
        zero.loc = loc;
        emit(std::move(zero));
        const BlockId head = fn_->addBlock("ann.hdr");
        const BlockId body = fn_->addBlock("ann.body");
        const BlockId out = fn_->addBlock("ann.done");
        Inst go;
        go.op = Op::Br;
        go.edges.push_back(Edge{head, {}});
        go.loc = loc;
        emit(std::move(go));
        here_ = head;
        Inst more;
        more.op = Op::CmpLtS;
        more.type = tt.boolType();
        more.operands.push_back(loadFrom(iSlot, loc));
        more.operands.push_back(count);
        more.loc = loc;
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(more)));
        br.edges.push_back(Edge{body, {}});
        br.edges.push_back(Edge{out, {}});
        br.loc = loc;
        emit(std::move(br));
        here_ = body;
        const ValueId at = loadFrom(iSlot, loc);
        auto rowAt = [&](ValueId table) {
            Inst g;
            g.op = Op::Gep;
            g.type = tt.sliceType(ptr);
            g.operands.push_back(table);
            g.operands.push_back(at);
            g.loc = loc;
            const ValueId cell = emit(std::move(g));
            slotType_[cell] = ptr;
            return loadFrom(cell, loc);
        };
        const ValueId tok =
            callExternal("__polaron_malloc", ptr, {i64}, {constLong(16, loc)}, loc);
        storeAt(tok, 0, rowAt(names), loc);
        storeAt(tok, 8, rowAt(argv), loc);
        noteName(tok, "Annotation");
        emitCall(add, {list, tok}, loc);
        Inst next;
        next.op = Op::AddWrap;
        next.type = i64;
        next.operands.push_back(at);
        next.operands.push_back(constLong(1, loc));
        next.loc = loc;
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(emit(std::move(next)));
        put.operands.push_back(iSlot);
        put.loc = loc;
        emit(std::move(put));
        Inst again;
        again.op = Op::Br;
        again.edges.push_back(Edge{head, {}});
        again.loc = loc;
        emit(std::move(again));
        here_ = out;
        return list;
    }

    // `m.invoke(receiver, args...)`. The result type is a TAG, not a type -- the call site has no
    // idea what it is calling -- so the call is made once per tag under a switch, each arm using
    // the signature that tag names, and the boxed answers meet at the join.
    ValueId invokeThroughToken(ValueId token, const std::vector<ValueId>& args,
                               SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* ptr = tt.ptrType();
        const Type* i64 = tt.intType(64);
        auto word = [&](int64_t slot, const Type* held) {
            Inst at;
            at.op = Op::Gep;
            at.type = ptr;
            at.operands.push_back(token);
            at.imm = slot * 8;
            at.loc = loc;
            const ValueId addr = emit(std::move(at));
            slotType_[addr] = held;
            return loadFrom(addr, loc);
        };
        const ValueId target = word(1, ptr);
        const ValueId tag = word(4, i64);
        std::vector<ValueId> pass(args.begin() + 1, args.end());

        Inst room;
        room.op = Op::Alloca;
        room.type = ptr;
        room.text = "invoke.r";
        room.loc = loc;
        const ValueId answer = emit(std::move(room));
        slotType_[answer] = ptr;
        Inst none;
        none.op = Op::Store;
        none.operands.push_back(nullPointer(loc));
        none.operands.push_back(answer);
        none.loc = loc;
        emit(std::move(none));

        const BlockId join = fn_->addBlock("invoke.cont");
        // The tags §31 defines, each with the return shape it names. `0` is void and `5` is a
        // reference, and neither is boxed -- the first has nothing to box and the second is
        // already an Object.
        //
        // A CHAIN OF EQUALITY TESTS, not one `switch`. A case value here is one of eight small
        // integers, so the two shapes cost the same -- and the chain is the one shape this lowering
        // already emits everywhere, which is what `lowerSwitch` says and why it says it.
        struct Arm {
            int64_t tag;
            const char* spelling;
        };
        static constexpr Arm kArms[] = {{0, "void"},  {1, "int"}, {2, "long"}, {3, "double"},
                                        {4, "float"}, {5, "ptr"}, {6, "byte"}, {7, "short"}};
        for (const Arm& a : kArms) {
            const BlockId take = fn_->addBlock("invoke.t" + std::to_string(a.tag));
            const BlockId next = fn_->addBlock("invoke.n" + std::to_string(a.tag));
            Inst same;
            same.op = Op::CmpEq;
            same.type = tt.boolType();
            same.operands.push_back(tag);
            same.operands.push_back(constLong(a.tag, loc));
            same.loc = loc;
            Inst br;
            br.op = Op::BrCond;
            br.operands.push_back(emit(std::move(same)));
            br.edges.push_back(Edge{take, {}});
            br.edges.push_back(Edge{next, {}});
            br.loc = loc;
            emit(std::move(br));
            here_ = take;
            const Type* ret = a.tag == 0   ? tt.voidType()
                              : a.tag == 1 ? tt.intType(32)
                              : a.tag == 2 ? tt.intType(64)
                              : a.tag == 3 ? tt.floatType(64)
                              : a.tag == 4 ? tt.floatType(32)
                              : a.tag == 5 ? ptr
                              : a.tag == 6 ? tt.intType(8)
                                           : tt.intType(16);
            const ValueId got = callIndirect(target, pass, ret, loc);
            ValueId boxed = nullPointer(loc);
            if (a.tag == 5) {
                boxed = got;
            } else if (a.tag != 0) {
                boxed = boxWord(got, a.spelling, loc);
            }
            Inst put;
            put.op = Op::Store;
            put.operands.push_back(boxed);
            put.operands.push_back(answer);
            put.loc = loc;
            emit(std::move(put));
            Inst go;
            go.op = Op::Br;
            go.edges.push_back(Edge{join, {}});
            go.loc = loc;
            emit(std::move(go));
            here_ = next;
        }
        Inst go;
        go.op = Op::Br;
        go.edges.push_back(Edge{join, {}});
        go.loc = loc;
        emit(std::move(go));
        here_ = join;
        const ValueId got = loadFrom(answer, loc);
        noteName(got, "Object");
        return got;
    }

    // A call through an address rather than to a name. The signature is built from what the caller
    // says it is passing, because that is all a reflective call ever knows.
    ValueId callIndirect(ValueId target, const std::vector<ValueId>& args, const Type* ret,
                         SourceLocation loc) {
        std::vector<Field> params;
        for (ValueId a : args) {
            Field p;
            p.type = fn_->value(a)->type;
            params.push_back(p);
        }
        Inst in;
        in.op = Op::CallIndirect;
        in.type = ret;
        in.aggregate = out_.module.types.fnType(ret, std::move(params));
        in.operands.push_back(target);
        for (ValueId a : args) {
            in.operands.push_back(a);
        }
        in.loc = loc;
        return emit(std::move(in));
    }

    // `Some(ordinal)` or `None`, from the index a parse landed on -- negative for "no constant of
    // that name". Built as the ordinary objects, because that is what an `Option` is in this
    // lowering and what `match` over one reads.
    ValueId buildParsedOption(const std::string& en, ValueId which, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const BlockId some = fn_->addBlock(fresh("parsesome"));
        const BlockId none = fn_->addBlock(fresh("parsenone"));
        const BlockId join = fn_->addBlock(fresh("parsejoin"));
        const ValueId answer =
            fn_->addValue(tt.ptrType(), ValueOrigin::BlockParam, join, 0, "");
        fn_->block(join)->params.push_back(answer);
        Inst ok;
        ok.op = Op::CmpGeS;
        ok.type = tt.boolType();
        ok.operands.push_back(which);
        ok.operands.push_back(constInt(0, 32, loc));
        ok.loc = loc;
        branchOn(emit(std::move(ok)), some, none);
        auto build = [&](BlockId from, const std::string& variant, bool carries) {
            here_ = from;
            const std::string cls = resolveClassKey(variant + "$" + en);
            const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
            ValueId obj = nullPointer(loc);
            if (shape != nullptr) {
                const int64_t size =
                    shape->facts.size > 0 ? static_cast<int64_t>(shape->facts.size) : 16;
                obj = callExternal("__polaron_malloc", tt.ptrType(), {tt.intType(64)},
                                   {constLong(size, loc)}, loc);
                pointee_[obj] = shape;
                noteName(obj, cls);
                if (const Function* ctor = resolveKey(cls + "." + cls)) {
                    std::vector<ValueId> args{obj};
                    if (carries) {
                        // WHAT A `Some` CARRIES IS THE VALUE, and for a java-style enum the value
                        // is the SINGLETON, not the ordinal (§12.5 says so in as many words). The
                        // ordinal went in as the payload, so `case Some(Planet p) -> p.density()`
                        // called a method on address 1 and the program died where it should have
                        // printed 10. An int-style enum IS its ordinal and passes it unchanged.
                        ValueId payload = which;
                        if (auto decl = enums_.find(en);
                            decl != enums_.end() && decl->second != nullptr &&
                            decl->second->isJavaStyle) {
                            payload = javaEnumFromOrdinal(*decl->second, which, loc);
                        }
                        args.push_back(payload);
                    }
                    emitCall(ctor, std::move(args), loc);
                }
            }
            Inst go;
            go.op = Op::Br;
            Edge edge{join, {}};
            edge.args.push_back(obj);
            go.edges.push_back(edge);
            go.loc = loc;
            emit(std::move(go));
        };
        build(some, "Some", true);
        build(none, "None", false);
        here_ = join;
        noteName(answer, resolveClassKey("Option$" + en));
        return answer;
    }

    // THE ENUM BUILT-INS (spec 12.5). `Color.count()` and `Color.values()` are not methods anybody
    // declared, so the resolver found nothing and emitted a call to a symbol that does not exist --
    // the link failed with `Color.count` undefined, which is at least an honest way to fail. They
    // are questions about the constant list, and the constant list is known here.
    Lowered lowerCatalogCall(const std::string& qualified, const ast::CallExpr& c) {
        const size_t dot = qualified.rfind('.');
        if (dot == std::string::npos) {
            return nothing();
        }
        const std::string owner = qualified.substr(0, dot);
        auto found = enums_.find(owner);
        if (found == enums_.end()) {
            // `Cart.Light.carries()` -- the receiver is a CONSTANT, and the value of a catalog
            // enum's constant IS its ordinal. The whole three-part chain was being flattened into
            // one symbol name, so the link asked for `Cart.Light.carries` and got nothing.
            auto ord = enumOrdinal_.find(owner);
            if (ord == enumOrdinal_.end()) {
                return nothing();
            }
            const std::string en = owner.substr(0, owner.rfind('.'));
            // A JAVA-STYLE CONSTANT'S RECEIVER IS ITS SINGLETON, not its ordinal: its methods live
            // on the twin class and take an object. `Planet.EARTH.density()` was being called with
            // the number 0 as `this` and read its fields out of address zero.
            if (auto decl = enums_.find(en);
                decl != enums_.end() && decl->second->isJavaStyle) {
                return done(callOnOrdinal(
                    en, qualified.substr(dot + 1),
                    javaEnumSingleton(*decl->second, static_cast<size_t>(ord->second), c.loc), c));
            }
            return done(callOnOrdinal(en, qualified.substr(dot + 1),
                                      constInt(ord->second, 32, c.loc), c));
        }
        const ast::EnumDecl& e = *found->second;
        const std::string member = qualified.substr(dot + 1);
        const int64_t n = static_cast<int64_t>(e.constants.size());
        TypeTable& tt = out_.module.types;

        if (member == "count" && c.args.empty()) {
            return done(constInt(n, 32, c.loc));
        }
        if (member == "values" && c.args.empty()) {
            // AN ARRAY OF THE ORDINALS -- or of the SINGLETONS, for a java-style enum, whose values
            // are objects. Handing back ordinals for one of those would give an array of small
            // integers that every use of it would then dereference.
            if (e.isJavaStyle) {
                std::vector<ValueId> singletons;
                singletons.reserve(static_cast<size_t>(n));
                for (int64_t i = 0; i < n; ++i) {
                    singletons.push_back(javaEnumSingleton(e, static_cast<size_t>(i), c.loc));
                }
                const ValueId made = makeArray(tt.ptrType(), singletons, c.loc);
                noteName(made, e.name + "[]");
                return done(made);
            }
            std::vector<ValueId> ordinals;
            ordinals.reserve(static_cast<size_t>(n));
            for (int64_t i = 0; i < n; ++i) {
                ordinals.push_back(constInt(i, 32, c.loc));
            }
            return done(makeArray(tt.intType(32), ordinals, c.loc));
        }
        // `Color.parse("Blue")` -- §12.5. A QUESTION ABOUT THE CONSTANT LIST, so it is answered
        // here where the list is: the text is compared against each name in turn, and the answer is
        // the Option the language says it is -- `Some(constant)` or `None`. As an ordinary call it
        // linked against `Color.parse`, a method nobody wrote.
        if (member == "parse" && c.args.size() == 1) {
            const ValueId text = lowerExpr(c.args[0].get());
            if (text == kNoValue) {
                return nothing();
            }
            const ValueId data = strField(text, kStrData, tt.ptrType(), c.loc);
            Inst room;
            room.op = Op::Alloca;
            room.type = tt.intType(32);
            room.text = "parse.i";
            room.loc = c.loc;
            const ValueId found = emit(std::move(room));
            slotType_[found] = tt.intType(32);
            Inst none;
            none.op = Op::Store;
            none.operands.push_back(constInt(-1, 32, c.loc));
            none.operands.push_back(found);
            none.loc = c.loc;
            emit(std::move(none));
            const BlockId settled = fn_->addBlock(fresh("parsedone"));
            for (size_t i = 0; i < e.constants.size(); ++i) {
                Inst same;
                same.op = Op::CmpEq;
                same.type = tt.boolType();
                same.operands.push_back(callExternal("strcmp", tt.intType(32),
                                                     {tt.ptrType(), tt.ptrType()},
                                                     {data, literalText(e.constants[i], c.loc)},
                                                     c.loc));
                same.operands.push_back(constInt(0, 32, c.loc));
                same.loc = c.loc;
                const BlockId hit = fn_->addBlock(fresh("parsehit"));
                const BlockId next = fn_->addBlock(fresh("parsenext"));
                Inst br;
                br.op = Op::BrCond;
                br.operands.push_back(emit(std::move(same)));
                br.edges.push_back(Edge{hit, {}});
                br.edges.push_back(Edge{next, {}});
                br.loc = c.loc;
                emit(std::move(br));
                here_ = hit;
                Inst put;
                put.op = Op::Store;
                put.operands.push_back(constInt(static_cast<int64_t>(i), 32, c.loc));
                put.operands.push_back(found);
                put.loc = c.loc;
                emit(std::move(put));
                gotoIfOpen(settled);
                here_ = next;
            }
            gotoIfOpen(settled);
            here_ = settled;
            return done(buildParsedOption(owner, loadFrom(found, c.loc), c.loc));
        }
        if (member == "name") {
            return nothing();   // handled where a receiver is available, not from the type name
        }
        if (member == "random" && c.args.empty() && n > 0 && !e.isJavaStyle) {
            const ValueId r = callExternal("rand", tt.intType(32), {}, {}, c.loc);
            Inst rem;
            rem.op = Op::RemChecked;   // `n` is the constant count, so the trap can never fire
            rem.type = tt.intType(32);
            rem.operands.push_back(r);
            rem.operands.push_back(constInt(n, 32, c.loc));
            rem.loc = c.loc;
            return done(emit(std::move(rem)));
        }
        return nothing();
    }

    // `embed("path")`: the file's bytes, in the image, laid out as every Polaron array is --
    // `[i64 length | bytes...]` -- so `.length()` and indexing need no special case.
    //
    // The path is resolved relative to the SOURCE FILE that wrote the call, like an include, so it
    // travels with the code rather than with whatever directory the compiler was started in.
    ValueId lowerEmbed(const ast::CallExpr& c) {
        const auto* lit = dynamic_cast<const ast::StringLiteralExpr*>(c.args[0].get());
        if (lit == nullptr) {
            gap("embed(...) needs a literal path known at compile time", c.loc);
            return nullPointer(c.loc);
        }
        std::filesystem::path p(lit->value);
        if (p.is_relative()) {
            std::error_code ec;
            const std::filesystem::path base =
                std::filesystem::path(std::string(c.loc.file)).parent_path();
            if (!base.empty() && std::filesystem::exists(base / p, ec)) {
                p = base / p;
            }
        }
        std::ifstream in(p, std::ios::binary);
        if (!in) {
            gap("embed(\"" + lit->value + "\"): cannot open the file", c.loc);
            return nullPointer(c.loc);
        }
        const std::string bytes((std::istreambuf_iterator<char>(in)),
                                std::istreambuf_iterator<char>());
        // ONE GLOBAL PER FILE, keyed by the resolved path: two `embed`s of the same font are one
        // copy in the image, and the same address, which is what makes comparing them meaningful.
        const std::string name = "embed." + p.filename().string();
        bool declared = false;
        for (const Global& g : out_.module.globals) {
            if (g.name == name) {
                declared = true;
                break;
            }
        }
        if (!declared) {
            Global g;
            g.name = name;
            g.type = out_.module.types.arrayType(out_.module.types.intType(8), bytes.size(),
                                                 ArrayStorage::Inline);
            g.linkage = Linkage::Private;
            g.isConst = true;
            g.zeroInit = false;
            g.hasBytes = true;
            g.initBytes.assign(bytes.begin(), bytes.end());
            out_.module.globals.push_back(std::move(g));
        }
        Inst at;
        at.op = Op::ConstFn;   // §7.1: the address of a named module-level thing
        at.type = out_.module.types.ptrType();
        at.text = name;
        at.loc = c.loc;
        const ValueId block = emit(std::move(at));
        noteName(block, "byte[]");
        return block;
    }

    ValueId lowerCall(const ast::CallExpr& c) {
        std::vector<ValueId> args;
        ValueId receiver = kNoValue;
        std::string key;

        // `checked(expr)` (spec 3.6) IS NOT A CALL -- it is the opt-in that changes which opcode
        // `+`, `-` and `*` lower to inside it. Lowered as a call it resolved to nothing, and the
        // one construct the language offers for trapping on overflow silently did nothing.
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(c.callee.get());
            id != nullptr && id->name == "checked" && c.args.size() == 1) {
            const bool saved = checkedArith_;
            checkedArith_ = true;
            const ValueId v = lowerExpr(c.args[0].get());
            checkedArith_ = saved;
            return v;
        }

        // `embed("path")` (§36) IS NOT A CALL EITHER: it reads a file AT COMPILE TIME and puts its
        // bytes in the image as a `byte[]` constant. That is how a freestanding program carries
        // data it must not load from a filesystem it does not have -- a guest binary, a font, a
        // firmware blob -- without dropping to an assembly file to write `.incbin`.
        //
        // Lowered as an ordinary call it resolved to nothing and then to the nearest thing with
        // that name: pico's kernel emitted `call i32 @.strobj.551()` -- a CALL TO A STRING LITERAL
        // -- and the machine jumped into `.data` and executed the bytes of a string. `EXC=06` at an
        // address inside a `.strobj`, three seconds after the desktop appeared.
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(c.callee.get());
            id != nullptr && id->name == "embed" && c.args.size() == 1) {
            return lowerEmbed(c);
        }
        // §34: `d.toString()` ON A `Decimal` IS NOT A METHOD CALL EITHER -- there is no class to
        // find it on. The mantissa becomes text the same way the interpolation does, and the result
        // is a `String` object rather than a bare buffer because that is what the caller then
        // concatenates. Without this the receiver fell through to the ordinary lookup, which found
        // an `Object.toString` for something that is not an object, and printed the mantissa:
        // `1800000000000000000` where the program says `1.8`.
        if (const auto* dm = dynamic_cast<const ast::MemberExpr*>(c.callee.get());
            dm != nullptr && dm->member == "toString" && c.args.empty()) {
            const ValueId subject = lowerExpr(dm->object.get());
            if (subject != kNoValue && classNameOf(declaredName(subject)) == "Decimal") {
                TypeTable& types = out_.module.types;
                const ValueId buf = decimalText(subject, c.loc);
                const ValueId len = callExternal("strlen", types.intType(64), {types.ptrType()},
                                                 {buf}, c.loc);
                const ValueId str = makeString(len, buf, c.loc);
                noteName(str, "String");
                return str;
            }
        }
        // `Dog.methods.replace("bark", fn)` (§32.8): REWRITE A CLASS'S DISPATCH SLOT. The
        // replacement takes over the slot, so every instance -- the ones already alive and the ones
        // not yet born -- picks up the new behaviour, which is the whole of what the feature is
        // for. Lowered as an ordinary call it linked against `Dog.methods.replace`, a method nobody
        // wrote and nobody could write.
        if (const auto* rp = dynamic_cast<const ast::MemberExpr*>(c.callee.get());
            rp != nullptr && rp->member == "replace" && c.args.size() == 2) {
            if (const auto* tbl = dynamic_cast<const ast::MemberExpr*>(rp->object.get());
                tbl != nullptr && tbl->member == "methods") {
                std::string owner;
                if (flatten(tbl->object.get(), &owner)) {
                    if (const size_t dot = owner.rfind('.'); dot != std::string::npos) {
                        owner = owner.substr(dot + 1);
                    }
                    if (findClass(owner) != nullptr) {
                        return patchDispatchSlot(resolveClassKey(owner), c);
                    }
                }
            }
        }
        // `vec3(1.0, 2.0, 3.0)` AND `mat4(...16 floats...)` (§34.6) look like calls and are not:
        // there is no method anywhere named `vec3`, and lowering them as one linked against a
        // symbol nobody wrote. Each is a vector built from its arguments, in the order written.
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(c.callee.get())) {
            if (const uint64_t lanes = vectorLanes(id->name);
                lanes != 0 && c.args.size() == lanes) {
                TypeTable& types = out_.module.types;
                const Type* vt = types.vectorType(types.floatType(32), lanes);
                std::vector<ValueId> made;
                for (const auto& a : c.args) {
                    const ValueId v = lowerExpr(a.get());
                    if (v == kNoValue) {
                        return kNoValue;
                    }
                    made.push_back(v);
                }
                const ValueId built = buildVector(vt, std::move(made), c.loc);
                noteName(built, id->name);
                return built;
            }
        }
        // ...and the three that ARE spelled as methods on those types. `mat4.identity()` is a
        // factory, `a.multiply(b)` and `m.transform(v)` are the two products a 4x4 matrix has. The
        // arithmetic is written out here rather than left to a runtime call because it is the
        // language's (§34.6), and because sixteen extracts and inserts over a value the optimiser
        // can see fold to constants when the matrix is one.
        if (const auto* mem = dynamic_cast<const ast::MemberExpr*>(c.callee.get())) {
            if (const auto* on = dynamic_cast<const ast::IdentifierExpr*>(mem->object.get());
                on != nullptr && on->name == "mat4" && mem->member == "identity" &&
                c.args.empty()) {
                return mat4Identity(c.loc);
            }
            // The GLSL-style vector methods (§34.6): `dot`, `length`, `normalize`, `cross`. All of
            // them are element-wise arithmetic over a value the optimiser can see, so they are
            // written out here rather than called into a runtime -- which is also what lets a
            // constant vector's length fold at compile time.
            if (isVectorExpr(mem->object.get())) {
                const ValueId on = lowerExpr(mem->object.get());
                if (on != kNoValue && isVector(fn_->value(on)->type)) {
                    const Type* vt = fn_->value(on)->type;
                    const int64_t lanes = static_cast<int64_t>(vt->extent);
                    if (mem->member == "dot" && c.args.size() == 1) {
                        const ValueId other = lowerExpr(c.args[0].get());
                        return other == kNoValue ? kNoValue
                                                 : horizontalAdd(fmulVec(on, other, c.loc), lanes,
                                                                 c.loc);
                    }
                    if ((mem->member == "length" || mem->member == "normalize") && c.args.empty()) {
                        TypeTable& types = out_.module.types;
                        const ValueId sum = horizontalAdd(fmulVec(on, on, c.loc), lanes, c.loc);
                        const ValueId len = callExternal("sqrtf", types.floatType(32),
                                                         {types.floatType(32)}, {sum}, c.loc);
                        if (mem->member == "length") {
                            return len;
                        }
                        Inst div;
                        div.op = Op::FDiv;
                        div.type = vt;
                        div.operands.push_back(on);
                        div.operands.push_back(buildVector(vt, {len}, c.loc));
                        div.loc = c.loc;
                        const ValueId unit = emit(std::move(div));
                        noteName(unit, declaredName(on));
                        return unit;
                    }
                    if (mem->member == "cross" && c.args.size() == 1 && lanes == 3) {
                        const ValueId other = lowerExpr(c.args[0].get());
                        return other == kNoValue ? kNoValue : cross3(on, other, vt, c.loc);
                    }
                }
            }
            const ValueId recv =
                mem->object != nullptr && (mem->member == "multiply" || mem->member == "transform")
                    ? lowerExpr(mem->object.get())
                    : kNoValue;
            if (recv != kNoValue && isVector(fn_->value(recv)->type) &&
                fn_->value(recv)->type->extent == 16 && c.args.size() == 1) {
                const ValueId arg = lowerExpr(c.args[0].get());
                if (arg == kNoValue) {
                    return kNoValue;
                }
                if (mem->member == "multiply") {
                    const ValueId product = mat4Multiply(recv, arg, c.loc);
                    noteName(product, "mat4");
                    return product;
                }
                const ValueId moved = mat4Transform(recv, arg, c.loc);
                noteName(moved, "vec4");
                return moved;
            }
        }
        // `itself(...)` INSIDE A LAMBDA IS THAT LAMBDA. The pronoun means "the entity being
        // declared" everywhere (§ the keyword reference), and a lambda body is the one place the
        // sema rewrite deliberately does not reach -- inside one, the entity being declared IS the
        // lambda. Called DIRECTLY rather than through the closure value, because the closure does
        // not exist yet: the body is lowered while the value that will hold it is still being
        // built. The environment is this invocation's own first parameter, so a recursive call sees
        // the same captures. Without it `itself(n - 1)` resolved to no method at all and the whole
        // program produced nothing.
        if (const auto* id = dynamic_cast<const ast::IdentifierExpr*>(c.callee.get());
            id != nullptr && id->name == "itself" && !lambdaSelfKey_.empty()) {
            std::vector<ValueId> all;
            if (auto env = locals_.find("__env"); env != locals_.end()) {
                all.push_back(loadFrom(env->second, c.loc));
            }
            for (const auto& a : c.args) {
                const ValueId v = lowerExpr(a.get());
                if (v == kNoValue) {
                    return kNoValue;
                }
                all.push_back(v);
            }
            return emitCall(resolveKey(lambdaSelfKey_), std::move(all), c.loc);
        }

        // `Channel.select().receive(ch, f).timeout(ms, g).run()` -- §20.4. A COMPILE-TIME chain,
        // not a runtime builder: the arms are known here, so it lowers to a poll loop over the
        // channels with an optional deadline. As an ordinary call chain it linked against
        // `Channel.select`, a method nobody wrote and nobody could write.
        if (const auto* run = dynamic_cast<const ast::MemberExpr*>(c.callee.get());
            run != nullptr && run->member == "run" && c.args.empty()) {
            std::vector<SelectArm> arms;
            if (collectSelectChain(run->object.get(), arms)) {
                lowerSelect(arms, c.loc);
                return kNoValue;
            }
        }
        // A QUALIFIED NAME IS NOT A RECEIVER. `System.IO.Console.println(x)` was being lowered by
        // evaluating `System.IO.Console` as a value -- and `System` is a namespace, so it came out
        // as an `undef` and every such call lost its receiver. The chain is resolved as a NAME
        // first; only if nothing in the module answers to it is the object treated as a value.
        // A METHOD ON A STATIC FIELD IS STILL A METHOD, and the name-first resolution below must
        // not claim it. `Shared.before.get()` flattens to `Shared.before.get` -- a function nobody
        // declared -- and, being qualified, that name was then DECLARED AS AN EXTERNAL, so the link
        // failed on exactly it. What the program wrote is a call on the value `Shared.before`
        // holds, and the class of that value is what says which `get`. Sent to the receiver path
        // below, which lowers the object -- a static read, which it already knows how to do -- and
        // dispatches from its type. Five samples ended here, each on a different static field:
        // `Shared.before`, `Dog.methods`, `IpcDispatch.live`, `Table.rows`, `Pace`.
        const bool onStaticField = [&] {
            const auto* mem = dynamic_cast<const ast::MemberExpr*>(c.callee.get());
            if (mem == nullptr ||
                dynamic_cast<const ast::MemberExpr*>(mem->object.get()) == nullptr ||
                !namesAQualifier(mem->object.get())) {
                return false;
            }
            std::string holder;
            return flatten(mem->object.get(), &holder) && globalExists(holder);
        }();
        std::string qualified;
        if (!onStaticField && flatten(c.callee.get(), &qualified) &&
            qualified.find('.') != std::string::npos) {
            if (const ValueId printed = lowerConsoleCall(qualified, c); printed != kNoValue) {
                return printed;
            }
            if (const Lowered raw = lowerMemoryCall(qualified, c); raw.handled) {
                return raw.value;
            }
            if (const Lowered m = lowerMathCall(qualified, c); m.handled) {
                return m.value;
            }
            if (const Lowered t = lowerTimeCall(qualified, c); t.handled) {
                return t.value;
            }
            if (const Lowered sys = lowerSystemCall(qualified, c); sys.handled) {
                return sys.value;
            }
            // `Scale.scaled(1.5)` NAMES AN OVERLOAD SET, not a function. Written out in full rather
            // than as a suffix, it still has to choose by the argument's type -- the same rule and
            // the same table.
            if (c.args.size() == 1 && literalOverloads_.count(qualified) != 0) {
                if (const Function* target =
                        literalOverloadFor(qualified, c.args.front().get())) {
                    const ValueId out = emitCall(target, {lowerExpr(c.args.front().get())}, c.loc);
                    if (auto named = returnName_.find(target->key); named != returnName_.end()) {
                        noteName(out, named->second.name, named->second.pointerDepth);
                    }
                    return out;
                }
            }
            if (const Lowered en = lowerCatalogCall(qualified, c); en.handled) {
                return en.value;
            }
            // `reflect.typeOf<T>()` (spec 31): the Type token for T. It is not a method anybody
            // declared -- it is a question about a DECLARATION -- so the resolver found nothing and
            // the link failed with `reflect.typeOf` undefined on nineteen samples.
            if (qualified == "reflect.typeOf" && !c.typeArgs.empty()) {
                return buildTypeToken(ast::mangleGeneric(c.typeArgs[0], {}), c.loc);
            }
            // `T.sizeof()` AND `Raw.sizeof(T)` (issue #7): how many bytes one of these occupies.
            // The type NAMES a type rather than evaluating to a value, so neither spelling is a
            // call the resolver can answer -- and both failed to link, on `Raw.sizeof` and on the
            // class's own name. The answer comes from the backend, which holds the data layout;
            // asking it here would be a second layout model, and two models drift.
            if (const Lowered bytes = lowerSizeOf(qualified, c); bytes.handled) {
                return bytes.value;
            }
            // ...and its six siblings, which ask the same kind of question of the same entry.
            if (const Lowered fact = lowerTypeQuery(qualified, c); fact.handled) {
                return fact.value;
            }
            const Function* byName = builtinFor(qualified);
            if (byName == nullptr) {
                byName = resolveKey(qualified);
            }
            if (byName == nullptr && namesAQualifier(c.callee.get())) {
                // AN UNRESOLVED QUALIFIED NAME IS AN EXTERNAL FUNCTION, not a chain of field reads.
                // `System.IO.Console.println` was being lowered by evaluating `System` as a value --
                // and it is a namespace, so it came out `undef` and three `gep`s were emitted to
                // walk fields of nothing. It is a function this module does not define; saying so
                // is a declaration, which is what verifier rule 15 asks for.
                byName = declareExternal(qualified, c.args.size());
            }
            if (byName != nullptr) {
                for (const auto& a : c.args) {
                    const ValueId v = lowerExpr(a.get());
                    if (v != kNoValue) {
                        args.push_back(v);
                    }
                }
                // WHAT IT RETURNS, recorded here too. This path returns early, so a call written
                // as a qualified name -- `Main.parse(n)`, which is most static calls -- produced a
                // value with no declared type at all: `try?` on it could not tell which `Ok` to
                // look for, and a method called on it resolved by bare name.
                const ValueId out = emitCall(byName, std::move(args), c.loc);
                if (auto it = returnName_.find(byName->key); it != returnName_.end()) {
                    noteName(out, it->second.name, it->second.pointerDepth);
                }
                return out;
            }
        }

        // `super(...)` AND `super.m(...)` NAME THE BASE, and neither was lowered. `super(...)` fell
        // through to a call on a key called "super", which resolves to nothing, so the arguments
        // were evaluated and thrown away: a subclass constructor ran, set its own fields, and left
        // every inherited one at zero. `super.m()` would have dispatched back to the override and
        // recursed. The base is found from the DECLARATION, which is the only thing that knows it.
        // `super` IS ITS OWN NODE (`ast::SuperExpr`), not an identifier that happens to spell it --
        // matching on the name found nothing, which is why the first attempt at this changed
        // nothing at all and the inherited fields stayed zero.
        const std::string base = superclassName();
        const bool calleeIsSuper =
            dynamic_cast<const ast::SuperExpr*>(c.callee.get()) != nullptr;
        if (calleeIsSuper && !base.empty()) {
            args.push_back(selfLoad(c.loc));
            for (const auto& a : c.args) {
                const ValueId v = lowerExpr(a.get());
                if (v != kNoValue) {
                    args.push_back(v);
                }
            }
            return emitCall(resolveKey(base + "." + base), std::move(args), c.loc);
        }
        if (auto* sm = dynamic_cast<const ast::MemberExpr*>(c.callee.get());
            sm != nullptr && !base.empty()) {
            if (dynamic_cast<const ast::SuperExpr*>(sm->object.get()) != nullptr) {
                args.push_back(selfLoad(c.loc));
                for (const auto& a : c.args) {
                    const ValueId v = lowerExpr(a.get());
                    if (v != kNoValue) {
                        args.push_back(v);
                    }
                }
                // NAMED, not dispatched: `super.m()` means the base's body even when this class
                // overrides it, which is the whole reason the word exists.
                return emitCall(resolveKey(base + "." + sm->member), std::move(args), c.loc);
            }
        }

        // CALLING A CLOSURE IS NOT CALLING A METHOD. `f(x)` where `f` is a local holding a
        // `function<...>` loads the code pointer and the environment out of it and calls
        // `code(env, x)`. Resolved by name instead, `twice(4)` bound to whatever class in the
        // program had a method called `twice` -- it found `Curve.twice`, and called it.
        if (auto* id = dynamic_cast<const ast::IdentifierExpr*>(c.callee.get());
            id != nullptr && locals_.count(id->name) != 0 && isClosureName(declaredName(locals_[id->name]))) {
            return callClosure(loadFrom(locals_[id->name], c.loc), c);
        }
        if (auto* m = dynamic_cast<const ast::MemberExpr*>(c.callee.get())) {
            receiver = lowerExpr(m->object.get());
            // §21: A METHOD ON THE VALUE FORM NEEDS AN OBJECT, and the tag says which one to build.
            if (isVariantValue(receiver)) {
                std::string sum = classNameOf(declaredName(receiver));
                // The value may be named by its CASE -- a freshly built `Ok(x)` is -- and the case
                // classes hang off the sum, so the sum is what the lookup needs.
                for (const auto& [prefix, whole] :
                     {std::pair<const char*, const char*>{"Ok", "Result"},
                      {"Err", "Result"},
                      {"Some", "Option"},
                      {"None", "Option"}}) {
                    if (sum.rfind(prefix, 0) == 0 &&
                        (sum.size() == std::strlen(prefix) || sum[std::strlen(prefix)] == '$')) {
                        sum = whole + sum.substr(std::strlen(prefix));
                        break;
                    }
                }
                if (const ValueId built = materialiseVariantCase(receiver, sum, c.loc);
                    built != kNoValue) {
                    receiver = built;
                }
            }
            // §3.7: CALLING A METHOD ON A NULLABLE RECEIVER DEREFERENCES IT -- the table is read
            // out of the object. `m?.call()` opts out, which is what the question mark buys.
            if (!m->safe) {
                guardReceiver(receiver, c.loc);
            }
            key = m->member;
            // A CLOSURE HELD IN A FIELD: `this.op(x)`. Checked here, with the receiver already in
            // hand -- lowering the object a second time to ask the question would evaluate it twice
            // and, where the object is itself a call, run it twice.
            if (const std::string owner = classNameOf(declaredName(receiver)); !owner.empty()) {
                auto ft = fieldTypeName_.find(owner + "." + key);
                if (ft != fieldTypeName_.end() && isClosureName(ft->second.name)) {
                    if (const ValueId addr = fieldAddress(receiver, key, c.loc); addr != kNoValue) {
                        return callClosure(loadFrom(addr, c.loc), c);
                    }
                }
            }
        } else if (auto* id = dynamic_cast<const ast::IdentifierExpr*>(c.callee.get())) {
            // `1 kilobytes` IS A SUFFIX, NOT A METHOD ON `this` (spec 17.10). It reads as a call to
            // a bare name from wherever it is written, and treating that as a method of the
            // enclosing class dispatched it virtually through that class's table at a slot no
            // table has -- every `itself.allocate(1 kilobytes)` read its size from `poison`.
            if (auto suffix = literalSuffix_.find(id->name);
                suffix != literalSuffix_.end() && c.args.size() == 1) {
                if (const Function* target =
                        literalOverloadFor(suffix->second, c.args.front().get())) {
                    const ValueId out = emitCall(target, {lowerExpr(c.args.front().get())}, c.loc);
                    if (auto named = returnName_.find(target->key); named != returnName_.end()) {
                        noteName(out, named->second.name, named->second.pointerDepth);
                    }
                    return out;
                }
            }
            key = id->name;
            receiver = selfLoad(c.loc);
            // ...and one held in a field of `this`, written without the `this.`.
            if (const std::string owner = classNameOf(declaredName(receiver)); !owner.empty()) {
                auto ft = fieldTypeName_.find(owner + "." + key);
                if (ft != fieldTypeName_.end() && isClosureName(ft->second.name)) {
                    if (const ValueId addr = fieldAddress(receiver, key, c.loc); addr != kNoValue) {
                        return callClosure(loadFrom(addr, c.loc), c);
                    }
                }
            }
        }
        // A BARE NAME THAT RESOLVES TO A `static` METHOD TAKES NO RECEIVER.
        //
        // `selfLoad` was pushed for every unqualified call, so a static method of the enclosing
        // class was handed `this` as its first argument and every real argument moved one place
        // along -- and the signature takes what it takes, so the last one fell off the end.
        //
        // A generator is where this showed. Its pump calls `<sym>$resume(this.st)`, a static extern
        // taking the state handle: the handle was computed, DISCARDED, and the object passed in its
        // place. The state machine resumed something that was not a state, produced nothing, and
        // `generator` printed `evens=0` for every sequence in the file.
        //
        // ASK THE SIGNATURE, NOT THE NAME. Deciding this by walking the declaration for a method of
        // that name took the first match up the chain, which is not necessarily the one this call
        // resolves to -- fifteen samples across the file, process and network parts of the standard
        // library lost their receiver that way. The function's own parameter list is the only thing
        // that knows: an instance method's first parameter IS `this`.
        if (receiver != kNoValue && !selfClassName_.empty()) {
            // AND ONLY WHEN PASSING IT WOULD NOT FIT. Two weaker tests were tried first and both
            // took a receiver away from a call that wanted one -- fifteen samples across the file,
            // process and network parts of the standard library lost theirs. Asking the declaration
            // for a method of that name takes the first match up the chain, which is not necessarily
            // the one this call resolves to; asking whether the first parameter is `this` reads an
            // EMPTY parameter list -- an imported declaration, anything not built by
            // `declareMethodOn` -- as "takes no receiver", which is a different claim.
            //
            // What is left is the one shape that cannot be anything else: the enclosing class
            // declares this name `extern`, and the callee takes exactly as many parameters as the
            // call has arguments. An `extern` is a symbol with a fixed signature -- there is no
            // override of it to resolve to and no receiver hiding in it -- so if it has no room for
            // `this`, `this` was never meant to go there. That is the generator's `<sym>$resume(long)`
            // called as `<sym>$resume(this.st)`, and nothing else in the corpus.
            //
            // The wider tests each cost a sweep. Resolving `selfClassName_ + "." + key` is not
            // necessarily the function the call ends up at -- the target is chosen from the
            // RECEIVER's class further down, which differs the moment inheritance is involved -- so
            // a rule that reads one and changes the other took the receiver from calls that wanted
            // it, in fifteen samples and then in two.
            const ast::ClassDecl* self = findClass(selfClassName_);
            const Function* target = resolveKey(selfClassName_ + "." + key);
            const size_t arity =
                target != nullptr && target->signature != nullptr ? target->signature->fields.size()
                                                                  : 0;
            if (self != nullptr && target != nullptr && declaresExtern(*self, key) &&
                arity == c.args.size()) {
                receiver = kNoValue;
            }
        }
        if (receiver != kNoValue) {
            // §30: CALLING INTO A CLASS THAT IS GONE THROWS. Asked of the receiver's STATIC type,
            // which is all a call site has; a call through a base-typed handle is caught by the
            // poisoned table instead, which is why both exist.
            guardAlive(classNameOf(declaredName(receiver)), c.loc);
            args.push_back(receiver);
        }
        // §20.2: AN EARLIER ARGUMENT OUTLIVES A SUSPENSION IN A LATER ONE. `f(x, await t)`
        // evaluates `x`, suspends, and then wants `x` again in a block the resume reaches from
        // elsewhere. Each one is put away only when something after it actually awaits, so an
        // ordinary call in an async body pays nothing.
        {
            std::vector<int64_t> parked(args.size() + c.args.size(), -1);
            size_t held = 0;
            const bool machine = asyncStateObj_ != kNoValue;
            for (size_t i = 0; i < c.args.size(); ++i) {
                bool laterAwaits = false;
                for (size_t j = i + 1; machine && j < c.args.size() && !laterAwaits; ++j) {
                    laterAwaits = containsAwait(c.args[j].get());
                }
                const size_t before = args.size();
                const ValueId v = lowerExpr(c.args[i].get());
                if (v == kNoValue) {
                    continue;
                }
                args.push_back(v);
                (void)before;
                if (laterAwaits) {
                    parked[args.size() - 1] = spillAcrossAwait(v);
                    ++held;
                }
            }
            // ...AND THE RECEIVER TOO, when any argument awaits: it was evaluated first of all.
            if (machine && !args.empty() && held > 0) {
                for (size_t i = args.size(); i > 0; --i) {
                    if (parked[i - 1] >= 0) {
                        args[i - 1] = reloadSpill(parked[i - 1], args[i - 1]);
                    }
                }
            }
        }

        // A STRING METHOD IS A BUILTIN, not a method anyone declared -- see `lowerStringCall`. And
        // when one is not covered yet, the answer is a recorded GAP rather than a fall-through: the
        // fall-through binds to whatever unrelated class declares that name, which is how a wrong
        // number reached the differential looking like a right one.
        if (const std::string cls = classNameOf(declaredName(receiver));
            !args.empty() && (cls == "String" || cls == "string")) {
            const ValueId got = lowerStringCall(key, args, c.loc);
            if (got != kNoValue) {
                return got;
            }
            gap("String." + key + "(no builtin)", c.loc);
            return kNoValue;
        }

        // AN ARRAY'S `length` IS ITS HEADER, not a method. `a.length()` on an `int[]` bound to
        // `Buffer.length` for the same reason `data.length()` on a String did -- the first key in
        // the module ending that way wins -- and it is not even a call: the count is the first eight
        // bytes of the allocation, which is what `new T[n]` writes there.
        // `a.length(n)` RESIZES (spec 25) -- the same name, a different operation, and this pass had
        // only the reader. With an argument it fell through to matching by bare name, so the resize
        // simply did not happen: `a.length(4)` left the array at two and the two slots written
        // afterwards went past the end of the allocation.
        if (receiver != kNoValue && key == "length" && args.size() == 2) {
            TypeTable& tt = out_.module.types;
            const Type* rt = fn_->value(receiver)->type;
            if (rt != nullptr && (rt->kind == TypeKind::Slice || rt->kind == TypeKind::Array)) {
                if (const auto* m = dynamic_cast<const ast::MemberExpr*>(c.callee.get())) {
                    return resizeArray(m->object.get(), receiver, args[1], rt, c.loc);
                }
            }
        }
        if (receiver != kNoValue && key == "length" && args.size() == 1) {
            TypeTable& tt = out_.module.types;
            const Type* rt = shapeOf(receiver);
            // A FIXED EXTENT IS IN THE TYPE, so the length is a constant and nothing is read. An
            // `int[16]` carries no header -- that is the difference between it and an `int[]` --
            // and loading eight bytes from its start returned the first two elements as a length.
            if (rt != nullptr && rt->kind == TypeKind::Array &&
                rt->storage == ArrayStorage::Inline) {
                return constInt(static_cast<int64_t>(rt->extent), 32, c.loc);
            }
            if (rt != nullptr && (rt->kind == TypeKind::Slice || rt->kind == TypeKind::Array)) {
                Inst g;
                g.op = Op::Gep;
                g.type = tt.ptrType();
                g.operands.push_back(receiver);
                g.imm = 0;
                // NAMED, because the guard eliminator recognises the bound by this word (§11.3).
                // `foreach` has always named it; `for (i = 0; i < a.length(); i++)` did not, and so
                // the one loop shape everybody writes kept a bounds check the compiler could prove
                // redundant. The whole corpus measured `guards-removed=0`, and this is why.
                g.text = "length";
                g.loc = c.loc;
                Inst ld;
                ld.op = Op::Load;
                ld.type = tt.intType(64);
                ld.operands.push_back(emit(std::move(g)));
                ld.loc = c.loc;
                return narrow(emit(std::move(ld)), 32, c.loc);
            }
        }

        // THE RECEIVER'S CLASS DECIDES, and only if nothing answers does the bare name get to.
        //
        // `resolveSuffix` alone takes the FIRST method in the module whose key ends in `.<name>`,
        // which is a coin toss the moment two classes share a method name -- and in a language whose
        // prelude has `length` on String, Buffer, Array, List and Map, it is a coin toss on almost
        // every call. `data.length()` on a `String` bound to `Buffer.length`, silently, and the
        // program ran and printed a wrong number. This is the same lookup the analyzer already did;
        // what was missing here was the receiver, which `declaredAs_` now carries.
        const Function* target = nullptr;
        const std::string cls = classNameOf(declaredName(receiver));
        // A PRIMITIVE HAS METHODS AND NO CLASS. `value.hash()` on an `int` names nothing this
        // module declares, so the by-suffix fallback below took the first `.hash` it could find --
        // `ByteSize.hash`, in the standard library -- and passed the integer to it as a POINTER.
        // Every hashed collection over a primitive key crashed on its first insert.
        // §20.3/20.6: `atomic<T>` and `Channel<T>` are classes with a field and no methods -- what
        // they can be asked is a set of OPERATIONS the compiler emits, not bodies anybody wrote.
        // Resolved as ordinary calls they linked against `atomic$int.increment`, which nothing
        // defines, and the whole concurrency corner of the corpus failed at the linker.
        if (const Lowered conc = concurrencyMethod(receiver, cls, key, args, c.loc); conc.handled) {
            return conc.value;
        }
        if (const Lowered built = primitiveMethod(receiver, cls, key, args, c.loc); built.handled) {
            return built.value;
        }
        if (const Lowered token = reflectionMethod(receiver, cls, key, args, c.loc);
            token.handled) {
            return token.value;
        }
        // AN ENUM-TYPED RECEIVER ANSWERS THROUGH ITS ENUM. `c.name()` on a `Color` local is the
        // same question as `Color.GREEN.name()`, and only the second was being answered -- the
        // first fell through to matching by bare name and took whichever class in the prelude
        // declares `name` first.
        if (receiver != kNoValue && enums_.count(cls) != 0) {
            return callOnOrdinal(cls, key, receiver, c);
        }
        // A CATALOG-TYPED RECEIVER dispatches on the tag it carries: which enum, then that enum's
        // body. Without this the call resolved by bare name to one implementer's method and every
        // value went to it whatever it really was.
        if (receiver != kNoValue && catalogs_.count(cls) != 0) {
            if (const Lowered through = callThroughCatalog(cls, key, receiver, c);
                through.handled) {
                return through.value;
            }
        }
        // SPAWNING A THREAD IS A THING A TARGET MAY NOT HAVE, and this is the only place the
        // question can be asked without refusing correct programs.
        //
        // The obvious place is where `Thread.start()` reaches the runtime -- a line in the PRELUDE,
        // lowered for every program whether or not it uses threads. Asked there, a wasm module that
        // never mentioned a thread was refused, and the caret pointed at a file the author never
        // opened. A check that refuses something correct is worse than no check; it is the same
        // failure the `asm` architecture check exists to avoid, and it was made here first too.
        //
        // Here the receiver's class and the CALLER are both known, so the refusal lands on the line
        // that asked for the feature, and the prelude compiling its own `Thread` costs nothing.
        if (cls == "Thread" && key == "start" && !isPreludeClass(enclosingClassKey())) {
            requireTargetFeature("threads", "`Thread.start()`", c.loc);
        }
        if (!cls.empty()) {
            target = resolveKey(cls + "." + key);
        }
        // THE RECEIVER'S OWN CHAIN, before anything is matched by bare name. `Mouse extends
        // Peripheral` and does not declare `describe`, so the key misses -- and the suffix search
        // below looks across the WHOLE MODULE for anything ending in `.describe`, which found
        // `Driver.describe`: the interface's declaration, with no body. The call linked against
        // nothing, and it took a 66722-line kernel to produce a class hierarchy deep enough to show
        // it. `implementationOf` answers precisely this question -- which class's body answers this
        // name for this class -- and it was already written for the vtables.
        if (target == nullptr && !cls.empty()) {
            if (const ast::ClassDecl* decl = findClass(cls); decl != nullptr) {
                if (const std::string impl = implementationOf(*decl, key); !impl.empty()) {
                    target = resolveKey(impl);
                }
            }
        }
        if (target == nullptr) {
            target = resolveSuffix(key);
        }

        // VIRTUAL WHEN THE OBJECT DECIDES. Two cases, and both were being emitted as a direct call:
        // the method has no body here (an interface method, an abstract one), and the method is
        // overridden by something the receiver might actually be. The first failed at LINK time --
        // `undefined symbol: Greeter.name` -- and the second linked and silently called the base.
        if (receiver != kNoValue && !cls.empty() && needsDispatch(cls, key)) {
            TypeTable& tt = out_.module.types;
            Inst load;
            load.op = Op::VtableLoad;
            load.type = tt.ptrType();
            load.operands.push_back(receiver);
            load.imm = slotFor(key);
            load.text = cls;   // rule 15: the class whose table this names
            load.loc = c.loc;
            const ValueId fnPtr = emit(std::move(load));

            Inst call;
            call.op = Op::CallIndirect;
            call.type = target != nullptr && target->signature != nullptr
                            ? target->signature->element
                            : tt.intType(32);
            call.operands.push_back(fnPtr);
            for (ValueId a : args) {
                call.operands.push_back(a);
            }
            call.loc = c.loc;
            const ValueId out = emit(std::move(call));
            noteStringResult(target, out);
            if (target != nullptr) {
                if (auto it = returnName_.find(target->key); it != returnName_.end()) {
                    noteName(out, it->second.name, it->second.pointerDepth);
                }
            }
            return out;
        }
        const ValueId out = emitCall(target, std::move(args), c.loc);
        // What the call RETURNS keeps its declared type too, so `s.substring(0, 3).length()` finds
        // `String.length` rather than starting the guessing over.
        if (target != nullptr) {
            auto it = returnName_.find(target->key);
            if (it != returnName_.end()) {
                noteName(out, it->second.name, it->second.pointerDepth);
            }
        }
        return out;
    }

    // Does the chain START with something that is a QUALIFIER rather than a value? A local, a
    // parameter or a field is a receiver; anything else -- a namespace, a class name, an enum -- is
    // part of a name. This is the one question that decides between the two lowerings.
    bool namesAQualifier(const ast::Expr* e) const {
        const ast::Expr* root = e;
        while (auto* m = dynamic_cast<const ast::MemberExpr*>(root)) {
            root = m->object.get();
        }
        auto* id = dynamic_cast<const ast::IdentifierExpr*>(root);
        if (id == nullptr) {
            return false;
        }
        if (locals_.count(id->name) != 0) {
            return false;   // a local or a parameter: a receiver
        }
        if (selfClass_ != nullptr) {
            for (const Field& f : selfClass_->fields) {
                if (f.name == id->name) {
                    return false;   // a field of `this`: also a receiver
                }
            }
        }
        return true;
    }

    // ---- the builtins ----
    //
    // `System.IO.Console.printf` IS NOT A DECLARATION ANYWHERE. It is a name the old codegen
    // special-cases into a call to the C `printf`, and there is no prelude method behind it -- which
    // is why the first program built through PIR linked against a symbol literally named
    // `System.IO.Console.printf` and found nothing.
    //
    // The mapping belongs here, in the lowering, rather than in the backend: it is a fact about the
    // LANGUAGE (this name means that runtime entry point), not about a target. A backend that had
    // to know it would have to know it once per backend.
    //
    // This table is the Console family, which is what a program that produces output needs. The rest
    // of the builtin surface the old codegen carries -- math, memory, string, reflection -- is not
    // here yet, and a call to one of those still becomes an honest gap rather than a wrong symbol.
    // WHETHER THE FIRST ARGUMENT IS A FORMAT STRING IS A RULE OF THE LANGUAGE, and it is not
    // "it is a string, so it is a format". A LONE literal is TEXT and goes through `"%s"`, because
    // `println("50% done")` contains no formatting and one `%`, and handing that to `printf` as a
    // directive with nothing behind it is undefined behaviour reached from a line that formats
    // nothing. A literal WITH arguments after it is a format. Anything else is a value, printed as
    // a string. The trusted path decides exactly this way; the rule lives here rather than in the
    // backend because it is about what the call MEANS.
    ValueId lowerConsoleCall(const std::string& name, const ast::CallExpr& c) {
        const bool newline = name == "System.IO.Console.println" || name == "Console.println" ||
                             name == "System.IO.println";
        const bool plain = name == "System.IO.Console.printf" || name == "System.IO.printf" ||
                           name == "Console.printf" || name == "System.IO.Console.print";
        if ((!newline && !plain) || c.args.empty()) {
            return kNoValue;
        }
        Function* fn = builtinFor(name);
        if (fn == nullptr) {
            return kNoValue;
        }

        // AN INTERPOLATION IS ALREADY A FORMAT STRING. Printed through the generic path it became a
        // `String` built at run time and then printed with `%s`, which is two allocations and a
        // `snprintf` for something the compiler can spell at compile time.
        if (const auto* is =
                dynamic_cast<const ast::InterpStringExpr*>(c.args.front().get())) {
            Interp built = buildInterp(*is);
            if (newline) {
                built.format += "\n";
            }
            std::vector<ValueId> pieces{literalText(built.format, c.loc)};
            for (ValueId v : built.values) {
                pieces.push_back(v);
            }
            return emitCall(fn, std::move(pieces), c.loc);
        }

        const auto* lead = dynamic_cast<const ast::StringLiteralExpr*>(c.args.front().get());
        std::vector<ValueId> args;
        size_t first = 1;   // which of the call's own arguments follows the format
        if (lead != nullptr && c.args.size() > 1) {
            args.push_back(literalText(lead->value + (newline ? "\n" : ""), c.loc));
        } else {
            args.push_back(literalText(newline ? "%s\n" : "%s", c.loc));
            if (lead != nullptr) {
                args.push_back(literalText(lead->value, c.loc));
            } else {
                const ValueId v = lowerExpr(c.args.front().get());
                if (v == kNoValue) {
                    return kNoValue;
                }
                args.push_back(v);
            }
        }
        for (size_t i = first; i < c.args.size(); ++i) {
            const ValueId v = lowerExpr(c.args[i].get());
            if (v != kNoValue) {
                args.push_back(v);
            }
        }
        return emitCall(fn, std::move(args), c.loc);
    }

    // ---- the maths family ----
    //
    // `Math.sqrt` AND ITS TWENTY SIBLINGS ARE DECLARED NOWHERE. Like `Allocator.*`, they are names
    // the trusted path recognises and turns into an operation; lowered as ordinary calls they
    // became `undefined symbol: Math.sqrt` at link time. Every one of them takes and returns a
    // `double`, which is the whole of the coercion rule.
    //
    // Where LLVM has an intrinsic it is used rather than the libm call: `sqrt` becomes one machine
    // instruction, and going through `@sqrt` would leave the optimiser unable to see that.
    Lowered lowerMathCall(const std::string& name, const ast::CallExpr& c) {
        if (name.rfind("Math.", 0) != 0) {
            return nothing();
        }
        const std::string what = name.substr(5);
        struct Row {
            const char* name;
            const char* intrinsic;   // an LLVM intrinsic, or null for a libm call
            int arity;
        };
        // THE SUFFIX IS PART OF AN INTRINSIC'S NAME. `llvm.sqrt` alone is not a symbol LLVM will
        // accept -- the overload is named by the type it operates on, and everything here is `f64`.
        static constexpr Row kMath[] = {
            {"sqrt", "llvm.sqrt.f64", 1},    {"abs", "llvm.fabs.f64", 1},
            {"floor", "llvm.floor.f64", 1},  {"ceil", "llvm.ceil.f64", 1},
            {"round", "llvm.round.f64", 1},  {"trunc", "llvm.trunc.f64", 1},
            {"sin", "llvm.sin.f64", 1},      {"cos", "llvm.cos.f64", 1},
            {"exp", "llvm.exp.f64", 1},      {"log", "llvm.log.f64", 1},
            {"log2", "llvm.log2.f64", 1},    {"log10", "llvm.log10.f64", 1},
            {"pow", "llvm.pow.f64", 2},      {"min", "llvm.minnum.f64", 2},
            {"max", "llvm.maxnum.f64", 2},   {"tan", nullptr, 1},
            {"asin", nullptr, 1},            {"acos", nullptr, 1},
            {"atan", nullptr, 1},            {"sinh", nullptr, 1},
            {"cosh", nullptr, 1},            {"tanh", nullptr, 1},
            {"cbrt", nullptr, 1},            {"atan2", nullptr, 2},
            {"hypot", nullptr, 2},
        };
        TypeTable& tt = out_.module.types;
        const Type* d = tt.floatType(64);

        // `clamp` and `lerp` are WRITTEN OUT rather than called: they are two operations each, and
        // as real instructions the optimiser folds them when the arguments are constant.
        if (what == "clamp" || what == "lerp") {
            std::vector<ValueId> a;
            for (const auto& x : c.args) {
                a.push_back(toDouble(lowerExpr(x.get()), c.loc));
            }
            if (a.size() < 3) {
                return nothing();
            }
            if (what == "clamp") {
                // THE TYPE SUFFIX IS PART OF AN INTRINSIC'S NAME. `llvm.minnum` is not a function;
                // `llvm.minnum.f64` is. Spelled without it the module was rejected outright --
                // "Intrinsic name not mangled correctly for type arguments! Should be:
                // llvm.minnum.f64" -- which took the whole of `math_extra_stdlib` down with it.
                // Every other entry in the table above is spelled with its suffix; these two were
                // written by hand beside it and were not.
                const ValueId lo = callDouble("llvm.minnum.f64", {a[0], a[2]}, c.loc);
                return done(callDouble("llvm.maxnum.f64", {a[1], lo}, c.loc));
            }
            Inst sub;
            sub.op = Op::FSub;
            sub.type = d;
            sub.operands.push_back(a[1]);
            sub.operands.push_back(a[0]);
            sub.loc = c.loc;
            Inst mul;
            mul.op = Op::FMul;
            mul.type = d;
            mul.operands.push_back(emit(std::move(sub)));
            mul.operands.push_back(a[2]);
            mul.loc = c.loc;
            Inst add;
            add.op = Op::FAdd;
            add.type = d;
            add.operands.push_back(a[0]);
            add.operands.push_back(emit(std::move(mul)));
            add.loc = c.loc;
            return done(emit(std::move(add)));
        }

        for (const Row& r : kMath) {
            if (what != r.name) {
                continue;
            }
            std::vector<ValueId> a;
            for (const auto& x : c.args) {
                a.push_back(toDouble(lowerExpr(x.get()), c.loc));
            }
            if (static_cast<int>(a.size()) != r.arity) {
                return nothing();
            }
            return done(callDouble(r.intrinsic != nullptr ? r.intrinsic : r.name, a, c.loc));
        }
        // A user class NAMED `Math` is not this family; anything unrecognised falls through to
        // ordinary resolution, which is why nothing above evaluates an argument until it matches.
        return nothing();
    }

    ValueId toDouble(ValueId v, SourceLocation loc) {
        if (v == kNoValue) {
            return v;
        }
        const Type* from = fn_->value(v)->type;
        return lowerConversion(v, from, out_.module.types.floatType(64), loc);
    }

    ValueId callDouble(const std::string& symbol, const std::vector<ValueId>& args,
                       SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* d = tt.floatType(64);
        return callExternal(symbol, d, std::vector<const Type*>(args.size(), d), args, loc);
    }

    // `Time.*` and `Bits.*`: two more families the trusted path recognises by name, both thin
    // wrappers over a runtime entry point or a reinterpretation of the same bits.
    Lowered lowerTimeCall(const std::string& name, const ast::CallExpr& c) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        if (name == "Bits.doubleToLong" && c.args.size() == 1) {
            // NO CONVERSION AND NO ROUNDING: the same sixty-four bits read as an integer, which is
            // what makes this different from `cast<long>(x)` and why it needs its own name.
            const ValueId v = lowerExpr(c.args[0].get());
            Inst in;
            in.op = Op::Bitcast;
            in.type = i64;
            in.operands.push_back(v);
            in.loc = c.loc;
            return done(emit(std::move(in)));
        }
        if (name == "Bits.longToDouble" && c.args.size() == 1) {
            const ValueId v = lowerExpr(c.args[0].get());
            Inst in;
            in.op = Op::Bitcast;
            in.type = tt.floatType(64);
            in.operands.push_back(widenToLong(v, c.loc));
            in.loc = c.loc;
            return done(emit(std::move(in)));
        }
        if (name.rfind("Time.", 0) != 0) {
            return nothing();
        }
        const std::string what = name.substr(5);
        if (what == "sleep" && c.args.size() == 1) {
            callExternal("__polaron_sleep", tt.voidType(), {i64},
                         {widenToLong(lowerExpr(c.args[0].get()), c.loc)}, c.loc);
            return done();
        }
        if (what == "millis" || what == "nanos" || what == "unixMillis") {
            const char* sym = what == "millis"  ? "__polaron_now_ms"
                              : what == "nanos" ? "__polaron_now_ns"
                                                : "__polaron_unix_ms";
            return done(callExternal(sym, i64, {}, {}, c.loc));
        }
        return nothing();
    }

    // ---- the operating system family ----
    //
    // SIXTY-ODD NAMES THE COMPILER ANSWERS AND NOTHING DECLARES. `File.readAll`, `Net.connect`,
    // `Subproc.spawn`, `Env.get`, `System.Concurrency.__threadStart` -- each is a name the trusted
    // path recognises and turns into a call to a runtime symbol with a C signature. Lowered as
    // ordinary Polaron calls they linked against `File.readAll`, which nothing defines, and took
    // sixty-four samples down at the linker.
    //
    // ONE TABLE, NOT SIXTY BLOCKS. Written out by hand these are sixty near-identical paragraphs
    // whose only differences are a symbol, an argument shape and a result shape -- and sixty
    // paragraphs is how the fifty-ninth ends up calling the fifty-eighth's symbol. What varies is
    // exactly three facts, so three facts is what the table holds; the driver below is the rest.
    //
    // The argument letters say how a Polaron argument crosses into C:
    //   i  as int32       l  as int64       p  through, untouched (a closure, an address)
    //   s  a String, as its DATA pointer only (a C string; the runtime reads to the NUL)
    //   S  a String, as data AND length -- TWO C arguments, which is how a payload that may hold a
    //      NUL crosses at all, and why `spawnArgv` can pass an argument containing a space.
    //
    // The result letters say how the answer comes back:
    //   v  nothing        i  an int32       l  an int64      I  an int64 truncated to int
    //   s  (…, long* outLen) -> char*: the callee is handed a slot for the length and answers with
    //      a buffer; both become an owned String here.
    //   t  a NUL-terminated char* the caller now OWNS, whose length is `strlen`.
    //   b  the same, BORROWED: the bytes stay the runtime's and are copied on the way in.
    //
    // THE DIFFERENCE BETWEEN `t` AND `b` IS NOT COSMETIC, and writing both as `t` is what made it
    // look so. A String owns its buffer (§21) -- that is what lets a temporary be released -- and
    // `Net.udpPeerHost` answers with `g_udp_peer_host`, a static of the runtime's. Wrapped as
    // owned, releasing that String called `free` on a global: `udp_socket` exited 0xc0000374.
    // `Env.executablePath` beside it really does `__polaron_malloc` its answer. One letter each,
    // so the table states which, rather than the lowering guessing from a name.
    struct SysRow {
        const char* name;      // the qualified Polaron spelling
        const char* symbol;    // the runtime entry point
        const char* args;      // one letter per Polaron argument
        char result;
        int trailing = -1;     // a constant int64 appended after the arguments
        int trailing2 = -1;    // ...and a second one
    };

    Lowered lowerSystemCall(const std::string& name, const ast::CallExpr& c) {
        // clang-format off
        static constexpr SysRow kSys[] = {
            // ---- threads and locks. A thread starts from a `function<void>` CLOSURE, which is one
            // pointer holding both the code and what it captured; the runtime calls it back.
            {"System.Concurrency.__threadStart", "__polaron_thread_spawn",  "p",  'l'},
            {"System.Concurrency.__threadJoin",  "__polaron_thread_join",   "l",  'v'},
            {"System.Concurrency.__threadYield", "__polaron_thread_yield",  "",   'v'},
            {"System.Concurrency.__lockCreate",  "__polaron_lock_create",   "",   'l'},
            {"System.Concurrency.__lockAcquire", "__polaron_lock_acquire",  "l",  'v'},
            {"System.Concurrency.__lockRelease", "__polaron_lock_release",  "l",  'v'},
            {"System.Concurrency.__chanNew",     "__polaron_chan_new",      "l",  'l'},
            {"System.OS.__machineThreads",       "__polaron_machine_threads", "", 'i'},
            // ---- the environment.
            {"Env.get",            "__polaron_env_get",         "s",  's'},
            {"Env.set",            "__polaron_env_set",         "ss", 'i'},
            {"Env.executablePath", "__polaron_executable_path", "",   't'},
            // ---- files. `writeAll` and `appendAll` are ONE runtime call apart: the trailing flag.
            {"File.readAll",   "__polaron_file_read_all",  "s",  's'},
            {"File.writeAll",  "__polaron_file_write_all", "sS", 'i', 0},
            {"File.appendAll", "__polaron_file_write_all", "sS", 'i', 1},
            {"File.exists",    "__polaron_file_exists",    "s",  'i'},
            {"File.remove",    "__polaron_file_delete",    "s",  'i'},
            {"File.list",      "__polaron_dir_list",       "s",  's'},
            {"File.open",      "__polaron_fopen",          "ss", 'l'},
            {"File.readInto",  "__polaron_fread",          "lpl", 'l'},
            {"File.writeFrom", "__polaron_fwrite",         "lpl", 'l'},
            {"File.seek",      "__polaron_fseek",          "lli", 'i'},
            {"File.lock",      "__polaron_file_lock",      "lii", 'i'},
            {"File.unlock",    "__polaron_file_unlock",    "l",  'i'},
            {"File.tell",      "__polaron_ftell",          "l",  'l'},
            {"File.flush",     "__polaron_fflush",         "l",  'i'},
            {"File.close",     "__polaron_fclose",         "l",  'i'},
            {"File.atEnd",     "__polaron_feof",           "l",  'i'},
            {"File.size",      "__polaron_file_size",      "s",  'l'},
            {"File.mtime",     "__polaron_file_mtime",     "s",  'l'},
            {"File.mkdir",     "__polaron_mkdir",          "s",  'i'},
            {"File.rmdir",     "__polaron_rmdir",          "s",  'i'},
            {"File.isDir",     "__polaron_is_dir",         "s",  'i'},
            {"File.rename",    "__polaron_rename",         "ss", 'i'},
            // ---- TCP and UDP. `recv` is not here: it allocates the buffer the runtime fills, which
            // is a shape the table cannot say, so it is written out below.
            {"Net.connect",     "__polaron_tcp_connect",   "si",   'l'},
            {"Net.send",        "__polaron_tcp_send",      "lS",   'l'},
            {"Net.close",       "__polaron_tcp_close",     "l",    'v'},
            {"Net.listen",      "__polaron_tcp_listen",    "i",    'l'},
            {"Net.accept",      "__polaron_tcp_accept",    "l",    'l'},
            {"Net.udpOpen",     "__polaron_udp_open",      "i",    'l'},
            {"Net.udpSend",     "__polaron_udp_sendto",    "lsiS", 'l'},
            {"Net.udpPeerHost", "__polaron_udp_peer_host", "",     'b'},
            {"Net.udpPeerPort", "__polaron_udp_peer_port", "",     'i'},
            {"Net.udpClose",    "__polaron_udp_close",     "l",    'v'},
            // ---- a named pipe / unix socket, the same six operations on a local name.
            {"Ipc.listen",  "__polaron_ipc_listen",  "s",  'l'},
            {"Ipc.connect", "__polaron_ipc_connect", "s",  'l'},
            {"Ipc.accept",  "__polaron_ipc_accept",  "l",  'l'},
            {"Ipc.send",    "__polaron_ipc_send",    "lS", 'l'},
            {"Ipc.recv",    "__polaron_ipc_recv",    "l",  's'},
            {"Ipc.close",   "__polaron_ipc_close",   "l",  'v'},
            // ---- a child process kept alive. The three spawns differ only in two flags: whether
            // the child's stderr shares its stdout pipe, and whether it gets a console window.
            {"Subproc.spawn",         "__polaron_subproc_spawn_ex", "s", 'l', 0, 0},
            {"Subproc.spawnCombined", "__polaron_subproc_spawn_ex", "s", 'l', 1, 0},
            {"Subproc.spawnVisible",  "__polaron_subproc_spawn_ex", "s", 'l', 0, 1},
            {"Subproc.spawnArgv",     "__polaron_subproc_spawn_argv", "SlsSllll", 'l'},
            {"Subproc.wait",       "__polaron_subproc_wait",         "l",  'I'},
            {"Subproc.waitFor",    "__polaron_subproc_wait_for",     "ll", 'I'},
            {"Subproc.writeStr",   "__polaron_subproc_write",        "lS", 'I'},
            {"Subproc.readChunk",  "__polaron_subproc_read",         "l",  's'},
            {"Subproc.isAlive",    "__polaron_subproc_alive",        "l",  'i'},
            {"Subproc.canRead",    "__polaron_subproc_can_read",     "l",  'i'},
            {"Subproc.closeStdin", "__polaron_subproc_close_stdin",  "l",  'v'},
            {"Subproc.kill",       "__polaron_subproc_close",        "l",  'v'},
            // ---- a pseudo-console, for a terminal that hosts a real shell.
            {"Conpty.spawn",     "__polaron_conpty_spawn",    "sii", 'l'},
            {"Conpty.writeStr",  "__polaron_conpty_write",    "lS",  'I'},
            {"Conpty.readChunk", "__polaron_conpty_read",     "l",   's'},
            {"Conpty.isAlive",   "__polaron_conpty_alive",    "l",   'i'},
            {"Conpty.canRead",   "__polaron_conpty_can_read", "l",   'i'},
            {"Conpty.resize",    "__polaron_conpty_resize",   "lii", 'v'},
            {"Conpty.close",     "__polaron_conpty_close",    "l",   'v'},
            // ---- one line from standard input, which is the language's only input primitive.
            {"System.IO.Console.read", "polaron_read_line", "", 's'},
            {"Console.read",           "polaron_read_line", "", 's'},
        };
        // clang-format on
        for (const SysRow& r : kSys) {
            if (name == r.name) {
                return done(emitSysRow(r, c));
            }
        }
        // ...and the rest of what the operating system already knows, from the table the analyzer
        // reads too. Keeping a second copy here is how one of them ends up calling its neighbour's
        // symbol, which is the whole reason `sys_intrinsics.h` sits in semantic and not in codegen.
        if (const sysint::SysIntrinsic* si = sysint::findSysIntrinsic(name); si != nullptr) {
            SysRow r{si->name, si->symbol, si->takesPath ? "s" : "",
                     si->result == 's' ? 's' : (si->result == 'l' ? 'l' : 'i')};
            return done(emitSysRow(r, c));
        }
        if (const sysint::SysIntrinsic2* si = sysint::findSysIntrinsic2(name); si != nullptr) {
            SysRow r{si->name, si->symbol, si->secondIsInt ? "si" : "ss",
                     si->result == 's' ? 's' : 'i', si->trailing};
            return done(emitSysRow(r, c));
        }
        // A RECEIVE ALLOCATES ITS OWN BUFFER, which no row above can say: the caller decides how
        // much it is willing to take, the runtime fills up to that and answers how much arrived,
        // and a NEGATIVE answer means the socket failed rather than that zero bytes came. Reading
        // that -1 as a length is a String of eighteen quintillion bytes.
        if (name == "Net.recv" || name == "Net.udpRecv") {
            return done(lowerSocketRecv(name == "Net.recv" ? "__polaron_tcp_recv"
                                                           : "__polaron_udp_recvfrom",
                                        c));
        }
        // THE ERROR STREAM IS NOT `printf` UNDER ANOTHER NAME. It takes a String and writes its
        // bytes -- no format parser, because the language's own interpolation IS the formatting and
        // a `%` inside a diagnostic message is a `%`, not a conversion waiting for an argument that
        // was never passed. This was filed as a builtin named `polaron_write_errln`, a symbol with
        // no leading underscores that the runtime has never defined under any spelling, so every
        // program that reported an error failed to link.
        // `Process.run(cmd)` ANSWERS WITH TWO THINGS AT ONCE -- what the command printed and what it
        // returned -- and the language has no tuple, so the pair is a `ProcessResult` built here.
        // The runtime call is the easy half; the object around it is why this is not a table row.
        if (name == "Process.run" && c.args.size() == 1) {
            TypeTable& tt = out_.module.types;
            const Type* i32 = tt.intType(32);
            const Type* i64 = tt.intType(64);
            const Type* ptr = tt.ptrType();
            const ValueId cmd = lowerExpr(c.args[0].get());
            if (cmd == kNoValue) {
                return done();
            }
            Inst lenRoom;
            lenRoom.op = Op::Alloca;
            lenRoom.type = i64;
            lenRoom.text = "pr.len";
            lenRoom.loc = c.loc;
            const ValueId lenSlot = emit(std::move(lenRoom));
            slotType_[lenSlot] = i64;
            Inst codeRoom;
            codeRoom.op = Op::Alloca;
            codeRoom.type = i32;
            codeRoom.text = "pr.exit";
            codeRoom.loc = c.loc;
            const ValueId codeSlot = emit(std::move(codeRoom));
            slotType_[codeSlot] = i32;
            const ValueId buf =
                callExternal("__polaron_process_run", ptr, {ptr, ptr, ptr},
                             {strField(cmd, kStrData, ptr, c.loc), lenSlot, codeSlot}, c.loc);
            const ValueId text = makeString(loadFrom(lenSlot, c.loc), buf, c.loc);
            const std::string cls = resolveClassKey("ProcessResult");
            const Type* t = baseTypeOf(cls);
            Inst obj;
            obj.op = Op::Alloca;
            obj.extra.push_back("heap");
            obj.type = t != nullptr && t->kind == TypeKind::Struct ? t : ptr;
            obj.text = cls;
            obj.loc = c.loc;
            const ValueId made = emit(std::move(obj));
            if (t != nullptr && t->kind == TypeKind::Struct) {
                pointee_[made] = t;
            }
            noteName(made, cls);
            noteStorage(made, Storage::Heap);
            if (const Function* ctor = resolveKey(cls + "." + cls)) {
                emitCall(ctor, {made, text, loadFrom(codeSlot, c.loc)}, c.loc);
            }
            return done(made);
        }
        if (name == "System.IO.Console.error" || name == "System.IO.Console.errorln") {
            TypeTable& tt = out_.module.types;
            const Type* i64 = tt.intType(64);
            const Type* ptr = tt.ptrType();
            if (!c.args.empty()) {
                ValueId text = kNoValue;
                if (const auto* is =
                        dynamic_cast<const ast::InterpStringExpr*>(c.args.front().get())) {
                    text = lowerInterpAsString(*is, c.loc);
                } else {
                    text = lowerExpr(c.args.front().get());
                }
                if (text == kNoValue) {
                    return done();
                }
                callExternal("__polaron_write_err", i64, {ptr, i64},
                             {strField(text, kStrData, ptr, c.loc),
                              strField(text, kStrLength, i64, c.loc)},
                             c.loc);
            }
            if (name == "System.IO.Console.errorln") {
                callExternal("__polaron_write_err", i64, {ptr, i64},
                             {literalText("\n", c.loc), constInt(1, 64, c.loc)}, c.loc);
            }
            return done();
        }
        return nothing();
    }

    // One row, driven. Every argument is evaluated exactly once and in source order -- a String
    // crossing as (data, length) reads both out of the same evaluation, which is why the letters
    // are consumed here rather than by evaluating the argument list twice.
    ValueId emitSysRow(const SysRow& r, const ast::CallExpr& c) {
        TypeTable& tt = out_.module.types;
        const Type* i32 = tt.intType(32);
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        std::vector<const Type*> ptypes;
        std::vector<ValueId> args;
        const std::string shape = r.args;
        for (size_t i = 0; i < shape.size(); ++i) {
            if (i >= c.args.size()) {
                return kNoValue;   // an arity the declaration and the table disagree on
            }
            const ValueId v = lowerExpr(c.args[i].get());
            if (v == kNoValue) {
                return kNoValue;
            }
            switch (shape[i]) {
                case 'i':
                    ptypes.push_back(i32);
                    args.push_back(fitInt(v, 32, c.loc));
                    break;
                case 'l':
                    ptypes.push_back(i64);
                    args.push_back(fitInt(v, 64, c.loc));
                    break;
                case 'p':
                    ptypes.push_back(ptr);
                    args.push_back(v);
                    break;
                case 's':
                    ptypes.push_back(ptr);
                    args.push_back(strField(v, kStrData, ptr, c.loc));
                    break;
                case 'S':
                    ptypes.push_back(ptr);
                    args.push_back(strField(v, kStrData, ptr, c.loc));
                    ptypes.push_back(i64);
                    args.push_back(strField(v, kStrLength, i64, c.loc));
                    break;
                default:
                    return kNoValue;
            }
        }
        for (int extra : {r.trailing, r.trailing2}) {
            if (extra >= 0) {
                ptypes.push_back(i64);
                args.push_back(constInt(extra, 64, c.loc));
            }
        }
        // A STRING RESULT NEEDS A SLOT TO PUT THE LENGTH IN, and the slot is a trailing argument the
        // Polaron declaration never mentions. It has to be allocated before the call, which is why
        // this cannot be folded into the loop above.
        ValueId lenSlot = kNoValue;
        if (r.result == 's') {
            Inst room;
            room.op = Op::Alloca;
            room.type = i64;
            room.text = "sys.len";
            room.loc = c.loc;
            lenSlot = emit(std::move(room));
            slotType_[lenSlot] = i64;
            ptypes.push_back(ptr);
            args.push_back(lenSlot);
        }
        const Type* ret = r.result == 'v'   ? tt.voidType()
                          : r.result == 'i' ? i32
                          : (r.result == 's' || r.result == 't' || r.result == 'b') ? ptr
                                                                 : i64;
        const ValueId out = callExternal(r.symbol, ret, ptypes, args, c.loc);
        if (r.result == 'v') {
            return kNoValue;
        }
        if (r.result == 's') {
            return makeString(loadFrom(lenSlot, c.loc), out, c.loc);
        }
        if (r.result == 't' || r.result == 'b') {
            // NO LENGTH CAME BACK, so it is measured. `strlen` is the contract a bare `char*`
            // carries and the only thing that can be asked of one.
            const ValueId n = callExternal("strlen", i64, {ptr}, {out}, c.loc);
            if (r.result == 't') {
                return makeString(n, out, c.loc);
            }
            // BORROWED: the String takes a copy, so it owns what it points at like every other
            // String does. One allocation on an I/O call, against a `free` of the runtime's own
            // static -- which is not a trade, it is a correctness rule with a price attached.
            Inst plus;
            plus.op = Op::AddWrap;
            plus.type = i64;
            plus.operands.push_back(n);
            plus.operands.push_back(constInt(1, 64, c.loc));   // room for the terminator
            plus.loc = c.loc;
            const ValueId room = emit(std::move(plus));
            const ValueId mine = callExternal("__polaron_malloc", ptr, {i64}, {room}, c.loc);
            callExternal("memcpy", ptr, {ptr, ptr, i64}, {mine, out, room}, c.loc);
            return makeString(n, mine, c.loc);
        }
        if (r.result == 'I') {
            return narrow(out, 32, c.loc);
        }
        return out;
    }

    // `recv(sock, max)`: room for `max` bytes plus the NUL, filled by the runtime, clamped at zero
    // so a failed socket reads as an empty answer rather than as a length of -1.
    ValueId lowerSocketRecv(const char* symbol, const ast::CallExpr& c) {
        if (c.args.size() < 2) {
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        const ValueId sock = fitInt(lowerExpr(c.args[0].get()), 64, c.loc);
        const ValueId cap = fitInt(lowerExpr(c.args[1].get()), 64, c.loc);
        Inst room;
        room.op = Op::AddWrap;
        room.type = i64;
        room.operands.push_back(cap);
        room.operands.push_back(constInt(1, 64, c.loc));
        room.loc = c.loc;
        const ValueId buf =
            callExternal("__polaron_malloc", ptr, {i64}, {emit(std::move(room))}, c.loc);
        const ValueId n = callExternal(symbol, i64, {i64, ptr, i64}, {sock, buf, cap}, c.loc);
        Inst neg;
        neg.op = Op::CmpLtS;
        neg.type = tt.boolType();
        neg.operands.push_back(n);
        neg.operands.push_back(constInt(0, 64, c.loc));
        neg.loc = c.loc;
        Inst pick;
        pick.op = Op::Select;
        pick.type = i64;
        pick.operands.push_back(emit(std::move(neg)));
        pick.operands.push_back(constInt(0, 64, c.loc));
        pick.operands.push_back(n);
        pick.loc = c.loc;
        const ValueId len = emit(std::move(pick));
        // THE NUL GOES AT THE END OF WHAT ARRIVED, not at the end of the buffer: anything that
        // reads the answer as a C string has to stop where the data stops.
        Inst at;
        at.op = Op::Gep;
        at.type = ptr;
        at.operands.push_back(buf);
        at.operands.push_back(len);
        at.loc = c.loc;
        Inst st;
        st.op = Op::Store;
        st.operands.push_back(constInt(0, 8, c.loc));
        st.operands.push_back(emit(std::move(at)));
        st.loc = c.loc;
        emit(std::move(st));
        return makeString(len, buf, c.loc);
    }

    // Widen or narrow, whichever the target asks for. The C signatures below are exact and a
    // Polaron `int` handed to a `long long` parameter is half an argument.
    ValueId fitInt(ValueId v, unsigned bits, SourceLocation loc) {
        if (v == kNoValue) {
            return v;
        }
        return lowerConversion(v, fn_->value(v)->type, out_.module.types.intType(bits), loc);
    }

    // ---- the memory family ----
    //
    // `Allocator.alloc` and the `Raw.*` primitives are DECLARED in the prelude and defined nowhere:
    // the trusted path recognises the name and emits the operation. Lowered as ordinary calls they
    // became eight `undefined symbol: Allocator.alloc` at link time -- the single largest reason a
    // sample built through PIR did not link at all.
    //
    // An address here is a 64-bit integer, not a pointer: that is the language's `address`, and it
    // is why every one of these starts or ends with a conversion.
    Lowered lowerMemoryCall(const std::string& name, const ast::CallExpr& c) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        const std::string what =
            name.rfind("System.Memory.", 0) == 0 ? name.substr(14) : name;

        auto arg = [&](size_t i) {
            return i < c.args.size() ? lowerExpr(c.args[i].get()) : kNoValue;
        };
        auto asPtr = [&](ValueId address) {
            Inst in;
            in.op = Op::AddrToPtr;
            in.type = ptr;
            in.operands.push_back(address);
            in.loc = c.loc;
            return emit(std::move(in));
        };
        auto asAddress = [&](ValueId p) {
            Inst in;
            in.op = Op::PtrToAddr;
            in.type = i64;
            in.operands.push_back(p);
            in.loc = c.loc;
            return emit(std::move(in));
        };

        if (what == "Allocator.alloc" && !c.args.empty()) {
            const ValueId n = widenToLong(arg(0), c.loc);
            return done(asAddress(callExternal("__polaron_malloc", ptr, {i64}, {n}, c.loc)));
        }
        if (what == "Allocator.free" && !c.args.empty()) {
            callExternal("__polaron_free", tt.voidType(), {ptr}, {asPtr(arg(0))}, c.loc);
            return done();
        }
        if (what == "Allocator.copy" && c.args.size() >= 3) {
            const ValueId dst = asPtr(arg(0));
            const ValueId src = asPtr(arg(1));
            callExternal("memcpy", ptr, {ptr, ptr, i64}, {dst, src, widenToLong(arg(2), c.loc)},
                         c.loc);
            return done();
        }
        if (what == "Raw.write" && c.args.size() >= 2) {
            const ValueId at = asPtr(arg(0));
            const ValueId v = arg(1);
            Inst st;
            st.op = Op::Store;
            st.operands.push_back(v);
            st.operands.push_back(at);
            st.loc = c.loc;
            emit(std::move(st));
            return done();
        }
        if (what == "Raw.read" && !c.args.empty()) {
            Inst ld;
            ld.op = Op::Load;
            ld.type = c.typeArgs.empty() ? tt.intType(32) : baseTypeOf(c.typeArgs[0]);
            ld.operands.push_back(asPtr(arg(0)));
            ld.loc = c.loc;
            return done(emit(std::move(ld)));
        }
        if (what == "Raw.writeString" && c.args.size() >= 2) {
            const ValueId dst = asPtr(arg(0));
            const ValueId src = arg(1);
            callExternal("memcpy", ptr, {ptr, ptr, i64},
                         {dst, strField(src, kStrData, ptr, c.loc),
                          strField(src, kStrLength, i64, c.loc)},
                         c.loc);
            return done();
        }
        if (what == "Raw.readString" && c.args.size() >= 2) {
            // The new String OWNS its bytes -- it outlives the buffer it was read from, which is
            // the whole reason this is a copy and not a view.
            const ValueId src = asPtr(arg(0));
            const ValueId len = widenToLong(arg(1), c.loc);
            const ValueId room = addLong(len, 1, c.loc);   // room for the terminator
            const ValueId buf = callExternal("__polaron_malloc", ptr, {i64}, {room}, c.loc);
            callExternal("memcpy", ptr, {ptr, ptr, i64}, {buf, src, len}, c.loc);
            Inst nul;
            nul.op = Op::Store;
            nul.operands.push_back(constInt(0, 8, c.loc));
            nul.operands.push_back(rawOffset(buf, len, c.loc));
            nul.loc = c.loc;
            emit(std::move(nul));
            const ValueId made = makeString(len, buf, c.loc);
            noteName(made, "String");
            return done(made);
        }
        return nothing();
    }

    // `a.length(n)`: `realloc`, write the new length into the header, zero whatever was grown, and
    // store the block back -- because realloc MAY MOVE IT, and a variable still holding the old
    // address is a use-after-free the next time it is read.
    ValueId resizeArray(const ast::Expr* target, ValueId array, ValueId count, const Type* arrayType,
                        SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        const ValueId slot = addressOf(target);
        if (slot == kNoValue) {
            gap("array resize(target is not assignable)", loc);
            return kNoValue;
        }
        const Type* elem = elementOf(arrayType);
        const int64_t stride =
            elem != nullptr && elem->facts.size > 0 ? static_cast<int64_t>(elem->facts.size) : 4;

        Inst oldLen;
        oldLen.op = Op::Load;
        oldLen.type = i64;
        oldLen.operands.push_back(array);
        oldLen.loc = loc;
        const ValueId before = emit(std::move(oldLen));   // the header IS at offset zero

        const ValueId wanted = widenToLong(count, loc);
        const ValueId bytes = mulLong(wanted, stride, loc);
        const ValueId total = addLong(bytes, 8, loc);
        // `__polaron_realloc`, NOT the C one. The block came from `__polaron_malloc`, which is the
        // runtime's pooled allocator with its own liveness registry; handing one of its pointers to
        // the libc `realloc` is undefined and here it simply corrupted the heap, so a program that
        // grew an array printed nothing at all. One heap, one allocator, both ends of every pair.
        const ValueId block =
            callExternal("__polaron_realloc", ptr, {ptr, i64}, {array, total}, loc);

        Inst put;
        put.op = Op::Store;
        put.operands.push_back(wanted);
        put.operands.push_back(block);
        put.loc = loc;
        emit(std::move(put));

        // ZERO ONLY WHAT GREW. Shrinking must clear nothing, and the count has to come out as zero
        // rather than negative -- a `memset` of a negative length is a wild write of about as much
        // memory as the machine has.
        const BlockId grow = fn_->addBlock(fresh("grew"));
        const BlockId done = fn_->addBlock(fresh("resized"));
        Inst cmp;
        cmp.op = Op::CmpGtS;
        cmp.type = tt.boolType();
        cmp.operands.push_back(wanted);
        cmp.operands.push_back(before);
        cmp.loc = loc;
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(emit(std::move(cmp)));
        br.edges.push_back(Edge{grow, {}});
        br.edges.push_back(Edge{done, {}});
        br.loc = loc;
        emit(std::move(br));

        here_ = grow;
        Inst span;
        span.op = Op::SubWrap;
        span.type = i64;
        span.operands.push_back(wanted);
        span.operands.push_back(before);
        span.loc = loc;
        const ValueId added = mulLong(emit(std::move(span)), stride, loc);
        const ValueId from = rawOffset(rawOffset(block, constInt(8, 64, loc), loc),
                                       mulLong(before, stride, loc), loc);
        callExternal("memset", ptr, {ptr, tt.intType(32), i64},
                     {from, constInt(0, 32, loc), added}, loc);
        Inst go;
        go.op = Op::Br;
        go.edges.push_back(Edge{done, {}});
        go.loc = loc;
        emit(std::move(go));

        here_ = done;
        Inst back;
        back.op = Op::Store;
        back.operands.push_back(block);
        back.operands.push_back(slot);
        back.loc = loc;
        emit(std::move(back));
        return kNoValue;   // a resize produces nothing
    }

    // ---- string interpolation ----
    //
    // `$"{a} {b}"` IS A FORMAT STRING, not a chain of concatenations. This pass lowered it by
    // concatenating the pieces -- and the pieces are not all Strings, so `concat` read a `length`
    // out of the first eight bytes of an `int` and asked the allocator for that many bytes. Three
    // samples died with "out of memory" from printing two small numbers.
    //
    // The specifier comes from the value's TYPE, which is the same decision the trusted path makes,
    // and it has to be made the same way or the two print different text for the same program: a
    // `boolean` interpolates as `true`/`false` (the only spelling the language has for it), a
    // `char` as a character, a `String` as its bytes rather than its object pointer.
    struct Interp {
        std::string format;
        std::vector<ValueId> values;
    };

    // §34: a `Decimal` as text, in a fresh buffer, ready for `%s`.
    //
    // The 128-bit work is done HERE -- sign, whole part, eighteen-digit fraction -- and the runtime
    // helper only assembles the digits and trims the trailing zeros of the fraction, so that
    // `1.8` does not print as `1.800000000000000000`. It has to be that way round because MSVC has
    // no 128-bit integer to write the helper in; the compiler does have one, in the IR.
    ValueId decimalText(ValueId v, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* dec = tt.intType(kDecimalBits);
        const Type* i64 = tt.intType(64);
        const Type* i32 = tt.intType(32);
        auto arith = [&](Op op, const Type* type, ValueId x, ValueId y) {
            Inst in;
            in.op = op;
            in.type = type;
            in.operands.push_back(x);
            in.operands.push_back(y);
            in.loc = loc;
            return emit(std::move(in));
        };
        Inst zeroWide;
        zeroWide.op = Op::ConstInt;
        zeroWide.type = dec;
        zeroWide.imm = 0;
        zeroWide.loc = loc;
        const ValueId zero = emit(std::move(zeroWide));
        const ValueId negative = cmp(Op::CmpLtS, v, zero, loc);
        Inst pick;
        pick.op = Op::Select;
        pick.type = dec;
        pick.operands.push_back(negative);
        pick.operands.push_back(arith(Op::SubWrap, dec, zero, v));
        pick.operands.push_back(v);
        pick.loc = loc;
        const ValueId magnitude = emit(std::move(pick));
        Inst scale;
        scale.op = Op::ConstInt;
        scale.type = dec;
        scale.text = "1" + std::string(cgutil::DECIMAL_SCALE, '0');
        scale.loc = loc;
        const ValueId by = emit(std::move(scale));
        const ValueId whole =
            lowerConversion(arith(Op::DivChecked, dec, magnitude, by), dec, i64, loc);
        const ValueId frac =
            lowerConversion(arith(Op::RemChecked, dec, magnitude, by), dec, i64, loc);
        const ValueId buf = callExternal("__polaron_malloc", tt.ptrType(), {i64},
                                         {constInt(64, 64, loc)}, loc);
        callExternal("__polaron_decimal_str", i64, {i32, i64, i64, tt.ptrType()},
                     {lowerConversion(negative, tt.boolType(), i32, loc), whole, frac, buf}, loc);
        return buf;
    }

    // §34: a cast that crosses the `Decimal` boundary, or kNoValue when it does not cross one (two
    // Decimals, or a `Decimal` reaching here through a path this does not own).
    //
    // Into a Decimal, an integer is multiplied by the scale and a float is multiplied before it is
    // truncated -- the truncation last, so `cast<Decimal>(0.1)` keeps the digits the double had.
    // Out of one, the scale is divided out first and the width narrowed after.
    ValueId lowerDecimalCast(ValueId v, const std::string& want, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* dec = tt.intType(kDecimalBits);
        const Type* from = fn_->value(v)->type;
        const bool wasDecimal = classNameOf(declaredName(v)) == "Decimal";
        if (from == nullptr || (want == "Decimal") == wasDecimal) {
            return kNoValue;   // Decimal to Decimal, or neither: nothing to rescale
        }
        auto scaleAt = [&](const Type* width) {
            Inst c;
            c.op = Op::ConstInt;
            c.type = width;
            c.text = "1" + std::string(cgutil::DECIMAL_SCALE, '0');
            c.loc = loc;
            return emit(std::move(c));
        };
        auto arith = [&](Op op, const Type* type, ValueId x, ValueId y) {
            Inst in;
            in.op = op;
            in.type = type;
            in.operands.push_back(x);
            in.operands.push_back(y);
            in.loc = loc;
            return emit(std::move(in));
        };
        if (want == "Decimal") {
            if (from->kind == TypeKind::Float) {
                const Type* f64 = tt.floatType(64);
                const ValueId wide = lowerConversion(v, from, f64, loc);
                Inst big;
                big.op = Op::ConstFloat;
                big.type = f64;
                big.fimm = 1e18;
                big.loc = loc;
                const ValueId out =
                    lowerConversion(arith(Op::FMul, f64, wide, emit(std::move(big))), f64, dec, loc);
                noteName(out, "Decimal");
                return out;
            }
            const ValueId out =
                arith(Op::MulWrap, dec, lowerConversion(v, from, dec, loc), scaleAt(dec));
            noteName(out, "Decimal");
            return out;
        }
        const Type* to = baseTypeOf(want);
        if (to == nullptr) {
            return kNoValue;
        }
        if (to->kind == TypeKind::Float) {
            const Type* f64 = tt.floatType(64);
            Inst big;
            big.op = Op::ConstFloat;
            big.type = f64;
            big.fimm = 1e18;
            big.loc = loc;
            const ValueId asFloat = lowerConversion(v, from, f64, loc);
            const ValueId out = arith(Op::FDiv, f64, asFloat, emit(std::move(big)));
            return to == f64 ? out : lowerConversion(out, f64, to, loc);
        }
        const ValueId whole = arith(Op::DivChecked, dec, v, scaleAt(dec));
        const ValueId out = lowerConversion(whole, dec, to, loc);
        noteName(out, want);
        return out;
    }

    Interp buildInterp(const ast::InterpStringExpr& is) {
        Interp out;
        TypeTable& tt = out_.module.types;
        for (size_t i = 0; i < is.exprs.size(); ++i) {
            out.format += escapePercents(is.literals[i]);
            const ValueId v = lowerExpr(is.exprs[i].get());
            if (v == kNoValue) {
                continue;
            }
            const Type* vt = fn_->value(v)->type;
            const std::string declared = classNameOf(declaredName(v));
            const SourceLocation loc = is.exprs[i]->loc;

            // `$"pi = {pi:0.00}"` -- THE FORMAT SPECIFIER (§4.1), which this pass was dropping.
            // The digits after the dot fix the decimal places; a specifier with no dot is a minimum
            // field width. Without it `{f:0.0}` printed `212` where the program asks for `212.0`,
            // and a program that formats a number is a program that cares which.
            const std::string spec = i < is.formats.size() ? is.formats[i] : std::string();
            const bool numeric =
                vt != nullptr && (vt->kind == TypeKind::Float || vt->kind == TypeKind::Int);
            if (!spec.empty() && numeric) {
                const size_t dot = spec.find('.');
                if (dot != std::string::npos) {
                    out.format += "%." + std::to_string(spec.size() - dot - 1) + "f";
                    out.values.push_back(lowerConversion(v, vt, tt.floatType(64), loc));
                    continue;
                }
                if (spec.find_first_not_of("0123456789") == std::string::npos) {
                    if (vt->kind == TypeKind::Float) {
                        out.format += "%" + spec + "g";
                        out.values.push_back(lowerConversion(v, vt, tt.floatType(64), loc));
                    } else {
                        out.format += "%" + spec + "d";
                        out.values.push_back(widen(v, 32, loc));
                    }
                    continue;
                }
            }
            if (declared == "Decimal") {
                // §34: NOT `%d` AND NOT `%g`. A Decimal is a 128-bit mantissa and printf has no
                // conversion for one; printed as an integer it shows the mantissa, and printed as a
                // double it shows a number the type exists to avoid. `decimalText` does the 128-bit
                // split here and the runtime assembles the digits.
                out.format += "%s";
                out.values.push_back(decimalText(v, loc));
            } else if (vt != nullptr && vt->kind == TypeKind::Float) {
                out.format += "%g";
                out.values.push_back(lowerConversion(v, vt, tt.floatType(64), loc));
            } else if (declared == "String" || declared == "string") {
                out.format += "%s";
                out.values.push_back(strField(v, kStrData, tt.ptrType(), loc));
            } else if (declared == "char") {
                out.format += "%c";
                out.values.push_back(v);
            } else if (vt != nullptr && vt->kind == TypeKind::Bool) {
                out.format += "%s";
                out.values.push_back(pickText(v, "true", "false", loc));
            } else if (isUnsignedValue(v)) {
                out.format += vt != nullptr && vt->bits == 64 ? "%llu" : "%u";
                out.values.push_back(v);
            } else if (vt != nullptr && vt->kind == TypeKind::Int && vt->bits == 64) {
                out.format += "%lld";
                out.values.push_back(v);
            } else if (vt != nullptr && vt->kind == TypeKind::Ptr) {
                // A pointer with no class behind it: print its bytes, which is what a `String`
                // arriving without its declaration would want and is harmless for anything else.
                out.format += "%s";
                out.values.push_back(v);
            } else {
                out.format += "%d";
                out.values.push_back(v);
            }
        }
        if (!is.literals.empty()) {
            out.format += escapePercents(is.literals.back());
        }
        return out;
    }

    // One of two texts, chosen at run time. PIR has no `select`, and it does not need one: a branch
    // into a block that takes the answer as a PARAMETER is the shape §1.2 chose block arguments for.
    // The same choice, but yielding the String OBJECT rather than its bytes -- what a method
    // declared `returns String` has to hand back, and what `println` of the result reads a length
    // from. Handing over the bytes alone made the object header whatever followed the literal.
    ValueId pickString(ValueId cond, const char* whenTrue, const char* whenFalse,
                       SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const BlockId yes = fn_->addBlock(fresh("strtrue"));
        const BlockId no = fn_->addBlock(fresh("strfalse"));
        const BlockId join = fn_->addBlock(fresh("strjoin"));
        const ValueId out = fn_->addValue(tt.ptrType(), ValueOrigin::BlockParam, join, 0, "");
        fn_->block(join)->params.push_back(out);
        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(asBoolean(cond, loc));
        br.edges.push_back(Edge{yes, {}});
        br.edges.push_back(Edge{no, {}});
        br.loc = loc;
        emit(std::move(br));
        for (const auto& [from, text] :
             {std::pair<BlockId, const char*>{yes, whenTrue}, {no, whenFalse}}) {
            here_ = from;
            Inst lit;
            lit.op = Op::ConstStr;
            lit.type = tt.ptrType();
            lit.text = text;
            lit.loc = loc;
            Inst go;
            go.op = Op::Br;
            Edge e{join, {}};
            e.args.push_back(emit(std::move(lit)));
            go.edges.push_back(e);
            go.loc = loc;
            emit(std::move(go));
        }
        here_ = join;
        noteName(out, "String");
        return out;
    }

    ValueId pickText(ValueId cond, const char* whenTrue, const char* whenFalse, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const BlockId yes = fn_->addBlock(fresh("istrue"));
        const BlockId no = fn_->addBlock(fresh("isfalse"));
        const BlockId join = fn_->addBlock(fresh("ijoin"));
        const ValueId out = fn_->addValue(tt.ptrType(), ValueOrigin::BlockParam, join, 0, "");
        fn_->block(join)->params.push_back(out);

        Inst br;
        br.op = Op::BrCond;
        br.operands.push_back(asBoolean(cond, loc));
        br.edges.push_back(Edge{yes, {}});
        br.edges.push_back(Edge{no, {}});
        br.loc = loc;
        emit(std::move(br));

        for (const auto& [from, text] :
             {std::pair<BlockId, const char*>{yes, whenTrue}, {no, whenFalse}}) {
            here_ = from;
            Inst go;
            go.op = Op::Br;
            Edge e{join, {}};
            e.args.push_back(literalText(text, loc));
            go.edges.push_back(e);
            go.loc = loc;
            emit(std::move(go));
        }
        here_ = join;
        return out;
    }

    static std::string escapePercents(const std::string& s) {
        std::string out;
        out.reserve(s.size());
        for (char c : s) {
            out += c;
            if (c == '%') {
                out += '%';   // a literal chunk is TEXT: its `%` is a percent sign, not a directive
            }
        }
        return out;
    }

    // `$"..."` used as a VALUE rather than printed: `snprintf` measures, then formats into a fresh
    // buffer. Two calls, which is what the trusted path does and what makes the length exact.
    ValueId lowerInterpAsString(const ast::InterpStringExpr& is, SourceLocation loc) {
        TypeTable& tt = out_.module.types;
        const Type* i32 = tt.intType(32);
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();
        Interp built = buildInterp(is);
        const ValueId fmt = literalText(built.format, loc);

        std::vector<ValueId> measure{constInt(0, 64, loc), constInt(0, 64, loc), fmt};
        // The destination is a null POINTER for the measuring pass; `snprintf(nullptr, 0, ...)`
        // returns the length it would have written.
        measure[0] = nullPointer(loc);
        for (ValueId v : built.values) {
            measure.push_back(v);
        }
        Function* sn = declareExternalTyped("snprintf", i32, {ptr, i64, ptr});
        sn->variadic = true;
        const ValueId shortLen = emitVariadic(sn, measure, i32, loc);

        Inst wide;
        wide.op = Op::ExtendS;
        wide.type = i64;
        wide.operands.push_back(shortLen);
        wide.loc = loc;
        const ValueId len = emit(std::move(wide));
        const ValueId cap = addLong(len, 1, loc);
        const ValueId buf = callExternal("__polaron_malloc", ptr, {i64}, {cap}, loc);

        std::vector<ValueId> format{buf, cap, fmt};
        for (ValueId v : built.values) {
            format.push_back(v);
        }
        emitVariadic(sn, format, i32, loc);
        const ValueId made = makeString(len, buf, loc);
        noteName(made, "String");
        return made;
    }

    ValueId nullPointer(SourceLocation loc) {
        Inst in;
        in.op = Op::ConstNull;
        in.type = out_.module.types.ptrType();
        in.loc = loc;
        return emit(std::move(in));
    }

    ValueId emitVariadic(const Function* fn, std::vector<ValueId> args, const Type* ret,
                         SourceLocation loc) {
        Inst in;
        in.op = Op::Call;
        in.text = fn->key;
        in.type = ret;
        in.operands = std::move(args);
        in.loc = loc;
        return emit(std::move(in));
    }

    // Bytes, not a `String`: this is a format string on its way to a C variadic, and the C boundary
    // conversion in `emitCall` would otherwise read a length out of the first eight characters.
    ValueId literalText(const std::string& text, SourceLocation loc) {
        Inst in;
        in.op = Op::ConstStr;
        in.type = out_.module.types.ptrType();
        in.text = text;
        in.loc = loc;
        const ValueId lit = emit(std::move(in));
        return strField(lit, kStrData, out_.module.types.ptrType(), loc);
    }

    Function* builtinFor(const std::string& name) {
        struct Row {
            const char* polaron;
            const char* symbol;
            bool variadic;
        };
        static constexpr Row kBuiltins[] = {
            {"System.IO.Console.printf", "printf", true},
            {"System.IO.printf", "printf", true},
            {"Console.printf", "printf", true},
            {"System.IO.Console.print", "printf", true},
            // `println` IS `printf`, not `puts`. As `puts` it took the first argument and dropped
            // the rest, so `println("sum=%d len=%d", sum, n)` printed its own format string back --
            // the literal text `sum=%d len=%d`, which reads like a formatting bug and is a lost
            // argument list. The newline and the "is this a format string" rule are handled at the
            // call site; see `lowerConsoleCall`.
            {"System.IO.Console.println", "printf", true},
            {"Console.println", "printf", true},
            {"System.IO.println", "printf", true},
        };
        for (const Row& r : kBuiltins) {
            if (name != r.polaron) {
                continue;
            }
            const std::string key = std::string("__builtin.") + r.symbol;
            if (Function* had = out_.module.find(key)) {
                return had;
            }
            Field a;
            a.type = out_.module.types.ptrType();
            Function* fn = out_.module.addFunction(
                key, out_.module.types.fnType(out_.module.types.intType(32), {a}));
            fn->linkage = Linkage::External;
            fn->conv = Conv::Cdecl;
            fn->symbol = r.symbol;
            fn->params = {{}};
            fn->variadic = r.variadic;
            return fn;
        }
        return nullptr;
    }

    Function* declareExternal(const std::string& key, size_t argc) {
        if (Function* had = out_.module.find(key)) {
            return had;
        }
        std::vector<Field> params;
        for (size_t i = 0; i < argc; ++i) {
            Field f;
            f.type = out_.module.types.ptrType();
            params.push_back(f);
        }
        Function* fn = out_.module.addFunction(
            key, out_.module.types.fnType(out_.module.types.voidType(), std::move(params)));
        fn->linkage = Linkage::External;
        fn->params.assign(argc, {});
        return fn;
    }

    // The exact key, or nothing. A qualified name resolves here before any receiver is evaluated.
    const Function* resolveKey(const std::string& key) const {
        for (const std::unique_ptr<Function>& f : out_.module.functions) {
            if (f->key == key) {
                return f.get();
            }
        }
        // A MEMBER OF A CLASS WHOSE NAME TWO CLASSES ANSWER TO is filed under the path, so a call
        // written with the bare name -- `Scanner.of(...)`, a static, which never has a receiver to
        // resolve from -- finds nothing. Resolving the owner and asking again is the same question
        // put to the right class; every other lookup already goes through a receiver whose recorded
        // name IS the key.
        if (!sharedNames_.empty()) {
            if (const size_t dot = key.rfind('.'); dot != std::string::npos) {
                const std::string owner = key.substr(0, dot);
                if (const std::string resolved = resolveClassKey(owner); resolved != owner) {
                    const std::string full = resolved + key.substr(dot);
                    for (const std::unique_ptr<Function>& f : out_.module.functions) {
                        if (f->key == full) {
                            return f.get();
                        }
                    }
                }
            }
        }
        // A dotted name whose leading components the module does not carry, tried from the most
        // specific to the least: `System.IO.Console.printf` -> `Console.printf` -> `printf`.
        //
        // The last step is not a guess. The prelude declares `printf` as a namespace-level `extern`
        // whose key is the bare name, so a qualified call to it matches nothing longer -- and
        // without this step the lowering invents an external symbol called
        // `System.IO.Console.printf`, which links against nothing and names something that was
        // never supposed to exist.
        size_t at = key.rfind('.');
        while (at != std::string::npos) {
            const std::string tail = key.substr(at + 1);
            for (const std::unique_ptr<Function>& f : out_.module.functions) {
                if (f->key == tail) {
                    return f.get();
                }
            }
            at = at == 0 ? std::string::npos : key.rfind('.', at - 1);
            if (at != std::string::npos) {
                const std::string two = key.substr(at + 1);
                for (const std::unique_ptr<Function>& f : out_.module.functions) {
                    if (f->key == two) {
                        return f.get();
                    }
                }
            }
        }
        return nullptr;
    }

    const Function* resolveSuffix(const std::string& method) const {
        for (const std::unique_ptr<Function>& f : out_.module.functions) {
            const std::string& fk = f->key;
            if (fk.size() > method.size() + 1 &&
                fk.compare(fk.size() - method.size() - 1, method.size() + 1, "." + method) == 0) {
                return f.get();
            }
        }
        return nullptr;
    }

    ValueId emitCall(const Function* target, std::vector<ValueId>&& args, SourceLocation loc) {
        // AT A C BOUNDARY, A `String` IS ITS BYTES. Inside Polaron a `String` is the three-word
        // object; `printf` and every other cdecl callee want the NUL-terminated data and nothing
        // else. Passing the object handed `printf` a pointer to a length, which prints as whatever
        // the first bytes of the header happen to spell. The conversion is a field read of a
        // constant, which the optimiser folds back to the address the trusted path passes directly.
        if (target != nullptr && target->conv == Conv::Cdecl) {
            for (ValueId& a : args) {
                if (const std::string n = classNameOf(declaredName(a));
                    n == "String" || n == "string") {
                    a = strField(a, kStrData, out_.module.types.ptrType(), loc);
                }
                // ...AND A CAPTURE-FREE LAMBDA IS A RAW FUNCTION POINTER (§26). A closure here is
                // `{code, env}` and the C side knows nothing of an environment: it calls what it is
                // given with the arguments it was told about. A lambda that captures nothing needs
                // no environment, so what crosses is the code -- and it has to be a body written
                // WITHOUT the leading env parameter, or the C caller puts its first argument where
                // the environment would be. Handing the closure object over instead called address
                // `{code,env}` as if it were code.
                if (const ValueId raw = cCallbackFor(a, loc); raw != kNoValue) {
                    a = raw;
                }
            }
        }
        // A VALUE STRUCT ARGUMENT TRAVELS BY VALUE. Inside a method an object is a pointer to its
        // storage -- a `struct` too, since that is what makes `k.bytes[i]` an address rather than a
        // register -- and at the boundary the signature says otherwise. Handing the pointer over
        // left the backend to coerce a `ptr` into a `%Key`, which it cannot do: `Main.total(k)`
        // went out as `call i32 @Main.total(%Key undef)` and summed four words of nothing.
        if (target != nullptr && target->signature != nullptr) {
            const std::vector<Field>& declared = target->signature->fields;
            for (size_t i = 0; i < args.size() && i < declared.size(); ++i) {
                // A CATALOG PARAMETER TAKES A TAGGED ORDINAL. Both a catalog value and a plain
                // enum ordinal lower to an integer, so coercing to the machine shape alone let an
                // untagged one through -- and it then read as whichever enum has id zero.
                if (i < target->params.size() && catalogs_.count(target->params[i].typeName) != 0) {
                    if (const std::string from = classNameOf(declaredName(args[i]));
                        enums_.count(from) != 0) {
                        args[i] = tagForCatalog(args[i], from, loc);
                    }
                }
                const Type* want = declared[i].type;
                const Type* have = args[i] != kNoValue ? fn_->value(args[i])->type : nullptr;
                // ANY ADDRESS, not only one typed `ptr`. An ELEMENT of an array of value structs
                // arrives as a `gep` whose type is the array's -- a `slice<Coord>`, because that is
                // what the instruction steps over -- and testing for `Ptr` alone let it through
                // unloaded: `h.cap - cs[0]` went out as `call %Coord @Coord.operator-(ptr, %Coord
                // undef)` and subtracted four words of nothing.
                // A SMALL STRUCT AT A C BOUNDARY IS ITS BYTES IN A REGISTER (§26). The parameter
                // was rewritten to an integer at the declaration, so what has to travel is the
                // struct's bytes READ AS THAT INTEGER -- one load of the right width from the
                // storage, which is what the trusted path emits as `%ffi.byval`.
                if (want != nullptr && want->kind == TypeKind::Int && have != nullptr &&
                    (have->isPointerLike() || have->kind == TypeKind::Struct) &&
                    i < target->params.size() && isValueClass(target->params[i].typeName) &&
                    ffiWord(named_.count(target->params[i].typeName) != 0
                                ? named_.at(target->params[i].typeName)
                                : nullptr) == want) {
                    args[i] = readAsWord(args[i], want, loc);
                } else if (want != nullptr && want->kind == TypeKind::Struct &&
                           want->facts.isValue && have != nullptr && have->isPointerLike()) {
                    Inst ld;
                    ld.op = Op::Load;
                    ld.type = want;
                    ld.operands.push_back(args[i]);
                    ld.loc = loc;
                    args[i] = emit(std::move(ld));
                } else if (want != nullptr && have != nullptr && want != have &&
                           (want->kind == TypeKind::Int || want->kind == TypeKind::Float ||
                            want->kind == TypeKind::Addr) &&
                           (have->kind == TypeKind::Int || have->kind == TypeKind::Float ||
                            have->kind == TypeKind::Addr)) {
                    // ...AND A NARROW ADDRESS IS A NUMBER TOO. `Addr` was left out of both lists, so
                    // a `short address` argument reaching an `address` parameter travelled with no
                    // conversion at all and the backend widened sixteen bits by their sign. See
                    // `lowerConversion` for what that cost.
                    // A NUMBER IS CONVERTED TO WHAT THE PARAMETER DECLARES. `new Turn(1.0, 0.0)`
                    // over a `float` parameter passed a `double` literal, and the backend's
                    // last-ditch coercion cannot narrow a float -- so the argument arrived as
                    // `undef` and every value computed from it was undefined. Done here, the
                    // conversion is an instruction the passes can see and fold.
                    args[i] = lowerConversion(args[i], have, want, loc);
                }
            }
        }
        Inst in;
        in.loc = loc;
        in.operands = std::move(args);
        if (target != nullptr) {
            in.op = Op::Call;
            in.text = target->key;
            in.type = target->signature != nullptr ? target->signature->element
                                                   : out_.module.types.voidType();
        } else {
            // Verifier rule 15 refuses a call to a key the module does not have, so an unresolved
            // callee is an INDIRECT call rather than a name that names nothing.
            in.op = Op::CallIndirect;
            in.type = out_.module.types.intType(32);
        }

        // INSIDE A `try`, A CALL THAT CAN THROW IS A `call.unwind`. Two successors -- the normal
        // path and the enclosing handler -- which is what makes a `catch` reachable at all. A call
        // that cannot unwind stays an ordinary call: giving every call two successors would put an
        // edge into the CFG that nothing can take, and every pass would have to reason about it.
        // AN INDIRECT CALL CAN UNWIND -- nothing here knows what it will reach, so the safe answer
        // is that it might throw. Excluding it left `try { action(); }` over a `function<void>`
        // with a `catch` block nothing branched to, which rule 19 refuses; and had the module been
        // accepted, the exception would have escaped a `try` written to stop it.
        const Type* produced = in.type;
        // INSIDE A `try`, EVERY CALL MAY UNWIND. Whether the callee DECLARES `throws` is not the
        // question: `risky()` declares nothing, throws, and its exception has to reach the `catch`
        // around the call. Asking the declaration left the call an ordinary one, so the throw
        // walked straight past a handler written to stop it. Outside a `try` there is nothing to
        // unwind to and an ordinary call is right -- which is also why this costs nothing anywhere
        // else in the program.
        const bool canUnwind = true;
        ValueId got;
        if (!handlers_.empty() && canUnwind) {
            in.op = Op::CallUnwind;
            const BlockId normal = fn_->addBlock(fresh("resumed"));
            in.edges.push_back(Edge{normal, {}});
            in.edges.push_back(Edge{handlers_.back().landing, {}});
            got = emit(std::move(in));
            here_ = normal;
        } else {
            got = emit(std::move(in));
        }
        // A SMALL STRUCT COMES BACK IN A REGISTER TOO. The declaration says the callee returns an
        // integer -- see `ffiWord` -- and what the program declared it returns is a struct, so the
        // bytes are put into storage of that shape and the address of it is what travels on, which
        // is what an object is everywhere else here.
        if (target != nullptr && got != kNoValue && produced != nullptr &&
            produced->kind == TypeKind::Int) {
            if (auto declared = returnName_.find(target->key); declared != returnName_.end()) {
                const std::string cls = classNameOf(declared->second.name);
                const Type* shape = named_.count(cls) != 0 ? named_.at(cls) : nullptr;
                if (shape != nullptr && ffiWord(shape) == produced) {
                    const ValueId at = wordAsStruct(got, shape, loc);
                    noteName(at, cls);
                    return at;
                }
            }
        }
        // §21: A `String` HANDED BACK BY A CALL BELONGS TO THE CALLER.
        //
        // A `return` copies (or claims) on the way out, so what arrives here is always a fresh
        // object nothing else names -- which makes it a temporary of THIS statement, exactly like
        // one this body built itself. Not recorded as one, two things went wrong at once: binding
        // it to a local COPIED it, because `ownedString` copies anything it does not recognise as a
        // temporary, and the original was then abandoned. `String h = Hex.encode("ABC");` allocated
        // twice and released neither, and the six such calls in `encoding_hex_base64` were the
        // whole of its 976 bytes against the other path's 400.
        //
        // The declared return type is what says so -- not the runtime shape, which is `ptr` for
        // every object alike -- and a `String*` is excluded by the same rule the field protocol
        // uses: a star means the author is sharing, not handing over.
        noteStringResult(target, got);
        return spillValueStruct(got, produced, loc);
    }

    // A `String` a call handed back is a temporary of the statement that made the call. Written
    // once and used from every call site -- direct, unwinding and virtual -- because a rule that
    // holds for one kind of call and not the others is a leak that depends on whether the method
    // was overridden.
    void noteStringResult(const Function* target, ValueId got) {
        if (target == nullptr || got == kNoValue) {
            return;
        }
        // A SWITCH THAT PUTS ONE DEFECT BACK, so a test can prove the instrument bites.
        //
        // Wave 2 deletes the trusted path and with it every check that is a COMPARISON. What
        // replaces them is absolute checks -- numbers a program reports about itself -- and an
        // absolute check that has never been seen to fail is a claim, not an instrument. So one is
        // demonstrated: `live_catches_reintroduced_defect` sets this, which restores exactly the
        // leak D6 had here, and REQUIRES `live_encoding_hex_base64` to fail. It moves 400/17 to
        // 976/41, and the test is registered `WILL_FAIL`.
        //
        // Read only here, and only for that test. Nothing else in the compiler consults it.
        if (std::getenv("POLARON_REINTRODUCE_D6") != nullptr) {
            return;
        }
        if (auto declared = returnName_.find(target->key);
            declared != returnName_.end() && declared->second.pointerDepth == 0 &&
            isStringNamed(declared->second.name)) {
            stringTemps_.emplace_back(got, here_);
        }
    }

    // A CALL THAT RETURNS A VALUE STRUCT HANDS BACK BYTES; the rest of this lowering means "an
    // object" whenever it says pointer, so the bytes are given a home right here and the pointer to
    // that home is what travels on. Without it `Box a = Box.make(100L)` memcpy'd FROM the struct
    // register -- `memcpy(ptr %copy, ptr undef, 8)` -- and both locals read poison.
    ValueId spillValueStruct(ValueId got, const Type* produced, SourceLocation loc) {
        if (got == kNoValue || produced == nullptr || produced->kind != TypeKind::Struct ||
            !produced->facts.isValue) {
            return got;
        }
        Inst home;
        home.op = Op::Alloca;
        home.type = produced;
        home.text = "ret.value";
        home.loc = loc;
        const ValueId slot = emit(std::move(home));
        Inst put;
        put.op = Op::Store;
        put.operands.push_back(got);
        put.operands.push_back(slot);
        put.loc = loc;
        emit(std::move(put));
        slotType_[slot] = produced;
        pointee_[slot] = produced;
        pointeeOfSlot_[slot] = produced;
        if (produced->nominal) {
            noteName(slot, produced->name);
        }
        return slot;
    }

    // A FRESH OBJECT'S WEAK SLOTS ARE NULL, WHEREVER THE STORAGE CAME FROM. A `weak` field is a
    // two-word slot the registry threads onto a list, and `__polaron_weak_link` UNLINKS the old
    // occupant before writing the new one -- so it reads both words of whatever the storage held
    // before it was handed out. Malloc'd bytes and a region's block are alike here: neither is
    // zeroed, and on Windows the heap hands back 0xBAADF00D, which the unlink walk then followed.
    // `linkedlist_stdlib` crashed about half the times it ran for exactly this reason:
    // `LinkedList.add` builds its node with `new LinkedNode<T>(item) in this.nodes` -- a REGION
    // allocation -- and only the plain `new` path was nulling the slots.
    //
    // One method because there are three storage branches -- the class arena, the region, and the
    // ordinary alloca -- and every one of them owes the object the same start. Called BEFORE the
    // constructor, since the constructor runs the first `weak = x` and must find a slot it can
    // unlink from.
    void initWeakSlots(ValueId obj, const std::string& className, const Type* t,
                       SourceLocation loc) {
        if (obj == kNoValue) {
            return;
        }
        if (carriesWeakHead(className)) {
            const ValueId head = rawOffset(obj, constLong(kWeakHeadOffset, loc), loc);
            slotType_[head] = out_.module.types.ptrType();
            storePtr(head, nullPointer(loc), loc);
        }
        if (t == nullptr || t->kind != TypeKind::Struct) {
            return;
        }
        for (const Field& f : t->fields) {
            if (!f.weak) {
                continue;
            }
            if (const ValueId slot = fieldAddress(obj, f.name, loc); slot != kNoValue) {
                storePtr(weakWord(slot, 0, loc), nullPointer(loc), loc);
                storePtr(weakWord(slot, 1, loc), nullPointer(loc), loc);
            }
        }
    }

    ValueId lowerNew(const ast::NewExpr& n) {
        std::vector<ValueId> args;
        for (const auto& a : n.args) {
            const ValueId v = lowerExpr(a.get());
            if (v != kNoValue) {
                args.push_back(v);
            }
        }
        // §21: `Ok(x)` IN VALUE FORM IS A VALUE. No allocation, no class, no vtable, nothing to
        // delete -- a tag and a payload in two registers. The analyser has already decided which
        // form this is and says so in `location`; this read that word and sent it to the allocator
        // anyway, so every fallible return cost a `__polaron_malloc(16)` and every instantiation
        // an entire class. `value_compat` carried 292 vtables where the other path carries ONE.
        //
        // Tag 0 is the success side -- `Ok` and `Some` -- and 1 the other, which is the numbering
        // the other back end assigns and the one a `match` arm is compared against.
        //
        // THE FOUR NAMES, not every `new` that says "value". `location` is set to `value` for a
        // plain `struct` too -- `Vec v = new Vec(n)` -- and reading the word alone turned one into
        // a two-word variant whose payload was its first constructor argument. The next line read
        // a field off it and the compiler died with no diagnostic at all.
        const bool sumCase = n.className == "Ok" || n.className == "Err" ||
                             n.className == "Some" || n.className == "None";
        if (n.location == "value" && sumCase) {
            const bool good = n.className == "Ok" || n.className == "Some";
            Inst make;
            make.op = Op::VariantMake;
            make.type = anyVariantType();
            make.imm = good ? 0 : 1;
            if (!args.empty()) {
                make.operands.push_back(args.front());
            }
            make.loc = n.loc;
            const ValueId built = emit(std::move(make));
            noteName(built, ast::mangleGeneric(n.className, n.typeArgs));
            return built;
        }
        // THE MONOMORPHIZED NAME, not the generic one. `new ArrayList<int>()` carries the base name
        // and its type arguments separately, and this took only the base -- so it allocated the
        // GENERIC `ArrayList`, which has no fields and no size, while the calls beside it went to
        // `ArrayList$int`. Worse, since the object had no class the method lookup fell back to
        // matching by bare name and bound `nums.add(10)` to `ArrayList$long.add`: a different
        // instantiation, chosen by whichever one the module happened to declare first.
        // WHICH CLASS OF THAT NAME. `new Color(255)` in a program that also has the library's
        // `Color` must build ITS Color -- and name the constructor the same way the declaration
        // did, or the call finds nothing, the object is left uninitialised, and the reachability
        // pass then turns the constructor nobody calls back into a declaration.
        const std::string className = resolveClassKey(ast::mangleGeneric(n.className, n.typeArgs));
        // §30: BUILDING ONE OF SOMETHING THAT IS GONE THROWS. Checked before the storage is taken,
        // so a refused construction leaves nothing half-made behind.
        guardAlive(ast::mangleGeneric(n.className, n.typeArgs), n.loc);
        // §37.3: A LAZILY IMPORTED CLASS LOADS ON ITS FIRST INSTANCE. Its `onClassLoad` is not in
        // the module's init list, so this is the only thing that ever runs it -- once, guarded by a
        // flag, which is what "on its first instance" means.
        loadLazyImport(className, n.loc);
        const Type* t = baseTypeOf(className);
        Inst in;
        in.loc = n.loc;
        // A REGION CLASS ANSWERS THE QUESTION ITSELF, before the placement is read. `new A()` with
        // no placement parses as location "stack" -- that is the default for every class -- and
        // taking that at its word put a region-class instance on the frame and destroyed it at the
        // closing brace, on an object the design says lives until it is deleted or the region dies.
        // Asking the CLASS where its instances live is the only reading that cannot be wrong,
        // because for a region class there is exactly one answer and the author never writes it.
        if (t != nullptr && t->kind == TypeKind::Struct && livesInClassArena(className)) {
            // ...AND A PLACEMENT WRITTEN ANYWAY IS REFUSED, not ignored.
            //
            // Accepting `on heap` and quietly allocating from the region is the worst of the three
            // outcomes: the author wrote a placement, the compiler did something else, and nothing
            // said so. Obeying it is worse still -- one instance outside the arena ends the totality
            // that a region class's whole value rests on: O(1) liveness for `unimport`, the linear
            // walk over every instance, and the eventual 32-bit `A*` that is an OFFSET from the
            // arena base and is not an offset at all if the object is somewhere else.
            //
            // `on stack` has to be asked about separately from `on heap`, because "stack" is what
            // the DEFAULT parses as: silence and the written word arrive here identical unless the
            // parser says which it was. That is what `locationWritten` is for, and it is also the
            // placement that would do the most damage.
            if (n.location == "heap") {
                refuse("`" + className +
                           "` is a `region class`, so `on heap` has nowhere to put this -- every "
                           "instance comes from the type's own region, and that is the whole "
                           "guarantee. Write `new " + className + "(...)` with no placement",
                       n.loc);
            } else if (n.locationWritten) {
                refuse("`" + className + "` is a `region class`, so `on " + n.location +
                           "` has nowhere to put this -- every instance comes from the type's own "
                           "region, and a region class is worth having precisely because there is "
                           "nowhere else. Write `new " + className + "(...)` with no placement",
                       n.loc);
            } else if (!n.region.empty()) {
                refuse("`" + className +
                           "` is a `region class`, so every instance comes from its own region -- "
                           "`in region " + n.region + "` would put one somewhere else, and the "
                           "guarantee that makes a region class worth having is that there is "
                           "nowhere else",
                       n.loc);
            }
            const ValueId obj = classArenaAlloc(className, t, n.loc);
            pointee_[obj] = t;
            noteName(obj, className);
            regionOwned_.insert(obj);   // the arena's to destroy, never the block's
            initWeakSlots(obj, className, t, n.loc);
            const std::string ctorKey = className + "." + className;
            if (out_.module.find(ctorKey) != nullptr) {
                std::vector<ValueId> all{obj};
                for (ValueId a : args) {
                    all.push_back(a);
                }
                emitCall(resolveKey(ctorKey), std::move(all), n.loc);
            }
            return obj;
        }
        // WHERE IT LIVES IS PART OF THE INSTRUCTION. `on stack`, `on heap` and `in region R` are
        // three different allocations, and escape analysis (§11.5) rewrites the second into the
        // first when it can prove nothing escapes -- which it can only do if the site says which
        // one it was.
        if (!n.region.empty()) {
            // `new T in region R` IS A CURSOR BUMP, written out. `RegionAlloc` reached the backend
            // as an opcode nothing translated, so the object had no storage at all -- which is why
            // every region sample read back whatever the block happened to contain. Emitted here
            // rather than left to the backend because the arithmetic is the language's (§17), not
            // the target's: one header layout, one alignment rule, one place.
            // A MULTI-RANGE REGION HAS NO BLOCK TO LOOK UP. Its memory is somebody else's, at
            // addresses the declaration named, and which one this object goes to is decided from
            // its TYPE -- so the routing happens before anything is loaded (§17.4).
            const bool multi = multiRegions_.count(n.region) != 0;
            const ValueId region = multi ? kNoValue : regionBlockFor(n.region, n.loc);
            if ((multi || region != kNoValue) && t != nullptr && t->kind == TypeKind::Struct) {
                const ValueId obj = multi ? multiRangeAlloc(n.region, className, t, n.loc)
                                          : regionAlloc(region, t, n.loc, n.region);
                if (obj == kNoValue) {
                    return kNoValue;
                }
                pointee_[obj] = t;
                noteName(obj, className);
                // AN OBJECT IN A REGION IS THE REGION'S TO DESTROY, not the block's. It lives
                // until the region is released or rolled back -- that is what a region IS -- so
                // registering it for scope-exit teardown as well destroyed it twice: `region_stack`
                // counted 200000 destructions of 100000 objects.
                regionOwned_.insert(obj);
                // §37.5: AN OBJECT IN A `volatile` REGION IS A DEVICE. Marking the object is
                // enough: every field address is a `gep` off it, and `emit` hands the fact down
                // the chain -- so `window.control = 1` writes a register rather than a variable
                // the optimiser is free to keep in a machine register.
                if (volatileRegions_.count(n.region) != 0) {
                    volatilePointee_.insert(obj);
                }
                initWeakSlots(obj, className, t, n.loc);
                const std::string ctorKey = className + "." + className;
                if (out_.module.find(ctorKey) != nullptr) {
                    std::vector<ValueId> all{obj};
                    for (ValueId a : args) {
                        all.push_back(a);
                    }
                    emitCall(resolveKey(ctorKey), std::move(all), n.loc);
                }
                // AN OBJECT WITH A DESTRUCTOR IS RECORDED WITH THE REGION. The compiler can only
                // see the objects created in the block that releases the region; a tree built
                // across method calls is invisible to it, and so is anything allocated in a loop.
                // The registry is what makes a region's destructors correct rather than merely
                // lexical -- and it is what `rollback` walks. Only objects that HAVE a destructor
                // reach here, so a region of plain data never touches it.
                if (const ast::ClassDecl* decl = findClass(className); decl != nullptr) {
                    if (const std::string dtor = destructorOf(*decl);
                        !dtor.empty() && regionShapeOf(n.region).registry()) {
                        TypeTable& types = out_.module.types;
                        Inst which;
                        which.op = Op::ConstFn;
                        which.type = types.ptrType();
                        which.text = dtor;
                        which.loc = n.loc;
                        callExternal("__polaron_region_track", types.voidType(),
                                     {types.ptrType(), types.ptrType(), types.ptrType()},
                                     {region, obj, emit(std::move(which))}, n.loc);
                    }
                }
                return obj;
            }
            in.op = Op::RegionAlloc;
            if (region != kNoValue) {
                in.operands.push_back(region);
            }
        // A VALUE `Option`/`Result` (§21) IS STILL AN OBJECT HERE. The trusted path packs it into a
        // `{tag, payload}` register pair; this lowering has no aggregate-by-value shape, so it
        // builds the ordinary `Some$int`/`None$int` object -- which every reader of one already
        // handles: `match` compares tables, `try?` reads the table, and the methods dispatch. What
        // it must NOT be is a FRAME slot: `return Some(x)` from a method hands back the address of
        // a frame that has gone, and `find` answered whatever the caller's stack held next.
        // A BOUND TARGET IS STORAGE THE PROCEDURE HANDS BACK (§ transformers): `procedure
        // into<Fahrenheit f>` fills `f` and returns it, so a frame slot is dead the instant the
        // procedure returns. The declaration says "stack" because that is the default nobody wrote,
        // and taking that at its word made the FIRST conversion work by luck -- nothing had
        // overwritten the frame yet -- and the second read the first one's leftovers: `212F is
        // 137523637C`.
        // A `struct`, `record` or `union` IS COPIED, so it does not need to outlive the frame that
        // made it. That is the whole difference between a value and an object: `typeOf` hands a
        // value class its aggregate type rather than a pointer, so every assignment, argument and
        // `return` of one copies the bytes, and the frame slot they were copied OUT of can die.
        //
        // This branch used to send every value class to the allocator, and said so: "the block
        // comes from the allocator, which costs a leak rather than a wrong answer... a placeholder
        // with a name on it, not a design". The placeholder was written when this lowering had no
        // aggregate-by-value shape and an object was only ever reached through a pointer; it has
        // one now, and the trusted path has always put these on the frame -- `%PageTable.obj =
        // alloca %class.PageTable` where this emitted `call ptr @__polaron_malloc(i64 8)`.
        //
        // In a hosted program that difference is a leak nothing measures. In a kernel it is fatal
        // and immediate: pico's page walk builds a `new VirtualAddress(virt)` per page and a `new
        // PageTable(...)` per level, so mapping one 3 MiB framebuffer asked the allocator for
        // several thousand eight-byte blocks that nothing ever frees -- inside the method that
        // maps memory.
        //
        // `on heap` in the author's own hand is still honoured: it is a placement, and refusing
        // one that was written is a different act from choosing one that was not.
        } else if (isValueClass(className) && n.location != "heap" &&
                   asyncStatePtr_ == kNoValue) {
            in.op = Op::Alloca;
        } else if (isValueClass(className) && n.location != "heap") {
            // §20.2: INSIDE AN ASYNC BODY A VALUE AGGREGATE GOES TO THE HEAP. Its frame home
            // belongs to one resume invocation and is gone by the next, so a state field holding
            // its address would point at a dead frame after the first suspension. Promoted for
            // every such `new` in the body rather than only the ones that demonstrably cross a
            // suspension: which those are needs a liveness analysis, and the block is reclaimed at
            // the scope end either way.
            in.op = Op::Alloca;
            in.extra.push_back("heap");
        } else if (n.blank || n.location == "heap" || n.location == "value" || returningNew_) {
            // AN OBJECT IS REACHED THROUGH A POINTER, so `return new Counter(n + 1)` from an
            // `operator ++` handed back the address of the callee's own frame -- dead the instant
            // it returned, and the counter it fed read garbage.
            in.op = Op::Alloca;
            in.extra.push_back("heap");
        } else {
            // THE DEFAULT IS THE STACK. This read "anything that does not say `stack` is heap",
            // which was invisible while both spellings emitted the same frame slot and became a
            // leak the moment `on heap` started calling the allocator -- and worse than a leak:
            // a plain `new T()` is RAII, destroyed at the end of its scope, and moving it to the
            // heap changes when its destructor runs.
            in.op = Op::Alloca;
        }
        // WHAT IT ALLOCATES IS THE CLASS, not a pointer. `Alloca`'s type is the thing being made --
        // that is what §7.4 says and what the backend reads -- and this said `ptr`, so EVERY object
        // in every program got eight bytes however many fields it had. A `StringBuilder` has three;
        // its constructor wrote the third one past the end of its own storage, and the corruption
        // surfaced as a loop that would not terminate three methods away.
        in.type = t != nullptr && t->kind == TypeKind::Struct ? t : out_.module.types.ptrType();
        in.text = className;
        const ValueId obj = emit(std::move(in));   // a frame slot is hoisted by `emit` -- see there
        if (obj == kNoValue) {
            return kNoValue;
        }
        // A VALUE STRUCT WITH NO CONSTRUCTOR STARTS AT ZERO.
        //
        // A class is safe without this: the analyzer refuses a constructor that leaves a field
        // unassigned, so every field of a class is written before anything can read it. A struct
        // with no declared constructor has no constructor to hold to that promise, and reading
        // uninitialised memory is precisely what this language says does not happen.
        //
        // It was missing here and INVISIBLE, because every such object was coming from the
        // allocator and a fresh block from the operating system is already zero. Moving value
        // structs to the frame -- where the bytes are the previous call's -- is what uncovered it:
        // `fixed_array` summed a four-element inline array and got a different wrong answer on
        // every run, while the two elements the program had written read back correctly.
        //
        // Only for a struct, and only when nothing else is going to write those bytes: a declared
        // constructor is the author saying what the initial values are.
        bool authorWroteOne = false;
        if (const ast::ClassDecl* decl = findClass(className); decl != nullptr) {
            forEachMember<ast::ConstructorDecl>(
                *decl, [&](const ast::ConstructorDecl&) { authorWroteOne = true; });
        }
        if (t != nullptr && t->kind == TypeKind::Struct && isValueClass(className) &&
            !authorWroteOne) {
            TypeTable& types = out_.module.types;
            callExternal("memset", types.ptrType(),
                         {types.ptrType(), types.intType(32), types.intType(64)},
                         {obj, constInt(0, 32, n.loc), sizeOfClass(t, n.loc)}, n.loc);
        }
        // The class travels with the object, so a field access on it knows where to look.
        if (t != nullptr && t->kind == TypeKind::Struct) {
            pointee_[obj] = t;
        }
        noteName(obj, className);
        // ...and so does WHERE IT CAME FROM, because a `delete` of it must free the heap ones and
        // must not free the frame ones.
        // A VALUE VARIANT IS NOT `delete`d BY ANYBODY -- the language says it carries no ownership
        // -- so it is not recorded as heap storage even though that is where it lives. Recording it
        // would make a scope end free something the program still holds.
        // ...AND THE FRAME ONES ARE RECORDED TOO, which is the whole reason storage has three
        // states rather than two. `new T()` with no placement is a frame slot -- spec 3.6's RAII
        // default -- and a `delete` of one must run the destructor and NOT call the allocator.
        // Saying only which ones are heap left "on the frame" and "allocated somewhere this method
        // cannot see" spelled the same way, and no rule can be right about both.
        noteStorage(obj, n.location == "heap" ? Storage::Heap : Storage::Frame);
        // AN EMPTY WEAK LIST TO START, and empty slots in every weak field -- see `initWeakSlots`,
        // which the other two storage branches call for the same reason. Written before the
        // constructor for the same reason the persistent block is: the constructor may already
        // assign a weak field, and the assignment unlinks whatever the slot says it holds.
        initWeakSlots(obj, className, t, n.loc);
        // §18.2: THE BLOCK IS ATTACHED BEFORE THE CONSTRUCTOR RUNS, because the constructor may
        // read a persistent field -- that is what reattaching is for -- and because an inline
        // initialiser on one would otherwise write through a wild pointer.
        attachPersistBlock(obj, className, n.loc);

        // ...and then the constructor, AS AN ORDINARY CALL -- through `emitCall`, which is the one
        // place that knows what a call is. Building the instruction here by hand meant a
        // constructor argument got none of what every other call does: no coercion to what the
        // parameter declares, no catalog tagging, no value-struct load, no unwind edge inside a
        // `try`. `new Crate(Timber.Oak)` handed a singleton POINTER to a `Heavy` parameter and the
        // backend reinterpreted it as an integer.
        // ...AND NO CONSTRUCTOR RUNS OVER IT. `blank` is storage the BODY constructs -- that is
        // what the target's `entrusts` agreed to, and what the analyzer holds the body to. Calling
        // the constructor anyway passed `undef` for every parameter it declares.
        const std::string ctorKey = className + "." + className;
        if (const Function* ctor = n.blank ? nullptr : resolveKey(ctorKey)) {
            std::vector<ValueId> all{obj};
            // A PARTIAL CONSTRUCTOR (§18.9): fewer arguments than parameters, and the ones left out
            // are the parameters NAMED LIKE A PERSISTENT FIELD -- they take the reattached value
            // instead of one the caller passes. `new Car(7)` on `Car(int serial, int motor)` means
            // motor = 7 and serial = whatever the last Car left behind. Filled positionally, the 7
            // landed in `serial` and the sample printed 71 71 71 for 7 17 27.
            const std::vector<ValueId> filled = partialConstructorArgs(className, obj, n, args);
            for (ValueId a : filled.empty() ? args : filled) {
                all.push_back(a);
            }
            emitCall(ctor, std::move(all), n.loc);
        }
        (void)t;
        return obj;
    }

    // The full argument list a partial constructor needs, or nothing when the call is ordinary.
    std::vector<ValueId> partialConstructorArgs(const std::string& cls, ValueId object,
                                                const ast::NewExpr& n,
                                                const std::vector<ValueId>& provided) {
        auto order = persistOrder_.find(cls);
        if (order == persistOrder_.end()) {
            return {};
        }
        const ast::ClassDecl* decl = findClass(cls);
        if (decl == nullptr) {
            return {};
        }
        const ast::ConstructorDecl* ctor = nullptr;
        forEachMember<ast::ConstructorDecl>(*decl, [&](const ast::ConstructorDecl& k) {
            if (ctor == nullptr) {
                ctor = &k;
            }
        });
        if (ctor == nullptr || n.args.size() >= ctor->params.size()) {
            return {};
        }
        const Type* block = persistBlock_.count(cls) != 0 ? persistBlock_[cls] : nullptr;
        // THE BLOCK IS ALREADY ATTACHED at this point -- that is why it is attached before the
        // constructor runs and not after -- so the values come out of the object rather than out
        // of a pointer this would have to compute a second way.
        std::vector<ValueId> out;
        size_t next = 0;
        for (const ast::Param& p : ctor->params) {
            int64_t at = -1;
            for (size_t i = 0; i < order->second.size(); ++i) {
                if (order->second[i] == p.name) {
                    at = static_cast<int64_t>(i);
                    break;
                }
            }
            if (at >= 0 && block != nullptr) {
                // READ BACK OUT OF THE OBJECT, which already holds the block -- rather than
                // recomputing where the block is. A named block is a global and an index-keyed one
                // comes from a registry, and this way the two need no separate cases here.
                out.push_back(loadFrom(persistParamAddress(cls, object, block, at, n.loc), n.loc));
            } else if (next < provided.size()) {
                out.push_back(provided[next++]);
            } else {
                out.push_back(constInt(0, 32, n.loc));
            }
        }
        return out;
    }

    ValueId persistParamAddress(const std::string& cls, ValueId object, const Type* block,
                                int64_t at, SourceLocation loc) {
        Inst hold;
        hold.op = Op::Gep;
        hold.type = out_.module.types.ptrType();
        hold.operands.push_back(object);
        hold.aggregate = named_.count(cls) != 0 ? named_[cls] : nullptr;
        hold.imm = persistIndex_.count(cls) != 0 ? persistIndex_[cls] : 0;
        hold.text = "__persist";
        hold.loc = loc;
        const ValueId slot = emit(std::move(hold));
        slotType_[slot] = out_.module.types.ptrType();
        const ValueId from = loadFrom(slot, loc);
        Inst g;
        g.op = Op::Gep;
        g.type = out_.module.types.ptrType();
        g.operands.push_back(from);
        g.aggregate = block;
        g.imm = at;
        g.text = persistOrder_[cls][static_cast<size_t>(at)];
        g.loc = loc;
        const ValueId addr = emit(std::move(g));
        if (static_cast<size_t>(at) < block->fields.size()) {
            slotType_[addr] = block->fields[at].type;
        }
        return addr;
    }

    ValueId concat(ValueId left, ValueId right, SourceLocation loc) {
        if (left == kNoValue) {
            return right;
        }
        if (right == kNoValue) {
            return left;
        }
        // BUILT HERE, not called. This declared `String.concat` as an external and called it, and
        // verifier rule 15 was satisfied because a declaration IS a declaration -- but the runtime
        // exports no such symbol and the trusted path never emits a call, it open-codes the join.
        // So every program that concatenated two strings compiled, verified, and then failed to
        // link naming a method the standard library appears to declare. Rule 15 moves "never
        // emitted" forward to compile time only for keys this module owns; a name invented for an
        // external cannot be checked by anyone until the linker looks.
        TypeTable& tt = out_.module.types;
        const Type* i64 = tt.intType(64);
        const Type* ptr = tt.ptrType();

        const ValueId leftLen = strField(left, kStrLength, i64, loc);
        const ValueId rightLen = strField(right, kStrLength, i64, loc);
        Inst sum;
        sum.op = Op::AddWrap;
        sum.type = i64;
        sum.operands.push_back(leftLen);
        sum.operands.push_back(rightLen);
        sum.loc = loc;
        const ValueId total = emit(std::move(sum));

        const ValueId buf =
            callExternal("__polaron_malloc", ptr, {i64}, {addLong(total, 1, loc)}, loc);
        callExternal("memcpy", ptr, {ptr, ptr, i64},
                     {buf, strField(left, kStrData, ptr, loc), leftLen}, loc);
        callExternal("memcpy", ptr, {ptr, ptr, i64},
                     {rawOffset(buf, leftLen, loc), strField(right, kStrData, ptr, loc), rightLen},
                     loc);
        Inst nul;
        nul.op = Op::Store;
        nul.operands.push_back(constInt(0, 8, loc));
        nul.operands.push_back(rawOffset(buf, total, loc));
        nul.loc = loc;
        emit(std::move(nul));

        const ValueId made = makeString(total, buf, loc);
        noteName(made, "String");
        return made;
    }

    ValueId lowerBinary(const ast::BinaryExpr& b) {
        // SHORT CIRCUIT IS CONTROL FLOW, so it is blocks. `a && b` does not evaluate `b` when `a`
        // is false, and an IR that lowered it to a bitwise `and` would evaluate both -- which is
        // wrong whenever the right side faults, allocates, or has an effect. Block arguments carry
        // the result out, which is what §1.2 chose them for.
        if (b.op == "&&" || b.op == "||") {
            const bool isAnd = b.op == "&&";
            const ValueId l = lowerExpr(b.lhs.get());
            const BlockId rhsB = fn_->addBlock(fresh(isAnd ? "andrhs" : "orrhs"));
            const BlockId join = fn_->addBlock(fresh("sc"));
            const ValueId out = fn_->addValue(out_.module.types.boolType(),
                                              ValueOrigin::BlockParam, join, 0, "");
            fn_->block(join)->params.push_back(out);

            Inst shortcut;
            shortcut.op = Op::ConstBool;
            shortcut.type = out_.module.types.boolType();
            shortcut.imm = isAnd ? 0 : 1;
            const ValueId shortVal = emit(std::move(shortcut));

            Inst br;
            br.op = Op::BrCond;
            br.loc = b.loc;
            if (l != kNoValue) {
                br.operands.push_back(l);
            }
            Edge whenTrue{isAnd ? rhsB : join, {}};
            Edge whenFalse{isAnd ? join : rhsB, {}};
            (isAnd ? whenFalse : whenTrue).args.push_back(shortVal);
            br.edges.push_back(whenTrue);
            br.edges.push_back(whenFalse);
            emit(std::move(br));

            here_ = rhsB;
            const ValueId r = lowerExpr(b.rhs.get());
            // AS A BOOLEAN, because the join block declares one. The right side of `&&` can lower to
            // an `i32` -- a call, a field read the propagation could not type -- and passing it
            // where a `bool` is declared is exactly what verifier rule 3 refuses. The comparison is
            // free: the backend folds it when the value is already a boolean.
            Inst go;
            go.op = Op::Br;
            Edge e{join, {}};
            e.args.push_back(r != kNoValue ? asBoolean(r, b.loc) : shortVal);
            go.edges.push_back(e);
            emit(std::move(go));

            here_ = join;
            return out;
        }

        ValueId l = lowerExpr(b.lhs.get());
        // §20.2: THE LEFT SIDE OUTLIVES A SUSPENSION ON THE RIGHT. `out = base + await val(5)`
        // loads `base`, suspends, and adds -- and the loaded value belongs to a block the resume
        // does not come from, so the module does not verify. Put away before, read back after.
        const int64_t parked = asyncStateObj_ != kNoValue && containsAwait(b.rhs.get())
                                   ? spillAcrossAwait(l)
                                   : -1;
        ValueId r = lowerExpr(b.rhs.get());
        l = reloadSpill(parked, l);
        if (l == kNoValue || r == kNoValue) {
            return kNoValue;
        }
        TypeTable& tt = out_.module.types;

        // BOTH SIDES TO ONE WIDTH, before anything else. `long + int` was emitted as-is and the
        // backend cannot make an `add` of an i64 and an i32, so it produced `undef` -- a well-formed
        // module that computes nothing, which the verifier is right not to catch and the differential
        // is the only thing that does. The wider side wins, and the narrower is extended by ITS OWN
        // sign, which is the one place the two facts have to be read together.
        const Type* lty = fn_->value(l)->type;
        const Type* rty = fn_->value(r)->type;
        if (lty != nullptr && rty != nullptr && lty->kind == TypeKind::Int &&
            rty->kind == TypeKind::Int && lty->bits != rty->bits) {
            if (lty->bits < rty->bits) {
                const ValueId wide = lowerConversion(l, lty, rty, b.loc);
                noteName(wide, declaredName(l));   // widening does not change what it is
                l = wide;
            } else {
                const ValueId wide = lowerConversion(r, rty, lty, b.loc);
                noteName(wide, declaredName(r));
                r = wide;
            }
        }
        const Type* lt = fn_->value(l)->type;

        Inst in;
        in.loc = b.loc;
        in.operands.push_back(l);
        in.operands.push_back(r);

        // THE OVERFLOW RULE IS THE OPCODE -- and the rule is WRAP, not check.
        //
        // This pass emitted `add.checked` for every `+` on the belief that "no undefined behaviour"
        // meant "traps on overflow". It does not: spec 3.6 makes integer arithmetic modular, which
        // is what makes it defined, and `checked(expr)` is the per-expression opt-in that trades
        // that for a trap. Checking everything was wrong twice over -- it changed the semantics of
        // every wrapping algorithm in the standard library (a hash, a PRNG, a checksum: all of them
        // wrap ON PURPOSE), and it inhibits the inliner and the loop optimiser, which the trusted
        // path's own comment measures at about ten times on hot arithmetic. Turning the LLVM path
        // off with this in place would have made every program slower and some of them wrong.
        //
        // Inside `checked(...)` the opcode changes and nothing else does; that is the whole point
        // of putting the rule in the opcode.
        const bool ck = checkedArith_;
        // EITHER SIDE being unsigned makes the operation unsigned. The analyzer has already refused
        // the mixtures that are errors, so what reaches here is a `uint` beside a literal or beside
        // a value this pass could not trace -- and in both of those the unsigned side is the one
        // that knows. Defaulting to signed is what gave `(a + b) % 65521` a negative answer.
        // AN OVERLOADED OPERATOR IS A METHOD CALL. `a + b` over a class that declares `operator +`
        // means `a.operator+(b)`, and this pass went straight to the integer opcodes: two pointers
        // were added as if they were numbers, and the result was an address nobody could use. The
        // method is named `operator+` -- the parser spells it exactly that way -- so the lookup is
        // the same one every other call makes.
        // A POINTER IS NOT A NUMBER (spec 27), and this is checked before the operator overload so
        // that a class with an `operator +` and a `T*` to it still steps by elements.
        if (const Lowered stepped = pointerArith(b, l, r); stepped.handled) {
            return stepped.value;
        }
        if (const std::string cls = classNameOf(declaredName(l)); !cls.empty()) {
            if (const Function* op = resolveKey(cls + ".operator" + b.op)) {
                const ValueId out = emitCall(op, {l, r}, b.loc);
                if (auto it = returnName_.find(op->key); it != returnName_.end()) {
                    noteName(out, it->second.name, it->second.pointerDepth);
                }
                return out;
            }
        }

        // §34: TWO DECIMALS. `+` and `-` are the mantissas added; `*` and `/` have to move the
        // scale, and they do it through a 256-bit intermediate so the product of two mantissas
        // cannot overflow on the way. Everything else -- the comparisons -- is the integers as they
        // are. Handled before the ordinary integer path, which would divide 5.0 by 2.0 as
        // 5*10^18 / 2*10^18 and answer 2.
        if (classNameOf(declaredName(l)) == "Decimal" && classNameOf(declaredName(r)) == "Decimal" &&
            (b.op == "*" || b.op == "/")) {
            const Type* wide = tt.intType(kDecimalWideBits);
            const Type* dec = tt.intType(kDecimalBits);
            Inst scale;
            scale.op = Op::ConstInt;
            scale.type = wide;
            scale.text = "1" + std::string(cgutil::DECIMAL_SCALE, '0');
            scale.loc = b.loc;
            const ValueId by = emit(std::move(scale));
            const ValueId lw = lowerConversion(l, lt, wide, b.loc);
            const ValueId rw = lowerConversion(r, fn_->value(r)->type, wide, b.loc);
            auto arith = [&](Op op, ValueId x, ValueId y) {
                Inst in2;
                in2.op = op;
                in2.type = wide;
                in2.operands.push_back(x);
                in2.operands.push_back(y);
                in2.loc = b.loc;
                return emit(std::move(in2));
            };
            const ValueId scaled = b.op == "*" ? arith(Op::DivChecked, arith(Op::MulWrap, lw, rw), by)
                                               : arith(Op::DivChecked, arith(Op::MulWrap, lw, by), rw);
            const ValueId out = lowerConversion(scaled, wide, dec, b.loc);
            noteName(out, "Decimal");
            return out;
        }
        const bool uns = isUnsignedValue(l) || isUnsignedValue(r);

        // ELEMENT-WISE, AND THAT IS ALL IT TAKES. `a + b` over two vectors is one `fadd` whose
        // operands happen to be vectors -- no opcode of its own, no loop, nothing for the backend to
        // recognise -- which is the second return on making `Vector` a kind rather than a struct of
        // N floats. A SCALAR OPERAND BROADCASTS: `a * 2.0` scales every lane, so the scalar side is
        // built into a vector of the same width first.
        if (isVector(fn_->value(l)->type) || isVector(fn_->value(r)->type)) {
            const Type* vt =
                isVector(fn_->value(l)->type) ? fn_->value(l)->type : fn_->value(r)->type;
            if (!isVector(fn_->value(l)->type)) {
                l = buildVector(vt, {l}, b.loc);
            }
            if (!isVector(fn_->value(r)->type)) {
                r = buildVector(vt, {r}, b.loc);
            }
            Inst wide;
            wide.type = vt;
            wide.operands.push_back(l);
            wide.operands.push_back(r);
            wide.loc = b.loc;
            if (b.op == "+") { wide.op = Op::FAdd; }
            else if (b.op == "-") { wide.op = Op::FSub; }
            else if (b.op == "*") { wide.op = Op::FMul; }
            else if (b.op == "/") { wide.op = Op::FDiv; }
            else {
                gap("BinaryExpr(operator '" + b.op + "' on a vector)", b.loc);
                return kNoValue;
            }
            return emit(std::move(wide));
        }

        // A JAVA-STYLE ENUM ORDERS BY ORDINAL (§12.2), which is its DECLARATION INDEX and not its
        // fields and not its address. `LOW < HIGH` is the same question Java's compareTo answers,
        // and each constant is one singleton object here -- so the comparison is over the ordinals
        // recovered from those identities, never over the pointers. Compared as pointers, `HIGH >
        // MEDIUM` answered whichever way the allocator happened to lay the two singletons out.
        if (b.op != "==" && b.op != "!=") {
            const std::string ln = classNameOf(declaredName(l));
            const std::string rn = classNameOf(declaredName(r));
            const std::string en = enums_.count(ln) != 0 ? ln : (enums_.count(rn) != 0 ? rn : "");
            if (!en.empty()) {
                if (auto decl = enums_.find(en);
                    decl != enums_.end() && decl->second != nullptr && decl->second->isJavaStyle) {
                    const ValueId oa = javaEnumOrdinal(*decl->second, l, b.loc);
                    const ValueId ob = javaEnumOrdinal(*decl->second, r, b.loc);
                    Inst cmp;
                    cmp.type = tt.boolType();
                    cmp.operands.push_back(oa);
                    cmp.operands.push_back(ob);
                    cmp.loc = b.loc;
                    if (b.op == "<") { cmp.op = Op::CmpLtS; }
                    else if (b.op == "<=") { cmp.op = Op::CmpLeS; }
                    else if (b.op == ">") { cmp.op = Op::CmpGtS; }
                    else if (b.op == ">=") { cmp.op = Op::CmpGeS; }
                    else {
                        gap("BinaryExpr(operator '" + b.op + "' on a java-style enum)", b.loc);
                        return kNoValue;
                    }
                    return emit(std::move(cmp));
                }
            }
        }

        // A `String` IS A VALUE (spec 4), so `==` compares CONTENT and `+` joins. Both fell through
        // to the pointer path, where `==` asked whether two strings were the SAME OBJECT -- which is
        // false for every pair that was not literally the same allocation, so `p.has("--n")` over an
        // argument list that contained "--n" answered no. Two strings spelled the same are equal;
        // that is what makes them a value and not a handle.
        {
            auto isText = [&](ValueId v) {
                const std::string n = classNameOf(declaredName(v));
                return n == "String" || n == "string";
            };
            if (isText(l) && isText(r)) {
                if (b.op == "+") {
                    return concat(l, r, b.loc);
                }
                if (b.op == "==" || b.op == "!=") {
                    const ValueId same = callExternal("__polaron_str_eq", tt.intType(32),
                                                      {tt.ptrType(), tt.ptrType()}, {l, r}, b.loc);
                    Inst cmp;
                    cmp.op = b.op == "==" ? Op::CmpNe : Op::CmpEq;
                    cmp.type = tt.boolType();
                    cmp.operands.push_back(same);
                    cmp.operands.push_back(constInt(0, 32, b.loc));
                    cmp.loc = b.loc;
                    return emit(std::move(cmp));
                }
            }
        }

        // FLOATING POINT IS ITS OWN SET OF OPCODES, and this pass emitted the integer ones for it:
        // `d + 0.5` came out as `add.wrap` over two doubles, which the backend cannot make and so
        // produced `undef`. There is no overflow rule and no sign here -- a float has neither -- so
        // the choice is only which operation, and the wider operand decides the result type.
        const Type* rt2 = fn_->value(r)->type;
        const bool floating = (lt != nullptr && lt->kind == TypeKind::Float) ||
                              (rt2 != nullptr && rt2->kind == TypeKind::Float);
        if (floating) {
            const Type* ft = lt != nullptr && lt->kind == TypeKind::Float ? lt : rt2;
            if (lt != nullptr && rt2 != nullptr && lt->kind == TypeKind::Float &&
                rt2->kind == TypeKind::Float && rt2->bits > lt->bits) {
                ft = rt2;
            }
            bool known = true;
            if (b.op == "+") { in.op = Op::FAdd; in.type = ft; }
            else if (b.op == "-") { in.op = Op::FSub; in.type = ft; }
            else if (b.op == "*") { in.op = Op::FMul; in.type = ft; }
            else if (b.op == "/") { in.op = Op::FDiv; in.type = ft; }
            else if (b.op == "%") { in.op = Op::FRem; in.type = ft; }
            else if (b.op == "==") { in.op = Op::CmpEq; in.type = tt.boolType(); }
            else if (b.op == "!=") { in.op = Op::CmpNe; in.type = tt.boolType(); }
            else if (b.op == "<") { in.op = Op::CmpLtF; in.type = tt.boolType(); }
            else if (b.op == "<=") { in.op = Op::CmpLeF; in.type = tt.boolType(); }
            else if (b.op == ">") { in.op = Op::CmpGtF; in.type = tt.boolType(); }
            else if (b.op == ">=") { in.op = Op::CmpGeF; in.type = tt.boolType(); }
            else { known = false; }
            if (known) {
                // A MIXED-WIDTH pair is widened here, where the result type was just decided, so
                // the instruction's two operands and its result agree -- rule 3.
                for (ValueId* side : {&l, &r}) {
                    const Type* st = fn_->value(*side)->type;
                    if (st != nullptr && st->kind == TypeKind::Int) {
                        *side = lowerConversion(*side, st, ft, b.loc);
                    } else if (st != nullptr && st->kind == TypeKind::Float && st->bits < ft->bits) {
                        *side = lowerConversion(*side, st, ft, b.loc);
                    }
                }
                in.operands.clear();
                in.operands.push_back(l);
                in.operands.push_back(r);
                return emit(std::move(in));
            }
        }

        // THE SIGN IS ON THE OPERATION (§3.1), and an OVERFLOW CHECK is an operation. `7u - 16u`
        // does not overflow signed -- -9 fits an `int` -- and does underflow unsigned, so
        // `checked()` over unsigned arithmetic wrapped to 4294967289 and trapped on nothing.
        if (b.op == "+") { in.op = ck ? Op::AddChecked : Op::AddWrap; in.type = lt; in.unsignedOp = uns; }
        else if (b.op == "-") { in.op = ck ? Op::SubChecked : Op::SubWrap; in.type = lt; in.unsignedOp = uns; }
        else if (b.op == "*") { in.op = ck ? Op::MulChecked : Op::MulWrap; in.type = lt; in.unsignedOp = uns; }
        else if (b.op == "/") { in.op = Op::DivChecked; in.type = lt; in.unsignedOp = uns; }
        else if (b.op == "%") { in.op = Op::RemChecked; in.type = lt; in.unsignedOp = uns; }
        else if (b.op == "&") { in.op = Op::And; in.type = lt; }
        else if (b.op == "|") { in.op = Op::Or; in.type = lt; }
        else if (b.op == "^") { in.op = Op::Xor; in.type = lt; }
        else if (b.op == "<<") { in.op = Op::ShlWrap; in.type = lt; }
        // A LOGICAL shift for an unsigned value. `>> 24` on a `uint` whose top bit is set is how a
        // checksum extracts its high byte; arithmetically it smears the sign bit down instead.
        else if (b.op == ">>") { in.op = uns ? Op::ShrL : Op::ShrA; in.type = lt; }
        else if (b.op == "==") { in.op = Op::CmpEq; in.type = tt.boolType(); }
        else if (b.op == "!=") { in.op = Op::CmpNe; in.type = tt.boolType(); }
        else if (b.op == "<") { in.op = uns ? Op::CmpLtU : Op::CmpLtS; in.type = tt.boolType(); }
        else if (b.op == "<=") { in.op = uns ? Op::CmpLeU : Op::CmpLeS; in.type = tt.boolType(); }
        else if (b.op == ">") { in.op = uns ? Op::CmpGtU : Op::CmpGtS; in.type = tt.boolType(); }
        else if (b.op == ">=") { in.op = uns ? Op::CmpGeU : Op::CmpGeS; in.type = tt.boolType(); }
        else {
            gap("BinaryExpr(unhandled operator)", b.loc);
            return kNoValue;
        }

        // A SHIFT PAST THE WIDTH IS ZERO, not poison. LLVM leaves `x << 64` undefined and the
        // optimiser is entitled to fold the whole expression away on that basis; the language says
        // the bits shifted out are gone and none come back, so 64 of them leaves nothing. The
        // trusted path has always clamped it, both halves -- the AMOUNT, so the machine
        // instruction is well defined, and the RESULT, so the answer is the language's -- and this
        // emitted the raw shift, which agrees right up until the optimiser notices it may not.
        if ((in.op == Op::ShlWrap || in.op == Op::ShrL || in.op == Op::ShrA) && in.type != nullptr &&
            fn_->value(r)->type != nullptr) {
            const Type* wide = in.type;
            const Type* amountType = fn_->value(r)->type;
            // The constants take the operands' OWN types -- the amount's for the comparison, the
            // result's for the zero -- because an `address` is not an `int<64>` here even though
            // both are sixty-four bits, and rule 3 says an instruction's operands agree.
            auto constOf = [&](const Type* of, int64_t v) {
                Inst c;
                c.op = Op::ConstInt;
                c.type = of;
                c.imm = v;
                c.loc = b.loc;
                return emit(std::move(c));
            };
            Inst fits;
            fits.op = Op::CmpLtU;
            fits.type = tt.boolType();
            fits.operands.push_back(r);
            fits.operands.push_back(constOf(amountType, static_cast<int64_t>(wide->bits)));
            fits.loc = b.loc;
            const ValueId inRange = emit(std::move(fits));
            auto pick = [&](ValueId whenInRange, const Type* of) {
                Inst s;
                s.op = Op::Select;
                s.type = of;
                s.operands.push_back(inRange);
                s.operands.push_back(whenInRange);
                s.operands.push_back(constOf(of, 0));
                s.loc = b.loc;
                return emit(std::move(s));
            };
            in.operands.clear();
            in.operands.push_back(l);
            in.operands.push_back(pick(r, amountType));
            const ValueId clamped = pick(emit(std::move(in)), wide);
            // THE RESULT OF UNSIGNED ARITHMETIC IS UNSIGNED, or the fact stops here: a `>>` feeding
            // a `<` would go back to comparing signed one operator later.
            noteName(clamped, declaredName(l));
            return clamped;
        }
        // A DIVISION CARRIES ITS GUARD, named. Open-coded as a branch it is something the optimiser
        // reasons about without knowing what it is; as `guard.divisor` the eliminator can delete a
        // redundant one and `--no-bounds-check` becomes a pass that removes a node.
        if (in.op == Op::DivChecked || in.op == Op::RemChecked) {
            Inst g;
            g.op = Op::GuardDivisor;
            g.operands.push_back(r);
            // ARITHMETIC WITH NO CORRECT ANSWER IS AN EXCEPTION IN A HOSTED PROGRAM, so a caller
            // can decide what a bad divisor means for it, and a PANIC in freestanding, where there
            // is no exception machinery (spec 36.3). This guard only ever panicked, so a division
            // whose divisor came from input could not be handled at all: the only defence was to
            // test every divisor by hand, and forgetting one killed the process.
            //
            // The class travels with the guard, and so does the enclosing handler: a throw with
            // nowhere named to land leaves the function, and the `try` around the division is
            // usually the one that wanted it.
            g.text = "DivideByZeroException";
            if (auto raised = named_.find(g.text); raised != named_.end()) {
                g.aggregate = raised->second;
            }
            if (!handlers_.empty()) {
                g.edges.push_back(Edge{handlers_.back().landing, {}});
            }
            g.loc = b.loc;
            emit(std::move(g));
        }
        const bool arithmetic = in.type != tt.boolType();
        // `checked(a + b)` TRAPS ON OVERFLOW, and the trap is an exception in a hosted program.
        // The opcode already says the rule -- that is what the suffix is for -- but the overflow
        // BIT the intrinsic produces was being extracted and thrown away, so `checked()`, the one
        // construct the language offers for catching overflow, silently did nothing.
        if (checkedArith_ && (in.op == Op::AddChecked || in.op == Op::SubChecked ||
                              in.op == Op::MulChecked)) {
            in.text = "OverflowException";
            if (auto raised = named_.find(in.text); raised != named_.end()) {
                in.aggregate = raised->second;
            }
            if (!handlers_.empty()) {
                in.edges.push_back(Edge{handlers_.back().landing, {}});
            }
        }
        const ValueId got = emit(std::move(in));
        // THE RESULT OF UNSIGNED ARITHMETIC IS UNSIGNED, or the fact stops at the first operator.
        // `(a + b) % m` reads the sign off the `+`, not off `a`: without this the sum came out
        // unmarked and the remainder beside it went back to being signed. The name recorded is the
        // one that carried the sign in, whichever side it was.
        if (uns && arithmetic) {
            noteName(got, isUnsignedValue(l) ? declaredName(l) : declaredName(r));
        }
        // ...AND THE SUM OF TWO DECIMALS IS A DECIMAL, for exactly the same reason. `+` and `-` do
        // not go through the rescaling path above -- adding two mantissas IS adding the values --
        // but the result still has to know what it is, or the `toString()` on it finds no Decimal
        // and prints the mantissa: `1800000000000000000` where the program says `1.8`.
        if (arithmetic && classNameOf(declaredName(l)) == "Decimal" &&
            classNameOf(declaredName(r)) == "Decimal") {
            noteName(got, "Decimal");
        }
        return got;
    }

    const ast::Program& ast_;
    Lowering out_;
    Function* fn_ = nullptr;
    BlockId here_ = kNoBlock;
    std::unordered_map<std::string, const Type*> named_;
    std::unordered_map<std::string, ValueId> locals_;     // name -> its frame slot (a ptr)
    std::unordered_map<ValueId, const Type*> slotType_;   // slot -> what it holds
    // What each slot and value was DECLARED as, spelled as the programmer wrote it. `pointee_`
    // below answers a different question -- what a pointer's LAYOUT is, for a `gep` -- and cannot
    // answer this one, because a `String` and a `Buffer` are the same `ptr`.
    std::unordered_map<ValueId, DeclaredType> declaredAs_;
    // `<Class>.<field>` for every field declared `external` -- an association the cascade walk
    // must not follow, because the object on the other end belongs to somebody else.
    std::unordered_set<std::string> externalFields_;
    // The `cascade` helpers built so far, and the counter that keeps two call sites' filters from
    // colliding. Memoised by (call site, class) so a self-referential type terminates.
    std::unordered_map<std::string, Function*> cascadeFns_;
    int cascadeSites_ = 0;
    // Types currently being deep-copied, so a class that contains itself stops at the shallow copy
    // instead of recursing until the compiler's own stack runs out.
    std::unordered_set<std::string> copyChain_;
    // Function key -> the RETURN type as written. Module-wide and never cleared per body: it is a
    // property of the declaration, and it is what lets a chained call know what it is holding.
    // WHAT A METHOD RETURNS, AND HOW MANY STARS IT WROTE. The name alone loses the depth --
    // `resolvedTypeName` strips the pointers, and it has to, because every table here is keyed by
    // the CLASS's name -- so a method returning `uint64*` handed back a value that looked like a
    // `uint64`. Indexing it then took the ARRAY path: a bounds guard reading a length header that a
    // raw pointer does not have. pico's `Frames.state()[slot]` panicked with `index = 0, length =
    // 0` on the first frame it touched. This is the same defect `Function::Param` already carries a
    // `pointerDepth` for, on the other side of the call.
    std::unordered_map<std::string, DeclaredType> returnName_;
    // Method name -> its dispatch slot, one numbering for the whole program. See `slotFor`.
    std::unordered_map<std::string, int64_t> vtableSlot_;
    std::unordered_set<std::string> hasVtable_;   // classes whose table was emitted
    std::vector<std::string> synthesized_;        // classes given a default constructor
    std::vector<std::string> synthesizedDtors_;   // ...and the counted ones given a destructor
    std::unordered_map<std::string, const Type*> paramTypes_;
    std::unordered_map<ValueId, const Type*> pointee_;   // value -> the class it points at, if known
    std::unordered_map<ValueId, const Type*> pointeeOfSlot_;  // ...and the same for a slot's contents
    std::unordered_map<std::string, BlockId> labels_;   // the chaos tetrad's named blocks
    std::vector<LoopTargets> loops_;   // see the type, declared with the other shared ones
    // Where a `yield` inside a `match` arm goes, innermost last, and what type the join declares.
    std::vector<YieldTarget> yields_;
    // Which class a `match` case resolved to, so the bindings can be read off its fields. Keyed by
    // the case itself: the name in the source may be `Ok` where the class is `Ok$int`.
    std::unordered_map<const ast::MatchCase*, std::string> caseClassOf_;
    // `<Class>.<field>` -> the field's type as written, AND how many stars were on it. The depth is
    // what says whether assigning to the field SHARES or COPIES -- `nullable Node* next` shares --
    // and recording only the name lost it: `n.next = this.head` deep-copied the list's head every
    // time, which for a null head was a memcpy from address zero.
    //
    // Module-wide: a field's declaration does not change between bodies, and it is read in all of
    // them.
    std::unordered_map<std::string, DeclaredType> fieldTypeName_;
    std::unordered_set<std::string> unions_;   // classes whose fields all sit at offset zero
    // `<class>.<field>` -> where in its shared unit that field's bits are. A bit field is not a
    // TYPE -- `int species : 5` is an `int` everywhere in the program -- it is a PLACEMENT, so what
    // is recorded is where the bits live and not what they are.
    std::unordered_map<std::string, BitField> bitFields_;
    // ...and the same record filed against the ADDRESS a `fieldAddress` handed back, so the `load`
    // and the `store` that follow it know to shift and mask. Per body, like every other id-keyed
    // map here: a value id from the previous function resolves to something and is wrong.
    std::unordered_map<ValueId, BitField> packedAt_;
    // Which addresses are NARROW `A*` slots, and whose arena they are offsets into. Keyed by the
    // address rather than by the field name because that is what the load and the store see.
    std::unordered_map<ValueId, std::string> narrowAt_;
    // Classes something in the program points at with a `weak T*`, closed over the inheritance
    // relation -- they are the ones that carry a weak-list head. See `collectWeakTargets`.
    std::unordered_set<std::string> weakTargets_;
    // A weak field's address, and the class it is declared to point at. Per body, like every other
    // id-keyed map here.
    std::unordered_map<ValueId, std::string> weakSlotAt_;
    // `kilobytes` -> `ByteSize.kilobytes`: every `comptime literal` suffix in the program, by the
    // word that spells it. A suffix belongs to the class that declared it, wherever it is written.
    std::unordered_map<std::string, std::string> literalSuffix_;
    // `Class.name` -> its overloads, as (parameter type, function key). A vector of pairs rather
    // than two vectors indexed alike: the pair IS the overload, and the two halves are never
    // useful apart.
    std::unordered_map<std::string, std::vector<std::pair<std::string, std::string>>>
        literalOverloads_;
    // Every class by its key, the names two classes answer to, and the first declaration of each
    // such name. See `indexClasses`.
    struct ClassEntry {
        const ast::ClassDecl* decl = nullptr;
        std::string bundle;
        std::string ns;
        bool prelude = false;   // declared in the standard library rather than in the program
    };
    std::unordered_map<std::string, ClassEntry> classesByKey_;
    std::unordered_set<std::string> sharedNames_;
    std::unordered_map<std::string, std::string> firstOwner_;
    // Every name declared by an `interrupt` method anywhere in the program. Almost always empty,
    // which is the point: it is what lets a member read decide it is NOT an interrupt binding
    // without evaluating anything. See `indexClasses` and `interruptEntryPoint`.
    std::unordered_set<std::string> interruptNames_;
    // Whose code is being walked, so a shared name resolves to the one in scope where it is
    // written. Set by every loop that walks namespaces.
    std::string currentBundle_;
    std::string currentNamespace_;
    // `<Enum>.<CONSTANT>` -> its ordinal. Kept apart from `named_` because a class of the same name
    // overwrites that entry -- see `declareEnum`.
    std::unordered_map<std::string, int64_t> enumOrdinal_;
    std::unordered_map<std::string, const ast::EnumDecl*> enums_;
    // Catalogs, the enums that implement each, and the id each enum answers to inside a tagged
    // catalog value. See `tagForCatalog`.
    // THE CLASSES SOME `unimport X;` NAMES. Being unimportable is not written on the declaration --
    // it is decided by whether anything in the program asks for the class to be taken away -- so it
    // is collected from the statements rather than read off a flag that does not exist.
    std::unordered_set<std::string> unimportable_;
    // §18.2: a class's persistent fields, in order, the block they live in, and which field of the
    // object points at it. Three maps rather than three fields on one entry only because the class
    // table here is the interned type, and the interned type is keyed by SHAPE -- a name is not
    // shape, and these are all keyed by name.
    std::unordered_map<std::string, std::vector<std::string>> persistOrder_;
    std::unordered_map<std::string, const Type*> persistBlock_;
    std::unordered_map<std::string, int64_t> persistIndex_;
    std::string pendingPersistKey_;
    // §20.2: the task the body being lowered completes, or nothing when the body is an ordinary
    // method. It is what tells a `return` which of the two things it means.
    ValueId asyncTask_ = kNoValue;
    // §20.2's state machine, while an async body is being lowered. `asyncStatePtr_` is the state
    // object this invocation was handed; `asyncStepSlot_` and `asyncAwaitedSlot_` are where it
    // records how far it got and what it is waiting on; `asyncSuspend_` is the block that returns
    // to the scheduler; `asyncSteps_` is the block each `await` resumes at, in order.
    ValueId asyncStatePtr_ = kNoValue;
    ValueId asyncStepSlot_ = kNoValue;
    ValueId asyncAwaitedSlot_ = kNoValue;
    BlockId asyncSuspend_ = kNoBlock;
    std::string asyncResumeKey_;
    std::vector<BlockId> asyncSteps_;
    static constexpr int kAsyncScratch = 64;
    ValueId asyncStateObj_ = kNoValue;   // the state pointer, for a scratch gep
    const Type* asyncStateTy_ = nullptr;
    int64_t asyncScratchBase_ = 0;
    int asyncScratchTop_ = 0;
    // True while the operand of a `return` is being lowered, so a `new` inside it takes heap
    // storage rather than a frame slot the caller would read after the frame is gone.
    bool returningNew_ = false;
    // §7.9: the block each label sits in, and the scopes currently open, so a `goto` can tear down
    // exactly the ones it leaves. A vector rather than a count because the label names a BLOCK.
    struct OpenScope {
        const ast::Block* block = nullptr;
        size_t objects = 0;
        size_t defers = 0;
    };
    std::vector<OpenScope> blockScopes_;
    std::unordered_map<std::string, const ast::Block*> labelBlock_;
    // §7.9: the labels some `comefrom` steals, and the block each one lands in.
    std::unordered_set<std::string> comefromNames_;
    std::unordered_map<std::string, BlockId> comefromBlock_;
    std::unordered_map<std::string, const ast::Block*> comefromOwner_;
    // The plain `static` fields still waiting to fold, with the class that declares each. Held on
    // the pass rather than passed around because the fixed point runs over both kinds at once.
    std::vector<std::pair<const ast::FieldDecl*, std::string>> staticFields_;
    // §37.3: the lazy locals of the body being lowered, by name. Cleared with the rest of the
    // per-body state, since a slot from another function answers wrongly for both.
    std::unordered_map<std::string, LazySite> lazyLocals_;
    // §28.4: `Class.field` -> the initialiser that runs on its first read. Module-wide, not
    // per-body: the field is read from wherever, and the expression belongs to the declaration.
    std::unordered_map<std::string, const ast::Expr*> lazyFieldInit_;
    // Which lazy field's initialiser is being lowered right now, so one that mentions its own field
    // does not re-enter its own guard.
    std::unordered_set<std::string> buildingLazy_;
    // Which SLOT, when the identity is `arr[i]` rather than a name. Empty for every other shape.
    ValueId pendingPersistIndex_ = kNoValue;
    // §18: derived state, excluded from a copy and from serialization.
    std::unordered_map<std::string, std::unordered_set<std::string>> transientFields_;
    // §37.5: `<class key>.<field>` for every field declared `volatile`. Read by `fieldAddress`,
    // which is the one place a field's address is made, so an access through any path -- `this.x`,
    // `obj.x`, a chain -- is marked the same way.
    std::unordered_set<std::string> volatileFields_;
    // ...and the REGIONS declared volatile, by name. An object allocated in one is a device, so it
    // is marked at its `new` and every field address geped off it inherits the fact. Not per-body:
    // a region field is declared on the class and used from every method of it.
    std::unordered_set<std::string> volatileRegions_;
    // Where an `expecting { ... }` block's `return` puts its value, and where control goes next.
    // Both empty outside such a block, which is what tells a `return` it is an ordinary one.
    ValueId expectingSlot_ = kNoValue;
    BlockId expectingEnd_ = kNoBlock;
    std::unordered_set<std::string> catalogs_;
    std::unordered_map<std::string, std::vector<std::string>> catalogImplementers_;
    std::unordered_map<std::string, int64_t> enumTypeId_;
    // The flavour each region local was declared with, and the one being declared right now -- the
    // initialiser is lowered before the name exists, and it is the initialiser that allocates.
    std::unordered_map<std::string, RegionShape> regionShape_;
    std::unordered_map<std::string, MultiRange> multiRegions_;
    std::string lambdaSelfKey_;   // what `itself(...)` calls inside the lambda being lowered
    // §22.6: the generator body being lowered, if any. `genState_` is the state object's type,
    // `genStatePtr_` the pointer to this invocation's, `genSteps_` the block each `yield` resumes
    // at -- the step number IS the index into it, which is why they are one vector and not a map.
    const Type* genState_ = nullptr;
    ValueId genStatePtr_ = kNoValue;
    const Type* genElem_ = nullptr;
    Function* genResume_ = nullptr;
    std::vector<BlockId> genSteps_;
    BlockId genDone_ = kNoBlock;
    ValueId resumeAt_ = kNoValue;   // the step this invocation was resumed at
    int patchSites_ = 0;            // §32.8: one global and one thunk per `methods.replace`
    // §32.8: the methods some `methods.replace` names. They keep a dispatch slot whether or not
    // anything overrides them -- see `needsDispatch`.
    std::unordered_set<std::string> replaceable_;
    // Every class named as a superclass or an interface anywhere in the program: the ones that
    // must carry a vtable pointer because something can be them. See `carriesVtable`.
    std::unordered_set<std::string> bases_;
    // ...and the CLASSES those replaces name. Their dispatch tables are written at run time, so
    // they are emitted mutable -- see `rewritesItsVtable`.
    std::unordered_set<std::string> patched_;
    // Closures that capture nothing, and the lambda each came from -- the two facts a C callback
    // needs, and the creation site is the only place that holds both. PER BODY, like every other
    // id-keyed map here: value ids restart at zero in a new function, so a leftover entry matches
    // an unrelated value and replaces it with a function pointer. It did: `lambda_field` printed
    // `v=-680849136` for 105 the first time this was left standing.
    std::unordered_map<ValueId, const ast::LambdaExpr*> cCallable_;
    // ...and the thunk each lambda got, keyed by the DECLARATION rather than by a counter, so a
    // lambda that crosses to C twice crosses as one function.
    std::unordered_map<const ast::LambdaExpr*, std::string> cCallbacks_;
    RegionShape pendingRegion_;
    // Values that came out of a region. They are the region's to destroy -- at a rollback or at a
    // release -- and never the enclosing block's.
    std::unordered_set<ValueId> regionOwned_;
    // Per region name, the objects in it the compiler can see. Only for a region with no runtime
    // registry: where there is one, the runtime holds the list and knows about the objects this
    // pass never saw -- a tree built across method calls, anything allocated in a loop.
    std::unordered_map<std::string, std::vector<ScopedObject>> regionObjects_;
    // Every compile-time constant in the program, folded once before anything is declared, and the
    // `comptime` methods a constant's initialiser may call. See `foldConstants`.
    std::unordered_map<std::string, long long> constInts_;
    std::unordered_map<std::string, double> constDoubles_;
    std::unordered_map<std::string, const ast::MethodDecl*> comptimeMethods_;
    // The chaos tetrad, read off the body before it is lowered: which labels something abstains
    // from, and which label follows each -- the end of the region an abstention skips.
    std::unordered_set<std::string> abstained_;
    std::unordered_map<std::string, std::string> nextLabel_;
    // WHERE THE STORAGE UNDER A VALUE CAME FROM, for the values this method can answer it for.
    //
    // This was a SET of the heap ones, and `delete` freed exactly its members. That reads as the
    // right question and is not, because a set has two states and the language has three: the
    // allocator's, the frame's, and -- for every pointer that arrived as a parameter, came back
    // from a call, or was loaded out of a field -- not known here. Collapsing the third into "not
    // heap" made `delete t` on a parameter free nothing, and `binarytrees` leaked every node of
    // thirty trees; collapsing it the other way frees a frame address, which `stack_delete` exists
    // to catch. Only the middle state can be released, and only the frame one must not be, so both
    // have to be sayable.
    std::unordered_map<ValueId, Storage> storage_;
    void noteStorage(ValueId v, Storage s) {
        if (v != kNoValue) {
            storage_[v] = s;
        }
    }
    // THE STORAGE UNDER A VALUE, or `Unknown` when this method never saw it allocated.
    Storage storageOf(ValueId v) const {
        const auto it = storage_.find(v);
        return it == storage_.end() ? Storage::Unknown : it->second;
    }
    bool onFrame(ValueId v) const { return storageOf(v) == Storage::Frame; }
    bool fromAllocator(ValueId v) const { return storageOf(v) == Storage::Heap; }
    // §37.5: THE VALUES THAT POINT AT VOLATILE STORAGE -- a `volatile` local's slot, a `volatile`
    // field's address, the result of `cast<volatile T*>`, and everything derived from one by
    // stepping. `emit` reads it to mark the load or store; nothing else needs to know.
    //
    // POINTS AT, not IS: `volatile int* px` says the PIXELS are volatile, not the variable holding
    // their address. Reading `px` is an ordinary load of an ordinary local; `px[i]` is the volatile
    // one, and it is a `gep` off the loaded value -- which is why the propagation follows the
    // pointer rather than the slot it came out of.
    std::unordered_set<ValueId> volatilePointee_;
    // ...and the SLOTS holding such a pointer. `volatile int* px` makes the pixels volatile, not
    // the variable, so the fact belongs to whatever `px` yields -- which means it has to be handed
    // over at the load, not at the declaration. Kept apart from the set above because marking the
    // slot itself would make reading the variable a volatile access and the access through it an
    // ordinary one, which is the rule exactly backwards.
    std::unordered_set<ValueId> volatilePointerSlots_;
    // WHERE THE PROGRAM IS, statement by statement -- what a runtime guard names when it fires.
    // See `lowerStmt`, and `whereLine` in the backend for what it is printed as.
    SourceLocation stmtLoc_;
    // §21: A `String` OWNS ITS BUFFER. Two lifetimes, two lists:
    //
    //   a TEMPORARY -- what `a + b` or `s.substring(...)` builds -- belongs to the STATEMENT that
    //                  built it. Nothing names it, so nothing else could ever free it.
    //   a SLOT      -- a `String` local -- belongs to the SCOPE, and rides in `scoped_` with the
    //                  objects so one list gives one order at one exit. `stringSlots_` is only the
    //                  membership test an assignment needs before releasing what it overwrites.
    //
    // Safe because of COPY-ON-STORE, which is the language's rule and not escape analysis: every
    // point where a String crosses into something outliving the expression makes its own copy, so
    // no two names ever share a buffer and freeing each owner exactly once is right.
    std::vector<std::pair<ValueId, BlockId>> stringTemps_;
    std::unordered_set<ValueId> stringSlots_;
    // The `requires` clauses of the body about to be lowered, as expressions. See `lowerBody`.
    std::vector<const ast::Expr*> pendingRequires_;
    // EVERY INVARIANT OF THE OWNING CLASS, to hand to the optimiser at entry as a fact it may rely
    // on. ALL of them, deliberately -- not the narrowed set `stagedExit_` keeps, which is empty for
    // exactly the read-only methods that have the most to gain from knowing them.
    std::vector<const ast::Expr*> pendingInvariants_;
    // An exit check and WHAT IT IS CALLED, because the message the program prints names the clause
    // kind: `contract 'invariant' failed` and `contract 'ensures' failed` are different diagnostics
    // and the trusted path prints both. Two parallel vectors would be this pair with the name of
    // the type left off.
    struct ExitCheck {
        const ast::Expr* clause;
        const char* kind;
    };
    // Reads back one line of one compiled file, or is empty. See `lower()` in the header: nothing
    // here needs it, and what it buys is the text of a failing contract clause.
    std::function<std::string(std::string_view, int)> sourceLine_;
    // The target triple, as the driver resolved it. See `lower()` in the header.
    std::string triple_;
    BundleContext bundles_;   // the `.polb` dependencies, as the driver read them
    // Which functions each RUN-TIME bundle declared, kept from the walk that declared them: after
    // it, the module is one flat list and there is nothing left to say which bundle a key came from.
    std::map<std::string, std::vector<Function*>> dynamicFns_;
    std::vector<ExitCheck> stagedExit_;    // handed from `lowerBody` across to `lowerBodyOf`
    std::vector<ExitCheck> pendingExit_;   // the checks in force for the body being lowered
    bool inExitChecks_ = false;
    // What `result` means, and only while an `ensures` is being emitted. See the `return` lowering.
    ValueId resultValue_ = kNoValue;
    // Where each `old(...)` in those checks was put at entry. Keyed by the NODE, not by position:
    // the same clause can hold several and the exit check asks for one of them by identity.
    std::unordered_map<const ast::OldExpr*, ValueId> oldSlots_;
    // The captures of the lambda whose body is about to be lowered, in declaration order.
    std::vector<Captured> pendingCaptures_;
    // The label a `LabeledStmt` just read, waiting for the loop inside it to claim it.
    std::string pendingLoopLabel_;
    // The `defer` blocks of the body being lowered, in the order they were written.
    std::vector<DeferSite> deferred_;
    // Everything a `try` body creates, at EVERY depth inside it, so the way out through the
    // landing block tears down the same things the closing braces would have. A nested scope that
    // completed normally has already run its own: the destructor sees a nulled slot and the
    // `defer` sees its flag set, so the second pass over them does nothing.
    std::vector<ScopedObject> unwindObjects_;
    std::vector<DeferSite> unwindDefers_;
    // Stack objects declared in the scopes currently open, oldest first. Destroyed in reverse when
    // their scope ends -- see `destroyScoped`.
    std::vector<ScopedObject> scoped_;
    // The enclosing `try`'s landing block, innermost last. A call lowered while this is non-empty
    // becomes a `call.unwind` with that block as its second successor.
    std::vector<Handler> handlers_;
    std::unordered_map<std::string, ValueId> statics_;   // one address per static, per body
    ValueId selfSlot_ = kNoValue;
    const Type* selfClass_ = nullptr;
    std::string selfClassName_;   // the class whose body is being lowered, by name
    BlockId entryBlock_ = kNoBlock;   // where every `alloca` goes -- it dominates everything
    size_t allocaAt_ = 0;             // ...and where the next one is inserted, keeping them grouped
    int counter_ = 0;
    int lambdaCount_ = 0;   // lambdas become top-level functions and need distinct keys
    // Inside `checked(...)`, and only there. Integer arithmetic wraps by default -- spec 3.6.
    bool checkedArith_ = false;
};

// The four suffixes, in the order the hooks happen. Kept as one array so the declaration walk and
// the lowering walk cannot pair a hook with its neighbour's function.
const char* Lower::kHookSuffix[4] = {".__onClassLoad", ".__onFirstInstance",
                                     ".__onLastInstanceDestroyed", ".__onClassUnload"};

}  // namespace

Lowering lower(const ast::Program& program,
               std::function<std::string(std::string_view, int)> sourceLine, std::string triple,
               BundleContext bundles) {
    return Lower(program, std::move(sourceLine), std::move(triple), std::move(bundles)).run();
}

std::string renderGaps(const std::vector<Gap>& gaps) {
    // Counted rather than listed one per site: the same construct in four hundred places is one
    // thing to implement, and a list of four hundred lines hides that.
    std::unordered_map<std::string, int> counts;
    // ...AND WHERE THE FIRST ONE IS. A count says how much work a construct is; it does not say
    // which line to open, and a gap becomes an `unreachable` -- so in a real program the same list
    // is also the list of places the machine will execute `ud2`. Finding that by reading 66 000
    // lines for a construct name is not a work queue.
    std::unordered_map<std::string, const Gap*> first;
    for (const Gap& g : gaps) {
        ++counts[g.construct];
        first.emplace(g.construct, &g);
    }
    std::string out;
    for (const auto& [what, n] : counts) {
        out += "pir::lower: " + what + " x" + std::to_string(n);
        if (const Gap* g = first[what]; g != nullptr && !g->loc.file.empty()) {
            out += "  first at " + std::string(g->loc.file) + ":" + std::to_string(g->loc.line) +
                   ":" + std::to_string(g->loc.col) + (g->where.empty() ? "" : "  in " + g->where);
        }
        out += "\n";
    }
    return out;
}

}  // namespace polaron::pir
